      local rw=action.reach_walk
      if rw then
        last.reach_walk=string.format('no path led within reach of it (%s); walked toward %s, a spot within reach%s',rw.why or 'no path',at(rw.to),
          rw.tried and #rw.tried>0 and string.format(' (after %d other spot%s within reach no path led to: %s)',#rw.tried,#rw.tried==1 and '' or 's',
