    if (outcome=='unreachable' or outcome=='no_safe_route') and here then
      local oks,st=pcall(M.staging,here,action.via and action.via.final or action.position,action.surface_name)
      if oks and st then last.staging=st.lines; last.staging_via=st.via; last.staging_spot=st.staging end
    end
