    -- (d17 batch35 A4) unbox: walked straight over the belts to the open spot first
    if action.unboxed then last.unboxed=string.format('boxed in by belts at %s: walked straight over them to the open spot %s, then the path from there',at(action.unboxed.from),at(action.unboxed.to)) end
    if action.escapes and action.escape_first then
