    else s.last[index].taken_back='not taken back: the machine is gone or out of reach' end
  end
  if action and action.kind=='gather' then
    local last=s.last[index]
    last.short_allowed=action.feed and action.feed.up_to==true and outcome=='out_of_items' or nil
    last.item=action.item; last.got=action.got; last.want=action.want<10000 and action.want or nil; last.visited=action.visited
    -- The first place that failed and why (a tour where every place failed ends failed: Astra 08:47).
    last.first_error=action.first_error; last.error=last.error or (outcome=='failed' and action.first_error) or nil
    -- The first place not reached and why (stock.lua: a walk that ended unreachable, no_safe_route, blocked ...).
    last.route_failures=action.route_failures
    last.first_unreached=action.first_unreached; last.why=last.why or (outcome=='unreached' and action.first_unreached) or nil
    -- held short of a live attack at its stop when it ended (d17 batch17 B1)
    last.held_short=action.held_short
    -- (d17 batch18 C3, Opus) after a feed, rearm or refuel walk: enemy groups seen moving toward the places served
    if action.op=='feed' or action.op=='rearm' or action.op=='refuel' or action.fuel_round then
      local served={}
      for i,t in ipairs(action.targets or {}) do
        if i>=action.index then break end
        local e=t.entity
        if e and e.valid then served[#served+1]={name=e.name,position=e.position} end
      end
      local okg,lines=pcall(function()
        local pl=M.lookup(index)
        local ch=pl and pl.character
        return M.avoid.groups_toward(ch and ch.valid and ch.surface or (pl and pl.surface),served)
      end)
      last.enemy_groups_toward=okg and lines or nil
    end
    last.mine_for_a_way=action.mine_for_a_way  -- an unreachable stop: the fewest to mine for a way (B2)
    -- The route walked (C5, Luna 18:20): from where, each via point and stop as reached, the tiles moved.
    last.route=stock.route_text(action)
    last.off_rails=action.off_rails
    -- Places left out for the enemy check (round1950a): how many, and the first 8; at the call too (round2120a).
    last.danger=action.danger; last.dangers=action.dangers; last.skipped_attack=action.skipped_attack; last.enemies_ahead=action.enemies_ahead; last.ahead_waited=action.ahead_waited
    -- (d18 batch37 C1) a chain: what of its items is held, the steps left, and on_fail "return"'s walk back
    if action.chain then
      local okc,call=pcall(M.transferchain.report,M.lookup(index),action,last,outcome)
      if okc and call then s.then_calls=s.then_calls or {}; s.then_calls[#s.then_calls+1]={index=index,call=call,started_by='on_fail "return" of a transfer chain that ended '..outcome} end
    end
    last.left_out=action.left_out; last.left_out_count=action.left_out_count
    last.turrets_skipped=action.turrets_skipped  -- (batch32 A2) turrets a rearm walk skipped: other ammo with no room, ghosts
    if action.fuel_round then local r=action.fuel_round;last.fuel_taken=r.taken+(r.source and r.source.got or 0);last.sources=r.sources;last.source_read_capped=r.source_read_capped;last.why=action.why or last.why end
    -- An end that moved nothing says why on its error line (round1650d: Luna's courier ended "nothing_collected" with the
    -- reason only in status; Sol's walking give ended "nothing_to_do" at a full chest): the first place's error, else
    -- the places that were full or held none.
    if (outcome=='nothing_collected' or outcome=='nothing_to_do') and not last.why then
      if action.first_error then last.why=action.first_error
      else
        local parts={}
        for _,r in ipairs(action.rows or {}) do
          if (r.moved or 0)==0 and #parts<3 and r.position then
            local dir=r.direction or (action.transfer and action.transfer.direction)
            parts[#parts+1]=string.format('%s (%g,%g) %s',r.name or 'a place',r.position.x,r.position.y,
              r.full and (dir=='to_player' and 'gave nothing: your inventory is full' or (r.why or 'is full')) or (dir=='to_player' and 'held none' or 'took none'))
          end
        end
        if #parts>0 then last.why=table.concat(parts,'; ') end
      end
    end
    -- The moved batch's spoilage over the tour (Sol, 22:25).
    if action.fresh then
      local okp,pl=pcall(function() return body(M.lookup(index)) end)
      local okl,lines=pcall(M.fresh_lines,okp and pl and pl.force or nil,action.fresh)
      if okl and #lines>0 then last.freshness=lines end
    end
    -- A courier that delivered less than it took (Sol, 22:08: taken 40, delivered 0, and the call said ok): a short
    -- line with why; what it did not deliver stays with you (inv says how much you hold).
    if action.legs and (action.taken or 0)>0 then
      local delivered=math.max(0,(action.got or 0)-action.taken)
      if delivered<action.taken then
        local give
        for _,r in ipairs(action.rows or {}) do if r.direction=='to_entity' then give=r end end
        local where=give and give.position and string.format('%s (%g,%g)',give.name or 'the destination',give.position.x,give.position.y)
        local why
        if give and give.full then why=where..' is full'..(give.why and ': '..give.why or '')
        elseif give then why=where..' took '..(give.moved or 0)
        else why=last.why or 'the destination was not reached' end
        last.short={asked=action.taken,moved=delivered,reason=give and give.full and 'target_full' or (give and 'target_short' or 'not_delivered'),
          why=why,kept=string.format('%d %s not delivered, carried by you',action.taken-delivered,action.item or 'items')}
      end
    end
    -- A feed tour's machines that took nothing with spoilage in their input: a short line naming them.
    if action.feed and not last.short then
      local parts,k={},0
      for _,r in ipairs(action.rows or {}) do
        if r.spoilage then
          k=k+1
          if #parts<3 then parts[#parts+1]=string.format('%s (%g,%g) %s',r.name or 'a machine',r.position.x,r.position.y,r.spoilage) end
        end
      end
      if k>0 then
        last.short={reason='input_spoilage',machines=k,why=table.concat(parts,'; ')..(k>3 and string.format('; +%d more',k-3) or '')}
      end
    end
    -- Waiting at a machine: what it took against what the machine made and its inserters took (stock.lua).
    if action.wait then
      local r=stock.wait_report(action)
      if r then for k,v in pairs(r) do last[k]=v end end
      last.why=action.why or (r and r.why)
      last.want=action.want<1000000 and action.want or nil
    end
    if action.all then last.items=next(action.items) and action.items or nil end
    -- collect over a radius: the same total line as a transfer over several targets.
    if not action.op and #action.targets>1 then
      local moved={}
      if action.all then
        for key,n in pairs(action.items) do moved[#moved+1]={name=key,count=n} end
        table.sort(moved,function(x,y) return x.count>y.count end)
      else moved[1]={name=action.item,count=action.got,quality=action.quality} end
      local left=math.max(0,#action.targets-action.index+1)
      last.tally=M.tally{moved=moved,targets=#action.targets,touched=action.touched,unreached=action.unreached,errors=action.errors,
        noun='places'}..(left>0 and string.format('; %d places not visited (%s)',left,outcome) or '')
    end
    if action.op then
      -- A tour that found nothing to do: why, and the nearest one outside its radius (M.tour_note).
      if action.nothing then
        last.nothing=action.nothing; last.nearest_outside=action.nearest_outside; last.types_note=action.types_note
        local parts={action.nothing}
        if action.nearest_outside then parts[#parts+1]=action.nearest_outside end
        if action.types_note then parts[#parts+1]=action.types_note end
        last.why=last.why or table.concat(parts,'; ')
      end
      last.op=action.op; last.got=nil; last.given=action.got; last.errors=action.errors; last.items=action.items; last.entities=action.rows
      last.left=math.max(0,#action.targets-action.index+1)>0 and #action.targets-action.index+1 or nil
    end
    if action.op=='transfer' then
      last.given=nil; last.transferred=action.got; last.direction=action.transfer.direction
      last.items=next(action.items) and action.items or nil; last.unreached=action.unreached
      if action.entries then last.entries=action.entries; last.short=action.short end
    end
    if action.op=='load_silo' then M.rocketload.walk_last(action,last) end
  end
  -- repair over positions or an area: repaired against already full, and what was not reached.
  if action and action.kind=='repair' and action.targets then
    local last,left=s.last[index],#action.targets-action.index+1
    last.repaired=action.repaired; last.already_full=action.already_full
    last.lost=action.lost>0 and action.lost or nil; last.unreached=action.unreached>0 and action.unreached or nil
    last.left=left>0 and left or nil
    last.tally=string.format('repaired %d, %d already full%s%s%s',action.repaired,action.already_full,
      action.unreached>0 and string.format(', %d not reached',action.unreached) or '',action.lost>0 and string.format(', %d gone',action.lost) or '',
      left>0 and string.format(', %d left (%s)',left,outcome) or '')
  end
  -- Waits for trains on the legs of other walks (M.train_guard: tours, construct, pickup); move_to's are above.
  if action and action.kind~='move_to' then
    if type(action.nav)=='table' then M.train_done(action.nav) end
    s.last[index].train_waits=action.train_waits
  end
  -- A walk that ends on rails says so (M.on_rails).
  if action and M.WALK_KINDS[action.kind] then
    local ok,line=pcall(M.on_rails,body(M.lookup(index)))
    s.last[index].on_rails=ok and line or nil
  end
  -- Item moves that ran over time: moved and the inventory line after (Muse 06:27).
  if action and (action.kind=='pickup' or action.kind=='gather' or action.kind=='feed' or action.kind=='mine') then pcall(M.moved_last,index,action,s.last[index]) end
  -- A walk that ends on a belt: the game carries the character on (shift03).
  if action and action.kind~='drive' then s.last[index].on_belt=M.belt.note(body(M.lookup(index))) end
  stop(body(M.lookup(index)))
  if action and action.started_by and s.last[index] then s.last[index].started_by=action.started_by end
  -- The route memory (batch28 C2): a move_to through via points that arrived keeps them; one with none that ended
  -- unreachable or no_safe_route runs once more through a kept route between the same two areas.
  if action and action.kind=='move_to' and s.last[index] then pcall(M.route_memory,index,action,outcome,s.last[index]) end
  -- (batch28 C3) a rearm tour: a line per turret, those not reached named
  if action and action.op=='rearm' and s.last[index] then
    local lines={}
    for i,l in ipairs(action.turret_lines or {}) do lines[i]=l end
    for _,t in ipairs(action.targets or {}) do
      local e=t.entity
      local seen=false
      if e and e.valid then
        local key=string.format('%s (%g,%g):',e.name,e.position.x,e.position.y)
        for _,l in ipairs(lines) do if l:sub(1,#key)==key then seen=true; break end end
        if not seen then lines[#lines+1]=string.format('%s (%g,%g): not reached (the tour ended %s)',e.name,e.position.x,e.position.y,tostring(outcome)) end
      end
    end
    if #lines>0 then s.last[index].turret_lines=lines end
  end
  -- A call to run once the wait is met (A2: rearm {retry_when_clear}): next tick, outside this finish.
  if action and action.then_call and s.last[index] then
    -- (d17 batch34 C2) or a tour that ended one of then_after's outcomes (rearm {from}: the take, then the tour)
    if outcome=='met' or (action.then_after and action.then_after[outcome]) then
      s.then_calls=s.then_calls or {}
      s.then_calls[#s.then_calls+1]={index=index,call=action.then_call}
      s.last[index].then_call=action.then_call.action..' runs again now'
    else s.last[index].then_call=string.format('%s not run again: the %s ended %s',action.then_call.action,action.then_after and 'action' or 'wait',outcome) end
  end
  -- launch {wait_ready}: the wait met, the launch now (last.launch; launch_failed when it is refused).
  if action and action.then_launch and outcome=='met' and s.last[index] then
    local ok,r=pcall(M.launch_now,M.lookup(index),action.then_launch)
    -- a met wait and a launch that went is the step's success (E13, Astra 20:02: the queue recorded failed: met and paused)
    if ok then
      s.last[index].launch=r
      s.last[index].outcome=type(r)=='table' and r.launched==false and 'not_launched' or 'launched'
    else
      -- the game launched it first (d17 batch17 A2, Grok 2x: a rocket holding what the platform above asks for is
      -- launched by the game when it stops, one item type a rocket): said as what it sent and what stayed, not as a failure
      local okg,g=pcall(M.game_launched,index,action)
      if okg and g then s.last[index].outcome='launched_by_game'; s.last[index].launch=g
      else s.last[index].outcome='launch_failed'; s.last[index].launch_error=(tostring(r):gsub('^[^:]*:%d+: ','')) end
    end
  elseif action and action.then_launch and s.last[index] then
    -- Ended before the rocket was ready (Astra, board #635, twice: a tell ended the wait and --wait read it as done):
    -- nothing launched, said as the outcome.
    s.last[index].outcome='not_launched'
    -- (what it waited for: the rocket, the platform in orbit, or both: B2)
    local c=action.condition or {}
    local parts={}
    for _,m in ipairs((c['until']=='all' or c['until']=='any') and c.conditions or {c}) do
      if m['until']=='platform_arrived' then parts[#parts+1]=string.format('%s was in orbit of %s',tostring(m.platform),tostring(m.location))
      else parts[#parts+1]='it was ready' end
    end
    s.last[index].launch_error=string.format('the wait for the rocket ended %s%s before %s: nothing launched',outcome,action.told and ' ('..action.told..')' or '',table.concat(parts,c['until']=='any' and ' or ' or ' and '))
  end
  -- a courier with personal_logistics: "pause": the requests back on (D3)
  if action and action.personal_paused then
    local p=M.lookup(index)
    local c=p and p.valid and p.character
    local rp=c and c.valid and c.get_requester_point()
    if rp then rp.enabled=true end
    if s.last[index] then s.last[index].personal_logistics='your personal logistic requests are back on' end
  end
  -- load_silo {auto_requests: "pause"} that ended without its launch (short, failed, timed out, stopped): the silo's
  -- automatic requests stay off, as the agent set them (d17 batch17 A1, Astra and Sol: turned back on after a short
  -- rescue load, they put one gun turret in and the next scarce Aquilo rocket went up with it). The pause record goes;
  -- configure {auto_requests: true} turns them on.
  if action and (action.handler=='load_silo' or action.op=='load_silo') and M.silo_keep_off then
    local o=s.last[index] and s.last[index].outcome or outcome
    if o~='fed' and o~='launched' and o~='loaded' then
      local ok,line=pcall(M.silo_keep_off,index,'the load ended '..tostring(o))
      if ok and line and s.last[index] then s.last[index].auto_requests_kept_off=line end
    end
  end
  if action and action.borrowed_cursor then
    local p=M.lookup(index)
    if M.bots.is(p) and p.valid and p.character then M.bots.clear_cursor(p)
    elseif p and p.valid and p.connected and p.character and p.character.valid and p.cursor_stack then pcall(p.clear_cursor) end
  end
  s.active[index]=nil
end
local function stop_combat(index,outcome)
  combat_targets()[index]=nil
  local p=body(M.lookup(index))
  local combat=state().combat and state().combat[index]
  local used
  local guns
  if p and p.valid and p.character and p.character.valid then
    p.shooting_state={state=defines.shooting.not_shooting,position=p.position}
    -- Whole magazines (or shells) gone from the ammo slots since the start; a vehicle's from its gun's slot.
    if combat and combat.vehicle then used,guns=M.vehicles.combat_end(p,combat)
    elseif combat and combat.ammo_start then used=math.max(0,combat.ammo_start-kite.ammo_count(p)) end
  end
  if state().combat then state().combat[index]=nil end
  -- A drive's guns stopping first (out of ammo): their count stays with the drive for its last.
  local active=state().active[index]
  if combat and combat.with_drive and active and active.kind=='drive' and outcome~='drive_ended' then
    local v=combat.vehicle_entity
    combat.rounds_left=v and v.valid and M.vehicles.rounds(v,combat.slot) or 0
    combat.outcome=outcome
    active.combat_done=combat
  end
  state().last_combat=state().last_combat or {}
  if combat and combat.retreated and outcome=='move_ended' then outcome='retreated' end
  -- Nothing fired on foot: why, as the start read it, or no enemy in reach (Sol, d15 07:50).
  local why_none
  if combat and not combat.vehicle and used==0 then
    local w=combat.why_start
    why_none=w and (w.no_compatible_ammo and 'no_compatible_ammo: '..w.no_compatible_ammo or w.out_of_range and 'out_of_range: '..w.out_of_range)
      or (combat.auto and string.format('nothing fired: no enemy the gun could reach within radius %d',combat.radius or 24)) or 'nothing fired'
  end
  state().last_combat[index]={outcome=outcome,tick=game.tick,ammo_used=used,reloads=combat and combat.reloads,equipped=combat and combat.equipped,
    gun_used=combat and combat.gun_used,why_none=why_none,held_blast=combat and combat.held_blast,held_blast_ticks=combat and combat.held_blast_n,
    switched_gun=combat and combat.switched_gun,dry=combat and combat.dry,held_melee=combat and combat.held_melee,held_melee_ticks=combat and combat.held_melee_n,
    vehicle=combat and combat.vehicle,gun=combat and combat.gun,guns=guns,kills=combat and combat.kills,retreated=combat and combat.retreated,
    why=combat and combat.retreated and (combat.retreated.why..(combat.retreated.going and '; '..combat.retreated.going or '')) or nil}
end
-- (d22 batch112 BV1) The entries a running build had left: its walk's call for the rest (autowalk.lua) or a step aside's
-- rerun; nil for anything else.
function M.left_undone(index)
  local action=state().active[index]
  if not action then return nil end
  local args=action.then_call and action.then_call.action=='build' and action.then_call.args or action.handler=='build' and action.args or nil
  local list=type(args)=='table' and type(args.builds)=='table' and args.builds or nil
  if not list or #list==0 then return nil end
  local pos={}
  for i=1,math.min(8,#list) do
    local b=list[i]
    local q=type(b)=='table' and type(b.position)=='table' and b.position
    pos[#pos+1]=q and string.format('%s (%g,%g)',tostring(b.item or args.item),q.x or q[1] or 0,q.y or q[2] or 0) or '?'
  end
  return {count=#list,positions=pos,line=table.concat(pos,', ')..(#list>8 and string.format(' and %d more',#list-8) or '')}
end
-- The tick a read or passive action raised: the bootstrap's failure handler
-- calls stop_player right after, which must leave the action and queue alone.
local passive_failed=false
-- why (d24 batch148 PT1, Astra #2159: her body lane read "a call of yours failed while your queue ran" each time the
-- stream service's board_focus read, sent under her bot name, took over her character): what paused it, named with
-- the action and request id; with neither outcome nor why, the failed call M.dispatch recorded (M.last_failed).
function M.stop_player(index,outcome,why)
  if passive_failed==game.tick and not outcome and not why then passive_failed=false; return end
  -- (d17 batch35 A5) the failed call M.dispatch named: its action in the pause record, for the team block's line
  local fc=M.failed_call
  local mine=not outcome and not why and fc and fc.index==index and fc.tick==game.tick
  M.failed_call=nil
  local lf=M.last_failed
  local failed=not outcome and not why and lf and lf.index==index and lf.tick==game.tick and lf or nil
  M.last_failed=nil
  local text=outcome and ('your action ended '..tostring(outcome)) or why
    or failed and string.format('your %s call (request %s) failed while your queue ran',tostring(failed.action),tostring(failed.id))
    or 'a call made as you failed while your queue ran (no request recorded)'
  if scheduler then scheduler.pause(index,text,mine and fc.action or nil,mine and fc.job or nil,failed and failed.id or nil) end
  finish(index,outcome or 'interrupted')
  stop_combat(index,outcome or 'interrupted')
end
-- (d24 batch153) the queues' pause names the harness update; the incoming runtime carries on what was running
M.UPDATE_PAUSE='paused by a harness update at tick %d (a runtime deploy or restart stops every action and pauses every queue; the incoming runtime carries on the steps that were running)'
function M.stop_all()
  if scheduler then scheduler.pause_all(string.format(M.UPDATE_PAUSE,game.tick)) end
  for index in pairs(state().active) do finish(index,'interrupted') end
  for index in pairs(state().combat or {}) do stop_combat(index,'interrupted') end
end
-- Watchdog for actions that walk: no progress counter change (built, mined,
-- placed, next tile, kills) and under 2 tiles of displacement for STUCK_TICKS
-- means the character is physically stuck, whatever the controller believes.
local WATCH_TICKS,STUCK_TICKS=60,600
local watched={move_to=true,construct=true,build_path=true,gather=true}
local function watch(p,action)
  if not watched[action.kind] or game.tick%WATCH_TICKS~=0 then return end
  local key=table.concat({action.built or 0,action.mined or 0,action.placed or 0,action.next_index or 0,action.kills or 0,action.got or 0,action.index or 0},':')
  local w,pos=action.watch,p.position
  -- A collect waiting at its machine stands still on purpose (stock.lua wait_tick).
  if not w or w.key~=key or action.mining or action.awaiting_craft or action.waiting or distance(pos,w.anchor)>=2 then
    action.watch={key=key,anchor={x=pos.x,y=pos.y},since=game.tick}
  end
end
-- Hits on our characters and the vehicles they ride (on_entity_damaged from another force), and the kills a character
-- or vehicle made lately, by unit number (viewer Joonazan, 13:36: the stream called a shoot auto guard with nothing in
-- range "under attack"). Kept for HURT_KEEP ticks; a hit within HURT_EPISODE of the last adds to its damage.
-- (one table: the main chunk is at Lua's 200 locals)
M.HURT={keep=18000,episode=600,kills_window=600,types={character=true,car=true,['spider-vehicle']=true}}
function M.note_hurt(event)
  local e=event.entity
  if not (e and e.valid and M.HURT.types[e.type]) then return end
  local by=event.force
  if not by or by==e.force or (e.force.get_friend and e.force.get_friend(by)) then return end
  local unit=e.unit_number
  if not unit then return end
  local s=state()
  s.hurt=s.hurt or {}
  local h=s.hurt[unit]
  if not h then
    for k,v in pairs(s.hurt) do if event.tick-v.tick>M.HURT.keep then s.hurt[k]=nil end end
    h={first=event.tick,damage=0}; s.hurt[unit]=h
  elseif event.tick-h.tick>M.HURT.episode then h.first,h.damage=event.tick,0 end
  local cause=event.cause
  h.tick=event.tick
  h.damage=h.damage+(event.final_damage_amount or 0)
  h.by=cause and cause.valid and cause.name or event.damage_type and event.damage_type.name or by.name
  h.at=cause and cause.valid and {x=math.floor(cause.position.x+0.5),y=math.floor(cause.position.y+0.5)} or nil
  h.what=e.type~='character' and e.name or nil
end
function M.note_kill(cause,tick)
  if not (cause and cause.valid and M.HURT.types[cause.type] and cause.unit_number) then return end
  local s=state()
  s.char_kills=s.char_kills or {}
  local list=s.char_kills[cause.unit_number] or {}
  s.char_kills[cause.unit_number]=list
  list[#list+1]=tick
  while #list>0 and (#list>20 or tick-list[1]>M.HURT.kills_window) do table.remove(list,1) end
end
-- A character's death (d17 batch12 A4, Opus: 7 deaths in two shifts, each recovered blind): where, when, what killed it
-- (the killing entity, kept to say later whether it is still alive), the damage type, and the hits of that episode.
-- The last 32 deaths are kept.
function M.note_char_death(event)
  local e=event.entity
  local s=state()
  s.char_deaths=s.char_deaths or {}
  local cause=event.cause
  local okc=cause and cause.valid
  local h=s.hurt and e.unit_number and s.hurt[e.unit_number]
  table.insert(s.char_deaths,1,{surface=e.surface.name,position={x=e.position.x,y=e.position.y},tick=event.tick,who=M.character_owner(e),
    by=okc and cause.name or (h and h.by) or (event.force and event.force.name) or nil,
    at=okc and {x=math.floor(cause.position.x*10+0.5)/10,y=math.floor(cause.position.y*10+0.5)/10} or (h and h.at) or nil,
    cause=okc and cause or nil,cause_type=okc and cause.type or nil,
    damage_type=event.damage_type and event.damage_type.name or nil,
    episode=h and h.first and {damage=math.floor(h.damage+0.5),s=math.floor((event.tick-h.first)/60)} or nil})
  while #s.char_deaths>32 do table.remove(s.char_deaths) end
end
-- A team line per death of our characters that left a corpse holding items (batch24 C2, Haiku: a 1,194-item corpse at
-- (-314,-296) sat near a wave for minutes): who, where, the items, what killed it, the enemy groups our force sees
-- near it. Each agent sees a death once (its first look: the last 5 minutes); a corpse emptied is not said.
function M.death_lines(p,h)
  local since=h.death_tick or game.tick-18000
  h.death_tick=game.tick
  local out={}
  local list=state().char_deaths or {}
  for i=#list,1,-1 do
    local d=list[i]
    if d.tick>since and d.tick<game.tick then
      local s=game.get_surface(d.surface)
      local corpse
      for _,k in ipairs(s and s.find_entities_filtered{type='character-corpse',position=d.position,radius=3,limit=8} or {}) do
        local okt,t=pcall(function() return k.character_corpse_tick_of_death end)
        if okt and t and math.abs(t-d.tick)<=1 then corpse=k end
      end
      local okn,n=pcall(function() return corpse.get_inventory(defines.inventory.character_corpse).get_item_count() end)
      if corpse and okn and n>0 then
        local okg,groups=pcall(threat.groups_near,p.force,s,d.position,160)
        out[#out+1]=string.format('%s died at (%d,%d) on %s %ds ago: the corpse holds %d item%s%s; %s',tostring(d.who or 'a character'),
          math.floor(d.position.x+0.5),math.floor(d.position.y+0.5),d.surface,math.floor((game.tick-d.tick)/60),n,n==1 and '' or 's',
          d.by and '; killed by '..d.by or '',okg and threat.groups_line(groups) or 'enemy groups not read')
      end
    end
  end
  return #out>0 and out or nil
end
-- The death that left a corpse (its surface, position and tick of death), nil when not recorded.
function M.death_of(surface,pos,tick)
  for _,d in ipairs(state().char_deaths or {}) do
    if d.surface==surface and tick and math.abs(d.tick-tick)<=1 and distance(d.position,pos)<=3 then return d end
  end
end
-- What killed the character at a corpse and whether it is there now, as our force sees it (survival-fair): the killer
-- alive and in sight (where, how far from the corpse), alive out of sight, or no longer alive; and the enemy units
-- within 32 tiles of the corpse seen now. {killed_by, killer_now, units_near} (nil fields when unknown).
function M.killer_facts(surface_name,pos,tick)
  local d=M.death_of(surface_name,pos,tick)
  local surface=game.get_surface(surface_name)
  local out={}
  if d then
    out.killed_by=string.format('%s%s%s%s',d.by or 'unknown',d.at and string.format(' at (%g,%g)',d.at.x,d.at.y) or '',
      d.damage_type and ' ('..d.damage_type..' damage)' or '',d.episode and string.format(', %d damage taken in the last %d s',d.episode.damage,d.episode.s) or '')
    local c=d.cause
    if c then
      if c.valid then
        local q=c.position
        if surface and M.avoid.seen_now(surface,q) then
          out.killer_now=string.format('the %s that killed it is alive at (%g,%g), %.0f tiles from the corpse (in sight now)',c.name,math.floor(q.x+0.5),math.floor(q.y+0.5),distance(q,pos))
        else
          out.killer_now=string.format('the %s that killed it is alive, out of our sight now',c.name)
        end
      else
        out.killer_now=string.format('the %s that killed it is no longer alive',d.by or 'enemy')
      end
    end
  end
  if surface and M.avoid.seen_now(surface,pos) then
    local okf,list=pcall(function() return surface.find_entities_filtered{position=pos,radius=32,type='unit',force='enemy',limit=64} end)
    local kinds,n={},0
    for _,u in ipairs(okf and list or {}) do n=n+1; kinds[u.name]=(kinds[u.name] or 0)+1 end
    local parts={}
    for name,k in pairs(kinds) do parts[#parts+1]=k..' '..name end
    table.sort(parts)
    out.units_near=n>0 and string.format('%d enemy unit%s within 32 tiles of the corpse now: %s',n,n==1 and '' or 's',table.concat(parts,', ')) or 'no enemy unit within 32 tiles of the corpse now'
  else
    out.units_near='the corpse lies out of our sight now: units there are not seen'
  end
  return out
end
-- A belt destroyed with items on it (d17 batch13 C1, Opus: three cuts in a coal trunk found only after the drills had
-- backed up 10 minutes): where, which way it moved its items, what it carried and what destroyed it; told to the owner
-- of the claim it lies in (and the agent who placed it) every 2 s, waking them (M.belt_cut_tell). At most 64 kept.
function M.note_belt_cut(event)
  local e=event.entity
  local items={}
  local n=0
  for i=1,(pcall(function() return e.get_max_transport_line_index() end) and e.get_max_transport_line_index() or 0) do
    for _,c in ipairs((pcall(function() return e.get_transport_line(i).get_contents() end)) and e.get_transport_line(i).get_contents() or {}) do
      items[c.name]=(items[c.name] or 0)+c.count; n=n+c.count
    end
  end
  if n==0 then return end
  local s=state()
  s.belt_cuts=s.belt_cuts or {}
  if #s.belt_cuts>=64 then return end
  local cause=event.cause
  local okl,lu=pcall(function() return e.last_user and e.last_user.name end)
  s.belt_cuts[#s.belt_cuts+1]={surface=e.surface.name,position={x=e.position.x,y=e.position.y},name=e.name,direction=M.direction_name(e.direction),
    items=items,tick=event.tick,by=cause and cause.valid and cause.name or nil,force=e.force.name,placed_by=okl and lu or nil}
end
function M.belt_cut_tell()
  local s=state()
  local list=s.belt_cuts
  if not list or #list==0 then return end
  s.belt_cuts=nil
  -- by owner: the claim the cut lies in, else the agent who placed the belt
  local agents={}
  for _,ag in ipairs(M.board.agents()) do agents[ag.name]=ag.index end
  local by_owner,order={},{}
  for _,c in ipairs(list) do
    local surface=game.get_surface(c.surface)
    local claim=surface and M.claims and M.claims.find({name='',surface=surface},c.position) or nil
    local owner=claim and claim.owner or (c.placed_by and agents[c.placed_by] and c.placed_by) or nil
    -- no claim and no placer of ours: the nearest agent on that surface
    if not owner then
      local bd
      for _,ag in ipairs(M.board.agents()) do
        local p=M.lookup(ag.index)
        local ch=p and p.character
        if ch and ch.valid and ch.surface.name==c.surface then
          local d=distance(ch.position,c.position)
          if not bd or d<bd then owner,bd=ag.name,d end
        end
      end
    end
    if owner and agents[owner] then
      if not by_owner[owner] then by_owner[owner]={}; order[#order+1]=owner end
      table.insert(by_owner[owner],{c=c,claim=claim})
    end
  end
  for _,owner in ipairs(order) do
    local parts,items,by,claim={},{},{},nil
    for i,x in ipairs(by_owner[owner]) do
      local c=x.c
      claim=claim or x.claim
      if i<=8 then parts[#parts+1]=string.format('%s (%g,%g) facing %s',c.name,c.position.x,c.position.y,c.direction or '?') end
      for name,k in pairs(c.items) do items[name]=(items[name] or 0)+k end
      if c.by then by[c.by]=(by[c.by] or 0)+1 end
    end
    local it,bt={},{}
    for name,k in pairs(items) do it[#it+1]=k..' '..name end
    for name,k in pairs(by) do bt[#bt+1]=k..' by '..name end
    table.sort(it); table.sort(bt)
    local n=#by_owner[owner]
    local text=string.format('%d belt%s carrying items destroyed%s%s: %s%s (they carried %s); a ghost stands where each was if robots or construct are to rebuild it (inspect lists it with its direction)',
      n,n==1 and '' or 's',#bt>0 and ' ('..table.concat(bt,', ')..')' or '',
      claim and string.format(' in your claim #%s',tostring(claim.id)) or ' (no claim there; you are the nearest)',table.concat(parts,'; '),n>8 and string.format('; +%d more',n-8) or '',
      #it>0 and table.concat(it,', ') or 'items')
    M.board.deliver(agents[owner],{seq='belt-cut',tick=game.tick,from='belt cut',text=text,wake=true})
  end
end
-- The character's and its vehicle's units (the hits and kills above are keyed by them).
function M.units_of(p)
  local out={}
  local c=p.character
  if c and c.valid then
    out[#out+1]=c.unit_number
    local v=c.vehicle
    if v and v.valid and v.unit_number then out[#out+1]=v.unit_number end
  end
  return out
end
-- Status hurt: the last hit on the character or the vehicle it rides in the last 5 minutes: tick, ago_s, by (the
-- attacker's name, else the damage type), at (the attacker's position), damage (this episode's, hits under 10 s apart),
-- what (the vehicle's name when the vehicle was hit), or nil.
function M.hurt_row(p)
  local s=state()
  if not s.hurt then return nil end
  local best
  for _,unit in ipairs(M.units_of(p)) do
    local h=s.hurt[unit]
    if h and game.tick-h.tick<=M.HURT.keep and (not best or h.tick>best.tick) then best=h end
  end
  if not best then return nil end
  return {tick=best.tick,ago_s=math.floor((game.tick-best.tick)/60),by=best.by,at=best.at,damage=math.floor(best.damage+0.5),what=best.what}
end
-- Status combat: the shoot channel's own record plus what it does now: target {name, position, distance} (the enemy
-- it aims at, or the fixed spot of a shoot at a position), fired_tick (the last tick it fired at something: an enemy in
-- range, or the fixed spot), kills_10s (kills by the character or its vehicle in the last 10 s) and hurt (hurt_row).
-- A shoot auto with nothing in range has no target and no recent fired_tick.
-- (d22 batch93 BC2, viewer Foobator 13:33: "could the camera on spidertrons zoom out a bit more when rockets are fired?
-- half the action is not on cam") While the character drives a spidertron: its guns' reach (the prototype's longest
-- gun range; 2.0.77: four rocket launchers, 36 tiles), the rockets loaded, and the enemies within that reach, which it
-- fires at on its own: how many (up to 64), the farthest and nearest distance, their box. One bounded find, only seated
-- in a spidertron; nil otherwise. The stream's director frames them (onecam.py).
local spider_range={}
function M.vehicle_fire(p)
  local v=p.driving and p.vehicle
  if not (v and v.valid and v.type=='spider-vehicle') then return nil end
  local range=spider_range[v.name]
  if not range then
    range=0
    for _,g in pairs(v.prototype.guns or {}) do
      local ok,r=pcall(function() return g.attack_parameters.range end)
      if ok and type(r)=='number' and r>range then range=r end
    end
    spider_range[v.name]=range
  end
  local inv=v.get_inventory(defines.inventory.spider_ammo)
  local out={vehicle=v.name,unit_number=v.unit_number,range=range,ammo=inv and inv.get_item_count() or 0,targets=0}
  if range<=0 then return out end
  local pos=v.position
  local found=v.surface.find_entities_filtered{force='enemy',position=pos,radius=range,type={'unit','unit-spawner','turret','segmented-unit','spider-unit'},limit=64}
  local far,near,l,t,r,b=0,nil
  for _,e in ipairs(found) do
    local q=e.position
    local d=((q.x-pos.x)^2+(q.y-pos.y)^2)^0.5
    if d>far then far=d end
    if not near or d<near then near=d end
    l=l and math.min(l,q.x) or q.x; t=t and math.min(t,q.y) or q.y; r=r and math.max(r,q.x) or q.x; b=b and math.max(b,q.y) or q.y
  end
  out.targets=#found
  if #found>0 then
    out.farthest=math.floor(far*10+0.5)/10; out.nearest=math.floor(near*10+0.5)/10
    out.box={left_top={x=math.floor(l),y=math.floor(t)},right_bottom={x=math.ceil(r),y=math.ceil(b)}}
    out.more=#found>=64 or nil
  end
  return out
end
function M.combat_row(index,p)
  local combat=state().combat and state().combat[index]
  if not combat then return false end
  local out={}
  for k,v in pairs(combat) do out[k]=v end
  local aim=combat_targets()[index]
  local e=aim and (aim.fixed or aim.entity)
  local alive=p and p.character and p.character.valid
  -- the scan's last pick counts while it is in range (the scan runs every 6 ticks; an enemy that left is no target)
  if e and e.valid and not aim.fixed and not (alive and distance(p.position,e.position)<=(combat.radius or 0)) then e=nil end
  if e and e.valid then
    out.target={name=e.name,position={x=math.floor(e.position.x+0.5),y=math.floor(e.position.y+0.5)},
      distance=alive and math.floor(distance(p.position,e.position)*10+0.5)/10 or nil}
  elseif not combat.auto and combat.position then
    out.target={position=combat.position}
  end
  local n=0
  for _,unit in ipairs(alive and M.units_of(p) or {}) do
    for _,t in ipairs((state().char_kills or {})[unit] or {}) do if game.tick-t<=M.HURT.kills_window then n=n+1 end end
  end
  out.kills_10s=n
  out.hurt=alive and M.hurt_row(p) or nil
  return out
end
local function active(index)
  local action=state().active[index]
  if not action then
    local combat=state().combat and state().combat[index]
    return combat and {kind='shoot',until_tick=combat.until_tick} or false
  end
  local wait=(action.kind=='wait_until' or action.kind=='wait_ticks') and M.waiteta and M.waiteta.info({},action) or {}
  return {kind=action.kind,until_tick=action.until_tick,direction=action.direction,
    wait_estimates=wait.wait_estimates,idle_s=wait.idle_s,wait_line=wait.wait_line,
    next_index=action.next_index,total=action.cells and #action.cells,placed=action.placed,skipped=action.skipped,
    cleared=action.kind=='build_path' and action.mined or nil,mining=action.kind=='build_path' and action.mining and action.mining.entity.valid and action.mining.entity.name or nil,
    next_position=action.cells and action.cells[action.next_index] and action.cells[action.next_index].position,
    target=action.entity and action.entity.valid and {name=action.entity.name,position=action.entity.position} or nil,
    kills=action.kills,shooting=action.kind=='kite' and action.target or nil,
    built=action.built,remaining=action.kind=='construct' and construction.remaining(action) or nil,
    missing=action.missing and next(action.missing) and action.missing or nil,
    awaiting_craft=action.awaiting_craft,got=action.got,
    silo_wait=action.await_silo and M.rocketload.wait_report(action) or action.silo_hold and M.rocketload.wait_report({await_silo=action.silo_hold}) or nil,
    condition=action.kind=='wait_until' and action.condition['until'] or nil,saw=action.kind=='wait_until' and action.saw or nil,
    -- (d17 batch34 A5, Astra 12:24: a load_silo tour holding at the silo for the rocket read stuck_s and "14 tiles to it"
    -- for 40 s, and was stopped) a tour holding at a silo stands by design: no stuck_s, and holding says why
    stuck_s=action.watch and not action.silo_hold and game.tick-action.watch.since>=STUCK_TICKS and math.floor((game.tick-action.watch.since)/60) or nil,
    holding=action.kind=='gather' and action.silo_hold and M.rocketload.hold_line(action) or nil,
    -- Waiting short of rails a moving train will pass (M.train_guard).
    train_wait=M.train_wait_line(action.train_wait or (type(action.nav)=='table' and action.nav.train_wait) or nil),
    retreating=action.retreated and (action.retreated.why..(action.retreated.going and '; '..action.retreated.going or '')) or nil,
    -- the stream director's look-ahead: where the work is (set once when the action starts, never per tick)
    bounds=action.bounds,to=action.kind=='move_to' and action.position or nil,
    -- A walk into reach for a call (autowalk.lua): the call made on arrival.
    walking_for=action.then_call and action.then_call.action or nil,
    leg=action.kind=='move_to' and action.via and string.format('%d of %d',action.via.index,#action.via.points+1) or nil,
    -- A walking tour's or a courier's progress (Muse, Luna, shift19): leg N of M, the walk left, moved so far.
    progress=action.kind=='gather' and not action.wait and not action.silo_hold and M.tour_progress(index,action) or nil,
    held_short=action.held_short,  -- a tour waiting short of a live attack at its stop (d17 batch17 B1)
    remote=action.kind=='drive' and action.remote and action.vehicle and action.vehicle.valid and
      string.format('%s at (%.1f,%.1f) by remote view',action.vehicle.name,action.vehicle.position.x,action.vehicle.position.y) or nil}
end
M.active=active
-- A queued tour's finished part, kept on its queue step (Luna, shift19: queued timed transfers interrupted by a direct
-- action failed whole while harvesting yumako): the stops left, what it moved, and a courier's leg; scheduler.lua
-- requeues the step from there when it is interrupted.
function M.tour_mark(index,action)
  action.marked_index=action.index
  local q=(state().queues or {})[index]
  local cur=q and q.current
  if not cur or type(action.targets)~='table' then return end
  local left={}
  for k=action.index or 1,#action.targets do
    local t=action.targets[k]
    if t and t.position then left[#left+1]={x=t.position.x,y=t.position.y} end
  end
  local give=action.legs and action.legs[2]
  cur.tour_left={positions=left,done=(action.index or 1)-1,total=#action.targets,got=action.got or 0,item=action.item,quality=action.quality,
    fill=action.fill,courier=action.legs and true or nil,taken=action.taken,give_inventory=give and give.inventory or nil}
end
-- "leg 2 of 3 (to steel-chest (12.5,4.5)), 37 tiles to it, 85 tiles left in all; moved 40 iron-plate so far": a timed
-- transfer, collect, feed, rearm or refuel tour, or a courier (take, then give), read from the action as it runs.
function M.tour_progress(index,action)
  local targets=action.targets
  if type(targets)~='table' or #targets==0 then return nil end
  local i=math.min(action.index or 1,#targets)
  local t=targets[i]
  local p=M.lookup and M.lookup(index)
  local c=p and (p.character or p)
  local here=c and c.valid~=false and c.position
  if not (t and t.position and here) then return nil end
  local to=distance(here,t.position)
  local all,prev=to,t.position
  for k=i+1,#targets do local q=targets[k].position; if q then all=all+distance(prev,q); prev=q end end
  local name=t.entity and t.entity.valid and t.entity.name or t.name or 'place'
  local moved
  if action.legs then moved=string.format('took %d, delivered %d',action.taken or 0,math.max(0,(action.got or 0)-(action.taken or 0)))
  else moved=string.format('moved %d%s so far',action.got or 0,action.item and ' '..action.item or '') end
  return string.format('%s %d of %d (%s (%g,%g)), %.0f tiles to it, %.0f tiles left in all; %s',action.legs and 'leg' or 'stop',i,#targets,
    name,t.position.x,t.position.y,to,all,moved)
end
-- {left,top,right,bottom} around a list of cells or ghosts, once when an action is planned (at most 512 cells).
-- A field of M, not a top-level local (tests/locals.lua: runtime.lua keeps 3 of Lua's 200 free).
function M.cell_bounds(list,pos)
  local b
  for _,c in ipairs(list or {}) do
    local q=pos(c)
    if q then
      if not b then b={left=q.x,top=q.y,right=q.x,bottom=q.y}
      else b.left=math.min(b.left,q.x); b.top=math.min(b.top,q.y); b.right=math.max(b.right,q.x); b.bottom=math.max(b.bottom,q.y) end
    end
  end
  return b
end
-- Our own space platforms are shown whole in remote view: every chunk of
-- their surface counts as charted and visible.
local function own_platform(p)
  local pl=p.surface.platform
  return pl~=nil and pl.force==p.force
end
local function visible(p,pos)
  -- Acting on a platform by name (platform=): remote view shows all of it.
  if type(p)=='table' and rawget(p,'__platform') and own_platform(p) then return true end
  -- Another surface by name (surface=): remote view shows its visible chunks.
  if type(p)=='table' and rawget(p,'__remote') then return own_platform(p) or p.force.is_chunk_visible(p.surface,{x=math.floor(pos.x/32),y=math.floor(pos.y/32)}) end
  return distance(p.position,pos) <= 32 and (own_platform(p) or p.force.is_chunk_visible(p.surface, {x=math.floor(pos.x/32), y=math.floor(pos.y/32)}))
end
local function chunk_of(pos) return {x=math.floor(pos.x/32),y=math.floor(pos.y/32)} end
-- Reach and visibility failures say where the character actually stood, so a
-- plan step that ran from an unexpected spot is obvious from its error.
local function from_character(p,pos)
  return string.format('(%g,%g) is %.1f tiles from the character at (%.1f,%.1f)',pos.x,pos.y,distance(p.position,pos),p.position.x,p.position.y)
end
-- The nearest chunk our force sees now (radar coverage or a character's
-- sight) to pos, within 8 chunks: "(96,-64)-(127,-33), 40 tiles away".
function M.nearest_coverage(p,pos)
  local ok,text=pcall(function()
    local cx,cy=math.floor(pos.x/32),math.floor(pos.y/32)
    local best,bd
    for r=1,8 do
      if bd and (r-1)*32>bd then break end
      for dx=-r,r do
        for dy=-r,r do
          if math.max(math.abs(dx),math.abs(dy))==r and p.force.is_chunk_visible(p.surface,{x=cx+dx,y=cy+dy}) then
            local x0,y0=(cx+dx)*32,(cy+dy)*32
            local nx,ny=math.max(x0,math.min(pos.x,x0+32)),math.max(y0,math.min(pos.y,y0+32))
            local d=((nx-pos.x)^2+(ny-pos.y)^2)^0.5
            if not bd or d<bd then best,bd={x0,y0},d end
          end
        end
      end
    end
    if not best then return 'no chunk within 256 tiles of it is in radar coverage or a character\'s sight' end
    local d=math.max(1,math.floor(bd+0.5))
    return string.format('the nearest radar coverage (or a character\'s sight) is chunk (%d,%d)-(%d,%d), %d %s away',best[1],best[2],best[1]+31,best[2]+31,d,d==1 and 'tile' or 'tiles')
  end)
  return ok and text or nil
end
-- The tick our force's reads last saw each chunk (B1, Muse 12:20: empty ground read the same whether never charted or
-- charted and empty now): every read that finds a chunk in sight or in a chunk our force sees records it; at most 4096
-- chunks, the oldest record dropped first.
function M.saw_chunk(p,pos)
  local ok,key=pcall(function() local c=chunk_of(pos); return p.force.name..'|'..p.surface.name..'|'..c.x..','..c.y end)
  if not ok then return end
  local s=state(); local m=s.chunk_seen
  if not m then m={by={},ring={},next=1}; s.chunk_seen=m end
  if not m.by[key] then
    local old=m.ring[m.next]; if old then m.by[old]=nil end
    m.ring[m.next]=key; m.next=m.next%4096+1
  end
  m.by[key]=game.tick
end
-- What a player's map says of the chunk at pos: in sight now, charted and out of sight (with the tick our reads last saw
-- it), or never charted.
function M.ground_state(p,pos)
  local c=chunk_of(pos)
  if own_platform(p) or p.force.is_chunk_visible(p.surface,c) then return string.format('chunk (%d,%d) is in sight now (tick %d)',c.x,c.y,game.tick) end
  if not p.force.is_chunk_charted(p.surface,c) then return string.format('chunk (%d,%d) was never charted',c.x,c.y) end
  local m=state().chunk_seen
  local t=m and m.by[p.force.name..'|'..p.surface.name..'|'..c.x..','..c.y]
  return string.format('chunk (%d,%d) is charted and not in sight now; %s',c.x,c.y,
    t and string.format('our reads last saw it at tick %d (%ds ago)',t,math.floor((game.tick-t)/60)) or 'no read of ours saw it since the harness began recording (radar coverage shows it again)')
end
local function assert_visible(p,pos,what)
  if visible(p,pos) then M.saw_chunk(p,pos); return end
  -- Out of sight in a chunk our force sees: no coverage to name.
  local near=not (own_platform(p) or p.force.is_chunk_visible(p.surface,chunk_of(pos))) and M.nearest_coverage(p,pos) or nil
  if type(p)=='table' and rawget(p,'__remote') then
    error(string.format('%s at (%g,%g) on %s is not in a visible chunk (remote view needs radar coverage there)%s',what,pos.x,pos.y,p.surface.name,near and '; '..near or ''),2)
  end
  error(string.format('%s is outside local visible area: %s (limit 32 tiles, in a visible chunk; move_to within 30 tiles first)%s',what,from_character(p,pos),near and '; '..near or ''),2)
end
-- Reads by remote view (2.0): on the character's own surface the map shows
-- every entity in a chunk our force sees now (Astra, operator 04:57: inspect
-- only worked within 32 tiles). Returns 'remote view' when pos is out of the
-- character's sight but in such a chunk; nil in sight; errors otherwise,
-- naming the nearest radar coverage. Another surface by name (surface=) is
-- always remote view, with assert_visible's refusal.
function M.read_sight(p,pos,what)
  if type(p)=='table' and rawget(p,'__remote') then assert_visible(p,pos,what); return 'remote view' end
  if visible(p,pos) then M.saw_chunk(p,pos); return nil end
  if own_platform(p) or p.force.is_chunk_visible(p.surface,chunk_of(pos)) then M.saw_chunk(p,pos); return 'remote view' end
  local near=M.nearest_coverage(p,pos)
  local okg,g=pcall(M.ground_state,p,pos)
  error(string.format('%s at (%g,%g) (%s) is in no chunk our force sees now (radar coverage or a character\'s sight)%s%s',what,pos.x,pos.y,
    from_character(p,pos),okg and '; '..g or '',near and '; '..near or ''),0)
end
-- The chunks under a box our force sees now (d20 batch56 R3: inspect {area} of an empty area in sight read like a
-- sight refusal, 27 times in shifts 45-47; R2: a screenshot's frame by remote view): seen, all, and the unseen ones.
function M.area_sight(p,lt,rb)
  local seen,n,unseen=0,0,{}
  for cx=math.floor(lt.x/32),math.floor(rb.x/32) do
    for cy=math.floor(lt.y/32),math.floor(rb.y/32) do
      n=n+1
      if own_platform(p) or p.force.is_chunk_visible(p.surface,{x=cx,y=cy}) then seen=seen+1 else unseen[#unseen+1]={x=cx,y=cy} end
    end
  end
  return seen,n,unseen
end
function M.area_sight_text(p,lt,rb)
  local seen,n=M.area_sight(p,lt,rb)
  if seen==n then return n==1 and 'the area is in sight now (our force sees its chunk)' or string.format('the area is in sight now (our force sees all %d of its chunks)',n) end
  if seen==0 then
    local near=M.nearest_coverage(p,{x=(lt.x+rb.x)/2,y=(lt.y+rb.y)/2})
    return string.format('the area is out of sight now (%s our force sees: radar coverage or a character\'s sight lights a chunk)%s',
      n==1 and 'its chunk is not one' or string.format('none of its %d chunks is one',n),near and '; '..near or '')
  end
  return string.format('%d of its %d chunks in sight now, %d out of sight',seen,n,n-seen)
end
local function charted(p,pos) return own_platform(p) or p.force.is_chunk_charted(p.surface,chunk_of(pos)) end
-- Read views may be centred anywhere on the charted map, so scripts can look
-- without walking the character there.
local function center(p,a)
  if a.position==nil then return p.position end
  local pos=position(a.position)
  assert(charted(p,pos),'position must be in a charted chunk')
  return pos
end
-- What the player's map shows: everything in visible chunks; in charted but
-- fogged chunks only what stays drawn there (own and neutral entities, enemy
-- structures), never units that may have moved since.
local drawn_enemy={['unit-spawner']=true,turret=true}
local function known(p,e)
  local chunk=chunk_of(e.position)
  if own_platform(p) or p.force.is_chunk_visible(p.surface,chunk) then return true end
  if not p.force.is_chunk_charted(p.surface,chunk) then return false end
  return e.force==p.force or (e.force.name=='neutral' and e.type~='unit') or drawn_enemy[e.type]==true
end
local attached={['rocket-silo-rocket']=true,['rocket-silo-rocket-shadow']=true,['cargo-pod']=true}
-- Rails under a locomotive or wagon: the cursor picks the train, so a rail
-- is the target only when nothing else is there or it is named.
M.UNDER={['straight-rail']=true,['half-diagonal-rail']=true,['curved-rail-a']=true,['curved-rail-b']=true,['legacy-straight-rail']=true,
  ['legacy-curved-rail']=true,['elevated-straight-rail']=true,['elevated-half-diagonal-rail']=true,['elevated-curved-rail-a']=true,
  ['elevated-curved-rail-b']=true,['rail-ramp']=true,['rail-support']=true}
-- Flying robots, units and other passing or unselectable entities over a building yield to it unless named or
-- given by unit_number (Sol, shift08: a robot over a chest made inspect, transfer and collect there ambiguous).
M.PASSING={['logistic-robot']=true,['construction-robot']=true,['combat-robot']=true,['capture-robot']=true,unit=true,
  ['spider-unit']=true,projectile=true,['artillery-projectile']=true,fire=true,stream=true,sticker=true,beam=true,
  explosion=true,['smoke-with-trigger']=true,['highlight-box']=true,['speech-bubble']=true,['particle-source']=true,
  -- an item request (a turret ghost's ammo, built in) sits on its building (Astra 08:43: rearm on 6 guns was ambiguous)
  ['item-request-proxy']=true}
function M.passing(e)
  if M.PASSING[e.type] then return true end
  local ok,selectable=pcall(function() return e.prototype.selectable_in_game end)
  return ok and selectable==false
end
-- How a candidate at a position ranks as the target, as a player's cursor picks; the one rule for every call that
-- resolves a position, in reach and by remote view (Astra 07:05: requests by remote view took a logistic robot over
-- a requester chest): 1 a building (or anything named or given by unit_number), 2 a ghost, 3 rails under a train,
-- 4 ore, an item on the ground or a tile ghost, 5 a passing entity (a flying robot, a unit, a projectile, anything unselectable).
function M.target_rank(e,args)
  local named=args.name or args.unit_number
  -- A tile ghost (foundation under a platform layout's ghosts, Astra 12:20) yields like ore: a tile, not a building.
  if (e.type=='resource' or e.type=='item-entity' or e.type=='tile-ghost') and not args.name then return 4 end
  if e.type=='entity-ghost' and not args.name then return 2 end
  if not named and M.passing(e) then return 5 end
  if not named and M.UNDER[e.type] then return 3 end
  return 1
end
local function entity(p,args,read_only)
  local pos = position(args.position)
  -- A read sees by remote view too (read_sight); an action needs the character's sight; a walk's target
  -- (read_only 'walk': move_to target) any entity the map draws, on a charted chunk; read_only 'unreached': an
  -- action's target (ore at the point before a drill over it) seen by sight or remote view, out of reach too
  -- (autowalk.lua: the call walks there first).
  local by
  if read_only=='walk' then
    if not charted(p,pos) then error(string.format('target (%g,%g) is on a chunk the map has not charted',pos.x,pos.y),0) end
  elseif read_only then by=M.read_sight(p,pos,'target') else assert_visible(p,pos,'target') end
  local candidates = p.surface.find_entities_filtered{position=pos, radius=0.2, name=args.name}
  -- name may be what a ghost there will build (a ghost's own name is entity-ghost).
  if args.name and #candidates==0 then candidates = p.surface.find_entities_filtered{position=pos, radius=0.2, ghost_name=args.name} end
  -- Ore under a building is never the intended target unless named explicitly
  -- (resource: the fallback, ore or an item on the ground).
  -- A ghost on a building (a paste replacing it) yields to the building
  -- unless named, as the cursor picks the building; inspect lists the ghost.
  -- An item lying on a chest's tile is not the target either (shake3: Grok's
  -- "ambiguous target" until the item was picked up). M.target_rank orders them.
  local found
  local others = {}
  local function wanted(e)
    -- A silo's rocket and its cargo pod sit on the silo; they are never the
    -- intended target unless named.
    return e.valid and (not args.unit_number or e.unit_number == args.unit_number) and e.type ~= 'character'
      and (args.name or not attached[e.type])
  end
  for _, e in pairs(candidates) do
    if wanted(e) then
      local rank = M.target_rank(e, args)
      if rank > 1 then others[rank] = others[rank] or e
      else
        if found then
          error(string.format('ambiguous target: %s and %s at (%g,%g); specify name or unit_number', found.name, e.name, pos.x, pos.y), 0)
        end
        found = e
      end
    end
  end
  -- Any tile of a building's footprint picks it, as a player's cursor does
  -- (shake3: Gemini's inspect missed buildings off their centre). Ore at the
  -- point stays the target of an action (mine there means the ore, never the
  -- drill over it); a read takes the building.
  if not found and ((read_only and read_only~='unreached') or not others[4]) then
    local cover
    for _, e in pairs(p.surface.find_entities_filtered{position=pos, name=args.name}) do
      local rank = wanted(e) and M.target_rank(e, args)
      if rank == 1 and e.type ~= 'resource' and e.type ~= 'item-entity' then
        if cover and cover ~= e then cover = nil; break end
        cover = e
      elseif rank and rank ~= 4 and rank ~= 1 then others[rank] = others[rank] or e end
    end
    found = cover
  end
  found = found or others[2] or others[3] or others[4] or others[5]
  -- A tile corner (Muse 09:24: a position copied from an alert, rounded to integers, missed the chest at x.5 beside it):
  -- the one entity of a tile touching that corner is the target; several are named.
  if not found and pos.x == math.floor(pos.x) and pos.y == math.floor(pos.y) then
    local touch = {}
    for _, e in pairs(p.surface.find_entities_filtered{position=pos, radius=0.75, name=args.name}) do
      if wanted(e) and e.type ~= 'resource' and e.type ~= 'item-entity' and M.target_rank(e, args) == 1
        and math.abs(e.position.x - pos.x) <= 0.5 and math.abs(e.position.y - pos.y) <= 0.5 then touch[#touch+1] = e end
    end
    if #touch == 1 then found = touch[1]
    elseif #touch > 1 then
      local parts = {}
      for i, e in ipairs(touch) do if i <= 4 then parts[#parts+1] = string.format('%s (%g,%g)', e.name, e.position.x, e.position.y) end end
      -- name (or unit_number) picks one (E2, Haiku 19:50: the refusal said only "by its position")
      error(string.format('(%g,%g) is a tile corner %d entities touch: %s; "name": "%s" (or unit_number %s) picks that one, or the position of the one meant',
        pos.x, pos.y, #touch, table.concat(parts, ', '), touch[1].name, tostring(touch[1].unit_number)), 0)
    end
  end
  -- (d24 batch154, the batch149 review's bug 7: inspect {name: rocket-silo} on a pole read "entity not found ...
  -- nearest small-electric-pole 0.0 tiles") name left out what stands there: say so, naming it
  if not found and args.name then
    local there={}
    for _,e in pairs(p.surface.find_entities_filtered{position=pos,limit=8}) do
      if e.valid and e.type~='resource' and e.type~='character' and not attached[e.type] and M.target_rank(e,{})<=2 then
        there[#there+1]=string.format('%s (%g,%g)%s',e.type=='entity-ghost' and 'ghost '..e.ghost_name or e.name,e.position.x,e.position.y,
          e.unit_number and ' unit_number '..e.unit_number or '')
      end
    end
    if #there>0 then
      -- (the text starts as the plain miss does: mine {name} falls back to a tile of that name on it)
      error(string.format('entity not found at (%g,%g): no %s there; name=%s left out what stands there: %s; without name (or with its own name) that is the target',
        pos.x,pos.y,tostring(args.name),tostring(args.name),table.concat(there,', ',1,math.min(3,#there))),0)
    end
  end
  if not found then
    -- Say what is close instead (shake3: 23 of Gemini's inspect misses were a
    -- tile or so from a pole, inserter or belt, or empty).
    local near = {}
    for _, e in pairs(p.surface.find_entities_filtered{position=pos, radius=3, limit=32}) do
      if e.valid and e.type ~= 'resource' and not attached[e.type] and e ~= p.character then near[#near+1] = e end
    end
    table.sort(near, function(x, y) return distance(x.position, pos) < distance(y.position, pos) end)
    local parts = {}
    for i = 1, math.min(3, #near) do
      local e = near[i]
      local name = e.type == 'character' and ((M.character_owner(e) or 'another') .. "'s character") or e.type == 'entity-ghost' and 'ghost ' .. e.ghost_name or e.name
      parts[i] = string.format('%s (%g,%g) %.1f tiles', name, e.position.x, e.position.y, distance(e.position, pos))
    end
    local okg, g = pcall(M.ground_state, p, pos)
    error(string.format('entity not found at (%g,%g): %s%s; target an entity\'s position as scan lists it (observe scope=scan position={x=%g,y=%g} radius=3)',
      pos.x, pos.y, #parts > 0 and 'nearest ' .. table.concat(parts, ', ') or 'nothing within 3 tiles', okg and ' (' .. g .. ')' or '', pos.x, pos.y), 0)
  end
  -- Reads (inspect) only need sight, as scan does; by is 'remote view' when it was out of the character's.
  if read_only then return found,by end
  if not p.can_reach_entity(found) then error(M.out_of_reach(p,found),0) end
  return found
end
-- The reach the engine applies (can_reach_entity, read on world n at 01:58 against measured distances; Grok 01:51:
-- "mine says reach 10 but fails at 3 to 8 tiles"): the distance from the character to the entity's collision box
-- (bounding_box), within reach_distance (10) for buildings and within resource_reach_distance (2.7) for ore, trees and plants.
-- An assembler 10.19 tiles from its box was out though 9.78 from its selection box; a belt 10.25 from its centre was in
-- at 9.70 from its box; trees 4.3 to 11 tiles from their box and stone ore 3.24 were out, ore at 2.31 in. Rocks
-- (simple-entity) are taken as trees; a target the engine refuses inside the long reach gets the short one.
-- Plants have their own type, distinct from trees (wild jellystems on Gleba).
M.SHORT_REACH={resource=true,tree=true,plant=true,['simple-entity']=true,fish=true}
function M.box_distance(pos,e)
  local ok,b=pcall(function() return e.bounding_box end)
  if not (ok and b and b.left_top) then return distance(pos,e.position) end
  local dx=math.max(b.left_top.x-pos.x,0,pos.x-b.right_bottom.x)
  local dy=math.max(b.left_top.y-pos.y,0,pos.y-b.right_bottom.y)
  return (dx*dx+dy*dy)^0.5
end
-- (reach, what it is for) for this target; d: its box distance when the engine has refused it.
function M.reach_for(p,e,d)
  local long=p.reach_distance or 10
  local ok,short=pcall(function() return p.resource_reach_distance end)
  short=ok and type(short)=='number' and short or 2.7
  if M.SHORT_REACH[e.type] or (d and d<=long) then return short,' (ore, trees, plants and rocks)' end
  return long,''
end
-- Out of reach (Haiku, shift09: about once a cycle): how far to its edge, the reach for it, and a free spot that
-- reaches it by the same rule.
function M.out_of_reach(p,e)
  local at,from=e.position,p.position
  local d=M.box_distance(from,e)
  local reach,kind=M.reach_for(p,e,d)
  local text=string.format('entity is out of reach: %s at (%g,%g) is %.1f tiles away (to its edge), reach %g%s',e.name,at.x,at.y,d,reach,kind)
  local ok,spot=pcall(function()
    -- Points on the line from it toward you, nearest to you first, that are within reach of its box; each moved to
    -- free ground and kept only if still within reach.
    local cd=distance(from,at)
    local ux,uy=1,0
    if cd>0 then ux,uy=(from.x-at.x)/cd,(from.y-at.y)/cd end
    local tries=0
    for k=math.floor(cd*2)/2,0,-0.5 do
      local q={x=at.x+ux*k,y=at.y+uy*k}
      if M.box_distance(q,e)<=reach-0.4 then
        local free=p.surface.find_non_colliding_position('character',q,2,0.25)
        if free and M.box_distance(free,e)<=reach-0.2 then return free end
        tries=tries+1
        if tries>=8 then return nil end
      end
    end
  end)
  if ok and spot then text=text..string.format('; in reach from (%g,%g)',math.floor(spot.x*10+0.5)/10,math.floor(spot.y*10+0.5)/10) end
  return text
end
-- Remote view (2.0) opens any own entity in a visible chunk, without reach.
local function remote_entity(p,a)
  local pos=position(a.position)
  assert(own_platform(p) or p.force.is_chunk_visible(p.surface,chunk_of(pos)),
    string.format('target must be in a visible chunk (remote view): (%g,%g) on %s is not visible to our force now (radar coverage there)',pos.x,pos.y,p.surface.name))
  -- The best rank (M.target_rank: a building before a flying robot over it, an entity ghost after a building, a
  -- tile ghost after both), then the nearest. Entity ghosts count, as the cursor picks them in remote view
  -- (Astra 12:20: configure on a 75-entity ghost layout on Starling found only the foundation tile ghosts).
  local found,best,rank
  local function pick(list)
    for _,e in pairs(list) do
      if e.valid and e.type~='character' and (a.name or not attached[e.type]) and (not a.unit_number or e.unit_number==a.unit_number) then
        local r,d=M.target_rank(e,a),distance(e.position,pos)
        if not found or r<rank or (r==rank and d<best) then found,best,rank=e,d,r end
      end
    end
  end
  pick(p.surface.find_entities_filtered{position=pos,radius=0.5,name=a.name,force=p.force})
  -- name may be what a ghost there will build.
  if not found and a.name then pick(p.surface.find_entities_filtered{position=pos,radius=0.5,ghost_name=a.name,force=p.force}) end
  -- Any tile of a building's footprint picks it, as the cursor does in remote view (a silo is 9x9).
  if not found or rank>1 then pick(p.surface.find_entities_filtered{position=pos,name=a.name,force=p.force}) end
  assert(found,string.format('no entity of ours at (%g,%g) on %s',pos.x,pos.y,p.surface.name))
  return found
end
-- Per-entry failures drop "file:line: " prefixes; rethrows can stack them.
local function reason(err)
  local text,n=tostring(err),1
  while n>0 do text,n=text:gsub('^[^:]*:%d+: ','') end
  return text
end
local function friendly(p,e) assert(e.force == p.force or e.force.name == 'neutral', 'cannot manipulate another force') end
-- An action's one target, seen and out of reach (autowalk.lua): within 32 tiles the call walks into reach first, as
-- move_to {target} walks, and is made there. Returns the walk's reply; nil when the target is in reach or not seen, or
-- the call does not walk (walk: false, or made again after its walk). Past 32 tiles without walk: true it is refused,
-- naming the call that walks. args: the target's own (default a); check: what the call refuses before any walk.
function M.walk_first(p,action,a,args,check)
  if a.walk==false or a.walked then return nil end
  local ok,e=pcall(entity,p,args or a,'unreached')
  if not (ok and e and e.valid) or p.can_reach_entity(e) then return nil end
  friendly(p,e)
  if check then check(e) end
  local f=M.autowalk.entity_far(p,e)
  if not M.autowalk.wanted(action,a,{f}) then return nil end
  return M.autowalk.approach(p,action,a,{entity=e},M.autowalk.line({f},1,f))
end
-- The targets of a transfer, collect, feed, rearm or refuel out of reach (autowalk.lua), seen by sight or remote view:
-- their far records, the number of targets and every target's entity in order; nil when each is in reach, or one is
-- not found (the call's own errors then say so).
function M.unreached(p,a)
  local list=a.positions or (a.position~=nil and {a.position}) or nil
  if type(list)~='table' or #list==0 or #list>64 then return nil end
  local far,ents={},{}
  for i,pos in ipairs(list) do
    local ok,e=pcall(entity,p,{position=pos,name=type(pos)=='table' and pos.name or a.name,unit_number=type(pos)=='table' and pos.unit_number or a.unit_number},true)
    if not (ok and e and e.valid) then return nil end
    ents[i]=e
    if not p.can_reach_entity(e) then far[#far+1]=M.autowalk.entity_far(p,e) end
  end
  if #far==0 then return nil end
  return far,#list,ents
end
local entity_status_names={}
for name,value in pairs(defines.entity_status or {}) do entity_status_names[value]=name end
-- A burner its full burnt-result slot stopped reads burnt_result_full, whatever the engine's status reads (burnt.lua;
-- Sol, shift14: two biochambers read working for minutes and made nothing): supply, bottleneck, trace, rates, the
-- science line, the status survey and scan rows read it so.
M.burnt=require('burnt'){}
function M.machine_status(e)
  local ok,f=pcall(M.burnt.stuck,e)
  if ok and f then return f.unusable and M.burnt.UNUSABLE or M.burnt.STATE end
  return entity_status_names[e.status]
end
-- Defaults are omitted to save agent context: direction north, full health,
-- and the player's own force are implied when absent.
local compass_names={[0]='north',[4]='east',[8]='south',[12]='west'}
-- An entity's quality (a ghost's: what it builds) when not normal, else nil (d20 batch122, Astra #2087: legendary
-- engines proved by a blueprint export; inspect and scan read no quality).
function M.quality_of(e) return e.quality.name end
function M.quality_name(e)
  local ok,q=pcall(M.quality_of,e)
  if ok and q and q~='normal' then return q end
end
local function summary(e)
  local max_health=e.max_health
  local out={name=e.name, type=e.type~=e.name and e.type or nil, position=e.position, unit_number=e.unit_number,
    direction=e.direction~=0 and e.direction or nil, health=e.health and max_health and e.health<max_health and e.health or nil,
    force=e.force.name~='player' and e.force.name or nil, status_name=entity_status_names[e.status], amount=e.type == 'resource' and e.amount or nil,
    ghost_name=(e.type=='entity-ghost' or e.type=='tile-ghost') and e.ghost_name or nil,ghost_type=e.type=='entity-ghost' and e.ghost_type or nil,
    quality=M.quality_name(e)}
  -- An electric machine no pole reaches is unpowered, whatever its status
  -- reads (Gemini's roboports read low_power for 2 h 45 min).
  if e.type~='entity-ghost' and e.type~='tile-ghost' and M.unpowered then
    local ok,why=pcall(M.unpowered,e)
    if ok and why then out.status_name='unpowered'; out.power=why end
  end
  if e.type~='entity-ghost' and e.type~='tile-ghost' then
    local ok,f=pcall(M.burnt.stuck,e)
    if ok and f then out.status_name=f.unusable and M.burnt.UNUSABLE or M.burnt.STATE; out.burnt_result_full=M.burnt.line(e,f,entity_status_names[e.status]) end
  end
  -- An underground end shows what the belt GUI arrows show: which end it is
  -- (flow direction by name) and where its partner is.
  if e.type=='underground-belt' then
    local other=e.neighbours
    out.underground=e.belt_to_ground_type; out.flow=compass_names[e.direction]
    if other then out.paired_with=other.position else out.unpaired=true end
  end
  -- A belt, underground or splitter (or its ghost): where it moves items and what feeds it (beltflow.lua;
  -- Grok, shift11: a belt facing south read as feeding the tile at lower y; south is +y).
  if M.beltflow and (M.beltflow.TYPES[e.type] or e.type=='entity-ghost' and M.beltflow.TYPES[e.ghost_type]) then
    local ok,line=pcall(M.beltflow.line,e)
    out.belt=ok and line or nil
  end
  -- Pumps and underground pipes likewise: where fluid enters and leaves.
  if e.type=='pump' or e.type=='offshore-pump' or e.type=='pipe-to-ground' then pipes.hint(e,out) end
  -- An unpaired end says why: lava or space under its reach, its partner a
  -- ghost or out of reach, or none (underpass.lua).
  if out.unpaired and M.underpass then
    local ok,why=pcall(M.underpass.why,e)
    out.unpaired_why=ok and why or nil
  end
  -- Inserter direction names the pickup side; show the tiles it moves between.
  local function tile(pos) return {x=math.floor(pos.x)+0.5,y=math.floor(pos.y)+0.5} end
  if e.type=='inserter' then
    out.pickup=tile(e.pickup_position); out.drop=tile(e.drop_position)
    -- Nothing to take from or put into on a point (the engine's targets):
    -- 'no pickup target', 'no drop target' (targets.lua).
    out.io_warning=M.targets and M.targets.missing(e) or nil
  end
  -- Item filters in use, one line (details.lua filters_line).
  if (e.type=='inserter' or e.type=='loader' or e.type=='loader-1x1') and M.details then
    local ok,line=pcall(M.details.filters_line,e)
    out.filters=ok and line or nil
  end
  -- A drill drops onto one tile beside its footprint: which, and into what
  -- (sapilot board #4: Astra placed output chests by trial).
  if e.type=='mining-drill' then
    local ok,drop,into=pcall(function() return e.drop_position,e.drop_target end)
    if ok and drop then out.drop=tile(drop); out.drop_into=into and into.valid and into.name or nil end
  end
  if M.readmemory then pcall(M.readmemory.observe,e) end
  return out
end
