-- The real action names nearest an unknown one, at most 6: one that contains it or that it contains, a typo of up to 2
-- letters, else one sharing a word of 3+ letters (host/reference.ts nearNames); the fewest letters apart first.
function M.near_actions(name)
  if type(name)~='string' or name=='' or #name>64 then return {} end
  local function apart(x,y)
    local row={}
    for j=0,#y do row[j]=j end
    for i=1,#x do
      local diag=row[0]; row[0]=i
      for j=1,#y do local prev=row[j]; row[j]=math.min(row[j]+1,row[j-1]+1,diag+(x:sub(i,i)==y:sub(j,j) and 0 or 1)); diag=prev end
    end
    return row[#y]
  end
  -- a shared word only when nothing is nearer (techologies: technologies, not damage_log for "log")
  local list,weak={},{}
  for n in pairs(handlers) do
    if type(n)=='string' and n:sub(1,1)~='_' then
      local d=math.abs(#n-#name)<=2 and apart(n,name) or 99
      if d<=2 or (#name>=3 and (n:find(name,1,true) or name:find(n,1,true))) then list[#list+1]={n=n,d=d}
      else for w in n:gmatch('[^_]+') do if #w>2 and name:find(w,1,true) then weak[#weak+1]={n=n,d=d}; break end end end
    end
  end
  if #list==0 then list=weak end
  table.sort(list,function(x,y) if x.d~=y.d then return x.d<y.d end return x.n<y.n end)
  local out={}
  for i=1,math.min(6,#list) do out[i]=list[i].n end
  return out
end
