  for name,schema in pairs(M.turretfeed and M.turretfeed.schema or {}) do description.actions[name]=schema end
  for name,schema in pairs(M.beltupgrade and M.beltupgrade.schema or {}) do description.actions[name]=schema end
  for name,schema in pairs(M.alertdigest and M.alertdigest.schema or {}) do description.actions[name]=schema end
  for name,schema in pairs(M.reqrate and M.reqrate.schema or {}) do description.actions[name]=schema end
  for name,schema in pairs(M.dependency and M.dependency.schema or {}) do description.actions[name]=schema end
  for name,schema in pairs(M.ghostlist and M.ghostlist.schema or {}) do description.actions[name]=schema end
  for name,schema in pairs(M.lostlog and M.lostlog.schema or {}) do description.actions[name]=schema end
  for name,schema in pairs(M.silo and M.silo.schema or {}) do description.actions[name]=schema end
  for name,schema in pairs(M.rocketload and M.rocketload.schema or {}) do description.actions[name]=schema end
  -- Settings on entries (entryset.lua; Sol 19:50): place_ghosts and build entries, and a single build's own.
  if M.entryset then
    local t=M.entryset.schema_text
    local pg,b=description.actions.place_ghosts,description.actions.build
    if pg and pg.entities then pg.entities=pg.entities..'; each entry may also carry '..t end
    if b and b.builds then b.builds=b.builds..'; each entry may also carry '..t end
    if b then
      b.configure='a single build: configure arguments for it (as configure takes them, no position); builds entries carry their own'
      b.requests='a single build: requests arguments for it (set, clear, ...)'
      b.circuit='a single build: circuit_set arguments for it (enable, read, settings, decider, ...)'
      b.wires='a single build: [{to {x,y}, color red|green, from_side?, to_side?}] from it'
      b.retry_when_clear='optional true: a build refused because its walk ends in an area under attack now (passing enemies; none for a worm or spawner) waits until no enemy unit is within 48 tiles there (retry_ticks, default 5 min), then builds again, at most 6 times'
      b.retry_ticks='with retry_when_clear: 600..54000 (default 18000)'
      b.retries='(set by the retry: how many so far)'
      b.rail_layer='optional, a single build: '..'rail_layer (rail and chain signals): ground or elevated, the rail layer it goes beside (as a player\'s cursor over elevated rails places it on them); the game\'s own check on that layer decides, and with none given the ground layer and then the elevated; with no direction the facing of the signal spot there (placements {name: rail-signal} lists the spots); the reply says the layer placed'
    end
    -- (AG1) rail_layer on a signal's entry
    if pg and pg.entities then pg.entities=pg.entities..'; an entry may carry rail_layer (rail and chain signals): ground or elevated, the rail layer it goes beside (as a player\'s cursor over elevated rails places it on them); the game\'s own check on that layer decides, and with none given the ground layer and then the elevated; with no direction the facing of the signal spot there (placements {name: rail-signal} lists the spots); the reply says the layer placed' end
    if b and b.builds then b.builds=b.builds..'; an entry may carry rail_layer (rail and chain signals: ground or elevated) and orientation (rolling stock)' end
    -- (AG2) rolling stock's facing
    if b then b.orientation='optional, rolling stock (locomotives and wagons): 0..1 (0 north, 0.25 east, 0.5 south, 0.75 west), asked as the nearest of 16 directions; the game snaps it to the way along the rail nearer to it (direction does the same); the reply\'s rolling_stock reads back orientation, facing, couplings and the train\'s locomotives facing its front and its back; a dry run gives rolling_stock: the rail under each and the way it faces' end
    local rt=description.actions.rotate
    if rt and rt.returns then rt.returns=rt.returns..'; on rolling stock: flipped (uncoupled, flipped, coupled: the steps), before (its line), rolling_stock {orientation, facing, coupled, train {front_locomotives, back_locomotives, ...}, line}, not_recoupled; or unchanged' end
    if rt and rt.direction then rt.direction=rt.direction..'; on rolling stock (no direction in the game): rotate flips it 180 degrees as R does (with direction: only when it faces more than 90 degrees from there); the game flips one coupled to another only uncoupled, so it is uncoupled at each end, flipped and coupled again; refused while its train moves; the reply gives flipped (the steps), before, rolling_stock' end
  end
  -- (d18 batch37 U1) a walking tour waits for a leg enemies pass
  local LEGW=' On the walk (rearm by default; a walking transfer with retry_when_clear): a leg enemies pass (units or a group seen now in 24 tiles of it) is waited for where you stand, rechecked every 3 s, up to retry_ticks (default 60 s), then walked (last.ahead_waited says each wait); enemies_ahead only when the wait runs out (it says how long it waited). retry_when_clear: false on rearm: no wait'
  for _,n in ipairs({'rearm','transfer'}) do
    local d=description.actions[n]
    if d and type(d.retry_when_clear)=='string' then d.retry_when_clear=d.retry_when_clear..LEGW end
  end
  -- (d18 batch37 C1) transfer {steps}
  if description.actions.transfer then
    description.actions.transfer.steps='a chain in one walking call: [{take: [{x,y}, ...], item, count?}, {give: [{x,y}, ...], item, split?: "even" | "fill", count?}, ...] in order (32 chests at most): a take takes the item from those chests (count in all; default all), a give gives what you hold of it (even: an even share at each; fill: all that fits, the default; count: at most that many); the first leg that fails or is not reached ends it: last.chain_held (what of its items you hold), last.chain_left (the steps left)'
    description.actions.transfer.on_fail='with steps: "return": on a failure, what the chain took and you still hold goes back to the chests it came from (a second walk; last.chain_return); "keep" (default): you keep it'
  end
  -- (d18 batch36 C1) clear_obstacles on build and place_ghosts (clearobs.lua)
  for _,name in ipairs({'build','place_ghosts'}) do
    local d=description.actions[name]
    if d then d.clear_obstacles='optional true: the trees and rocks in the entries\' footprints are marked for deconstruction, those in reach mined by hand (a timed construct over them), the rest left to the construction robots; once all are gone the call runs again (watched 10 min; last.cleared); none in the way: the call runs at once (cleared says so); returns cleared, mining, robots, then_runs. The dry run lists them in trees_rocks' end
  end
  description.actions.status.brief='boolean: only active (a walking tour or courier adds progress: stop or leg N of M, the place, tiles to it and left in all, moved so far), last, combat, last_combat, vehicle_fire (seated in a spidertron: its guns\' range, rockets loaded, and the enemies within range it fires at: targets, farthest, nearest, box), alive, connected, surface, platform, position and tick (what fh --wait polls); without it, factory, machines, fuel/power/ammo/lab warnings, pollution and chart are shared by every agent on the same surface and refreshed every 10 s (factory_as_of, threats_as_of give the tick when older, factory_age_s its age; factory_refresh_failed and chart.refresh_failed when the last background refresh failed: when, the error, the age kept)'
  description.actions.status.alerts='boolean, with brief: add the alerts block (losses, attacked areas, groups, enemy news; read from what the game reported, no scan)'
  -- (d20 batch70 AF3, viewer Aurora: "Sonnet's plan still says free while sampling Cinder") the site's agent cards
  -- (d20 batch70 AF4, Astra #1718) inspect of a logistic or construction robot
  description.actions.inspect.returns=(description.actions.inspect.returns and description.actions.inspect.returns..'; ' or '')..'robot: for a logistic or construction robot (by position, unit_number or in an area): robot {unit_number, name, position, cargo {name, quality, count} (its one cargo slot; holds says it too), heading {x, y} (where it flies; none when it has no order), network (its logistic network id), line}; nothing records where a robot picked up what it carries'
  -- (d22 batch78 AN1, Astra #1809) items on the ground
  description.actions.inspect.returns=description.actions.inspect.returns..'; stack: items on the ground (item-on-ground): stack {name, quality, count, fresh (percent fresh, an item that spoils)} and holds, as hovering it shows; an area with types item-entity or name item-on-ground lists them (they belong to no force), each row with stack, and ground_items, all of them by item'
  description.actions.status.work='boolean, with brief: add watches, the agent\'s bounded watches (uptime, turret_tally, belt_flow, collector_tally, asteroid_watch, signal_watch) running or needing it: id, kind, scope, state (running, done with its final not read, late, stalled, invalid), start_tick, end_tick, latest {tick, line}, reason, line, mixed (d23 batch123 CF2: an edit inside what it measures split its window: the line); and the flight watches it set (kind flight_watch, id flight#N, scope its platform, state armed (waiting for the departure), running or done until read or replaced, end_tick its time limit); none when there are none'
  description.actions.status.inventory='boolean: add inventory, one line: main (name*count, free slots), ammo, guns, armor with its equipment, trash slots, cursor (the inventory read in one line)'
  description.actions.cameras={returns='director cameras: player, follow, position, zoom'}
  -- inspect's circuit readback and another surface by remote view (circuits.lua).
  description.actions.inspect.surface='optional planet or surface name: inspect there by remote view (a visible chunk)'
  description.actions.inspect.note=description.actions.inspect.note..'; circuit (an entity with circuit settings or wires): enable/logistic conditions as text with _met, disabled, logistic_reads (the logistic network the condition reads, whose logistic area holds the entity\'s centre, with its count of the item; none: never met, and the nearest roboport area\'s distance), '..
    'settings and off (switches, modes, signals by the names circuit_set takes), a combinator\'s settings and output, wires per color (red, green, copper; '..
    'a combinator\'s red_input ... green_output, a power switch\'s copper_left/right) with each far end {entity, position, side}, networks {id, signals} (the signals on each now)'
  for name,list in pairs(M.EXAMPLES) do
    local s=description.actions[name]
    if s then s.examples=list end
  end
  description.runtime_fault=state().runtime_fault or false
  description.bundle=bundle
  return description
end
function handlers.attach(p,a)
  state().controlled=state().controlled or {}
  assert(a.offline~=true,'offline control is unsupported; join a graphical Factorio client')
  state().controlled[p.index]={allow_cheat_mode=a.allow_cheat_mode==true}
  return {player=p.index,connected=p.connected,allow_cheat_mode=a.allow_cheat_mode==true}
end
function handlers.detach(p)
  M.stop_player(p.index)
  if state().controlled then state().controlled[p.index]=nil end
  return {detached=true}
end
-- Losses (buildings destroyed) are kept as incidents: one per 64-tile cell,
-- counting every entity by name, so a wiped outpost is reported whole. A cell
-- quiet for 5 minutes, or a new shift (operator shift_start), starts a new
-- incident (shake5: one raid's total grew across two shifts and read as one
-- raid); the old ones stay in status alerts with since.
-- Since the shift 5 study, an incident is one raid: losses on the same surface within 32 tiles of its box join it
-- (while the box stays under 192 tiles), it has an id, and a reader is told it once and then its running total at most
-- once a game minute while it grows (shift 5: 839 loss lines for about 30 raids, each growth repeated).
-- One table: runtime.lua's main chunk is near Lua's 200-local limit (tests/locals.lua).
local LOSS={cell=64,max=64,join=32,span=192,again=3600,first=18000,near=2}
-- Entities the game removes on its own are no losses (Luna, 08:56: a cargo pod's container emptied of its 50 rocket
-- fuel vanished and was told as incident #183, friendly fire from an unknown source): a landed pod's container
-- (temporary-container) and the pod itself, items on the ground, corpses, ghosts and request proxies.
LOSS.not_lost={['temporary-container']=true,['cargo-pod']=true,['item-entity']=true,corpse=true,['character-corpse']=true,
  ['entity-ghost']=true,['tile-ghost']=true,['item-request-proxy']=true}
-- An incident's latest tick is `(i.last or i.first or 0)`: saves from before shake11 can hold one created without
-- `last` (it was set only after the 64-incident cap check, which then failed on it in the tick: shake10's quarantines).
-- friendly: the cause is one of the entity's own force (shake11-12: our flamethrower turrets burnt gun turrets, radars,
-- belts and their own oil lines in 8 and 11 areas), kept apart from enemy causes, with where the cause stood.
local function record_loss(tick,e,cause,friendly,cause_at)
  local s=state()
  s.losses=s.losses or {}
  local x,y=e.position.x,e.position.y
  local surface=e.surface and e.surface.name or nil
  local incident
  for _,i in ipairs(s.losses) do
    local b=i.box
    if i.surface==surface and not i.closed and tick-(i.last or i.first or 0)<=5*3600
      and x>=b[1]-LOSS.join and x<=b[3]+LOSS.join and y>=b[2]-LOSS.join and y<=b[4]+LOSS.join
      and math.max(b[3],x)-math.min(b[1],x)<=LOSS.span and math.max(b[4],y)-math.min(b[2],y)<=LOSS.span then incident=i; break end
  end
  if not incident then
    s.loss_ids=(s.loss_ids or 0)+1
    local ok,platform=pcall(function() return e.surface.platform and e.surface.platform.name end)
    incident={id=s.loss_ids,key=math.floor(x/LOSS.cell)..','..math.floor(y/LOSS.cell),surface=surface,platform=ok and platform or nil,
      box={x,y,x,y},first=tick,last=tick,names={},causes={},total=0}
    s.losses[#s.losses+1]=incident
    if #s.losses>LOSS.max then
      local oldest=1
      -- last is set at creation: the newest incident once had none, and this compare failed and left it so (shake11)
      for i,v in ipairs(s.losses) do if (v.last or v.first or 0)<(s.losses[oldest].last or s.losses[oldest].first or 0) then oldest=i end end
      table.remove(s.losses,oldest)
    end
  end
  s.loss_seq=(s.loss_seq or 0)+1
  -- (d20 batch55 P3) a loss after an incident's recovery check, joining it or within LOSS.near of its box, reopens it
  for _,i in ipairs(s.losses) do
    local r,q=i.recovery,i.box
    if r and i.surface==surface and tick>r.tick and (i==incident or x>=q[1]-LOSS.near and x<=q[3]+LOSS.near and y>=q[2]-LOSS.near and y<=q[4]+LOSS.near) then
      r.lost=(r.lost or 0)+1; r.reopened=r.reopened or tick; r.names=r.names or {}; r.names[e.name]=(r.names[e.name] or 0)+1
    end
  end
  local b=incident.box
  b[1],b[2],b[3],b[4]=math.min(b[1],e.position.x),math.min(b[2],e.position.y),math.max(b[3],e.position.x),math.max(b[4],e.position.y)
  incident.last=tick; incident.seq=s.loss_seq; incident.total=incident.total+1
  incident.names[e.name]=(incident.names[e.name] or 0)+1
  -- On a platform (B7, Luna 13:52: Swift lost 28 structures in a minute; the alert gave counts and a box): each lost
  -- entity's name and position, at most 48 an incident, read at the alert for a ghost there.
  if incident.platform then
    incident.lost_at=incident.lost_at or {}
    if #incident.lost_at<48 then incident.lost_at[#incident.lost_at+1]={name=e.name,x=e.position.x,y=e.position.y} end
  end
  -- A drill: what it mined and at what rate, and who built it (Opus, d15 22:51: the NW coal mine was wiped and noticed
  -- 15 min later; urgent.lua tells its builders when the output there is gone).
  if e.type=='mining-drill' then pcall(function()
    local res=e.mining_target
    local mp=res and res.valid and res.prototype.mineable_properties
    local prod=mp and mp.products and mp.products[1]
    if prod and prod.name then
      local speed=(e.prototype.mining_speed or 0)*(1+(e.force.mining_drill_productivity_bonus or 0))
      local per_min=(mp.mining_time or 1)>0 and speed/(mp.mining_time or 1)*60*(prod.amount or 1) or 0
      incident.mined=incident.mined or {}
      local m=incident.mined[prod.name] or {drills=0,per_min=0}
      m.drills=m.drills+1; m.per_min=m.per_min+per_min
      incident.mined[prod.name]=m
      local who=e.last_user and e.last_user.name
      if who then incident.builders=incident.builders or {}; incident.builders[who]=true end
    end
  end) end
  if cause and friendly then
    incident.friendly=incident.friendly or {}; incident.friendly[cause]=(incident.friendly[cause] or 0)+1
    -- Where the burning turret stands (up to 2 per name), so the reader can find it.
    if cause_at then
      incident.friendly_at=incident.friendly_at or {}
      local list=incident.friendly_at[cause] or {}; incident.friendly_at[cause]=list
      local at=string.format('(%g,%g)',cause_at.x,cause_at.y)
      local known=false
      for _,v in ipairs(list) do if v==at then known=true end end
      if not known and #list<2 then list[#list+1]=at end
      LOSS.own_add(incident,cause,cause_at,e)
    end
  elseif cause then incident.causes[cause]=(incident.causes[cause] or 0)+1 end
end
-- (d18 batch40 A1, Sol 21:21: Wayfarer lost 27 structures to its own bow railguns; the platform alert said "28
-- destroyed ... by 1 small-oxide-asteroid") the count per turret of ours that destroyed something, by where it
-- stands: own_by [{name, x, y, n}], at most 8 (own_more counts the rest). The first such loss on a platform is told
-- to the platform's listeners (platalerts.lua) once an incident, with the read that gives a railgun's line of fire.
function LOSS.own_add(incident,cause,at,e)
  incident.own_by=incident.own_by or {}
  local row
  for _,r in ipairs(incident.own_by) do if r.name==cause and r.x==at.x and r.y==at.y then row=r end end
  if not row and #incident.own_by<8 then row={name=cause,x=at.x,y=at.y,n=0}; incident.own_by[#incident.own_by+1]=row end
  if row then row.n=row.n+1 else incident.own_more=(incident.own_more or 0)+1 end
  if not incident.platform or incident.own_told then return end
  incident.own_told=true
  pcall(function()
    local pl=e.surface.platform
    local arc=M.fireline and M.fireline.arc(cause)
    local line=string.format('platform %s: our own %s at (%g,%g) destroyed %s at (%g,%g) (loss #%d)%s',incident.platform,cause,at.x,at.y,
      e.name,e.position.x,e.position.y,incident.id,arc and string.format('; platform_defense {platform: "%s"} gives its line of fire (the entities of ours its shots cross)',incident.platform) or '')
    for _,who in ipairs(M.platalerts.listeners(pl)) do
      M.board.deliver(who.index,{seq='ownfire',tick=game.tick,from='loss alert',text=line,wake=true})
    end
  end)
end
-- Our own destroyers of an incident, most first: rows {name, at, n}, their total and those past the 8 kept.
function LOSS.own(i)
  local rows,total={},i.own_more or 0
  for _,r in ipairs(i.own_by or {}) do rows[#rows+1]={name=r.name,at=string.format('(%g,%g)',r.x,r.y),n=r.n}; total=total+r.n end
  table.sort(rows,function(a,b) return a.n>b.n or a.n==b.n and a.at<b.at end)
  return rows,total,i.own_more or 0
end
-- A platform's kept incidents' own destroyers (platform_defense): rows {name, x, y, n, loss, last_tick}, most first.
function LOSS.own_on(platform)
  local out={}
  for _,i in ipairs(state().losses or {}) do
    if i.platform==platform then
      for _,r in ipairs(i.own_by or {}) do out[#out+1]={name=r.name,x=r.x,y=r.y,n=r.n,loss=LOSS.id(i),last_tick=i.last or i.first} end
    end
  end
  table.sort(out,function(a,b) return a.n>b.n or a.n==b.n and a.loss<b.loss end)
  return out
end
-- "27 destroyed by our own railgun-turret at (-0.5,-21.5): 20, railgun-turret at (9.5,-21.5): 7", or nil.
function LOSS.own_text(i)
  local rows,total=LOSS.own(i)
  if #rows==0 then return nil end
  local parts,named={},0
  for k,r in ipairs(rows) do if k<=4 then parts[k]=string.format('%s at %s: %d',r.name,r.at,r.n); named=named+r.n end end
  return string.format('%d destroyed by our own %s%s',total,table.concat(parts,', '),total>named and string.format(' (+%d more)',total-named) or '')
end
local function losses_since(since)
  local out={}
  -- An incident without a last tick (shake11: status failed for 4 agents on 'compare number with nil') counts as old.
  for _,i in ipairs(state().losses or {}) do if (i.last or i.first or 0)>since then out[#out+1]=i end end
  table.sort(out,function(a,b) return (a.last or a.first or 0)>(b.last or b.first or 0) end)
  return out
end
local function ago(ticks)
  local sec=math.floor(ticks/60)
  if sec>=3600 then return string.format('%dh%02dm',math.floor(sec/3600),math.floor(sec/60)%60) end
  if sec>=60 then return string.format('%dm%02ds',math.floor(sec/60),sec%60) end
  return sec..'s'
end
local function counted(t)
  local names={}
  for name,n in pairs(t) do names[#names+1]={name,n} end
  table.sort(names,function(a,b) return a[2]>b[2] or a[2]==b[2] and a[1]<b[1] end)
  for i,v in ipairs(names) do names[i]=v[2]..' '..v[1] end
  return names
end
-- An incident kept from before ids gets one when next read.
function LOSS.id(i)
  if not i.id then local s=state(); s.loss_ids=(s.loss_ids or 0)+1; i.id=s.loss_ids end
  return i.id
end
-- What an incident lost and what destroyed it, as text: names ("4 stone-wall, 3 gun-turret"), causes ("5 small-biter,
-- friendly fire: 2 flamethrower-turret at (80,90)": our own entities after the enemy ones), or nil.
function LOSS.parts(i)
  local names=counted(i.names)
  while #names>6 do table.remove(names) end
  local causes=counted(i.causes)
  while #causes>2 do table.remove(causes) end
  local friendly={}
  local rows=LOSS.own(i)
  if #rows>0 then
    -- (batch40 A1) each turret of ours by where it stands with its count, then those not placed (unknown source)
    local placed={}
    for k,r in ipairs(rows) do placed[r.name]=(placed[r.name] or 0)+r.n; if k<=4 then friendly[k]=string.format('%d %s at %s',r.n,r.name,r.at) end end
    for name,n in pairs(i.friendly or {}) do if n>(placed[name] or 0) and #friendly<5 then friendly[#friendly+1]=(n-(placed[name] or 0))..' '..name end end
  else
    for _,v in ipairs(counted(i.friendly or {})) do
      local name=v:match('^%d+ (.+)$')
      local at=name and i.friendly_at and i.friendly_at[name]
      friendly[#friendly+1]=v..(at and #at>0 and ' at '..table.concat(at,' ') or '')
    end
    while #friendly>2 do table.remove(friendly) end
  end
  if #friendly>0 then
    -- our own first when they destroyed more than the enemies did (the stream's label names the first)
    local ours,theirs=0,0
    for _,n in pairs(i.friendly or {}) do ours=ours+n end
    for _,n in pairs(i.causes or {}) do theirs=theirs+n end
    table.insert(causes,ours>theirs and 1 or #causes+1,'friendly fire: '..table.concat(friendly,', '))
  end
  return table.concat(names,', '),#causes>0 and table.concat(causes,', ') or nil
end
-- "#7 in (x,y)-(x,y) 40 destroyed: ..."; `reader` (a surface name) names an incident on another surface; without a
-- reader (an operator read) any surface but nauvis is named. `before` (the total the reader was told) marks a running total.
local function describe_incident(i,reader,before)
  local names,causes=LOSS.parts(i)
  local last=(i.last or i.first or 0)
  local span=i.first==last and ago(game.tick-last)..' ago' or ago(game.tick-i.first)..'-'..ago(game.tick-last)..' ago'
  local b=i.box
  local where=string.format('(%d,%d)',math.floor(b[1]),math.floor(b[2]))
  if b[3]-b[1]>=1 or b[4]-b[2]>=1 then where=where..'-'..string.format('(%d,%d)',math.floor(b[3]),math.floor(b[4])) end
  local on=''
  if i.platform then on=' on platform '..i.platform
  elseif i.surface and i.surface~=(reader or 'nauvis') then on=' on '..i.surface end
  return string.format('#%d%s in %s%s %d destroyed%s: %s%s, %s',LOSS.id(i),on,where,before and ' continue:' or '',i.total,
    before and string.format(' (+%d since you were told)',i.total-before) or '',names,
    causes and ' by '..causes or '',span)..(i.platform and LOSS.platform_places(i) or '')..LOSS.recovery_text(i)
end
-- A platform incident's lost entities by place: a ghost of the same entity there now (the hub rebuilds it, given the
-- item) or nothing (it needs a new placement), as the platform's map shows.
function LOSS.platform_places(i)
  local surface=i.surface and game.get_surface(i.surface)
  if not (surface and i.lost_at and #i.lost_at>0) then return '' end
  local ghosted,bare,rebuilt={},{},0
  for _,l in ipairs(i.lost_at) do
    local found,built=false,false
    for _,g in ipairs(surface.find_entities_filtered{position={l.x,l.y},radius=0.5}) do
      if g.valid and g.type=='entity-ghost' and g.ghost_name==l.name then found=true
      elseif g.valid and g.name==l.name then built=true end
    end
    local text=string.format('%s (%g,%g)',l.name,l.x,l.y)
    if built then rebuilt=rebuilt+1 elseif found then ghosted[#ghosted+1]=text else bare[#bare+1]=text end
  end
  local function list(t) return table.concat(t,', ',1,math.min(#t,12))..(#t>12 and string.format(' (+%d more)',#t-12) or '') end
  return (rebuilt>0 and string.format('; %d rebuilt already',rebuilt) or '')
    ..(#ghosted>0 and string.format('; a ghost stands at %d (the hub rebuilds them with the items): %s',#ghosted,list(ghosted)) or '')
    ..(#bare>0 and string.format('; no ghost at %d (a new placement each): %s',#bare,list(bare)) or '')
    ..(i.total>#i.lost_at and string.format('; the first %d of %d listed',#i.lost_at,i.total) or '')
end
-- (d20 batch55 P3, viewer Aurora 14:38: "Could alerts include the owner's dated recovery check?") An incident's recovery
-- check (losses {incident, recovery}): who, when, what was checked and the result, and a check of checks.lua with its
-- state now; a loss after it, joining the incident or within LOSS.near tiles of its box, reopens it (said, with what).
function LOSS.recovery_text(i)
  local r=i.recovery
  if not r then return '' end
  local what=r.checked..(r.result and ': '..r.result or '')
  local check=''
  if r.check and M.checks then
    local ok,v=pcall(M.checks.state_of,r.check)
    check=ok and v and '; '..v or ''
  end
  if r.reopened then
    local names=counted(r.names or {})
    while #names>4 do table.remove(names) end
    return string.format('; reopened: %d lost there since %s\'s recovery check %s ago (%s; the first %s ago; that check: %s)',r.lost,r.by,ago(game.tick-r.tick),
      table.concat(names,', '),ago(game.tick-r.reopened),what)..check
  end
  return string.format('; handled by %s, checked %s ago: %s',r.by,ago(game.tick-r.tick),what)..check
end
-- losses {incident, recovery?}: an incident by id (kept: the last 64), its row; recovery {checked, result?, check?} sets
-- its recovery check (yours, now), false clears it.
function LOSS.recover(p,a)
  local found
  for _,i in ipairs(state().losses or {}) do if LOSS.id(i)==a.incident then found=i end end
  assert(found,'no loss incident #'..tostring(a.incident)..' kept (status alerts.incidents lists them; the last 64 are kept)')
  local r=a.recovery
  local was=found.recovery
  if r==false then found.recovery=nil
  elseif r~=nil then
    assert(type(r)=='table' and type(r.checked)=='string' and r.checked:find('%S') and #r.checked<=200,'recovery is {checked (what you checked, 1..200 characters), result? (up to 200), check? (a check number)}')
    assert(r.result==nil or (type(r.result)=='string' and #r.result<=200),'recovery.result is text, at most 200 characters')
    if r.check~=nil then assert(type(r.check)=='number' and M.checks and M.checks.state_of(r.check),'recovery.check is a check number (checks lists them)') end
    found.recovery={by=M.board.who(p),tick=game.tick,checked=(r.checked:gsub('[%c]+',' ')),result=r.result and (r.result:gsub('[%c]+',' ')) or nil,check=r.check}
  end
  local row=LOSS.row(found,p.surface and p.surface.name)
  return {incident=row,replaced=r~=nil and was and string.format('%s\'s recovery check from %s ago',was.by,ago(game.tick-was.tick)) or nil,line=row.line}
end
-- status alerts.incidents: one row per loss incident for programs (the stream's loss banners and cuts): where (surface,
-- platform, box), how many, what, by what, when; the text line beside it.
function LOSS.row(i,reader)
  local names,causes=LOSS.parts(i)
  local b=i.box
  return {id=LOSS.id(i),surface=i.surface,platform=i.platform,box={x0=math.floor(b[1]),y0=math.floor(b[2]),x1=math.ceil(b[3]),y1=math.ceil(b[4])},
    total=i.total,names=names,by=causes,first_tick=i.first,last_tick=i.last or i.first,line=describe_incident(i,reader),
    recovery=i.recovery and {by=i.recovery.by,tick=i.recovery.tick,checked=i.recovery.checked,result=i.recovery.result,check=i.recovery.check,
      reopened=i.recovery.reopened and true or nil,reopened_tick=i.recovery.reopened,lost_since=i.recovery.lost} or nil}
end
-- Losses in the reply's team alerts: each incident once, then its running total at most once a game minute while it
-- grows. A reader never told anything starts with the incidents of the last 5 minutes. s.losses_told[index] holds
-- {id -> {tick, total}} for incidents still kept.
local function unseen_losses(p)
  local s=state()
  s.losses_told=s.losses_told or {}
  local told=s.losses_told[p.index]
  local new_reader=told==nil
  told=told or {}
  -- What a reader saw before ids (s.losses_seen, a loss_seq) counts as told.
  local seen=s.losses_seen and s.losses_seen[p.index]
  if s.losses_seen then s.losses_seen[p.index]=nil end
  local kept,due={},{}
  for _,i in ipairs(s.losses or {}) do
    local id=LOSS.id(i)
    local t=told[id]
    if not t and seen and (i.seq or 0)<=seen then t={tick=game.tick,total=i.total} end
    if t then
      kept[id]=t
      if i.total>t.total and game.tick-t.tick>=LOSS.again then due[#due+1]={i=i,before=t.total} end
    elseif not (new_reader and not seen and game.tick-(i.last or i.first or 0)>LOSS.first) then due[#due+1]={i=i}
    else kept[id]={tick=game.tick,total=i.total} end
  end
  s.losses_told[p.index]=kept
  if #due==0 then return nil end
  table.sort(due,function(a,b) return (a.i.last or 0)>(b.i.last or 0) end)
  local lines={}
  local reader=p.surface and p.surface.name
  for n,d in ipairs(due) do
    if n>4 then lines[#lines+1]=string.format('+%d more areas with losses; status alerts lists them',#due-4); break end
    lines[#lines+1]='losses '..describe_incident(d.i,reader,d.before)
    kept[d.i.id]={tick=game.tick,total=d.i.total}
  end
  return lines
end
local function recent_alerts(a,p)
  local since=a.since or game.tick-18000
  local reader=p and p.surface and p.surface.name
  local counts,latest,rows={},{},{}
  for _,i in ipairs(losses_since(since)) do
    for name,n in pairs(i.names) do counts[name]=(counts[name] or 0)+n end
    if #latest<8 then local row=LOSS.row(i,reader); latest[#latest+1]=row.line; rows[#rows+1]=row end
  end
  local attacks=threat.alerts(since,reader)
  local kills={}
  for _,k in ipairs(state().kills or {}) do if k.tick>since then kills[k.name]=(kills[k.name] or 0)+1 end end
  local okp,platform_hits=pcall(M.platalerts.rows,since)
  platform_hits=okp and platform_hits or nil
  local okc,power_cuts=pcall(M.powercut.since,since,reader)
  power_cuts=okc and power_cuts or nil
  if #latest==0 and not attacks and not next(kills) and not platform_hits and not power_cuts then return nil end
  local result=attacks or {}
  result.power_cuts=power_cuts
  if #latest>0 then result.losses=counts; result.latest=latest; result.incidents=rows end
  result.kills=next(kills) and kills or nil
  result.platform_hits=platform_hits
  return result
end
-- Hand-crafting queue as the crafting panel shows it, with the time left at
-- the character's crafting speed.
local function hand_speed(p)
  return 1+(p.character and p.character.character_crafting_speed_modifier or 0)+(p.force.manual_crafting_speed_modifier or 0)
end
-- Seconds of hand crafting left in the queue, and its item count.
local function crafting_left(p)
  local queue=p.crafting_queue
  if not queue or #queue==0 then return 0,0 end
  local items,seconds=0,0
  for _,entry in ipairs(queue) do
    local recipe=p.force.recipes[entry.recipe]
    if not entry.prerequisite then items=items+entry.count end
    seconds=seconds+(recipe and recipe.energy or 0.5)*entry.count
  end
  local head_recipe=p.force.recipes[queue[1].recipe]
  seconds=seconds-(head_recipe and head_recipe.energy or 0.5)*(p.crafting_queue_progress or 0)
  return math.max(0,seconds)/hand_speed(p),items
end
-- Items of this name the hand-crafting queue will still deliver (final
-- entries only; prerequisite crafts are consumed by the entry they feed).
local function crafting_count(p,item)
  local n=0
  for _,entry in ipairs(p.crafting_queue or {}) do
    local recipe=not entry.prerequisite and p.force.recipes[entry.recipe]
    for _,product in ipairs(recipe and recipe.products or {}) do
      if product.name==item then n=n+(product.amount or product.amount_max or 1)*entry.count end
    end
  end
  return n
end
local function crafting_line(p)
  local queue=p.crafting_queue
  if not queue or #queue==0 then return nil end
  local seconds,items=crafting_left(p)
  return string.format('%d items, ~%ds left, head=%s x%d',items,math.ceil(seconds),queue[1].recipe,queue[1].count)
end
-- A paused plan still holding steps is easy to forget between sessions.
do local function queue_warning(index)
  local q=state().queues and state().queues[index]
  if not (q and q.paused and #q.pending>0) then return nil end
  local first,last=q.pending[1],q.history[#q.history]
  local cause=''
  if last and last.ok==false and last.id then
    local why=type(last.result)=='table' and (last.result.reason or last.result.outcome) or nil
    cause=string.format('; paused when %s %s failed%s',last.id,last.action,why and ': '..reason(why) or '')
  end
  return string.format('queue: paused with %d pending step%s (first: %s %s%s)%s; queue resume runs them, queue cancel drops them',
    #q.pending,#q.pending==1 and '' or 's',first.id or '?',first.action,first.label and ' ['..first.label..']' or '',cause)
end
-- (d19 batch41 B3, Astra seq 862 and 864, Sol seq 865) status: the reminders and board items of this agent past their
-- review time, oldest first, with ages (reminders.lua overdue, board.lua overdue_reviews).
function M.overdue_reviews(p)
  local name=M.board.who(p)
  local rows={}
  local okr,r=pcall(M.reminders.overdue,name)
  for _,x in ipairs(okr and r or {}) do rows[#rows+1]=x end
  local okb,b=pcall(M.board.overdue_reviews,name)
  for _,x in ipairs(okb and b or {}) do rows[#rows+1]=x end
  if #rows==0 then return nil end
  table.sort(rows,function(x,y) return x.age>y.age end)
  local lines={}
  for i=1,math.min(8,#rows) do lines[i]=rows[i].line end
  if #rows>8 then lines[#lines+1]=string.format('+%d more (reminders {pending: true}; board_review)',#rows-8) end
  return lines
end
function handlers.status(p,a)
  a=a or {}
  local controllable,control_error=pcall(player,p.index)
  local alive=p.character and p.character.valid
  assert(a.inventory==nil or type(a.inventory)=='boolean','inventory must be true or false')
  -- inventory=true: the character's inventory in one line (Gemini, 06:20; M.inventory_line).
  local inv_line=a.inventory==true and alive and M.inventory_line(p) or nil
  -- What a wait polls for (fh --wait, several times a second): the action
  -- running and the last results, none of the factory, threat or alert scans.
  -- The stream's overlay adds alerts (stored incidents, no scan).
  if a.brief==true then
    return {brief=true,queues=scheduler.lanes(p.index),inventory=inv_line,active=active(p.index),retreat_guard=M.retreat_guard_line(p.index),last=state().last and state().last[p.index] or false,combat=M.combat_row(p.index,p),hurt=alive and M.hurt_row(p) or nil,flight=alive and M.flight_row(p) or nil,
      last_combat=state().last_combat and state().last_combat[p.index] or false,alive=alive or false,riding=p.driving or nil,connected=p.connected,
      vehicle_fire=alive and (function() local ok,v=pcall(M.vehicle_fire,p); return ok and v or nil end)() or nil,
      drop_pending=M.drop_pending(p.index),last_drop=M.last_drop(p.index),
      surface=alive and p.surface.name or nil,platform=alive and p.surface.platform and p.surface.platform.name or nil,
      alerts=a.alerts==true and recent_alerts(a,p) or nil,order=M.orders.brief(p.index),
      watches=a.work==true and M.work_watches(p) or nil,
      logistics_here=alive and (function() local ok,l=pcall(M.personal.here,p); return ok and l or nil end)() or nil,
      supported_control=controllable,control_error=not controllable and tostring(control_error) or nil,tick=game.tick,position=p.position}
  end
  -- (d22 batch93 BC1) list: every place a factory warning counts, paged (survey.lua M.list)
  if a.list~=nil then return survey.list(p,a.list,a.page) end
  assert(a.page==nil,'page goes with list')
  assert(a.alerts==nil,'alerts is an option of brief (a full status always has them)')
  assert(a.work==nil,'work is an option of brief')
  local threats=alive and threat.summary(p,a.threats==true) or {}
  -- Status is the recovery channel; a survey fault is reported, not raised.
  local surveyed,factory=true,{}
  if alive then surveyed,factory=pcall(survey.summary,p,a.machines==true) end
  if not surveyed then factory={error=reason(factory)} end
  local now=active(p.index)
  local paused=queue_warning(p.index)
  if paused then
    factory.warnings=factory.warnings or {}
    table.insert(factory.warnings,1,paused)
  end
  -- Fluid segments past the engine's extent limit carry no flow at all.
  if alive then
    -- One check per force and surface every 10 s, shared (one slot made agents on two surfaces rescan every call).
    state().fluid_check=nil
    state().fluid_checks=state().fluid_checks or {}
    local fkey=p.force.name..'/'..p.surface.index
    local fc=state().fluid_checks[fkey]
    if not fc or game.tick-fc.tick>=600 then
      local ok,list,limit=pcall(pipes.overlong,p,3)
      fc={tick=game.tick,surface=p.surface.index,list=ok and list or {},limit=limit}
      state().fluid_checks[fkey]=fc
    end
    for _,seg in ipairs(fc.list) do
      factory.warnings=factory.warnings or {}
      local b=seg.box
      factory.warnings[#factory.warnings+1]=string.format('fluid: %s segment spans %d tiles (limit %d) over (%d,%d)-(%d,%d), e.g. at (%g,%g): the game stops all flow into it; split it with a pump',
        seg.fluid and 'a '..seg.fluid or 'an empty',seg.extent,fc.limit,b[1],b[2],b[3],b[4],seg.at.x,seg.at.y)
    end
  end
  if alive then
    for _,line in ipairs(M.spoil.nearby(p) or {}) do
      factory.warnings=factory.warnings or {};factory.warnings[#factory.warnings+1]=line
    end
  end
  -- Fighting right now (hits in the last 10 s) goes first, with where.
  local fresh=alive and threat.alerts(game.tick-600)
  local shown=0
  for _,area in ipairs(fresh and fresh.attacked or {}) do
    -- Zero-damage hits (the crash site's fire) are not a fight.
    if shown<3 and area.damage>0 then
      shown=shown+1
      factory.warnings=factory.warnings or {}
      local on=area.surface and area.surface~=p.surface.name and ' on '..area.surface or ''
      table.insert(factory.warnings,shown,string.format('under attack%s near (%g,%g): %s hit %d times%s, %s ago',on,area.chunk_centre.x,area.chunk_centre.y,
        area.entities,area.hits,area.by and ' by '..area.by or '',ago(game.tick-area.last_tick)))
    end
  end
  -- Items on the ground: full landing pads that spill, piles near our buildings (ground.lua, a pass every 30 s).
  local alerts=recent_alerts(a,p)
  -- Our buildings out of radar sight per planet, with the nearest radar's state (pushalerts.lua; d17 territory, Nick 17:22).
  local oks,sight=pcall(M.pushalerts.sight_lines,p.force)
  if oks and sight then alerts=alerts or {}; alerts.out_of_sight=sight end
  -- What lies outside every construction area, requester/buffer chests outside every logistic area (part 4).
  local okc,cover=pcall(M.pushalerts.coverage_lines,p.force)
  if okc and cover then alerts=alerts or {}; alerts.outside_coverage=cover end
  local ground=alive and M.ground.alerts(p)
  if ground then alerts=alerts or {}; alerts.ground_items=ground end
  if now and now.stuck_s then
    factory.warnings=factory.warnings or {}
    table.insert(factory.warnings,1,string.format('character: %s made no progress and moved under 2 tiles for %ds near (%.1f,%.1f); likely physically stuck (belt, obstacle, unreachable goal): cancel or redirect it',
      now.kind,now.stuck_s,p.position.x,p.position.y))
  end
  -- On Fulgora: its sky now and the lightning bolts near you (lightning.lua M.sky; Gemini 12:20).
  local oks,sky=false,nil
  if alive then oks,sky=pcall(M.lightning.sky,p.surface,p.position) end
  local okb,boiler_line=pcall(M.networks.boiler_line,p.force,p.surface.name)
  -- robots per planet from the kept network view (D4, Haiku 16:50)
  local okr,robots=pcall(M.networks.robot_lines,p.force)
  local okv,overdue=pcall(M.overdue_reviews,p)
  return {overdue_reviews=okv and overdue or nil,robots=okr and robots or nil,logistics_here=alive and (function() local ok,l=pcall(M.personal.here,p); return ok and l or nil end)() or nil,boilers=okb and boiler_line or nil,queues=scheduler.lanes(p.index),storm=oks and sky or nil,crafting=alive and crafting_line(p) or nil,retreat_guard=M.retreat_guard_line(p.index),inv=factory.inv,inventory=inv_line,factory=factory.factory,machines=factory.machines,machine_positions=factory.machine_positions,warnings=factory.warnings,factory_as_of=factory.as_of,factory_age_s=factory.age_s,factory_refresh_failed=factory.refresh_failed,survey_error=factory.error,
    evolution=threats.evolution,pollution=threats.pollution,enemies=threats.enemies,chart=threats.chart,threats_as_of=threats.as_of,
    alerts=alerts,runtime_fault=state().runtime_fault or false,connected=p.connected,alive=p.character and p.character.valid or false,cheat_mode=p.cheat_mode,
    supported_control=controllable,control_error=not controllable and tostring(control_error) or nil,active=now,order=M.orders.brief(p.index),
    spoiling=alive and spoil_text(main_inventory(p)) or nil,on_belt=alive and M.belt.note(p) or nil,teammates=M.where.team(p),
    trash=alive and M.trash.status(p) or nil,
    landed_pods=alive and (function() local ok,l=pcall(M.landed.status_lines,p); return ok and l or nil end)() or nil,
    alerts_new=M.alertdigest and (function() local ok,n=pcall(M.alertdigest.count,p); return ok and n>0 and string.format('%d place%s with enemy or structure news since your last alerts_digest read (alerts_digest {} lists them)',n,n==1 and '' or 's') or nil end)() or nil,
    surface=alive and p.surface.name or nil,platform=alive and p.surface.platform and p.surface.platform.name or nil,riding=p.driving or nil, last=state().last and state().last[p.index] or false, combat=M.combat_row(p.index,p), hurt=alive and M.hurt_row(p) or nil, flight=alive and M.flight_row(p) or nil, last_combat=state().last_combat and state().last_combat[p.index] or false, tick=game.tick, position=p.position}
end
end -- Connected visible resource tiles are summarized separately from structures so a
-- large ore patch cannot consume the entity budget and hide machines or enemies.
local function resource_patches(entities)
  local remaining, patches = {}, {}
  local function key(name,x,y) return name..':'..x..':'..y end
  for _,e in ipairs(entities) do remaining[key(e.name,math.floor(e.position.x),math.floor(e.position.y))]=e end
  for _,seed in ipairs(entities) do
    local sx,sy=math.floor(seed.position.x),math.floor(seed.position.y)
    if remaining[key(seed.name,sx,sy)] then
      local patch={name=seed.name,tiles=0,amount=0,left=sx,top=sy,right=sx+1,bottom=sy+1}
      local queue,head={{sx,sy,seed.amount or 0}},1
      remaining[key(seed.name,sx,sy)]=nil
      while head<=#queue do
        local cell=queue[head]; head=head+1
        local x,y=cell[1],cell[2]
        patch.tiles=patch.tiles+1
        patch.amount=patch.amount+cell[3]
        patch.left=math.min(patch.left,x); patch.top=math.min(patch.top,y)
        patch.right=math.max(patch.right,x+1); patch.bottom=math.max(patch.bottom,y+1)
        for _,d in ipairs({{1,0},{-1,0},{0,1},{0,-1}}) do
          local nx,ny=x+d[1],y+d[2]
          local k=key(seed.name,nx,ny); local e=remaining[k]
          if e then remaining[k]=nil; queue[#queue+1]={nx,ny,e.amount or 0} end
        end
      end
      patches[#patches+1]=patch
    end
  end
  return patches
end
-- Live map queries require current visibility. Merely explored chunks may be
-- fog-covered: reading their current entities would expose unseen expansions.
-- Historical map knowledge must come from previously observed snapshots.
function handlers.map(p,a)
  local radius=integer(a.radius,256,32,1024,'radius')
  local want={resources=a.resources~=false,water=a.water~=false,enemies=a.enemies~=false}
  local surface,force=p.surface,p.force
  local origin=center(p,a)
  local cx0,cy0=math.floor(origin.x/32),math.floor(origin.y/32)
  local r=math.ceil(radius/32)
  local cells={}
  local function add(kind,name,cx,cy,count,amount,box)
    local k=name..':'..cx..':'..cy
    local c=cells[k] or {kind=kind,name=name,cx=cx,cy=cy,count=0,amount=0,left=box.left,top=box.top,right=box.right,bottom=box.bottom}
    cells[k]=c
    c.count=c.count+count; c.amount=c.amount+(amount or 0)
    c.left=math.min(c.left,box.left); c.top=math.min(c.top,box.top); c.right=math.max(c.right,box.right); c.bottom=math.max(c.bottom,box.bottom)
  end
  -- Water by what a character can do there (M.water_kind): lava apart, and walkable water apart from water it cannot cross.
  local water_names,walk_names,lava_names={},{},{}
  for name in pairs(prototypes.tile) do
    local kind=M.water_kind(name)
    if kind then water_names[#water_names+1]=name end
    if kind=='walkable' then walk_names[#walk_names+1]=name elseif kind=='lava' then lava_names[#lava_names+1]=name end
  end
  for cx=cx0-r,cx0+r do
    for cy=cy0-r,cy0+r do
      -- The player's map keeps charted ore, water and enemy bases drawn under
      -- fog of war, so charted (not currently visible) is the fair boundary.
      if force.is_chunk_charted(surface,{x=cx,y=cy}) then
        local area={{cx*32,cy*32},{cx*32+32,cy*32+32}}
        if want.resources then
          for _,e in pairs(surface.find_entities_filtered{area=area,type='resource'}) do
            local x,y=math.floor(e.position.x),math.floor(e.position.y)
            if math.floor(x/32)==cx and math.floor(y/32)==cy then
              add('resource',e.name,cx,cy,1,e.amount,{left=x,top=y,right=x+1,bottom=y+1})
            end
          end
        end
        if want.water and #water_names>0 then
          local n=surface.count_tiles_filtered{area=area,name=water_names}
          if n>0 then
            local box={left=cx*32,top=cy*32,right=cx*32+32,bottom=cy*32+32}
            local walk=#walk_names>0 and surface.count_tiles_filtered{area=area,name=walk_names} or 0
            local lava=#lava_names>0 and walk<n and surface.count_tiles_filtered{area=area,name=lava_names} or 0
            if n-walk-lava>0 then add('water','water',cx,cy,n-walk-lava,0,box) end
            if walk>0 then add('water','walkable water',cx,cy,walk,0,box) end
            if lava>0 then add('lava','lava',cx,cy,lava,0,box) end
          end
        end
        for _,kind in ipairs({'tree','rock'}) do
          if a[kind..'s'] then
            local filter=kind=='tree' and {area=area,type=(script and script.active_mods['space-age']) and {'tree','plant'} or 'tree'} or {area=area,type='simple-entity'}
            for _,e in pairs(surface.find_entities_filtered(filter)) do
              local x,y=math.floor(e.position.x),math.floor(e.position.y)
              if math.floor(x/32)==cx and math.floor(y/32)==cy and (kind=='tree' or e.name:find('rock')) then
                add(kind,kind..'s',cx,cy,1,0,{left=x,top=y,right=x+1,bottom=y+1})
              end
            end
          end
        end
        if want.enemies then
          for _,e in pairs(surface.find_entities_filtered{area=area,type={'unit-spawner','turret'},force='enemy'}) do
            local x,y=math.floor(e.position.x),math.floor(e.position.y)
            -- Area searches include overlapping collision boxes. Attribute an
            -- entity only to its center's chunk, never an adjacent hidden one.
            if math.floor(x/32)==cx and math.floor(y/32)==cy then
              add('enemy','enemy-base',cx,cy,1,0,{left=x,top=y,right=x+1,bottom=y+1})
            end
          end
        end
      end
    end
  end
  local regions={}
  local seen={}
  -- Trees and rocks are scattered everywhere: report per-chunk density
  -- (at least min_count) instead of merging them into one huge region.
  local min_count=integer(a.min_count,1,1,1024,'min_count')
  for k,c in pairs(cells) do
    if (c.kind=='tree' or c.kind=='rock') and not seen[k] then
      seen[k]=true
      if c.count>=min_count then
        local mid={x=c.cx*32+16,y=c.cy*32+16}
        regions[#regions+1]={kind=c.kind,name=c.name,count=c.count,left=c.left,top=c.top,right=c.right,bottom=c.bottom,center=mid,distance=math.floor(distance(origin,mid))}
      end
    end
  end
  for k,c in pairs(cells) do
    if not seen[k] then
      seen[k]=true
      local region={kind=c.kind,name=c.name,count=0,amount=0,left=c.left,top=c.top,right=c.right,bottom=c.bottom}
      local queue,head={c},1
      while head<=#queue do
        local cell=queue[head]; head=head+1
        region.count=region.count+cell.count; region.amount=region.amount+cell.amount
        region.left=math.min(region.left,cell.left); region.top=math.min(region.top,cell.top)
        region.right=math.max(region.right,cell.right); region.bottom=math.max(region.bottom,cell.bottom)
        for dx=-1,1 do for dy=-1,1 do
          local nk=c.name..':'..(cell.cx+dx)..':'..(cell.cy+dy)
          if cells[nk] and not seen[nk] then seen[nk]=true; queue[#queue+1]=cells[nk] end
        end end
      end
      region.center={x=math.floor((region.left+region.right)/2),y=math.floor((region.top+region.bottom)/2)}
      region.distance=math.floor(distance(origin,region.center))
      if region.kind~='resource' then region.amount=nil end
      regions[#regions+1]=region
    end
  end
  table.sort(regions,function(x,y) return x.distance<y.distance end)
  local limit=integer(a.limit,48,1,256,'limit')
  local out={regions={},truncated=#regions>limit,radius=radius,
    scope='charted chunks (as drawn on the player map); bounds may include gaps; count is tiles (water, ore) or structures (enemy); water: tiles a character cannot cross; walkable water: water tiles a character walks through (shallow water, wetland, oil ocean)'}
  for i=1,math.min(limit,#regions) do out.regions[i]=regions[i] end
  return out
end
-- A name filter the engine does not know ("Unknown entity name: tree",
-- shake4): list the entity names holding every dash-separated part of it
-- ("rock-huge" finds huge-rock), and say when it is an entity type.
-- An entity type the game does not know gives no error, only nothing found (Astra, shift12 15:10: type
-- electric-mining-drill, an entity name, scanned empty and nine drills looked lost): each type is checked first.
function M.entity_types(fresh)
  if fresh or not M.ENTITY_TYPES then
    local ok,list=pcall(function() return prototypes.entity end)
    if not (ok and list) then return nil end
    local t={}
    for _,proto in pairs(list) do if proto.type then t[proto.type]=true end end
    M.ENTITY_TYPES=t
  end
  return M.ENTITY_TYPES
end
-- Whether the game knows an entity type (read again once before saying no: the list is kept from the first read).
function M.known_type(t)
  local types=M.entity_types()
  if not types or types[t] then return true end
  types=M.entity_types(true)
  return types and types[t] or false
end
-- The refusal for a type the game does not know: what the value names instead, else the types like it.
function M.unknown_type(bad)
  local types=M.entity_types()
  local proto=prototypes.entity[bad]
  if proto then
    return string.format('unknown entity type %s: it is an entity name (its type is %s): name %s, or type %s',bad,proto.type,bad,proto.type)
  end
  local item=prototypes.item[bad]
  local placed=item and item.place_result
  if placed then
    return string.format('unknown entity type %s: it is an item, which places %s (type %s): name %s, or type %s',bad,placed.name,placed.type,placed.name,placed.type)
  end
  local words={}
  for w in bad:lower():gmatch('[^%-_%s]+') do words[#words+1]=(#w>3 and w:sub(-1)=='s') and w:sub(1,-2) or w end
  local like={}
  for t in pairs(types or {}) do
    local all=#words>0
    for _,w in ipairs(words) do if not t:find(w,1,true) then all=false; break end end
    if all then like[#like+1]=t end
  end
  table.sort(like)
  local shown={}
  for i=1,math.min(#like,8) do shown[i]=like[i] end
  return string.format('unknown entity type %s%s',bad,#like>0 and '; types like it: '..table.concat(shown,', ')..(#like>8 and string.format(' (+%d more)',#like-8) or '')
    or '; types are names such as assembling-machine, furnace, mining-drill, inserter, transport-belt, container')
end
function M.find_named(surface,filter)
  if filter.type~=nil then
    for _,t in ipairs(type(filter.type)=='table' and filter.type or {filter.type}) do
      if type(t)~='string' then error('type must be an entity type name (a string)',0) end
      if not M.known_type(t) then error(M.unknown_type(t),0) end
    end
  end
  local ok,found=pcall(surface.find_entities_filtered,filter)
  if ok then return found end
  local bad=tostring(found):match('[Uu]nknown entity name:? *([%w%-_]+)')
  if not bad then error(found,0) end
  local parts,matches,is_type={},{},false
  for part in bad:lower():gmatch('[^%-_]+') do parts[#parts+1]=part end
  for name,proto in pairs(prototypes.entity) do
    if proto.type==bad then is_type=true end
    local all=true
    for _,part in ipairs(parts) do if not name:find(part,1,true) then all=false end end
    if all then matches[#matches+1]=name end
  end
  table.sort(matches)
  local shown={}
  for i=1,math.min(#matches,12) do shown[i]=matches[i] end
  error(bad..' is not an entity name'..(#matches>0 and '; matching names: '..table.concat(shown,', ')..(#matches>12 and ' ('..#matches..' in all)' or '') or '')
    ..(is_type and '; '..bad..' is an entity type: filter with type instead' or ''),0)
end
-- Cheap targeting: the nearest matches around the player or any charted
-- position, limited to what the player's map shows.
function handlers.nearest(p,a)
  assert(a.name or a.type,'name or type is required')
  for _,key in ipairs({'name','type'}) do
    local v=a[key]
    assert(v==nil or type(v)=='string' or (type(v)=='table' and #v>=1 and #v<=32),key..' must be a string or 1..32 strings')
  end
  local radius=integer(a.radius,32,1,128,'radius')
  local limit=integer(a.limit,5,1,64,'limit')
  local origin,rows=center(p,a),{}
  for _,e in pairs(M.find_named(p.surface,{position=origin,radius=radius,name=a.name,type=a.type})) do
    if e.valid and e~=p.character and known(p,e) then rows[#rows+1]={entity=e,distance=distance(origin,e.position)} end
  end
  table.sort(rows,function(x,y)
    if x.distance~=y.distance then return x.distance<y.distance end
    local u,v=x.entity.position,y.entity.position
    if u.x~=v.x then return u.x<v.x end
    return u.y<v.y
  end)
  -- A single requested name is implied; otherwise each row names its entity.
  local named=not (type(a.name)=='string' or (type(a.name)=='table' and #a.name==1))
  local out={entities={},total=#rows}
  for i=1,math.min(limit,#rows) do
    local e=rows[i].entity
    -- An ore tile: what is left in it now (Sonnet, shift11: the ores survey can be minutes old).
    out.entities[i]={name=named and e.name or nil,position=e.position,distance=math.floor(rows[i].distance*10+0.5)/10,
      amount=e.type=='resource' and e.amount or nil}
  end
  -- Only charted ground is searched. Just after landing on a new planet that
  -- is the ~48 tiles a character sees (live on sa: Vulcanus coal was 90 out).
  if #rows==0 then out.note='nothing map-known within '..radius..' tiles; only charted chunks count, and on a new planet that is about 48 tiles around you: walk out to explore (map shows what is charted), or build a radar' end
  return out
end
local function stacks_text(list)
  local parts={}
  for _,s in ipairs(list) do parts[#parts+1]=s.name..(s.quality and s.quality~='normal' and '@'..s.quality or '')..'*'..s.count end
  return #parts>0 and table.concat(parts,' ') or 'empty'
end
-- The character's inventory on its own (shake2: `call inventory` failed 15 times; Gemini, 06:20: held items
-- "without the overhead of full observe"): main, guns, ammo, armor with its equipment grid, trash slots and the
-- cursor as short item lines (name*count, name@quality*count), free slots and hand crafting, in one small reply.
-- full=true: the stacks as lists {name, quality, count}, as observe's player has them.
function M.character_inventory(p,full)
  local function inv(i) local ok,x=pcall(p.get_inventory,i); return ok and x or nil end
  local function list(x) return x and contents(x) or {} end
  local function text(x) return stacks_text(list(x)) end
  local armor=inv(defines.inventory.character_armor)
  local grid
  pcall(function() local st=armor and armor[1]; if st and st.valid_for_read and st.grid then grid=st.grid.get_contents() end end)
  local trash=defines.inventory.character_trash and inv(defines.inventory.character_trash)
  local cursor
  pcall(function()
    local st=p.cursor_stack
    if st and st.valid_for_read then cursor=stacks_text({{name=st.name,count=st.count,quality=st.quality and st.quality.name}})
    elseif p.cursor_ghost then
      local g=p.cursor_ghost
      local name=type(g.name)=='string' and g.name or g.name and g.name.name
      if name then cursor='ghost of '..name end
    end
  end)
  local free,warnings=survey.inventory(p)
  local out={free=free,crafting=crafting_line(p),warnings=warnings and #warnings>0 and warnings or nil,cursor=cursor}
  if full then
    out.inventory=contents(p.get_main_inventory()); out.guns=list(inv(defines.inventory.character_guns))
    out.ammo=list(inv(defines.inventory.character_ammo)); out.armor=list(armor); out.equipment=grid or nil
    out.trash=trash and #list(trash)>0 and list(trash) or nil
    return out
  end
  out.inventory=stacks_text(contents(p.get_main_inventory())); out.guns=text(inv(defines.inventory.character_guns))
  out.ammo=text(inv(defines.inventory.character_ammo)); out.armor=text(armor)
  -- Per slot (Grok, shift19 00:36: a pistol in gun slot 1, its ammo in ammo slot 2): gun slot N fires from ammo slot N.
  local okr,r=pcall(M.ammoslots.read,p)
  if okr and r.n>0 and (out.guns~='empty' or out.ammo~='empty') then
    local g,am=M.ammoslots.lines(r)
    local sel=p.character and p.character.valid and p.character.selected_gun_index
    out.guns=sel and (g..' (selected: '..sel..')') or g
    out.ammo=am
    out.ammo_idle=M.ammoslots.idle_ammo(r)
  end
  out.equipment=grid and #grid>0 and stacks_text(grid) or nil
  local t=trash and list(trash)
  out.trash=t and #t>0 and stacks_text(t) or nil
  return out
end
-- (d17 batch34 C5, Grok: a full inventory hid the egg hatch times and he walked off gun cover with about a minute left)
-- each spoilable stack of an inventory, soonest first: its slot, spoil percent and time left; an item that triggers
-- when it spoils (a pentapod egg hatches) reads hatches in. {lines, more} or nil.
function M.spoil_stacks(inv,limit)
  local rows={}
  for i=1,inv and inv.valid and #inv or 0 do
    local s=inv[i]
    if s.valid_for_read then
      local ok,t=pcall(function() return s.prototype.get_spoil_ticks(s.quality)>0 and s.spoil_tick end)
      if ok and t and t>0 then
        local hatch=(pcall(function() return s.prototype.spoil_to_trigger_result end)) and s.prototype.spoil_to_trigger_result~=nil
        local q=s.quality and s.quality.name~='normal' and '@'..s.quality.name or ''
        rows[#rows+1]={key=s.name..q,count=s.count,slot=i,left=math.max(0,t-game.tick),pct=(pcall(function() return s.spoil_percent end)) and s.spoil_percent or 0,hatch=hatch}
      end
    end
  end
  if #rows==0 then return nil end
  table.sort(rows,function(x,y) if x.left~=y.left then return x.left<y.left end return x.slot<y.slot end)
  local lines={}
  for i=1,math.min(#rows,limit or 24) do
    local r=rows[i]
    local sec=math.floor(r.left/60)
    lines[i]=string.format('%s*%d (slot %d): %s in %dm%02ds (%d%% spoiled)',r.key,r.count,r.slot,r.hatch and 'hatches' or 'spoils',math.floor(sec/60),sec%60,math.floor(r.pct*100))
  end
  return {lines=lines,more=#rows>(limit or 24) and #rows-(limit or 24) or nil}
end
function handlers.inventory(p,a)
  assert(a==nil or a.full==nil or type(a.full)=='boolean','full must be true or false')
  local out=M.character_inventory(p,a and a.full==true)
  -- Items that carry a grid (an equipped spidertron's or tank's item, a spare armor), with what each grid holds.
  local okg,ig=pcall(M.grids.item_grids,p.get_main_inventory())
  out.item_grids=okg and ig or nil
  local oks,sp=pcall(M.spoil_stacks,p.get_main_inventory(),24)
  if oks and sp then out.spoiling,out.spoiling_more=sp.lines,sp.more end
  return out
end
-- status {inventory=true}: the same in one line.
function M.inventory_line(p)
  local v=M.character_inventory(p,false)
  local parts={'main '..v.inventory..' ('..tostring(v.free)..')'}
  if v.ammo~='empty' then parts[#parts+1]='ammo '..v.ammo end
  if v.guns~='empty' then parts[#parts+1]='guns '..v.guns end
  if v.ammo_idle then parts[#parts+1]=table.concat(v.ammo_idle,'; ') end
  if v.armor~='empty' then parts[#parts+1]='armor '..v.armor..(v.equipment and ' with '..v.equipment or '') end
  if v.trash then parts[#parts+1]='trash '..v.trash end
  if v.cursor then parts[#parts+1]='cursor '..v.cursor end
  return table.concat(parts,'; ')
end
local function fuel_inventory(e) local ok,inv=pcall(e.get_fuel_inventory); return ok and inv or nil end
-- Belt lanes (left|right, in flow direction), 'L: items | R: items'; nil for what has no transport line.
function M.lanes_text(e)
  local ok,n=pcall(e.get_max_transport_line_index)
  if not ok or not n or n<1 then return nil end
  local parts={}
  for i=1,n do parts[#parts+1]=(n==2 and (i==1 and 'L' or 'R') or tostring(i))..': '..stacks_text(e.get_transport_line(i).get_contents()) end
  return table.concat(parts,' | ')
end
-- (d23 batch123 CF4) the take-order inventory names (fuel aside) an entity type takes, as inventory() reads them
M.SCAN_INV={}
function M.scan_inventories(e)
  local t=e.type
  local list=M.SCAN_INV[t]
  if list then return list end
  list={}
  for _,name in ipairs(take_order) do
    local real=name~='fuel' and M.inventory_name(e,name)
    local allowed=real and inventories[real]
    if allowed and defines.inventory[real] then
      for _,kind in ipairs(allowed) do if kind==t then list[#list+1]=real; break end end
    end
  end
  M.SCAN_INV[t]=list
  return list
end
-- Opt-in per-entity columns; each is a short string or number.
local scan_fields={
  hp=function(e) return e.health and e.max_health and e.max_health>0 and math.floor(e.health+0.5)..'/'..math.floor(e.max_health+0.5) or nil end,
  fuel=function(e) local inv=fuel_inventory(e); return inv and stacks_text(inv.get_contents()) or nil end,
  inventory=function(e)
    if M.robotread.ROBOT[e.type] then return M.robotread.holds(e) end  -- (d20 batch70 AF4) a robot's cargo
    if e.type=='item-entity' then return M.groundstack.text(M.groundstack.stack(e)) end  -- (d22 batch78 AN1) its stack
    local all,any={},false
    -- (d23 batch123 CF4) only the inventories its type takes, in take order: the same reads without a refused pcall
    -- for each of the other names (Asterion's 669-belt band: 29 refusals a belt)
    for _,name in ipairs(M.scan_inventories(e)) do
      local ok,inv=pcall(e.get_inventory,defines.inventory[name])
      if ok and inv and inv.valid then any=true; for _,s in ipairs(inv.get_contents()) do all[#all+1]=s end end
    end
    -- (d17 batch14 A10, Astra: tracing Meridian's western rocket feed took an inspect per belt) a belt's items per lane
    if not any then return M.lanes_text(e) end
    return stacks_text(all)
  end,
  output=function(e) local ok,inv=pcall(e.get_output_inventory); return ok and inv and stacks_text(inv.get_contents()) or nil end,
  spoil=function(e)
    if e.type=='item-entity' then return M.groundstack.spoil_text(M.groundstack.stack(e)) end  -- (AN1) its stack
    local parts={}
    for _,name in ipairs(take_order) do
      local ok,inv=false,nil
      if name~='fuel' then ok,inv=pcall(inventory,e,name) else ok,inv=true,fuel_inventory(e) end
      local text=ok and spoil_text(inv,4)
      if text then parts[#parts+1]=text end
    end
    return #parts>0 and table.concat(parts,' | ') or nil
  end,
  status=function(e) return M.machine_status(e) end,
  recipe=function(e) local ok,r=pcall(e.get_recipe); return ok and r and r.name or nil end,
  direction=function(e) return e.supports_direction and e.direction or nil end,
  amount=function(e) return e.type=='resource' and e.amount or nil end,
  -- Attack range from the prototype (turrets, worms, units); spawners have none.
  range=function(e)
    local proto=e.prototype
    local ok,r=pcall(function() return proto.turret_range or (proto.attack_parameters and proto.attack_parameters.range) end)
    return ok and r or nil
  end,
  ammo=function(e)
    local name=ammo_inventory[e.type] or (e.type=='car' and 'car_ammo') or (e.type=='spider-vehicle' and 'spider_ammo')
    local ok,inv=false,nil
    if name then ok,inv=pcall(inventory,e,name) end
    return ok and stacks_text(inv.get_contents()) or nil
  end,
  -- Belt lanes (left|right, in flow direction); splitters and undergrounds
  -- have more transport lines, listed in engine order.
  lanes=function(e) return M.lanes_text(e) end,
  -- Inserter pickup and drop positions with the entity found at each.
  io=function(e)
    if e.type~='inserter' and e.type~='mining-drill' then return nil end
    local function at(pos)
      local target=e.surface.find_entities_filtered{position=pos,limit=1,type={'resource','character','corpse','character-corpse','item-entity','item-request-proxy','sticker','fire','smoke-with-trigger','projectile','entity-ghost','tile-ghost'},invert=true}[1]
      return string.format('%g,%g',pos.x,pos.y)..(target and ' '..target.name or '')
    end
    -- A drill only drops (onto the ground when nothing is there).
    if e.type=='mining-drill' then return '-> '..at(e.drop_position) end
    -- An inserter: a side with no target says so (the engine's pickup and drop targets).
    local ok,pick,drop=pcall(function() return e.pickup_target,e.drop_target end)
    return at(e.pickup_position)..((ok and not pick) and ' (no pickup target)' or '')..' -> '..at(e.drop_position)..((ok and not drop) and ' (no drop target)' or '')
  end,
  -- Fluidboxes with contents and where each pipe connection leads.
  fluids=function(e) return pipes.fluids(e) end,
  -- Item filters (inserters, loaders): whitelist|blacklist: items, off, set by circuit; none without.
  filters=function(e)
    local ok,line=pcall(M.details.filters_line,e)
    if ok and line then return line end
    local slots=(pcall(function() return e.filter_slot_count end)) and e.filter_slot_count or 0
    return slots>0 and 'none' or nil
  end,
  target=function(e)
    local ok,t=pcall(function() return e.shooting_target end)
    return ok and t and t.valid and t.name..'@'..math.floor(t.position.x+0.5)..','..math.floor(t.position.y+0.5) or nil
  end,
}
-- Fields that change over time; hidden for other forces' entities under fog.
do local live_fields={hp=true,fuel=true,inventory=true,output=true,spoil=true,status=true,ammo=true,target=true,amount=true,lanes=true,fluids=true,filters=true}
-- Ore letters are stable per name within one reply: the first unused letter
-- of the name, upper-cased.
local function ore_letters(names)
  local legend,used={},{['#']=true,['~']=true,['.']=true}
  table.sort(names)
  for _,name in ipairs(names) do
    for ch in (name:upper()..'ABCDEFGHIJKLMNOPQRSTUVWXYZ'):gmatch('%u') do
      if not used[ch] then used[ch]=true; legend[name]=ch; break end
    end
  end
  return legend
end
-- One compact row per entity plus optional ore layout, over a radius around
-- any charted position or an explicit area (<=128x128).
-- An explicit area up to 128x128, or a square around a charted centre.
local function view_area(p,a)
  if a.area then
    assert(type(a.area)=='table','area requires left_top and right_bottom')
    local lt,rb=position(a.area.left_top),position(a.area.right_bottom)
    assert(rb.x>lt.x and rb.y>lt.y and rb.x-lt.x<=128 and rb.y-lt.y<=128,'area must be nonempty and at most 128x128')
    return {left_top=lt,right_bottom=rb}
  end
  local c,r=center(p,a),integer(a.radius,16,1,64,'radius')
  return {left_top={x=c.x-r,y=c.y-r},right_bottom={x=c.x+r,y=c.y+r}}
end
M.SCAN_BELT={['transport-belt']=true,['underground-belt']=true,splitter=true,['lane-splitter']=true,loader=true,['loader-1x1']=true,['linked-belt']=true}
M.SCAN_PAGE=256  -- (d23 batch123 CF4) rows a call; page continues
M.SCAN_BELTS,M.SCAN_HOLDING=1024,64  -- about 6 us a belt read on world n (512 on Kestrel II: 3.1 ms)
-- A fluid entity's fluid as its segment holds it (scan rows, pipe_gaps cuts): the most of it in the segment, else what
-- its first box holds, else its locked fluid or filter; 'empty' when none.
function M.pipe_fluid(e)
  local fb=e.fluidbox
  local okc,contents=pcall(function() return fb.get_fluid_segment_contents(1) end)
  local best,amount
  for name,n in pairs(okc and contents or {}) do if not amount or n>amount then best,amount=name,n end end
  if best then return best end
  local okb,f=pcall(function() return fb[1] end)
  if okb and f and f.name then return f.name end
  local okl,lf=pcall(function() return fb.get_locked_fluid(1) end)
  if okl and lf then return (type(lf)=='string' and lf or lf.name)..' (locked, empty)' end
  local okf,flt=pcall(function() return fb.get_filter(1) end)
  if okf and flt and flt.name then return flt.name..' (filter, empty)' end
  return 'empty'
end
function handlers.scan(p,a)
  local area=a.positions==nil and view_area(p,a) or nil
  for _,key in ipairs({'name','type','fields'}) do
    local v=a[key]
    assert(v==nil or type(v)=='string' or (type(v)=='table' and #v<=32),key..' must be a string or up to 32 strings')
  end
  -- "hp|fuel" or "hp,fuel" as one string, as describe's example reads (61% of
  -- unknown-field errors copied it whole): each name a field.
  local fields={}
  for _,v in ipairs(type(a.fields)=='string' and {a.fields} or a.fields or {}) do
    for f in tostring(v):gmatch('[^|,%s]+') do fields[#fields+1]=f end
  end
  for _,f in ipairs(fields) do assert(scan_fields[f],'unknown field '..tostring(f)..'; use hp|fuel|inventory|output|spoil|status|recipe|direction|amount|range|ammo|target|lanes|io|fluids|filters') end
  local limit=integer(a.limit,256,1,1024,'limit')
  local filtered=a.name~=nil or a.type~=nil
  local out={entities={},truncated=false}
  local rows,ores,blocked={}, {}, {}
  local candidates
  if a.positions~=nil then
    assert(a.area==nil and a.position==nil and a.radius==nil and a.ore==nil,'positions replaces area, position, radius and ore')
    assert(type(a.positions)=='table' and #a.positions>=1 and #a.positions<=64,'positions requires 1..64 {x,y}')
    candidates={}
    local seen={}
    for _,raw in ipairs(a.positions) do
      local pos=position(raw)
      for _,e in pairs(M.find_named(p.surface,{position=pos,radius=0.3,name=a.name,type=a.type})) do
        if not seen[e] then seen[e]=true; candidates[#candidates+1]=e end
      end
    end
  else candidates=M.find_named(p.surface,{area=area,name=a.name,type=a.type}) end
  -- Items on the ground: a summary by item unless the caller filtered for
  -- them (a spill of thousands of stacks would push every building out).
  local ground={}
  -- Our own buildings and belts in a chunk out of sight come from what our force last saw (fog below, fogmem.lua; Nick
  -- d17 17:28), not from what stands there now; our ghosts there are read as they are (the map draws them in fog).
  -- fog_strict off (the default): read as before, and what they are goes in present, so fog lists only the remembered
  -- ones no longer there.
  local strict,present=M.fogmem.strict(),{}
  -- (d23 batch123 CF4, Sol's Asterion bands at 17:17: 697 candidates, 70 ms with limit 1 on a copy) the caller's force,
  -- surface, platform and character read once: with platform= the caller is a remote-view stand-in, and each read went
  -- through it; known() and hidden_own() as before, with those.
  local pforce,psurface,pchar=p.force,p.surface,p.character
  local own=own_platform(p)
  local function known_here(e,pos)
    local chunk=chunk_of(pos)
    if own or pforce.is_chunk_visible(psurface,chunk) then return true end
    if not pforce.is_chunk_charted(psurface,chunk) then return false end
    local f=e.force
    return f==pforce or (f.name=='neutral' and e.type~='unit') or drawn_enemy[e.type]==true
  end
  local function hidden_own(e,pos)
    if own then return false end
    local t=e.type
    return e.force==pforce and t~='entity-ghost' and t~='tile-ghost' and t~='character' and not pforce.is_chunk_visible(psurface,chunk_of(pos))
  end
  for _,e in pairs(candidates) do
    local pos=e.valid and e~=pchar and e.position
    local kn=pos and known_here(e,pos)
    local hidden=kn and hidden_own(e,pos)
    if hidden and not strict then present[e.name..'@'..pos.x..','..pos.y]=true end
    if hidden and strict then -- out of sight: from the memory (fog below)
    elseif kn then
      local t=e.type
      if t=='resource' and a.ore then ores[#ores+1]=e end
      -- (d22 batch78 AN1, Astra #1809) asked for by name or type, ground items are rows too, and summed before the limit
      if t=='item-entity' then ground[#ground+1]=e end
      if (t~='item-entity' or filtered) and (t~='resource' or filtered) then rows[#rows+1]=e end
    end
  end
  out.ground_items=M.ground.summary(ground)
  -- (d17 batch31 C1, Sol: 10 rockets stranded among 214 belts on Kestrel III, found by paging) the belts found, all of
  -- them before the limit (up to M.SCAN_BELTS): what they carry by item, and with item each belt holding it.
  local item=a.item
  if item~=nil then assert(type(item)=='string' and prototypes.item[item],'item is an item name: the belts holding it') end
  local belt_types=false
  for _,t in ipairs(type(a.type)=='table' and a.type or {a.type}) do if M.SCAN_BELT[t] then belt_types=true end end
  if item~=nil or belt_types then
    local by,belts,holding,cut={},0,{},false
    for _,e in ipairs(rows) do
      if M.SCAN_BELT[e.type] and e.force==p.force then
        if belts>=M.SCAN_BELTS then cut=true; break end
        belts=belts+1
        local here=0
        for li=1,(select(2,pcall(function() return e.get_max_transport_line_index() end)) or 0) do
          local okc,list=pcall(function() return e.get_transport_line(li).get_contents() end)
          for _,c in ipairs(okc and list or {}) do
            by[c.name]=(by[c.name] or 0)+c.count
            if c.name==item then here=here+c.count end
          end
        end
        if here>0 then holding[#holding+1]={x=e.position.x,y=e.position.y,name=e.name,count=here} end
      end
    end
    local list={}
    for n,c in pairs(by) do list[#list+1]={n,c} end
    table.sort(list,function(x,y) return x[2]>y[2] or x[2]==y[2] and x[1]<y[1] end)
    for i,v in ipairs(list) do list[i]=v[1]..'*'..v[2] end
    out.belt_items=string.format('%d belts%s carry %s',belts,cut and string.format(' (the first %d)',M.SCAN_BELTS) or '',#list>0 and table.concat(list,' ') or 'nothing')
    if item~=nil then
      table.sort(holding,function(x,y) if x.y~=y.y then return x.y<y.y end return x.x<y.x end)
      local n=0
      for _,h in ipairs(holding) do n=n+h.count end
      local shown={}
      for i=1,math.min(#holding,M.SCAN_HOLDING) do shown[i]=holding[i] end
      out.belt_item={item=item,count=n,belts=#holding,positions=shown,more=#holding>M.SCAN_HOLDING and #holding-M.SCAN_HOLDING or nil,
        line=string.format('%d %s on %d of %d belts%s',n,item,#holding,belts,#holding>0 and ': '..table.concat((function()
          local t={} for i=1,math.min(#holding,12) do local h=holding[i]; t[i]=string.format('(%g,%g) %d',h.x,h.y,h.count) end return t end)(),', ')..(#holding>12 and ', ...' or '') or '')}
    end
  end
  -- More than limit: the ones nearest the scan's centre (the position given, the character, or the area's middle), as
  -- observe keeps them; listed in reading order still. Rows were cut from the top before (Muse, 6 times this shift: a
  -- radius 25 scan at (-20,84) held 507 and listed y 59..72, none at the character's feet).
  local total=#rows
  -- (d23 batch123 CF4) each row's position and name read once: the sorts read them about 20 times a row (Asterion's
  -- 697-row band)
  local at_pos,at_name={},{}
  for _,e in ipairs(rows) do at_pos[e]=e.position; at_name[e]=e.name end
  if #rows>limit then
    local c=area and {x=(area.left_top.x+area.right_bottom.x)/2,y=(area.left_top.y+area.right_bottom.y)/2} or p.position
    local dist={}
    for _,e in ipairs(rows) do dist[e]=distance(c,at_pos[e]) end
    table.sort(rows,function(x,y)
      local dx,dy=dist[x],dist[y]
      if dx~=dy then return dx<dy end
      return at_name[x]<at_name[y]
    end)
    local within=dist[rows[limit]]
    for i=#rows,limit+1,-1 do rows[i]=nil end
    out.truncated=true
    out.kept_nearest={centre={x=c.x,y=c.y},within=math.floor(within*10+0.5)/10,
      note=string.format('kept the %d nearest (%g,%g), within %.1f tiles; a smaller radius, a name or type filter, or limit up to 1024 shows the rest',
        limit,c.x,c.y,within)}
  end
  table.sort(rows,function(x,y)
    local u,v=at_pos[x],at_pos[y]
    if u.y~=v.y then return u.y<v.y end
    if u.x~=v.x then return u.x<v.x end
    return at_name[x]<at_name[y]
  end)
  -- (d20 batch70 AF4, Astra #1718: robots at one spot read alike) rows at one position carry their unit numbers
  local at_count={}
  for _,e in ipairs(rows) do local q=at_pos[e]; local k=q.x..','..q.y; at_count[k]=(at_count[k] or 0)+1 end
  -- (d23 batch123 CF4, operator 10:25: Sol's 16-tile bands of Asterion at limit 1024, 96 ms a call on world n, the worst
  -- game second 670 ms from 4) at most SCAN_PAGE rows a call, in reading order; page continues them (more says how)
  local kept=#rows
  local pages=math.max(1,math.ceil(kept/M.SCAN_PAGE))
  local page=integer(a.page,1,1,math.ceil(1024/M.SCAN_PAGE),'page')
  assert(page<=pages,string.format('page %d: this scan keeps %d rows, %d page%s of %d',page,kept,pages,pages==1 and '' or 's',M.SCAN_PAGE))
  local from,upto=(page-1)*M.SCAN_PAGE+1,math.min(kept,page*M.SCAN_PAGE)
  if pages>1 then
    out.page,out.pages=page,pages
    out.rows=string.format('%d..%d of %d',from,upto,kept)
    if page<pages then
      out.more={rows=kept-upto,next={page=page+1},line=string.format('rows %d..%d of the %d kept are listed (%d a call, reading order); page %d lists the next, the same arguments otherwise',
        from,upto,kept,M.SCAN_PAGE,page+1)}
    end
  end
  for k=from,upto do
    local e=rows[k]
    local q=at_pos[e]
    local etype,ours=e.type,e.force==pforce  -- (CF4) read once a row
    local row={name=at_name[e],position=q,quality=M.quality_name(e)}
    if at_count[q.x..','..q.y]>1 then row.unit_number=e.unit_number end
    -- (AF5, Astra 18:33: 7 robot rows with no unit_number and only inventory text) every robot: unit_number, cargo
    if M.robotread.ROBOT[etype] then row.unit_number=e.unit_number; row.cargo=M.robotread.cargo(e) end
    if etype=='item-entity' then row.stack=M.groundstack.stack(e) end  -- (AN1) the stack as hovering shows
    if etype=='entity-ghost' or etype=='tile-ghost' then row.ghost_name=e.ghost_name; row.ghost_type=e.ghost_type end
    local live=ours or pforce.is_chunk_visible(psurface,chunk_of(q))
    for _,f in ipairs(fields) do if live or not live_fields[f] then row[f]=scan_fields[f](e) end end
    -- A pole of ours says its electric network and where its copper wires go, unasked (round2120a, Opus: a cut found
    -- only by walking 400 tiles of poles).
    if etype=='electric-pole' and ours then
      local okn,id=pcall(function() return e.electric_network_id end)
      row.network=okn and id or nil
      local okw,line=pcall(M.powercut.copper_line,e)
      row.wires=okw and line or nil
    end
    -- A cargo pod container (a pod landed without a pad) says what it holds unasked, at the position it stands on
    -- (Sonnet, shift14 22:50: the landing line's rounded spot sent a transfer a tile off).
    if at_name[e]=='cargo-pod-container' then
      local okc,list=pcall(function() return e.get_inventory(defines.inventory.chest).get_contents() end)
      if okc and list then
        local parts={}
        for i,s in ipairs(list) do if i<=8 then parts[#parts+1]=s.name..'*'..s.count end end
        row.holds=#parts>0 and table.concat(parts,' ')..(#list>8 and string.format(' +%d more',#list-8) or '') or 'nothing'
      end
    end
    -- (d18 batch39 D1, Opus: ~15 min in a dense oil block) a pipe, pipe-to-ground, tank or pump of ours names its
    -- segment's fluid unasked: the most of it in the segment, else the box's, its locked fluid or its filter; empty
    if row.fluid==nil and ours and (etype=='pipe' or etype=='pipe-to-ground' or etype=='storage-tank' or etype=='pump') then
      row.fluid=M.pipe_fluid(e)
    end
    -- An inserter or loader with item filters in use says so unasked (Sonnet 06:20: stale filters blocked a line).
    if row.filters==nil and ours and (etype=='inserter' or etype=='loader' or etype=='loader-1x1') then
      local ok,line=pcall(M.details.filters_line,e)
      row.filters=ok and line or nil
    end
    out.entities[#out.entities+1]=row
  end
  out.total=total
  -- The part out of sight: remembered buildings and belts (status as seen when asked for), and our losses there.
  if not own_platform(p) then
    local boxes={}
    if area then boxes[1]={{area.left_top.x,area.left_top.y},{area.right_bottom.x,area.right_bottom.y}}
    else for _,raw in ipairs(a.positions or {}) do local q=position(raw); boxes[#boxes+1]={{q.x-0.5,q.y-0.5},{q.x+0.5,q.y+0.5}} end end
    local names_ok,types_ok
    if a.name then names_ok={} for _,n in ipairs(type(a.name)=='table' and a.name or {a.name}) do names_ok[n]=true end end
    if a.type then types_ok={} for _,t in ipairs(type(a.type)=='table' and a.type or {a.type}) do types_ok[t]=true end end
    local want_status=false
    for _,f in ipairs(fields) do if f=='status' then want_status=true end end
    local fog
    for _,b in ipairs(boxes) do
      local ok,f=pcall(M.fogmem.area,p.force,p.surface,b,limit,not strict and present or nil)
      if ok and f then
        if not fog then fog={remembered={},lost={},chunks_out_of_sight=0,remembered_count=0,lost_count=0,note=f.note,only_gone=f.only_gone} end
        fog.chunks_out_of_sight=fog.chunks_out_of_sight+f.chunks_out_of_sight
        for _,r in ipairs(f.remembered) do
          local t=names_ok==nil and types_ok==nil or names_ok and names_ok[r.name] or
            types_ok and types_ok[(prototypes.entity[r.name] or {}).type or '']
          if t then
            if not want_status then r.status=nil end
            fog.remembered_count=fog.remembered_count+1
            if #fog.remembered<limit then fog.remembered[#fog.remembered+1]=r end
          end
        end
        for _,r in ipairs(f.lost) do
          if names_ok==nil or names_ok[r.name] then fog.lost_count=fog.lost_count+1; fog.lost[#fog.lost+1]=r end
        end
      end
    end
    if fog then
      fog.line=string.format('%d chunks here out of sight: %d of our buildings and belts remembered%s, %d of ours lost there; our ghosts there are in entities',
        fog.chunks_out_of_sight,fog.remembered_count,fog.only_gone and ' that no longer stand there' or '',fog.lost_count)
      out.fog=fog
    end
  end
  -- Nothing found (B1): what the map says of the centre's chunk.
  if total==0 and area then
    local okg,g=pcall(M.ground_state,p,{x=(area.left_top.x+area.right_bottom.x)/2,y=(area.left_top.y+area.right_bottom.y)/2})
    out.ground=okg and g or nil
  end
  if a.ore then
    assert(a.ore=='runs' or a.ore=='grid','ore must be runs or grid')
    -- Ore needs its own unfiltered query when rows were filtered by name/type.
    if filtered then
      ores={}
      for _,e in pairs(p.surface.find_entities_filtered{area=area,type='resource'}) do
        if known(p,e) then ores[#ores+1]=e end
      end
    end
    local totals,names,cells={},{},{}
    for _,e in ipairs(ores) do
      local t=totals[e.name]
      if not t then t={name=e.name,tiles=0,amount=0}; totals[e.name]=t; names[#names+1]=e.name end
      t.tiles=t.tiles+1; t.amount=t.amount+e.amount
      cells[math.floor(e.position.y)..':'..math.floor(e.position.x)]=e.name
    end
    local legend=ore_letters(names)
    out.ore={legend={},totals={}}
    for _,name in ipairs(names) do out.ore.legend[legend[name]]=name; out.ore.totals[#out.ore.totals+1]=totals[name] end
    local left,top=math.floor(area.left_top.x),math.floor(area.left_top.y)
    local right,bottom=math.ceil(area.right_bottom.x)-1,math.ceil(area.right_bottom.y)-1
    out.ore.rows={}
    if a.ore=='grid' then
      -- Drill layout needs obstacles too: '#' marks tiles under other entities
      -- (trees, rocks, buildings), '~' marks water.
      for _,e in pairs(p.surface.find_entities_filtered{area=area}) do
        local layers=e.valid and e.type~='resource' and e.prototype.collision_mask and e.prototype.collision_mask.layers or {}
        if (layers.object or layers.player or layers.cliff) and e~=p.character and known(p,e) then
          local box=e.bounding_box
          for y=math.floor(box.left_top.y),math.ceil(box.right_bottom.y)-1 do
            for x=math.floor(box.left_top.x),math.ceil(box.right_bottom.x)-1 do blocked[y..':'..x]='#' end
          end
        end
      end
      for _,tile in pairs(p.surface.find_tiles_filtered{area=area,collision_mask='water_tile'}) do
        blocked[math.floor(tile.position.y)..':'..math.floor(tile.position.x)]='~'
      end
      out.ore.origin={x=left,y=top}
      for y=top,bottom do
        local line={}
        for x=left,right do
          local k=y..':'..x
          line[#line+1]=blocked[k] or (cells[k] and legend[cells[k]]) or '.'
        end
        out.ore.rows[#out.ore.rows+1]={y=y,row=table.concat(line)}
      end
    else
      -- Runs: per row, maximal x ranges of one ore, e.g. "C:-64..-50 I:-40..-30".
      for y=top,bottom do
        local runs,x={},left
        while x<=right do
          local name=cells[y..':'..x]
          if name then
            local start=x
            while x+1<=right and cells[y..':'..(x+1)]==name do x=x+1 end
            runs[#runs+1]=legend[name]..':'..start..'..'..x
          end
          x=x+1
        end
        if #runs>0 then out.ore.rows[#out.ore.rows+1]={y=y,runs=table.concat(runs,' ')} end
      end
    end
  end
  return out
end
-- Electric networks with a pole in the area. Rates are 5 s averages in kW;
-- the engine reports J per tick, input being consumption.
function handlers.power(p,a)
  -- by_cause (C1, Opus 22:50): each network's draw by entity name, and what drives robot charging (powercause.lua).
  if a.by_cause~=nil then
    assert(type(a.by_cause)=='boolean','by_cause must be true or false')
    assert(a.robots==nil or type(a.robots)=='boolean','robots must be true or false')
    if a.by_cause then
      M.powercause=M.powercause or require('powercause'){pole_map=function() return M.networks.pole_map() end,
        platform_power=function(s,f) return M.networks.platform_grid(s,f) end}
      return M.timed('powercause.read',M.powercause.read,p,a)  -- (d24 batch178) a part of its own in profile_ticks
    end
  end
  -- fragile (Opus, d15: one pole cut 142 poles of oil and drills): the poles whose loss alone cuts machines off from all
  -- generation (fragile.lua).
  if a.fragile~=nil then
    assert(type(a.fragile)=='boolean','fragile must be true or false')
    if a.fragile then
      assert(a.position~=nil,'fragile takes position (a pole of the network, or near one) and radius (default 96)')
      return M.fragile.read(p,a)
    end
  end
  assert(a.fresh==nil or type(a.fresh)=='boolean','fresh must be true or false')
  -- On a platform (platform=, Astra 13:10): the whole platform round its hub unless an area or radius is given.
  local plat=type(p)=='table' and rawget(p,'__platform')
  if plat and a.area==nil and a.radius==nil and a.position==nil then a.radius=64 end
  local area=view_area(p,a)
  local UNPOWERED={[defines.entity_status.no_power]='no_power',[defines.entity_status.low_power]='low_power'}
  local POWER_SELF={['electric-turret']=true,roboport=true,generator=true,['burner-generator']=true,['fusion-generator']=true,['solar-panel']=true,
    accumulator=true,['electric-energy-interface']=true,['lightning-attractor']=true}
  local networks,order={},{}
  -- (d24 batch152 PX1, Astra #2182: Asterion's 20 rare laser turrets drew 5.8 MW and no laser row came) each name over
  -- every quality (qflow.lua: a read by name counts normal only), a row for each quality with any (quality, nil for
  -- normal), and the qualities found
  local function rates(stats,category,counts)
    local total,top,found=0,{},nil
    for name,all in pairs(counts) do
      local t,by=M.qflow.flow_by(stats,name,category,defines.flow_precision_index.five_seconds,nil,all)
      for _,r in ipairs(by or {{quality='normal',n=t}}) do
        local kw=r.n*60/1000
        if kw>=0.5 then
          total=total+kw; top[#top+1]={name=name,quality=r.quality~='normal' and r.quality or nil,kw=math.floor(kw+0.5)}
          if r.quality~='normal' then found=found or {}; found[r.quality]=true end
        end
      end
    end
    table.sort(top,function(x,y) return x.kw>y.kw end)
    return math.floor(total+0.5),top,found
  end
  -- the qualities other than normal among a network's rows, by level
  local function both(n,stats)
    local cf,pf
    n.consumption_kw,n.consumers,cf=rates(stats,'input',stats.input_counts)
    n.production_kw,n.producers,pf=rates(stats,'output',stats.output_counts)
    local q={}
    for _,name in ipairs(M.qflow.qualities()) do if (cf and cf[name]) or (pf and pf[name]) then q[#q+1]=name end end
    n.qualities=#q>0 and q or nil
  end
  for _,e in pairs(p.surface.find_entities_filtered{area=area,type='electric-pole',force=p.force}) do
    local id=e.valid and known(p,e) and e.electric_network_id
    if id then
      local n=networks[id]
      if not n then
        local stats=e.electric_network_statistics
        n={id=id,poles=0,unpowered=0}
        both(n,stats)
        networks[id]=n; order[#order+1]=n
      end
      n.poles=n.poles+1
    end
  end
  -- (d20 batch71 AG4, Astra #1699) a platform's own network, read whole from its surface (networks.platform_power):
  -- its machines and panels are on it, also under a pole; a pole network no machine or panel is on gives this
  -- network's figures under its own id, so it is no row of its own.
  local pp=M.networks.platform_power(p.surface,p.force)
  local gstats=pp and pp.network and M.networks.global_stats(p.surface)
  -- Machines without power: unconnected ones have no network id at all.
  local unpowered,limit={},integer(a.limit,32,1,256,'limit')
  local total=0
  for _,e in pairs(p.surface.find_entities_filtered{area=area,force=p.force}) do
    if e.valid and e.type~='electric-pole' and known(p,e) and e.prototype.electric_energy_source_prototype then
      local id=e.electric_network_id
      -- A network with no pole in the area (Astra, 14:05: Starling's network 475 showed nothing): listed from its
      -- machines and panels, without figures (the game gives a network's statistics through its poles).
      if id and not networks[id] then
        if gstats and id==pp.network then
          local n={id=id,poles=0,unpowered=0,entities=0,platform_network=true,
            note='the platform\'s own network: every machine, panel and accumulator of ours on the platform is on it, no pole needed; figures from the surface\'s statistics'}
          both(n,gstats)
          networks[id]=n
        else
          networks[id]={id=id,poles=0,unpowered=0,entities=0,note='no pole of ours in the area: the game gives a network\'s statistics through its poles'}
        end
        order[#order+1]=networks[id]
      end
      if id and networks[id].entities then networks[id].entities=networks[id].entities+1 end
      -- Generators by state (Sol, d15 09:20: a 94 MW grid gave about 40 MW and 177 machines low power, its boilers dry):
      -- nameplate (the prototype's maximum output) of all, of those working now, and those stopped, by status.
      -- (d21 batch64 Z5, Astra #1635: two fusion generators making 57 MW read nameplate 0; 2.0.77 gives a fusion
      -- generator's 50 MW only as get_max_energy_production, networks.max_output_kw) and per name and quality: count,
      -- each one's most output, theirs together and how many work; the network's output of that name beside it.
      if id and (e.type=='generator' or e.type=='burner-generator' or e.type=='fusion-generator') then
        local n=networks[id]
        local kw=M.networks.max_output_kw(e)
        local st=M.machine_status(e) or 'unknown'
        local works=st=='working' or st=='normal' or st=='low_power'
        n.gen=n.gen or {count=0,nameplate=0,working=0,stopped={},stopped_kw=0,by={},order={}}
        n.gen.count=n.gen.count+1; n.gen.nameplate=n.gen.nameplate+kw
        if works then n.gen.working=n.gen.working+kw
        else
          local k=e.name..' '..st
          n.gen.stopped[k]=(n.gen.stopped[k] or 0)+1; n.gen.stopped_kw=n.gen.stopped_kw+kw
        end
        local q=e.quality and e.quality.name or 'normal'
        local key=e.name..'|'..q
        local r=n.gen.by[key]
        if not r then r={name=e.name,quality=q~='normal' and q or nil,count=0,each_kw=kw,max_kw=0,working=0}; n.gen.by[key]=r; n.gen.order[#n.gen.order+1]=r end
        r.count=r.count+1; r.max_kw=r.max_kw+kw; if works then r.working=r.working+1 end
      end
      -- Solar panels in the area (Z5): their most output at full sun at this surface's solar power.
      if id and e.type=='solar-panel' then
        local n=networks[id]
        n.solar_count=(n.solar_count or 0)+1
        n.solar_full_kw=(n.solar_full_kw or 0)+M.networks.max_output_kw(e)
      end
      -- Accumulators in the area, read now (Astra, shift14 22:50: Fulgora's dusk brownouts read from a view that stood
      -- still while each accumulator's inspect moved); (Z5) the most they give holding charge, each its output limit.
      if id and e.type=='accumulator' then
        local n=networks[id]
        n.accumulators=(n.accumulators or 0)+1
        n.acc_j=(n.acc_j or 0)+(e.energy or 0)
        n.acc_buf=(n.acc_buf or 0)+(e.electric_buffer_size or 0)
        if (e.energy or 0)>0 then
          local okf,lim=pcall(function() return e.prototype.electric_energy_source_prototype.get_output_flow_limit(e.quality) end)
          n.acc_out_kw=(n.acc_out_kw or 0)+((okf and type(lim)=='number') and lim*60/1000 or 0)
          n.acc_holding=(n.acc_holding or 0)+1
        end
      end
      -- Lightning attractors in the area (Z5): what they hold; they give it out as the network draws.
      if id and e.type=='lightning-attractor' then
        local n=networks[id]
        n.attractors=(n.attractors or 0)+1
        n.attr_j=(n.attr_j or 0)+(e.energy or 0)
      end
      local why=not id and 'unconnected' or UNPOWERED[e.status]
      -- (PX1) a laser turret refills its buffer after shots at its input limit and reads low_power meanwhile; in a short
      -- network every machine gets the same share and reads low_power too. The other machines on its network in the
      -- area (not turrets, roboports, generators, panels or accumulators) tell the two apart.
      -- (d24 batch160 QC1, Astra #2208) every turret firing from a buffer (laser, railgun, tesla: networks.shot_turret)
      -- is a turret here, never one of the other machines
      local n=id and networks[id]
      local shot=M.networks.shot_turret(e)
      if n and not POWER_SELF[e.type] and not shot then n.others=(n.others or 0)+1; if why then n.others_short=(n.others_short or 0)+1 end end
      if why then
        total=total+1
        if n then n.unpowered=n.unpowered+1 end
        local row={name=e.name,position=e.position,status=why,network=id}
        if n and why=='low_power' and shot then n.turrets_low=(n.turrets_low or 0)+1; row.turret=true end
        if #unpowered<limit then unpowered[#unpowered+1]=row end
      end
    end
  end
  -- (PX1) low_power turrets: the network short when another machine of it in the area is on low or no power
  -- (turrets_short_by machines), or (QC1) its accumulators in the area are empty (1% or less) while it draws all it
  -- produces (turrets_short_by accumulators); else recharging after shots, when a machine or an accumulator of it in
  -- the area says so
  for _,n in pairs(networks) do
    if n.turrets_low then
      local acc_empty=(n.accumulators or 0)>0 and (n.acc_buf or 0)>0 and (n.acc_j or 0)<=0.01*n.acc_buf
        and (n.production_kw or 0)>0 and (n.consumption_kw or 0)>=0.99*n.production_kw
      if (n.others_short or 0)>0 then n.turrets_short,n.turrets_short_by=n.turrets_low,'machines'
      elseif acc_empty then n.turrets_short,n.turrets_short_by=n.turrets_low,'accumulators'
      elseif (n.others or 0)>0 or (n.accumulators or 0)>0 then n.turrets_recharging=n.turrets_low end
    end
  end
  local function acc_text(n)
    return string.format('its %d accumulator%s in the area %s %.1f of %.1f MJ',n.accumulators,n.accumulators==1 and '' or 's',n.accumulators==1 and 'holds' or 'hold',(n.acc_j or 0)/1e6,(n.acc_buf or 0)/1e6)
  end
  for _,r in ipairs(unpowered) do
    if r.turret then
      local n=networks[r.network]
      r.turret=nil
      if n.turrets_recharging then
        r.cause=string.format('recharging after shots: its buffer refills at its input limit; %s',table.concat((function()
          local w={}
          if (n.others or 0)>0 then w[#w+1]=string.format('the %d other machines of electric #%d in the area are supplied',n.others,n.id) end
          if (n.accumulators or 0)>0 then w[#w+1]=acc_text(n) end
          return w end)(),'; '))
      elseif n.turrets_short_by=='machines' then r.cause=string.format('electric #%d short of supply: %d of its %d other machines in the area on low or no power',n.id,n.others_short,n.others)
      elseif n.turrets_short_by=='accumulators' then
        r.cause=string.format('electric #%d short of supply: %s, and it draws %.1f MW of the %.1f MW it produces',n.id,acc_text(n),(n.consumption_kw or 0)/1000,(n.production_kw or 0)/1000)
      else r.cause=string.format('no other machine or accumulator of electric #%d in the area to tell recharging from a short network',n.id) end
    end
  end
  for _,n in pairs(networks) do n.others,n.others_short,n.turrets_low=nil,nil,nil end
  -- Boilers in the area by state: they feed the steam engines and turbines (not on a network themselves).
  -- (Z5) Reactors too: a nuclear reactor or heating tower makes heat for heat exchangers and boilers, a fusion reactor
  -- plasma for fusion generators; none gives electricity itself.
  local boilers,reactors
  for _,e in pairs(p.surface.find_entities_filtered{area=area,type={'boiler','reactor','fusion-reactor'},force=p.force}) do
    if e.valid and known(p,e) then
      local st=M.machine_status(e) or 'unknown'
      if e.type=='boiler' then
        boilers=boilers or {total=0}
        boilers.total=boilers.total+1; boilers[st]=(boilers[st] or 0)+1
      else
        reactors=reactors or {total=0,by={},fusion={},fusion_more=0}
        reactors.total=reactors.total+1
        local k=e.name..' '..st
        reactors.by[k]=(reactors.by[k] or 0)+1
        -- (Z6) a fusion reactor's row as inspect gives it, up to 8
        if e.type=='fusion-reactor' then
          if #reactors.fusion<8 then local okf,fu=pcall(M.fusion.read,e); if okf and fu then reactors.fusion[#reactors.fusion+1]=fu.line end
          else reactors.fusion_more=reactors.fusion_more+1 end
        end
      end
    end
  end
  -- (AG4) pole networks with no machine or panel of ours on them, on a platform: folded into the platform's network
  local folded
  if pp then
    local apart={}
    for _,id in ipairs(pp.separate_pole_networks or {}) do apart[id]=true end
    local kept={}
    for _,n in ipairs(order) do
      if n.poles>0 and not apart[n.id] and not n.entities then folded=folded or {}; folded[#folded+1]=string.format('#%d (%d pole%s)',n.id,n.poles,n.poles==1 and '' or 's')
      else kept[#kept+1]=n end
    end
    order=kept
  end
  table.sort(order,function(x,y) return x.poles>y.poles end)
  for _,n in ipairs(order) do
    -- (Z5) the network's output now by name (its 5 s statistics), and by entity type
    local made,madeq={},{}
    for _,x in ipairs(n.producers or {}) do
      made[x.name]=(made[x.name] or 0)+x.kw
      local k=x.name..'|'..(x.quality or 'normal'); madeq[k]=(madeq[k] or 0)+x.kw
    end
    local function made_of(kind)
      local kw=0
      for name,v in pairs(made) do if prototypes.entity[name] and prototypes.entity[name].type==kind then kw=kw+v end end
      return kw
    end
    if n.gen then
      local g=n.gen
      local parts={}
      for k,c in pairs(g.stopped) do parts[#parts+1]=c..' '..k end
      table.sort(parts)
      -- (Z5) per name and quality: each one's most output apart from the network's output of that name now
      table.sort(g.order,function(x,y) return x.max_kw>y.max_kw end)
      local by,kinds={},{}
      for _,r in ipairs(g.order) do
        local label=r.name..(r.quality and ' ('..r.quality..')' or '')
        by[#by+1]={name=r.name,quality=r.quality,count=r.count,each_kw=math.floor(r.each_kw+0.5),max_kw=math.floor(r.max_kw+0.5),working=r.working,network_output_kw=madeq[r.name..'|'..(r.quality or 'normal')]}
        kinds[#kinds+1]=string.format('%s %d x %.1f MW = %.1f MW, %d working',label,r.count,r.each_kw/1000,r.max_kw/1000,r.working)
      end
      local outs={}
      for _,x in ipairs(by) do
        if made[x.name] and not outs[x.name] then
          outs[x.name]=true
          local qs={}
          for _,q in ipairs(M.qflow.qualities()) do local v=madeq[x.name..'|'..q]; if v and v~=made[x.name] then qs[#qs+1]=string.format('%s %.1f',q,v/1000) end end
          outs[#outs+1]=string.format('%s %.1f MW%s',x.name,made[x.name]/1000,#qs>0 and ' ('..table.concat(qs,', ')..')' or '')
        end
      end
      n.generators={count=g.count,nameplate_kw=math.floor(g.nameplate+0.5),working_kw=math.floor(g.working+0.5),
        stopped_kw=g.stopped_kw>0 and math.floor(g.stopped_kw+0.5) or nil,stopped=#parts>0 and parts or nil,by_name=by}
      n.supply_line=string.format('generators in the area: %d (%s), nameplate %.1f MW; working now %.1f MW (the most they give at full load); stopped %.1f MW%s; the network produces %.1f MW now%s%s',
        g.count,table.concat(kinds,'; '),g.nameplate/1000,g.working/1000,g.stopped_kw/1000,#parts>0 and ' ('..table.concat(parts,', ')..')' or '',(n.production_kw or 0)/1000,
        #outs>0 and ', of it '..table.concat(outs,', ') or '',
        n.unpowered>0 and string.format('; %d machines in the area without full power%s',n.unpowered,
          n.turrets_recharging and string.format(' (%d of them turrets recharging after shots, every other machine supplied)',n.turrets_recharging) or '') or '')
      n.gen=nil
    end
    -- (Z5) Solar panels, accumulators and lightning attractors in the area, apart from the generators.
    if n.solar_count then
      local okp,sun=pcall(M.networks.solar,p.surface)
      local pct=okp and sun.percent or 100
      n.solar={count=n.solar_count,full_sun_kw=math.floor(n.solar_full_kw*pct/100+0.5),solar_power=math.floor(pct+0.5),network_output_kw=made_of('solar-panel')}
      n.solar_line=string.format('solar panels in the area: %d, %.1f MW at full sun here (solar power %d%%); the network\'s panels produce %.1f MW now',
        n.solar_count,n.solar.full_sun_kw/1000,n.solar.solar_power,n.solar.network_output_kw/1000)
      n.solar_count,n.solar_full_kw=nil,nil
    end
    if n.accumulators then
      n.acc_holding=n.acc_holding or 0
      n.acc_out_kw=math.floor((n.acc_out_kw or 0)+0.5)
      n.acc_line=string.format('accumulators in the area: %d, %d holding charge, giving up to %.1f MW together; the network\'s accumulators give %.1f MW now',
        n.accumulators,n.acc_holding,n.acc_out_kw/1000,made_of('accumulator')/1000)
    end
    if n.attractors then
      n.attr_mj=math.floor(n.attr_j/1e5+0.5)/10
      n.attractor_line=string.format('lightning attractors in the area: %d, holding %.1f MJ; the network\'s attractors give %.1f MW now',n.attractors,n.attr_mj,made_of('lightning-attractor')/1000)
      n.attr_j=nil
    end
    -- Its draw ranked, by prototype and by kind (Opus 04:11: roboports recharging after a blackout drew 11-16 MW and
    -- starved the boilers' feeders): the game's 5 s statistics, each prototype under its entity type.
    if n.consumers and #n.consumers>0 then
      local kinds,korder={},{}
      for _,c in ipairs(n.consumers) do
        local kind=(prototypes.entity[c.name] and prototypes.entity[c.name].type) or c.name
        if not kinds[kind] then kinds[kind]={kind=kind,kw=0,names={}}; korder[#korder+1]=kinds[kind] end
        kinds[kind].kw=kinds[kind].kw+c.kw; kinds[kind].names[#kinds[kind].names+1]=c.name..(c.quality and ' ('..c.quality..')' or '')
      end
      table.sort(korder,function(x,y) return x.kw>y.kw end)
      n.draw_by_kind=korder
      local function mw(kw) return kw>=1000 and string.format('%.1f MW',kw/1000) or string.format('%d kW',kw) end
      local parts={}
      for i,k in ipairs(korder) do if i>6 then break end; parts[#parts+1]=string.format('%s %s (%s)',k.kind,mw(k.kw),table.concat(k.names,', ',1,math.min(3,#k.names))) end
      n.draw_line=string.format('electric #%s draws %s: %s',tostring(n.id),mw(n.consumption_kw or 0),table.concat(parts,'; '))
    end
    if n.accumulators then
      n.acc_mj,n.acc_max_mj=math.floor(n.acc_j/1e5+0.5)/10,math.floor(n.acc_buf/1e5+0.5)/10
      n.acc_pct=n.acc_buf>0 and math.floor(100*n.acc_j/n.acc_buf+0.5) or nil
      n.acc_j,n.acc_buf=nil,nil
    end
  end
  -- The solar power where the surface is (a platform's changes with its location), and the networks read's line.
  local oks,sun=pcall(M.networks.solar,p.surface)
  -- (Z5, Astra #1635: the line held a capacity from before two fusion generators were built) each line says the view's
  -- age; a network here with no line in the view is named; a generator built since the view began is said.
  local lines,in_view={},{}
  local okv,nv=pcall(M.networks.read,p,{surface=p.surface.name,fresh=a.fresh})
  for _,s in ipairs(okv and nv.surfaces or {}) do
    for _,r in ipairs(s.electric or {}) do
      if networks[r.id] then in_view[r.id]=true; lines[#lines+1]=r.line..' (as of '..nv.as_of..')' end
    end
  end
  local not_in_view={}
  for _,n in ipairs(order) do if okv and not in_view[n.id] and (n.poles>2 or n.generators) then not_in_view[#not_in_view+1]='#'..n.id end end
  local boiler_line
  if boilers then
    local parts={}
    for k,c in pairs(boilers) do if k~='total' then parts[#parts+1]=c..' '..k end end
    table.sort(parts)
    boiler_line=string.format('boilers in the area: %d (%s)',boilers.total,table.concat(parts,', '))
  end
  local reactor_line
  if reactors then
    local parts={}
    for k,c in pairs(reactors.by) do parts[#parts+1]=c..' '..k end
    table.sort(parts)
    reactor_line=string.format('reactors in the area: %d (%s); they make heat or plasma for the generators counted above, no electricity themselves',reactors.total,table.concat(parts,', '))
  end
  local fusion_rows=reactors and #reactors.fusion>0 and reactors.fusion or nil
  if fusion_rows and reactors.fusion_more>0 then fusion_rows[#fusion_rows+1]=reactors.fusion_more..' more fusion reactors in the area: inspect each' end
  -- (d20 batch62 X2) the surface read, named: another one by remote view (surface=)
  return {surface=p.surface.name,networks=order,unpowered=unpowered,unpowered_total=total>#unpowered and total or nil,boilers=boiler_line,
    reactors=reactor_line,fusion_reactors=fusion_rows,platform=plat or nil,solar_power=oks and sun.text or nil,lines=#lines>0 and lines or nil,
    platform_power=pp or nil,
    pole_networks_folded=folded and string.format('pole network%s %s: no machine, panel or accumulator of ours is on %s (the game keeps them on the platform\'s network #%s), and a pole\'s statistics there are that network\'s; shown in platform_power',
      #folded==1 and '' or 's',table.concat(folded,', '),#folded==1 and 'it' or 'them',tostring(pp.network)) or nil,
    lines_as_of=#lines>0 and okv and nv.as_of and (nv.as_of..' (the networks view; its accumulator part read now)') or nil,
    not_in_view=#not_in_view>0 and string.format('electric %s: no line in the networks view of %s (a network the view has not reached yet: its generators and draw are read now above)',
      table.concat(not_in_view,', '),nv.as_of) or nil,
    built_since=okv and nv.built_since or nil}
end
-- A top-down character map of an area, one character per tile: buildings as
-- upper-case letters by type, belts as arrows, ore under free tiles in lower
-- case, water '~'. Every letter in use is listed in the legend.
-- Upper case never collides with ore, which is always lower case.
local GRID_TYPES={['mining-drill']='D',furnace='F',['assembling-machine']='A',lab='L',container='C',['logistic-container']='C',
  ['electric-pole']='P',inserter='I',boiler='B',generator='E',splitter='S',['ammo-turret']='G',['electric-turret']='G',
  turret='W',['unit-spawner']='N',wall='X',gate='X',pipe='=',['pipe-to-ground']='=',['offshore-pump']='O',radar='*',
  ['storage-tank']='K',pump='=',['rocket-silo']='Z',roboport='Q',beacon='Y',['solar-panel']='H',accumulator='M',
  tree='T',['simple-entity']='R',cliff='%',['entity-ghost']='?',character='@',car='&'}
local GRID_SKIP={resource=true,corpse=true,['character-corpse']=true,['item-entity']=true,['item-request-proxy']=true,
  ['highlight-box']=true,projectile=true,sticker=true,fire=true,['smoke-with-trigger']=true,['tile-ghost']=true,
  ['deconstructible-tile-proxy']=true,particle=true,['speech-bubble']=true,explosion=true}
local ARROWS={[0]='^',[4]='>',[8]='v',[12]='<'}
local function grid_char(e)
  if e.type=='transport-belt' then return ARROWS[e.direction] or '+' end
  if e.type=='underground-belt' then return e.belt_to_ground_type=='input' and 'U' or 'J' end
  return GRID_TYPES[e.type] or '#'
end
function handlers.grid(p,a)
  local area=view_area(p,a)
  local x0,y0=math.floor(area.left_top.x),math.floor(area.left_top.y)
  local x1,y1=math.ceil(area.right_bottom.x),math.ceil(area.right_bottom.y)
  local cells,legend={},{}
  local function put(x,y,ch,name)
    if x>=x0 and x<x1 and y>=y0 and y<y1 then
      cells[y..':'..x]=ch
      local names=legend[ch] or {}; legend[ch]=names
      if name and not names[name] and #names<6 then names[name]=true; names[#names+1]=name end
    end
  end
  local ore_names,ores={},{}
  for _,e in pairs(p.surface.find_entities_filtered{area=area,type='resource'}) do
    if known(p,e) then
      if not ores[e.name] then ores[e.name]={}; ore_names[#ore_names+1]=e.name end
      table.insert(ores[e.name],e.position)
    end
  end
  local letters=ore_letters(ore_names)
  for name,list in pairs(ores) do
    for _,pos in ipairs(list) do put(math.floor(pos.x),math.floor(pos.y),letters[name]:lower(),name) end
  end
  local seen_chunk={}
  for _,tile in pairs(p.surface.find_tiles_filtered{area=area,collision_mask='water_tile'}) do
    -- (d18 batch37 D1) water in charted chunks only, as the map shows it (a grid of another planet reaches past them)
    local c=chunk_of(tile.position); local ck=c.x..','..c.y
    if seen_chunk[ck]==nil then seen_chunk[ck]=charted(p,tile.position) end
    if seen_chunk[ck] then put(math.floor(tile.position.x),math.floor(tile.position.y),M.water_kind(tile.name)=='walkable' and ',' or '~',tile.name or 'water') end
  end
  -- On a platform, space without foundation is where nothing can stand.
  if own_platform(p) then
    for _,tile in pairs(p.surface.find_tiles_filtered{area=area,name='empty-space'}) do
      put(math.floor(tile.position.x),math.floor(tile.position.y),'_','empty space')
    end
  end
  for _,e in pairs(p.surface.find_entities_filtered{area=area}) do
    if e.valid and not GRID_SKIP[e.type] and (e==p.character or known(p,e)) then
      local ch=e==p.character and '@' or grid_char(e)
      local name=e.type=='entity-ghost' and 'ghost: '..e.ghost_name or e.name
      if e.type=='underground-belt' then name=name..' '..e.belt_to_ground_type end
      local box=e.bounding_box
      for y=math.floor(box.left_top.y+0.01),math.ceil(box.right_bottom.y-0.01)-1 do
        for x=math.floor(box.left_top.x+0.01),math.ceil(box.right_bottom.x-0.01)-1 do put(x,y,ch,name) end
      end
    end
  end
  local rows,ruler={},{}
  for x=x0,x1-1 do ruler[#ruler+1]=x%10==0 and '|' or ' ' end
  for y=y0,y1-1 do
    local line={}
    for x=x0,x1-1 do line[#line+1]=cells[y..':'..x] or '.' end
    rows[#rows+1]={y=y,row=table.concat(line)}
  end
  local out_legend={}
  for ch,names in pairs(legend) do out_legend[ch]=table.concat(names,', ') end
  if out_legend['~'] then out_legend['~']='water a character cannot cross: '..out_legend['~'] end
  if out_legend[','] then out_legend[',']='water a character walks through: '..out_legend[','] end
  return {origin={x=x0,y=y0},ruler=table.concat(ruler),ruler_note="'|' marks x%10==0",rows=rows,legend=out_legend}
end
end -- rates {recipe | item} with no area or positions (Gemini 02:36: rates filtered by recipe or item across a surface):
-- every crafter of ours on the surface set to that recipe (or to one making the item), at most 512, as the rates read
-- computes them, with the surface's statistics for the item beside it (made and used a minute over 10 min).
M.RATES_SURFACE=512
function handlers.rates(p,a)
  if (a.recipe~=nil or a.item~=nil) and a.area==nil and a.positions==nil then
    assert(a.recipe==nil or (type(a.recipe)=='string' and prototypes.recipe[a.recipe]),'recipe must be a recipe name')
    assert(a.item==nil or (type(a.item)=='string' and prototypes.item[a.item]),'item must be an item name')
    local list,found={},0
    for _,e in ipairs(p.surface.find_entities_filtered{type={'assembling-machine','furnace','rocket-silo'},force=p.force}) do
      local ok,r=pcall(function() return e.get_recipe() or (e.type=='furnace' and e.previous_recipe and prototypes.recipe[type(e.previous_recipe.name)=='string' and e.previous_recipe.name or e.previous_recipe.name.name]) end)
      local name=ok and r and r.name
      local hit=name and (name==a.recipe)
      if name and a.item and not a.recipe then
        for _,pr in ipairs(prototypes.recipe[name].products or {}) do if pr.name==a.item then hit=true end end
      end
      if hit then found=found+1; if #list<M.RATES_SURFACE then list[#list+1]=e end end
    end
    local out=rates.compute(p,list,a.per)
    for _,row in ipairs(out.rows or {}) do row.raw_net=nil end
    if a.item then
      local keep={}
      for _,row in ipairs(out.rows or {}) do if row.name==a.item or row.item==a.item then keep[#keep+1]=row end end
      out.rows_other=#(out.rows or {})-#keep; out.rows=keep
      local stats=p.force.get_item_production_statistics(p.surface)
      -- (PX1) every quality, the qualities found named
      local qs={}
      local function per(c)
        local n,by=M.qflow.flow_by(stats,a.item,c,defines.flow_precision_index.ten_minutes,true)
        if by then qs[#qs+1]=(c=='input' and 'made ' or 'used ')..M.qflow.label(by) end
        return math.floor(n/10*10+0.5)/10
      end
      out.statistics=string.format('%s on %s, the game\'s statistics over 10 min (every quality): made %g/min, used %g/min%s',a.item,p.surface.name,per('input'),per('output'),
        #qs>0 and ' (in 10 min by quality: '..table.concat(qs,'; ')..')' or '')
    end
    out.machines=found; out.machines_read=#list<found and #list or nil; out.surface=p.surface.name; out.per=a.per or 'minute'
    out.scope=string.format('%d crafter%s on %s set to %s%s',found,found==1 and '' or 's',p.surface.name,a.recipe or ('a recipe making '..a.item),
      #list<found and string.format(' (the first %d read)',#list) or '')
    return out
  end
  return rates.rates(p,a)
end
-- bottleneck {item}: the item's chain to its root (supply.lua; Sonnet, 15:20); else the area read (rates.lua).
function handlers.bottleneck(p,a)
  -- chain: true (d17 batch31 A1, Sonnet and Opus): each link's makers, rates now and at full speed, its ask and stock,
  -- and the limiting link (chain.lua)
  if a.chain~=nil then
    assert(type(a.chain)=='boolean','chain must be true or false')
    assert(a.item~=nil,'chain goes with item: bottleneck {item, chain: true}')
    assert(a.per_min==nil and a.all_stopped==nil,'chain takes item and surface only')
    if a.chain then
      assert(type(a.item)=='string' and (prototypes.item[a.item] or (prototypes.fluid and prototypes.fluid[a.item])),'item must be an item or fluid name (processing-unit, plastic-bar, petroleum-gas, ...)')
      local surface=p.surface
      if a.surface~=nil then
        assert(type(a.surface)=='string','surface must be a surface name')
        surface=game.get_surface(a.surface)
        assert(surface,'no surface '..a.surface)
      end
      return M.chain.read(p,a,surface)
    end
  end
  -- (d24 batch135 PG1) an item's chain is the surface's: area and positions are refused there, not ignored
  if a.item~=nil then
    assert(a.area==nil and a.positions==nil,'bottleneck {item} reads the item\'s chain on the whole surface: area and positions go without item')
    return M.supply.bottleneck_item(p,a)
  end
  assert(a.surface==nil,'surface goes with item')
  assert(a.per_min==nil,'per_min goes with item: bottleneck {item, per_min}')
  return rates.bottleneck(p,a)
end
-- stock {network} and stock {item, surface} (Gemini 02:36: stock with a surface or network filter): a logistic
-- network's holdings by its number (the networks read numbers them), and one planet's whole stock of an item as
-- freight_audit counts it (networks, pads in no network, plain chests and landed pods, silos' rockets, labs).
-- nearest_water {position?, radius?} (Opus 04:11: placements stops at 24 tiles): the nearest tile an offshore pump can
-- pump from (a tile with a fluid: water, lava, an oil ocean, ammonia) in chunks the map has charted, by rings of chunks
-- outward to radius (1..256, default 200), and the offshore-pump spots there as placements gives them.
function handlers.nearest_water(p,a)
  local centre=a.position~=nil and position(a.position) or p.position
  local radius=integer(a.radius,200,1,256,'radius')
  local s,f=p.surface,p.force
  local cx,cy=math.floor(centre.x/32),math.floor(centre.y/32)
  local best,bd,checked,uncharted
  local rings=math.ceil(radius/32)+1
  local fluid_of={}
  local function pumpable(name)
    if fluid_of[name]==nil then fluid_of[name]=(pcall(function() return prototypes.tile[name].fluid end) and prototypes.tile[name].fluid and (prototypes.tile[name].fluid.name or tostring(prototypes.tile[name].fluid))) or false end
    return fluid_of[name]
  end
  checked,uncharted=0,0
  -- A ring with no water at all is skipped with four counts over its sides (each chunk alone cost 0.5 ms in the
  -- container); only rings with some are read chunk by chunk, charted chunks only.
  local function ring_has(r)
    if r==0 then return true end
    local x0,y0,x1,y1=(cx-r)*32,(cy-r)*32,(cx+r+1)*32,(cy+r+1)*32
    for _,ar in ipairs({{x0,y0,x1,y0+32},{x0,y1-32,x1,y1},{x0,y0+32,x0+32,y1-32},{x1-32,y0+32,x1,y1-32}}) do
      if s.count_tiles_filtered{area={left_top={x=ar[1],y=ar[2]},right_bottom={x=ar[3],y=ar[4]}},collision_mask='water_tile',limit=1}>0 then return true end
    end
    return false
  end
  -- Near water first: every water tile within 8, then 16 tiles is read (a tile outside that circle is farther than any in
  -- it), in charted chunks.
  for _,R in ipairs({8,16}) do
    if R<=radius and not best then
      for _,tile in ipairs(s.find_tiles_filtered{position=centre,radius=R,collision_mask='water_tile',limit=1200}) do
        local q={x=tile.position.x+0.5,y=tile.position.y+0.5}
        local fl=pumpable(tile.name)
        if fl and f.is_chunk_charted(s,{x=math.floor(q.x/32),y=math.floor(q.y/32)}) then
          local d=distance(centre,q)
          if d<=R and (not bd or d<bd) then best,bd={pos=q,name=tile.name,fluid=fl},d end
        end
      end
    end
  end
  for r=0,(best and -1 or rings) do
    local any=ring_has(r)
    for dx=-r,r do
      for dy=-r,r do
        if any and math.max(math.abs(dx),math.abs(dy))==r then
          local ch={x=cx+dx,y=cy+dy}
          if f.is_chunk_charted(s,ch) then
            checked=checked+1
            local area={left_top={x=ch.x*32,y=ch.y*32},right_bottom={x=ch.x*32+32,y=ch.y*32+32}}
            if s.count_tiles_filtered{area=area,collision_mask='water_tile',limit=1}>0 then
              for _,tile in ipairs(s.find_tiles_filtered{area=area,collision_mask='water_tile',limit=1024}) do
                local fl=pumpable(tile.name)
                if fl then
                  local q={x=tile.position.x+0.5,y=tile.position.y+0.5}
                  local d=distance(centre,q)
                  if d<=radius and (not bd or d<bd) then best,bd={pos=q,name=tile.name,fluid=fl},d end
                end
              end
            end
          else uncharted=uncharted+1 end
        end
      end
    end
    -- a ring further can still hold a nearer tile than this ring's corners: one more, then stop
    if best and (r*32-32)>bd then break end
  end
  if not best then
    return {found=false,checked_chunks=checked,uncharted_chunks=uncharted,line=string.format('no tile an offshore pump takes within %d tiles of (%g,%g) in the %d charted chunks read (%d not charted)',radius,math.floor(centre.x),math.floor(centre.y),checked,uncharted)}
  end
  local out={found=true,tile=best.name,fluid=best.fluid,position=best.pos,distance=math.floor(bd*10+0.5)/10,checked_chunks=checked,uncharted_chunks=uncharted>0 and uncharted or nil}
  local ok,pl=pcall(M.shore.handlers.placements,p,{name='offshore-pump',near=best.pos,radius=12,limit=3})
  if ok and type(pl)=='table' then out.pump_spots=pl.placements; out.pump_note=pl.in_the_way or pl.note
  else out.pump_note='offshore-pump spots there: '..(reason and reason(pl) or tostring(pl)) end
  out.line=string.format('nearest %s (%s) at (%g,%g), %.1f tiles from (%g,%g)%s',best.name,best.fluid,best.pos.x,best.pos.y,bd,math.floor(centre.x),math.floor(centre.y),
    out.pump_spots and #out.pump_spots>0 and string.format('; offshore-pump spots: %s',(function() local t2={} for i,sp in ipairs(out.pump_spots) do t2[i]=string.format('(%g,%g) %s',sp.position.x,sp.position.y,sp.direction or '') end return table.concat(t2,', ') end)()) or '')
  return out
end
function handlers.stock(p,a)
  if a.network~=nil then
    assert(type(a.network)=='number','network is a logistic network number (the networks read lists them)')
    local surface=p.surface
    if a.surface~=nil then surface=game.get_surface(a.surface); assert(surface,'no surface '..tostring(a.surface)) end
    local ln
    for _,n in ipairs(p.force.logistic_networks[surface.name] or {}) do if n.network_id==a.network then ln=n end end
    assert(ln,string.format('no logistic network #%d of ours on %s',a.network,surface.name))
    local items={}
    for _,s in ipairs(ln.get_contents() or {}) do
      if a.item==nil or s.name==a.item then items[#items+1]={name=s.name,quality=s.quality~='normal' and s.quality or nil,count=s.count} end
    end
    table.sort(items,function(x,y) return x.count>y.count end)
    local limit=integer(a.limit,16,1,64,'limit')
    local parts={}
    for i,s in ipairs(items) do if i>limit then break end; parts[#parts+1]=s.name..(s.quality and '@'..s.quality or '')..' '..s.count end
    -- The robots each roboport holds (Haiku 07:50: which roboport to take robots from, as its GUI shows): most first.
    local ports={}
    for _,cell in ipairs(ln.cells or {}) do
      local e=cell.owner
      local inv=e and e.valid and e.type=='roboport' and e.get_inventory(defines.inventory.roboport_robot)
      if inv then
        local parts,n={},0
        for _,s in ipairs(inv.get_contents()) do parts[#parts+1]=s.name..' '..s.count; n=n+s.count end
        if n>0 then ports[#ports+1]={n=n,line=string.format('roboport (%g,%g): %s',e.position.x,e.position.y,table.concat(parts,', '))} end
      end
    end
    table.sort(ports,function(x,y) return x.n>y.n end)
    local port_lines={}
    for i,r in ipairs(ports) do if i<=16 then port_lines[i]=r.line end end
    return {network=a.network,surface=surface.name,items=items[limit+1] and {table.unpack(items,1,limit)} or items,more=#items>limit and #items-limit or nil,
      roboports=#port_lines>0 and port_lines or nil,roboports_more=#ports>16 and #ports-16 or nil,
      robots=string.format('%d logistic robots (%d idle), %d construction robots',ln.all_logistic_robots,ln.available_logistic_robots,ln.all_construction_robots),
      line=string.format('logistic network #%d on %s holds %s%s',a.network,surface.name,#parts>0 and table.concat(parts,', ') or (a.item and 'no '..a.item or 'nothing'),
        #items>limit and string.format(' (+%d more items)',#items-limit) or '')}
  end
  -- The surface named (a planet, or a platform by its name) or the character's, throughout (Sonnet 12:20: stock with a
  -- position read the caller's surface and said 0 packs while 2,500 sat in a requester on the one named).
  local surface=p.surface
  if a.surface~=nil then
    local named=type(a.surface)=='string' and game.get_surface(a.surface)
    surface=named or M.on_surface(p,a.surface).surface
  end
  local platform=surface.platform~=nil
  -- places "all" (A9, Muse 2x: turrets and ammo past 128 tiles): every place on the surface, nearest first, paged.
  if a.places~=nil then
    assert(a.places=='all','places may be "all": every place on the surface, nearest first (page for more)')
    assert(a.item~=nil and a.radius==nil,'places "all" takes item and no radius')
    local b=a
    if surface~=p.surface and a.position==nil then b={}; for k,v in pairs(a) do b[k]=v end; b.position={x=0,y=0} end
    local out=stock.view(p,b,{surface=surface,whole=true})
    if surface~=p.surface and a.position==nil then out.nearest_to='(0,0) on '..surface.name..' (you are elsewhere; position= another centre)' end
    if out.pages and out.page<out.pages then out.next=string.format('stock {item: "%s", places: "all", page: %d%s}',a.item,out.page+1,a.surface and ', surface: "'..tostring(a.surface)..'"' or '') end
    return out
  end
  -- (batch33 A2, Astra 09:33) a planet's whole count (freight_audit's) is by the item's name: normal quality only
  local other_q=a.quality~=nil and a.quality~='normal'
  if a.surface~=nil and a.position==nil and not platform then
    assert(type(a.item)=='string' and prototypes.item[a.item],'stock {surface} takes item (an item name); with position it reads around a place there')
    assert(not other_q,string.format('quality %s: a planet\'s whole count (stock {item, surface}) is of normal quality only; stock {item, quality, surface, places: "all"} lists every place there holding %s of that quality, and stock {item, quality, surface, position} reads around a place',tostring(a.quality),a.item))
    local row=M.stock_planet_row(p,surface,a.item)
    local by_net=M.stock_by_network(p,surface,a.item)
    -- (d17 batch14 B2) stacks on the ground, in chunks our force sees now: counted apart, not in total; (d25 batch198
    -- QK2) of normal quality, as the whole count
    local okg,g=pcall(M.stores.on_ground,p.force,surface,a.item,{quality='normal'})
    local ground=okg and g.count>0 and g or nil
    local ground_line=ground and string.format('%d of normal quality on the ground in %d stack%s (%s), not in total',ground.count,ground.stacks,ground.stacks==1 and '' or 's',
      table.concat((function() local t={} for i,c in ipairs(ground.cells) do if i<=4 then t[i]=string.format('%d near (%d,%d)',c.count,math.floor(c.position.x),math.floor(c.position.y)) end end return t end)(),', '))
    return {item=a.item,surface=surface.name,total=row.total,on_ground=ground and ground.count or nil,on_ground_line=ground_line,by_network=#by_net>0 and by_net or nil,networks=row.networks,pads=row.pads,pads_in_networks=row.pads_in_networks,chests=row.chests,
      chests_holding=row.chests_holding,silos=row.silos,labs=row.labs,made_per_min=row.made_per_min,used_per_min=row.used_per_min,line=row.line..(ground_line and '; '..ground_line or ''),
      covered=string.format('the whole of %s: logistic networks, requester chests, landing pads, plain chests and landed pods, silos\' rockets, labs',surface.name),as_of=row.as_of,requesters=row.requesters,
      note='counted as freight_audit counts a planet; supply {item, surface} gives the belts, machines and inserters too'}
  end
  assert(surface==p.surface or a.position~=nil or platform or a.item~=nil,'stock on another surface takes item, or a position there')
  -- Without a radius, an item's total is the whole surface's (Sonnet, Muse 12:20-14:08: 0 within 128 tiles read as none
  -- at all, twice told to a teammate); the places listed stay the nearest within 128 tiles. A platform is read whole.
  if platform and a.radius==nil then return stock.view(p,a,{surface=surface,whole=true}) end
  local out=stock.view(p,a,{surface=surface})
  if a.item==nil or a.radius~=nil then return out end
  if other_q then out.quality_note=string.format('total: %s quality within 128 tiles (the whole-planet total counts normal quality only)',a.quality); return out end
  local row=M.stock_planet_row(p,surface,a.item)
  out.within_radius={radius=128,total=out.total,as_of=out.as_of}
  out.total=row.total
  out.as_of=row.as_of
  out.surface_line=row.line
  out.covered=string.format('total: the whole of %s (logistic networks, requester chests, landing pads, plain chests and landed pods, silos\' rockets, labs; machine outputs not counted); places: %s (%d there)',
    surface.name,out.covered,out.within_radius.total)
  -- (C7) a spoilable item: what spoils within 2 minutes, of the places read
  if out.spoils_within_2_min then out.spoil_note=string.format('%d of the %d within 128 tiles spoil within 2 minutes',out.spoils_within_2_min,out.within_radius.total) end
  out.summary=string.format('%d %s on %s as a whole (%s); within 128 tiles: %s',row.total,a.item,surface.name,
    tostring(row.as_of):match('^live') and 'live' or (tostring(row.as_of):match('^%d+s ago') or tostring(row.as_of)),
    out.summary or string.format('none in our machine outputs and chests'))
  return out
end
-- items (batch27 B3, Gemini: a platform's whole payload was a call an item): several items in one call, the same read
-- for each with the call's other arguments, a row each: item, total, line; one that fails is a row with its error.
M.stock_read=handlers.stock
-- (d24 batch164 QG1, viewer Aurora 13:15) an item that places a vehicle: the total is what is stored (as items); placed
-- (as vehicles) said beside it, on every surface (stores.lua placed)
function M.stock_one(p,a) return M.stores.stock_scope(p.force,a.item,M.stock_read(p,a)) end
function handlers.stock(p,a)
  -- unrequested (batch32 B4, reqrate.lua): requester and buffer chests holding items they do not request
  if a.unrequested~=nil then
    assert(a.unrequested==true,'unrequested is true')
    assert(a.item==nil or (type(a.item)=='string' and prototypes.item[a.item]),'item: an item name')
    local surface=p.surface
    if a.surface~=nil then surface=game.get_surface(a.surface) or M.on_surface(p,a.surface).surface end
    assert(surface,'no surface '..tostring(a.surface))
    local out=M.reqrate.unrequested(surface,p.force,a.item,a.page~=nil and integer(a.page,1,1,64,'page') or nil)
    out.surface=surface.name
    return out
  end
  if a.items==nil then return M.stock_one(p,a) end
  assert(type(a.items)=='table' and #a.items>=1 and #a.items<=32,'items: 1..32 item names')
  assert(a.item==nil and a.places==nil and a.network==nil,'items is one row an item: no item, places or network with it')
  local rows,lines={},{}
  for _,name in ipairs(a.items) do
    assert(type(name)=='string' and prototypes.item[name],'items: unknown item '..tostring(name))
    local args={}
    for k,v in pairs(a) do if k~='items' then args[k]=v end end
    args.item=name
    local ok,out=pcall(M.stock_one,p,args)
    if ok then
      local line=out.summary or out.line or out.surface_line or string.format('%s: %s',name,tostring(out.total))
      rows[#rows+1]={item=name,total=out.total,line=line}
      lines[#lines+1]=line
    else
      rows[#rows+1]={item=name,error=reason(out)}
      lines[#lines+1]=name..': '..reason(out)
    end
  end
  return {rows=rows,lines=lines,note='each row the read stock {item} gives with the same other arguments; stock {item} has the places'}
end
-- (d17 batch14 A11, Gemini) Each logistic network's hold of an item on a surface, one line each: providers (active and
-- passive provider chests), storage, other holders (buffer and requester chests, landing pads, roboports and the like).
-- At most 2000 members read per network; networks holding none are counted, not listed.
function M.stock_by_network(p,surface,item)
  local lines,none={},0
  for _,net in ipairs(p.force.logistic_networks[surface.name] or {}) do
    local c={provider=0,storage=0,other=0}
    local held={provider=0,storage=0,other=0}
    local kinds,seen,read={},{},0
    local function add(e)
      if read>=2000 or not e.valid or seen[e.unit_number or e] then return end
      seen[e.unit_number or e]=true; read=read+1
      local mode=pcall(function() return e.prototype.logistic_mode end) and e.prototype.logistic_mode
      local kind=(mode=='passive-provider' or mode=='active-provider') and 'provider' or mode=='storage' and 'storage' or 'other'
      local ok,n=pcall(function() return e.get_item_count(item) end)
      n=ok and n or 0
      if n>0 then
        c[kind]=c[kind]+n; held[kind]=held[kind]+1
        if kind=='other' then local label=mode or e.type; kinds[label]=(kinds[label] or 0)+n end
      end
    end
    for _,list in ipairs({'storages','providers','requesters'}) do
      local ok,members=pcall(function() return net[list] end)
      for _,e in ipairs(ok and members or {}) do add(e) end
    end
    if c.provider+c.storage+c.other==0 then none=none+1
    else
      local okp,pos=pcall(function() return net.cells[1].owner.position end)
      local other={}
      for k,n in pairs(kinds) do other[#other+1]=k..' '..n end
      table.sort(other)
      lines[#lines+1]=string.format('network #%d%s: providers %d (%d chests), storage %d (%d), other %d%s%s',net.network_id,
        okp and pos and string.format(' at (%g,%g)',math.floor(pos.x),math.floor(pos.y)) or '',c.provider,held.provider,c.storage,held.storage,c.other,
        #other>0 and ' ('..table.concat(other,', ')..')' or '',read>=2000 and ' (the first 2000 members read)' or '')
    end
  end
  if none>0 and #lines>0 then lines[#lines+1]=string.format('%d more network%s hold none',none,none==1 and '' or 's') end
  return lines
end
-- One planet's stock of an item as freight_audit counts it, kept 10 s (supply.lua reuse); as_of says live or its age
-- (Haiku 13:50, Sol 15:22: a total read as current when it was not).
function M.stock_planet_row(p,surface,item)
  return M.supply.reuse('stock_planet|'..p.force.name..'|'..surface.name..'|'..item,function() return M.packaudit.planet_row(p.force,surface,item) end)
end
-- eta_to (A2, Sonnet 01:50: waits at the silo for a ship several times a shift): each platform's ETA to that planet
-- through its schedule (freight.lua before_departure: the leg it flies at its cruise, its stops' waits and what sends
-- it on, the legs between), or why there is none; a platform there now says so.
function handlers.platforms(p,a)
  if a.eta_to==nil then return space.platforms(p,a) end
  assert(type(a.eta_to)=='string' and prototypes.space_location[a.eta_to],'eta_to is a planet or space location name')
  local rest={}
  for k,v in pairs(a) do if k~='eta_to' then rest[k]=v end end
  if rest.compact==nil then rest.compact=false end  -- (AZ4) each row's ETA: the rows, not the compact lines
  local out=space.platforms(p,rest)
  local lines={}
  for _,row in ipairs(out.platforms or {}) do
    local pl
    for _,each in pairs(p.force.platforms) do if each.valid and each.name==row.name then pl=each end end
    if pl then
      local w=M.freight.where(pl)
      local e
      if w.stopped and w.at==a.eta_to then e={line='there now ('..w.text..')',eta_s=0}
      else
        local ok,est,why=pcall(M.freight.before_departure,pl,a.eta_to)
        e=ok and est and {line=est.line,eta_s=est.eta_s} or {line='no estimate: '..tostring(ok and why or est)}
      end
      row.eta_to={planet=a.eta_to,eta_s=e.eta_s,line=e.line}
      lines[#lines+1]=string.format('%s (%s): to %s %s',row.name,w.text,a.eta_to,e.line)
    end
  end
  out.eta_to=lines
  -- (d22 batch96 BF1) the rows come a page at a time: the next page asks for the same ETA
  if out.next then out.next=string.format('platforms {eta_to: "%s", page: %d}',a.eta_to,out.page+1) end
  return out
end
-- platform {platform | name} as the help's `fh platform NAME` reads (A5, Gemini 21:29: fh call platform was an
-- unsupported action 14 times in shift25): the platforms read of that one, or of every one.
function handlers.platform(p,a)
  local args={}
  for k,v in pairs(a or {}) do if k~='name' then args[k]=v end end
  if a and a.name~=nil and a.platform==nil then args.platform=a.name end
  return handlers.platforms(p,args)
end
for _,name in ipairs({'requests','platform_create','platform_schedule','launch','land','drop'}) do
  handlers[name]=function(p,a) return space[name](p,a) end
end
-- A launch an agent ordered is the silo read's last launch (silo.lua), with who ordered it.
function M.launch_now(p,a) return handlers.launch(p,a) end
handlers.launch=function(p,a)
  if a.position==nil and a.unit_number==nil then error(M.launch_needs_silo(p,a),0) end
  -- wait_ready (Muse, twice: a queued launch failed at 45/50 parts): a rocket not ready yet is waited for as a wait_until
  -- rocket_ready at the silo; finish launches it in the tick the wait is met (then_launch).
  -- wait_platform (B2, Grok 22:50: a sleep chained into launch ended early on a tell, and the launch failed with the
  -- platform not in orbit yet): the named platform stopped over the silo's planet is waited for too, the same way.
  if a.wait_ready~=nil or a.timeout~=nil or a.wait_platform~=nil then
    assert(a.wait_ready==nil or type(a.wait_ready)=='boolean','wait_ready must be true or false')
    assert(a.wait_platform==nil or type(a.wait_platform)=='boolean','wait_platform must be true or false')
    assert(a.timeout==nil or a.wait_ready==true or a.wait_platform==true,'timeout goes with wait_ready or wait_platform')
    local rest={}
    for k,v in pairs(a) do if k~='wait_ready' and k~='timeout' and k~='wait_platform' then rest[k]=v end end
    -- wait_ready with a platform waits for the platform too (D11, Haiku 00:41: about once a launch the wait ended in a
    -- not-in-orbit error); wait_platform: false keeps the rocket alone.
    local wait_platform=a.wait_platform
    if wait_platform==nil and a.wait_ready and rest.platform~=nil then wait_platform=true end
    if a.wait_ready or wait_platform then
      local silo=remote_entity(p,{position=a.position,name=a.name,unit_number=a.unit_number})
      assert(silo.type=='rocket-silo',silo.name..' is not a rocket silo')
      local waits,words={},{}
      if a.wait_ready and silo.rocket_silo_status~=defines.rocket_silo_status.rocket_ready then
        waits[#waits+1]={['until']='rocket_ready',position=silo.position}
        words[#words+1]=string.format('the rocket at (%g,%g) is not ready',silo.position.x,silo.position.y)
      end
      if wait_platform then
        if rest.platform==nil then error('wait_platform needs platform=<name>: the platform the rocket goes to; nothing waited',0) end
        local planet=silo.surface.planet and silo.surface.planet.name or silo.surface.name
        local c={['until']='platform_arrived',platform=rest.platform,location=planet}
        local okc,there,saw=pcall(M.scheduler_api.condition,p,c)
        if not okc then error(tostring(there),0) end
        if not there then waits[#waits+1]=c; words[#words+1]=string.format('%s is not in orbit of %s yet (%s)',rest.platform,planet,tostring(saw)) end
      end
      if #waits>0 then
        -- What the launch itself would refuse for its arguments, said now rather than after the wait.
        if rest.platform==nil and rest.orbit~=true then error('give platform=<name>, or orbit=true to launch into orbit with no platform (cargo is lost unless it has launch products); nothing waited',0) end
        local running=state().active[p.index]
        if running then error('launch {wait_ready, wait_platform} waits as a timed action, and an action runs now ('..tostring(running.kind)..'): a queue step launch {wait_ready: true} waits in the queue',0) end
        local timeout=integer(a.timeout,36000,1,54000,'timeout (1..54000 ticks)')
        local cond=#waits==1 and waits[1] or {['until']='all',conditions=waits}
        local args={timeout=timeout}
        for k,v in pairs(cond) do args[k]=v end
        local out=handlers.wait_until(p,args)
        local now=state().active[p.index]
        if not now then return handlers.launch(p,rest) end
        now.then_launch=rest
        -- No tell ends it (a tell with wake: true and an urgent alert do; then nothing launches: outcome not_launched).
        now.wake_messages=false
        -- the platform's arrival as a state with its ETA (D11)
        local eta,no_eta
        for _,row in ipairs(out.wait_estimates or {}) do
          if type(row)=='table' and tostring(row.condition or ''):find('platform_arrived',1,true) then eta=row.eta_s; no_eta=row.no_estimate end
        end
        out.waiting_to_launch=string.format('%s%s: it launches when %s (within %d s); a tell does not end this wait (one with wake: true does, and an urgent alert: then nothing launches, outcome not_launched)',
          table.concat(words,'; '),eta and string.format(' (its arrival in about %d s)',math.floor(eta+0.5)) or no_eta and ' (no arrival estimate: '..no_eta..')' or '',
          #waits>1 and 'both hold' or 'that holds',math.floor(timeout/60))
        return out
      end
    end
    a=rest
  end
  -- min_cargo and arrived (Luna 15:20): read in this tick, the one the rocket goes in (rocketload.lua M.guard); a rocket
  -- not ready yet is refused by space.launch first.
  local checked
  if a.min_cargo~=nil or a.arrived~=nil then
    local silo=remote_entity(p,{position=a.position,name=a.name,unit_number=a.unit_number})
    if silo.type=='rocket-silo' and silo.rocket_silo_status==defines.rocket_silo_status.rocket_ready then checked=M.rocketload.guard(p,a,silo) end
  end
  -- Cargo loaded for another platform (D11, Haiku 00:41: a stale armed launch sent a rocket off; load_silo records the
  -- platform a load was for): refused, naming both, unless cargo_for: "any".
  assert(a.cargo_for==nil or a.cargo_for=='any','cargo_for is "any": launch whatever platform the cargo was loaded for')
  do
    local oks,silo=pcall(remote_entity,p,{position=a.position,name=a.name,unit_number=a.unit_number})
    local rec=oks and silo and silo.valid and M.silo_load_record(silo)
    if rec and a.cargo_for~='any' and a.platform~=nil and rec.platform~=a.platform then
      local inv=silo.get_inventory(defines.inventory.rocket_silo_rocket)
      local held={}
      for _,c in ipairs(inv and inv.get_contents() or {}) do held[#held+1]=c.name..'*'..c.count end
      if #held>0 then
        error(string.format('launch refused: the cargo aboard (%s) was loaded for platform %s by %s %d s ago, and this launch goes to %s; launch {platform: "%s"}, take the cargo out (transfer {inventory: "cargo", direction: "to_player"}), or cargo_for: "any" to send it anyway',
          table.concat(held,' '),tostring(rec.platform),tostring(rec.by),math.floor((game.tick-rec.tick)/60),tostring(a.platform),tostring(rec.platform)),0)
      end
    end
  end
  local launch_args=a
  if a.cargo_for~=nil then launch_args={}; for k,v in pairs(a) do if k~='cargo_for' then launch_args[k]=v end end end
  local out=space.launch(p,launch_args)
  out.checked=checked
  if out.launched then pcall(function() M.silo_loads()[remote_entity(p,{position=a.position,name=a.name,unit_number=a.unit_number}).unit_number]=nil end) end
  pcall(function()
    local silo=remote_entity(p,{position=a.position,name=a.name,unit_number=a.unit_number})
    if out.launched then M.silo.record(silo,{by=M.board.who(p),to=out.to,cargo=type(out.cargo)=='string' and out.cargo or nil,called=true}) end
    -- a load_silo auto_requests pause (B5): this rocket counted, the requests back on after the last
    if out.launched then out.auto_requests_back=M.silo_launched(p,silo) end
    -- The silo's switches as they stand after the call (auto_requests set, or a launch).
    out.settings=M.silo.settings(silo)
  end)
  return out
end
do local views={danger=true,pipe_gaps=true,belt_gaps=true,drill_sites=true,agriculture=true,map=true,nearest=true,craftable=true,scan=true,power=true,grid=true,rates=true,bottleneck=true,stock=true,platforms=true,labs=true,science=true,supply=true,sleep_check=true}
function handlers.observe(p,a)
  -- Newer read-only views travel as observe scopes: an already loaded
  -- bootstrap treats unknown action names as cached mutations.
  if a.scope then
    assert(views[a.scope],'unknown observe scope')
    return handlers[a.scope](p,a)
  end
  if a.platform then return M.platformview.read(p,a) end
  local mode=a.exclude_resources and 'none' or a.resources or 'summary'
  assert(mode=='summary' or mode=='tiles' or mode=='none','resources must be summary, tiles, or none')
  local radius=integer(a.radius,16,1,32,'radius')
  local limit=integer(a.limit,128,1,512,'limit')
  for _,key in ipairs({'entity_types','entity_names'}) do
    if a[key] then
      assert(type(a[key])=='table' and #a[key]>0 and #a[key]<=32,key..' requires 1..32 names')
      for _,name in ipairs(a[key]) do assert(type(name)=='string',key..' requires strings') end
    end
  end
  local ch=p.character
  local out={player={index=p.index, position=p.position, surface=p.surface.name, health=ch and ch.health, max_health=ch and ch.max_health, selected_gun_slot=ch and ch.selected_gun_index,
    inventory=ch and contents(p.get_main_inventory()) or nil, guns=ch and contents(p.get_inventory(defines.inventory.character_guns)) or nil,
    ammo=ch and contents(p.get_inventory(defines.inventory.character_ammo)) or nil, armor=ch and contents(p.get_inventory(defines.inventory.character_armor)) or nil,
    crafting_queue=ch and (p.crafting_queue or {}) or nil,body=not ch and 'none' or nil}, entities={}, tiles={}, truncated=false,
    active=active(p.index)}
  if a.group then out.entities=nil; out.groups={} end
  local origin=center(p,a)
  local candidates=M.find_named(p.surface,{position=origin, radius=radius,type=a.entity_types,name=a.entity_names})
  table.sort(candidates,function(x,y)
    local dx,dy=distance(origin,x.position),distance(origin,y.position)
    if dx ~= dy then return dx < dy end
    if x.position.x ~= y.position.x then return x.position.x < y.position.x end
    if x.position.y ~= y.position.y then return x.position.y < y.position.y end
    return x.name < y.name
  end)
  local resources,ground={},{}
  local unfiltered=not (a.entity_types or a.entity_names)
  -- Our own buildings and belts in chunks out of sight: as our force last saw them (fog below, fogmem.lua), not as
  -- they stand now; our ghosts there are read as they are (the map draws them in fog).
  -- fog_strict off (the default): read as before, and noted in present so fog lists only the remembered ones gone.
  local plat,strict,present=own_platform(p),M.fogmem.strict(),{}
  for _, e in ipairs(candidates) do
    local shown=plat or e.force~=p.force or e.type=='entity-ghost' or e.type=='tile-ghost' or e.type=='character' or
      p.force.is_chunk_visible(p.surface,chunk_of(e.position))
    if not shown and not strict and e.valid then present[e.name..'@'..e.position.x..','..e.position.y]=true end
    if distance(origin,e.position)<=radius and known(p,e) and (shown or not strict) then
      if e.type=='resource' and mode~='tiles' then
        if mode=='summary' then resources[#resources+1]=e end
      elseif e.type=='item-entity' and unfiltered then ground[#ground+1]=e
      elseif a.group then
        local g=out.groups[e.name]
        if g then g.count=g.count+1 else out.groups[e.name]={count=1,nearest=e.position} end
      elseif #out.entities >= limit then out.truncated=true
      else out.entities[#out.entities+1]=summary(e) end
    end
  end
  if mode=='summary' then
    out.resource_patches=resource_patches(resources)
  end
  out.ground_items=M.ground.summary(ground)
  if not plat then
    local okf,fog=pcall(M.fogmem.area,p.force,p.surface,{{origin.x-radius,origin.y-radius},{origin.x+radius,origin.y+radius}},limit,
      not strict and present or nil)
    if okf and fog then
      local names,types
      if a.entity_names then names={} for _,n in ipairs(a.entity_names) do names[n]=true end end
      if a.entity_types then types={} for _,t in ipairs(a.entity_types) do types[t]=true end end
      local shown=0
      for _,r in ipairs(fog.remembered) do
        local t=(prototypes.entity[r.name] or {}).type
        if distance(origin,r.position)<=radius and (not names or names[r.name]) and (not types or types[t]) then
          shown=shown+1
          if a.group then
            local g=out.groups[r.name]
            if g then g.count=g.count+1 else out.groups[r.name]={count=1,nearest=r.position,remembered=true} end
          elseif #out.entities>=limit then out.truncated=true
          else out.entities[#out.entities+1]={name=r.name,type=t,position=r.position,direction=r.direction,remembered=true,
            seen_s_ago=r.seen_s_ago,status_when_seen=r.status,lost_after_seen=r.lost_after_seen} end
        end
      end
      out.fog={line=fog.line,remembered_shown=shown,lost=fog.lost,lost_count=fog.lost_count,chunks_out_of_sight=fog.chunks_out_of_sight,note=fog.note}
    end
  end
  -- (d18 batch37 D1, Astra 17:29: lake-to-lake Nauvis defense planning from Aquilo) tile_runs: the charted tiles in the
  -- radius as runs along x, [{x,y,count,name}], row by row; tile_names keeps those names only (a lake's water, say)
  if a.tile_runs then
    local names
    if a.tile_names~=nil then
      assert(type(a.tile_names)=='table' and #a.tile_names>=1 and #a.tile_names<=32,'tile_names requires 1..32 tile names')
      names=a.tile_names
    end
    local cap=integer(a.tiles_limit,1024,1,4096,'tiles_limit')
    local by,ys,charted_chunk={},{},{}
    for _,tile in ipairs(p.surface.find_tiles_filtered{position=origin,radius=radius,name=names}) do
      local c=chunk_of(tile.position); local ck=c.x..','..c.y
      if charted_chunk[ck]==nil then charted_chunk[ck]=charted(p,tile.position) end
      if charted_chunk[ck] then
        local y=math.floor(tile.position.y)
        if not by[y] then by[y]={}; ys[#ys+1]=y end
        by[y][#by[y]+1]={x=math.floor(tile.position.x),name=tile.name}
      end
    end
    table.sort(ys)
    out.tile_runs,out.tile_count={},0
    for _,y in ipairs(ys) do
      local row=by[y]
      table.sort(row,function(u,v) return u.x<v.x end)
      local run
      for _,t in ipairs(row) do
        out.tile_count=out.tile_count+1
        if run and run.name==t.name and run.x+run.count==t.x then run.count=run.count+1
        elseif #out.tile_runs>=cap then out.tile_runs_truncated=true; run=nil
        else run={x=t.x,y=y,count=1,name=t.name}; out.tile_runs[#out.tile_runs+1]=run end
      end
    end
  end
  if a.tiles then
    for _,tile in ipairs(p.surface.find_tiles_filtered{position=origin,radius=radius}) do
      if p.force.is_chunk_charted(p.surface,chunk_of(tile.position)) then
        if #out.tiles >= integer(a.tiles_limit,4096,1,4096,'tiles_limit') then out.tiles_truncated=true; break end
        out.tiles[#out.tiles+1]={name=tile.name,position=tile.position}
      end
    end
  end
  -- Equipment rows are opt-in; the default is a compact name->count summary.
  local grid=ch and ch.grid
  out.player.equipment=ch and {} or nil
  if grid then
    for _,e in pairs(grid.equipment) do
      if a.equipment then
        out.player.equipment[#out.player.equipment+1]={name=e.name,position=e.position,quality=e.quality.name,energy=e.energy,shield=e.shield}
      else out.player.equipment[e.name]=(out.player.equipment[e.name] or 0)+1 end
    end
    if not a.equipment then out.player.robots=p.character.logistic_network and {available_construction=p.character.logistic_network.available_construction_robots,total_construction=p.character.logistic_network.all_construction_robots} or nil end
  end
  local r=p.force.current_research
  out.research=r and {name=r.name, progress=p.force.research_progress} or false
  out.research_queue={}
  for _,technology in ipairs(p.force.research_queue or {}) do out.research_queue[#out.research_queue+1]=technology.name end
  out.combat=M.combat_row(p.index,p)
  local q=state().queues and state().queues[p.index]
  out.queue=q and {revision=q.revision,paused=q.paused,pending=#q.pending,
    active=q.current and {id=q.current.id,action=q.current.action,started_tick=q.current.started_tick} or false} or false
  return out
end
end function handlers.stop(p) if scheduler then scheduler.pause(p.index,'stop') end; finish(p.index,'stopped'); stop_combat(p.index,'stopped'); return {stopped=true} end
function handlers.walk(p,a)
  local direction=directions[a.direction]
  assert(direction,'invalid compass direction')
  local ticks=integer(a.ticks,60,1,MAX_TICKS,'ticks')
  if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
  state().active[p.index]={kind='walk',direction=direction,until_tick=game.tick+ticks}
  return {until_tick=game.tick+ticks}
end
-- Engine pathfinding for the character's walks (pathing.lua): a ladder of
-- requests (padded box, a belt-free variant, the character's own box on the
-- tile, half- and quarter-tile grids) whose results arrive through
-- on_script_path_request_finished; until then the character waits in place.
-- When no level finds a route the walk ends as unreachable with why and the
-- nearest reachable point. The shared path cache is skipped: it can hand back
-- routes planned for other units.
M.pathing=require('pathing'){paths=function() state().paths=state().paths or {}; return state().paths end,
  accept=function(p,nav,path,avoided) return M.avoid.accept(p,nav,path,avoided) end,
  -- The walkable water in an area (M.water_kind): names, for an unreachable walk's why (friction4: Gemini read a walk
  -- into its packed island as the oil ocean being impassable).
  walkable_water=function(surface,area)
    local names,seen={},{}
    for _,t in pairs(surface.find_tiles_filtered{area=area,collision_mask='water_tile',limit=1024}) do
      local n=t.name
      if not seen[n] then seen[n]=true; if M.water_kind(n)=='walkable' then names[#names+1]=n end end
    end
    table.sort(names)
    return names
  end}
request_path=function(p,nav) return M.pathing.request(p,nav) end
-- Walks and drives around the enemy worms and spawners the map shows (avoid.lua): a
-- found path through one's reach becomes legs around it, each leg the engine's path.
M.avoid=require('avoid'){state=state,
  charted=function(force,surface,chunk) local pl=surface.platform if pl and pl.force==force then return true end return force.is_chunk_charted(surface,chunk) end,
  adopt=function(p,nav,path,avoided) if nav.vehicle then return M.vehicles.use(p,nav,path) end return M.pathing.use(p,nav,path,avoided) end,
  leg=function(p,nav)
    if not M.avoid.next_leg(p,nav) then return false end
    nav.path_level=0; nav.stalls=0; nav.stalled=0; nav.replans=0; nav.approach=nil
    -- A corner's step off a belt or rail is that leg's (A1, Opus 21:20: a step-off left set made every later leg read
    -- arrived at once, and the walk ended "arrived" 150 to 300 tiles short).
    nav.step_off=nil; nav.step_off_tick=nil
    if nav.vehicle then M.vehicles.request(p,nav) else request_path(p,nav) end
    return true
  end}
M.routecheck=require('routecheck'){avoid=M.avoid,pathing=M.pathing}
M.margin_probe=require('margin_probe'){avoid=M.avoid,paths=function() state().paths=state().paths or {}; return state().paths end}
M.REACH_ENDS={unreachable=true,blocked=true,arrived_near=true,timed_out=true,no_safe_route=true}
-- Ways walked (Haiku, d15 07:50: return walks refused no_safe_route after the walk out): each move_to that arrives keeps
-- the way it walked, a point every 8 tiles (at most 64), with its start, end and tick; the last 4 an agent walked, for
-- 30 minutes. A walk refused no_safe_route that starts within 16 tiles of where one of them ended and goes within 16
-- tiles of where it started gets that way back, the points reversed (walked_back): via points whose legs a move_to
-- checks again with the margins it is given.
function M.trail_point(action,pos)
  local t=action.trail_pts
  if not t then return end
  local l=t[#t]
  if (pos.x-l.x)^2+(pos.y-l.y)^2>=64 and #t<64 then t[#t+1]={x=math.floor(pos.x*2+0.5)/2,y=math.floor(pos.y*2+0.5)/2} end
end
function M.walked_record(index,action,outcome)
  if not (outcome=='arrived' or outcome=='arrived_near') or not action.trail_pts or #action.trail_pts<1 then return end
  local p=body(M.lookup(index))
  local here=p and p.valid and p.position
  if not here then return end
  local s=state()
  s.walked=s.walked or {}
  local list=s.walked[index] or {}
  s.walked[index]=list
  local pts={}
  for i,pt in ipairs(action.trail_pts) do pts[i]=pt end
  list[#list+1]={tick=game.tick,surface=action.surface_name,from=action.trail_pts[1],to={x=here.x,y=here.y},points=pts}
  while #list>4 do table.remove(list,1) end
end
function M.walked_back(index,here,goal,surface_name)
  local list=(state().walked or {})[index]
  for i=#(list or {}),1,-1 do
    local w=list[i]
    if game.tick-w.tick<=108000 and w.surface==surface_name and distance(w.to,here)<=16 and distance(w.from,goal)<=16 and #w.points>=2 then
      local via={}
      for k=#w.points-1,2,-1 do via[#via+1]=w.points[k] end
      -- at most 12 points, evenly kept
      if #via>12 then
        local keep={}
        for k=1,12 do keep[k]=via[math.floor((k-1)*(#via-1)/11)+1] end
        via=keep
      end
      local texts={}
      for k,v in ipairs(via) do texts[k]=string.format('{"x":%g,"y":%g}',v.x,v.y) end
      return {tick=w.tick,ago_s=math.floor((game.tick-w.tick)/60),from=w.from,to=w.to,via=via,
        line=string.format('you walked from (%g,%g) to (%g,%g) %ds ago; that way back as via points: move_to {"position":{"x":%g,"y":%g},"via":[%s]} (each leg is checked again with the margins given)',
          w.from.x,w.from.y,w.to.x,w.to.y,math.floor((game.tick-w.tick)/60),goal.x,goal.y,table.concat(texts,','))}
    end
  end
end
-- Staging for a walk that found no way (d17 batch14 A3, Muse 3x crossing the factory: to (-60,40) "no path ... nor to
-- anywhere within 48 tiles", vias guessed): the ways the team walked to arrival in the last 30 minutes on this surface
-- (each agent's last 4, a point every 8 tiles). A way that passes within 16 tiles of you and within 48 of the goal gives
-- via points (its stretch between them, in the order it goes); else the point of any way nearest the goal (within 48)
-- is a spot someone reached: a staging spot. {lines, via?, staging?} or nil.
function M.staging(here,goal,surface_name)
  local best_via,best_stage
  for idx,list in pairs(state().walked or {}) do
    local who
    pcall(function() local r=M.bots.record(idx); who=r and r.name end)
    if not who then pcall(function() who=game.get_player(idx).name end) end
    for _,w in ipairs(list) do
      if game.tick-w.tick<=108000 and w.surface==surface_name and #w.points>=1 then
        local pts={w.from}
        for _,q in ipairs(w.points) do pts[#pts+1]=q end
        pts[#pts+1]=w.to
        local ih,dh,ig,dg
        for i,q in ipairs(pts) do
          local a,b=distance(q,here),distance(q,goal)
          if not dh or a<dh then ih,dh=i,a end
          if not dg or b<dg then ig,dg=i,b end
        end
        if dg<=48 then
          if dh<=16 and ih~=ig and (not best_via or dg<best_via.dg) then
            local via={}
            local step=ih<ig and 1 or -1
            for i=ih,ig,step do via[#via+1]={x=math.floor(pts[i].x*2+0.5)/2,y=math.floor(pts[i].y*2+0.5)/2} end
            if #via>12 then local keep={} for k=1,12 do keep[k]=via[math.floor((k-1)*(#via-1)/11)+1] end via=keep end
            best_via={via=via,dg=dg,who=who,ago=math.floor((game.tick-w.tick)/60)}
          end
          if not best_stage or dg<best_stage.dg then best_stage={at=pts[ig],dg=dg,who=who,ago=math.floor((game.tick-w.tick)/60)} end
        end
      end
    end
  end
  if not (best_via or best_stage) then return nil end
  local out={lines={}}
  if best_via then
    local t={}
    for k,v in ipairs(best_via.via) do t[k]=string.format('{"x":%g,"y":%g}',v.x,v.y) end
    out.via=best_via.via
    out.lines[#out.lines+1]=string.format('%s walked a way %ds ago that passes near you and ends %.0f tiles from the goal: move_to {"position":{"x":%g,"y":%g},"via":[%s]}',
      best_via.who or 'a teammate',best_via.ago,best_via.dg,goal.x,goal.y,table.concat(t,','))
  end
  if best_stage then
    out.staging=best_stage.at
    out.lines[#out.lines+1]=string.format('%s reached (%g,%g) %ds ago, %.0f tiles from the goal: a staging spot (move_to there first)',
      best_stage.who or 'a teammate',best_stage.at.x,best_stage.at.y,best_stage.ago,best_stage.dg)
  end
  return out
end
-- move_to target (Astra, operator 07:55: a walk that ended unreachable while
-- already within transfer reach of its target broke an && chain): the walk
-- goes until the character is within reach of the entity, measured to its box
-- as the engine measures reach, and counts as arrived there. The entity by
-- unit_number or a position on its footprint, on a chunk the map draws; reach
-- transfer (the engine's own test: 10 tiles, ore, trees, plants and rocks 2.7), build
-- (build_distance) or tiles.
-- An entity by unit_number alone, on the character's surface. By number alone the game finds only prototypes flagged
-- get-by-unit-number (vehicles and the like; read on a private 2.0.77 server: an iron chest's own number found
-- nothing): others need their position too (form: the call's form with position, %d the number).
function M.by_unit_number(p,n,form)
  local ok,e=pcall(function() return game.get_entity_by_unit_number(n) end)
  e=ok and e or nil
  if not (e and e.valid) then
    error(string.format('the game finds no entity by unit_number %d alone (only vehicles and the like); give its position too: '..form,n,n),0)
  end
  if e.surface~=p.surface then error(string.format('unit_number %d (%s) is on %s; the character is on %s',n,e.name,e.surface.name,p.surface.name),0) end
  return e
end
function M.walk_target(p,a)
  local t=a.target
  assert(type(t)=='table','target is an entity: {position={x,y}} or {unit_number=N}, with optional name; reach is build, transfer or tiles')
  local e
  assert(t.unit_number==nil or type(t.unit_number)=='number','target.unit_number must be a number')
  if t.unit_number~=nil and t.position==nil and t.x==nil and t[1]==nil then
    e=M.by_unit_number(p,t.unit_number,'target={position={x,y},unit_number=%d}')
    if not charted(p,e.position) then error(string.format('target %s (%g,%g) is on a chunk the map has not charted',e.name,e.position.x,e.position.y),0) end
  else
    e=entity(p,{position=t.position or t,name=t.name,unit_number=t.unit_number},'walk')
  end
  local reach=a.reach==nil and 'transfer' or a.reach
  local r,kind
  if reach=='transfer' then r=M.reach_for(p,e); kind='transfer reach'
  elseif reach=='build' then r=p.build_distance or 10; kind='build reach'
  else
    assert(type(reach)=='number' and reach>=0.5 and reach<=64,'reach is build, transfer or a number of tiles 0.5..64 (to the entity\'s box)')
    r=reach; kind='reach'
  end
  local b=e.bounding_box
  local c={x=e.position.x,y=e.position.y}
  local centre=reach=='build' or nil
  return {entity=e,name=e.name,unit_number=e.unit_number,center=c,r=r,kind=kind,transfer=reach=='transfer' or nil,centre=centre,
    box=centre and {c.x,c.y,c.x,c.y} or {b.left_top.x,b.left_top.y,b.right_bottom.x,b.right_bottom.y}}
end
-- move_to {position, reach} (friction2: Sol wanted to stand within build reach of an empty spot, and target takes an
-- entity): the walk goes until the character is within reach of the point, and counts as arrived there; reach build
-- (build_distance, as build measures a position), transfer (reach_distance) or tiles 0.5..64.
function M.walk_point(p,a)
  local q=position(a.position)
  local r,kind
  if a.reach=='build' then r=p.build_distance or 10; kind='build reach'
  elseif a.reach=='transfer' then r=p.reach_distance or 10; kind='transfer reach'
  else
    assert(type(a.reach)=='number' and a.reach>=0.5 and a.reach<=64,'reach is build, transfer or a number of tiles 0.5..64 (to the point)')
    r=a.reach; kind='reach'
  end
  return {point=true,centre=true,name='position',center={x=q.x,y=q.y},r=r,kind=kind,box={q.x,q.y,q.x,q.y}}
end
-- Within the walk's reach of its target now: the distance to its box within reach less a quarter tile (a margin:
-- on a copy of world n a walk stopped where the engine's test first held, 10.0 tiles off), and for transfer the
-- engine's own test too (can_reach_entity). 'gone' when the entity is no more.
-- The distance a reach is measured by: to the entity's box, or to its centre (build reach, as build measures its
-- position: friction2, Sol 14:43: move_to arrived 9.7 tiles from a chest's edge, and the build there failed at 10.1 from
-- its centre), or to a point (move_to {position, reach}).
function M.reach_dist(pos,rt)
  if rt.centre or not rt.entity then return distance(pos,rt.center) end
  return M.box_distance(pos,rt.entity)
end
function M.in_reach(p,rt)
  if rt.point then return distance(p.position,rt.center)<=rt.r-0.25 end
  local e=rt.entity
  if not (e and e.valid) then return 'gone' end
  if M.reach_dist(p.position,rt)>rt.r-0.25 then return false end
  if rt.transfer then
    local ok,r=pcall(function() return p.can_reach_entity(e) end)
    if ok then return r==true end
  end
  return true
end
-- 'iron-chest (12.5,3.5): 8.7 tiles to its box (transfer reach 10)'.
function M.reach_text(p,rt)
  if rt.point then
    return string.format('(%g,%g): %.1f tiles (%s %g)',rt.center.x,rt.center.y,distance(p.position,rt.center),rt.kind,rt.r)
  end
  local e=rt.entity
  local d=e and e.valid and M.reach_dist(p.position,rt)
  return string.format('%s (%g,%g)%s (%s %g)',rt.name,rt.center.x,rt.center.y,
    d and string.format(': %.1f tiles to its %s',d,rt.centre and 'centre' or 'box') or ' is gone',rt.kind,rt.r)
end
-- A spot within the target's reach that the give-up found (pathing.lua: the
-- build spot, else the nearest reachable point), and whether it takes squeeze.
-- Other spots within reach of a target (D8): 16 round its box, just inside the reach, moved to the nearest spot the
-- character's box fits within 1.5 tiles, still within reach, not within 2 tiles of one tried; the nearest to you.
-- (d17 batch21 A5, Gemini: transfer and collect walks to a chest among machines stalled, closed_in_goal) the spots
-- within reach on rings at several distances, nearest you first; each checked against a closed pocket (pathing.region,
-- 16 tiles out, at most REACH_CHECKS of them): the first with a way out, else the nearest.
M.REACH_TRIES,M.REACH_CHECKS=6,8
function M.reach_ring(p,rt,tried)
  local e=rt.entity
  if rt.point or not (e and e.valid) then return nil end
  local b=rt.box
  local cx,cy=(b[1]+b[3])/2,(b[2]+b[4])/2
  local half=math.max(b[3]-b[1],b[4]-b[2])/2
  local cands={}
  for _,f in ipairs({1,0.75,0.5,0.3}) do
    for k=0,15 do
      local ang=2*math.pi*(k+(f<1 and 0.5 or 0))/16
      local q={x=cx+math.cos(ang)*(half+(rt.r-1.5)*f),y=cy+math.sin(ang)*(half+(rt.r-1.5)*f)}
      for _=1,3 do
        if M.reach_dist(q,rt)<=rt.r-0.5 then break end
        q={x=cx+(q.x-cx)*0.8,y=cy+(q.y-cy)*0.8}
      end
      local ok,free=pcall(function() return p.surface.find_non_colliding_position('character',q,1.5,0.25) end)
      q=ok and free or nil
      if q and M.reach_dist(q,rt)<=rt.r-0.25 then
        local near=false
        for _,t in ipairs(tried) do if distance(t,q)<2 then near=true; break end end
        for _,c in ipairs(cands) do if distance(c,q)<1 then near=true; break end end
        if not near then q.d=distance(p.position,q); cands[#cands+1]=q end
      end
    end
  end
  table.sort(cands,function(x,y) return x.d<y.d end)
  local c=p.character
  local okh,hf=pcall(function() return c and c.valid and M.pathing.half(c) end)
  for i=1,math.min(#cands,M.REACH_CHECKS) do
    local q=cands[i]
    local okr,r=pcall(M.pathing.region,p.surface,q,okh and hf or 0.2,{window=16,force=p.force,ignore=c})
    if not okr or not (r and r.closed) then return {x=q.x,y=q.y} end
  end
  return cands[1] and {x=cands[1].x,y=cands[1].y} or nil
end
function M.reach_spot(p,nav,rt)
  local e=rt.entity
  if not rt.point and not (e and e.valid) then return nil end
  local function within(q) return q and M.reach_dist(q,rt)<=rt.r-0.25 end
  local sp=nav.spot
  if sp and sp.pos and within(sp.pos) then return {x=sp.pos.x,y=sp.pos.y},(sp.searched or not sp.room) and true or nil end
  if within(nav.reachable) then return {x=nav.reachable.x,y=nav.reachable.y},nil end
end
-- via: points walked in order before position in one call (Opus, operator
-- 06:26: worm detours took 5-6 chained move_tos a trip). Each leg is a walk of
-- its own, pathfound and checked for enemies as a single move_to; a via point
-- counts as reached within VIA_WITHIN tiles (or the walk's tolerance when
-- larger); a leg that does not arrive ends the walk with its outcome.
M.VIA_MAX,M.VIA_WITHIN=16,1
function M.long_via(p,target)
  local from=p.position
  local d=distance(from,target)
  local n=math.ceil(d/500)
  assert(n-1<=M.VIA_MAX,string.format('movement target is %d tiles away; a walk takes via points at most 512 tiles apart and at most %d of them (%d tiles in all)',math.floor(d),M.VIA_MAX,512*(M.VIA_MAX+1)))
  local points,text={},{}
  for i=1,n-1 do
    local q={x=from.x+(target.x-from.x)*i/n,y=from.y+(target.y-from.y)*i/n}
    local ok,free=pcall(function() return p.surface.find_non_colliding_position('character',q,24,0.5) end)
    q=ok and free or q
    local chunk={x=math.floor(q.x/32),y=math.floor(q.y/32)}
    assert(p.force.is_chunk_charted(p.surface,chunk),string.format('movement target is %d tiles away; a walk takes via points at most 512 tiles apart, and the one on the way at (%g,%g) lies in a chunk the map has not charted: give via points',math.floor(d),math.floor(q.x),math.floor(q.y)))
    points[#points+1]={x=q.x,y=q.y}; text[#text+1]=string.format('(%g,%g)',math.floor(q.x*10+0.5)/10,math.floor(q.y*10+0.5)/10)
  end
  for i,q in ipairs(points) do
    local before=points[i-1] or from
    assert(distance(before,q)<=512,'the via points made on the way are more than 512 tiles apart: give via points')
  end
  return points,string.format('%d tiles away, past the 512 a leg takes: walked through via points %s (on the straight line, each moved to the nearest free spot)',math.floor(d),table.concat(text,' '))
end
function M.via_points(p,list,target)
  assert(type(list)=='table' and #list>=1 and #list<=M.VIA_MAX,'via takes 1..'..M.VIA_MAX..' points {x,y}, walked in order before position')
  local points,from={},p.position
  for i,raw in ipairs(list) do
    local q=position(raw)
    assert(distance(from,q)<=512,string.format('via point %d (%g,%g) must be within 512 tiles of the point before it',i,q.x,q.y))
    points[i]=q; from=q
  end
  assert(distance(from,target)<=512,'position must be within 512 tiles of the last via point')
  return points
end
-- The fields a leg's walk sets (navigate, pathing.lua, avoid.lua): cleared for the next leg.
M.LEG_FIELDS={'found','path_state','foes','why','escape','escape_stalled','escape_still','probe_id','probe_kind','probe_radius','path_level',
  'waypoints','waypoint','reachable','dig_from','dig_area','avoid_id','sidestep','reach','paths_failed','path_id','leg','escapes',
  'escape_first','blind','avoided','asked_tick','asked_from','stalled','stalls','replans','region','progress_tick','progress_gap',
  'progress_mark','path_length','escaped_to','dig','approach','no_progress','off_belt','pocket','retry_tick','step_off','step_off_tick',
  'previous_position','spot','trail_still','squeezed','search','squeeze_tried','unboxed','open_spot'}
-- A move_to ending arrived (or arrived_near) checked against its final goal (A1, Opus 21:20, 2-3 times a shift: arrived
-- while hundreds of tiles short, once between spawners): farther than its tolerance + 3 tiles (arrived_near: + 16, the
-- near walk's spot lies within build reach) and not within a target's reach, the walk ends stopped_short, saying where
-- it is, how far from the goal, and the leg it was on.
function M.short_check(p,action,outcome)
  local goal=action.via and action.via.final or action.foes and action.foes.goal or action.position
  if not (goal and p.position) then return outcome end
  if action.reach_target and M.in_reach(p,action.reach_target)==true then return outcome end
  if (action.near_walk or action.reach_walk) and outcome=='arrived_near' then return outcome end
  local d=distance(p.position,goal)
  local tol=(action.via and action.via.tolerance or action.foes and action.foes.tolerance or action.tolerance or 0.5)+(outcome=='arrived_near' and 16 or 3)
  if d<=tol then return outcome end
  local f=action.foes
  action.why=string.format('the walk stopped at (%.1f,%.1f), %d tiles from (%g,%g)%s%s',p.position.x,p.position.y,math.floor(d+0.5),goal.x,goal.y,
    f and f.legs and string.format(', after %d leg%s round enemies',f.legs,f.legs==1 and '' or 's') or '',
    action.off_belt and ' (it had stepped off a belt or rail there)' or '')
  return 'stopped_short'
end
-- (d17 batch23 A5, Opus: "to (8,545) it went by (-106,506)") last.route: the tiles walked (the trail, a point every 8
-- tiles) against the straight line, the point farthest off it, and what bent it: what the straight line crosses
-- (pathing.line_crossing at the call), the enemies gone round (avoided_enemies), a path off belts.
function M.route_note(last,action,here)
  local st=action.straight
  local pts=action.trail_pts
  local walked,far,fd=0,nil,0
  local a=pts[1]
  local b=action.via and action.via.final or action.position
  for i=2,#pts+1 do
    local q=pts[i] or here
    walked=walked+distance(pts[i-1],q)
    local dx,dy=b.x-a.x,b.y-a.y
    local L=dx*dx+dy*dy
    local t=L>0 and math.max(0,math.min(1,((q.x-a.x)*dx+(q.y-a.y)*dy)/L)) or 0
    local d=distance(q,{x=a.x+dx*t,y=a.y+dy*t})
    if d>fd then far,fd=q,d end
  end
  local why={}
  if st and (st.water or st.cliffs or st.solid) then why[#why+1]=st.text end
  if last.avoided_enemies then why[#why+1]=string.format('enemies\' reach: %d group%s (avoided_enemies)',#last.avoided_enemies,#last.avoided_enemies==1 and '' or 's') end
  if action.avoided then why[#why+1]='belts: the path off belts was taken (at most a quarter longer)' end
  local straight=st and st.length or distance(a,b)
  local bent=fd>=4
  last.route=string.format('walked %s%d tiles against %d in a straight line%s%s',#pts>=64 and 'at least ' or '',math.floor(walked+0.5),math.floor(straight+0.5),
    bent and string.format(', at most %d tiles off it (at (%d,%d))',math.floor(fd+0.5),math.floor(far.x+0.5),math.floor(far.y+0.5)) or ', on the straight line',
    bent and (#why>0 and '; it went round: '..table.concat(why,'; ') or '; nothing on the straight line, no enemy avoided: the engine\'s path') or '')
end
-- Leg i's goal: via point i, then the walk's position.
function M.via_leg(p,action,i)
  local v=action.via
  v.index=i; v.leg_tick=game.tick
  local final=i>#v.points
  action.position=final and v.final or v.points[i]
  action.tolerance=final and v.tolerance or math.max(M.VIA_WITHIN,v.tolerance)
  -- A move_to never ends on a belt (or a rail); a via point is passed, so only the last leg steps off one.
  action.off_belts=final or nil
end
-- One leg's line in last.legs: where to, how it ended, how long, why not, what it went around.
function M.via_record(action,outcome)
  local v=action.via
  local goal=action.foes and action.foes.goal or action.position
  local r={to={x=math.floor(goal.x*10+0.5)/10,y=math.floor(goal.y*10+0.5)/10},outcome=outcome,s=math.floor((game.tick-(v.leg_tick or game.tick))/6+0.5)/10}
  if action.foes then
    local t={}
    M.avoid.report(t,action)
    r.avoided_enemies=t.avoided_enemies; r.passed_within_margin=t.passed_within_margin
  end
  if outcome~='arrived' and outcome~='arrived_near' then r.why=action.why end
  v.legs[#v.legs+1]=r
end
-- A leg ended: the next one starts (true), or the walk ends with this outcome.
function M.via_next(p,action,outcome,index)
  local v=action.via
  M.via_record(action,outcome)
  if not (outcome=='arrived' or outcome=='arrived_near') or v.index>#v.points then return false end
  -- A queue step restarted after a pause resumes from the next via point (scheduler.lua).
  local q=(state().queues or {})[index]
  if q and q.current and q.current.args==v.args then q.current.via_done=v.index end
  -- (d18 batch36 B2) the next leg against enemy groups and units seen now: one in reach of it ends the walk short here
  local nxt=v.index+1
  local to=nxt>#v.points and v.final or v.points[nxt]
  local args=v.args or {}
  if v.mode and args.unsafe_goal==nil then
    local okl,lt=pcall(M.avoid.leg_threat,p,p.position,to,v.mode)
    if okl and lt then
      action.why=string.format('%s; stopped at (%.1f,%.1f) before it (leg %d of %d)',lt.line,p.position.x,p.position.y,nxt,#v.points+1)
      action.enemies_ahead=action.why
      return false,'enemies_ahead'
    end
  end
  for _,k in ipairs(M.LEG_FIELDS) do action[k]=nil end
  M.via_leg(p,action,nxt)
  if not action.direct then M.avoid.start(p,action,v.mode); request_path(p,action) end
  return true
end
-- last.legs: each leg walked, then the ones not walked.
function M.via_report(action)
  local v=action.via
  local legs={}
  for i,r in ipairs(v.legs) do legs[i]=r end
  for i=#v.legs+1,#v.points+1 do
    local goal=i>#v.points and v.final or v.points[i]
    legs[i]={to={x=goal.x,y=goal.y},outcome='not walked'}
  end
  return legs
end
-- New builds not working (batch29 B2, Opus: about 10 minutes each on a new furnace row): a ghost an agent places of a
-- requester or buffer chest, or of a machine on electricity, is watched; once robots have built it, a requester or
-- buffer in no logistic network, or a machine with no power or no pole, is one team line to that agent at once. A
-- watch ends when it is checked, or after WATCH_TICKS still a ghost. At most WATCH_MAX an agent.
M.BUILT_WATCH_TICKS,M.BUILT_WATCH_MAX=36000,256
M.BUILT_POWERED={['assembling-machine']=true,furnace=true,['mining-drill']=true,lab=true,inserter=true,beacon=true,roboport=true,radar=true}
function M.built_watch(p,name,ghost)
  local proto=prototypes.entity[name]
  if not proto then return end
  local mode=proto.type=='logistic-container' and proto.logistic_mode
  local kind=(mode=='requester' or mode=='buffer') and 'network' or (M.BUILT_POWERED[proto.type] and proto.electric_energy_source_prototype and 'power') or nil
  if not kind then return end
  local st=state()
  st.built_watch=st.built_watch or {}
  local list=st.built_watch[p.index] or {}
  st.built_watch[p.index]=list
  if #list>=M.BUILT_WATCH_MAX then return end
  list[#list+1]={name=name,kind=kind,position={x=ghost.position.x,y=ghost.position.y},surface=ghost.surface.name,tick=game.tick}
end
function M.built_tick()
  local st=state()
  for index,list in pairs(st.built_watch or {}) do
    local keep={}
    for _,w in ipairs(list) do
      local s=game.surfaces[w.surface]
      local found=s and s.find_entities_filtered{position=w.position,radius=0.3,name=w.name,limit=1}[1]
      if found and found.valid then
        local why
        if w.kind=='network' then
          if not found.logistic_network then why='is in no logistic network: nothing delivers to it' end
        else
          local stn=M.machine_status(found)
          if found.electric_network_id==nil then why='has no pole reaching it: no power'
          elseif stn=='no_power' then why='has no power (its network makes none)' end
        end
        if why then
          st.built_news=st.built_news or {}
          local news=st.built_news[index] or {}
          st.built_news[index]=news
          if #news<16 then news[#news+1]=string.format('%s (%g,%g)%s your robots built %s',w.name,w.position.x,w.position.y,w.surface~='nauvis' and ' on '..w.surface or '',why) end
        end
      elseif s and game.tick-w.tick<M.BUILT_WATCH_TICKS and s.find_entities_filtered{position=w.position,radius=0.3,ghost_name=w.name,type='entity-ghost',limit=1}[1] then
        keep[#keep+1]=w
      end
    end
    st.built_watch[index]=#keep>0 and keep or nil
  end
end
function M.built_lines(p,h)
  local st=state()
  local news=st.built_news and st.built_news[p.index]
  if not news then return {} end
  st.built_news[p.index]=nil
  return news
end
-- A queue step checked against the game at submit (batch29 A1, Sol: Swiftlet's emergency freight asked for section 8
-- on a hub with 7 sections; the queue paused on its first tick and nobody saw it for 3 minutes): only what a read
-- shows now and no earlier step of the plan changes: the platform a step names (unless an earlier step creates it),
-- and a requests section number against the sections its target has (unless an earlier requests step works on that
-- target). Positions are not checked: a plan often builds what its later steps use.
function M.step_read_check(p,action,args,prior)
  if type(args)~='table' then return end
  local name=args.platform
  if type(name)=='string' and action~='platform_create' then
    local made=false
    for _,st in ipairs(prior or {}) do if st.action=='platform_create' and type(st.args)=='table' and st.args.name==name then made=true end end
    local found
    for _,pl in pairs(p.force.platforms or {}) do if pl.valid and pl.name==name then found=pl end end
    assert(found or made,'no platform of ours named '..name..' (none of the plan\'s earlier steps creates it)')
    if action=='requests' and found and type(args.section)=='number' then
      local earlier=false
      for _,st in ipairs(prior or {}) do if st.action=='requests' and type(st.args)=='table' and st.args.platform==name then earlier=true end end
      local n=found.hub and found.hub.valid and (pcall(function() return found.hub.get_logistic_sections().sections_count end) and found.hub.get_logistic_sections().sections_count) or nil
      assert(earlier or not n or args.section<=n,string.format('section %d: the hub of %s has %d section%s (an earlier requests step on it would count; requests without section adds one)',
        args.section,name,n or 0,n==1 and '' or 's'))
    end
  end
end
-- A plan that paused on a step failing within its first FRESH ticks: a team line to its owner at once (A1), each
-- such failure once.
M.FRESH_FAIL=600
function M.queue_fresh_lines(p,h)
  local st=state()
  local out={}
  h.fresh_fail=h.fresh_fail or {}
  local keys={{'queues','queue'},{'remote_queues','remote queue'}}
  for name in pairs(st.platform_lanes or {}) do keys[#keys+1]={'lane_queues|'..name,'queue of platform lane '..name} end
  for _,k in ipairs(keys) do
    local q=(st[k[1]] or {})[p.index]
    local f
    for i=#(q and q.paused and q.history or {}),1,-1 do local e=q.history[i]; if e.ok==false and not e.order then f=e; break end end
    local plan=q and q.plan
    if f and plan and f.plan==plan.id and (f.finished_tick or 0)-(plan.tick or 0)<=M.FRESH_FAIL then
      local key=k[1]..'|'..tostring(plan.id)..'|'..tostring(f.id)
      if not h.fresh_fail[key] then
        h.fresh_fail[key]=true
        local why=type(f.result)=='table' and (f.result.reason or f.result.outcome) or '?'
        out[#out+1]=string.format('your %s paused %ds after plan %s was submitted: step %s %s failed: %s; queue_resume runs the rest',
          k[2],math.floor(((f.finished_tick or game.tick)-(plan.tick or game.tick))/60),tostring(plan.id),tostring(f.id),tostring(f.action),tostring(why))
      end
    end
  end
  return out
end
-- Route memory (batch28 C2, Opus: base to south copper failed unless given exact via points, 6 times): per agent, per
-- pair of 64-tile areas (where the walk started, its goal), the via points of the last move_to through them that
-- arrived (at most ROUTES a agent). A move_to with no via points that ends unreachable or no_safe_route between two
-- such areas runs once more through them (then_call, next tick); last.route_memory says which.
M.ROUTE_CELL,M.ROUTES=64,16
M.ROUTE_KEYS={'position','target','tolerance','within','avoid_enemies','unsafe_goal','combat','retreat','ticks','pathfind','reach','near','squeeze','unbox','mine_out','stay_in_turret_coverage','max_uncovered','route_retry'}
function M.route_args(a)
  local out={}
  for _,k in ipairs(M.ROUTE_KEYS) do out[k]=a[k] end
  return out
end
function M.walk_route_key(surface,from,to)
  local c=M.ROUTE_CELL
  return string.format('%s|%d,%d|%d,%d',tostring(surface),math.floor(from.x/c),math.floor(from.y/c),math.floor(to.x/c),math.floor(to.y/c))
end
function M.route_memory(index,action,outcome,last)
  local st=state()
  st.routes=st.routes or {}
  local mine=st.routes[index] or {}
  st.routes[index]=mine
  local from,to=action.route_from,action.via and action.via.final or action.position
  if not (from and to) then return end
  local key=M.walk_route_key(action.surface_name,from,to)
  if (outcome=='arrived' or outcome=='arrived_near') and action.via and #(action.via.points or {})>0 then
    local pts={}
    for i,q in ipairs(action.via.points) do pts[i]={x=q.x,y=q.y} end
    mine[key]={via=pts,tick=game.tick,from={x=from.x,y=from.y},to={x=to.x,y=to.y}}
    local n,oldest,ok_=0,nil,nil
    for k,r in pairs(mine) do n=n+1; if not oldest or r.tick<mine[oldest].tick then oldest=k end end
    if n>M.ROUTES and oldest then mine[oldest]=nil end
    last.route_memory=string.format('kept: the %d via points of this walk, for the next move_to from around (%d,%d) to around (%d,%d)',#pts,math.floor(from.x),math.floor(from.y),math.floor(to.x),math.floor(to.y))
  elseif (outcome=='unreachable' or outcome=='no_safe_route') and not action.via then
    local r=mine[key]
    if not r then return end
    if action.route_args and action.route_args.route_retry then
      last.route_memory=string.format('the kept route (via %d points, kept %s ago) ended %s too',#r.via,ago(game.tick-r.tick),outcome)
      return
    end
    local args={}
    for k,v in pairs(action.route_args or {}) do args[k]=v end
    args.via=r.via; args.route_retry=true
    st.then_calls=st.then_calls or {}
    st.then_calls[#st.then_calls+1]={index=index,call={action='move_to',args=args}}
    last.route_memory=string.format('ended %s; it walks again through the %d via points of your walk from around (%d,%d) to around (%d,%d) that arrived %s ago',
      outcome,#r.via,math.floor(r.from.x),math.floor(r.from.y),math.floor(r.to.x),math.floor(r.to.y),ago(game.tick-r.tick))
  end
end
function handlers.move_to(p,a)
  -- target: an entity's reach (M.walk_target); its centre is the walk's position.
  local rt
  if a.target~=nil or a.reach~=nil then
    assert(a.target~=nil or a.position~=nil,'reach goes with target (an entity: {position={x,y}} or {unit_number=N}) or position (a point)')
    assert(a.target==nil or a.position==nil,'give position or target, not both')
    assert(a.within==nil and a.tolerance==nil,'with reach, reach says how near (within/tolerance are for position)')
    rt=a.target~=nil and M.walk_target(p,a) or M.walk_point(p,a)
  end
  assert(a.near==nil or type(a.near)=='boolean','near must be true or false')
  local target=rt and rt.center or position(a.position)
  local via=a.via~=nil and M.via_points(p,a.via,target) or nil
  -- Past 512 tiles with no via (Haiku, every ~20 minutes: refused, no route summary): via points about 500 tiles apart
  -- on the straight line, each moved to the nearest spot a character fits in a chunk our force has charted.
  local via_added
  if not via and distance(p.position,target)>512 then
    via,via_added=M.long_via(p,target)
  end
  -- dry_run (Haiku, shift18 22:16; Luna): the route read now, nothing walked (routecheck.lua); a goal or via point in
  -- a weapon's reach is said, not refused.
  assert(a.dry_run==nil or type(a.dry_run)=='boolean','dry_run must be true or false')
  if a.dry_run then
    local mode=M.walk_mode(a)
    local points={{x=p.position.x,y=p.position.y}}
    for _,q in ipairs(via or {}) do points[#points+1]=q end
    points[#points+1]=target
    local out=M.routecheck.check(p,points,mode)
    out.position=target
    out.avoid_enemies=mode and M.avoid.describe(mode) or 'false: no check'
    local unsafe={}
    for i=2,#points do
      local c=mode and M.avoid.goal_check(p,points[i-1],points[i],mode)
      if c then unsafe[#unsafe+1]=M.avoid.goal_text(i==#points and 'goal' or 'via point '..(i-1),points[i],c) end
    end
    out.unsafe_goal=#unsafe>0 and table.concat(unsafe,'; ')..' (a live move_to refuses it without unsafe_goal: true)' or nil
    out.note='walked nothing; the running action and queue go on'
    out.via_added=via_added
    return out
  end
  -- The limit: ticks as given, else scaled to the planned route, straight lines through the via points at the
  -- character's speed, 1.5 times that for the path and 10 s more, at least 3600 (round1820a, Opus: 400-tile via trips
  -- timed out at the fixed 3600 four times in shift13 while walking fine).
  local route,from=0,p.position
  for _,q in ipairs(via or {}) do route=route+distance(from,q); from=q end
  route=route+distance(from,target)
  local ok_speed,speed=pcall(function() return p.character_running_speed end)
  speed=ok_speed and type(speed)=='number' and speed>=0.05 and speed or 0.15
  local scaled=math.max(3600,math.min(36000,math.ceil(route/speed*1.5)+600))
  local ticks=integer(a.ticks,scaled,1,36000,'ticks')
  local limit_text=string.format('%d ticks (%s)%s',ticks,ago(ticks),a.ticks~=nil and ', as given'
    or scaled>3600 and string.format(' for the planned route, %d tiles in straight lines%s at %.2f tiles a tick',math.floor(route+0.5),via and ' through the via points' or '',speed)
    or '')
  -- `within` reads naturally for "stop once in reach"; both mean the same. A target's path ends within its
  -- reach of the centre less a tile and a half (its box is nearer still).
  local tolerance=rt and math.max(0.25,math.min(10,rt.r-1.5)) or a.within or a.tolerance or 0.5
  assert(type(tolerance)=='number' and tolerance>=0.25 and tolerance<=10,'tolerance/within out of range 0.25..10')
  assert(a.squeeze==nil or type(a.squeeze)=='boolean','squeeze must be true or false')
  assert(a.unbox==nil or type(a.unbox)=='boolean','unbox must be true or false')
  -- A goal (or via point) inside a weapon's reach the map shows is refused unless unsafe_goal
  -- (avoid.lua goal_check; Astra, operator 07:26: died at (-25,335) on the way to (-10,350), in a nest's reach).
  -- unsafe_goal "moving" (d17 batch35 A3, Haiku): on only when every threat holding the goal moves (units, groups, an
  -- area under attack now), never past a worm, spawner or turret; the refusal names each threat counted.
  assert(a.unsafe_goal==nil or type(a.unsafe_goal)=='boolean' or a.unsafe_goal=='moving','unsafe_goal must be true, false or "moving"')
  local unsafe
  do
    local mode=M.walk_mode(a)
    local from=p.position
    local goals={}
    for i,q in ipairs(via or {}) do goals[i]={q=q,label='via point '..i} end
    goals[#goals+1]={q=target,label='goal'}
    for _,g in ipairs(mode and goals or {}) do
      local c=M.avoid.goal_check(p,from,g.q,mode)
      if c then
        local text=M.avoid.goal_text(g.label,g.q,c)
        local go=a.unsafe_goal==true or (a.unsafe_goal=='moving' and c.moving_only)
        if not go then
          error(text..(a.unsafe_goal=='moving' and ': unsafe_goal "moving" goes only when every threat moves' or '')
            ..': unsafe_goal: true to go anyway'..M.avoid.spot_text(g.q,c,mode),0)
        end
        unsafe=unsafe or {}; unsafe[#unsafe+1]=text..(a.unsafe_goal=='moving' and ' (unsafe_goal "moving")' or ' (unsafe_goal)')
      end
      from=g.q
    end
  end
  if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
  local action={kind='move_to',position=target,tolerance=tolerance,off_belts=true,
    until_tick=game.tick+ticks,last_position=p.position,stalled=0,replans=0,direct=a.pathfind==false,pocket_check=true,squeeze=a.squeeze==true or nil,unbox=a.unbox==true or nil,
    avoid_mode=M.walk_mode(a),reach_target=rt,near=a.near,limit_text=limit_text,
    trail_pts={{x=p.position.x,y=p.position.y}},surface_name=p.surface.name,
    -- (batch28 C2) the call's own arguments and where it started, for the route memory
    route_args=M.route_args(a),route_from={x=p.position.x,y=p.position.y},
    -- (d17 batch23 A5, Opus) the limit set again from each path found unless ticks was given; what the straight line crosses
    limit_auto=a.ticks==nil and {start=game.tick,cap=36000,speed=speed,text=limit_text} or nil,
    straight=M.pathing.line_crossing and (function() local pts={{x=p.position.x,y=p.position.y}} for _,q in ipairs(via or {}) do pts[#pts+1]=q end pts[#pts+1]=target
      local ok,r=pcall(M.pathing.line_crossing,p.surface,pts) return ok and r or nil end)()}
  -- The give-up's spots for a target count within its reach, to its box (pathing.lua).
  if rt then action.reach_r=rt.r; action.reach_box=rt.box; action.reach_label=rt.kind end
  if via then
    action.via={points=via,final=target,tolerance=tolerance,legs={},mode=M.walk_mode(a),args=a}
    M.via_leg(p,action,1)
  end
  -- combat: the combat channel fires at enemies in range for the walk (as
  -- shoot auto), so a walk into an attacked area shoots back (request #57).
  local combat
  if a.combat~=nil and a.combat~=false then
    local radius=a.combat==true and 20 or integer(a.combat,20,1,32,'combat radius')
    local equipped=kite.ammo_count(p)==0 and kite.auto_equip(p) or nil
    -- (d17 batch35 A2) the selected gun's empty ammo slot loaded from the main inventory, then kept loaded on the walk
    local sel=p.character and p.character.selected_gun_index
    local loaded=sel and M.ammoslots.load(p,sel) or nil
    if loaded then equipped=equipped and equipped..'; '..loaded or loaded end
    local ammo=kite.ammo_count(p)
    assert(ammo>0,'combat needs ammunition in the ammo slots and none is carried that fits a gun: craft firearm-magazine')
    local okg,gname=pcall(function() return p.get_inventory(defines.inventory.character_guns)[sel].name end)
    state().combat=state().combat or {}
    combat_targets()[p.index]=nil
    state().combat[p.index]={started=game.tick,until_tick=game.tick+ticks,auto=true,radius=radius,ammo_start=ammo,with_move=true,
      gun_used=sel and okg and gname and {slot=sel,name=gname} or nil}
    combat={auto=true,radius=radius,ammo=ammo,equipped=equipped}
  end
  state().active[p.index]=action
  -- retreat (retreat.lua): its own, or the standing retreat_guard.
  local back=M.retreat.arm(p,action,M.retreat.config(p,a,'move_to'))
  -- (retreat: false: no walk away either when a group shows up ahead: A2)
  action.no_retreat=a.retreat==false or nil
  local foes,in_reach
  if rt then in_reach=M.in_reach(p,rt)==true end
  if not action.direct then foes=M.avoid.start(p,action,M.walk_mode(a)); request_path(p,action) end
  -- avoid_enemies {distance: N}: the worms on the way whose range is more than N (routecheck.lua; Haiku, shift18 22:16).
  local under
  do
    local mode=M.walk_mode(a)
    if mode and mode.distance then
      local points={{x=action.last_position.x,y=action.last_position.y}}
      for _,q in ipairs(via or {}) do points[#points+1]=q end
      points[#points+1]=target
      local oku,u=pcall(M.routecheck.under_live,p,points,mode)
      under=oku and u or nil
    end
  end
  -- the rails the straight legs cross, and the trains on them (d17 batch14 A5)
  local crossings
  if p.surface.platform==nil then
    local pts={{x=p.position.x,y=p.position.y}}
    for _,q in ipairs(via or {}) do pts[#pts+1]=q end
    pts[#pts+1]=target
    local okc,c=pcall(M.routecheck.rail_crossings,p,pts)
    crossings=okc and c or nil
  end
  -- avoid_enemies false: what the straight legs come into, said (A1, Opus 02:09)
  local unchecked
  if a.avoid_enemies==false and p.surface.platform==nil then
    local pts={{x=p.position.x,y=p.position.y}}
    for _,q in ipairs(via or {}) do pts[#pts+1]=q end
    pts[#pts+1]=target
    local oku,u=pcall(M.routecheck.unchecked,p,pts)
    unchecked=oku and u or nil
  end
  return {until_tick=game.tick+ticks,limit=limit_text,position=target,pathfinding=not action.direct,straight_line=action.straight and action.straight.text or nil,combat=combat,avoid_enemies=foes and M.avoid.describe(foes.mode) or nil,under_range=under,
    enters_unchecked=unchecked,rail_crossings=crossings,
    retreat=back and M.retreat.line(back) or nil,
    via=via and #via or nil,legs=via and #via+1 or nil,via_added=via_added,unsafe_goal=unsafe and table.concat(unsafe,'; ') or nil,
    target=rt and {name=rt.name,position=rt.center,unit_number=rt.unit_number} or nil,reach=rt and string.format('%s %g',rt.kind,rt.r) or nil,
    in_reach=in_reach}
end
-- mine_out (Haiku 06:20: closed in among machines, last.mine_to_get_out named the way out and the agent mined it by
-- hand): a walk that ends closed in, or with no way that mining would open, marks the fewest blockers it names for
-- deconstruction, mines them by hand (a timed construct over them) and walks again once.
M.move_to_plain=handlers.move_to
-- stay_in_turret_coverage (turretcover.lua; d17 batch12 A3, Opus): the route inside our turrets' reach, as via points.
M.turretcover=require('turretcover'){}
function M.move_to_covered(p,a)
  if a.stay_in_turret_coverage==nil then return M.move_to_plain(p,a) end
  assert(type(a.stay_in_turret_coverage)=='boolean','stay_in_turret_coverage must be true or false')
  local args={}
  for k,v in pairs(a) do if k~='stay_in_turret_coverage' and k~='max_uncovered' then args[k]=v end end
  if not a.stay_in_turret_coverage then return M.move_to_plain(p,args) end
  assert(a.via==nil,'stay_in_turret_coverage plans the via points itself: no via')
  assert(a.position~=nil and a.target==nil,'stay_in_turret_coverage takes position')
  assert(p.surface.platform==nil,'stay_in_turret_coverage is for planets')
  local goal=position(a.position)
  assert(a.max_uncovered==nil or a.stay_in_turret_coverage,'max_uncovered goes with stay_in_turret_coverage')
  local via,line=M.turretcover.route(p,p.position,goal,a.max_uncovered~=nil and integer(a.max_uncovered,nil,0,256,'max_uncovered') or nil)
  if #via>0 then args.via=via end
  local out=M.move_to_plain(p,args)
  if type(out)=='table' then out.turret_coverage=line end
  local now=state().active[p.index]
  if now and now.kind=='move_to' then now.turret_coverage=line end
  return out
end
-- stand_off {target, reach}: the spot within reach of the target outside every reach the map shows, walked to as a
-- plain move_to (standoff.lua; d17 batch20 C3, Opus).
M.standoff=require('standoff'){position=position,charted=function(p,q) return charted(p,q) end,avoid=M.avoid}
function handlers.move_to(p,a)
  if a.stand_off~=nil then return M.standoff.move(p,a,function(b) return handlers.move_to(p,b) end) end
  if a.mine_out==nil then return M.move_to_covered(p,a) end
  assert(type(a.mine_out)=='boolean','mine_out must be true or false')
  local args={}
  for k,v in pairs(a) do if k~='mine_out' then args[k]=v end end
  local out=M.move_to_covered(p,args)
  local now=state().active[p.index]
  if a.mine_out and now and now.kind=='move_to' then
    now.mine_out=args
    if type(out)=='table' then out.mine_out='closed in or no way through: the fewest blockers it names are mined by hand (a timed construct over them), then it walks again once' end
  end
  return out
end
function M.mine_out_start(index,p,action)
  local s=state()
  local names,box={},nil
  for _,r in ipairs(action.mine_list or {}) do
    -- (the walk's list holds names and positions: the entity there)
    local e=r.valid~=nil and r or p.surface.find_entities_filtered{name=r.name,position=r.position,radius=0.2,limit=1}[1]
    if e and e.valid then
      pcall(function() e.order_deconstruction(p.force) end)
      names[#names+1]=string.format('%s (%g,%g)',e.name,e.position.x,e.position.y)
      local b=e.bounding_box
      box=box and {math.min(box[1],b.left_top.x),math.min(box[2],b.left_top.y),math.max(box[3],b.right_bottom.x),math.max(box[4],b.right_bottom.y)}
        or {b.left_top.x,b.left_top.y,b.right_bottom.x,b.right_bottom.y}
    end
  end
  if not box then return end
  local ok,err=pcall(handlers.construct,p,{area={left_top={x=math.floor(box[1])-1,y=math.floor(box[2])-1},right_bottom={x=math.ceil(box[3])+1,y=math.ceil(box[4])+1}}})
  local now=s.active[index]
  if s.last[index] then s.last[index].mining_out=ok and now and ('mining '..table.concat(names,' and ')..' by hand, then walking again') or ('mine_out could not start: '..reason(err)) end
  if ok and now and now.kind=='construct' then now.then_move=action.mine_out; now.queued=action.queued end
end
-- Hand-mining time for the character, including force and character bonuses.
local function hand_mining_ticks(p,e)
  local c=p.character
  local speed=c.prototype.mining_speed*(1+(c.character_mining_speed_modifier or 0)+(p.force.manual_mining_speed_modifier or 0))
  return math.max(1,math.ceil(e.prototype.mineable_properties.mining_time*60/speed))
end
-- A mined-out resource tile (Grok 03:20: a repeating mine step stalled its loop three times on one stone patch):
-- the resource this position held (name=, or remembered from an earlier mine there) is looked up within radius
-- (default 8) of it, a tile in reach first, else the nearest to the character. Positions remembered per agent.
-- A block: its helpers take no top-level local slots (tests/locals.lua).
do
local MINE_MEMORY=64
local function mine_key(pos) return string.format('%g,%g',pos.x,pos.y) end
local function remember_mined(p,pos,e)
  local s=state()
  s.mined_at=s.mined_at or {}
  local m=s.mined_at[p.index] or {order={},name={}}
  s.mined_at[p.index]=m
  local key=mine_key(pos)
  if m.name[key]==nil then
    m.order[#m.order+1]=key
    if #m.order>MINE_MEMORY then m.name[table.remove(m.order,1)]=nil end
  end
  m.name[key]=e.name
end
-- Space Age: some ores are not hand-mineable (tungsten-ore is hard-solid,
-- big mining drills only). Ore is taken through mine_entity, which would
-- not check, so check the character's resource categories here.
local function hand_minable(p,e)
  local hand=e.type=='resource' and p.character and p.character.prototype.resource_categories
  local category=hand and e.prototype.resource_category
  assert(not category or hand[category],e.name..' is '..tostring(category)..': a character cannot mine it by hand (a drill that mines '..tostring(category)..' can)')
end
local function next_tile(p,a,pos)
  local m=(state().mined_at or {})[p.index]
  local name=a.name or (m and m.name[mine_key(pos)])
  local proto=name and prototypes.entity[name]
  if not (proto and proto.type=='resource') then return nil end
  local radius=integer(a.radius,8,1,32,'radius')
  local best,best_reach,best_d
  for _,e in pairs(p.surface.find_entities_filtered{position=pos,radius=radius,name=name,type='resource'}) do
    if e.valid and visible(p,e.position) then
      local reach=p.can_reach_entity(e)
      local d=distance(p.position,e.position)
      if not best or (reach and not best_reach) or (reach==best_reach and d<best_d) then best,best_reach,best_d=e,reach,d end
    end
  end
  return best,name,radius
end
-- A position that is a tile of a building's footprint away from its centre (Muse 07:51: mine on what it took for an
-- empty tile mined its own assembler there): said, and mine refuses it unless the entity is named.
function M.mine_snap(a,e)
  local pos=position(a.position)
  if a.name or a.unit_number or e.type=='resource' or e.type=='item-entity' or e.type=='tree' or e.type=='simple-entity' then return nil end
  if math.abs(e.position.x-pos.x)<=0.5 and math.abs(e.position.y-pos.y)<=0.5 then return nil end
  return string.format('(%g,%g) is a tile of %s\'s footprint, its centre at (%g,%g)',pos.x,pos.y,e.name,e.position.x,e.position.y)
end
-- (d20 batch69 AE1, Sol #1642) an entity the game will not let a hand take now: refused with its name, unit and why
-- (railrun.lua: an elevated rail inside a support's run, a support carrying rails, the minable flag)
function M.mine_refuse_unminable(e)
  if e.minable then return end
  error(string.format('%s%s at (%g,%g) is not mineable now: %s',e.name,e.unit_number and (' '..e.unit_number) or '',e.position.x,e.position.y,
    M.railrun.why(e) or 'the game reads it not minable'),0)
end
function M.mine_refuse_snap(a,e)
  local snap=M.mine_snap(a,e)
  if snap then error(snap..': nothing mined; to mine it give name="'..e.name..'" (or its centre as the position); mine {dry_run: true} says what a position picks',0) end
end
function handlers.mine(p,a)
  -- Tiles laid by a player, by hand (tilemine.lua).
  if a.tiles~=nil then
    local reply,action=M.tilemine.handle(p,a)
    if action then
      if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
      state().active[p.index]=action
    end
    return reply
  end
  assert(a.positions==nil and a.area==nil,'mine positions and area require tiles: true (laid tiles only); entity mining takes one position {x,y} per call or queue step')
  assert(a.dry_run==nil or type(a.dry_run)=='boolean','dry_run must be true or false')
  -- An entity's dry run (Sol, shift19: reclaimed heat pipes froze an underground pipe and the only turbine on
  -- Aquilo): mine nothing; what its removal does to heat (heating.lua loss).
  if a.dry_run then
    local e=entity(p,a,true)
    -- (d20 batch69 AE1) the entity it picked, and whether the game lets a hand take it now and why not
    if not e.minable then
      return {dry_run=true,name=e.name,unit_number=e.unit_number,position={x=e.position.x,y=e.position.y},minable=false,
        why=M.railrun.why(e) or 'the game reads it not minable',in_reach=p.can_reach_entity(e),off_centre=M.mine_snap(a,e),note='mined nothing'}
    end
    local ok,loss=pcall(M.heating.loss,p.surface,p.force,{e})
    return {dry_run=true,name=e.name,unit_number=e.unit_number,position={x=e.position.x,y=e.position.y},minable=true,in_reach=p.can_reach_entity(e),
      heat_loss=ok and loss or nil,heat_error=not ok and tostring(loss) or nil,off_centre=M.mine_snap(a,e),note='mined nothing'}
  end
  -- Seen out of reach (autowalk.lua; Astra, shift12: a tree 5.4 tiles off refused, and as a queue step it paused the
  -- plan): within 32 tiles the character walks into reach first, then mines it.
  local walking=M.walk_first(p,'mine',a,nil,function(e) M.mine_refuse_unminable(e); M.mine_refuse_snap(a,e); hand_minable(p,e) end)
  if walking then return walking end
  local found,e=pcall(entity,p,a)
  local instead
  if not found then
    if not tostring(e):match('^entity not found at') then error(e,0) end
    local pos=position(a.position)
    local tile,name,radius=next_tile(p,a,pos)
    if not tile then
      if name then error(string.format('%s at (%g,%g) is mined out and no %s is left within %d tiles of it',name,pos.x,pos.y,name,radius),0) end
      error(e,0)
    end
    local gone=string.format('%s at (%g,%g) is mined out',name,pos.x,pos.y)
    if not p.can_reach_entity(tile) then
      local text=string.format('%s; the nearest %s within %d tiles is out of reach: %s',gone,name,radius,M.out_of_reach(p,tile))
      -- (autowalk.lua) walked into reach of it first; the call made there mines the nearest tile left.
      if a.walk~=false and not a.walked then
        local f=M.autowalk.entity_far(p,tile)
        f.text=text
        if M.autowalk.wanted('mine',a,{f}) then return M.autowalk.approach(p,'mine',a,{entity=tile},gone..'; the nearest: '..M.autowalk.line({f},1,f)) end
      end
      error(text,0)
    end
    instead={mined_out={x=pos.x,y=pos.y},name=name,position=tile.position,
      line=string.format('%s; mining %s at (%g,%g), %.1f tiles from it',gone,name,tile.position.x,tile.position.y,distance(pos,tile.position))}
    e=tile
  end
  friendly(p,e)
  M.mine_refuse_unminable(e)
  if not instead then M.mine_refuse_snap(a,e) end
  -- Where it mines: inside a worm's range, within 40 tiles of a spawner or in an area under attack now is refused unless
  -- unsafe_goal (round1950a item 1, Haiku 45h57m: a dry tree 38 tiles from a nest; big spitters killed it within 5 s).
  if not a.unsafe_goal then
    local mode=M.avoid.mode(a.avoid_enemies)
    local c=mode and M.avoid.goal_check(p,p.position,e.position,mode)
    if c then error(M.avoid.goal_text('the mining spot',e.position,c)..': unsafe_goal: true to mine anyway'..M.avoid.spot_text(e.position,c,mode),0) end
  end
  hand_minable(p,e)
  local ticks=integer(a.ticks,60,1,MAX_TICKS,'ticks')
  -- count (Grok, d15 06:20): units of a resource in one call; the time is what that many hand-mining cycles take.
  local count
  if a.count~=nil then
    assert(a.ticks==nil,'count and ticks: one or the other (count: units of a resource)')
    assert(e.type=='resource','count goes with a resource (ore, coal, stone); '..e.name..' is mined whole')
    count=integer(a.count,1,1,2000,'count')
  end
  if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
  local action={kind='mine',entity=e,until_tick=game.tick+ticks,products={},started=game.tick}
  -- What the character holds of the products now: last.moved is what it holds more of when the mining ends.
  action.held_before={}
  local okp,prods=pcall(function() return e.prototype.mineable_properties.products end)
  for _,pr in ipairs(okp and type(prods)=='table' and prods or {}) do
    if pr.type==nil or pr.type=='item' then
      local okc,n=pcall(function() return p.get_item_count(pr.name) end)
      action.held_before[pr.name]=okc and n or 0
    end
  end
  for _,product in ipairs(e.prototype.mineable_properties.products or {}) do
    if product.type=='item' then action.products[#action.products+1]=product.name end
  end
  -- An equipped vehicle (d23 batch120 CC1): what its item carries and what its inventories move into this one.
  local okv,_,vnames=pcall(M.grids.mining_line,e)
  for _,name in ipairs(okv and vnames or {}) do
    if action.held_before[name]==nil then local okc,n=pcall(function() return p.get_item_count(name) end); action.held_before[name]=okc and n or 0 end
  end
  if e.type=='resource' then
    for _,product in ipairs(e.prototype.mineable_properties.products or {}) do
      assert(product.type=='item','fluid resources cannot be mined by hand')
    end
    -- Setting mining_state does not survive a connected client's own input,
    -- so ore never progressed. Mine one unit per hand-mining cycle through
    -- the engine instead (same yield and speed as holding the mine button).
    action.cycle=hand_mining_ticks(p,e)
    action.next_mine=game.tick+action.cycle
    action.mined=0
    if count then
      action.count=count
      action.until_tick=game.tick+math.min(216000,math.ceil(count*action.cycle*1.1)+120)
    end
    -- The step's position names this resource from now on, also once its tile is gone.
    remember_mined(p,position(a.position),e)
    if instead then remember_mined(p,e.position,e) end
  else
    -- Buildings, trees, rocks and corpses need the entity selected, and the
    -- connected client's cursor hover overwrites selection every tick (the
    -- selection box flashes). Take exactly the hand-mining time instead and
    -- then mine through the engine, which applies normal products and space checks.
    action.done_tick=game.tick+hand_mining_ticks(p,e)
    -- A shorter duration could only ever expire unfinished.
    action.until_tick=math.max(action.until_tick,action.done_tick)
  end
  action.instead=instead
  state().active[p.index]=action
  -- LuaEntity cannot be serialized to JSON; only tick is returned (and the tile taken for a mined-out one).
  -- What mining it does to heat (Sol, shift19), said when it does anything.
  local okh,heat=pcall(M.heating.loss,p.surface,p.force,{e})
  heat=okh and heat and not heat.none and heat or nil
  return {until_tick=action.until_tick,instead=instead,count=action.count,cycle_ticks=action.count and action.cycle or nil,heat_loss=heat}
end
end
-- mine count: the nearest tile of a resource the character reaches now.
function M.mine_count_next(p,name)
  local reach=(p.resource_reach_distance or p.reach_distance or 10)+2
  local best,bd
  for _,t in ipairs(p.surface.find_entities_filtered{position=p.position,radius=reach,name=name,type='resource',limit=32}) do
    if t.valid and p.can_reach_entity(t) then
      local d=distance(p.position,t.position)
      if not bd or d<bd then best,bd=t,d end
    end
  end
  return best
end
-- Items on the ground within the character's pickup distance. shake5: a bot's
-- pickup returned ok and the plate stayed (a bot's character does not pick up
-- by itself), so the tick takes them and last reports what it took.
function handlers.pickup(p,a)
  -- Off belt lanes by hand (beltpick.lua; Grok, shift13 18:20).
  if a.belt~=nil then
    assert(a.belt==true,'belt must be true')
    return M.beltpick.pickup(p,a)
  end
  assert(a.item==nil and a.count==nil,'item and count go with belt=true (items on the ground: items, a list)')
  if a.area~=nil or a.radius~=nil or a.position~=nil or a.items~=nil then return M.ground.pickup(p,a) end
  local ticks=integer(a.ticks,30,1,MAX_TICKS,'ticks')
  local c=p.character
  local reach=c and c.valid and c.prototype and c.prototype.item_pickup_distance or 1
  local near=p.surface.find_entities_filtered{position=p.position,radius=reach,type='item-entity',limit=1}[1]
  assert(near,string.format('nothing to pick up within %g tiles of (%.1f,%.1f): stand on or next to the item (observe lists item-on-ground)',reach,p.position.x,p.position.y))
  if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
  state().active[p.index]={kind='pickup',until_tick=game.tick+ticks,reach=reach}
  return {until_tick=game.tick+ticks}
end
-- Repair (Astra 03:42: a patrol of repair steps logged 2481 "entity does not need repair" errors in a shift, which
-- hid the real failures). An undamaged target is a success: unchanged, last nothing_to_do, no repair tool needed.
-- positions or area: every damaged entity among them in one timed action, nearest first, walking to each, counted
-- as repaired against already full. A damaged target with no repair tool held still fails.
-- A block: its helpers take no top-level local slots (tests/locals.lua).
do
local MAX_REPAIR=64
local function damaged(e)
  local ok,hurt=pcall(function() return e.health~=nil and e.max_health~=nil and e.health<e.max_health end)
  return ok and hurt
end
local function has_health(e)
  local ok,yes=pcall(function() return e.health~=nil and (e.max_health or 0)>0 end)
  return ok and yes
end
-- Puts a repair tool in the cursor (from the inventory); true when it was borrowed.
local function hold_tool(p,a,why)
  if p.cursor_stack.valid_for_read then
    assert(p.cursor_stack.prototype.type=='repair-tool','cursor must hold a repair tool')
    return false
  end
  local tool=p.get_main_inventory().find_item_stack(a.item or 'repair-pack')
  assert(tool and tool.prototype.type=='repair-tool','no repair tool in inventory'..(why or ''))
  assert(p.cursor_stack.swap_stack(tool),'cannot hold repair tool')
  return true
end
-- Nothing to repair: the reply, and the last a finished action leaves (a --wait and a queue step see nothing_to_do).
local function unchanged(p,out)
  out.unchanged='not damaged'
  local s=state(); s.last=s.last or {}
  s.last[p.index]={kind='repair',outcome='nothing_to_do',tick=game.tick,unchanged=out.unchanged,already_full=out.already_full}
  return out
end
-- A list action's next target: the current one counts as repaired (worked on and now full), already full (full
-- before it was reached), or lost (gone).
function M.repair_next(p,action)
  local e=action.entity
  if e and not e.valid then action.lost=action.lost+1
  elseif e and action.working then action.repaired=action.repaired+1
  elseif e then action.already_full=action.already_full+1 end
  action.index=action.index+1; action.entity=action.targets[action.index]; action.working=nil; action.nav=nil
  if not M.bots.is(p) then p.repair_state={repairing=false,position=p.position} end
end
function M.repair_done(e) return not (e and e.valid) or not damaged(e) end
local function repair_list(p,a)
  assert(a.position==nil and a.radius==nil,'give position, positions or area: one of them')
  assert(a.positions==nil or a.area==nil,'give positions or area, not both')
  local found,errors={},{}
  if a.area~=nil then
    assert(type(a.area)=='table' and a.area.left_top and a.area.right_bottom,'area requires left_top and right_bottom')
    local lt,rb=position(a.area.left_top),position(a.area.right_bottom)
    assert(lt.x<rb.x and lt.y<rb.y and rb.x-lt.x<=128 and rb.y-lt.y<=128,'area must be nonempty and at most 128x128')
    for _,e in pairs(p.surface.find_entities_filtered{area={left_top=lt,right_bottom=rb},force=p.force}) do
      if e.valid and e.type~='character' and has_health(e) then found[#found+1]=e end
    end
    assert(#found>0,string.format('no entity of ours with health in (%g,%g)-(%g,%g)',lt.x,lt.y,rb.x,rb.y))
  else
    assert(type(a.positions)=='table' and #a.positions>=1 and #a.positions<=MAX_REPAIR,'positions requires 1..'..MAX_REPAIR..' entries')
    for _,pos in ipairs(a.positions) do
      local ok,e=pcall(function()
        local t=entity(p,{position=pos,name=type(pos)=='table' and pos.name or nil,unit_number=type(pos)=='table' and pos.unit_number or nil},true)
        friendly(p,t)
        return t
      end)
      if ok then found[#found+1]=e else errors[#errors+1]=reason(e) end
    end
  end
  local todo,full={},0
  for _,e in ipairs(found) do if damaged(e) then todo[#todo+1]=e else full=full+1 end end
  local out={targets=#found,damaged=#todo,already_full=full,failed=#errors>0 and #errors or nil,first_error=errors[1]}
  if #todo==0 then
    assert(#found>0,errors[1] or 'no target')
    return unchanged(p,out)
  end
  assert(#todo<=MAX_REPAIR,string.format('%d damaged entities; at most %d (a smaller area)',#todo,MAX_REPAIR))
  table.sort(todo,function(x,y) return distance(p.position,x.position)<distance(p.position,y.position) end)
  local ticks=integer(a.ticks,3600,1,36000,'ticks')
  -- A missing tool fails before the running action is touched.
  if not p.cursor_stack.valid_for_read then
    local tool=p.get_main_inventory().find_item_stack(a.item or 'repair-pack')
    assert(tool and tool.prototype.type=='repair-tool',string.format('no repair tool in inventory (%d of %d targets damaged)',#todo,#found))
  end
  if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
  local borrowed=hold_tool(p,a)
  state().active[p.index]={kind='repair',entity=todo[1],targets=todo,index=1,repaired=0,already_full=full,lost=0,unreached=0,
    borrowed_cursor=borrowed or M.bots.is(p),tool=a.item,until_tick=game.tick+ticks}
  out.until_tick=game.tick+ticks
  return out
end
function handlers.repair(p,a)
  assert(a.platform==nil and not (p.surface and p.surface.platform),'repair cannot reach a space platform: '..(space and space.REPAIR_NOTE or ''))
  if a.positions~=nil or a.area~=nil then return repair_list(p,a) end
  -- Seen first (health shows on hover), then reached: an undamaged target out of reach is unchanged too.
  local e=entity(p,a,true); friendly(p,e)
  assert(has_health(e),e.name..' has no health to repair')
  if not damaged(e) then return unchanged(p,{name=e.name,position=e.position,health=e.health}) end
  if not p.can_reach_entity(e) then error(M.out_of_reach(p,e),0) end
  local ticks=integer(a.ticks,60,1,MAX_TICKS,'ticks')
  if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
  local borrowed=hold_tool(p,a)
  -- A bot's cursor is invisible to it: always put the tool back afterwards.
  state().active[p.index]={kind='repair',entity=e,borrowed_cursor=borrowed or M.bots.is(p),tool=a.item,until_tick=game.tick+ticks}
  return {until_tick=game.tick+ticks}
end
-- A repair carried over a harness update (carry.lua): the outgoing runtime put the tool it borrowed back; it holds
-- one again (one started by an older runtime names its tool in the call it kept).
function M.rehold_tool(p,action)
  if p.cursor_stack.valid_for_read then return end
  local tool=action.tool or (type(action.call)=='table' and type(action.call.args)=='table' and action.call.args.item) or nil
  if hold_tool(p,{item=tool}) then action.borrowed_cursor=true end
end
end
-- Stock of the product our machines and chests hold within STOCK_RADIUS is stated with every craft; a player can
-- always hand-craft from their own inventory, so the craft goes ahead (d17 batch20 A1, Haiku: refused magazines over
-- 650 in requester chests, which stopped a rearm). check_stock: true (force='check') refuses a craft of at least
-- STOCK_REFUSE_S of hand time that the stock covers.
local STOCK_RADIUS,STOCK_REFUSE_S=64,3
M.STOCK_NEAR=25
local function craft_stock(p,name,count,force,notes)
  local recipe=p.force.recipes[name]
  local product
  for _,pr in ipairs(recipe.products or {}) do if pr.type=='item' then product=pr; break end end
  if not product then return end
  local s=stock.scan(p,product.name,{radius=STOCK_RADIUS})
  if s.total==0 then return end
  local line=stock.line(s)
  local wanted=count*(product.amount or product.amount_max or 1)
  local near=0
  for _,x in ipairs(s.places) do
    if (x.position.x-p.position.x)^2+(x.position.y-p.position.y)^2<=M.STOCK_NEAR*M.STOCK_NEAR then near=near+x.count end
  end
  if force=='check' and s.total>=wanted and (recipe.energy or 0.5)*count/hand_speed(p)>=STOCK_REFUSE_S then
    local chests={}
    for _,x in ipairs(s.places) do
      local t=x.entity and x.entity.valid and x.entity.type
      if (t=='container' or t=='logistic-container' or t=='cargo-landing-pad') and #chests<4 then
        chests[#chests+1]=string.format('%s (%g,%g) holds %d',x.name,x.position.x,x.position.y,x.count)
      end
    end
    error('not crafted: '..line..(#chests>0 and '; stocked in '..table.concat(chests,'; ') or '')
      ..'; (check_stock: true counts stock within '..STOCK_RADIUS..' tiles)'
      ..'; craft without check_stock hand-crafts from your inventory; queue step on_fail: abort (default) pauses the plan, skip continues with the next step, goto:<label> continues at that pending label; skipping does not acquire items',0)
  end
  if s.total>=wanted and force~=true then line=line..string.format(' (crafted from your inventory anyway: %d of it within %d tiles of you; check_stock: true refuses a craft that stock within %d tiles covers)',near,M.STOCK_NEAR,STOCK_RADIUS) end
  notes[product.name]=line
end
-- Why a hand craft started fewer than asked: the raw items it runs out of,
-- following hand-craftable intermediates (gears, cables) down like the
-- engine does, with where our factory holds each.
-- Whether a crafter with these categories takes the recipe: its own category
-- or one of its additional ones (Space Age: pressing, electronics, ...).
local function takes(categories,recipe)
  if categories[recipe.category or 'crafting'] then return true end
  for _,extra in ipairs(recipe.additional_categories or {}) do if categories[extra] then return true end end
  return false
end
local function hand_recipe(p,item)
  local recipe=p.force.recipes[item]
  local categories=p.character and p.character.prototype.crafting_categories or {}
  if recipe and recipe.enabled and takes(categories,recipe) then return recipe end
end
-- Where the team keeps a missing ingredient (d17 batch19 B4, Haiku: a craft short of iron named "nearest 1 at
-- (28.5,67.5)", most of the stock in requester chests holding it for their own requests, and nothing at all past 128
-- tiles): the nearest places of scan (stock.scan within 128 tiles) that can spare the shortfall, up to 3 (a requester
-- or buffer chest only what it holds over its request, robots' pickup reservations off); else the nearest that can
-- spare some; else each logistic network on your surface holding it and where its robots would take it from.
-- (d19 batch41 A1, Sonnet: ingredient_gap on an area failed "attempt to index local 'e'") a scan's ground stacks have no
-- entity: they spare all they hold, under their own name; a place whose entity went invalid is passed over.
function M.where_kept(p,item,need,scan)
  local good,some=({}),({})
  for _,x in ipairs(scan and scan.places or {}) do
    local e=x.entity
    local free=x.count
    if e and not e.valid then free=0 end
    local okr,r=pcall(M.supply.reserved,e,item)
    if e and okr and r then free=free-r end
    local okm,mode=pcall(function() return e.prototype.logistic_mode end)
    local over=''
    if e and okm and (mode=='requester' or mode=='buffer') then
      local okp,pt=pcall(function() return e.get_logistic_point(defines.logistic_member_index.logistic_container) end)
      local min=okp and pt and M.reqchest and M.reqchest.request(pt,item) or 0
      free=free-min; over=min>0 and ' over its request' or ''
    end
    if free>0 then
      local t=string.format('%s (%g,%g) %d tiles, %d free%s',x.name or (e and e.name),x.position.x,x.position.y,math.floor(x.distance+0.5),free,over)
      if free>=need and #good<3 then good[#good+1]=t elseif free<need and #some<3 then some[#some+1]=t end
    end
  end
  if #good>0 then return 'enough at '..table.concat(good,'; ') end
  if #some>0 then return 'some at '..table.concat(some,'; ') end
  local nets={}
  for _,ln in ipairs(p.force.logistic_networks[p.surface.name] or {}) do
    local okn,n=pcall(function() return ln.get_item_count(item) end)
    if okn and n and n>0 and #nets<2 then
      local okq,pick=pcall(function() return ln.select_pickup_point{name=item,position=p.position} end)
      local o=okq and pick and pick.owner
      nets[#nets+1]=string.format('logistic network #%d holds %d%s',ln.network_id,n,o and o.valid and string.format(' (robots would take it from %s (%g,%g), %d tiles)',
        o.name,o.position.x,o.position.y,math.floor(distance(p.position,o.position)+0.5)) or '')
    end
  end
  if #nets>0 then return 'none to spare within 128 tiles; '..table.concat(nets,'; ') end
  return 'none of ours to spare within 128 tiles or in a logistic network on '..p.surface.name
end
do local function craft_shortfall(p,name,count,notes)
  local have,short={},{}
  local inv=p.get_main_inventory()
  local function walk(recipe,n,depth)
    for _,ing in ipairs(recipe.ingredients or {}) do
      if ing.type=='item' then
        local need=ing.amount*n
        local held=have[ing.name] or inv.get_item_count{name=ing.name,quality='normal'}
        local use=math.min(held,need); have[ing.name]=held-use
        local missing=need-use
        local sub=missing>0 and depth<4 and hand_recipe(p,ing.name)
        local made=0
        for _,pr in ipairs(sub and sub.products or {}) do if pr.name==ing.name then made=pr.amount or pr.amount_max or 1 end end
        if made>0 then walk(sub,math.ceil(missing/made),depth+1)
        elseif missing>0 then
          local row=short[ing.name] or {need=0,held=inv.get_item_count{name=ing.name,quality='normal'}}
          short[ing.name]=row; row.need=row.need+missing
        end
      end
    end
  end
  walk(p.force.recipes[name],count,0)
  local out={}
  for item,row in pairs(short) do
    local oks,scan=pcall(stock.scan,p,item,{radius=128})
    local okw,where=pcall(M.where_kept,p,item,row.need,oks and scan or nil)
    out[#out+1]=string.format('%s short %d (held %d)%s',item,row.need,row.held,okw and where and '; '..where or '')
    local ok,line=pcall(function() return oks and stock.line(scan) end)
    if ok and line and notes then notes[item]=line end
  end
  table.sort(out)
  return #out>0 and table.concat(out,', ') or nil
end
local function begin_craft(p,recipe,count,force,notes,shorts,fromq)
  assert(type(recipe)=='string' and p.force.recipes[recipe] and p.force.recipes[recipe].enabled,'recipe is unavailable')
  -- Say why a machine-only recipe fails (shake3: Grok's engine-unit read
  -- "not hand-craftable now" with force and the ingredients held).
  local r,categories=p.force.recipes[recipe],p.character and p.character.prototype.crafting_categories
  if categories and not takes(categories,r) then
    error(string.format('%s (category %s) cannot be hand-crafted by a character; an assembling machine can make it (configure recipe=%s, then feed it)',recipe,r.category or 'crafting',recipe),0)
  end
  count=integer(count,1,1,1000,'count')
  craft_stock(p,recipe,count,force,notes)
  -- An ingredient still in the hand-craft queue (its own entries, not another
  -- craft's) is not counted by the game, which crafts it again from raw
  -- (Astra 11:01: 75 electronic circuits queued, then laser turrets made 20
  -- more). Up to the shortfall those queued crafts are cancelled first: their
  -- ingredients come back and the game crafts them again as this craft's own,
  -- none extra; any it does not use go back in the queue.
  local cancelled={}
  local inv=p.get_main_inventory()
  local function prereq(name)
    local n=0
    for _,entry in ipairs(p.crafting_queue or {}) do if entry.recipe==name and entry.prerequisite then n=n+entry.count end end
    return n
  end
  for _,ing in ipairs(r.ingredients or {}) do
    local short=ing.type=='item' and ing.amount*count-(inv and inv.get_item_count{name=ing.name,quality='normal'} or 0) or 0
    -- (the hand recipe named as the item, as hand_recipe finds it)
    local sub=short>0 and hand_recipe(p,ing.name)
    local name=ing.name
    local per=0
    for _,pr in ipairs(sub and sub.products or {}) do if pr.name==ing.name then per=pr.amount or pr.amount_max or 1 end end
    if per>0 then
      local queue=p.crafting_queue or {}
      local queued=0
      for _,entry in ipairs(queue) do if entry.recipe==name and not entry.prerequisite then queued=queued+entry.count end end
      local left=math.min(math.ceil(short/per),queued)
      local crafts=left
      for i=#queue,1,-1 do
        local entry=queue[i]
        if left>0 and entry.recipe==name and not entry.prerequisite then
          local n=math.min(left,entry.count)
          if pcall(function() p.cancel_crafting{index=entry.index or i,count=n} end) then left=left-n end
        end
      end
      if crafts-left>0 then cancelled[#cancelled+1]={recipe=name,item=ing.name,crafts=crafts-left,per=per,queued=queued*per,before=prereq(name)} end
    end
  end
  local started=p.begin_crafting{recipe=recipe,count=count}
  for _,c in ipairs(cancelled) do
    local used=math.min(c.crafts,prereq(c.recipe)-c.before)
    local back=c.crafts-used
    if back>0 then pcall(function() p.begin_crafting{recipe=c.recipe,count=back} end) end
    if fromq then
      fromq[c.item]=string.format('%d of the %d queued go into %s (the game crafts them again as its ingredients: none extra)%s',
        used*c.per,c.queued,recipe,back>0 and string.format('; %d not used, queued again as before',back*c.per) or '')
    end
  end
  if started<count and shorts then shorts[recipe]=craft_shortfall(p,recipe,count-started,notes) or 'not hand-craftable now' end
  for _,product in ipairs(p.force.recipes[recipe].products or {}) do
    if product.type=='item' then survey.log_hand('crafted',product.name,started*(product.amount or product.amount_max or 1)) end
  end
  return started
end
-- What a hand craft costs: seconds of character crafting for what was just
-- queued, the whole queue's backlog, and how many of our assemblers already
-- run each recipe (surface-wide).
local function craft_cost(p,started)
  local hand,assemblers=0,{}
  local counts={}
  for _,e in pairs(p.surface.find_entities_filtered{type='assembling-machine',force=p.force}) do
    local ok,r=pcall(e.get_recipe); if ok and r then counts[r.name]=(counts[r.name] or 0)+1 end
  end
  for name,n in pairs(started) do
    local recipe=p.force.recipes[name]
    hand=hand+(recipe and recipe.energy or 0.5)*n
    assemblers[name]=counts[name] or 0
  end
  return math.ceil(hand/hand_speed(p)),math.ceil((crafting_left(p))),assemblers
end
-- The best assembler this force can build that takes the recipe's category.
local ASSEMBLERS={'assembling-machine-3','assembling-machine-2','assembling-machine-1'}
local function best_assembler(p,recipe)
  for _,name in ipairs(ASSEMBLERS) do
    local proto=prototypes.entity[name]
    local unlocked=p.force.recipes[name] and p.force.recipes[name].enabled
    if proto and unlocked and takes(proto.crafting_categories or {},recipe) then
      local ok,speed=pcall(function() return proto.get_crafting_speed() end)
      return name,ok and speed or proto.crafting_speed or 1
    end
  end
end
-- Facts that make a large hand craft's cost visible: the backlog the
-- character's queued work may wait on, and what a machine would take instead.
local HAND_BACKLOG_S=30
local function craft_facts(p,out,started)
  if out.queue_s>=HAND_BACKLOG_S then
    out.blocks=string.format('~%ds of hand crafting queued (this: ~%ds); a construct needing these items waits for them',out.queue_s,out.hand_s)
  end
  for name,n in pairs(started) do
    local recipe=p.force.recipes[name]
    local machine,speed=nil,nil
    if recipe and n>0 and (out.assemblers[name] or 0)==0 then machine,speed=best_assembler(p,recipe) end
    if machine then
      local items=0
      for _,product in ipairs(recipe.products or {}) do
        if product.name==name or #recipe.products==1 then items=items+n*(product.amount or product.amount_max or 1) end
      end
      out.no_assembler=out.no_assembler or {}
      out.no_assembler[name]=string.format('none of our assemblers is set to %s; one %s makes these %d in ~%ds without the character',
        name,machine,items>0 and items or n,math.ceil((recipe.energy or 0.5)*n/speed))
    end
  end
  return out
end
-- A spoilable hand craft (batch28 C1, Grok: 40 yumako-processing crafts, and the mash spoiled before the bacteria
-- batch used it, 3 times): when the first held stack of a spoilable ingredient spoils, against when each craft would
-- finish (the hand queue ahead, then each craft's time at the character's crafting speed): how many finish before
-- it; and how long each spoilable product lasts fresh once it lands (its prototype's spoil time). nil when neither.
function M.craft_spoil(p,name,count)
  local recipe=type(name)=='string' and p.force.recipes[name]
  if not recipe then return nil end
  local function spoil_ticks(n) local ok,t=pcall(function() return prototypes.item[n].get_spoil_ticks() end); return ok and type(t)=='number' and t>0 and t or nil end
  local inv=p.get_main_inventory()
  local first,item
  for _,ing in ipairs(recipe.ingredients or {}) do
    if ing.type~='fluid' and spoil_ticks(ing.name) then
      for i=1,inv and #inv or 0 do
        local st=inv[i]
        if st.valid_for_read and st.name==ing.name then
          local ok,t=pcall(function() return st.spoil_tick end)
          if ok and type(t)=='number' and t>0 and (not first or t<first) then first,item=t,ing.name end
        end
      end
    end
  end
  local products={}
  for _,pr in ipairs(recipe.products or {}) do
    local t=pr.type~='fluid' and spoil_ticks(pr.name)
    if t then products[#products+1]=string.format('%s lasts %ds fresh once it lands (a fresh one; made from part-spoiled ingredients, less)',pr.name,math.floor(t/60)) end
  end
  if not first and #products==0 then return nil end
  local per=(recipe.energy or 0.5)/hand_speed(p)
  local ahead=crafting_left(p)
  local fits=count
  if first then fits=math.max(0,math.min(count,math.floor(((first-game.tick)/60-ahead)/per))) end
  return {fits=fits,item=item,spoils_in=first and math.floor((first-game.tick)/60) or nil,per=per,ahead=ahead,products=products}
end
function handlers.craft(p,a)
  local notes,shorts={},{}
  if not a.recipes then
    local fromq={}
    assert(a.check_stock==nil or type(a.check_stock)=='boolean','check_stock must be true or false')
    assert(a.spoiling==nil or type(a.spoiling)=='boolean','spoiling must be true or false')
    -- (C1) a spoilable ingredient: only the crafts that finish before it spoils, unless spoiling: true
    local want=type(a.count)=='number' and a.count or 1
    local sp=M.craft_spoil(p,a.recipe,want)
    local spoil_line
    if sp and sp.item then
      spoil_line=string.format('the first %s you hold spoils in %ds; with %ds of hand crafting ahead and %gs a craft, %d of the %d crafts finish before it',
        sp.item,sp.spoils_in,math.floor(sp.ahead+0.5),sp.per,sp.fits,want)
      if sp.fits<want and a.spoiling~=true then
        if sp.fits==0 then
          return {started=0,nothing_queued=string.format('nothing was queued for %s: %s; spoiling: true queues them anyway',a.recipe,spoil_line),spoil=spoil_line,
            products_spoil=#sp.products>0 and sp.products or nil}
        end
        spoil_line=spoil_line..string.format('; %d queued (spoiling: true queues all %d)',sp.fits,want)
        a=setmetatable({count=sp.fits},{__index=a})
      end
    end
    local started=begin_craft(p,a.recipe,a.count,a.force==true or (a.check_stock==true and 'check') or nil,notes,shorts,fromq)
    local hand_s,queue_s,assemblers=craft_cost(p,{[a.recipe]=started})
    -- Nothing queued, said plainly (Sonnet 07:50: "started: cargo-bay=0" read as a partial start).
    local none=started==0 and string.format('nothing was queued for %s: %s',tostring(a.recipe),shorts[a.recipe] or 'not hand-craftable now') or nil
    return craft_facts(p,{started=started,nothing_queued=none,short=shorts[a.recipe],stock=next(notes) and notes or nil,from_queue=next(fromq) and fromq or nil,
      hand_s=hand_s,queue_s=queue_s,assemblers=assemblers,spoil=spoil_line,products_spoil=sp and #sp.products>0 and sp.products or nil},{[a.recipe]=started})
  end
  assert(type(a.recipes)=='table' and #a.recipes>=1 and #a.recipes<=32,'recipes requires 1..32 {recipe,count} entries')
  -- Every entry is attempted: a shortfall in one should not hide what the
  -- others queued. Repeated recipes accumulate.
  local started,errors,fromq={},{},{}
  for _,entry in ipairs(a.recipes) do
    local name=type(entry)=='table' and entry.recipe
    local ok,result=pcall(begin_craft,p,name,type(entry)=='table' and entry.count,a.force or type(entry)=='table' and entry.force,notes,shorts,fromq)
    local key=tostring(name)
    if ok then started[key]=(started[key] or 0)+result
    else errors[key]=reason(result) end
  end
  local hand_s,queue_s,assemblers=craft_cost(p,started)
  -- An entry that queued nothing leaves started and is said plainly (Sonnet 07:50).
  local none={}
  for key,n in pairs(started) do if n==0 then none[key]=string.format('nothing was queued for %s: %s',key,shorts[key] or 'not hand-craftable now'); started[key]=nil end end
  return craft_facts(p,{started=started,nothing_queued=next(none) and none or nil,errors=next(errors) and errors or nil,short=next(shorts) and shorts or nil,stock=next(notes) and notes or nil,
    from_queue=next(fromq) and fromq or nil,hand_s=hand_s,queue_s=queue_s,assemblers=assemblers},started)
end
end -- Hand-craftable counts from current inventory, including intermediates.
function handlers.craftable(p,a)
  local names=type(a.recipes)=='string' and {a.recipes} or a.recipes
  local out={}
  local categories=p.character.prototype.crafting_categories or {}
  local function by_hand(recipe) return takes(categories,recipe) end
  if names then
    assert(type(names)=='table' and #names>=1 and #names<=64,'recipes requires 1..64 names')
    for _,name in ipairs(names) do
      local recipe=type(name)=='string' and p.force.recipes[name]
      assert(recipe,'unknown recipe: '..tostring(name))
      out[name]=recipe.enabled and by_hand(recipe) and p.get_craftable_count(name) or 0
    end
  else
    -- Unfiltered: only the recipes that can be started right now.
    for name,recipe in pairs(p.force.recipes) do
      if recipe.enabled and not recipe.hidden and by_hand(recipe) then
        local n=p.get_craftable_count(name)
        if n>0 then out[name]=n end
      end
    end
  end
  return {craftable=out}
end
function handlers.cancel_craft(p,a)
  -- all (Sonnet 13:51: duplicate hand crafts twice): every queued craft, the latest first, as the queue's cancel does
  -- one by one; what came back to the inventory.
  if a.all~=nil then
    assert(a.all==true,'all must be true')
    assert(a.recipe==nil and a.index==nil and a.count==nil,'all cancels the whole queue: no recipe, index or count')
    local function held()
      local t={}
      local ok,list=pcall(function() return p.get_main_inventory().get_contents() end)
      for _,st in ipairs(ok and list or {}) do t[st.name]=(t[st.name] or 0)+st.count end
      return t
    end
    local before=held()
    local by,n={},0
    for _=1,1000 do
      local queue=p.crafting_queue or {}
      local entry
      for i=#queue,1,-1 do if not queue[i].prerequisite then entry=queue[i]; entry.at=i; break end end
      if not entry then break end
      p.cancel_crafting{index=entry.index or entry.at,count=entry.count}
      by[entry.recipe]=(by[entry.recipe] or 0)+entry.count; n=n+entry.count
    end
    assert(n>0,'the crafting queue is empty')
    local after,returned=held(),{}
    for item,c in pairs(after) do if c>(before[item] or 0) then returned[item]=c-(before[item] or 0) end end
    return {cancelled=n,recipes=by,returned=next(returned) and returned or nil,crafting_queue=p.crafting_queue or {}}
  end
  if a.recipe~=nil then
    assert(a.index==nil,'give recipe or index, not both')
    -- The recipe's own entries, not intermediates queued for other crafts;
    -- latest first, as a player trims the tail of the queue.
    local queue=p.crafting_queue or {}
    local available=0
    for _,entry in ipairs(queue) do if entry.recipe==a.recipe and not entry.prerequisite then available=available+entry.count end end
    assert(available>0,'no queued crafts of '..tostring(a.recipe))
    local wanted=integer(a.count,available,1,available,'count')
    local left=wanted
    for i=#queue,1,-1 do
      local entry=queue[i]
      if left>0 and entry.recipe==a.recipe and not entry.prerequisite then
        local n=math.min(left,entry.count)
        p.cancel_crafting{index=entry.index or i,count=n}
        left=left-n
      end
    end
    return {cancelled=wanted,recipe=a.recipe,crafting_queue=p.crafting_queue or {}}
  end
  local index=integer(a.index,1,1,10000,'index')
  local entry=(p.crafting_queue or {})[index]
  assert(entry,'crafting queue entry does not exist')
  local count=integer(a.count,entry.count,1,entry.count,'count')
  p.cancel_crafting{index=index,count=count}
  return {cancelled=count,recipe=entry.recipe,crafting_queue=p.crafting_queue or {}}
end
-- The ingredients a cancel puts back in the inventory, counted as moved (operator 08:01): the recipe's item
-- ingredients held before and after.
do
  local cancel=handlers.cancel_craft
  handlers.cancel_craft=function(p,a)
    if a.all~=nil then
      local out=cancel(p,a)
      local n=0
      for _,c in pairs(out.returned or {}) do n=n+c end
      out.moved=n
      return out
    end
    local name=a.recipe or (type(a.index)=='number' and ((p.crafting_queue or {})[a.index] or {}).recipe) or nil
    local recipe=type(name)=='string' and p.force.recipes[name]
    local before={}
    for _,ing in ipairs(recipe and recipe.ingredients or {}) do if ing.type=='item' then before[ing.name]=p.get_item_count(ing.name) end end
    local out=cancel(p,a)
    local n,returned=0,{}
    for item,b in pairs(before) do
      local d=p.get_item_count(item)-b
      if d>0 then n=n+d; returned[item]=d end
    end
    out.moved=n; out.returned=next(returned) and returned or nil
    return out
  end
end
-- A player's pole auto-connects only to a few neighbours, and a pole revived
-- from a ghost keeps only the ghost's wires (none for a lone ghost). Join the
-- nearest pole of every separate wire group the wire reaches. Groups come from
-- walking copper wires, not electric_network_id: poles built in the same tick
-- (construct builds several per tick) share a stale network id until the next
-- update, which left rows of ghost-built poles unwired.
local COPPER_GROUP_LIMIT=4096
local function copper_group(e,seen)
  local copper=defines.wire_connector_id.pole_copper
  local queue,head,n={e},1,0
  seen[e.unit_number]=true
  while head<=#queue and n<COPPER_GROUP_LIMIT do
    local pole=queue[head]; head=head+1; n=n+1
    local connector=pole.get_wire_connector(copper,false)
    for _,c in ipairs(connector and connector.connections or {}) do
      local other=c.target and c.target.owner
      if other and other.valid and other.type=='electric-pole' and not seen[other.unit_number] then
        seen[other.unit_number]=true; queue[#queue+1]=other
      end
    end
  end
end
local function bridge_pole(e)
  local copper=defines.wire_connector_id.pole_copper
  local mine=e.get_wire_connector(copper,true)
  local reach=e.prototype.get_max_wire_distance(e.quality)
  local others=e.surface.find_entities_filtered{type='electric-pole',position=e.position,radius=reach,force=e.force}
  table.sort(others,function(x,y) return distance(e.position,x.position)<distance(e.position,y.position) end)
  local joined,seen=0,{}
  copper_group(e,seen)
  for _,other in ipairs(others) do
    if other.valid and not seen[other.unit_number] then
      local theirs=other.get_wire_connector(copper,true)
      if mine.can_wire_reach(theirs) and mine.connect_to(theirs,false) then
        joined=joined+1
        copper_group(other,seen)
      end
    end
  end
  return joined
end
-- Map view (cursor building there only places ghosts) and undergrounds: place
-- the way a hand build does: reach and manual build checks from the character, one item from
-- its inventory, and a ghost already on the spot revived with its settings.
local STEP={[0]={0,-1},[4]={1,0},[8]={0,1},[12]={-1,0}}
-- The end a player's hand-build makes: the nearest same-kind underground
-- upstream flowing the same way decides. An unpaired entrance makes this its
-- exit; an exit or a paired entrance leaves this an entrance. Undergrounds
-- flowing another way never pair with it and are skipped.
local function underground_type(surface,proto,pos,direction)
  local step=STEP[direction]
  local x,y=math.floor(pos.x)+0.5,math.floor(pos.y)+0.5
  for k=1,proto.max_underground_distance or 0 do
    for _,e in pairs(surface.find_entities_filtered{position={x=x-step[1]*k,y=y-step[2]*k},radius=0.3,type='underground-belt'}) do
      if e.name==proto.name and e.direction==direction then
        return (e.direction==direction and e.belt_to_ground_type=='input' and not e.neighbours) and 'output' or 'input'
      end
    end
  end
  return 'input'
end
-- What sits in a refused footprint: entities and ghosts (name and position),
-- the character itself, else the tiles it may not go on (water, space).
-- Trees and rocks are called out: place_ghosts marks them and construct
-- clears them, where a direct build cannot. Items on the ground: pick them up.
-- A refused build (near) revives a ghost of the same entity on the same
-- centre, so that ghost is never what blocks it (Sol, shift09 01:38: five
-- pole ghosts on Gleba wetland read "placement blocked by ghost
-- medium-electric-pole" at their own positions; the tiles refused them).
-- What a refused placement found nothing in the way of can still break (Astra, d15 07:50: a cargo bay "fits the
-- cleared footprint" and the reply said nothing found, about 10 min): the tile grid (an entity of even width centres on
-- a tile edge, of odd width on a tile centre) and a cargo bay's attachment (it joins the platform hub or another cargo
-- bay, edge to edge). nil when neither explains it.
function M.attach_why(p,proto,pos,direction)
  local w,h=proto.tile_width,proto.tile_height
  if type(w)=='number' and type(h)=='number' then
    if direction==4 or direction==12 then w,h=h,w end
    local function off(c,n) local f=c-math.floor(c); return (n%2==0) and math.abs(f)>0.01 and math.abs(f-1)>0.01 or (n%2==1 and math.abs(f-0.5)>0.01) end
    if off(pos.x,w) or off(pos.y,h) then
      local function fix(c,n)
        if not off(c,n) then return string.format('%g',c) end
        return n%2==0 and string.format('%g or %g',math.floor(c),math.ceil(c)) or string.format('%g',math.floor(c)+0.5)
      end
      return string.format(': off the tile grid: a %dx%d %s centres on %s (x %s, y %s)',w,h,proto.name,
        (w%2==0 and h%2==0) and 'tile edges' or (w%2==1 and h%2==1) and 'tile centres' or 'a tile edge on its even side and a tile centre on its odd side',
        fix(pos.x,w),fix(pos.y,h))
    end
  end
  if proto.type~='cargo-bay' then return nil end
  local b=proto.collision_box
  if not b then return nil end
  local l,t,r,bt=pos.x+math.floor(b.left_top.x*2+0.5)/2,pos.y+math.floor(b.left_top.y*2+0.5)/2,pos.x+math.ceil(b.right_bottom.x*2-0.5)/2,pos.y+math.ceil(b.right_bottom.y*2-0.5)/2
  l,t,r,bt=math.floor(l+0.5),math.floor(t+0.5),math.floor(r+0.5),math.floor(bt+0.5)
  -- (d17 batch13 A5, Sol: "no hub or cargo bay within 12 tiles" beside the hub: one find of hubs, bays and every ghost,
  -- 32 at most, filled with other ghosts first) the hub and bays, then the bays' ghosts, apart
  local list=p.surface.find_entities_filtered{area={{l-12,t-12},{r+12,bt+12}},type={'space-platform-hub','cargo-bay'},force=p.force,limit=32}
  for _,g in ipairs(p.surface.find_entities_filtered{area={{l-12,t-12},{r+12,bt+12}},type='entity-ghost',ghost_type='cargo-bay',force=p.force,limit=32}) do list[#list+1]=g end
  local best,bd,touch
  for _,e in ipairs(list) do
    local kind=e.type=='entity-ghost' and e.ghost_type or e.type
    if e.valid and (kind=='space-platform-hub' or kind=='cargo-bay') then
      local eb=e.bounding_box
      local el,et,er,ebt=math.floor(eb.left_top.x+0.5),math.floor(eb.left_top.y+0.5),math.floor(eb.right_bottom.x+0.5),math.floor(eb.right_bottom.y+0.5)
      local dx=math.max(el-r,l-er,0); local dy=math.max(et-bt,t-ebt,0)
      local overlap_x=math.min(r,er)-math.max(l,el); local overlap_y=math.min(bt,ebt)-math.max(t,et)
      local label=(e.type=='entity-ghost' and 'ghost ' or '')..(e.type=='entity-ghost' and e.ghost_name or e.name)
      if (overlap_y>0 and (el==r or er==l)) or (overlap_x>0 and (et==bt or ebt==t)) then
        touch=touch or string.format('%s (%g,%g)',label,e.position.x,e.position.y)
      end
      local d=math.max(dx,dy)
      if not bd or d<bd then best,bd=string.format('%s (%g,%g), box (%g,%g)-(%g,%g)',label,e.position.x,e.position.y,el,et,er,ebt),d end
    end
  end
  if touch then
    return string.format(': the cargo bay\'s box (%g,%g)-(%g,%g) touches %s, and the game still refuses it there: a cargo bay joins the hub or a bay only where its connection points line up; positions shifted along that edge are worth a dry run',l,t,r,bt,touch)
  end
  return string.format(': a cargo bay joins the platform hub or another cargo bay edge to edge; its box (%g,%g)-(%g,%g) touches none%s',l,t,r,bt,
    best and string.format('; the nearest: %s, %d tiles from its edge',best,bd) or '; no hub or cargo bay within 12 tiles')
end
-- One cargo landing pad per planet (the game's rule; Astra 02:03: a second pad on Fulgora refused with no blocker
-- named): the pad already there (built or a ghost), or nil.
function M.one_pad(surface,force,proto,pos)
  if not (proto and proto.type=='cargo-landing-pad') then return nil end
  if (pcall(function() return surface.platform end)) and surface.platform then return nil end
  local found=surface.find_entities_filtered{type='cargo-landing-pad',limit=1}
  local e=found[1]
  local ghost=false
  if not e then
    e=surface.find_entities_filtered{ghost_type='cargo-landing-pad',limit=1}[1]
    ghost=e~=nil
  end
  if not e then return nil end
  if pos and math.abs(e.position.x-pos.x)<0.01 and math.abs(e.position.y-pos.y)<0.01 then return nil end
  local whose=e.force==force and 'ours' or ('of force '..tostring(e.force and e.force.name))
  return string.format('one cargo landing pad per planet (the game\'s rule): %s%s stands at (%g,%g) on %s',
    ghost and 'a ghost of one, ' or 'one, ',whose,e.position.x,e.position.y,surface.name)
end
-- (d24 batch154, the batch149 review's bug 3: "placement blocked by logistic-robot (-21.76,-21.20), logistic-robot
-- (-21.80,-21.16), boompuff", Sonnet) whether entity e meets proto in the game's collision test: their collision masks
-- share a layer (flying robots, corpses and smoke share none with a building, and never block it). A mask that cannot
-- be read counts as meeting.
do local masks={}
function M.mask_meets(proto,e)
  local function mask_of(x) local ok,m=pcall(function() return x.collision_mask end); return ok and type(m)=='table' and type(m.layers)=='table' and m or nil end
  local a=mask_of(proto)
  local name=e.name
  local b=masks[name]
  if b==nil then
    local ok,ep=pcall(function() return e.prototype end)
    b=ok and ep and mask_of(ep) or false
    masks[name]=b
  end
  if not a or not b then return true end
  if a.colliding_with_tiles_only or b.colliding_with_tiles_only then return false end
  for layer in pairs(a.layers) do if b.layers[layer] then return true end end
  return false
end
end
local function placement_error(p,proto,pos,direction,near)
 local function blockers()
  local pad=M.one_pad(p.surface,p.force,proto,pos)
  if pad then return ': '..pad end
  if proto.type=='rail-ramp' then
    local _,_,text=M.placewhy.ramp_collisions(p.surface,p.force,proto,pos,direction)
    if text~='' then return '; ramp footprint contains '..text end
  end
  local b=proto.collision_box or {left_top={x=-0.4,y=-0.4},right_bottom={x=0.4,y=0.4}}
  local l,t,r,btm=b.left_top.x,b.left_top.y,b.right_bottom.x,b.right_bottom.y
  if direction==4 or direction==12 then l,t,r,btm=-btm,l,-t,r end
  local area={left_top={x=pos.x+l,y=pos.y+t},right_bottom={x=pos.x+r,y=pos.y+btm}}
  local found,character,items={},false,false
  local trees,rocks,cliffs=0,0,0
  -- (d24 batch154) 48: robots passing over (left out below) leave room for what blocks it
  for _,e in pairs(p.surface.find_entities_filtered{area=area,limit=48}) do
    if e.valid and e.type=='character' and e==p.character then character=true
    elseif e.valid and e.type=='character' and #found<4 then
      -- Someone else stands there: say who, so the agent can ask them.
      local who=M.character_owner(e)
      found[#found+1]=string.format('%s standing at (%.1f,%.1f) (ask them to move, or build elsewhere)',who and who..'\'s character' or 'another character',e.position.x,e.position.y)
    elseif near and e.valid and e.type=='entity-ghost' and e.ghost_name==proto.name
      and math.abs(e.position.x-pos.x)<0.01 and math.abs(e.position.y-pos.y)<0.01 then
      -- the ghost this build revives
    elseif e.valid and e.type=='tile-ghost' then
      -- a tile ordered under it is no blocker: a build reads the tile there now; the game takes an entity ghost over
      -- tile ghosts (d20 batch52 J1: Sol's thrusters were refused "blocked by tile ghost space-platform-foundation")
    elseif e.valid and e.type~='resource' and #found<4 and (e.type=='entity-ghost' or M.mask_meets(proto,e)) then
      local name=e.type=='entity-ghost' and 'ghost '..e.ghost_name or e.type=='tile-ghost' and 'tile ghost '..e.ghost_name or e.name
      -- An item on the ground (shake4: Grok's 9 tries at one spot): say which.
      if e.type=='item-entity' then items=true; name=name..(e.stack and e.stack.valid_for_read and ' ('..e.stack.name..')' or '') end
      if e.type=='tree' or e.type=='plant' then trees=trees+1 elseif e.type=='simple-entity' then rocks=rocks+1 elseif e.type=='cliff' then cliffs=cliffs+1 end
      found[#found+1]=string.format('%s (%g,%g)',name,e.position.x,e.position.y)
    end
  end
  if character then found[#found+1]='the character standing on the footprint (move off it first)' end
  if #found>0 then
    -- Trees and rocks need mining first (Sol, shift09: say so with the names
    -- and positions, also when a build that waited for a craft hits them).
    local what=trees>0 and rocks>0 and 'the trees and rocks' or trees>1 and 'the trees' or trees==1 and 'the tree'
      or rocks>1 and 'the rocks' or rocks==1 and 'the rock' or nil
    local them=trees+rocks>1 and 'them' or 'it'
    return ' by '..table.concat(found,', ')
      ..(what and string.format('; it needs %s mined first (mine %s, or place_ghosts marks %s and construct clears %s)',what,them,them,them) or '')
      ..(cliffs>0 and '; cliff explosives clear a cliff (a character cannot mine one)' or '')
      ..(items and '; a build takes items on the ground into your inventory, and this one did not fit: free a slot (or stand next to it and fh call pickup)' or '')
  end
  -- Tile buildability rules (asteroid collectors: rear rows on foundation, the
  -- front in empty space): the broken one; with rules, they judge the tiles.
  local rule,ruled
  if near then rule,ruled=M.placewhy.tile_rules(p.surface,proto,pos,direction)
  else
    -- (d20 batch52 J1) a ghost: tile ghosts laid, tiles past the generated chunks asked for and said
    local rt=M.placewhy.rule_tiles(p.surface,p.force,proto,pos,direction)
    ruled=rt.ruled
    rule=rt.broken or (rt.ungenerated and M.placewhy.ungenerated_text(p.surface,rt.ungenerated,true))
      or (#rt.need>0 and string.format('stands on %d %s tiles its tile rules want %s under',#rt.need,rt.need[1].tile,rt.need[1].item)) or nil
  end
  if rule then return ': '..rule end
  -- Tiles it cannot stand on (its collision mask against each tile: water,
  -- wetland, lava, space), with the tile item that makes them buildable;
  -- else water, space and lava under it.
  local tiles,items={},{}
  local ok_fix,fixes=pcall(function() return not ruled and M.dryrun and M.dryrun.tile_fixes(p.surface,p.force,proto,pos,direction) end)
  for _,f in ipairs(ok_fix and fixes or {}) do
    if not tiles[f.tile] then tiles[f.tile]=true; tiles[#tiles+1]=f.tile end
    local item=f.item or f.locked or f.two
    if item and not items[item] then items[item]=true; items[#items+1]=item end
  end
  for _,tile in pairs(#tiles==0 and not ruled and p.surface.find_tiles_filtered{area=area,limit=16} or {}) do
    local mask=tile.prototype.collision_mask
    local layers=mask and mask.layers or {}
    if (layers.water_tile or layers.empty_space or layers.lava_tile) and not tiles[tile.name] then tiles[tile.name]=true; tiles[#tiles+1]=tile.name end
  end
  if #tiles>0 then
    -- On a platform (Astra, shift19: three belts at the foundation's edge refused until the foundation under them was
    -- built, though its tile ghosts were placed): the tile ghosts on the footprint, and that the game refuses the
    -- entity ghost over them until that foundation is built.
    if p.surface.platform then
      local tg={}
      for _,g in pairs(p.surface.find_entities_filtered{area=area,type='tile-ghost',limit=8}) do
        if g.valid and g.type=='tile-ghost' then tg[#tg+1]=string.format('(%g,%g)',math.floor(g.position.x),math.floor(g.position.y)) end
      end
      if #tg>0 then
        return ' by tiles: '..table.concat(tiles,', ')..' under it, with tile ghosts of '..(items[1] or 'space-platform-foundation')..' at '..table.concat(tg,' ')
          ..' not built yet: the game\'s ghost check refuses this entity\'s ghost while they are ghosts, and takes it once the foundation under it is built (the hub builds foundation ghosts from hub items)'
      end
      return ' by tiles: '..table.concat(tiles,', ')..' under it, with no foundation or foundation tile ghost there (needs '..(#items>0 and table.concat(items,' or ') or 'space-platform-foundation')..'; the same call with dry_run: true names the foundation the hub would not build and the fewest tiles that join it to the floor: tiles.unbuilt, tiles.connect)'
    end
    local wet,lava=false,false
    for _,t in ipairs(tiles) do
      if t:find('water',1,true) or t:find('wetland',1,true) or t:find('ocean',1,true) then wet=true end
      if t:find('lava',1,true) then lava=true end
    end
    -- Lava (Sonnet, shift19: "needs foundation (not researched)" read as a research problem): the tile first.
    if lava and not wet then
      local fix=items[1]
      return ' by tiles: '..table.concat(tiles,', ')..' (unbuildable: lava'
        ..(fix and (fix:find(' (not researched)',1,true) and '; only '..fix:gsub(' %(not researched%)','')..' laid on it makes it buildable, and that is not researched'
          or '; '..fix..' laid on it makes it buildable') or '; no tile item makes it buildable')..')'
    end
    return ' by tiles: '..table.concat(tiles,', ')..' (needs '..(#items>0 and table.concat(items,' or ') or 'landfill')
      ..(wet and ', or a shore position: scan fields=fluids / grid ~ marks water)' or ')')
  end
  local okw,why=pcall(M.attach_why,p,proto,pos,direction)
  if okw and why then return why end
  return ' (nothing found in the footprint: check the position is a valid centre for a '..(proto.name or 'entity')..' and the direction)'
 end
 local ok,extra=pcall(blockers)
 local text='placement blocked'..(ok and extra or '')
 -- A refused build (near): an offshore pump, or water under the footprint,
 -- lists the nearest valid placements (shore.lua).
 if near and M.shore then
  local water=ok and extra and extra:find(' by tiles: ',1,true)~=nil
  local fine,hint=pcall(M.shore.hint,p,proto,pos,direction,water)
  if fine and hint then text=text..hint end
 end
 return text
end
M.placement_error=placement_error
local function build_direct(p,stack,pos,direction,quality,kind,place,rail_layer)
  local proto,surface=place or stack.prototype.place_result,p.surface
  -- A rail planner's curve takes 3 rails and a half-diagonal 2, as the game
  -- charges them (items_to_place_this); everything else here takes one.
  local need=1
  for _,it in ipairs(proto.items_to_place_this or {}) do if it.name==stack.name then need=it.count or 1 end end
  if need>1 then
    local held=p.get_main_inventory().get_item_count{name=stack.name,quality=quality}
    assert(held>=need,string.format('%s takes %d %s; you hold %d',proto.name,need,stack.name,held))
  end
  construction.clear_remnants(surface,proto,pos,direction)
  -- Items on the ground in the footprint go into the inventory, as a player's
  -- build takes them (shake5: Grok's six builds over one iron plate). One
  -- that does not fit stays, and the placement error says so.
  local picked
  for _,it in pairs(surface.find_entities_filtered{area=construction.box(proto,pos,direction),type='item-entity'}) do
    if it.valid and it.type=='item-entity' and it.stack and it.stack.valid_for_read then
      local name,count=it.stack.name,it.stack.count
      local n=p.insert{name=name,count=count,quality=it.stack.quality and it.stack.quality.name or nil}
      if n>0 then
        picked=picked or {}; picked[name]=(picked[name] or 0)+n
        if n>=count then it.destroy() else it.stack.count=count-n end
      end
    end
  end
  local ghost=surface.find_entities_filtered{position=pos,radius=0.1,ghost_name=proto.name,force=p.force,limit=1}[1]
  local e,replaced,plan,hold
  if ghost then
    local _,revived=ghost.revive{raise_revive=true}
    e=revived
    -- (d23 batch120 CC1) an equipped vehicle's item: its grid and label go on the revived vehicle (grids.lua from_item)
    if e and stack.is_item_with_entity_data then pcall(M.grids.from_item,stack,e) end
  else
    local args={name=proto.name,position=pos,direction=direction,force=p.force,build_check_type=defines.build_check_type.manual,rail_layer=rail_layer}
    if not surface.can_place_entity(args) then error(placement_error(p,proto,pos,direction,true),0) end
    -- The manual check allows a fast-replace, which create_entity without
    -- fast_replace does not do: both machines stayed on the tiles (shake5:
    -- assembling-machine-2 over -1, the old one kept running; request #68).
    -- A machine of the same group on the same centre is replaced as a
    -- player's build does: a chest's contents into the new chest as far as
    -- it holds them, the rest and the old one into the inventory, all or
    -- nothing (replace.lua); its recipe set on the new one. Any other
    -- overlap is refused.
    local group=proto.fast_replaceable_group
    if group then
      local cb=proto.collision_box or {left_top={x=-0.4,y=-0.4},right_bottom={x=0.4,y=0.4}}
      local l,t,r,btm=cb.left_top.x,cb.left_top.y,cb.right_bottom.x,cb.right_bottom.y
      if direction==4 or direction==12 then l,t,r,btm=-btm,l,-t,r end
      for _,o in pairs(surface.find_entities_filtered{area={left_top={x=pos.x+l,y=pos.y+t},right_bottom={x=pos.x+r,y=pos.y+btm}},force=p.force}) do
        if o.valid and o.type~='entity-ghost' and o.prototype and o.prototype.fast_replaceable_group==group then
          local ob=o.prototype.collision_box
          local same=math.abs(o.position.x-pos.x)<0.01 and math.abs(o.position.y-pos.y)<0.01 and ob
            and math.abs((ob.right_bottom.x-ob.left_top.x)-(cb.right_bottom.x-cb.left_top.x))<0.01
            and math.abs((ob.right_bottom.y-ob.left_top.y)-(cb.right_bottom.y-cb.left_top.y))<0.01
          if not same then
            error(string.format('placement blocked by %s (%g,%g) already on these tiles, not on the same centre: mine it first (mine at its position), then build',
              o.name,o.position.x,o.position.y),0)
          end
          assert(o.name~=proto.name,'target already contains this entity')
          local ok,recipe,rq=pcall(function() if o.get_recipe then return o.get_recipe() end end)
          local old={name=o.name,recipe=ok and recipe and recipe.name or nil,recipe_quality=ok and rq and rq.name or nil}
          plan=M.replace.plan(p,o,proto,quality,(need==1 and stack.count==1) and 1 or 0)
          if plan.error then error(plan.error,0) end
          -- Its filters, wires, circuit settings, limit and requests, for the new one (replace.lua).
          plan.settings=M.replace.settings(o)
          hold=M.replace.take(o,plan)
          assert(hold,string.format('cannot replace %s (%g,%g): the game did not remove it; nothing moved',old.name,pos.x,pos.y))
          replaced=old
          break
        end
      end
    end
    args.quality=quality; args.player=real(p); args.raise_built=true
    -- (d23 batch120 CC1, Sol #2027: Haiku's rebuilt spidertron had an empty grid; the item carried fusion, shields,
    -- batteries and lasers) An item with entity data builds with its grid, label and colour, as the game builds it.
    if stack.is_item_with_entity_data then args.item=stack end
    if proto.type=='underground-belt' then args.type=kind or underground_type(surface,proto,pos,direction) end
    e=surface.create_entity(args)
  end
  if not e then
    -- The replaced entity's items go to the character after all.
    if hold then M.replace.give(p,nil,hold,{item={},kept={},keep=false,any=plan.any}) end
    error(placement_error(p,proto,pos,direction,true),0)
  end
  if need>1 then p.get_main_inventory().remove{name=stack.name,count=need,quality=quality}
  elseif stack.count>1 then stack.count=stack.count-1 else stack.clear() end
  if hold then replaced.contents=M.replace.give(p,e,hold,plan) end
  -- Then its settings (Sol 10:50), after the contents so a limit does not stop them: what was kept, what was not.
  if plan and plan.settings then
    local ok,kept,refused=pcall(M.replace.apply,e,plan.settings)
    if ok then
      replaced.kept=#kept>0 and kept or nil
      replaced.not_kept=#refused>0 and refused or nil
    else replaced.not_kept={'settings: '..reason(kept)} end
  end
  -- The replaced machine's recipe goes on the new one when it can make it.
  if replaced and replaced.recipe and e.set_recipe then
    local ok=pcall(e.set_recipe,replaced.recipe,replaced.recipe_quality)
    replaced.recipe_kept=ok or nil
  end
  -- The build log (efficiency.lua): a machine built by hand is this agent's; one revived from a ghost, its planner's.
  pcall(M.efficiency.built,M.board.who(p),e,ghost~=nil)
  pcall(M.ghostlog.placed,M.board.who(p),e,true,ghost~=nil)
  -- a generator, solar panel or accumulator: the networks view is made again from now (Z5, networks.built)
  pcall(M.networks.built,e)
  pcall(M.fusion.watch,e)
  -- (d23 batch123 CF2) a running watch it touches splits there (mixed.lua)
  if M.mixed then pcall(M.mixed.edit,e,'built by '..M.board.who(p)) end
  return e,picked,replaced,need
end
local function build_reach(p,pos,what)
  assert_visible(p,pos,what)
  if distance(p.position,pos)>p.build_distance then
    error(string.format('%s is out of build reach: %s, build reach %g',what,from_character(p,pos),p.build_distance),2)
  end
end
-- A build entry b of call a out of build reach (autowalk.lua): its far record (the position a belt snaps to), or nil
-- in reach or with no position.
function M.build_far(p,b,a)
  local ok,pos=pcall(position,b.position)
  if not ok or type(pos)~='table' then return nil end
  local item=prototypes and prototypes.item[b.item or a.item or '']
  local place=item and item.place_result
  if place and place.type=='transport-belt' then pos={x=math.floor(pos.x)+0.5,y=math.floor(pos.y)+0.5} end
  if place and place.type=='rail-ramp' then
    local direction=M.direction_of(b.direction or a.direction or 'north')
    if direction then pos=M.placewhy.ramp_position(pos,direction) end
  end
  local reach=p.build_distance or 10
  if distance(p.position,pos)<=reach then return nil end
  -- (out of sight: the sight refusal, with the nearest radar coverage when the chunk is dark)
  local seen,why=pcall(assert_visible,p,pos,'position')
  return M.autowalk.point_far(p,pos,reach,seen and string.format('position is out of build reach: %s, build reach %g',from_character(p,pos),reach) or reason(why))
end
-- Tiles go down like a player's: the item in the cursor, placed over a
-- size x size square (the game's terrain brush) that the tile's placement
-- rules allow (landfill only on water), revived over matching tile ghosts.
-- A building's status the tick it is placed is stale (a powered radar reads
-- no_power until the network updates), so build results leave it out.
-- An inserter has no engine targets in the tick it is built or turned (they
-- come a tick later; checked on 2.0.77): read what stands on its points instead.
local function built_summary(e)
  local out=summary(e); out.status_name=nil
  -- A vehicle's grid as built (d23 batch120 CC1).
  local okg,grid=pcall(function() return e.grid end)
  if okg and grid then out.equipment=M.grids.view(grid) end
  if e.type=='inserter' and M.targets then
    local ok,t=pcall(M.targets.plan,e.surface,e.prototype,e.position,e.direction)
    out.io_warning=ok and t and t.missing or nil
    -- What its pickup and drop sides touch (Muse 07:51: three backwards inserters, about 30 min), as check_inserters reads them.
    if ok and t then out.pickup=t.pickup; out.drop=t.drop end
  end
  if e.type=='inserter' then
    local ok,line=pcall(M.inserter_sides,e)
    out.inserter=ok and line or nil
    -- onto a belt that does not take what it puts (beltfit.lua; Opus 19:50)
    local okf,fit=pcall(M.beltfit.check,e)
    out.belt_mismatch=okf and fit or nil
  end
  return out
end
-- An inserter's direction in words (Sonnet, shift12 13:50: "direction = pick side" got misplaced several times): the
-- side it picks up from and the side it drops to, from the engine's own points.
function M.inserter_sides(e)
  local function side(from,to)
    local dx,dy=to.x-from.x,to.y-from.y
    if math.abs(dx)>=math.abs(dy) then return dx>0 and 'east' or 'west' end
    return dy>0 and 'south' or 'north'
  end
  local function at(q) return string.format('(%g,%g)',math.floor(q.x)+0.5,math.floor(q.y)+0.5) end
  local here,pick,drop=e.position,e.pickup_position,e.drop_position
  return string.format('direction %s: picks up from its %s side at %s, drops to its %s side at %s (items move %s)',
    compass_names[e.direction] or tostring(e.direction),side(here,pick),at(pick),side(here,drop),at(drop),side(pick,drop))
end
-- A recipe set as the machine is built (build, and place_ghosts entries; Sonnet, shift12 13:50: one call instead of
-- configure after): configure's checks, on the prototype before anything is placed.
function M.recipe_for(p,proto,name)
  if type(name)~='string' then error('recipe must be a recipe name',0) end
  if proto.type~='assembling-machine' then
    error(string.format('recipe: %s (type %s) takes no recipe; only assembling machines (assemblers, foundries, chemical plants and the like) do',proto.name,tostring(proto.type)),0)
  end
  local recipe=p.force.recipes[name]
  if not (recipe and recipe.enabled) then error('recipe '..name..' is unavailable',0) end
  if not (proto.crafting_categories or {})[recipe.category] then
    local cats={}
    for c in pairs(proto.crafting_categories or {}) do cats[#cats+1]=c end
    table.sort(cats)
    error(string.format('recipe %s (category %s) is not one %s makes (its categories: %s)',name,tostring(recipe.category),proto.name,table.concat(cats,', ')),0)
  end
  return recipe
end
-- Sets it on what was just built, or its ghost, and reads it back.
-- want: the direction the build asked for. A machine whose fluid ports come with its recipe is placed without them, and
-- the game kept it facing north (d17 batch20->21 A1, Sol: an electromagnetic plant built east read north once its
-- quantum-processor recipe was set, its hot and cold ports swapped); with the recipe set, it is turned the way asked
-- (as a player's rotate does), said in the second return.
function M.set_built_recipe(e,name,want)
  e.set_recipe(name)
  local now=e.get_recipe()
  if not (now and now.name==name) then error('recipe incompatible with machine',0) end
  local note
  if want and e.direction~=want then
    local was=e.direction
    local ok=pcall(function() e.direction=want end)
    note=ok and e.direction==want
      and string.format('placed facing %s (the game keeps a machine without its recipe\'s fluid ports facing north); turned %s once the recipe was set',
        M.direction_name(was) or tostring(was),M.direction_name(want) or tostring(want))
      or string.format('faces %s, not %s as asked: the game did not turn it with recipe %s',M.direction_name(e.direction) or tostring(e.direction),M.direction_name(want) or tostring(want),name)
  end
  return now.name,note
end
local function build_tile(p,a,stack,pos)
  assert(not in_map_view(p),'tiles are placed by the character; leave map view')
  assert(a.direction==nil or a.direction=='north','tiles take no direction')
  local size=integer(a.size,1,1,4,'size')
  if M.bots.is(p) then return M.bots.place_tiles(p,a,stack,pos,size) end
  assert(not p.cursor_stack.valid_for_read,'cursor must be empty; clear it in the client first')
  local tile=stack.prototype.place_as_tile_result.result.name
  local inv=p.get_main_inventory()
  local function held() return inv.get_item_count{name=a.item,quality=a.quality or 'normal'} end
  local before=held()
  assert(p.cursor_stack.swap_stack(stack),'could not borrow inventory stack')
  local ok,err=pcall(function()
    assert(p.can_build_from_cursor{position=pos,terrain_building_size=size},'tile placement blocked (landfill needs water; the tile may already be there)')
    p.build_from_cursor{position=pos,terrain_building_size=size}
  end)
  local restored=not p.cursor_stack.valid_for_read or
    (not stack.valid_for_read and p.cursor_stack.swap_stack(stack)) or p.clear_cursor()
  assert(restored,'build finished but could not restore cursor; items remain in cursor')
  assert(ok,err)
  local consumed=before-held()
  assert(consumed>0,'no tile was placed (blocked or already there)')
  return {consumed=consumed,tile=tile,position={x=math.floor(pos.x)+0.5,y=math.floor(pos.y)+0.5}}
end
-- Fast-replacing one end of an underground pair with another tier (d17 batch20 A3, Opus: the pair broke, the belt
-- stopped with no word): the other end goes too, as a player's fast-replace does, when it is ours, in build reach and
-- you hold the item for it; else the build is refused naming it. nil when no pair is in question.
function M.underground_pair(p,place,pos,item,quality)
  local o
  for _,e in pairs(p.surface.find_entities_filtered{position=pos,radius=0.1,type='underground-belt',force=p.force}) do
    if e.valid and e.name~=place.name and e.prototype.fast_replaceable_group==place.fast_replaceable_group then o=e end
  end
  if not o then return nil end
  local ok,other=pcall(function() return o.neighbours end)
  if not (ok and other and other.valid and other.force==p.force) or other.name==place.name then return nil end
  local held=p.get_main_inventory().get_item_count{name=item,quality=quality}
  local d=distance(p.position,other.position)
  if d<=p.build_distance and held>=2 then return {position=other.position,direction=other.direction,kind=other.belt_to_ground_type,name=other.name} end
  local mid={x=math.floor((pos.x+other.position.x)/2)+0.5,y=math.floor((pos.y+other.position.y)/2)+0.5}
  error(string.format('%s (%g,%g) is one end of a pair with %s (%g,%g): a %s does not pair with a %s, so replacing one end alone breaks the belt; %s; build replaces both ends from within %g tiles of both, e.g. from (%g,%g)',
    o.name,o.position.x,o.position.y,other.name,other.position.x,other.position.y,place.name,other.name,
    held<2 and string.format('you hold %d %s, the pair takes 2',held,item) or string.format('the other end is %.1f tiles from you, build reach %g',d,p.build_distance),
    p.build_distance,mid.x,mid.y),0)
end
local function build_one(p,a)
  local pos=position(a.position)
  -- A turret out of reach: the refusal lists valid spots within reach toward it (shore.lua).
  local reached,far=pcall(build_reach,p,pos,'position')
  if not reached then
    local fine,hint=pcall(M.shore.reach_hint,p,a.item,pos)
    error(tostring(far)..(fine and hint or ''),0)
  end
  assert(type(a.item)=='string','item is required')
  local stack=p.get_main_inventory().find_item_stack{name=a.item,quality=a.quality or 'normal'}
  if not stack then
    -- What the item places already stands there (A2, Muse 21:20: a retry after a step-aside build that had placed it)
    local place=prototypes and prototypes.item and prototypes.item[a.item] and prototypes.item[a.item].place_result
    local there=place and p.surface.find_entities_filtered{position=pos,radius=0.5,name=place.name,force=p.force,limit=1}[1]
    if there then
      error(string.format('item is not in main inventory: %s already stands at (%g,%g)%s',there.name,there.position.x,there.position.y,
        there.last_user and there.last_user==p and ', placed by you' or ''),0)
    end
  end
  assert(stack,'item is not in main inventory')
  if stack.prototype.place_as_tile_result then return build_tile(p,a,stack,pos) end
  -- A rail planner (2.0: the rail item) places one of its rails, named by
  -- entity (default the first, straight-rail), directly at the position.
  local place,planner=stack.prototype.place_result,nil
  local ok_rails,rails=pcall(function() return stack.prototype.rails end)
  if ok_rails and type(rails)=='table' and #rails>0 then
    planner={}
    for _,r in ipairs(rails) do planner[#planner+1]=type(r)=='string' and r or r.name end
    local want=a.entity or planner[1]
    place=nil
    for _,n in ipairs(planner) do if n==want then place=prototypes.entity[n] end end
    assert(place,a.item..' places '..table.concat(planner,', ')..'; entity names which')
  else
    assert(a.entity==nil or (place and place.name==a.entity),'entity: '..a.item..' places '..tostring(place and place.name))
  end
  assert(place,'item does not place an entity')
  -- recipe: checked before anything is placed, set once it stands (M.recipe_for).
  if a.recipe~=nil then M.recipe_for(p,place,a.recipe) end
  -- Cursor building borrows the cursor; direct placement leaves it alone.
  -- While the game is tick-paused (turn mode between actions) the engine
  -- refuses every cursor build ("placement blocked" on clear ground), so
  -- place directly then, as in map view.
  local direct=in_map_view(p) or M.bots.is(p) or place.type=='underground-belt' or place.type=='rail-ramp' or planner~=nil or game.tick_paused==true
  assert(direct or not p.cursor_stack.valid_for_read,'cursor must be empty; clear it in the client first')
  -- A 1x1 entity stands on a tile centre (d17 batch17 C4, Muse: every new engineer learns that turrets sit on whole
  -- numbers and belts on halves by failing first): whole-number coordinates go to the centre of the tile there, as
  -- place_ghosts and its dry run snap; said in snapped.
  local snapped
  if ((place.tile_width==1 and place.tile_height==1) or place.type=='transport-belt') and place.type~='rail-ramp' and planner==nil then
    local to={x=math.floor(pos.x)+0.5,y=math.floor(pos.y)+0.5}
    if math.abs(to.x-pos.x)>0.01 or math.abs(to.y-pos.y)>0.01 then
      if place.type~='transport-belt' then
        snapped=string.format('(%g,%g) is a tile corner; a 1x1 %s stands on a tile centre: placed at (%g,%g)',pos.x,pos.y,place.name,to.x,to.y)
      end
      pos=to
      build_reach(p,pos,'snapped position')
    end
  end
  local direction=M.direction_of(a.direction or 'north'); assert(direction,'invalid direction: a compass name (north, east, south, west) or 0..15')
  if a.direction~=nil then M.check_direction(place,direction) end
  -- (AG2) rolling stock: orientation 0..1 asks the game the nearest of 16 directions; it snaps to the rail
  if a.orientation~=nil then
    assert(M.rollingstock.TYPES[place.type],'orientation goes with rolling stock (locomotives and wagons); others take direction')
    assert(a.direction==nil,'give direction or orientation, not both')
    direction=M.rollingstock.direction_of_orientation(a.orientation)
  end
  -- (AG1) a rail or chain signal: the game's manual check on its rail layer, the spot's facing when none is given;
  -- placed directly with that layer
  local sig
  if M.railsignal.TYPES[place.type] then
    sig=M.railsignal.resolve(p.surface,p.force,place.name,pos,a.direction~=nil and direction or nil,M.railsignal.layer_arg(a.rail_layer),false)
    direction=sig.direction; direct=true
  elseif a.rail_layer~=nil then error('rail_layer goes with rail signals and chain signals',0) end
  if place.type=='rail-ramp' then
    pos,direction=M.placewhy.ramp_position(pos,direction)
    build_reach(p,pos,'snapped position')
  end
  local filter={position=pos,radius=2,name=place.name,limit=64}
  local existing={}
  for _,e in pairs(p.surface.find_entities_filtered(filter)) do
    -- Native cursor placement can rotate an existing belt without consuming an
    -- item. A build request must not silently change an occupied crossing.
    if e.valid and e.name==place.name and distance(e.position,pos)<0.1
      and (e.quality and e.quality.name or 'normal')==(a.quality or 'normal') then
      -- (the other end of a pair an entry before replaced, this tick)
      local done=state().pair_done
      if done and done.tick==game.tick and e.unit_number and done[e.unit_number] then
        return {consumed=0,entity=built_summary(e),already=string.format('%s (%g,%g) was replaced with its pair by an entry before',e.name,e.position.x,e.position.y)},{}
      end
      error('target already contains this entity; use rotate explicitly or an underground crossing')
    end
    existing[e.unit_number or (e.name..'@'..e.position.x..','..e.position.y)]=true
  end
  local proto=place
  assert(a.type==nil or proto.type=='underground-belt' and (a.type=='input' or a.type=='output'),'type is input|output for underground belts only')
  -- Only the agent's own character in the way: handlers.build walks it off
  -- the footprint first, once per entry.
  if not a.stepped then
    local aside=construction.aside(p,proto,pos,direction)
    if aside then return {aside=aside} end
  end
  -- Undergrounds are always placed directly with an explicit end: cursor
  -- building does not reliably make the exit of a pair from script.
  if direct then
    local pair=place.type=='underground-belt' and M.underground_pair(p,place,pos,a.item,a.quality or 'normal') or nil
    local e,picked,replaced,need=build_direct(p,stack,pos,direction,a.quality or 'normal',a.type,place,sig and sig.layer)
    if pair then
      local stack2=p.get_main_inventory().find_item_stack{name=a.item,quality=a.quality or 'normal'}
      local ok2,e2,_,replaced2,need2=pcall(build_direct,p,stack2,pair.position,pair.direction,a.quality or 'normal',pair.kind,place)
      if ok2 and e2 then
        need=need+need2
        local done=state().pair_done
        if not done or done.tick~=game.tick then done={tick=game.tick}; state().pair_done=done end
        if e2.unit_number then done[e2.unit_number]=true end
        replaced=replaced or {}
        replaced.pair=string.format('its other end %s (%g,%g) replaced too: %s',pair.name,pair.position.x,pair.position.y,built_summary(e2).belt or e2.name)
        replaced.pair_contents=replaced2 and replaced2.contents or nil
      else
        replaced=replaced or {}
        replaced.pair=string.format('its other end %s (%g,%g) was not replaced: %s; the pair is broken until it is',pair.name,pair.position.x,pair.position.y,ok2 and 'placement failed' or reason(e2))
      end
    end
    local joined=e.type=='electric-pole' and bridge_pole(e) or 0
    local recipe,turned
    if a.recipe~=nil then recipe,turned=M.set_built_recipe(e,a.recipe,a.direction~=nil and direction or nil) end
    return {consumed=need,entity=built_summary(e),networks_joined=joined>0 and joined or nil,picked_up=picked,replaced=replaced,recipe=recipe,direction_note=turned,snapped=snapped,
      signal=sig and M.railsignal.read(e) or nil,signal_placed=sig and sig.line or nil,
      rolling_stock=M.rollingstock.TYPES[e.type] and M.rollingstock.read(e) or nil},{e}
  end
  local function held()
    local n=p.get_main_inventory().get_item_count{name=a.item,quality=a.quality or 'normal'}
    local c=p.cursor_stack
    if c.valid_for_read and c.name==a.item and c.quality.name==(a.quality or 'normal') then n=n+c.count end
    return n
  end
  local before=held()
  assert(p.cursor_stack.swap_stack(stack),'could not borrow inventory stack')
  local ok,err=pcall(function()
    if not p.can_build_from_cursor{position=pos,direction=direction,build_mode=defines.build_mode.normal} then
      error(placement_error(p,proto,pos,direction,true),0)
    end
    p.build_from_cursor{position=pos,direction=direction,build_mode=defines.build_mode.normal}
  end)
  local restored=not p.cursor_stack.valid_for_read or
    (not stack.valid_for_read and p.cursor_stack.swap_stack(stack)) or p.clear_cursor()
  assert(restored,'build finished but could not restore cursor; items remain in cursor')
  assert(ok,err)
  local after=held()
  local placed,joined,ents,recipe,turned={},nil,{},nil,nil
  if before>after then
    for _,e in pairs(p.surface.find_entities_filtered(filter)) do
      if e.valid and not existing[e.unit_number or (e.name..'@'..e.position.x..','..e.position.y)] then
        if a.recipe~=nil and e.type=='assembling-machine' then recipe,turned=M.set_built_recipe(e,a.recipe,a.direction~=nil and direction or nil) end
        placed[#placed+1]=built_summary(e); ents[#ents+1]=e
        if e.type=='electric-pole' then joined=(joined or 0)+bridge_pole(e) end
      end
    end
  end
  return {consumed=before-after,snapped=snapped,entity=#placed==1 and placed[1] or nil,entities=#placed>1 and placed or nil,
    networks_joined=joined and joined>0 and joined or nil,recipe=recipe,direction_note=turned},ents
end
-- After a hand build: what it just built closed the character in where it
-- stands (Gemini, shift09: a placement trapped the character in a closed
-- box), with the entities that each filled the last gap out (pathing.lua).
function M.closed_in_note(p,built)
  if #built==0 then return nil end
  local c=p.character
  if not (c and c.valid) or c.vehicle then return nil end
  local half=M.pathing.half(c)
  local ok,res=pcall(M.pathing.closed_by,p.surface,p.position,half,built,{ignore=c,force=p.force})
  if not (ok and res) then return nil end
  local list={}
  for _,e in ipairs(res.gaps) do if #list<6 then list[#list+1]=string.format('%s (%g,%g)',e.name,e.position.x,e.position.y) end end
  local here=p.position
  local what=#list==1 and 'the last gap out was where '..list[1]..' now stands'
    or #list>1 and 'without any one of '..table.concat(list,', ')..(#built>#list and string.format(' (of %d built now)',#built) or '')..' a gap out would stay'
    or 'what this build placed closes it'
  -- The one call that opens it (Gemini, d15 07:54: twice closed in by accumulators; each time one mine and one move_to).
  local g=res.gaps[1]
  local fix=g and string.format('; mine {"position":{"x":%g,"y":%g}} takes %s back and opens a way out',g.position.x,g.position.y,g.name) or ''
  return string.format('the character is closed in now where it stands (%g,%g): %s; %s%s',math.floor(here.x*10+0.5)/10,math.floor(here.y*10+0.5)/10,
    what,M.pathing.area_text(res.region,half),fix)
end
-- After a build or a ghost placement: logistic chests that no roboport's logistic area covers (networks.lua;
-- Sonnet, shift10: 8 chests with 31k copper sat outside roboport range for hours) and underground entrances fed
-- from the side by what was built (sidefeed.lua; Sol, shift10: long nutrient starvation). Lists or nil.
function M.build_notes(p,ents)
  local cover,side,seen={},{},{}
  local platform=own_platform(p)
  for _,e in ipairs(ents or {}) do
    if e.valid then
      local ghost=e.type=='entity-ghost'
      local t=ghost and e.ghost_type or e.type
      if t=='logistic-container' and not platform and M.networks and #cover<16 then
        local ok,line=pcall(M.networks.coverage,e.surface,e.force,e.position)
        if ok and line then cover[#cover+1]=string.format('%s (%g,%g): %s',ghost and e.ghost_name or e.name,e.position.x,e.position.y,line) end
      end
      if not ghost then
        local ok,lines=pcall(M.sidefeed.built,e)
        for _,l in ipairs(ok and lines or {}) do if not seen[l] and #side<8 then seen[l]=true; side[#side+1]=l end end
      end
    end
  end
  return #cover>0 and cover or nil,#side>0 and side or nil
end
-- Power and robot coverage of what a build or place_ghosts call put down (d17 batch18 C2, Opus: a whole circuit block
-- built unpowered outside the robot network): electric entities no pole's supply area covers (built: no electric
-- network, with the nearest pole; a ghost: no pole or pole ghost's supply area reaches its box), and entities no
-- roboport's construction area covers (robots neither build those ghosts nor repair or rebuild those entities). Each
-- a line: how many, the first 8 by name and position. Not on a platform (the hub builds there).
do
  local OWN={['electric-pole']=true,['solar-panel']=true,accumulator=true,generator=true,['burner-generator']=true,
    ['electric-energy-interface']=true,['power-switch']=true,['fusion-generator']=true,['lightning-attractor']=true}
  local MAX_READ,REACH=256,12
  local function supply(proto)
    local ok,d=pcall(function() return proto.get_supply_area_distance() end)
    if ok and d then return d end
    ok,d=pcall(function() return proto.supply_area_distance end)
    return ok and d or 0
  end
  local function ghost_covered(e,proto)
    local box=proto.collision_box or {left_top={x=0,y=0},right_bottom={x=0,y=0}}
    local x0,y0,x1,y1=e.position.x+box.left_top.x,e.position.y+box.left_top.y,e.position.x+box.right_bottom.x,e.position.y+box.right_bottom.y
    for _,f in ipairs({{type='electric-pole'},{type='entity-ghost',ghost_type='electric-pole'}}) do
      for _,pole in ipairs(e.surface.find_entities_filtered{position=e.position,radius=REACH,type=f.type,ghost_type=f.ghost_type,force=e.force,limit=64}) do
        local d=supply(pole.type=='entity-ghost' and pole.ghost_prototype or pole.prototype)
        local q=pole.position
        if x1>q.x-d and x0<q.x+d and y1>q.y-d and y0<q.y+d then return true end
      end
    end
    return false
  end
  function M.coverage_notes(p,ents)
    if own_platform(p) then return nil,nil end
    local off,offn,out,outn,read={},0,{},0,0
    for _,e in ipairs(ents or {}) do
      if read>=MAX_READ then break end
      if e.valid and e.type~='tile-ghost' then
        read=read+1
        local ghost=e.type=='entity-ghost'
        local proto=ghost and e.ghost_prototype or e.prototype
        local name=ghost and e.ghost_name or e.name
        local at=string.format('%s%s (%g,%g)',ghost and 'ghost of ' or '',name,e.position.x,e.position.y)
        local okp,src=pcall(function() return proto.electric_energy_source_prototype end)
        if okp and src and not OWN[proto.type] then
          if ghost then
            local okc,covered=pcall(ghost_covered,e,proto)
            if okc and not covered then offn=offn+1; if #off<8 then off[#off+1]=at end end
          else
            local okw,why=pcall(M.unpowered,e)
            if okw and why then offn=offn+1; if #off<8 then off[#off+1]=at..': '..why:gsub('^unpowered: ','') end end
          end
        end
        local okn,nets=pcall(function() return e.surface.find_logistic_networks_by_construction_area(e.position,e.force) end)
        if okn and nets and #nets==0 then outn=outn+1; if #out<8 then out[#out+1]=at end end
      end
    end
    local power=offn>0 and string.format('%d not covered by any pole\'s supply area: %s%s',offn,table.concat(off,'; '),offn>#off and string.format('; +%d more',offn-#off) or '') or nil
    local robots=outn>0 and string.format('%d outside every roboport\'s construction area (robots do not build, repair or rebuild them there): %s%s',outn,table.concat(out,', '),outn>#out and string.format(', +%d more',outn-#out) or '') or nil
    return power,robots
  end
end
-- A batch entry blocked by an entity this batch placed says which entry placed it (Muse, shift13: a pole at
-- (20.5,64.5) inside the assembler's footprint stopped the batch at entry 2). own: {name, position, index}.
function M.own_blockers(why,own)
  if #own==0 or not why:find('blocked by',1,true) then return why end
  local notes={}
  for name,x,y in why:gmatch('([%w%-]+) %((%-?[%d%.]+),(%-?[%d%.]+)%)') do
    x,y=tonumber(x),tonumber(y)
    for _,o in ipairs(own) do
      if x and y and o.name==name and math.abs(o.position.x-x)<0.01 and math.abs(o.position.y-y)<0.01 then
        notes[#notes+1]=string.format('%s (%g,%g) is entry %d of this batch',name,x,y,o.index)
      end
    end
  end
  return #notes>0 and why..'; '..table.concat(notes,'; ') or why
end
-- Batches share item/direction/quality defaults and stop at the first failure,
-- (tiles report the tile instead of an entity)
-- returning only the placed positions; earlier placements stay built. all=true (or skip_failed) builds every entry
-- that can be built and lists the rest with why (Muse, shift13).
M.materials=require('materials'){queued=crafting_count,recipe=hand_recipe,known=known}
function handlers.build(p,a)
  -- Short of an item the hand-craft queue is making: wait for it
  -- (awaiting_craft, outcome fed | failed | timed_out), as transfer does.
  if not a.awaited then
    local need,order={},{}
    for _,b in ipairs(a.builds or {a}) do
      local item=type(b)=='table' and b.item or a.item
      if type(item)=='string' then
        if not need[item] then order[#order+1]=item end
        need[item]=(need[item] or 0)+1
      end
    end
    -- Every item the batch is short of while the queue makes it, not only the first (M.await_crafts).
    local wants={}
    for i,item in ipairs(order) do wants[i]={item=item,need=need[item]} end
    local waiting=M.await_crafts(p,'build',a,wants)
    if waiting then return waiting end
  end
  -- The character stands on the footprint and nothing else does: walk it off
  -- (real walking, a timed action) and build then, as a player steps aside.
  -- The rest of the call reruns from that entry (outcome fed | failed | timed_out).
  local function step_aside(aside,rest)
    rest.awaited=true; rest.stepped=true
    -- A later batch entry from a rerun replaces the running step-aside itself.
    local current=state().active[p.index]
    if current and not current.running then finish(p.index,'replaced') elseif not current then stop(p) end
    local until_tick=game.tick+180
    state().active[p.index]={kind='feed',handler='build',args=rest,aside=aside,until_tick=until_tick,next_check=game.tick}
    -- Not built yet, said so (A2, Muse 21:20: "built: 0" read as nothing placed; the biolab stood there a moment later and
    -- the retry failed for want of the item): what is still to build, and where the result goes.
    local n=rest.builds and #rest.builds or 1
    return {stepping_aside={from=p.position,to=aside.to},until_tick=until_tick,still_to_build=n,
      not_yet=string.format('you stand on the footprint: stepping aside first, then building the %s (a timed call: --wait waits for it; status last.built counts it); the item stays in your inventory until then',
        n==1 and 'entry' or n..' entries')}
  end
  local settings=a.entry_settings or {rows={},wires={},set=0,failed={}}
  local function result(out,complete) return M.entryset.built_result(p,settings,out,complete) end
  if not a.builds then
    -- Out of build reach (autowalk.lua; Sol, shift12: 10.2 to 15.3 tiles off, a guessed standing spot each time): within
    -- 32 tiles the character walks into build reach first, then builds.
    local far=M.build_far(p,a,a)
    if far and M.autowalk.wanted('build',a,{far}) then return M.autowalk.approach(p,'build',a,{point=far.point},M.autowalk.line({far},1,far)) end
    local r,ents=build_one(p,a)
    if not r.aside then
      M.entryset.built(p,a,1,settings)
      r.closed_in=M.closed_in_note(p,ents or {})
      r.outside_logistic_coverage,r.underground_side_feed=M.build_notes(p,ents)
      r.no_power_coverage,r.outside_construction_area=M.coverage_notes(p,ents)
      return result(r,true)
    end
    local rest={}
    for k,v in pairs(a) do rest[k]=v end
    return step_aside(r.aside,rest)
  end
  -- More than 64 entries (d17 batch19 D3, Opus 65 and Sonnet 72, refused): worked in batches of 64 in this call, one
  -- reply (batches says how many), up to 256.
  assert(type(a.builds)=='table' and #a.builds>=1 and #a.builds<=256,'builds requires 1..256 {item,position,direction} entries (more than 64: worked in batches of 64, one reply)')
  assert(a.skip_failed==nil or type(a.skip_failed)=='boolean','skip_failed must be true or false')
  assert(a.all==nil or type(a.all)=='boolean','all must be true or false')
  local skip=a.skip_failed==true or a.all==true
  -- A batch of mining drills tries every entry unless all: false (batch24 C1, Sonnet: a drill batch stopped at a spot a
  -- ghost or a pole blocked, the rest untried): each spot left is named with what blocked it (left).
  local drills=a.all==nil and a.skip_failed==nil
  for _,b in ipairs(a.builds) do
    local okp,kind=pcall(function() return prototypes.item[(type(b)=='table' and b.item) or a.item or ''].place_result.type end)
    if not (okp and kind=='mining-drill') then drills=false end
  end
  if drills then skip=true end
  local placed,failed,inserters,built={},{},{},{}
  -- What each entry of this batch placed, for a later entry it blocks (M.own_blockers); carried over a rerun.
  local own={}
  for _,o in ipairs(a.own_before or {}) do own[#own+1]=o end
  -- Tile entries: what their tiles took away (water-cane, fish) and what of a brush did not go down (Sol 12:55).
  local tiles_removed,tiles_not_placed={},{}
  local grids={}
  for _,f in ipairs(a.failed_before or {}) do failed[#failed+1]=f end
  for _,e in ipairs(a.built_ents or {}) do built[#built+1]=e end
  for i,b in ipairs(a.builds) do
    local ok,result,ents=pcall(function()
      assert(type(b)=='table','each build must be an object')
      -- Out of build reach (autowalk.lua; Sonnet, shift12: a 27-entry batch from 4 spots, re-sent from each): within 32
      -- tiles the character walks there first and builds from this entry on (the entry walked to is not walked to again).
      if a.walked_entry~=i then
        local far=M.build_far(p,b,a)
        if far then
          local rest={}
          for k,v in pairs(a) do rest[k]=v end
          rest.builds={}
          for j=i,#a.builds do rest.builds[#rest.builds+1]=a.builds[j] end
          if M.autowalk.wanted('build',rest,{far}) then return {walk=far} end
        end
      end
      -- An entry's recipe, else the call's for an entry that places an assembling machine.
      local recipe=b.recipe
      if recipe==nil and a.recipe~=nil then
        local it=prototypes.item[b.item or a.item or '']
        local pr=it and it.place_result
        if pr and pr.type=='assembling-machine' then recipe=a.recipe end
      end
      local r,ents=build_one(p,{item=b.item or a.item,position=b.position,direction=b.direction or a.direction,quality=b.quality or a.quality,type=b.type,size=b.size or a.size,
        entity=b.entity or a.entity,stepped=a.stepped and i==1,recipe=recipe})
      assert(r.aside or r.consumed>0,'nothing was placed')
      return r,ents
    end)
    for _,e in ipairs(ok and ents or {}) do built[#built+1]=e end
    -- A partial batch is a failure, so plan on_fail policies see it; the
    -- entries before it stay built. all (or skip_failed; shake3: Grok and Astra
    -- wanted the rest built) lists the entry and goes on.
    if not ok and skip then
      failed[#failed+1]={index=i+(a.index_before or 0),item=type(b)=='table' and (b.item or a.item) or nil,
        position=type(b)=='table' and b.position or nil,error=M.own_blockers(reason(result),own)}
    elseif not ok then
      -- The entries built before it still stand: what they closed is said (friction2: Gemini's 19:25 batch failed
      -- after 2 built, and those 2 closed the last gap out with no word of it; the dry runs had named them).
      local note=#built>0 and M.closed_in_note(p,built) or nil
      local n,total=i+(a.index_before or 0),#a.builds+(a.index_before or 0)
      local untried=n<total and string.format('; entries %d-%d were not tried (all: true tries every entry)',n+1,total) or ''
      if n==total-1 then untried=string.format('; entry %d was not tried (all: true tries every entry)',total) end
      local set=M.entryset.built_result(p,settings,{},false)
      error(string.format('build %d/%d failed after %d built: %s%s%s',i,#a.builds,#placed,M.own_blockers(reason(result),own),note and '; '..note or '',untried)
        ..(set.settings_line and '; '..set.settings_line or '')..(set.settings_note and '; '..set.settings_note or ''))
    elseif result.aside or result.walk then
      local rest={builds={}}
      for k,v in pairs(a) do if k~='builds' then rest[k]=v end end
      for j=i,#a.builds do rest.builds[#rest.builds+1]=a.builds[j] end
      rest.entry_settings=settings
      rest.built_before=(a.built_before or 0)+#placed
      rest.index_before=(a.index_before or 0)+i-1
      rest.failed_before=#failed>0 and failed or nil
      rest.built_ents=#built>0 and built or nil
      rest.own_before=#own>0 and own or nil
      rest.walked_entry=nil
      local out
      if result.walk then
        -- The rest is made where the walk ends, this entry first (autowalk.lua).
        rest.walked_entry=1
        local n,total=i+(a.index_before or 0),#a.builds+(a.index_before or 0)
        out=M.autowalk.approach(p,'build',a,{point=result.walk.point},string.format('entry %d of %d: %s',n,total,M.autowalk.line({result.walk},1,result.walk)),rest)
      else out=step_aside(result.aside,rest) end
      -- stepping aside: built_so_far (the entries before it), not built (A2)
      if out.stepping_aside then out.built_so_far=#placed else out.built=#placed end
      out.placed=#placed>0 and placed or nil; out.failed=#failed>0 and failed or nil
      return M.entryset.built_result(p,settings,out,false)
    else
      M.entryset.built(p,b,i+(a.index_before or 0),settings)
      local e=result.entity or (result.entities and result.entities[1])
      placed[#placed+1]=e and e.position or b.position
      -- (d23 batch120 CC1) a vehicle built with a grid: what the grid holds
      if e and type(e.equipment)=='table' and #grids<16 then
        grids[#grids+1]=string.format('%s %s (%g,%g): grid %s %s',e.name,tostring(e.unit_number),e.position.x,e.position.y,e.equipment.grid,e.equipment.equipment)
      end
      if e and e.name and e.position then own[#own+1]={name=e.name,position=e.position,index=i+(a.index_before or 0)} end
      -- (summary gives an inserter's pickup tile, and only an inserter's)
      if e and e.pickup~=nil then inserters[#inserters+1]=e.position end
      local n=i+(a.index_before or 0)
      if result.removed and #tiles_removed<16 then tiles_removed[#tiles_removed+1]='#'..n..': '..result.removed end
      if result.not_placed and #tiles_not_placed<16 then tiles_not_placed[#tiles_not_placed+1]='#'..n..': '..result.not_placed end
    end
  end
  -- The batch's inserters with nothing on a pickup or drop point once all
  -- its entries stand (a chest built after its inserter counts; targets.lua):
  -- the first 16, and the count of all past them, as place_ghosts gives them.
  local loose,nloose
  for _,pos in ipairs(inserters) do
    local e=p.surface.find_entities_filtered{position=pos,type='inserter',limit=1}[1]
    local ok,t=pcall(function() return e and M.targets.plan(e.surface,e.prototype,e.position,e.direction) end)
    if ok and t and t.missing then
      loose=loose or {}; nloose=(nloose or 0)+1
      if #loose<16 then loose[#loose+1]={name=e.name,position=e.position,missing=t.missing,pickup=t.pickup,drop=t.drop} end
    end
  end
  local cover,side=M.build_notes(p,built)
  local no_power,outside=M.coverage_notes(p,built)
  local okb,last_belt=pcall(M.beltflow.last,built)
  -- Two or more belts: each one's line, the tile its items move to (last_belt stays the last one's).
  local okl,belt_lines,belts_more=pcall(M.beltflow.lines,built)
  if not (okl and #belt_lines>1) then belt_lines,belts_more=nil,nil end
  -- all: how many of the batch's entries stand and how many were not built.
  local total=#a.builds+(a.index_before or 0)
  local summary=skip and #failed>0 and string.format('%d of %d built; %d not built (failed)',#placed+(a.built_before or 0),total,#failed) or nil
  local left
  if drills and #failed>0 then
    left={}
    for _,f in ipairs(failed) do
      local q=f.position
      left[#left+1]=string.format('#%d%s: %s',f.index,type(q)=='table' and q.x and string.format(' (%g,%g)',q.x,q.y) or '',tostring(f.error))
    end
  end
  local entries=#a.builds+(a.index_before or 0)
  return result({built=#placed,placed=placed,built_before=a.built_before,failed=#failed>0 and failed or nil,summary=summary,inserters_without_target=loose,
    left=left,left_note=left and 'a batch of mining drills tries every entry (all: false stops at the first not built)' or nil,
    batches=entries>64 and string.format('%d entries in %d batches of up to 64, one reply',entries,math.ceil(entries/64)) or nil,
    inserters_without_target_count=nloose and nloose>#loose and nloose or nil,
    closed_in=M.closed_in_note(p,built),outside_logistic_coverage=cover,no_power_coverage=no_power,outside_construction_area=outside,underground_side_feed=side,last_belt=okb and last_belt or nil,
    belts=belt_lines,belts_more=belts_more and belts_more>0 and belts_more or nil,
    tiles_removed=#tiles_removed>0 and tiles_removed or nil,removed_note=#tiles_removed>0 and M.bots.REMOVED_NOTE or nil,
    tiles_not_placed=#tiles_not_placed>0 and tiles_not_placed or nil,equipment=#grids>0 and grids or nil},true)
end
-- Red, green and copper wires, as a player drags them (circuits.lua).
function handlers.wire(p,a) return M.circuits.wire(p,a) end
M.build_with_materials=handlers.build
function handlers.build(p,a)
  assert(a.dry_run==nil or type(a.dry_run)=='boolean','dry_run must be true or false')
  local materials=M.materials.build(p,a)
  local ok,out=pcall(M.build_with_materials,p,a)
  if not ok then error(reason(out)..'; materials before build: '..M.materials.line(materials),0) end
  out.materials=materials
  return out
end
-- build {retry_when_clear: true} (batch26 C1, Haiku: 23 poles held while the walks to (-187.5,-29.5) and (-187.5,-41.5) lay in
-- an area under attack): as rearm's and transfer's: refused for an area under attack at the entry the walk goes to (the
-- walk's own goal check: passing enemies; a worm or spawner stays and is refused as before), it waits until no enemy
-- unit is within 48 tiles there (wait_until units_clear, retry_ticks, default 5 min), then builds again, at most 6 times.
M.build_now=handlers.build
function handlers.build(p,a)
  M.fluid_guard(p,a,'build')
  if a.retry_when_clear==nil then return M.build_now(p,a) end
  assert(type(a.retry_when_clear)=='boolean','retry_when_clear must be true or false')
  local rest={}
  for k,v in pairs(a) do if k~='retry_when_clear' and k~='retry_ticks' and k~='retries' then rest[k]=v end end
  if not a.retry_when_clear then return M.build_now(p,rest) end
  local tries=integer(a.retries,0,0,6,'retries')
  local ticks=integer(a.retry_ticks,18000,600,54000,'retry_ticks')
  local ok,out=pcall(M.build_now,p,rest)
  if ok then return out end
  local first=rest.position or (type(rest.builds)=='table' and type(rest.builds[1])=='table' and rest.builds[1].position)
  local at=first and position(first)
  local okc,chk=pcall(function() return at and M.avoid.goal_check(p,p.position,at,M.avoid.mode(rest.avoid_enemies)) end)
  if not (okc and chk and chk.m and chk.m.attack) or tries>=6 then error(out,0) end
  local w=handlers.wait_until(p,{['until']='units_clear',position=at,radius=48,timeout=ticks})
  local now=state().active[p.index]
  if not now then w=handlers.wait_ticks(p,{ticks=1800}); now=state().active[p.index]; w.cleared='no enemy unit within 48 tiles now; the area under attack counts 30 s past its last hit' end
  if now then
    local again={}
    for k,v in pairs(rest) do again[k]=v end
    again.retry_when_clear=true; again.retry_ticks=ticks; again.retries=tries+1
    now.then_call={action='build',args=again}
  end
  w.retry=string.format('refused for an area under attack: %s; waits until no enemy unit is within 48 tiles of (%g,%g) (at most %d s), then builds again (try %d of 6)',
    reason(out),at.x,at.y,math.floor(ticks/60),tries+1)
  return w
end
function handlers.build_path(p,a)
  assert(not p.permission_group or p.permission_group.allows_action(defines.input_action.start_walking),'permission denied: start_walking')
  local action=construction.plan(p,a)
  action.bounds=M.cell_bounds(action.cells,function(c) return c.position end)
  -- (d20 batch67 AC2) what already feeds the belt tiles it will lay
  local ents={}
  for i,c in ipairs(action.cells) do if i>=(action.next_index or 1) then ents[#ents+1]={name=action.entity_name,position=c.position,direction=c.direction} end end
  local feeders=M.routefeeds.check(p.surface,p.force,ents)
  if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
  state().active[p.index]=action
  return {until_tick=action.until_tick,total=#action.cells,next_index=action.next_index,feeders=feeders}
end
function handlers.kite(p,a)
  -- retreat {to, ...} or the standing guard: the generic retreat (retreat.lua) instead of kite's own stop at
  -- min_health; retreat {x,y} keeps kite's own retreat (walk straight there firing).
  local legacy=type(a.retreat)=='table' and a.retreat.to==nil and a.retreat.retreat_to==nil and (a.retreat.x~=nil or a.retreat[1]~=nil)
  local back=not legacy and M.retreat.config(p,a,'kite') or nil
  if back then
    local plain={}
    for k,v in pairs(a) do if k~='retreat' then plain[k]=v end end
    if plain.min_health==nil then plain.min_health=0 end
    a=plain
  end
  local action=kite.plan(p,a)
  if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
  -- Kiting owns both walking and shooting; a separate shoot would fight it.
  if state().combat and state().combat[p.index] then stop_combat(p.index,'replaced') end
  state().active[p.index]=action
  if back then M.retreat.arm(p,action,back) end
  return {until_tick=action.until_tick,ammo=action.ammo_start,equipped=action.equipped,retreat=back and M.retreat.line(back) or nil}
end
function handlers.construct(p,a)
  assert(not p.permission_group or p.permission_group.allows_action(defines.input_action.start_walking),'permission denied: start_walking')
  local box
  if a.area then
    local lt,rb=position(a.area.left_top),position(a.area.right_bottom)
    assert(rb.x>lt.x and rb.y>lt.y and rb.x-lt.x<=256 and rb.y-lt.y<=256,'area must be nonempty and at most 256x256')
    box={left_top=lt,right_bottom=rb}
  else
    local b=state().last_paste and state().last_paste[p.index]
    assert(b,'no area given and no earlier paste to construct')
    -- Bounds hold ghost centres; pad so whole footprints are searched.
    box={left_top={x=b.left-0.5,y=b.top-0.5},right_bottom={x=b.right+0.5,y=b.bottom+0.5}}
  end
  assert(a.dry_run==nil or type(a.dry_run)=='boolean','dry_run must be true or false')
  assert(a.outside_robots==nil or type(a.outside_robots)=='boolean','outside_robots must be true or false')
  -- outside_robots (rebuild, lostlog.lua): leave the ghosts robots can build (idle robots and the item in a network
  -- whose construction area covers them) to the robots.
  local keep
  if a.outside_robots then
    local nets={}
    keep=function(g)
      local item=g.type=='entity-ghost' and g.ghost_prototype.items_to_place_this and g.ghost_prototype.items_to_place_this[1]
      local best=M.lostlog.robots(p.surface,p.force,g.position,item and item.name,nets)
      return not (best and best.idle>0 and best.has>0)
    end
  end
  local materials,ghosts=M.materials.ghosts(p,box,keep)
  if a.dry_run then return {dry_run=true,total=#ghosts,materials=materials,note='material check only; nothing built, mined, marked or crafted; before recovered items; hand-craftable counts are independent'} end
  local action=construction.plan_ghosts(p,a,box,ghosts)
  action.report={materials=materials}
  action.bounds={left=box.left_top.x,top=box.left_top.y,right=box.right_bottom.x,bottom=box.right_bottom.y}
  if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
  state().active[p.index]=action
  -- Nothing to do is done: plans continue rather than pausing on an error.
  if #action.pending==0 then finish(p.index,'nothing_to_do'); return {total=0,built=0,outcome='nothing_to_do',left_out=action.left_out} end
  return {until_tick=action.until_tick,total=#action.pending,materials=materials,left_out=action.left_out,line=construction.plan_line(p,action),
    avoid_enemies=action.avoid_mode and M.avoid.describe(action.avoid_mode) or nil}
end
-- Its parts are profile parts inspect.<part> (operator 18:33: inspect 70 ms on average, one call 287 ms).
M.INSPECT_POSITIONS=8
function handlers.inspect(p,a)
  local e,by=M.timed('inspect.entity',entity,p,a,true)
  M.readmemory.observe(e,p)
  local out=M.timed('inspect.summary',summary,e); out.inventories={}
  out.by=by
  -- its quality, normal too (Astra #2087)
  if e.type~='tile-ghost' then out.quality=out.quality or 'normal' end
  -- What hit it, where our force saw (damagelog.lua): newest first.
  local okdl,dl=pcall(M.damagelog.of,e)
  out.damage_history=okdl and dl or nil
  -- A vehicle's equipment grid (a tank's, a spidertron's), as its GUI shows it (grids.lua).
  local okg,grid=pcall(function() return e.grid end)
  if okg and grid then out.equipment=M.grids.view(grid) end
  -- A bot aboard a platform has no body to reach with (remote view only).
  local okr,inr=pcall(function() return p.can_reach_entity(e) end)
  out.in_reach=okr and inr==true
  out.health=e.health; out.max_health=e.max_health; out.direction=e.direction
  -- A turret's priority targets and Ignore unprioritised targets, built or ghost (M.turret_targets).
  local okt,tt=pcall(M.turret_targets,e)
  if okt and tt then out.priority_targets=tt.list; out.ignore_unprioritised=tt.ignore; out.targeting=tt.line end
  -- A built turret's kills and damage dealt, as its tooltip shows them (turrettally.lua; d20 batch60 V3).
  local okk,kd=pcall(M.turrettally.read,e)
  if okk and kd then out.kills=kd.kills; out.damage_dealt=kd.damage_dealt end
  -- The engine's status number and its defines.entity_status name beside it (Muse, shift10: --format json gave 14, 26,
  -- 27 to look up); an entity no pole reaches says so in power ("unpowered: ...") while the engine reads low_power.
  out.status=e.status
  out.status_name=entity_status_names[out.status]
  -- a captive spawner not producing: its health, the minutes it has left and why (pushalerts.lua; d17 batch18 C6)
  if e.name=='captive-biter-spawner' then local okc,_,line=pcall(M.pushalerts.captive,e); out.starving=okc and line or nil end
  out.energy=e.energy
  out.fluids=e.get_fluid_contents()
  out.electric_network_id=e.electric_network_id
  -- A producer's or consumer's maximum and its network's now (networks.lua; Astra, 13:10). (power is summary's
  -- "unpowered: ..." line.)
  local okp,pw=pcall(M.timed,'inspect.power',M.networks.entity_power,e)
  out.electricity=okp and pw or nil
  -- A fusion reactor: the reactors its plasma joins, its bonus, its most at its quality and its measured rates (Z6).
  if e.type=='fusion-reactor' then local okf,fu=pcall(M.fusion.read,e); out.fusion=okf and fu or nil end
  -- A rail or chain signal: its rail layer, the rails it is attached to and its block state (AG1).
  do local oks,sg=pcall(M.railsignal.read,e); out.signal=oks and sg or nil end
  -- A locomotive or wagon: its facing, couplings and train's locomotives each way (AG2).
  do local okr,rs=pcall(M.rollingstock.read,e); out.rolling_stock=okr and rs or nil end
  -- Inserters: the exact pickup/drop points, the tiles they are on, and what
  -- stands there (the same view as scan fields=io).
  -- An inserter's Spoil priority (built or ghost; Sol, 18:15).
  -- Its wait for a full hand (built or ghost; d22 batch104 BN2, luna #1931): the prototype's, fixed in 2.0.77 (details.lua).
  if e.type=='inserter' or (e.type=='entity-ghost' and e.ghost_type=='inserter') then
    out.spoil_priority=M.read_spoil_priority(e)
    out.wait_for_full_hand=M.details.wait_for_full_hand(e)
  end
  if e.type=='inserter' or e.type=='mining-drill' then
    out.pickup_position=e.type=='inserter' and e.pickup_position or nil
    local okd,drop=pcall(function() return e.drop_position end)
    out.drop_position=okd and drop or nil
    local ok,io=pcall(scan_fields.io,e)
    if ok then out.io=io end
  end
  -- Fluid connections: where each one is, the neighbouring tile it joins,
  -- its flow, and what is connected there (in scan fields=fluids form too).
  local okc,conns=pcall(M.timed,'inspect.fluids',pipes.connections,e)
  if okc and conns and #conns>0 then
    out.fluid_connections={}
    for i,c in ipairs(conns) do
      local target=c.target
      out.fluid_connections[i]={box=c.box,flow=c.flow,kind=c.kind,fluid=c.fluid,
        at={x=c.x+0.5,y=c.y+0.5},joins={x=c.tx+0.5,y=c.ty+0.5},direction=compass_names[c.dir],
        connected_to=target and target.valid and target.name or nil,underground_reach=c.reach}
    end
    local okf,text=pcall(M.timed,'inspect.fluids',pipes.fluids,e)
    if okf and text then out.fluids_summary=text end
  end
  -- A ghost with a recipe: the ports that recipe opens, each with its fluid
  -- (ports.lua), in place of every port the prototype has.
  if e.type=='entity-ghost' then
    local okp,rows,closed,recipe=pcall(function()
      local okr,r=pcall(function() return e.get_recipe() end)
      r=okr and r or nil
      local list,shut=M.ports.rows({prototype=e.ghost_prototype,position=e.position,direction=e.direction,mirroring=e.mirroring},r)
      return list,shut,r
    end)
    if okp and recipe and (#rows>0 or #closed>0) then
      out.fluid_connections=#rows>0 and rows or nil; out.fluids_summary=nil
      out.fluid_connections_closed=#closed>0 and closed or nil; out.fluid_recipe=recipe.name
    end
  end
  -- Heat (Sol, shift13 16:50: Gleba's heat power): the temperature and its maximum, and each heat connection with
  -- what joins it there (dryrun.lua heat_points: the prototype's connections turned with the entity).
  local okh,heat=pcall(function()
    local proto=e.type=='entity-ghost' and e.ghost_prototype or e.prototype
    local pts=M.dryrun.heat_points(proto,e.position,e.direction)
    if #pts==0 then return nil end
    local rows={}
    for _,c in ipairs(pts) do
      rows[#rows+1]=string.format('%s at (%g,%g): %s',compass_names[c.dir] or tostring(c.dir),c.tx+0.5,c.ty+0.5,M.dryrun.heat_there(e.surface,e.force,c))
    end
    local h={connections=rows}
    if e.type~='entity-ghost' then
      local okt,t=pcall(function() return e.temperature end)
      h.temperature=okt and type(t)=='number' and math.floor(t*10+0.5)/10 or nil
      local okm,mx=pcall(function() return proto.heat_buffer_prototype.max_temperature end)
      h.max_temperature=okm and mx or nil
    end
    return h
  end)
  out.heat=okh and heat or nil
  out.heating=M.heating.inspect(p,e)
  if e.type=='transport-belt' or e.type=='underground-belt' or e.type=='splitter' then
    out.belt_lines={}
    for i=1,e.get_max_transport_line_index() do out.belt_lines[i]=e.get_transport_line(i).get_contents() end
  end
  -- Spoilage (spoil.lua): per inventory each spoilable item, its first stack
  -- to spoil (time left, % spoiled) and how many within 5 min; a belt's lanes,
  -- an inserter's hand and an item on the ground too; items that hatch into
  -- enemies say so, and hatch_warning sums them up.
  local spoiling,all={},{}
  for name in pairs(inventories) do
    local ok,inv=pcall(inventory,e,name)
    if ok then
      out.inventories[name]=contents(inv)
      local acc=M.timed('inspect.spoil',M.spoil.inventory,inv,{},name)
      for _,line in ipairs(M.spoil.lines(acc,8,name..': ')) do spoiling[#spoiling+1]=line end
      -- Each spoilable item's spread, not only its oldest stack (Sol, 22:25).
      for i,r in ipairs(acc) do
        if i<=8 then out.freshness=out.freshness or {}; out.freshness[#out.freshness+1]=name..': '..M.spoil.spread_text(r) end
      end
      M.timed('inspect.spoil',M.spoil.inventory,inv,all,name)
    end
  end
  do
    local acc={}
    if e.type=='transport-belt' or e.type=='underground-belt' or e.type=='splitter' or e.type=='loader' or e.type=='loader-1x1' or e.type=='linked-belt' then M.spoil.belt(e,acc,'belt')
    elseif e.type=='inserter' then M.spoil.add(acc,e.held_stack,'hand')
    elseif e.type=='item-entity' then M.spoil.add(acc,e.stack,'ground') end
    for _,r in ipairs(acc) do all[#all+1]=r; all[r.key]=all[r.key] or r end
    for _,line in ipairs(M.spoil.lines(acc,8,(acc[1] and acc[1].where or '')..': ')) do spoiling[#spoiling+1]=line end
  end
  if #spoiling>0 then out.spoiling=spoiling end
  out.hatch_warning=M.spoil.warning(all)
  -- What its next products start at: the inherited spoilage (spoil.lua).
  if e.type=='assembling-machine' or e.type=='furnace' then
    local okr,line=pcall(M.timed,'inspect.spoil',M.spoil.recipe_output,e)
    out.output_spoil=okr and line or nil
  end
  -- An agricultural tower: state, seeds, output, its cells and plants (farm.lua).
  if e.type=='agricultural-tower' then
    local okt,tower=pcall(M.farm.tower,e,{status_name=function(x) return entity_status_names[x.status] end,
      flow=function(item) return M.farm_flow(p,e.surface,item) end})
    out.tower=okt and tower or nil
  end
  if e.type=='rocket-silo' and space then
    local okw,weight=pcall(space.rocket_weight,e)
    out.rocket_weight=okw and weight or nil
  end
  -- A silo's rocket in words, parts and rocket_ready side by side, and its last launch (silo.lua M.rocket; Astra 10:50).
  if e.type=='rocket-silo' then
    local okr,rk=pcall(M.silo.rocket,e)
    if okr then out.parts=rk.parts; out.built_parts=rk.built_parts; out.next_parts=rk.next_parts; out.rocket_ready=rk.rocket_ready; out.rocket=rk.rocket; out.last_launch=rk.last_launch; out.launch_count=rk.launch_count; out.launch_count_since=rk.launch_count_since end
    -- Its inventories by transfer name, alias, what each holds and is for, and a call for each (Luna 12:20).
    local oki,rows=pcall(M.silo.inventories,e,M.aliases.encode)
    out.silo_inventories=oki and rows or nil
  end
  -- Module slots and their inventory index (blueprint item requests name it).
  local okm,mods=pcall(function()
    local inv=e.get_module_inventory()
    return inv and {inventory_index=inv.index,slots=#inv,contents=contents(inv)}
  end)
  -- A ghost's module slots, and the modules requested or being taken out (configure modules; modules.lua).
  if not (okm and mods) and e.type=='entity-ghost' then
    local n=pcall(function() return e.ghost_prototype.module_inventory_size end) and e.ghost_prototype.module_inventory_size or 0
    if n>0 then okm,mods=true,{slots=n} end
  end
  if okm and mods then
    local okr,req=pcall(M.modules.requests,e)
    if okr and req then mods.requested=req.requested; mods.removing=req.removing end
    local oks,lines=pcall(M.modules.by_slot,e)
    if oks and lines then mods.by_slot=lines end
  end
  out.modules=okm and mods or nil
  -- A burner whose burnt-result slot is full: what fills it and what that does (burnt.lua), whatever status_name reads.
  local okb,burnt_line=pcall(M.burnt.line,e,nil,entity_status_names[e.status])
  out.burnt_result_full=okb and burnt_line or nil
  -- Filters, held stack, pickup/drop targets, marks, ghosts on the footprint
  -- (details.lua); on a platform, the hub's slots and what holds up its building.
  if M.details then M.timed('inspect.details',M.details.inspect,e,out) end
  -- An inserter ghost: what stands on its pickup and drop points, as a
  -- built one would have them (targets.lua).
  if e.type=='entity-ghost' and e.ghost_type=='inserter' then
    local okt,t=pcall(M.targets.ghost,e)
    if okt and t then out.pickup_target=t.pickup; out.drop_target=t.drop; out.io_warning=t.missing end
  end
  -- Circuit network: settings, each wire's far end, the signals now (circuits.lua).
  -- (d24 batch136 PH1, Sol #2104) signals: the counts of those named on each network, whatever the cap.
  local picks=a.signals~=nil and M.circuits and M.circuits.parse_signals(a.signals,'signals') or nil
  if M.circuits then local okc,c=pcall(M.timed,'inspect.circuits',M.circuits.read,e,nil,picks); if okc and c then out.circuit=c end end
  if picks and not out.circuit then out.signals_picked='no red or green network: nothing to read' end
  -- A combinator's description (d20 batch56 R4), as its GUI shows it.
  if out.circuit and out.circuit.description then out.description=out.circuit.description end
  -- Who placed it or its ghost, when, through which request; the game's last user (ghostlog.lua; d20 batch56 R7).
  local okpl,placed=pcall(M.ghostlog.read,e)
  out.placed=okpl and placed or nil
  -- An inserter in one line (Luna, d15: misrouting arms): condition and its signals now, wires, filters, pickup and drop.
  if M.circuits and e.type=='inserter' then local okl,l=pcall(M.circuits.inserter_line,e,out.circuit); if okl then out.inserter_line=l end end
  -- A roboport or logistic chest: its logistic network's id, areas and robots, or that it has none; a roboport's own cell (networks.lua).
  if M.networks and (e.type=='roboport' or e.type=='logistic-container') then
    local okn,ln=pcall(M.timed,'inspect.logistic',M.networks.of_entity,e); if okn and ln then out.logistic_network=ln end
  end
  local okp,pl=pcall(function() return e.surface.platform end)
  if okp and pl and space then
    if e.type=='space-platform-hub' then
      out.hub_slots=space.hub_slots(e)
      -- The platform's flight: speed, the leg and the km left on it, minutes at this speed, the next stop.
      local okf,flight=pcall(space.flight,pl)
      out.flight=okf and flight or nil
      local okr,repair=pcall(space.repair_view,pl)
      if okr then out.repair_packs,out.damaged,out.damaged_count=repair.repair_packs,repair.damaged,repair.damaged_count end
    end
    if e.health and e.max_health and e.health<e.max_health then out.repair=space.REPAIR_NOTE end
    if e.type=='space-platform-hub' or e.type=='entity-ghost' or e.type=='tile-ghost' or out.marked_for_deconstruction or out.ghosts_here then
      local okb,blocked=pcall(space.blockers,pl)
      out.construction_blocked=okb and blocked or nil
    end
    -- A marked foundation tile (its deconstructible-tile-proxy) or a tile ghost: what holds it (platformtiles2).
    if e.type=='deconstructible-tile-proxy' or e.type=='tile-ghost' then
      local okt,note=pcall(space.tile_note,pl,e)
      out.tile_wait=okt and note or nil
    end
  end
  -- Trash slots: one line naming what is there and how to take it.
  for name,list in pairs(out.inventories) do
    if name:find('_trash$') and #list>0 then
      local parts={}
      for i,s in ipairs(list) do parts[i]=s.count..' '..s.name..(s.quality and s.quality~='normal' and '@'..s.quality or '') end
      out.trash=table.concat(parts,', ')..' (in '..name..', put there by the game; take: transfer {position, direction=to_player, inventory='..name..'}, item= for one kind)'
    end
  end
  -- Every slot taken (Sol, 22:08: a requester's 48 slots, 494 spoilage among them, and robots could not deliver
  -- bioflux): what fills them; a requester or buffer chest names the requests that cannot come in.
  -- A cargo wagon's slots per item, free slots, filters and limit (batch25 C2, Muse).
  if e.type=='cargo-wagon' and M.trains then
    local okw,ws=pcall(M.trains.wagon_slots,e)
    if okw and ws then out.wagon_slots=ws.line end
  end
  if e.type=='container' or e.type=='logistic-container' or e.type=='cargo-wagon' or e.type=='car' or e.type=='spider-vehicle' then
    local okf,full=pcall(M.slots.full_of,e,nil)
    if okf and full then
      out.slots_full=full.text
      local okp,pt=pcall(function() return e.get_logistic_point(defines.logistic_member_index.logistic_container) end)
      local blocked={}
      for _,f in ipairs(okp and pt and pt.filters or {}) do
        local name=type(f.name)=='table' and f.name.name or f.name
        if name and (f.count or 0)>0 and e.get_item_count(name)<f.count and M.slots.full_of(e,name) then blocked[#blocked+1]=name end
      end
      if #blocked>0 then out.requests_blocked=table.concat(blocked,', ')..': requested, and no slot takes them' end
      local oki,one=pcall(M.reqchest.one_item,e)
      if oki and one then out.one_item=one.line end
      -- A full chest (Astra, Luna, shift19): the machines whose output waits on it, and the nearest chests with a free slot.
      if e.type=='container' or e.type=='logistic-container' then
        local fc=M.supply.fullchest
        local okw,r=pcall(fc.read,e)
        if okw and r then out.slots_used=string.format('%d/%d',r.used,r.total); out.output_waits=r.line:match('; (.*)$') end
        local okn,near=pcall(M.timed,'inspect.free_chests',fc.nearest_free,e)
        out.free_chests_near=okn and near or nil
      end
    end
  end
  if e.type=='assembling-machine' or e.type=='furnace' then
    -- Spoilage its recipe does not take, in its input (Sol, 22:08).
    local oks,sp=pcall(M.slots.input_spoilage,e)
    out.input_spoilage=oks and sp and sp.text or nil
    local recipe=e.get_recipe(); out.recipe=recipe and recipe.name or false
    -- Set recipe on: what its wires give, and why it has no recipe when it has none (circrecipe.lua; Sol #1515).
    if e.type=='assembling-machine' then local okc,cr=pcall(M.circrecipe.read,e); out.circuit_recipe=okc and cr or nil end
    out.crafting_progress=e.crafting_progress
    -- Crafts and output per minute at its speed and productivity now (craftrate.lua; Sol, 15:20).
    local okr,rate=pcall(M.timed,'inspect.craftrate',M.craftrate.machine,e)
    out.rate=okr and rate or nil
    local okf,fill=pcall(M.output_fill,e)
    out.output_fill=okf and fill or nil
    -- Where its output stops it, per product, and what full_output means now (outputstop.lua; Sol, shift17 12:20).
    local oko,stop=pcall(M.timed,'inspect.outputstop',M.outputstop.read,e,out.status_name)
    out.output_stop=oko and stop or nil
    -- An ingredient short of a craft while another is stacked, and who feeds the machine (inputs.lua; Grok, shift11).
    local oki,bal=pcall(M.timed,'inspect.inputs',M.inputs.check,e,out.status_name)
    if oki and bal then out.input_imbalance,out.feeders,out.feeders_count=bal.input_imbalance,bal.feeders,bal.feeders_count end
  end
  return out
end
-- How full an assembler's or furnace's output is (Muse: which of the machines fed by hand wait on their output): each
-- product held of its stack size, and full when the machine has stopped for it: status full_output with a stack that
-- takes no further craft ("copper-cable 200/200 (100%), full"). full_output below that is an idle machine holding a
-- few crafts' worth (outputstop.lua): "cryogenic-science-pack 45/200 (23%), status full_output below its limit".
function M.output_fill(e)
  local inv=e.get_output_inventory and e.get_output_inventory()
  if not inv then return nil end
  local parts={}
  for i=1,#inv do
    local s=inv[i]
    if s.valid_for_read then
      local size=(s.prototype and s.prototype.stack_size) or (prototypes.item[s.name] and prototypes.item[s.name].stack_size) or 1
      parts[#parts+1]=string.format('%s %d/%d (%d%%)',s.name,s.count,size,math.floor(s.count*100/size+0.5))
    end
  end
  local status=defines.entity_status and defines.entity_status.full_output
  local full=status~=nil and e.status==status
  if not full then return #parts==0 and 'empty' or table.concat(parts,', ') end
  -- At its limit: a product whose stack or output box takes no further craft (outputstop.lua).
  local at,fluid_at=false,false
  local ok,stop=pcall(M.outputstop.read,e,'full_output')
  for _,p in ipairs(ok and stop and stop.products or {}) do
    if p.full then if p.fluid then fluid_at=true else at=true end end
  end
  -- No recipe read: a full stack.
  if not (ok and stop) then
    for i=1,#inv do
      local s=inv[i]
      if s.valid_for_read and s.count>=((s.prototype and s.prototype.stack_size) or (prototypes.item[s.name] and prototypes.item[s.name].stack_size) or 1) then at=true end
    end
  end
  local tail=at and ', full' or fluid_at and ', full (a fluid output: output_stop)' or ', status full_output below its limit (output_stop)'
  if #parts==0 then return 'empty'..tail end
  return table.concat(parts,', ')..tail
end
-- inspect over positions (Muse surveys 6 assemblers every 5 minutes, one call each): one inspect per entry, in order;
-- an entry that fails is its position and error. Each entry may carry name or unit_number.
-- inspect over an area (Gemini, shift10: dozens of single inspects to check buffer chests' balances): our entities
-- with an inventory whose centre is in the area and that inspect can read (in sight, or by remote view in a chunk
-- our force sees now: read_sight), at most 64, one compact row each (name, position, holds, requests, recipe,
-- status_name), in reading order (top row first, then left to right).
do
  local inspect_live=handlers.inspect
  local function inspect_one(p,a) return M.readmemory.read(p,a,'inspect',inspect_live) end
  local MAX_SIDE,MAX_ROWS=128,64
  local STORES={'chest','cargo_wagon','car_trunk','spider_trunk','cargo_landing_pad_main','hub_main'}
  -- A machine's inventories as its GUI groups them, each with a short label.
  local PARTS={{'furnace_source','in'},{'assembling_machine_input','in'},{'lab_input','packs'},{'agricultural_tower_input','seeds'},
    {'furnace_result','out'},{'assembling_machine_output','out'},{'agricultural_tower_output','out'},{'asteroid_collector_output','out'},
    {'rocket_silo_rocket','cargo'},{'turret_ammo','ammo'},{'artillery_turret_ammo','ammo'},{'fuel','fuel'},{'burnt_result','burnt'},
    {'roboport_robot','robots'},{'roboport_material','repair packs'}}
  local CHESTS={container=true,['logistic-container']=true,['linked-container']=true}
  -- A belt's items are on its transport lines, not in an inventory (Astra 09:37: area inspect said "holds empty" for
  -- loaded belts): each lane as the game holds it; an underground's buried part (lines 3 and 4) said apart.
  local BELT_ROW={['transport-belt']=true,['underground-belt']=true,splitter=true,loader=true,['loader-1x1']=true,['linked-belt']=true}
  local LANE={'left lane','right lane','left lane underground','right lane underground'}
  local function lanes(e)
    local parts={}
    for i=1,e.get_max_transport_line_index() do
      local items={}
      for _,st in ipairs(e.get_transport_line(i).get_contents()) do
        local q=type(st.quality)=='table' and st.quality.name or st.quality
        items[#items+1]=st.name..(q and q~='normal' and '@'..q or '')..'*'..st.count
      end
      if #items>0 then parts[#parts+1]=(e.type=='splitter' and 'lane '..i or LANE[i] or 'lane '..i)..': '..table.concat(items,' ') end
    end
    return #parts>0 and table.concat(parts,'; ') or 'empty'
  end
  local function row(e)
    local r={name=e.name,position=e.position,quality=M.quality_name(e)}
    -- a combinator's description (d20 batch56 R4), a ghost's too
    local okdesc,desc=pcall(M.circuits.description,e)
    r.description=okdesc and desc or nil
    -- who placed it or its ghost (ghostlog.lua), when the record or the game knows
    local okpl,pl=pcall(M.ghostlog.short,e)
    r.placed=okpl and pl or nil
    -- direction, and an inserter's pickup and drop positions (A6)
    if e.type~='entity-ghost' then
      local okd,d=pcall(function() return e.supports_direction and e.direction end)
      if okd and type(d)=='number' then r.direction=M.direction_name(d) end
      if e.type=='inserter' then
        local okp,pp=pcall(function() return e.pickup_position end)
        local okq,dp=pcall(function() return e.drop_position end)
        if okp and pp then r.pickup=string.format('(%g,%g)',math.floor(pp.x*10+0.5)/10,math.floor(pp.y*10+0.5)/10) end
        if okq and dp then r.drop=string.format('(%g,%g)',math.floor(dp.x*10+0.5)/10,math.floor(dp.y*10+0.5)/10) end
      end
    end
    -- A ghost: what it is and which way it faces (d17 batch13 C1, Opus: a belt ghost read as entity-ghost alone).
    if e.type=='entity-ghost' then
      r.name=e.ghost_name; r.ghost=true
      local okd,d=pcall(function() return e.direction end)
      r.direction=okd and M.direction_name and M.direction_name(d) or (okd and d) or nil
      return r
    end
    if BELT_ROW[e.type] then
      local ok,h=pcall(lanes,e)
      r.holds=ok and h or nil
      return r
    end
    -- (d22 batch78 AN1, Astra #1809) items on the ground: the stack as hovering it shows
    if e.type=='item-entity' then
      r.stack=M.groundstack.stack(e); r.holds=M.groundstack.holds(r.stack)
      return r
    end
    -- (d20 batch70 AF4, Astra #1718: robots read "holds empty" here) a robot: its cargo, its unit number and where it flies
    if M.robotread.ROBOT[e.type] then
      local ok,rr=pcall(M.robotread.row,e)
      if ok then r.unit_number=rr.unit_number; r.holds=M.robotread.holds(e); r.cargo=rr.cargo; r.heading=rr.heading end
      return r
    end
    -- A chest, wagon, trunk, landing pad or hub: holds as inspect writes it (details.lua), and a requester's asks.
    local held={inventories={}}
    for _,name in ipairs(STORES) do
      local ok,inv=pcall(inventory,e,name)
      if ok then held.inventories[name]=contents(inv) end
    end
    pcall(M.details.holds,e,held)
    r.holds=held.holds; r.requests=held.requests
    if not r.holds then
      local parts={}
      for _,part in ipairs(PARTS) do
        local ok,inv=pcall(inventory,e,part[1])
        if ok and not inv.is_empty() then
          local items={}
          for _,st in ipairs(inv.get_contents()) do
            local q=type(st.quality)=='table' and st.quality.name or st.quality
            items[#items+1]=st.name..(q and q~='normal' and '@'..q or '')..'*'..st.count
          end
          parts[#parts+1]=part[2]..': '..table.concat(items,' ')
        end
      end
      r.holds=#parts>0 and table.concat(parts,'; ') or 'empty'
    end
    if e.type=='assembling-machine' or e.type=='furnace' then
      local ok,recipe=pcall(e.get_recipe)
      r.recipe=ok and recipe and recipe.name or nil
    end
    if not CHESTS[e.type] then r.status_name=entity_status_names[e.status] end
    local okk,kd=pcall(M.turrettally.read,e)
    if okk and kd then r.kills=kd.kills; r.damage_dealt=kd.damage_dealt end
    -- (d17 batch21 B1, Sonnet: pipes read empty in every area read) an entity with fluid boxes: each box's fluid and
    -- amount over its capacity, its segment's capacity and extent (pipes.fluids, as scan fields=fluids reads them)
    local okf,ft=pcall(function() local fb=e.fluidbox; return fb and #fb>0 and pipes.fluids(e,true) end)
    if okf and ft then r.fluid=ft; if r.holds=='empty' then r.holds=nil end end
    return r
  end
  -- compact (Muse, shift13: ~10 inspects over positions read as tables or JSON): one line per entity: name,
  -- position, status, health, recipe and what it holds, as the area rows read them; an inserter its hand; an entity
  -- with none of those inventories leaves holds out (the engine's get_max_inventory_index reads 8 for a belt too).
  local function has_inventory(e)
    for _,name in ipairs(STORES) do if pcall(inventory,e,name) then return true end end
    for _,part in ipairs(PARTS) do if pcall(inventory,e,part[1]) then return true end end
    return false
  end
  local function line(e)
    local r=row(e)
    local parts={}
    if r.status_name then parts[#parts+1]=r.status_name end
    local okh,h,mh=pcall(function() return e.health,e.max_health end)
    if okh and h and mh and mh>0 then parts[#parts+1]=string.format('health %d/%d',math.floor(h+0.5),math.floor(mh+0.5)) end
    if r.recipe then parts[#parts+1]='recipe '..r.recipe end
    if e.type=='inserter' then
      local okhs,hs=pcall(function() return e.held_stack end)
      parts[#parts+1]=okhs and hs and hs.valid_for_read and string.format('hand: %s*%d',hs.name,hs.count) or 'hand empty'
      local blocked=M.details.held_blocked(e)
      if blocked then parts[#parts+1]=blocked end
      local waits=M.details.pickup_wait(e)
      if waits then parts[#parts+1]='waits: '..waits end
    elseif BELT_ROW[e.type] and r.holds then
      parts[#parts+1]=r.holds=='empty' and 'lanes empty' or r.holds
    elseif M.robotread.ROBOT[e.type] and r.holds then  -- a robot (AF4)
      parts[#parts+1]=(r.holds=='empty' and 'carries nothing' or 'carries '..r.holds)..(r.heading and '; '..M.robotread.heading_text(r.heading) or '')..(r.unit_number and ' #'..r.unit_number or '')
    elseif r.holds and not (r.holds=='empty' and not has_inventory(e)) then
      local h=r.holds
      if h=='empty' then h='holds nothing' elseif CHESTS[e.type] and not h:find('^empty') then h='holds '..h end
      parts[#parts+1]=h
    end
    if r.requests and r.requests~='none' then parts[#parts+1]='requests '..r.requests end
    if r.fluid then parts[#parts+1]='fluid '..r.fluid end
    if r.direction then table.insert(parts,1,'facing '..r.direction) end
    if r.pickup then parts[#parts+1]='picks at '..r.pickup..', drops at '..tostring(r.drop) end
    if r.kills then parts[#parts+1]=M.turrettally.text(r) end
    if e.type~='entity-ghost' then
      -- (d17 batch20 B1, Luna: three Gleba breeders watched by paged dumps) what spoils in it: each spoilable item's
      -- count and count-weighted spoiled share, the first to spoil (or hatch) and when, and the hatch warning; its
      -- circuit and logistic conditions with the values now.
      local acc,seen={},{}
      local function add(name,where)
        if seen[name] then return end
        seen[name]=true
        local ok,inv=pcall(inventory,e,name)
        if ok then M.spoil.inventory(inv,acc,where) end
      end
      for _,name in ipairs(STORES) do add(name,'chest') end
      for _,part in ipairs(PARTS) do add(part[1],part[2]) end
      if BELT_ROW[e.type] then pcall(M.spoil.belt,e,acc,'belt')
      elseif e.type=='inserter' then pcall(M.spoil.add,acc,e.held_stack,'hand') end
      if #acc>0 then
        local items={}
        for i,x in ipairs(acc) do if i<=4 then items[i]=string.format('%s*%d %d%%',x.key,x.count,x.count>0 and math.floor(100*x.wsum/x.count+0.5) or 0) end end
        local first
        for _,x in ipairs(acc) do if not first or x.tick<first.tick then first=x end end
        parts[#parts+1]='spoil: '..table.concat(items,', ')..(#acc>4 and ', ...' or '')..' spoiled; first: '..(first.where and first.where..' ' or '')..M.spoil.row_text(first)
        local hatch=M.spoil.warning(acc)
        if hatch then parts[#parts+1]='hatch: '..hatch end
      end
      local okb,cb=pcall(function() return e.get_control_behavior() end)
      if okb and cb then
        local okc,cparts=pcall(function() return M.circuits.condition_parts(e,M.circuits.read(e,cb),cb) end)
        if okc and cparts and #cparts>0 then parts[#parts+1]='circuit: '..table.concat(cparts,', ') end
      end
      local okd,desc=pcall(M.circuits.description,e)
      if okd and desc then parts[#parts+1]='description: "'..desc:gsub('\n','\\n')..'"' end
    end
    if r.placed then parts[#parts+1]='placed: '..r.placed end
    local name=(r.quality and r.quality..' ' or '')..(e.type=='entity-ghost' and e.ghost_name or e.name)
    if e.type=='entity-ghost' then name='ghost of '..name end
    return string.format('%s (%g,%g)%s',name,e.position.x,e.position.y,#parts>0 and ': '..table.concat(parts,'; ') or '')
  end
  local function area_rows(p,a)
    assert(a.positions==nil and a.position==nil,'give area, positions or position: one of them')
    assert(type(a.area)=='table' and a.area.left_top and a.area.right_bottom,'area requires left_top and right_bottom')
    local lt,rb=position(a.area.left_top),position(a.area.right_bottom)
    assert(lt.x<rb.x and lt.y<rb.y and rb.x-lt.x<=MAX_SIDE and rb.y-lt.y<=MAX_SIDE,'area must be nonempty and at most '..MAX_SIDE..'x'..MAX_SIDE)
    local types=a.types
    -- name (one or a list) picks entities by name (C3, Gemini 22:50: names: [recycler] read every machine there); an
    -- entity name given in types counts as a name (4 refusals in Gemini's shift: fast-inserter, recycler, ...).
    local names
    if a.name~=nil then
      names=type(a.name)=='table' and a.name or {a.name}
      assert(#names>=1 and #names<=16,'name is an entity name or a list of 1..16')
      for _,n in ipairs(names) do assert(type(n)=='string' and prototypes.entity[n],'unknown entity name '..tostring(n)) end
    end
    local as_names
    if types~=nil then
      assert(type(types)=='table' and #types>=1 and #types<=16,'types requires 1..16 entity types')
      local kept={}
      for _,t in ipairs(types) do
        if type(t)=='string' and not M.known_type(t) and prototypes.entity[t] then
          names=names or {}; names[#names+1]=t; as_names=as_names or {}; as_names[#as_names+1]=t
        elseif type(t)~='string' or not M.known_type(t) then error(M.unknown_type(tostring(t)),0)
        else kept[#kept+1]=t end
      end
      types=#kept>0 and kept or nil
    end
    -- Every entity of ours there by default (d17 batch19 B1, Muse: chests and machines were listed and the belts and
    -- inserters only counted in an also line; finding a missing feeder took 20 minutes of walking): no type filter,
    -- characters left out, robots flying through counted in also; each row with its direction and an inserter's pickup
    -- and drop positions. all: true (d17 batch14 A6, Opus) is the same.
    assert(a.all==nil or type(a.all)=='boolean','all must be true or false')
    assert(not (a.all and (a.types~=nil or a.name~=nil)),'all lists every entity: no types or name')
    local found,unseen,present={},0,{}
    local strict=M.fogmem.strict()
    local every=not types and not names
    local ROBOTS={['logistic-robot']=true,['construction-robot']=true,['combat-robot']=true,['capture-robot']=true}
    local flying={}
    local filter={area={left_top=lt,right_bottom=rb},force=p.force,type=types}
    local named
    if names then
      -- names and types together: an entity of either
      local list={}
      for _,e in pairs(p.surface.find_entities_filtered{area=filter.area,force=p.force,name=names}) do list[#list+1]=e end
      if types then
        local seen={}
        for _,e in ipairs(list) do seen[e]=true end
        for _,e in pairs(p.surface.find_entities_filtered(filter)) do if not seen[e] then list[#list+1]=e end end
      end
      named=list
    end
    -- (d22 batch78 AN1, Astra #1809) items on the ground belong to no force: asked for by type or name, listed too
    local listed=named or p.surface.find_entities_filtered(filter)
    local ground_asked=false
    for _,t in ipairs(types or {}) do if t=='item-entity' then ground_asked=true end end
    for _,n in ipairs(names or {}) do if n=='item-on-ground' then ground_asked=true end end
    local ground={}
    if ground_asked then
      for _,e in pairs(p.surface.find_entities_filtered{area=filter.area,type='item-entity'}) do listed[#listed+1]=e end
    end
    -- (AN1) sight passes or fails by chunk (read_sight: a chunk our force sees): one check a chunk that passed
    local sighted={}
    for _,e in pairs(listed) do
      local at=e.valid and e.type~='character' and e.position
      if at and at.x>=lt.x and at.x<=rb.x and at.y>=lt.y and at.y<=rb.y then
        local ck=math.floor(at.x/32)*65536+math.floor(at.y/32)
        if not sighted[ck] and pcall(M.read_sight,p,at,'entity') then sighted[ck]=true end
        if not sighted[ck] then
          -- out of sight: counted in not_in_sight as before (fog_strict off), and named for fog's present
          unseen=unseen+1
          if e.type~='entity-ghost' and e.type~='tile-ghost' then present[e.name..'@'..at.x..','..at.y]=true end
        elseif every and ROBOTS[e.type] then flying[e.name]=(flying[e.name] or 0)+1
        else found[#found+1]=e; if e.type=='item-entity' then ground[#ground+1]=e end end
      end
    end
    local what_list={}
    for _,n in ipairs(names or {}) do what_list[#what_list+1]=n end
    for _,t in ipairs(types or {}) do what_list[#what_list+1]=t end
    local what=every and 'entity' or table.concat(what_list,', ',1,math.min(#what_list,6))..(#what_list>6 and ', ...' or '')
    -- Robots flying through (not listed; they are elsewhere a moment later)
    local also
    if next(flying) then
      local parts={}
      for n,c in pairs(flying) do parts[#parts+1]=c..' '..n end
      table.sort(parts)
      also='also passing through, not listed: '..table.concat(parts,', ')
    end
    -- The area's chunks out of sight (Nick d17 17:28, fogmem.lua): what our force last saw of its buildings and belts
    -- there (with when), the ghosts of ours there and our buildings lost there; never what stands there now.
    local okf,fog=pcall(M.fogmem.area,p.force,p.surface,{{lt.x,lt.y},{rb.x,rb.y}},MAX_ROWS,not strict and present or nil)
    fog=okf and fog or nil
    if fog and names then
      local want={}
      for _,n in ipairs(names) do want[n]=true end
      for _,k in ipairs({'remembered','ghosts','lost'}) do
        local kept={}
        for _,r in ipairs(fog[k]) do if want[r.name] then kept[#kept+1]=r end end
        fog[k]=kept
      end
    end
    if fog and #fog.remembered+#fog.ghosts+#fog.lost==0 then fog.empty=true end
    local function unseen_line()
      return unseen>0 and string.format('%d more in the area in chunks our force does not see now (radar coverage or a character\'s sight lights a chunk)',unseen) or nil
    end
    if #found==0 and (also or (fog and not fog.empty)) then
      return {entities={},count=0,by_name={},also=also,fog=fog,not_in_sight=strict and fog and fog.line or unseen_line(),
        note=string.format('no %s of ours with its centre there; %s%s%s',what,M.area_sight_text(p,lt,rb),also and '; '..also or '',
          fog and '; out of sight: fog (what our force last saw there, the ghosts and losses there)' or '')}
    end
    -- In sight and empty, or out of sight (all or part), said apart (d20 batch56 R3).
    assert(#found>0,string.format('no %s of ours with its centre in (%g,%g)-(%g,%g); %s%s',what,lt.x,lt.y,rb.x,rb.y,M.area_sight_text(p,lt,rb),
      not strict and (unseen>0 and string.format('; %d more there in chunks out of sight (not listed)',unseen) or '')
      or (fog and '; our force remembers nothing in its chunks out of sight, nor has a ghost or a loss there' or '')))
    -- One shape at any size (d17 batch13 A3, Muse: a list sometimes and a by-name summary at other times broke his
    -- scripts; batch10 C3 had switched to the summary alone past MAX_ROWS): entities, a page of MAX_ROWS in reading
    -- order (page, pages, next past one page), and by_name beside them, every name's count, states and where they lie.
    local by,order={},{}
    -- (d22 batch78 AN1: 2880 ground stacks took 177 ms) each position read once, for by_name and the sort below
    local at={}
    for _,e in ipairs(found) do
      local k=e.type=='entity-ghost' and 'ghost of '..e.ghost_name or e.name
      local pos=e.position
      at[e]=pos
      local r=by[k]
      if not r then r={name=k,type=e.type,count=0,states={},x0=pos.x,y0=pos.y,x1=pos.x,y1=pos.y}; by[k]=r; order[#order+1]=r end
      r.count=r.count+1
      local st=e.type~='item-entity' and M.machine_status and M.machine_status(e) or nil
      if st then r.states[st]=(r.states[st] or 0)+1 end
      r.x0,r.y0=math.min(r.x0,pos.x),math.min(r.y0,pos.y)
      r.x1,r.y1=math.max(r.x1,pos.x),math.max(r.y1,pos.y)
    end
    table.sort(order,function(x,y) if x.count~=y.count then return x.count>y.count end return x.name<y.name end)
    local by_name,name_lines={},{}
    for i,r in ipairs(order) do
      local st={}
      for k,n in pairs(r.states) do st[#st+1]={k=k,n=n} end
      table.sort(st,function(x,y) if x.n~=y.n then return x.n>y.n end return x.k<y.k end)
      local stt={}
      for j,x in ipairs(st) do stt[j]=x.n..' '..x.k end
      by_name[i]={name=r.name,type=r.type,count=r.count,states=#stt>0 and table.concat(stt,', ') or nil,
        area=string.format('(%g,%g)-(%g,%g)',r.x0,r.y0,r.x1,r.y1)}
      if i<=24 then name_lines[#name_lines+1]=string.format('%d %s (%s)%s in %s',r.count,r.name,r.type,#stt>0 and ': '..table.concat(stt,', ') or '',by_name[i].area) end
    end
    table.sort(found,function(x,y)
      local u,v=at[x],at[y]
      if u.y~=v.y then return u.y<v.y end
      return u.x<v.x
    end)
    local pages=math.max(1,math.ceil(#found/MAX_ROWS))
    local page=integer(a.page,1,1,pages,'page')
    local rows={}
    for i=(page-1)*MAX_ROWS+1,math.min(#found,page*MAX_ROWS) do rows[#rows+1]=a.compact and line(found[i]) or row(found[i]) end
    -- (d20 batch70 AF4) rows at one position told apart: each with its unit number
    local at_count={}
    local function key_of(e) return string.format('%g,%g',e.position.x,e.position.y) end
    for i=(page-1)*MAX_ROWS+1,math.min(#found,page*MAX_ROWS) do local k=key_of(found[i]); at_count[k]=(at_count[k] or 0)+1 end
    for j,r in ipairs(rows) do
      local e=found[(page-1)*MAX_ROWS+j]
      if e and e.unit_number and at_count[key_of(e)]>1 then
        if type(r)=='table' then r.unit_number=e.unit_number elseif not r:find('#'..e.unit_number,1,true) then rows[j]=r..' #'..e.unit_number end
      end
    end
    return {entities=not a.compact and rows or nil,lines=a.compact and rows or nil,count=#found,by_name=by_name,by_name_lines=name_lines,also=also,
      ground_items=#ground>0 and M.ground.summary(ground) or nil,
      page=pages>1 and page or nil,pages=pages>1 and pages or nil,
      next=page<pages and string.format('inspect {area: {left_top: {x: %g, y: %g}, right_bottom: {x: %g, y: %g}}, page: %d} (the same filters)',lt.x,lt.y,rb.x,rb.y,page+1) or nil,
      note=pages>1 and string.format('%d entities: page %d of %d lists %d of them in reading order; by_name counts all',#found,page,pages,#rows) or nil,
      as_names=as_names and 'entity names given in types, read as names: '..table.concat(as_names,', ') or nil,
      fog=fog,not_in_sight=strict and fog and fog.line or unseen_line()}
  end
  function handlers.inspect(p,a)
    assert(a.compact==nil or type(a.compact)=='boolean','compact must be true or false')
    -- position and radius (Gemini 14:49: area boxes went wrong), as observe takes them: the square round it.
    if a.radius~=nil and a.area==nil then
      assert(a.position~=nil and a.positions==nil,'radius goes with position: the square of our chests and machines round it, as area reads them')
      local r=integer(a.radius,nil,1,64,'radius')
      local c=position(a.position)
      local copy={}
      for k,v in pairs(a) do if k~='position' and k~='radius' then copy[k]=v end end
      copy.area={left_top={x=c.x-r,y=c.y-r},right_bottom={x=c.x+r,y=c.y+r}}
      local out=area_rows(p,copy)
      if type(out)=='table' then out.square=string.format('(%g,%g)-(%g,%g): radius %d round (%g,%g)',c.x-r,c.y-r,c.x+r,c.y+r,r,c.x,c.y) end
      return out
    end
    if a.area~=nil then return area_rows(p,a) end
    assert(a.types==nil,'types goes with area')
    -- compact: the entity as one line, found as inspect finds it (sight, or remote view).
    local function one(args)
      if not args.compact then return inspect_one(p,args) end
      if not M.memory_visible(p,position(args.position)) then
        local r=inspect_one(p,args)
        return string.format('%s (%g,%g): last seen tick %d (%gs ago); %s',r.name or 'entity',r.position.x,r.position.y,r.observed_tick,r.age_s,r.status_name or 'status not recorded')
      end
      local e=entity(p,args,true);M.readmemory.observe(e,p)
      return line(e)
    end
    if a.positions==nil then
      local ok,res=pcall(function()
        if a.compact then return {lines={one(a)},count=1} end
        return inspect_one(p,a)
      end)
      if ok then return res end
      -- (d17 batch14 A12, Gemini) nothing at a plain position: what stands within 3 tiles, every entity, said so
      if a.name==nil and a.unit_number==nil and a.position~=nil and tostring(res):find('entity not found at',1,true) then
        local c=position(a.position)
        local copy={all=true,compact=a.compact,area={left_top={x=c.x-3,y=c.y-3},right_bottom={x=c.x+3,y=c.y+3}}}
        local okn,near=pcall(area_rows,p,copy)
        if okn and type(near)=='table' and (near.count or 0)>0 then
          near.not_at=string.format('nothing stands at (%g,%g): every entity within 3 tiles of it ((%g,%g)-(%g,%g)) instead',c.x,c.y,c.x-3,c.y-3,c.x+3,c.y+3)
          return near
        end
      end
      error(res,0)
    end
    -- (d19 batch45 2: 32 positions read 26-31 ms on the private copy, about 0.9 ms a full read and 0.65 a compact one)
    -- (d20 batch59 U3, Astra #1502: positions took 32 and read 8, the rest listed) one limit, said in every reply:
    -- INSPECT_POSITIONS a call, compact or not.
    local cap=M.INSPECT_POSITIONS
    assert(type(a.positions)=='table' and #a.positions>=1 and #a.positions<=cap,
      string.format('positions takes 1..%d positions a call (each is a full inspect, about 0.9 ms on the private copy); this call gave %s',cap,type(a.positions)=='table' and #a.positions or 'none'))
    assert(a.position==nil,'give position or positions, not both')
    local out={}
    for i,pos in ipairs(a.positions) do
      local args={}
      for k,v in pairs(a) do if k~='positions' then args[k]=v end end
      args.position=pos
      if type(pos)=='table' then args.name=pos.name or a.name; args.unit_number=pos.unit_number or a.unit_number end
      local ok,r=pcall(one,args)
      if a.compact then
        local okp,at=pcall(position,pos)
        out[i]=ok and r or string.format('(%s): %s',okp and string.format('%g,%g',at.x,at.y) or tostring(pos),reason(r))
      else out[i]=ok and r or {position=pos,error=reason(r)} end
    end
    if a.compact then return {lines=out,count=#out,positions_limit=cap} end
    return {entities=out,count=#out,positions_limit=cap}
  end
end
-- Rotate as the R key does: one 90-degree turn clockwise per call (reverse=true counter-clockwise), or with direction,
-- turns until it faces that way. The reply names the facing before and after (Grok 01:51, "rotate turns a belt 180
-- degrees": its belts got two calls each, north to east to south, while the reply showed no facing).
function handlers.rotate(p,a)
  -- Seen out of reach (autowalk.lua; Opus, shift14: belts 10.5 to 24 tiles off refused one by one): within 32 tiles
  -- the character walks into reach first, then rotates it.
  local target
  if a.direction~=nil then
    target=type(a.direction)=='number' and a.direction or directions[a.direction]
    assert(type(target)=='number' and target%1==0 and target>=0 and target<16,'direction must be a compass name (north, east, south, west) or 0..15')
    assert(a.reverse==nil,'give direction or reverse, not both')
  end
  -- By remote view (Astra, Sol: platform corners re-ghosted by hand ~6 times): with platform= or surface= (or aboard a
  -- platform) the ghost or built belt, inserter and the like is turned where the map shows it, as remote view's R does.
  local remote=M.configure_remote(p,a)
  local e
  if remote then
    e=remote_entity(p,a); friendly(p,e)
  else
    -- (d17 batch21 D3, Muse: a backwards inserter 700 tiles off took a deconstruct and a new build) past the 32 tiles a
    -- call walks, without walk: true: by remote view in a chunk our force sees now, as a player rotates in the map;
    -- within them it walks into reach (or the reach refusal names a spot), as before
    if a.walk~=true and a.position~=nil and distance(p.position,position(a.position))>32 then
      e=remote_entity(p,a); remote=true
    else
      local walking=M.walk_first(p,'rotate',a)
      if walking then return walking end
      e=entity(p,a)
    end
    friendly(p,e)
  end
  -- (AG2) rolling stock: flipped 180 degrees as R does (rollingstock.lua); with direction, when it faces away from there
  if e.valid and M.rollingstock.TYPES[e.type] then return M.rollingstock.rotate(e,target,real(p)) end
  local names={}
  for n,d in pairs(directions) do names[d]=n end
  local function name(d) return d and (names[d] or tostring(d)) or nil end
  local before=e.direction
  local turns=0
  -- (d20 batch54 N8) the directions its prototype is built in; a ghost the game's rotate does not turn (a railgun
  -- turret's) is replaced by one facing the target; a built one the game does not turn is said so
  local ghost=e.type=='entity-ghost'
  local proto=ghost and e.ghost_prototype or e.prototype
  local kind=ghost and e.ghost_name or e.name
  if target~=nil then
    assert(not (proto and proto.supports_direction==false) or before==target,string.format('%s at (%g,%g) has no direction: the game builds it facing north whatever is asked, and does not turn it',kind,e.position.x,e.position.y))
    M.check_direction(proto,target)
  end
  local replaced
  if target==nil then
    if e.rotate{reverse=a.reverse==true,by_player=real(p)} then turns=1 end
  elseif before~=target then
    -- The shorter way round: clockwise up to 180 degrees, else counter-clockwise.
    local back=(target-before)%16>8
    for _=1,8 do
      if not e.rotate{reverse=back,by_player=real(p)} then break end
      turns=turns+1
      if e.direction==target then break end
    end
    if e.direction~=target and turns==0 and ghost then
      e=M.reghost(e,target)
      replaced=string.format('the game does not turn a %s ghost (its rotate, as R, refuses it): replaced by a ghost facing %s, as removing it and placing a new one does',kind,name(target))
    end
    assert(e.direction==target,turns==0 and string.format('%s at (%g,%g) faces %s: the game does not turn a placed %s (its rotate, as R, refuses it); it faces another way only as built (build or place_ghosts with direction %s)',
      kind,e.position.x,e.position.y,name(e.direction),kind,name(target))
      or string.format('%s at (%g,%g) faces %s after %d turn%s from %s; rotating does not bring it to %s',
      kind,e.position.x,e.position.y,name(e.direction),turns,turns==1 and '' or 's',name(before),name(target)))
  end
  -- Rotating an underground flips its end (and its partner's): show the result.
  -- As after a build: a turned inserter's engine targets come a tick later.
  return {rotated=turns>0 or replaced~=nil,before=name(before),after=name(e.direction),turns=turns,by=remote and 'remote view' or nil,replaced=replaced,
    note=target~=nil and turns==0 and not replaced and 'it faces '..name(target)..' already' or nil,entity=built_summary(e)}
end
-- Changing a recipe works as it does for a player: machine contents and the
-- ingredients of an interrupted craft go to the inventory, spilling at the
-- character's feet when it is full. Fluids are lost, so that needs force.
-- Item filters, as a player sets them in an inserter's (or loader's) GUI.
local function configure_filters(e,a)
  assert(a.recipe==nil,'give recipe or filters, not both')
  -- An entity ghost takes the settings its entity would (Astra 12:20: a 75-entity Starling layout).
  local etype=e.type=='entity-ghost' and e.ghost_type or e.type
  -- A collector's slot count reads 0 before its first filter (details.lua).
  if etype=='asteroid-collector' then
    assert(type(a.filters)=='table','filters requires asteroid chunk names ([] clears)')
    return M.details.configure_collector(e,a)
  end
  local slots=e.filter_slot_count or 0
  assert(slots>0,e.name..' has no filter slots')
  -- One name is a list of one; filter_mode or use_filters alone keep the items (Sonnet 06:20: stale filters).
  local list=type(a.filters)=='string' and {a.filters} or a.filters
  assert(list==nil or (type(list)=='table' and #list<=slots),'filters requires 0..'..slots..' item names')
  for _,name in ipairs(list or {}) do assert(prototypes.item[name],'unknown item '..tostring(name)) end
  local inserter=etype=='inserter'
  assert(a.use_filters==nil or (inserter and type(a.use_filters)=='boolean'),'use_filters is true or false, on an inserter')
  local before=M.details.filters_line(e) or 'none'
  if a.filter_mode~=nil then
    assert(a.filter_mode=='whitelist' or a.filter_mode=='blacklist','filter_mode is whitelist or blacklist')
    assert(inserter,'filter_mode applies to inserters')
    e.inserter_filter_mode=a.filter_mode
  end
  if list then
    for i=1,slots do e.set_filter(i,list[i]) end
    if inserter then e.use_filters=#list>0 end
  end
  if a.use_filters~=nil then e.use_filters=a.use_filters end
  local now=M.details.filters(e) or {filters={}}
  return {filters=now.filters,filter_mode=now.filter_mode,use_filters=now.use_filters,line=M.details.filters_line(e) or 'none',before=before,
    ghost=e.type=='entity-ghost' and e.ghost_name or nil}
end
M.configure_filters=configure_filters
-- Out of reach, 2.0's remote view still opens the machine: recipes and
-- filters change the same way, but contents cannot come back to the
-- character, so a remote recipe change needs an empty, idle machine.
do local function holds_items(e)
  if e.type=='entity-ghost' then return false end
  -- Modules stay through a recipe change unless the new recipe forbids one (M.modules_out; Astra, shift17 10:50).
  for _,name in ipairs({'assembling_machine_input','assembling_machine_output'}) do
    local ok,inv=pcall(inventory,e,name)
    if ok and not inv.is_empty() then return name..' holds items' end
  end
  if (e.crafting_progress or 0)>0 then return 'crafting progress is '..tostring(e.crafting_progress) end
end
do
-- configure's target (in reach, else by remote view) and the checks that
-- refuse a recipe change, before anything changes: the dispatch runs them
-- first too, so a refused configure stops nothing (Astra 11:01, twice: a
-- configure with surface=nauvis, her own surface, failed and paused her queue).
function M.configure_remote(p,a)
  if a.platform~=nil or (a.surface~=nil and a.surface~=p.surface.name) or (type(p)=='table' and (rawget(p,'__platform') or rawget(p,'__remote'))) then return true end
  local ok,c=pcall(function() return p.character end)
  return not ok or not (c and c.valid and c.surface==p.surface)
end
local function configure_target(p,a)
  if M.configure_remote(p,a) then
    local e=remote_entity(p,a)
    friendly(p,e)
    return false,e
  end
  local near,e=pcall(entity,p,a)
  if not near then
    local ok,far=pcall(remote_entity,p,a)
    -- On another surface (surface=) the remote view's reason is the one that applies.
    if not ok then error(type(p)=='table' and rawget(p,'__remote') and far or e,0) end
    e=far
  end
  friendly(p,e)
  return near,e
end
-- A turret's priority targets and Ignore unprioritised targets, as its 2.0 GUI sets them (Astra, shift12 15:02: Sunward's
-- rocket turrets on big metallic, carbonic and oxide asteroids only). On 2.0.77 (a copy of world n): gun, rocket,
-- railgun, laser, tesla and flamethrower turrets and their ghosts take them, artillery does not ("Entity is not
-- turret"); the engine takes any entity name; a cleared slot leaves a gap get_priority_target reads as nil while
-- priority_targets skips it, so a list is written whole from slot 1. Blueprints carry both (priority-list,
-- ignore-unprioritised), the ghosts a blueprint places keep them, and so does the turret a ghost becomes.
M.TARGETING={['ammo-turret']=true,['electric-turret']=true,['fluid-turret']=true}
-- What a turret or its ghost is set to: {list, ignore, line}, or nil for anything else.
function M.turret_targets(e)
  local t=e.type=='entity-ghost' and e.ghost_type or e.type
  if not M.TARGETING[t] then return nil end
  local list={}
  for _,proto in pairs(e.priority_targets) do list[#list+1]=proto.name end
  local ignore=e.ignore_unprioritised_targets==true
  return {list=list,ignore=ignore,line=string.format('priority targets: %s; ignore unprioritised targets: %s',
    #list>0 and table.concat(list,', ')..' (in this order)' or 'none',ignore and 'on' or 'off')}
end
-- An unknown name: entity names of enemies and asteroids that hold every word of it.
function M.unknown_target(nm)
  local words={}
  for w in tostring(nm):gmatch('[^-]+') do words[#words+1]=w end
  local hits={}
  for _,t in ipairs{'asteroid','unit','unit-spawner','turret','segmented-unit','spider-unit'} do
    local ok,list=pcall(function() return prototypes.get_entity_filtered{{filter='type',type=t}} end)
    for name in pairs(ok and list or {}) do
      local all=#words>0
      for _,w in ipairs(words) do if not name:find(w,1,true) then all=false; break end end
      if all then hits[#hits+1]=name end
    end
  end
  table.sort(hits)
  local more=#hits>8 and #hits-8 or 0
  for i=#hits,9,-1 do hits[i]=nil end
  return string.format('unknown entity %s in priority_targets%s',tostring(nm),
    #hits>0 and ('; names like it: '..table.concat(hits,', ')..(more>0 and string.format(' (+%d more)',more) or '')) or '')
end
-- priority_targets: entity names in priority order (asteroids, biters, worms, ...), at most 64; [] or false clears.
function M.target_names(v)
  if v==false then return {} end
  if type(v)=='string' then v={v} end
  if type(v)~='table' then error('priority_targets is a list of entity names in priority order ([] or false clears it)',0) end
  if #v>64 then error('priority_targets takes at most 64 names',0) end
  local out,seen={},{}
  for _,nm in ipairs(v) do
    if type(nm)~='string' or not prototypes.entity[nm] then error(M.unknown_target(nm),0) end
    if not seen[nm] then seen[nm]=true; out[#out+1]=nm end
  end
  return out
end
-- Sets one turret or its ghost and reads it back.
function M.configure_turret(e,a)
  local t=e.type=='entity-ghost' and e.ghost_type or e.type
  local name=e.type=='entity-ghost' and e.ghost_name or e.name
  if not M.TARGETING[t] then
    error(string.format('%s (type %s) has no priority targets: gun, rocket, railgun, laser, tesla and flamethrower turrets and their ghosts do (artillery does not; it has auto_targeting)',
      name,tostring(t)),0)
  end
  if a.ignore_unprioritised~=nil and type(a.ignore_unprioritised)~='boolean' then error('ignore_unprioritised must be true or false',0) end
  local list=a.priority_targets~=nil and M.target_names(a.priority_targets) or nil
  if list then
    -- Every slot from the last down (a gap reads nil, past the end raises), then the list from slot 1.
    local n=0
    while n<1000 and pcall(e.get_priority_target,n+1) do n=n+1 end
    for i=n,1,-1 do e.set_priority_target(i,nil) end
    for i,nm in ipairs(list) do e.set_priority_target(i,nm) end
  end
  if a.ignore_unprioritised~=nil then e.ignore_unprioritised_targets=a.ignore_unprioritised end
  -- a ghost's targeting is checked again once it is built (turretwatch.lua; backlog #569)
  if e.type=='entity-ghost' and M.turretwatch then pcall(M.turretwatch.watch,e,M.caller_index) end
  local now=M.turret_targets(e)
  -- (d17 batch31 B3, Astra) a railgun: the entities of ours its shots would cross (fireline.lua)
  local okf,fire=pcall(function() return M.fireline and M.fireline.of(e) end)
  return {name=name,position=e.position,ghost=e.type=='entity-ghost' or nil,priority_targets=now.list,ignore_unprioritised=now.ignore,targeting=now.line,
    line_of_fire=okf and fire and fire.line or nil}
end
local function configure_check(p,a,e,near)
  if e.type=='rocket-silo' or (e.type=='entity-ghost' and e.ghost_type=='rocket-silo') or a.filters~=nil or (a.recipe==nil and (a.filter_mode~=nil or a.use_filters~=nil)) then return end
  -- Modules alone are checked by modules.lua (M.configure_modules), slot by slot.
  if a.modules~=nil and a.recipe==nil then return end
  -- A turret's targeting is checked by M.configure_turret, which changes nothing before its checks pass.
  if a.priority_targets~=nil or a.ignore_unprioritised~=nil or a.auto_targeting~=nil then return end
  -- A storage chest's filter and a splitter's settings are checked by details.lua.
  if a.recipe==nil and (a.storage_filter~=nil or a.input_priority~=nil or a.output_priority~=nil or a.filter~=nil) then return end
  -- An inserter's spoil priority is checked by handlers.configure (inserters only).
  if a.spoil_priority~=nil and a.recipe==nil then return end
  if a.hand_size~=nil and a.recipe==nil then return end
  if a.wait_for_full_hand~=nil and a.recipe==nil then return end
  -- An inventory's bar is set or refused by invbar.lua.
  if a.bar~=nil and a.recipe==nil then return end
  -- An assembling machine's ghost takes a recipe as the machine would (it holds no items or fluid yet).
  local ghost=e.type=='entity-ghost'
  assert((ghost and e.ghost_type or e.type)=='assembling-machine','only assembling machines (and their ghosts) support recipe configuration')
  local recipe=type(a.recipe)=='string' and p.force.recipes[a.recipe]
  assert(recipe and recipe.enabled,'recipe is unavailable')
  assert((ghost and e.ghost_prototype or e.prototype).crafting_categories[recipe.category],'recipe incompatible with machine')
  if ghost then return end
  local current,current_quality=e.get_recipe()
  if current and current.name==recipe.name and (a.quality or 'normal')==((current_quality and current_quality.name) or 'normal') then return end
  -- (d21 batch64 Z1, Sol #1515) with Set recipe on the game ignores a recipe set by hand: say so, and what it takes
  if M.circrecipe.set_recipe_on(e) then error(M.circrecipe.refusal(e,recipe.name,a.quality),0) end
  -- (fluids the new recipe takes none of: handlers.configure, batch26 A3; force=true is fluid "keep")
  -- Out of reach, it needs the character there: the refusal's text, for the caller to walk (M.configure_walk) or raise.
  -- On a platform the old ingredients and products go to the hub instead (Astra, d15 twice: a deconstruct and rebuild
  -- to change a recipe left a gap in which an unfiltered feeder grabbed magazines), when it has room for them all.
  local held=not near and holds_items(e)
  if held and M.recipe_to_hub(e) then held=nil end
  if held then
    local why=M.recipe_hub_why(e)
    if why then held=held..'; '..why end
    return string.format('remote recipe change refused: %s at (%g,%g) on %s: %s; a recipe change can return these items and requires a character in reach on that surface',
      e.name,e.position.x,e.position.y,e.surface.name,held)
  end
  -- Modules the new recipe takes out come back to a character: named, with the slot change that empties them.
  local out=not near and M.modules_out(e,recipe.name) or {}
  if #out>0 then
    local parts,slots={},{}
    for _,m in ipairs(out) do parts[#parts+1]=string.format('%s in module slot %d (%s with %s)',m.name,m.slot,m.why,recipe.name); slots[tostring(m.slot)]='empty' end
    local keys={}
    for k in pairs(slots) do keys[#keys+1]=string.format('"%s":"empty"',k) end
    table.sort(keys)
    return string.format('remote recipe change refused: %s at (%g,%g) on %s: %s; they would come out, which takes a character in reach on that surface; modules the recipe allows stay and need nothing: empty those slots first (configure modules {%s}), or change the recipe in reach',
      e.name,e.position.x,e.position.y,e.surface.name,table.concat(parts,', '),table.concat(keys,','))
  end
end
-- (d20 batch53 L2, Astra #1275) a place_ghosts dry run's settings check it from outside this block (settings_dry)
M.configure_check=configure_check
-- A platform machine's stacks (input and output) and the hub that takes them on a remote recipe change: the hub when
-- its empty slots hold every stack, else nil.
function M.recipe_to_hub(e)
  local pl=e.surface and e.surface.platform
  local hub=pl and pl.hub
  if not (hub and hub.valid) then return nil end
  local okh,inv=pcall(function() return hub.get_inventory(defines.inventory.hub_main) end)
  if not (okh and inv) then return nil end
  local stacks=0
  for _,name in ipairs({'assembling_machine_input','assembling_machine_output'}) do
    local ok,mi=pcall(inventory,e,name)
    for i=1,ok and #mi or 0 do if mi[i].valid_for_read then stacks=stacks+1 end end
  end
  -- What is mid-craft comes back too: one more stack per ingredient.
  local okr,r=pcall(function() return e.get_recipe() end)
  if okr and r and (e.crafting_progress or 0)>0 then for _,ing in ipairs(r.ingredients or {}) do if ing.type~='fluid' then stacks=stacks+1 end end end
  if inv.count_empty_stacks(true,false)<stacks then return nil end
  return inv,stacks
end
function M.recipe_hub_why(e)
  local pl=e.surface and e.surface.platform
  local hub=pl and pl.hub
  if not (hub and hub.valid) then return nil end
  local okh,inv=pcall(function() return hub.get_inventory(defines.inventory.hub_main) end)
  return okh and inv and string.format('the hub has %d empty slots under its bar, too few for the machine\'s stacks',inv.count_empty_stacks(true,false)) or nil
end
-- The modules a recipe change takes out, as the game does (checked on a private 2.0.77 server, d15: a crusher's two
-- efficiency modules stay through metallic -> oxide crushing; productivity modules come out for wooden-chest, which
-- forbids productivity; a quality module for a barrel recipe, which forbids quality; a speed module's negative quality
-- and an efficiency module's negative consumption keep them in): a module whose positive effect the recipe forbids, or
-- whose category the recipe does not allow. Astra, shift17 10:50: remote configure refused an empty idle crusher only
-- because it held compatible efficiency modules. -> {slot, name, why}.
function M.modules_out(e,recipe_name)
  local rp=prototypes.recipe and prototypes.recipe[recipe_name]
  if not rp then return {} end
  local inv=e.type~='entity-ghost' and e.get_module_inventory and e.get_module_inventory()
  local out={}
  for i=1,(inv and #inv or 0) do
    local st=inv[i]
    if st.valid_for_read then
      local it=prototypes.item[st.name] or {}
      local why
      local cats=rp.allowed_module_categories
      if cats and it.category and not cats[it.category] then why='its category '..it.category..' is not allowed' end
      for k,v in pairs(it.module_effects or {}) do
        if not why and v>0 and rp.allowed_effects and rp.allowed_effects[k]==false then why=k..' is not allowed' end
      end
      if why then out[#out+1]={slot=i,name=st.name,why=why} end
    end
  end
  return out
end
-- configure out of reach that needs the character there (autowalk.lua): a recipe change on a machine holding items
-- or mid-craft, or modules by hand; need: the refusal it gets. Within 32 tiles it walks there first: the far record
-- (past 32 tiles without walk: true, refused); nil when it does not walk (walk: false, made again after its walk,
-- positions, another surface or a platform).
function M.configure_walk(p,a,e,need)
  if a.walk==false or a.walked or a.positions~=nil or M.configure_remote(p,a) then return nil end
  local f=M.autowalk.entity_far(p,e)
  f.text=need
  return M.autowalk.wanted('configure',a,{f}) and f or nil
end
-- The refusal a configure out of reach gets, when it needs the character there; nil when remote view does it.
function M.configure_need(p,a,e,near)
  if near then return nil end
  if a.modules~=nil and a.by=='hand' then
    if M.configure_remote(p,a) then return 'modules by hand require a character in reach on '..e.surface.name..'; this configure uses remote view' end
    return M.out_of_reach(p,e)
  end
  return configure_check(p,a,e,near)
end
-- Whether this configure walks into reach first: dispatch then runs it as character work, not remote view (M.remote).
function M.configure_walks(p,a)
  local ok,f=pcall(function()
    if a.positions~=nil or a.walk==false or a.walked or M.away(a) then return nil end
    local near,e=configure_target(p,a)
    local need=M.configure_need(p,a,e,near)
    return need and M.configure_walk(p,a,e,need)
  end)
  return ok and f and true or false
end
-- Walk into reach for it: the reply's walking line says why.
function M.configure_approach(p,a,e,f)
  local why=a.modules~=nil and a.by=='hand' and 'modules by hand need you in reach' or 'the machine holds items or is mid-craft, which come back to you only in reach'
  return M.autowalk.approach(p,'configure',a,{entity=e},why..': '..M.autowalk.line({f},1,f))
end
M.preflight=M.preflight or {}
-- A queued step's arguments checked at submit and in dry_run as the live call reads them, with no world (Sol, shift17
-- 19:06: a modules map passed the dry run and failed live in 8 steps; a transfer with no direction failed 3 times).
M.step_checks={
  configure=function(a)
    if a.modules~=nil then M.modules.parse(a.modules) end
    assert(a.by==nil or a.by=='hand' or a.by=='robots','by is hand (in reach, from your inventory) or robots (an item request)')
    if type(a.recipe)=='string' and a.recipe~='' and prototypes.recipe then assert(prototypes.recipe[a.recipe],'unknown recipe: '..a.recipe) end
  end,
  transfer=function(a)
    assert(a.direction==nil or a.direction=='to_entity' or a.direction=='to_player','direction must be to_entity or to_player')
    if type(a.item)=='string' and prototypes.item then assert(prototypes.item[a.item],'unknown item '..a.item) end
    if a.items~=nil then assert(a.direction~=nil,'items requires direction to_entity or to_player') end
    -- A direct call infers it from who holds the item at the call; a queued step runs later.
    if a.direction==nil and a.item~=nil and a.pick==nil and a.from==nil and a.items==nil and a.to==nil then
      error('a queued transfer of an item needs direction: to_entity (from your inventory into the target) or to_player '..
        '(from the target into your inventory). A direct call infers it from who holds the item at the call; a queued '..
        'step runs later, and fails when both sides hold it or neither does',0)
    end
  end,
}
-- (d25 batch200 QM2, Astra #2313: a queued platform_defense {asteroids, seconds: 3600} passed queue_submit's dry_run and
-- the job refused it, 10..1800) The numeric ranges each queueable action checks when it runs, checked for every queue
-- step at submit and in dry_run: {key, low, high, whole?=true, when?} (when: the arguments the range applies with; the
-- watches' ranges are their modules' own constants). A value of another type is left to the action (true, text forms).
-- Where an action takes a key in several modes with different ranges, the widest is listed: a value no mode takes.
-- On a copy of world n (d25) dry_run took an out-of-range value for every one of these, and each direct call refused it.
local function watch_range(mod) return function() local m=M[mod]; return m.SECONDS[1],m.SECONDS[2] end end
local function starts(mod) return function(a) return M[mod].starts(a) end end
local function retrying(a) return a.retry_when_clear==true end
M.step_ranges={
  platform_defense={{'seconds',watch_range('asteroidwatch'),when=function(a) return a.asteroids==true end},
    {'trajectory_limit',1,100,when=function(a) return a.asteroids==true end}},
  platform_supply={{'seconds',watch_range('collectreach'),when=function(a) return a.collection==true end}},
  uptime={{'seconds',watch_range('uptime'),when=starts('uptime')}},
  turret_tally={{'seconds',watch_range('turrettally'),when=starts('turrettally')}},
  belt_flow={{'seconds',watch_range('beltsample'),when=function(a) return a.position~=nil end}},
  signal_watch={{'seconds',function() return M.signalwatch.MIN_S,M.signalwatch.MAX_S end,when=function(a) return a.position~=nil or a.seconds~=nil end}},
  feed={{'count',1,1000},{'fuel_count',1,1000},{'crafts',1,1000},{'radius',1,256},{'ticks',1,36000}},
  refuel={{'count',1,1000},{'radius',1,256},{'ticks',1,36000}},
  rearm={{'count',1,1000},{'below',1,1000},{'radius',1,256},{'ticks',1,36000},{'retries',0,6},{'retry_ticks',600,54000,when=retrying}},
  transfer={{'count',1,1000000},{'keep',0,100000},{'up_to',1,100000},{'total',1,100000},{'max_fresh',0,100},{'min_spoil',0,100},{'min_spoiled',0,100},
    {'radius',1,256},{'ticks',1,36000},{'retries',0,6},{'retry_ticks',600,54000,when=retrying}},
  collect={{'ticks',1,72000},{'wait_ticks',1,36000},{'keep_taking',1,36000},{'count',1,10000},{'want',1,100000},
    {'min_fresh',0,100},{'radius',1,256}},
  move_to={{'ticks',1,36000},{'combat',1,32},{'max_uncovered',0,256},{'tolerance',0.25,10,whole=false},{'reach',0.5,64,whole=false}},
  mine={{'count',1,2000},{'ticks',1,36000},{'radius',1,32}},
  load_silo={{'rockets',2,20},{'wait_min',1,60},{'ticks',1,36000}},
  launch={{'timeout',1,54000}},
  build={{'retries',0,6},{'retry_ticks',600,54000,when=retrying},{'size',1,4},{'orientation',0,1,whole=false}},
  shoot={{'ticks',1,600},{'radius',1,36},{'gun_slot',1,3}},
  kite={{'radius',8,32},{'ticks',1,36000}},
  recover={{'stop_after',1,5},{'ticks',1,36000},{'group_radius',8,160}},
  pickup={{'ticks',1,36000},{'radius',1,32},{'count',1,10000},{'min_spoiled',0,100}},
  train_stop={{'limit',0,1000}},
  train={{'limit',0,1000},{'wagon_slots',0,40}},
  cancel_craft={{'index',1,10000}},
  walk={{'ticks',1,600}},repair={{'ticks',1,36000}},
  drops={{'limit',1,20}},eggs={{'limit',1,256}},ghosts={{'radius',1,256},{'limit',1,64}},labs={{'radius',1,256}},
  losses={{'since',1,100800}},nearest_water={{'radius',1,256}},ores={{'limit',1,100}},platform_plan={{'salvage',1,2000}},
  platform_rearm={{'ammo_below',1,10000}},players={{'minutes',1,240}},robot_losses={{'minutes',1,900}},
  research_done={{'limit',1,50}},sight={{'radius',16,240}},tells={{'limit',1,100}},turret_feeds={{'count',1,1000}},
  cargo={{'limit',1,32}},
}
function M.step_range_check(action,a)
  for _,r in ipairs(M.step_ranges[action] or {}) do
    local v=a[r[1]]
    if type(v)=='number' and (not r.when or r.when(a)) then
      local lo,hi=r[2],r[3]
      if type(lo)=='function' then lo,hi=lo() end
      local whole=r.whole~=false
      if v<lo or v>hi or (whole and v~=math.floor(v)) then
        error(string.format('%s %s is outside %s..%s%s, what %s takes when it runs',r[1],tostring(v),tostring(lo),tostring(hi),whole and ' (a whole number)' or '',action),0)
      end
    end
  end
end
M.preflight.configure=function(p,a)
  if a.modules~=nil then M.modules.parse(a.modules) end
  if a.positions~=nil then return end
  local near,e=configure_target(p,a)
  local need=configure_check(p,a,e,near)
  if need and not M.configure_walk(p,a,e,need) then error(need,0) end
end
-- Modules (modules.lua): one machine, or 1..64 set alike (positions); in reach by hand, else as item requests; with
-- recipe, the recipe changes first.
function M.configure_modules(p,a)
  local want=M.modules.parse(a.modules)
  assert(a.by==nil or a.by=='hand' or a.by=='robots','by is hand (in reach, from your inventory) or robots (an item request)')
  assert(a.priority_targets==nil and a.ignore_unprioritised==nil and a.filters==nil,'modules goes with position or positions, recipe and by')
  -- One machine out of reach that needs you there (by hand, or a recipe change on one holding items; autowalk.lua):
  -- within 32 tiles the character walks into reach first, and the whole call is made there.
  if a.positions==nil then
    local near,e=configure_target(p,a)
    local need=M.configure_need(p,a,e,near)
    local f=need and M.configure_walk(p,a,e,need)
    if f then return M.configure_approach(p,a,e,f) end
    if need and M.configure_remote(p,a) then error(need,0) end
  end
  local function one(args)
    local out
    if args.by=='hand' and M.configure_remote(p,args) then
      local _,e=configure_target(p,args)
      error('modules by hand require a character in reach on '..e.surface.name..'; this configure uses remote view',0)
    end
    if args.recipe~=nil then
      local r={}
      for k,v in pairs(args) do if k~='modules' and k~='by' then r[k]=v end end
      out=handlers.configure(p,r)
    end
    local near,e=configure_target(p,args)
    local row=M.modules.set(p,e,want,near,args.by)
    row.remote=not near or nil
    if out then out.modules=row; return out end
    return row
  end
  if a.positions==nil then return one(a) end
  assert(type(a.positions)=='table' and #a.positions>=1 and #a.positions<=64,'positions requires 1..64 {x,y} (machines or their ghosts)')
  assert(a.position==nil,'give position or positions, not both')
  local rows,done,failed={},0,0
  for i,pos in ipairs(a.positions) do
    local args={}
    for k,v in pairs(a) do if k~='positions' then args[k]=v end end
    args.position=pos
    if type(pos)=='table' then args.name=pos.name or args.name; args.unit_number=pos.unit_number or args.unit_number end
    local ok,out=pcall(one,args)
    if ok then done=done+1; rows[i]=out else failed=failed+1; rows[i]={position=pos,error=reason(out)} end
  end
  return {configured=done,failed=failed>0 and failed or nil,machines=rows}
end
-- Several turrets in one call (positions): each set as one would be; a row per turret, one that fails with its error.
-- (d19 batch41 A2, Sol seq 868-869: 11 turrets rebuilt to clear ammunition requests they could not use) configure
-- {position | positions, item_requests: false} (ammo: false on a built turret is the same): each built entity's item
-- requests removed, as a deconstruction planner over it and a cancel do (turretammo.lua's clear).
function M.clear_requests(p,a,near,e)
  assert(a.item_requests==nil or a.item_requests==false,'item_requests: false removes a built entity\'s item requests')
  local list=a.positions or {a.position}
  assert(type(list)=='table' and #list>=1 and #list<=64,'positions requires 1..64 {x,y}')
  local rows,cleared,none,failed={},0,0,0
  for i,pos in ipairs(list) do
    local ok,out=pcall(function()
      local n,x=near,e
      if not x or a.positions then
        local args={}
        for k,v in pairs(a) do if k~='positions' then args[k]=v end end
        args.position=pos
        if type(pos)=='table' then args.name=pos.name or args.name; args.unit_number=pos.unit_number or args.unit_number end
        n,x=configure_target(p,args)
      end
      local what=x.type=='entity-ghost' and x.ghost_name or x.name
      assert(x.type~='entity-ghost' and x.type~='tile-ghost',string.format('%s (%g,%g) is a ghost: configure {position, ammo} or {modules} changes its requests',what,x.position.x,x.position.y))
      local r=M.turretammo.clear(x,p.force)
      local text=r and table.concat({r.into and 'bring '..r.into or nil,r.out and 'take out '..r.out or nil},'; ') or nil
      return {name=x.name,position=x.position,removed=text,remote=not n or nil,
        line=string.format('%s (%g,%g): %s',x.name,x.position.x,x.position.y,text and 'item requests removed ('..text..')' or 'no item request on it')}
    end)
    if ok then rows[i]=out; if out.removed then cleared=cleared+1 else none=none+1 end
    else failed=failed+1; rows[i]={position=pos,error=reason(out)} end
  end
  if not a.positions then
    if not rows[1].line then error(rows[1].error,0) end
    local r=rows[1]; r.note='as a deconstruction planner over it and a cancel of that deconstruction: every item request on it goes'
    return r
  end
  return {cleared=cleared,without_requests=none>0 and none or nil,failed=failed>0 and failed or nil,entities=rows,
    note='as a deconstruction planner over each and a cancel of that deconstruction: every item request on it goes'}
end
function M.configure_turrets(p,a)
  assert(type(a.positions)=='table' and #a.positions>=1 and #a.positions<=64,'positions requires 1..64 {x,y} (turrets or their ghosts)')
  assert(a.position==nil,'give position or positions, not both')
  local rows,done,failed={},0,0
  for i,pos in ipairs(a.positions) do
    local args={}
    for k,v in pairs(a) do if k~='positions' then args[k]=v end end
    args.position=pos
    if type(pos)=='table' then args.name=pos.name or args.name; args.unit_number=pos.unit_number or args.unit_number end
    local ok,out=pcall(function()
      local near,e=configure_target(p,args)
      local r=M.configure_turret(e,args)
      r.remote=not near or nil
      return r
    end)
    if ok then done=done+1; rows[i]=out else failed=failed+1; rows[i]={position=pos,error=reason(out)} end
  end
  return {configured=done,failed=failed>0 and failed or nil,turrets=rows}
end
-- An inserter's spoil priority (Sol, 18:15, from viewer Foobator): the inserter GUI's Spoil priority, none, fresh first
-- or spoiled first (which spoilable stack it takes first). LuaEntity.inserter_spoil_priority in 2.0.77 (read and
-- write in the binary; its values are tried as fresh-first and fresh_first, and read back as the game spells them).
M.SPOIL_PRIORITY={none='none',off='none',fresh_first='fresh-first',['fresh-first']='fresh-first',spoiled_first='spoiled-first',['spoiled-first']='spoiled-first'}
function M.read_spoil_priority(e)
  local ok,v=pcall(function() return e.inserter_spoil_priority end)
  return ok and v or nil
end
function M.set_spoil_priority(e,want)
  local canon=type(want)=='string' and M.SPOIL_PRIORITY[want]
  if not canon then error('spoil_priority is none, fresh_first or spoiled_first (the inserter GUI\'s Spoil priority)',0) end
  local last
  for _,v in ipairs({canon,(canon:gsub('-','_'))}) do
    local ok,err=pcall(function() e.inserter_spoil_priority=v end)
    if ok then return M.read_spoil_priority(e) end
    last=err
  end
  error('the game refused spoil priority '..want..': '..tostring(last),0)
end
-- An inserter's hand size now (built or ghost): 1, its prototype's bonus and the force's (bulk or not), as the GUI's
-- stack size override slider reaches.
function M.inserter_hand_max(e)
  local proto=e.type=='entity-ghost' and e.ghost_prototype or e.prototype
  local n=1+(proto.inserter_stack_size_bonus or 0)
  local okb,uses=pcall(function() return proto.uses_inserter_stack_size_bonus end)
  if not okb or uses~=false then
    local okf,bonus=pcall(function() return proto.bulk and e.force.bulk_inserter_capacity_bonus or e.force.inserter_stack_size_bonus end)
    n=n+(okf and bonus or 0)
  end
  return n
end
function handlers.configure(p,a)
  if a.modules~=nil and a.ammo==nil then return M.configure_modules(p,a) end
  -- A turret's priority targets and Ignore unprioritised targets: several at once with positions.
  if a.positions~=nil then
    if a.item_requests==false or a.ammo==false then return M.clear_requests(p,a) end
    assert(a.priority_targets~=nil or a.ignore_unprioritised~=nil,'positions goes with priority_targets or ignore_unprioritised (turrets), or with item_requests: false')
    return M.configure_turrets(p,a)
  end
  local near,e=configure_target(p,a)
  -- An inserter's wait for a full hand (details.lua; d22 batch104 BN2, luna #1931): fixed by its prototype in 2.0.77, so
  -- the same as its own is read back and the other refused, before anything else in the call changes; with filters,
  -- spoil_priority or hand_size in the same call, those go on as without it.
  if a.wait_for_full_hand~=nil then
    local w=M.details.configure_wait_for_full_hand(e,a.wait_for_full_hand)
    if a.hand_size==nil and a.spoil_priority==nil and a.filters==nil and a.filter==nil and a.filter_mode==nil and a.use_filters==nil then
      assert(a.recipe==nil and a.modules==nil,'wait_for_full_hand goes with an inserter\'s filters, spoil priority and hand size')
      w.name=e.type=='entity-ghost' and e.ghost_name or e.name; w.position=e.position; w.ghost=e.type=='entity-ghost' or nil
      w.remote=not near or nil
      return w
    end
    local args={}
    for k,v in pairs(a) do if k~='wait_for_full_hand' then args[k]=v end end
    local out=handlers.configure(p,args)
    for k,v in pairs(w) do if k~='line' and out[k]==nil then out[k]=v end end
    out.wait_for_full_hand_line=w.line
    return out
  end
  if a.item_requests~=nil or (a.ammo==false and e.type~='entity-ghost') then return M.clear_requests(p,a,near,e) end
  -- filter (one name) on anything but a splitter is filters, as it was before splitters took it (an inserter's,
  -- loader's or storage chest's).
  if a.filter~=nil and not M.details.splitter_entity(e) then
    assert(a.filters==nil,'filter or filters, not both')
    local args={}
    for k,v in pairs(a) do args[k]=v end
    args.filters,args.filter=a.filter,nil
    a=args
  end
  -- A storage chest's filter (details.lua; Astra 18:58: removed modules had no storage chest to go to): storage_filter,
  -- or filters with one item on a storage chest (its one filter slot).
  if a.storage_filter~=nil or (a.filters~=nil and M.details.storage_chest(e)) then
    assert(a.recipe==nil and a.modules==nil and a.priority_targets==nil,'storage_filter is set alone: a storage chest has no recipe or modules')
    local v=a.storage_filter
    if v==nil then
      local list=type(a.filters)=='string' and {a.filters} or a.filters
      assert(type(list)=='table' and #list<=1,'a storage chest has one filter slot: one item in storage_filter')
      v=list[1] or false
    end
    local out=M.details.configure_storage_filter(e,v)
    out.remote=not near or nil
    return out
  end
  -- A splitter's input priority, output priority and filter (details.lua; Muse 19:50: a plate split could not favour
  -- the steel branch), or filters with one item on a splitter.
  if a.input_priority~=nil or a.output_priority~=nil or a.filter~=nil or (a.filters~=nil and M.details.splitter_entity(e)) then
    if not M.details.splitter_entity(e) then
      error(string.format('input_priority, output_priority and filter are a splitter\'s settings; %s (%g,%g) is a %s',
        e.type=='entity-ghost' and e.ghost_name or e.name,e.position.x,e.position.y,e.type=='entity-ghost' and e.ghost_type or e.type),0)
    end
    assert(a.recipe==nil and a.modules==nil,'a splitter has input_priority, output_priority and filter only')
    local args={input_priority=a.input_priority,output_priority=a.output_priority,filter=a.filter}
    if a.filters~=nil then
      assert(a.filter==nil,'filter or filters, not both')
      local list=type(a.filters)=='string' and {a.filters} or a.filters
      assert(type(list)=='table' and #list<=1,'a splitter has one filter: one item')
      args.filter=list[1] or false
    end
    local out=M.details.configure_splitter(e,args)
    out.remote=not near or nil
    return out
  end
  -- A chest's, cargo wagon's or landing pad's red-X bar, or the game's reason a machine has none and what it has
  -- instead (invbar.lua; d21 batch64 Z2, Luna #1576).
  if a.bar~=nil then
    assert(a.recipe==nil and a.filters==nil and a.storage_filter==nil,'bar goes alone (a chest, cargo wagon or landing pad: its usable slots)')
    local out=M.invbar.set(e,a.bar)
    out.remote=not near or nil
    return out
  end
  -- A turret ghost's ammo request, changed or cleared in place (turretammo.lua; batch33 A5, Sol 09:59).
  if a.ammo~=nil then
    assert(a.recipe==nil and a.filters==nil and a.priority_targets==nil,'ammo goes alone or with modules (a turret ghost\'s requests)')
    M.turretammo.check(a.ammo)
    local r=M.turretammo.set(e,a.ammo)
    local out={name=e.ghost_name,position=e.position,ammo_request=r.after,before=r.before,network_holds=r.network_holds,remote=not near or nil,
      line=string.format('%s ghost (%g,%g) requests %s (was %s)',e.ghost_name,e.position.x,e.position.y,r.after,r.before)}
    if a.modules~=nil then local b={}; for k,v in pairs(a) do if k~='ammo' then b[k]=v end end; out.modules=M.configure_modules(p,b) end
    return out
  end
  -- A programmable speaker's alert settings (circuits.lua; batch30 A2, Sol and viewer Foobator 05:47).
  if a.speaker_alert~=nil then
    assert(a.recipe==nil and a.filters==nil and a.modules==nil,'speaker_alert goes alone (a speaker takes no recipe, filters or modules)')
    local after,before=M.circuits.set_speaker_alert(e,a.speaker_alert)
    return {name=e.name,position=e.position,speaker_alert=after,before=before and before.line,line=after and after.line,remote=not near or nil}
  end
  -- A combinator's description, as its GUI writes it (circuits.lua; d20 batch56 R4, Astra #1399 for viewer Foobator).
  if a.description~=nil then
    assert(a.recipe==nil and a.filters==nil and a.modules==nil,'description goes alone (a combinator takes no recipe, filters or modules)')
    local d=M.circuits.check_description(e,a.description)
    local before=M.circuits.description(e) or ''
    e.combinator_description=d
    local after=M.circuits.description(e) or ''
    local name=e.type=='entity-ghost' and e.ghost_name or e.name
    return {name=name,position=e.position,ghost=e.type=='entity-ghost' or nil,description=after,description_before=before,remote=not near or nil,
      line=string.format('%s%s (%g,%g): description %s (was %s)',e.type=='entity-ghost' and 'ghost of ' or '',name,e.position.x,e.position.y,
        after=='' and 'none' or '"'..after..'"',before=='' and 'none' or '"'..before..'"')}
  end
  -- An artillery turret's or wagon's automatic targeting (artillery.lua; Grok, d15 14:07).
  if a.auto_targeting~=nil then
    assert(a.recipe==nil and a.filters==nil and a.priority_targets==nil and a.ignore_unprioritised==nil,'auto_targeting goes alone (an artillery piece takes no recipe, filters or priority targets)')
    local out=M.artillery.configure(e,a.auto_targeting)
    out.remote=not near or nil
    return out
  end
  if a.priority_targets~=nil or a.ignore_unprioritised~=nil then
    assert(a.recipe==nil and a.filters==nil and a.filter_mode==nil and a.use_filters==nil,
      'priority_targets and ignore_unprioritised go alone (a turret takes no recipe or filters)')
    local out=M.configure_turret(e,a)
    out.remote=not near or nil
    return out
  end
  -- A rocket silo's GUI checkboxes, in reach or by remote view on any planet (Astra 01:41: a silo on Vulcanus with
  -- automatic requests off held up a ferry): automatic requests and send to orbit automatically, read back after.
  -- (d20 batch53, Astra #1223 note) a rocket silo's ghost keeps both checkboxes for the silo it becomes (2.0.77: set on a
  -- ghost, read on the silo it revived as); it holds no cargo, so automatic requests are set as asked.
  if e.type=='entity-ghost' and e.ghost_type=='rocket-silo' then
    assert(a.recipe==nil and a.filters==nil,'a rocket silo takes auto_requests and send_to_orbit_automatically (its recipe is fixed)')
    assert(a.auto_requests~=nil or a.send_to_orbit_automatically~=nil,'a rocket silo takes auto_requests and send_to_orbit_automatically (true or false)')
    assert(a.auto_requests==nil or type(a.auto_requests)=='boolean','auto_requests must be true or false')
    assert(a.send_to_orbit_automatically==nil or type(a.send_to_orbit_automatically)=='boolean','send_to_orbit_automatically must be true or false')
    if a.auto_requests~=nil then e.use_transitional_requests=a.auto_requests end
    if a.send_to_orbit_automatically~=nil then e.send_to_orbit_automatically=a.send_to_orbit_automatically end
    return {name=e.ghost_name,position=e.position,ghost=true,remote=not near or nil,
      settings={auto_requests=e.use_transitional_requests,send_to_orbit_automatically=e.send_to_orbit_automatically},
      line=string.format('rocket-silo ghost (%g,%g): automatic requests %s, send to orbit automatically %s; the silo built from it keeps them',
        e.position.x,e.position.y,e.use_transitional_requests and 'on' or 'off',e.send_to_orbit_automatically and 'on' or 'off')}
  end
  if e.type=='rocket-silo' then
    assert(a.recipe==nil and a.filters==nil,'a rocket silo takes auto_requests and send_to_orbit_automatically (its recipe is fixed)')
    assert(a.auto_requests~=nil or a.send_to_orbit_automatically~=nil,'a rocket silo takes auto_requests and send_to_orbit_automatically (true or false)')
    assert(a.send_to_orbit_automatically==nil or type(a.send_to_orbit_automatically)=='boolean','send_to_orbit_automatically must be true or false')
    local out={}
    if a.auto_requests~=nil then
      out=space.launch(p,{position=e.position,unit_number=e.unit_number,auto_requests=a.auto_requests,force=a.force})
      out.auto_requests=nil
    end
    if a.send_to_orbit_automatically~=nil then
      local was=e.send_to_orbit_automatically and 'on' or 'off'
      e.send_to_orbit_automatically=a.send_to_orbit_automatically
      if M.editlog and e.unit_number then pcall(M.editlog.setting,'silo:'..e.unit_number,'send to orbit automatically',p.name or '?',was,e.send_to_orbit_automatically and 'on' or 'off') end
    end
    out.settings=M.silo.settings(e); out.remote=not near or nil
    return out
  end
  -- (d17 batch35 C1, Astra: a one-egg export took a constant combinator and a stack size signal only to set hand 1) the
  -- inserter GUI's stack size override (2.0; "Override hand size" from 2.1.22): 1 up to its hand size now, 0 or false
  -- for none (its own hand size again); with its filters and spoil priority in the same call if asked.
  if a.hand_size~=nil then
    local kind=e.type=='entity-ghost' and e.ghost_type or e.type
    if kind~='inserter' then error('hand_size applies to inserters (built or ghost); '..e.name..' is a '..tostring(kind),0) end
    assert(a.recipe==nil,'hand_size goes with an inserter\'s filters and spoil priority, not a recipe')
    local max=M.inserter_hand_max(e)
    local want=a.hand_size==false and 0 or integer(a.hand_size,nil,0,max,'hand_size (1..'..max..', its hand size now; 0 or false for none)')
    local _,before=pcall(function() return e.inserter_stack_size_override end)
    local ok,err=pcall(function() e.inserter_stack_size_override=want end)
    if not ok then error('the game refused hand size '..want..' on '..e.name..(e.type=='entity-ghost' and ' (a ghost)' or '')..': '..tostring(err),0) end
    local _,now=pcall(function() return e.inserter_stack_size_override end)
    local out=(a.filters~=nil or a.filter_mode~=nil or a.use_filters~=nil) and configure_filters(e,a) or {}
    if a.spoil_priority~=nil then out.spoil_priority_before=M.read_spoil_priority(e); out.spoil_priority=M.set_spoil_priority(e,a.spoil_priority) end
    now=tonumber(now) or want
    out.hand_size=now>0 and now or string.format('none: its own hand size, %d',max)
    out.hand_size_before=(tonumber(before) or 0)>0 and before or 'none'
    out.hand_max=max
    -- the circuit's set stack size, when on, sets the hand while its signal holds
    local okc,cs=pcall(function() local cb=e.get_control_behavior(); return cb and cb.circuit_set_stack_size and cb.circuit_stack_control_signal end)
    if okc and cs then out.circuit_note=string.format('circuit_set_stack_size is on (signal %s): the circuit sets the hand while that signal is on its wires',tostring(cs.name)) end
    out.ghost=e.type=='entity-ghost' and e.ghost_name or nil
    out.remote=not near or nil
    return out
  end
  -- An inserter's spoil priority (built or ghost), with its filters in the same call if asked.
  if a.spoil_priority~=nil then
    local kind=e.type=='entity-ghost' and e.ghost_type or e.type
    if kind~='inserter' then error('spoil_priority applies to inserters (built or ghost); '..e.name..' is a '..tostring(kind),0) end
    assert(a.recipe==nil,'spoil_priority goes with an inserter\'s filters, not a recipe')
    local before=M.read_spoil_priority(e)
    local now=M.set_spoil_priority(e,a.spoil_priority)
    local out=(a.filters~=nil or a.filter_mode~=nil or a.use_filters~=nil) and configure_filters(e,a) or {}
    out.spoil_priority,out.spoil_priority_before=now,before
    out.ghost=e.type=='entity-ghost' and e.ghost_name or nil
    out.remote=not near or nil
    return out
  end
  if a.filters~=nil or (a.recipe==nil and (a.filter_mode~=nil or a.use_filters~=nil)) then return configure_filters(e,a) end
  local need=configure_check(p,a,e,near)
  if need then
    -- (autowalk.lua) within 32 tiles: walk into reach, then change it there
    local f=M.configure_walk(p,a,e,need)
    if f then return M.configure_approach(p,a,e,f) end
    error(need,0)
  end
  local recipe=p.force.recipes[a.recipe]
  local current,current_quality=e.get_recipe()
  local same_quality=(a.quality or 'normal')==((current_quality and current_quality.name) or 'normal')
  local ghost=e.type=='entity-ghost' and e.ghost_name or nil
  if current and current.name==recipe.name and same_quality then return {recipe=recipe.name,quality=a.quality,unchanged=true,ghost=ghost,remote=not near or nil} end
  -- Fluids the machine holds that the new recipe takes none of (batch26 A3, Sol: a queued change from the railgun recipe
  -- left cold fluoroketone in a box, and the queue stopped): refused by default, naming them; fluid "drain" lets them go,
  -- "keep" changes it anyway. (d20 batch56 R6, Astra #1410: drain crashed on flush's table.) Read on 2.0.77 (private copy):
  -- a machine's fluidbox has no fluid segment of its own (get_fluid_segment_id nil, a pipe joined to it or not), so
  -- flush there removes nothing and returns {}; set_recipe drops a fluid the new recipe takes none of (input or output
  -- box) and keeps one it takes. So drain flushes (for a box that does have a segment), changes the recipe, and the
  -- reply says how much of each fluid left the machine (fluid_flushed) and what stays, measured after the change.
  local fluid_note,fluid_after
  if not ghost then
    assert(a.fluid==nil or a.fluid=='keep' or a.fluid=='drain','fluid: "drain" (change the recipe and let a fluid it takes none of go) or "keep" (the same change; the reply says what stayed)')
    local fluid_mode=a.fluid or (a.force==true and 'keep') or nil
    local takes={}
    for _,list in ipairs({recipe.ingredients or {},recipe.products or {}}) do
      for _,x in ipairs(list) do if x.type=='fluid' then takes[x.name]=true end end
    end
    local stray={}
    local boxes=e.fluidbox
    for i=1,boxes and #boxes or 0 do
      local f=boxes[i]
      if f and f.name and not takes[f.name] and f.amount>0 then stray[#stray+1]={index=i,name=f.name,amount=f.amount} end
    end
    if #stray>0 then
      local parts={}
      for _,x in ipairs(stray) do parts[#parts+1]=string.format('%s %g (fluidbox %d)',x.name,math.floor(x.amount*10+0.5)/10,x.index) end
      local text=string.format('%s holds %s, which recipe %s takes none of',e.name,table.concat(parts,', '),recipe.name)
      if fluid_mode==nil then
        error(text..': in 2.0.77 a recipe change drops a fluid the new recipe takes none of. fluid: "drain" changes the recipe and lets it go (the reply says how much left the machine and anything that stays); nothing changed',0)
      end
      if fluid_mode=='drain' then
        for _,x in ipairs(stray) do
          local okf,removed=pcall(function() return boxes.flush(x.index,x.name) end)
          if not okf then
            error(string.format('fluid "drain": the game refused to flush %s from fluidbox %d: %s; the recipe is unchanged',x.name,x.index,
              (tostring(removed):gsub('^[^:]*:%d+: ',''))),0)
          end
        end
      end
      local before={}
      for _,x in ipairs(stray) do before[x.name]=(before[x.name] or 0)+x.amount end
      -- After the change: what of each fluid left the machine and what stays (by box).
      fluid_after=function()
        local left,stays,gone={},{},{}
        local okb,now=pcall(function() return e.fluidbox end)
        for i=1,okb and now and #now or 0 do
          local f=now[i]
          if f and before[f.name] and f.amount>0 then
            left[f.name]=(left[f.name] or 0)+f.amount
            stays[#stays+1]=string.format('%s %g in fluidbox %d',f.name,math.floor(f.amount*10+0.5)/10,i)
          end
        end
        local names={}
        for name in pairs(before) do names[#names+1]=name end
        table.sort(names)
        local flushed,lines={},{}
        for _,name in ipairs(names) do
          local n=math.max(0,before[name]-(left[name] or 0))
          if n>0 then flushed[name]=math.floor(n*10+0.5)/10; lines[#lines+1]=string.format('%s %g',name,flushed[name]) end
        end
        fluid_note=(fluid_mode=='drain' and 'drained' or 'kept')..': '..text..'; '
          ..(#lines>0 and 'gone from the machine with the change: '..table.concat(lines,', ') or 'nothing of it left the machine')
          ..(#stays>0 and '; still in it: '..table.concat(stays,', ') or '')
        return next(flushed) and flushed or nil
      end
    end
  end
  -- A platform machine by remote view: its stacks to the hub first, then what the change returns (M.recipe_to_hub).
  local hub_inv=not ghost and not near and holds_items(e) and M.recipe_to_hub(e)
  if hub_inv then
    local moved={}
    local function put(name,count,quality)
      local key=name..(quality and quality~='normal' and '@'..quality or '')
      moved[key]=(moved[key] or 0)+count
    end
    for _,name in ipairs({'assembling_machine_input','assembling_machine_output'}) do
      local ok,mi=pcall(inventory,e,name)
      for i=1,ok and #mi or 0 do
        local st=mi[i]
        if st.valid_for_read then
          local q=st.quality; if type(q)~='string' then q=q and q.name or 'normal' end
          local n,c=st.name,st.count
          local okt=pcall(function() return hub_inv.insert(st) end)
          if okt then put(n,c,q); st.clear() end
        end
      end
    end
    for _,item in ipairs(e.set_recipe(recipe.name,a.quality) or {}) do
      local q=item.quality; if type(q)~='string' then q=q and q.name or 'normal' end
      local n=hub_inv.insert({name=item.name,count=item.count,quality=q})
      if n>0 then put(item.name,n,q) end
    end
    current=e.get_recipe()
    assert(current and current.name==recipe.name,'recipe incompatible with machine')
    local fluid_flushed=fluid_after and fluid_after()
    return {recipe=current.name,quality=a.quality,remote=true,to_hub=next(moved) and moved or nil,
      note='the machine\'s items went to the platform hub',fluid=fluid_note,fluid_flushed=fluid_flushed}
  end
  if ghost or not near then
    e.set_recipe(recipe.name,a.quality)
    current=e.get_recipe()
    assert(current and current.name==recipe.name,'recipe incompatible with machine')
    local fluid_flushed=fluid_after and fluid_after()
    return {recipe=current.name,quality=a.quality,remote=not near or nil,ghost=ghost,fluid=fluid_note,fluid_flushed=fluid_flushed}
  end
  local returned,spilled={},{}
  -- A machine slot is inserted as the stack itself so item data (spoilage) travels.
  local function give(stack,slot)
    local count=stack.count
    -- Slots carry a LuaQualityPrototype (userdata); set_recipe returns names.
    local quality=stack.quality
    if type(quality)~='string' then quality=quality and quality.name or 'normal' end
    local key=stack.name..(quality~='normal' and '@'..quality or '')
    local inserted=p.insert(slot and stack or {name=stack.name,count=count,quality=quality})
    returned[key]=(returned[key] or 0)+count
    if inserted<count then
      spilled[key]=(spilled[key] or 0)+count-inserted
      local rest={name=stack.name,count=count-inserted,quality=quality}
      if slot then stack.count=count-inserted; rest=stack end
      p.surface.spill_item_stack{position=p.position,stack=rest,enable_looted=true,allow_belts=false}
    end
    if slot then stack.clear() end
  end
  for _,name in ipairs({'assembling_machine_input','assembling_machine_output'}) do
    local ok,inv=pcall(inventory,e,name)
    for i=1,ok and #inv or 0 do
      if inv[i].valid_for_read then give(inv[i],true) end
    end
  end
  for _,item in ipairs(e.set_recipe(recipe.name,a.quality) or {}) do give(item) end
  current=e.get_recipe()
  assert(current and current.name==recipe.name,'recipe incompatible with machine')
  local fluid_flushed=fluid_after and fluid_after()
  return {recipe=current.name,quality=a.quality,remote=not near or nil,returned=next(returned) and returned or nil,spilled=next(spilled) and spilled or nil,fluid=fluid_note,fluid_flushed=fluid_flushed}
end
end
end -- Omitted inventories are inferred the way a player's click is: fuel into the
-- burner, smeltables into the furnace, and results back out of it.
local function infer_inventory(e,a)
  if a.outputs_only then
    local name=({['assembling-machine']='assembling_machine_output',furnace='furnace_result',['agricultural-tower']='agricultural_tower_output'})[e.type]
    assert(name,'outputs_only: '..e.name..' has no machine output inventory')
    return name,inventory(e,name)
  end
  local item=a.item and prototypes.item[a.item]
  local fuel=item and (item.fuel_value or 0)>0
  -- An item the machine's recipe takes goes to its recipe input (Grok, d15: nutrients into a biochamber making
  -- pentapod eggs went to its fuel slot, and the recipe stayed short; a module can be an ingredient too). Recipe input
  -- wins even when full: overflow must not go to the fuel slot or install a module instead. inventory: "fuel" puts it
  -- in the fuel slot.
  if a.direction=='to_entity' and item and e.get_recipe and e.type~='lab' then
    local ok,recipe=pcall(e.get_recipe)
    for _,ing in ipairs(ok and recipe and recipe.ingredients or {}) do
      if ing.type~='fluid' and ing.name==a.item then
        local name=e.type=='furnace' and 'furnace_source' or 'assembling_machine_input'
        local got,inv=pcall(inventory,e,name)
        if got then return name,inv end
      end
    end
  end
  if a.direction=='to_entity' and item and kind_order[item.type] then
    for _,name in ipairs(kind_order[item.type]) do
      local ok,inv=pcall(inventory,e,name)
      if ok then return name,inv end
    end
  end
  local fallback
  for _,name in ipairs(a.direction=='to_player' and take_order or give_order) do
    local ok,inv=pcall(inventory,e,name)
    if ok then
      if a.direction=='to_entity' then
        -- An inventory that refuses the item (a silo's ingredient slots for
        -- rocket cargo, say) yields to a later one that takes it.
        local accepts=not (item and inv.can_insert) or inv.can_insert{name=a.item,quality=a.quality or 'normal'}
        if accepts and (name=='fuel' or not fuel or not e.get_fuel_inventory()) then return name,inv end
        fallback=fallback or {name,inv}
      -- Trash slots come first when they hold something; never as a fallback.
      elseif name:find('_trash$') then
        if a.item and inv.get_item_count{name=a.item,quality=a.quality or 'normal'}>0 or not a.item and not inv.is_empty() then return name,inv end
      elseif not a.item or inv.get_item_count{name=a.item,quality=a.quality or 'normal'}>0 then return name,inv
      else fallback=fallback or {name,inv} end
    end
  end
  if not fallback then error(string.format('%s at (%g,%g) on %s has no transferable inventory',e.name,e.position.x,e.position.y,e.surface and e.surface.name or '?'),0) end
  return fallback[1],fallback[2]
end
-- Moves matching stacks with transfer_stack so item metadata travels intact.
local function move_stacks(source,target,match,limit)
  -- remaining never goes below 0: the engine refuses an amount under 1
  -- ("Given amount value(-1) too small", request #69, a queue transfer with
  -- keep and up_to near the cap), so every call is skipped at 0.
  local remaining,moved,order=math.max(0,limit),{},{}
  local fresh
  for i=1,#source do
    if remaining<=0 then break end
    local stack=source[i]
    if stack.valid_for_read and match(stack) then
      local key,name,quality,start=stack.name..'@'..stack.quality.name,stack.name,stack.quality.name,stack.count
      -- Its spoilage before the move (Sol, 22:25: the moved batch's spoil %).
      local okt,stick=pcall(function() return stack.spoil_tick end)
      local okp,spct=pcall(function() return stack.spoil_percent end)
      -- Top up partial stacks of the same item first, as a player's
      -- shift-click does, then fill empty slots.
      for pass=1,2 do
        for j=1,#target do
          if remaining<=0 or not stack.valid_for_read then break end
          local slot=target[j]
          if (pass==1)==(slot.valid_for_read and slot.name==name and slot.quality.name==quality) then
            local before=stack.count
            slot.transfer_stack(stack,math.min(before,remaining))
            remaining=math.max(0,remaining-(before-(stack.valid_for_read and stack.count or 0)))
          end
        end
      end
      local n=start-(stack.valid_for_read and stack.count or 0)
      if n>0 then
        if not moved[key] then moved[key]={name=name,count=0,quality=quality~='normal' and quality or nil}; order[#order+1]=key end
        moved[key].count=moved[key].count+n
        if okt and type(stick)=='number' and stick>0 then
          fresh=fresh or {}
          M.spoil.add_count(fresh,name,quality,n,okp and spct or 0,stick)
        end
      end
    end
  end
  local stacks,total={},0
  for i,key in ipairs(order) do stacks[i]=moved[key]; total=total+moved[key].count end
  return total,stacks,fresh
end
-- A moved batch's spoilage in lines (Sol, 22:25: choosing 2000 fresh agricultural packs for Aquilo): per item the
-- spread (spoil.lua spread_text); a science pack the running research takes, how many a unit it takes and the units
-- left. Effective research value uses the measured 2.0.77 spoil/durability rule (spoil.lua).
function M.fresh_lines(force,acc)
  local out={}
  for i,r in ipairs(acc or {}) do
    if i>8 then out[#out+1]=string.format('+%d more spoilable items',#acc-8); break end
    local line=M.spoil.spread_text(r)
    local value=M.spoil.research_text(r,force)
    if value then line=line..'; '..value end
    local tech=force and force.current_research
    for _,ing in ipairs(tech and tech.research_unit_ingredients or {}) do
      if ing.name==r.name and (ing.amount or 0)>0 then
        local left=math.max(0,math.floor((tech.research_unit_count or 0)*(1-(force.research_progress or 0))+0.5))
        line=line..string.format('; the running research %s takes %d a unit, %d units left',tech.name,ing.amount,left)
      end
    end
    out[#out+1]=line
  end
  return out
end
-- An inventory's spoilable items as those lines (names: only these items), nil when none (Sol, 22:52: a platform's
-- hub before departure, a drop's items, a rocket's cargo).
function M.fresh_inv(force,inv,names,eta,extra)
  if not inv and not extra then return nil end
  local acc=M.spoil.inventory(inv,{},nil,eta)
  if extra then M.spoil.inventory(extra,acc,nil,eta) end
  if names then
    local keep={}
    for _,r in ipairs(acc) do if names[r.name] then keep[#keep+1]=r end end
    acc=keep
  end
  if #acc==0 then return nil end
  return M.fresh_lines(force,acc)
end
-- What went up in a rocket, spoil by item (A11, Grok: both Gleba launches read it later from the platform): each
-- spoilable item's mean spoiled percent by count, and a line with its range.
function M.fresh_percent(inv)
  local acc=inv and M.spoil.inventory(inv,{}) or {}
  local map,parts={},{}
  for _,r in ipairs(acc) do
    local sp=M.spoil.spread(r)
    if sp then
      map[r.key]=sp.mean
      parts[#parts+1]=string.format('%s %d at %d%% spoiled by count%s',r.key,sp.count,sp.mean,sp.min==sp.max and '' or ' ('..sp.min..'-'..sp.max..'%)')
    end
  end
  if #parts==0 then return nil end
  return map,table.concat(parts,'; ')
end
-- Batch rows merged (transfer over several targets, a tour's stops).
function M.fresh_merge(into,acc)
  for _,r in ipairs(acc or {}) do M.spoil.merge(into,r) end
  return into
end
-- The rows alone, as a list (a reply or queue history encodes a list cleanly).
function M.fresh_list(acc)
  if not acc then return nil end
  local out={}
  for i,r in ipairs(acc) do out[i]=r end
  return #out>0 and out or nil
end
-- Where the character gives items from: the main inventory, then for ammo
-- the gun ammo slots, where crafted and picked-up ammo lands first.
local function give_sources(p,item)
  local out={p.get_main_inventory()}
  local proto=item and prototypes and prototypes.item[item]
  if proto and proto.type=='ammo' and defines.inventory.character_ammo and p.get_inventory then
    local ammo=p.get_inventory(defines.inventory.character_ammo)
    if ammo then out[#out+1]=ammo end
  end
  return out
end
local function held(p,item,quality)
  local n=0
  for _,inv in ipairs(give_sources(p,item)) do n=n+inv.get_item_count{name=item,quality=quality or 'normal'} end
  return n
end
-- A belt has no inventory a transfer takes from (Grok 12:21: transfer from the egg belt at (7.5,17.5) said it held none
-- while inspect showed 3-5 on its lanes, three times): the refusal says what its lanes carry and names pickup, which
-- takes items off belts as the pickup key does.
M.BELT_TYPES={['transport-belt']=true,['underground-belt']=true,splitter=true,loader=true,['loader-1x1']=true,['linked-belt']=true,['lane-splitter']=true}
function M.belt_refusal(e,item)
  if not M.BELT_TYPES[e.type] then return nil end
  local all,n,list={},0,{}
  for i=1,e.get_max_transport_line_index() do
    for _,c in ipairs(e.get_transport_line(i).get_contents()) do
      if not all[c.name] then all[c.name]=0; list[#list+1]=c.name end
      all[c.name]=all[c.name]+c.count
      if item==nil or c.name==item then n=n+c.count end
    end
  end
  local parts={}
  for _,name in ipairs(list) do parts[#parts+1]=name..' '..all[name] end
  return string.format('%s at (%g,%g) is a belt: transfer takes from inventories, and a belt\'s items are on its lanes (it carries %s now); pickup {belt: true, position: {x: %g, y: %g}, radius: 1, items: [%s]} takes them off the lanes as the pickup key does',
    e.name,e.position.x,e.position.y,#parts>0 and table.concat(parts,', ') or 'nothing',e.position.x,e.position.y,
    item and ('"'..item..'"') or (list[1] and '"'..list[1]..'"' or '"ITEM"')),n
end
-- (d18 batch36 C3, Grok: a hand transfer put a surplus over a requester's request, and robots hauled it out) a requester
-- or buffer chest's request for an item, summed over its active sections: {min, max (nil: none), trash_unrequested};
-- nil when it is no such chest or asks none of it.
function M.request_of(e,item,quality)
  if not (e and e.valid and e.type=='logistic-container') then return nil end
  local ok,pt=pcall(function() return e.get_logistic_point(defines.logistic_member_index.logistic_container) end)
  if not (ok and pt) then return nil end
  local okm,req_mode,buf_mode=pcall(function() return defines.logistic_mode.requester,defines.logistic_mode.buffer end)
  if not okm or (pt.mode~=req_mode and pt.mode~=buf_mode) then return nil end
  local min,max,found,nomax=0,0,false,false
  for _,f in ipairs(pt.filters or {}) do
    local n=type(f.name)=='string' and f.name or (f.name and f.name.name)
    local q=f.quality and (type(f.quality)=='string' and f.quality or f.quality.name) or 'normal'
    if n==item and q==(quality or 'normal') then
      found=true; min=min+(f.count or 0)
      if f.max_count==nil then nomax=true else max=max+f.max_count end
    end
  end
  if not found then return nil end
  local okt,trash=pcall(function() return e.get_requester_point().trash_not_requested end)
  local out={min=min,max=not nomax and max or nil}
  if okt and type(trash)=='boolean' then out.trash_unrequested=trash end
  return out
end
local function transfer_one(p,a,pos,e)
  if e then if not p.can_reach_entity(e) then error(M.out_of_reach(p,e),0) end
  else e=entity(p,{position=pos,name=pos.name or a.name,unit_number=pos.unit_number or a.unit_number}) end
  friendly(p,e)
  if a.direction~='to_entity' then local why=M.belt_refusal(e,a.item); if why then error(why,0) end end
  local inferred,target
  -- named: the inventory asked for, an alias (a silo's parts or cargo) resolved.
  local named=type(a.inventory)=='string' and M.inventory_name(e,a.inventory) or a.inventory
  assert(not (a.direction=='to_entity' and type(named)=='string' and named:find('_trash$')),tostring(a.inventory)..' is take-only (direction=to_player)')
  if named then
    local ok,inv=pcall(inventory,e,named)
    if not ok then error(tostring(inv):gsub('^[^:]*:%d+: ','')..': '..tostring(a.inventory)..'; '..M.inventory_names(e),0) end
    target=inv
  else inferred,target=infer_inventory(e,a) end
  local sources=a.direction=='to_player' and {target} or give_sources(p,a.item)
  if a.direction=='to_player' then target=p.get_main_inventory() end
  local quality=a.quality or 'normal'
  local wanted,match
  local function count(inv) return inv.get_item_count{name=a.item,quality=quality} end
  local function available()
    local n=0
    for _,inv in ipairs(sources) do n=n+count(inv) end
    return n
  end
  -- Personal logistics (Astra, 01:53: two hauls lost to auto-trash): what a
  -- take puts over the character's request max goes to trash. up_to=true
  -- stops at the max; keep_max=true refuses such a take (trash.lua).
  local lim=a.direction=='to_player' and (a.partial or a.keep_max) and M.trash.limits(p) or nil
  local held_back,caps
  if a.item then
    match=function(s) return s.name==a.item and s.quality.name==quality end
    -- Taking an item defaults to all of it; giving defaults to one.
    wanted=integer(a.count,a.direction=='to_player' and 10000 or 1,1,10000,'count')
    if a.keep~=nil then wanted=math.min(wanted,math.max(0,available()-integer(a.keep,0,0,100000,'keep'))) end
    if a.up_to~=nil then wanted=math.min(wanted,math.max(0,integer(a.up_to,1,1,100000,'up_to')-count(target))) end
    -- up_to_request: into a requester or buffer chest only up to its request (its max, else its min)
    if a.up_to_request~=nil then
      assert(a.up_to_request==true,'up_to_request is true')
      assert(a.direction=='to_entity','up_to_request goes with direction to_entity (into a requester or buffer chest)')
      local req=M.request_of(e,a.item,quality)
      assert(req,string.format('up_to_request: %s at (%g,%g) is no requester or buffer chest asking for %s',e.name,e.position.x,e.position.y,a.item))
      wanted=math.min(wanted,math.max(0,(req.max or req.min)-count(target)))
    end
    local room=lim and M.trash.room(p,a.item,quality,lim)
    if room then
      local take=math.min(wanted,available())
      if a.keep_max then
        assert(take<=room,string.format('keep_max: nothing taken; %d %s would put you %d over your request max (%d): the game trashes what is over it',
          take,a.item,take-room,M.trash.cap(lim,a.item,quality)))
      elseif take>room then held_back={[a.item]={take-room,M.trash.cap(lim,a.item,quality)}}; wanted=room end
    end
  else
    match=function() return true end
    wanted=integer(a.count,1000000,1,1000000,'count')
    -- Taking everything: per item, what fits under the request max.
    if lim then
      local over={}
      for _,source in ipairs(sources) do
        for _,st in ipairs(source.get_contents()) do
          local room=M.trash.room(p,st.name,st.quality,lim)
          if room and st.count>room then over[#over+1]={name=st.name,quality=st.quality,count=st.count,room=room} end
        end
      end
      if #over>0 and a.keep_max then
        local o=over[1]
        error(string.format('keep_max: nothing taken; %d %s would put you %d over your request max (%d): the game trashes what is over it',
          o.count,o.name,o.count-o.room,M.trash.cap(lim,o.name,o.quality)),0)
      end
      if #over>0 then
        caps={}
        for _,o in ipairs(over) do
          caps[o.name..'@'..(o.quality or 'normal')]=o.room
          held_back=held_back or {}; held_back[o.name]={o.count-o.room,M.trash.cap(lim,o.name,o.quality)}
        end
      end
    end
  end
  if a.budget then wanted=math.min(wanted,a.budget.left) end
  -- A rocket lifts 1000 kg: the game takes more by script and then refuses
  -- the launch, so only what fits goes in (shift04 07:17, 1060 kg aboard).
  local rocket=a.item and a.direction=='to_entity' and (named or inferred)=='rocket_silo_rocket' and e.type=='rocket-silo' and space and {}
  if rocket then
    local room,load=space.rocket_room(e,a.item)
    assert(room>0 or wanted==0,'the rocket is full by weight ('..load.weight..' of its lift): no '..a.item..' ('..load.each..' each) fits; launch it, or take cargo out (transfer direction=to_player inventory=rocket_silo_rocket)')
    if room<wanted then
      rocket.limited={requested=wanted,fits=room,note=string.format('a rocket lifts %s: %d of %d %s (%s each) fit',load.weight:match('/(.*)$'),room,wanted,a.item,load.each)}
      wanted=room
    end
  end
  -- min_fresh (Grok 12:21: collect from a biochamber's output took nutrients about 40% spoiled with no choice): a take
  -- leaves stacks less fresh than that percent where they are, and says how many.
  local stale_left
  if a.min_fresh~=nil and a.direction=='to_player' then
    local floor=integer(a.min_fresh,nil,0,100,'min_fresh')
    local base=match
    match=function(s) return base(s) and ((s.spoil_percent or 0)<=1-floor/100+1e-9) end
    stale_left=function()
      local n,worst=0,nil
      for _,source in ipairs(sources) do
        for i=1,#source do
          local st=source[i]
          if st.valid_for_read and base(st) and not match(st) then n=n+st.count; worst=math.max(worst or 0,st.spoil_percent or 0) end
        end
      end
      return n>0 and string.format('%d left where they were: less than %d%% fresh (the most spoiled %d%%)',n,floor,math.floor((worst or 0)*100+0.5)) or nil
    end
  end
  -- (d17 batch14 A13, Grok 2x: a cleanup moved fresh bioflux with the rotten) min_spoil (alias min_spoiled, as pickup's):
  -- only stacks at least that spoiled; max_fresh: only stacks at most that fresh (100 - it spoiled at least); the rest
  -- stay where they are, said in left_fresher.
  local spoil_floor
  if a.min_spoil~=nil or a.min_spoiled~=nil or a.max_fresh~=nil then
    local n=(a.min_spoil~=nil and 1 or 0)+(a.min_spoiled~=nil and 1 or 0)+(a.max_fresh~=nil and 1 or 0)
    assert(n==1,'give one of min_spoil (min_spoiled) and max_fresh')
    spoil_floor=a.max_fresh~=nil and 100-integer(a.max_fresh,nil,0,100,'max_fresh') or integer(a.min_spoil or a.min_spoiled,nil,0,100,'min_spoil')
    local base=match
    match=function(s) return base(s) and (s.spoil_percent or 0)>=spoil_floor/100-1e-9 end
    local prev=stale_left
    stale_left=function()
      local n2,best=0,nil
      for _,source in ipairs(sources) do
        for i=1,#source do
          local st=source[i]
          if st.valid_for_read and base(st) and not match(st) then n2=n2+st.count; best=math.min(best or 1,st.spoil_percent or 0) end
        end
      end
      local t=n2>0 and string.format('%d left where they were: less than %d%% spoiled (the least spoiled %d%%)',n2,spoil_floor,math.floor((best or 0)*100+0.5)) or nil
      local q=prev and prev()
      return q and t and q..'; '..t or q or t
    end
  end
  local moved,stacks,order=0,{},{}
  local fresh,fresh_done
  local function add(part,fr)
    if fr then fresh=M.fresh_merge(fresh or {},fr) end
    for _,st in ipairs(part) do
      local key=st.name..'@'..(st.quality or 'normal')
      if order[key] then order[key].count=order[key].count+st.count else order[key]=st; stacks[#stacks+1]=st end
    end
  end
  for _,source in ipairs(sources) do
    if moved>=wanted then break end
    if caps then
      -- Item by item, those over the request max only up to it.
      local kinds={}
      for _,st in ipairs(source.get_contents()) do kinds[#kinds+1]=st end
      for _,st in ipairs(kinds) do
        if moved>=wanted then break end
        local k=st.name..'@'..(st.quality or 'normal')
        local limit=math.min(wanted-moved,caps[k] or math.huge)
        if limit>0 then
          local n,part,fr=move_stacks(source,target,function(s) return s.name==st.name and s.quality.name==(st.quality or 'normal') end,limit)
          moved=moved+n; add(part,fr)
          if caps[k] then caps[k]=caps[k]-n end
        end
      end
    elseif (a.fresh_first or a.spoiled_first) and a.item then
      -- fresh_first (Grok 15:25: a walking load_silo took the chest's stacks in slot order and 87%-spoiled packs went
      -- up): every source's stacks of it, least spoiled first, each moved whole; spoiled_first (d17 batch14 A13, Grok):
      -- the most spoiled first.
      if not fresh_done then
        fresh_done=true
        local list={}
        for _,src in ipairs(sources) do
          for i=1,#src do local st=src[i]; if st.valid_for_read and match(st) then list[#list+1]=st end end
        end
        local rows={}
        for k,st in ipairs(list) do rows[k]={st=st,pct=st.spoil_percent or 0,k=k} end
        local worst=a.spoiled_first and not a.fresh_first
        table.sort(rows,function(x,y) if x.pct~=y.pct then if worst then return x.pct>y.pct end return x.pct<y.pct end return x.k<y.k end)
        for k,r in ipairs(rows) do list[k]=r.st end
        local n,part,fr=move_stacks(list,target,match,wanted-moved)
        moved=moved+n; add(part,fr)
      end
    else
      local n,part,fr=move_stacks(source,target,match,wanted-moved)
      moved=moved+n; add(part,fr)
    end
  end
  if a.budget then a.budget.left=a.budget.left-moved end
  -- Matching items left behind while more was asked for: the target is full.
  local full
  if moved<wanted then
    for _,source in ipairs(sources) do
      for i=1,#source do
        local stack=source[i]
        if not full and stack.valid_for_read and match(stack) then
          local left=0
          for _,inv in ipairs(sources) do left=left+inv.get_item_count{name=stack.name,quality=stack.quality.name} end
          full={requested=math.min(wanted,moved+left),got=moved,blocked_item=stack.name}
        end
      end
    end
  end
  -- A target with every slot taken: what fills them (Sol, 22:08: 494 spoilage among a requester's 48 slots).
  if full and a.direction=='to_entity' then
    local okf,f=pcall(M.slots.full,target,full.blocked_item)
    if okf and f then full.slots=f.text end
    full.inventory=named or inferred
    local okd,detail=pcall(M.slots.refusal,target,full.blocked_item,full.inventory,e,full.slots)
    if okd then full.slots=detail end
  end
  -- A burner's fuel slot holds one fuel type: giving coal to a boiler burning
  -- wood is refused by the game; say what is in the way.
  if full and a.direction=='to_entity' and (named or inferred)=='fuel' then
    for i=1,#target do
      local slot=target[i]
      if slot.valid_for_read and slot.name~=a.item then
        full.holding=slot.name
        full.note=string.format('the fuel slot holds %s; one fuel type at a time: let it burn out or take it out first (transfer to_player item=%s)',slot.name,slot.name)
        break
      end
    end
  end
  -- A silo with automatic requests on loads its rocket for the platforms'
  -- requests and refuses cargo by hand, empty rocket or not (request #124).
  if full and a.direction=='to_entity' and (named or inferred)=='rocket_silo_rocket' and e.type=='rocket-silo' then
    local ok,auto=pcall(function() return e.use_transitional_requests end)
    if ok and auto then
      full.auto_requests=true
      full.note='this silo has automatic requests on: the game fills its rocket for the platforms\' requests and takes no cargo by hand; turn them off with launch {position, auto_requests=false}, then transfer (and launch with platform=...)'
      -- the setting first, where the short line reads it (C4, Haiku 23:40: the refusal named the inventory, not the switch)
      full.blocked_by='automatic requests (the silo GUI\'s checkbox): on'
      full.slots='blocked by the silo\'s automatic requests (on): it takes no cargo by hand; launch {position, auto_requests: false} turns them off, or load_silo {..., launch: true, auto_requests: "pause"} loads and launches with them off for that load'
    end
  end
  -- Asked for an item the character does not hold at all: say so.
  local short=a.item and a.direction=='to_entity' and moved<wanted and not full and moved==0 and available()==0 and wanted or nil
  -- Hand share: feeding anything, and collecting from machines (not storage).
  local kind=a.direction=='to_entity' and 'fed' or (e.type~='container' and e.type~='logistic-container' and 'collected')
  for _,s in ipairs(kind and stacks or {}) do survey.log_hand(kind,s.name,s.count) end
  if moved>0 then
    -- The usual inventory feedback a player sees when moving items by hand.
    local sign,parts=a.direction=='to_player' and '+' or '-',{}
    for _,s in ipairs(stacks) do parts[#parts+1]=sign..s.count..' [item='..s.name..']' end
    p.create_local_flying_text{text=table.concat(parts,' '),position=e.position}
    -- The same for the camera clients, in the agent's colour (visuals.lua).
    pcall(M.visuals.moved,p,e.position,e.surface,table.concat(parts,' '))
    -- Takes and puts by hand, for the agent's repeated hauls (selfview.lua).
    pcall(M.selfview.moved,p,a.direction,e,stacks)
    pcall(M.hauling.moved,p.index,a.direction,e.position,e.surface and e.surface.name,stacks,e.name)
    pcall(M.filled_mark,p,a.direction,e,stacks)
  end
  local out={transferred=moved,items=not a.item and stacks or nil,inventory=inferred or (named~=a.inventory and named or nil),none_held=short and a.item or nil,target_has=short and count(target) or nil,
    at_up_to=a.item and a.up_to~=nil and a.direction=='to_entity' and count(target)>=a.up_to or nil}
  if stale_left then out.left_less_fresh=stale_left() end
  -- (C3) into a requester or buffer chest: what now lies over its request max
  if a.item and a.direction=='to_entity' and moved>0 then
    local req=M.request_of(e,a.item,quality)
    if req then
      local held=count(target)
      out.request=string.format('%s asks %s %d..%s; it holds %d now%s',e.name,a.item,req.min,req.max and tostring(req.max) or 'inf',held,
        req.max and held>req.max and string.format(': %d over its request max%s',held-req.max,req.trash_unrequested~=nil and (req.trash_unrequested and ' (trash unrequested on)' or ' (trash unrequested off)') or '') or '')
      if req.max and held>req.max then out.over_request=held-req.max end
    end
  end
  -- A fuel item into a recipe input (Grok, d15: nutrients for pentapod eggs): which slot, and how to reach the other.
  if inferred and (inferred=='assembling_machine_input' or inferred=='furnace_source') and a.item and (prototypes.item[a.item].fuel_value or 0)>0
    and pcall(function() return e.get_fuel_inventory() end) and e.get_fuel_inventory() then
    out.inventory_note=string.format('into the recipe input: its recipe takes %s; inventory: "fuel" puts it in the fuel slot',a.item)
  end
  if moved>0 and a.direction=='to_entity' and e.type=='logistic-container' then
    local okn,note=pcall(M.delivery_note,p,e,a.item)
    if okn then out.delivery_note=note end
  end
  if a.direction=='to_player' then
    -- What the game will move to the trash slots, and what up_to left behind at the max.
    out.trash=moved>0 and M.trash.lines(p,a.item and {{name=a.item,quality=quality,count=moved}} or stacks) or nil
    if out.trash and a.tally then
      for _,st in ipairs(a.item and {{name=a.item,quality=quality,count=moved}} or stacks) do a.tally.t=M.trash.count(p,a.tally.t,st.name,st.quality,st.count) end
    end
    if held_back then
      local parts={}
      for name,v in pairs(held_back) do parts[#parts+1]=string.format('%d %s (your request max %d)',v[1],name,v[2]) end
      table.sort(parts)
      out.left_at_max=table.concat(parts,', ')..' left in the source'
    end
  end
  if a.direction=='to_player' then out.inventory_full=full else out.entity_full=full end
  -- The moved batch's spoilage rows (made into lines by moved_line, or summed by a batch or a tour).
  out.fresh=M.fresh_list(fresh)
  -- (d17 batch14 A13, Grok ~6 times: a supply read after every spoilable move) the moved stacks' spread in a line each
  if fresh and #fresh>0 then
    local okl,lines=pcall(M.fresh_lines,p.force,fresh)
    out.freshness=okl and lines or nil
  end
  if rocket then out.rocket_weight=space.rocket_weight(e); out.weight_limited=rocket.limited end
  -- A rocket-part ingredient put into the rocket's cargo says where it went and where the recipe takes it from.
  if moved>0 and a.item and a.direction=='to_entity' and e.type=='rocket-silo' and (named or inferred)=='rocket_silo_rocket' then
    local names,recipe=M.silo.ingredients(e)
    for _,name in ipairs(names) do
      if name==a.item then
        out.cargo_note=string.format('%d %s went into rocket_silo_rocket (cargo), which goes up with the rocket; %s is a %s ingredient, and the %s recipe takes its ingredients from assembling_machine_input (parts)',
          moved,a.item,a.item,recipe,recipe)
      end
    end
  end
  -- Nothing moved and nothing was full: say why (agent-minds study: about 125
  -- empty takes a shift read as a success; Muse 38 of 43 circuit takes).
  if moved==0 and not full and not short then
    pcall(function()
      local where=string.format('%s at (%g,%g)',e.name,e.position.x,e.position.y)
      local label=a.item and (a.item..(quality~='normal' and '@'..quality or '')) or 'items'
      if a.direction=='to_player' then
        local list={}
        for i,s in ipairs(sources[1].get_contents()) do if i<=3 then list[#list+1]=s.name..'*'..s.count end end
        out.nothing_moved=string.format('%s holds no %s in %s; %s',where,label,named or inferred or 'its inventories',
          #list>0 and 'it holds '..table.concat(list,' ') or 'it is empty')
        -- What it held when it was named to this agent, and what robots had reserved then (Grok, 15:20).
        if a.item then out.nothing_moved=out.nothing_moved..(M.stock_then(e,a.item) or '') end
        -- Where the nearest chest holding it is (Haiku 10:50), read once a tick per agent and item (a batch's
        -- empty targets share it).
        if a.item then
          local c=M.nearest_cache
          if not c or c.tick~=game.tick then c={tick=game.tick}; M.nearest_cache=c end
          local key=p.index..'/'..a.item..'@'..quality
          if c[key]==nil then
            local ok,near=pcall(M.nearest_holding,p,a.item,quality,32,e)
            c[key]=ok and near and string.format('; the nearest holding %s: %s at (%g,%g), %.1f tiles from you, holds %d%s%s',
              label,near.entity.name,near.entity.position.x,near.entity.position.y,near.distance,near.count,M.reserved_text(near.reserved),
              near.feeds and ' ('..near.feeds..'; transfer from: "nearest" with feeding: true)' or ' (transfer from: "nearest")') or false
          end
          if c[key] then out.nothing_moved=out.nothing_moved..c[key] end
        end
      elseif out.at_up_to then
        out.nothing_moved=string.format('%s already holds %d %s (up_to %d)',where,count(target),label,a.up_to)
      elseif a.keep~=nil and wanted==0 then
        out.nothing_moved=string.format('you hold %d %s and keep %d',available(),label,a.keep)
      else
        out.nothing_moved=string.format('%s took no %s into %s',where,label,named or inferred or 'its inventory')
      end
    end)
  end
  -- An emptied corpse goes, as when a player takes everything from it.
  if a.direction=='to_player' and e.type=='character-corpse' and sources[1].is_empty() then e.destroy(); out.corpse_removed=true end
  return out
end
-- Targets are {position} or {entity}. Each is independent: an unreachable one
-- must not undo the others. Quiet batches list only entities that changed or failed.
local function transfer_batch(p,a,targets,quiet)
  local stale
  local total,totals,items,rows,untouched=0,{},{},{},0
  local left_at_max,bfresh
  local blocked,short,empty
  for _,t in ipairs(targets) do
    local pos=t.entity and t.entity.position or t.position
    local ok,result
    -- A spent batch total or a full character inventory ends the batch.
    if (a.budget and a.budget.left==0) or blocked then ok=false
    else ok,result=pcall(transfer_one,p,a,t.position,t.entity) end
    if result==nil then untouched=untouched+1
    elseif ok then
      total=total+result.transferred
      empty=empty or result.nothing_moved
      blocked=result.inventory_full and result.inventory_full.blocked_item
      if result.none_held then
        short=short or {}
        short[#short+1]=string.format('(%g,%g) has %d',pos.x,pos.y,result.target_has)
      end
      if result.transferred>0 or not quiet or result.entity_full then
        rows[#rows+1]={position=pos,moved=result.transferred,full=result.entity_full and true or nil,inventory=result.inventory or a.inventory,delivery_note=result.delivery_note,why=result.entity_full and result.entity_full.slots or nil}
      else untouched=untouched+1 end
      for _,s in ipairs(result.items or {}) do
        local key=s.name..'@'..(s.quality or 'normal')
        if totals[key] then totals[key].count=totals[key].count+s.count
        else totals[key]={name=s.name,count=s.count,quality=s.quality}; items[#items+1]=totals[key] end
      end
      left_at_max=left_at_max or result.left_at_max
      -- min_fresh: what stayed for being less fresh (A7), the first place's line.
      if result.left_less_fresh then stale=stale or string.format('(%g,%g): %s',pos.x,pos.y,result.left_less_fresh) end
      if result.fresh then bfresh=M.fresh_merge(bfresh or {},result.fresh) end
    else rows[#rows+1]={position=pos,moved=0,error=reason(result)} end
  end
  -- Nothing moved and targets wanted more, but the character holds none.
  if a.fail_short and total==0 and short then
    error(string.format('no %s in inventory or ammo slots; %d target(s) want more: %s',a.item,#short,table.concat(short,', ',1,math.min(#short,6))),0)
  end
  M.all_failed(rows,#targets)
  -- Over all targets: what the game will move to the trash slots (trash.lua).
  local trash=a.direction=='to_player' and total>0 and M.trash.lines(p,a.item and {{name=a.item,quality=a.quality,count=total}} or items) or nil
  return {transferred=total,items=not a.item and items or nil,entities=rows,unchanged=(quiet or untouched>0) and untouched or nil,trash=trash,
    left_at_max=left_at_max,fresh=M.fresh_list(bfresh),left_less_fresh=stale,
    none_held=short and #short or nil,total=a.budget and a.budget.cap,inventory_full=blocked and {got=total,blocked_item=blocked} or nil,
    nothing_moved=total==0 and not blocked and empty and (#targets>1 and string.format('none of %d targets: first, %s',#targets,empty) or empty) or nil,
    tally=#targets>1 and M.tally{moved=a.item and {{name=a.item,count=total,quality=a.quality~='normal' and a.quality or nil}} or items,
      targets=#targets,rows=rows,none_held=short and #short or 0,full_item=blocked} or nil}
end
-- A call over several targets where every one failed is a failure, naming the first reason (Astra 08:47: rearm on 6
-- guns returned ok with moved 0 while each was refused). Some moved, or were already full or wanted nothing: ok, with
-- the tally.
function M.all_failed(rows,n)
  if n<1 then return end
  local failed,first=0,nil
  for _,r in ipairs(rows) do if r.error then failed=failed+1; first=first or r end end
  if failed<n then return end
  local at=first.position and string.format(' (%g,%g)',first.position.x or first.position[1] or 0,first.position.y or first.position[2] or 0) or ''
  error(string.format('%s target%s failed, nothing moved; the first%s: %s',n==1 and 'the' or 'all '..n,n==1 and '' or 's',at,first.error),0)
end
-- One line closing a transfer or collect over several targets (Muse): moved per item, targets touched of the total,
-- and what fell short (full, holding none, failed with the first reason, never reached).
function M.tally(t)
  local moved={}
  for _,s in ipairs(t.moved or {}) do
    if s.count>0 then moved[#moved+1]=s.count..' '..s.name..(s.quality and s.quality~='normal' and '@'..s.quality or '') end
  end
  local touched,full,failed,why=0,0,0,nil
  for _,r in ipairs(t.rows or {}) do
    if (r.moved or r.transferred or 0)>0 then touched=touched+1 end
    if r.full then full=full+1 end
    if r.error then failed=failed+1; why=why or r.error end
  end
  touched=touched+(t.touched or 0)
  local shorts={}
  if t.full_item then shorts[#shorts+1]='your inventory full of '..t.full_item end
  if full>0 then shorts[#shorts+1]=full..' full' end
  if (t.none_held or 0)>0 then shorts[#shorts+1]=t.none_held..' wanting more you hold none of' end
  if failed>0 then shorts[#shorts+1]=failed..' failed ('..tostring(why):gsub('%s+',' '):sub(1,120)..')' end
  if (t.unreached or 0)>0 then shorts[#shorts+1]=t.unreached..' not reached' end
  if (t.errors or 0)>0 then shorts[#shorts+1]=t.errors..' failed' end
  local line=string.format('moved %s; %d of %d %s touched',#moved>0 and table.concat(moved,', ') or 'nothing',touched,t.targets,t.noun or 'targets')
  return line..(#shorts>0 and '; short: '..table.concat(shorts,', ') or '')
end
-- Items a feed still needs across its targets (up_to tops up; else count each).
local function shortfall(p,a,targets)
  local need=0
  for _,t in ipairs(targets) do
    local ok,n=pcall(function()
      local e=t.entity or entity(p,{position=t.position,name=t.position.name or a.name,unit_number=t.position.unit_number or a.unit_number})
      local _,inv
      if a.inventory then inv=inventory(e,a.inventory) else _,inv=infer_inventory(e,a) end
      local have=inv.get_item_count{name=a.item,quality=a.quality or 'normal'}
      return a.up_to and math.max(0,a.up_to-have) or (a.count or 1)
    end)
    if ok then need=need+n end
  end
  return need
end
-- A feed short of items the hand-crafting queue will deliver waits for them
-- (like construct does) instead of moving nothing: a timed 'feed' action that
-- reruns the handler once the crafts land.
local FEED_CHECK=10
local function await_feed(p,handler,a,item,need)
  if a.awaited or need<=0 then return nil end
  local have,coming=held(p,item,a.quality),crafting_count(p,item)
  if have>=need or coming==0 then return nil end
  if state().active[p.index] then finish(p.index,'replaced') end
  local args={}
  for k,v in pairs(a) do args[k]=v end
  args.awaited=true
  local until_tick=game.tick+math.ceil(crafting_left(p)*60)+600
  state().active[p.index]={kind='feed',handler=handler,args=args,item=item,need=need,awaiting_craft=true,until_tick=until_tick,next_check=game.tick+FEED_CHECK}
  return {awaiting_craft={item=item,held=have,need=need,crafting=coming},until_tick=until_tick}
end
M.await_feed=await_feed
-- A batch build short of several items the hand-craft queue is making waits for all of them (Sol, shift12 13:50: a
-- batch that waited for its first item placed 3 entries and failed on the next, its item still crafting).
-- wants: {{item, need}} in the batch's order; nil when none is short and crafting.
function M.await_crafts(p,handler,a,wants)
  if a.awaited then return nil end
  local waiting={}
  for _,w in ipairs(wants) do
    local coming=crafting_count(p,w.item)
    local have=coming>0 and held(p,w.item,a.quality) or 0
    if coming>0 and have<w.need then waiting[#waiting+1]={item=w.item,need=w.need,held=have,crafting=coming} end
  end
  if #waiting==0 then return nil end
  if #waiting==1 then return await_feed(p,handler,a,waiting[1].item,waiting[1].need) end
  if state().active[p.index] then finish(p.index,'replaced') end
  local args={}
  for k,v in pairs(a) do args[k]=v end
  args.awaited=true
  local until_tick=game.tick+math.ceil(crafting_left(p)*60)+600
  local items={}
  for i,w in ipairs(waiting) do items[i]={item=w.item,need=w.need} end
  local first=waiting[1]
  state().active[p.index]={kind='feed',handler=handler,args=args,item=first.item,need=first.need,items=items,awaiting_craft=true,
    until_tick=until_tick,next_check=game.tick+FEED_CHECK}
  return {awaiting_craft={item=first.item,held=first.held,need=first.need,crafting=first.crafting,items=waiting},until_tick=until_tick}
end
-- A feed waiting for crafts goes once every item it waits for is held, or no longer coming.
function M.feed_ready(p,action)
  if action.await_silo then return M.rocketload.ready(p,action) end
  for _,w in ipairs(action.items or {{item=action.item,need=action.need}}) do
    if w.item and crafting_count(p,w.item)>0 and held(p,w.item,action.args.quality)<w.need then return false end
  end
  return true
end
-- Own entities in reach (or at explicit positions) matching a predicate,
-- nearest first so a short supply goes to the closest machines.
local function reachable(p,a,wanted)
  local out={}
  if a.positions then
    assert(type(a.positions)=='table' and #a.positions>=1 and #a.positions<=64,'positions requires 1..64 entries')
    for i,pos in ipairs(a.positions) do out[i]={position=pos} end
    return out
  end
  local found={}
  for _,e in pairs(p.surface.find_entities_filtered{position=p.position,radius=(p.reach_distance or 10)+3,force=p.force,type=a.types}) do
    if e.valid and wanted(e) and p.can_reach_entity(e) then found[#found+1]=e end
  end
  table.sort(found,function(x,y) return distance(p.position,x.position)<distance(p.position,y.position) end)
  for i,e in ipairs(found) do out[i]={entity=e} end
  return out
end
-- With a radius, rearm/refuel walk a nearest-first route through every
-- matching entity in it that is below the target, topping each up.
-- types takes entity types; an entity name there is taken as a name (Grok, shift12: refuel types stone-furnace found
-- nothing: its type is furnace). Entries that are both (inserter, lab, boiler) stay types. Every entity of ours matching
-- base (position and radius, or area) of those kinds, and a note naming the names taken.
M.kind_is_type={}
function M.find_kinds(p,base,kinds)
  local q={}
  for k,v in pairs(base) do q[k]=v end
  q.force=p.force
  if kinds==nil then return p.surface.find_entities_filtered(q),nil end
  if type(kinds)=='string' then kinds={kinds} end
  local types,names,noted={},{},{}
  for _,k in ipairs(kinds) do
    local is_type=M.kind_is_type[k]
    if is_type==nil then
      -- A LuaCustomTable in the game: pairs, not next.
      local ok,any=pcall(function() for _ in pairs(prototypes.get_entity_filtered{{filter='type',type=k}}) do return true end return false end)
      is_type=not ok or any or not prototypes.entity[k]
      M.kind_is_type[k]=is_type
    end
    if is_type then types[#types+1]=k
    else names[#names+1]=k; noted[#noted+1]=string.format('%s is an entity name (its type: %s)',k,prototypes.entity[k].type) end
  end
  local out,seen={},{}
  local function add(list)
    for _,e in pairs(list) do
      local key=e.unit_number or e
      if not seen[key] then seen[key]=true; out[#out+1]=e end
    end
  end
  if #types>0 then q.type=types; add(p.surface.find_entities_filtered(q)); q.type=nil end
  if #names>0 then q.name=names; add(p.surface.find_entities_filtered(q)) end
  return out,#noted>0 and ('types takes entity types: '..table.concat(noted,', ')..'; taken as a name') or nil
end
-- Nothing in the radius or area (Grok, shift12 13:50: a refuel 48 tiles from furnaces out of fuel placed 0 and said
-- nothing): the nearest one outside it that would have been a target, within 512 tiles of the character.
do local NEAREST_OUT=512
function M.nearest_outside(p,kinds,inside,match,what)
  local list=M.find_kinds(p,{position=p.position,radius=NEAREST_OUT},kinds)
  local rows={}
  for _,e in ipairs(list) do
    if e.valid and not inside(e) then rows[#rows+1]={e=e,d=distance(p.position,e.position)} end
  end
  table.sort(rows,function(x,y) return x.d<y.d end)
  for _,r in ipairs(rows) do
    local ok,yes=pcall(match,r.e)
    if ok and yes then
      return string.format('nearest %s outside it: %s at (%g,%g), %.0f tiles from you',what,r.e.name,r.e.position.x,r.e.position.y,r.d)
    end
  end
  return string.format('no %s within %d tiles of you',what,NEAREST_OUT)
end
end -- A tour that found nothing keeps what its reply said for its last (finish; fh --wait shows last.why).
function M.tour_note(p,out)
  local action=state().active[p.index]
  if action and action.kind=='gather' then
    action.nothing=out.nothing; action.nearest_outside=out.nearest_outside; action.types_note=out.types_note
  end
end
-- Every turret of ours that takes ammo and holds under `below` rounds of any ammo (items in its ammo slots), in a
-- radius, an area or on the whole surface (Opus, shift12 13:50: one call for every gun turret under N rounds). Grouped
-- into clusters as the turrets read groups fronts (defense.lua fronts_of); the nearest cluster first from where the
-- character stands, then from where the last ended; inside one, nearest first. Returns the turrets in that order, a
-- line per cluster, how many there take other ammo, and the search used (for nearest_outside). A radius is round the
-- character, or round `position` (Haiku, shift13: a call with position and radius was refused; areas made by hand).
-- A turret under `below` whose ammo slots hold other ammo with no room for this one (a gun turret's one slot holding
-- piercing rounds takes no firearm magazines) is left out and returned apart (Haiku, shift13: three walks to (88,47)
-- gave nothing).
-- The ammo a turret gets when the call names none (A3): the one it holds (the largest stack), else the one it takes
-- that you carry most of (main inventory and gun ammo slots), else nil.
function M.rearm_pick(p,e)
  local okv,inv=pcall(function() return e.get_inventory(defines.inventory[ammo_inventory[e.type]]) end)
  local okc,cont=pcall(function() return inv.get_contents() end)
  local best,bn
  for _,st in ipairs(okv and okc and cont or {}) do if not bn or st.count>bn then best,bn=st.name,st.count end end
  if best then return best end
  local okt,t=pcall(function() return M.turretammo.takes(e.prototype) end)
  for _,n in ipairs(okt and t and t.items or {}) do
    local h=held(p,n)
    if h>0 and (not bn or h>bn) then best,bn=n,h end
  end
  return best
end
function M.rearm_clusters(p,a,ammo,below)
  local base
  if a.radius~=nil then base={position=a.position~=nil and position(a.position) or p.position,radius=integer(a.radius,32,1,256,'radius')}
  elseif a.area~=nil then
    assert(type(a.area)=='table','area must be {left_top={x,y}, right_bottom={x,y}}')
    local lt,rb=a.area.left_top or a.area[1],a.area.right_bottom or a.area[2]
    assert(type(lt)=='table' and type(rb)=='table','area must be {left_top={x,y}, right_bottom={x,y}}')
    lt,rb=position(lt),position(rb)
    assert(lt.x<rb.x and lt.y<rb.y,'area must have left_top above and left of right_bottom')
    base={area={lt,rb}}
  else base={} end
  base.limit=4096
  local list,note=M.find_kinds(p,base,a.types or {'ammo-turret'})
  local rows,other,taken=({}),0,{}
  -- ammo nil (A3, Haiku 01:50: rearm refused turrets holding firearm magazines; a walk stopped on the ammo carried):
  -- each turret gets the ammo it holds, an empty one the ammo it takes that you carry most of (M.rearm_pick).
  local function takes(e)
    local t=ammo_inventory[e.type] and M.turretammo.takes(e.prototype)
    if ammo==nil then return t~=nil and #(t.items or {})>0 end
    for _,n in ipairs(t and t.items or {}) do if n==ammo then return true end end
    return false
  end
  local function rounds(e)
    local inv=e.get_inventory(defines.inventory[ammo_inventory[e.type]])
    return inv and inv.get_item_count() or 0
  end
  local function room(e)
    if ammo==nil then return true end
    local inv=e.get_inventory(defines.inventory[ammo_inventory[e.type]])
    local ok,yes=pcall(function() return inv.can_insert{name=ammo,count=1,quality=a.quality or 'normal'} end)
    return not ok or yes~=false
  end
  for _,e in ipairs(list) do
    if e.valid and ammo_inventory[e.type] then
      if not takes(e) then other=other+1
      else
        local have=rounds(e)
        if have<below then
          if room(e) then rows[#rows+1]={entity=e,position=e.position,have=have} else taken[#taken+1]=e end
          if ammo==nil then rows[#rows].item=M.rearm_pick(p,e) end
        end
      end
    end
  end
  -- Turrets inside a worm's range, within 40 tiles of a spawner or in an area under attack now are left out before
  -- the clusters, and named (round2120a, Haiku shift14 03:58: a surface tour walked into a big worm's range; stock.lua
  -- screen); the nearest you first when there are more than it checks.
  if #rows>64 then table.sort(rows,function(x,y) return distance(p.position,x.position)<distance(p.position,y.position) end) end
  local unsafe
  -- unsafe_goal "moving" (d17 batch35 A3, Haiku): a turret whose only threats move (units, groups, an attack on ours
  -- now) stays in the tour, named in through; one a worm, spawner or turret holds is left out as before.
  local mode,through=M.avoid.mode(a.avoid_enemies),nil
  if a.unsafe_goal=='moving' and mode then
    local kept,pass={},{}
    for i,r in ipairs(rows) do
      local okc,c=false,nil
      if i<=64 then okc,c=pcall(M.avoid.inside,p,r.position,mode) end
      if okc and c and c.moving_only then
        pass[#pass+1]=r
        through=through or {}
        if #through<8 then through[#through+1]=M.avoid.goal_text(r.entity.valid and r.entity.name or 'turret',r.position,c) end
      else kept[#kept+1]=r end
    end
    rows=kept
    rows,unsafe=stock.screen(p,rows,mode,false)
    for _,r in ipairs(pass) do rows[#rows+1]=r end
  else rows,unsafe=stock.screen(p,rows,mode,a.unsafe_goal) end
  local left={}
  for i,g in ipairs(M.defense.fronts_of(rows)) do left[i]=g end
  local order,lines,at=({}),{},p.position
  while #left>0 do
    local bi,bd
    for i,g in ipairs(left) do
      for _,r in ipairs(g) do local d=distance(at,r.position); if not bd or d<bd then bi,bd=i,d end end
    end
    local members={}
    for i,r in ipairs(table.remove(left,bi)) do members[i]=r end
    local n,lo,hi,sx,sy=#members,math.huge,0,0,0
    for _,r in ipairs(members) do lo=math.min(lo,r.have); hi=math.max(hi,r.have); sx=sx+r.position.x; sy=sy+r.position.y end
    lines[#lines+1]=string.format('%d turret%s around (%d,%d), %.0f tiles %s, holding %s round%s',n,n==1 and '' or 's',
      math.floor(sx/n+0.5),math.floor(sy/n+0.5),bd,#lines==0 and 'from you' or 'on from the cluster before',
      lo==hi and tostring(lo) or lo..'-'..hi,(lo==hi and hi==1) and '' or 's')
    while #members>0 do
      local mi,md=1,math.huge
      for i,r in ipairs(members) do local d=distance(at,r.position); if d<md then mi,md=i,d end end
      local r=table.remove(members,mi)
      order[#order+1]=r.entity; at=r.position
      if r.item and r.entity.unit_number then order.item_of=order.item_of or {}; order.item_of[r.entity.unit_number]=r.item end
    end
  end
  order.through=through
  return order,lines,other,note,base,takes,rounds,taken,unsafe
end
-- A rearm tour's default ticks (Haiku, shift13: surface tours of 9 and 7 turrets over about 520 and 820 tiles ended
-- timed_out at 60 s with 4 left): the walk from the character through every stop in order at its running speed, half
-- again for the paths' turns, 1 s a stop and 10 s more; at least 60 s, at most 10 min. A tour takes the first 128
-- stops (stock.lua). Returns the ticks, the walk in tiles, the speed, whether the 10 minutes cut it and the stops.
function M.tour_ticks(p,stops)
  local len,at,n=0,p.position,math.min(#stops,128)
  for i=1,n do local q=stops[i].position; len=len+distance(at,q); at=q end
  local okv,speed=pcall(function() return p.character_running_speed end)
  speed=okv and tonumber(speed) and speed>0.01 and speed or 0.15
  local ticks=math.ceil(len*1.5/speed)+60*n+600
  return math.max(3600,math.min(36000,ticks)),len,speed,ticks>36000,n
end
-- Turrets under below with no room for the ammo (M.rearm_clusters): what each holds, the first 4.
function M.no_room_line(list,ammo,below)
  if #list==0 then return nil end
  local parts={}
  for i=1,math.min(4,#list) do
    local e=list[i]
    local held={}
    local ok,cont=pcall(function() return e.get_inventory(defines.inventory[ammo_inventory[e.type]]).get_contents() end)
    for _,st in ipairs(ok and cont or {}) do held[#held+1]=st.name..'*'..st.count end
    parts[i]=string.format('%s (%g,%g) holds %s',e.name,e.position.x,e.position.y,#held>0 and table.concat(held,' ') or 'nothing')
  end
  return string.format('%d turret%s under %d round%s with no room for %s (%s ammo slots hold other ammo): %s%s',#list,#list==1 and '' or 's',
    below,below==1 and '' or 's',ammo,#list==1 and 'its' or 'their',table.concat(parts,'; '),#list>4 and string.format('; +%d more',#list-4) or '')
end
local function below_target(p,a,radius,wanted,inv_of,item,count)
  local out,found={},0
  -- position: the radius's centre, as the schema says (Muse, d15 06:28: it was read as your own position)
  local list,note=M.find_kinds(p,{position=a.position and position(a.position) or p.position,radius=radius},a.types)
  for _,e in pairs(list) do
    if e.valid and wanted(e) then
      found=found+1
      local inv=inv_of(e)
      if inv and inv.get_item_count{name=item,quality=a.quality or 'normal'}<count then out[#out+1]=e end
    end
  end
  return out,found,note
end
local function start_tour(p,a,op,item,count,targets,ordered,default_ticks,unsafe)
  assert(#targets==0 or held(p,item,a.quality)+crafting_count(p,item)>0,string.format('no %s in inventory%s; %d entities in radius want more',item,op=='rearm' and ' or ammo slots' or '',#targets))
  -- unsafe: rearm's turrets left out before its clusters (M.rearm_clusters), so they are not checked again.
  local action,out=stock.start_tour(p,op,targets,integer(a.ticks,default_ticks or M.tour_ticks(p,targets),1,36000,'ticks'),{item=item,quality=a.quality,count=count,ordered=ordered,
    avoid_enemies=a.avoid_enemies,unsafe_goal=a.unsafe_goal,screened=op=='rearm' or nil})
  if unsafe then action.left_out=unsafe.lines; action.left_out_count=unsafe.count; stock.left_out_into(out,unsafe) end
  if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
  state().active[p.index]=action
  out.until_tick=action.until_tick; out.held=held(p,item,a.quality)
  return out
end
-- A rearm or refuel tour's stop that still holds less than the tour's count: its fuel (refuel) or its rounds of any
-- ammo (rearm).
function M.tour_wants(e,action)
  local inv
  if action.op=='refuel' then inv=fuel_inventory(e)
  else local ok,i=pcall(function() return e.get_inventory(defines.inventory.turret_ammo) end); inv=ok and i or nil end
  if not inv then return false end
  local n=action.op=='refuel' and inv.get_item_count{name=action.item,quality=action.quality or 'normal'} or inv.get_item_count()
  return n<(action.count or 1)
end
-- An alert's entities by its key (C1; pushalerts.lua alert_entities), for refuel and rearm {alert}: refused when no
-- alert of ours has that key now, or none of its entities is still in that state.
function M.alert_targets(p,a,what)
  assert(type(a.alert)=='string','alert is the key an alert line gives (e.g. "no_fuel|nauvis|0,-1")')
  assert(a.position==nil and a.positions==nil and a.radius==nil and a.area==nil and a.surface==nil,'alert names the '..what..' itself: no position, positions, radius, area or surface')
  local list,g=M.pushalerts.alert_entities(p.force,a.alert)
  if not list then error('no alert of ours has the key '..a.alert..' now (it cleared, or the alerts were read again: the newest line gives its key)',0) end
  if #list==0 then error('alert '..a.alert..': none of its '..what..' is still in that state',0) end
  assert(g.surface==p.surface.name,'alert '..a.alert..' is on '..tostring(g.surface)..'; you are on '..p.surface.name)
  return list,g
end
-- Tops every burner in reach up to `count` of one fuel item.
function handlers.refuel(p,a)
  local fuel=a.fuel or 'coal'
  assert(type(fuel)=='string' and prototypes.item[fuel] and (prototypes.item[fuel].fuel_value or 0)>0,'fuel must be a fuel item')
  local count=integer(a.count,10,1,1000,'count')
  -- alert (C1, Haiku): the burners an out-of-fuel alert names, as one walking tour, nearest first
  if a.alert~=nil then
    local list,g=M.alert_targets(p,a,'burners')
    local targets,other={},{}
    for _,e in ipairs(list) do
      if fuel_inventory(e) and M.farm.accepts_fuel(e,fuel) then targets[#targets+1]=e else other[#other+1]=string.format('%s (%g,%g)',e.name,e.position.x,e.position.y) end
    end
    table.sort(targets,function(x,y) return distance(p.position,x.position)<distance(p.position,y.position) end)
    local out=start_tour(p,a,'refuel',fuel,count,targets)
    out.alert=string.format('%d burner%s of alert %s%s%s',#targets,#targets==1 and '' or 's',a.alert,
      (g.n or 0)>#list and string.format(' (the alert counts %d; it keeps the first 128 found: refuel by it again for the rest)',g.n) or '',#other>0 and string.format('; %d burn another fuel than %s: %s',#other,fuel,table.concat(other,', ',1,math.min(4,#other))) or '')
    return out
  end
  if a.from~=nil or a.area~=nil or a.feed_chests~=nil then return M.fuelround.start(p,a,fuel,count) end
  if a.radius~=nil then
    assert(a.positions==nil,'give radius or positions, not both')
    local radius=integer(a.radius,32,1,256,'radius')
    local function wanted(e) return fuel_inventory(e)~=nil and pcall(inventory,e,'fuel') and M.farm.accepts_fuel(e,fuel) end
    local targets,found,note=below_target(p,a,radius,wanted,fuel_inventory,fuel,count)
    local out=start_tour(p,a,'refuel',fuel,count,targets)
    out.types_note=note
    if #targets==0 then
      -- Nothing below count in it: how many there hold enough, and the nearest one outside it that is below.
      out.nothing=found>0 and string.format('the %d burner%s in radius %d that burn %s hold %d %s or more',found,found==1 and '' or 's',radius,fuel,count,fuel)
        or string.format('no burner%s in radius %d burns %s',a.types and ' of those types' or '',radius,fuel)
      local centre=a.position and position(a.position) or p.position
      out.nearest_outside=M.nearest_outside(p,a.types,function(e) return distance(centre,e.position)<=radius end,function(e)
        local inv=wanted(e) and fuel_inventory(e)
        return inv and inv.get_item_count{name=fuel,quality=a.quality or 'normal'}<count
      end,string.format('burner below %d %s',count,fuel))
      M.tour_note(p,out)
    end
    return out
  end
  -- Burners out of reach within 32 tiles (autowalk.lua): the tour radius walks, over these burners; the reply says so.
  if a.positions~=nil and a.walk~=false and not a.walked then
    local far,n,ents=M.unreached(p,a)
    local worst=far and M.autowalk.wanted('refuel',a,far)
    if worst then
      for _,e in ipairs(ents) do
        if fuel_inventory(e) and not M.farm.accepts_fuel(e,fuel) then
          local cats={}
          for k in pairs(M.farm.fuel_categories(e) or {}) do cats[#cats+1]=k end
          table.sort(cats)
          error(string.format('%s at (%g,%g) burns %s fuel, not %s (%s)',e.name,e.position.x,e.position.y,table.concat(cats,'/'),fuel,
            tostring(prototypes.item[fuel].fuel_category)),0)
        end
      end
      local out=start_tour(p,a,'refuel',fuel,count,ents)
      out.walking=M.autowalk.line(far,n,worst)
      return out
    end
  end
  assert(a.ticks==nil,'ticks applies with radius or walk')
  local targets=reachable(p,a,function(e) return fuel_inventory(e)~=nil and pcall(inventory,e,'fuel') and M.farm.accepts_fuel(e,fuel) end)
  -- A burner at a given position that burns another fuel category says so (a biochamber burns nutrients).
  for _,t in ipairs(a.positions and targets or {}) do
    local ok,e=pcall(entity,p,{position=t.position})
    if ok and e and fuel_inventory(e) and not M.farm.accepts_fuel(e,fuel) then
      local cats={}
      for k in pairs(M.farm.fuel_categories(e) or {}) do cats[#cats+1]=k end
      table.sort(cats)
      error(string.format('%s at (%g,%g) burns %s fuel, not %s (%s)',e.name,e.position.x,e.position.y,table.concat(cats,'/'),fuel,
        tostring(prototypes.item[fuel].fuel_category)),0)
    end
  end
  local args={direction='to_entity',item=fuel,inventory='fuel',count=count,up_to=count,quality=a.quality,fail_short=true}
  local waiting=await_feed(p,'refuel',a,fuel,shortfall(p,args,targets))
  if waiting then return waiting end
  return transfer_batch(p,args,targets,true)
end
-- Tops every turret in reach (or at positions) up to `count` of one ammo item.
-- rearm {retry_when_clear: true} (A2, Haiku: three rearms refused for enemies near the turrets, retried by hand): a
-- refusal for passing enemies only (an attack, units or a group seen now; none for a worm or spawner) waits until no
-- enemy unit is within 48 tiles of the first place held (wait_until units_clear, retry_ticks, default 5 min), then
-- rearms again, at most 6 times.
function handlers.rearm(p,a)
  if a.retry_when_clear==nil then return M.rearm_now(p,a) end
  assert(type(a.retry_when_clear)=='boolean','retry_when_clear must be true or false')
  local rest={}
  for k,v in pairs(a) do if k~='retry_when_clear' and k~='retry_ticks' and k~='retries' then rest[k]=v end end
  if not a.retry_when_clear then return M.rearm_now(p,rest) end
  local tries=integer(a.retries,0,0,6,'retries')
  local ticks=integer(a.retry_ticks,18000,600,54000,'retry_ticks')
  stock.last_refusal=nil
  local ok,out=pcall(M.rearm_now,p,rest)
  if ok then
    -- (d17 batch34 C2, Haiku: a resupply tour skipped turrets with enemies near) turrets the tour left out for passing
    -- enemies: once it ends, rearm {positions: them, retry_when_clear: true} (refused while they are there, it waits
    -- until they clear, as above)
    local lr=stock.last_refusal
    local now=state().active[p.index]
    if lr and lr.tick==game.tick and (lr.passing or 0)>0 and lr.passing_at and #lr.passing_at>0 and now and tries<6 and type(out)=='table' then
      local again={}
      for _,k in ipairs({'ammo','count','below','quality','avoid_enemies','partial'}) do again[k]=rest[k] end
      again.positions=lr.passing_at; again.walk=true; again.retry_when_clear=true; again.retry_ticks=ticks; again.retries=tries+1
      now.then_call={action='rearm',args=again}
      now.then_after={topped_up=true,nothing_to_do=true,timed_out=true}
      out.left_out_retry=string.format('%d turret%s left out for passing enemies: once this tour ends, rearm goes to them (retry_when_clear: it waits until no enemy unit is within 48 tiles, then rearms them; try %d of 6)',
        #lr.passing_at,#lr.passing_at==1 and '' or 's',tries+1)
    end
    return out
  end
  local r=stock.last_refusal
  if not (r and r.tick==game.tick and (r.passing or 0)>0 and (r.staying or 0)==0 and r.at) or tries>=6 then error(out,0) end
  local w=handlers.wait_until(p,{['until']='units_clear',position=r.at,radius=48,timeout=ticks})
  local now=state().active[p.index]
  -- no unit there now (an area under attack counts 30 s past its last hit: d17 batch21 D2): 30 s, then again
  if not now then w=handlers.wait_ticks(p,{ticks=1800}); now=state().active[p.index]; w.cleared='no enemy unit within 48 tiles now; the area under attack counts 30 s past its last hit' end
  if now then
    local again={}
    for k,v in pairs(rest) do again[k]=v end
    again.retry_when_clear=true; again.retry_ticks=ticks; again.retries=tries+1
    now.then_call={action='rearm',args=again}
  end
  w.retry=string.format('refused for passing enemies only: %s; waits until no enemy unit is within 48 tiles of (%g,%g) (at most %d s), then rearms again (try %d of 6)',
    reason(out),r.at.x,r.at.y,math.floor(ticks/60),tries+1)
  return w
end
-- rearm {from: {position, count?}} (d17 batch34 C2, Haiku, about 10 times in 30 minutes: take ammo from a chest, then the
-- tour): a transfer of the ammo from that chest to you (walking to it as transfer does), then the rearm with the other
-- arguments (retry_when_clear and all) once it has taken some; a transfer in reach runs the rearm at once.
M.rearm_tour=handlers.rearm
function handlers.rearm(p,a)
  if a.from==nil then return M.rearm_tour(p,a) end
  local f=a.from
  assert(type(f)=='table' and (f.position~=nil or f.x~=nil or f[1]~=nil),'from is {position: {x,y}, count?}: the chest to take the ammo from first')
  local rest={}
  for k,v in pairs(a) do if k~='from' then rest[k]=v end end
  assert(not rest.dry_run,'from and dry_run: a dry run of the tour alone (without from) says what it would need')
  local ammo=rest.ammo or 'firearm-magazine'
  local take=handlers.transfer(p,{position=f.position or f,direction='to_player',item=ammo,count=integer(f.count,200,1,10000,'from.count'),walk=true})
  local now=state().active[p.index]
  if now then
    now.then_call={action='rearm',args=rest}
    now.then_after={transferred=true,collected=true,topped_up=true}
    if type(take)=='table' then take.then_rearm='the rearm tour starts once the take has ended with ammo taken (last.then_call; its reply in last.then_result)' end
    return take
  end
  local out=handlers.rearm(p,rest)
  if type(out)=='table' then out.took_first=take end
  return out
end
function M.rearm_now(p,a)
  -- no ammo named: each turret its own (A3; M.rearm_pick)
  local own=a.ammo==nil
  local ammo=a.ammo or 'firearm-magazine'
  assert(type(ammo)=='string' and prototypes.item[ammo] and prototypes.item[ammo].type=='ammo','ammo must be an ammo item')
  local count=integer(a.count,10,1,1000,'count')
  -- alert (C1, Haiku): the turrets an out-of-ammo alert names, as an area tour over the box round them (the turrets in
  -- it under below get their ammo)
  if a.alert~=nil then
    local list=M.alert_targets(p,a,'turrets')
    local x0,y0,x1,y1=math.huge,math.huge,-math.huge,-math.huge
    for _,e in ipairs(list) do local q=e.position; x0,y0,x1,y1=math.min(x0,q.x),math.min(y0,q.y),math.max(x1,q.x),math.max(y1,q.y) end
    local b={}
    for k,v in pairs(a) do if k~='alert' then b[k]=v end end
    b.area={left_top={x=math.floor(x0)-2,y=math.floor(y0)-2},right_bottom={x=math.ceil(x1)+2,y=math.ceil(y1)+2}}
    b.below=b.below or 1
    local out=handlers.rearm(p,b)
    if type(out)=='table' then out.alert=string.format('%d turret%s of alert %s, in the area (%d,%d)-(%d,%d)',#list,#list==1 and '' or 's',a.alert,b.area.left_top.x,b.area.left_top.y,b.area.right_bottom.x,b.area.right_bottom.y) end
    return out
  end
  -- below on every form (Haiku, shift13): turrets holding fewer rounds than this (any ammo, in items) get topped up to
  -- count (at least below); the tours default it to count.
  local below=a.below~=nil and integer(a.below,nil,1,1000,'below') or nil
  -- position: with radius, the radius's centre; alone, the turret there, as positions with one entry.
  if a.position~=nil then
    assert(a.positions==nil,'give position or positions, not both')
    assert(a.area==nil and a.surface==nil,'position goes with radius (its centre), or alone (the turret there)')
    if a.radius==nil then
      local b={}
      for k,v in pairs(a) do b[k]=v end
      b.positions={a.position}; b.position=nil
      a=b
    end
  end
  if a.radius~=nil or a.area~=nil or a.surface~=nil then
    assert(a.positions==nil,'give radius, area or surface, or positions')
    assert((a.radius~=nil and 1 or 0)+(a.area~=nil and 1 or 0)+(a.surface~=nil and 1 or 0)==1,'give one of radius, area or surface')
    assert(a.surface==nil or a.surface==true or a.surface==p.surface.name,
      'surface: true (or your surface\'s name) rearms every turret on your surface; a rearm walks, so only your own')
    below=below or count
    local target=math.max(count,below)
    local order,lines,other,note,base,takes,rounds,taken,unsafe=M.rearm_clusters(p,a,not own and ammo or nil,below)
    -- own ammo: the turrets you carry none of their ammo for are named and left out; the tour's item is the most used
    local item_of=order.item_of or {}
    local through=order.through
    order.item_of=nil; order.through=nil
    local none_held,by_item={},{}
    local none_ents
    if own then
      local kept={}
      for _,e in ipairs(order) do
        local it=item_of[e.unit_number]
        if it and held(p,it)+crafting_count(p,it)>0 then kept[#kept+1]=e; by_item[it]=(by_item[it] or 0)+1
        else none_held[#none_held+1]=string.format('%s (%g,%g)%s',e.name,e.position.x,e.position.y,it and ' wants '..it or ' is empty'); none_ents=none_ents or {}; none_ents[#none_ents+1]={e=e,it=it} end
      end
      order=kept
      local most
      for it,n in pairs(by_item) do if not most or n>by_item[most] then most=it end end
      ammo=most or ammo
    end
    if #order==0 and unsafe then
      error(string.format('every turret under %d round%s of %s there lies in enemy reach the map shows: %s%s%s: unsafe_goal: true to go anyway, avoid_enemies: false for no check',
        below,below==1 and '' or 's',own and 'the ammo each holds' or ammo,table.concat(unsafe.lines,'; '),unsafe.count>#unsafe.lines and string.format('; +%d more',unsafe.count-#unsafe.lines) or '',stock.blocker_text(unsafe)),0)
    end
    -- (d17 batch22 C2, Haiku) the magazines the stops need, by ammo, against what you carry and the hand-craft queue
    -- brings: the stops in the tour's order that this completes, the turrets left short; a tour that cannot finish is
    -- refused unless partial: true
    assert(a.partial==nil or type(a.partial)=='boolean','partial must be true or false')
    local need_by,have_by,done_stops,short_turrets={},{},0,{}
    do
      local left={}
      local stopped=false
      for _,e in ipairs(order) do
        local it=item_of[e.unit_number] or ammo
        local okn,have=pcall(function() return e.get_inventory(defines.inventory.turret_ammo).get_item_count() end)
        local want=math.max(0,target-(okn and have or 0))
        need_by[it]=(need_by[it] or 0)+want
        if left[it]==nil then left[it]=held(p,it)+crafting_count(p,it); have_by[it]=left[it] end
        if not stopped and left[it]>=want then left[it]=left[it]-want; done_stops=done_stops+1
        else
          stopped=true
          if #short_turrets<8 then short_turrets[#short_turrets+1]=string.format('%s (%g,%g) wants %d %s',e.name,e.position.x,e.position.y,want,it) end
        end
      end
    end
    local need_parts,lacking={},false
    for it,n in pairs(need_by) do
      need_parts[#need_parts+1]=string.format('%s %d (you carry %d)',it,n,have_by[it] or 0)
      if n>(have_by[it] or 0) then lacking=true end
    end
    table.sort(need_parts)
    local magazines=#need_parts>0 and string.format('the %d stop%s need %s to reach %d each; what you carry completes %d of them in the tour\'s order%s',
      #order,#order==1 and '' or 's',table.concat(need_parts,', '),target,done_stops,
      #short_turrets>0 and '; left short: '..table.concat(short_turrets,'; ')..(#order-done_stops>#short_turrets and string.format(' +%d more',#order-done_stops-#short_turrets) or '') or '') or nil
    if lacking and not a.partial and not a.dry_run_plan then
      error('not walked: '..magazines..'; partial: true tours anyway (it stops giving where you run out)',0)
    end
    -- the dry run's plan (d17 batch14 A4, Muse: auditing wall ammo without walking): the stops as the tour would take
    -- them, each turret's rounds and the ammo it would get, and what is left out; nothing walks. (batch24->25 A1, Haiku:
    -- each turret's ammunition by name, in the real call's reply too, before the walk.)
    local function holds(e)
      local parts={}
      for _,c in ipairs(select(2,pcall(function() return e.get_inventory(defines.inventory.turret_ammo).get_contents() end)) or {}) do
        if type(c)=='table' and c.name then parts[#parts+1]=c.name..'*'..c.count end
      end
      return #parts>0 and table.concat(parts,' ') or 'no ammo'
    end
    local rows={}
    for i,e in ipairs(order) do
      if i>64 then break end
      rows[#rows+1]=string.format('%s (%g,%g): holds %s, gets %s',e.name,e.position.x,e.position.y,holds(e),(item_of[e.unit_number] or ammo))
    end
    -- (the turrets under below whose ammo you carry none of: listed too, for an audit)
    for _,x in ipairs(none_ents or {}) do
      if #rows>=64 then break end
      rows[#rows+1]=string.format('%s (%g,%g): holds %s, wants %s: you carry none (not a stop)',x.e.name,x.e.position.x,x.e.position.y,holds(x.e),x.it or 'ammo')
    end
    if a.dry_run_plan then
      return {plan=order,turrets=rows,turrets_more=#order>64 and #order-64 or nil,below=below,count=target,left_out=unsafe and unsafe.lines or nil,through=through,
        none_held=#none_held>0 and none_held or nil,other_ammo=other,magazines=magazines,completes=done_stops}
    end
    local ticks,len,speed,capped,stops
    if a.ticks==nil then ticks,len,speed,capped,stops=M.tour_ticks(p,order) end
    local out=start_tour(p,a,'rearm',ammo,target,order,true,ticks,unsafe)
    if type(out)=='table' and through then out.through=through end
    if own then
      local act=state().active[p.index]
      if act then act.item_of=item_of end
      local parts={}
      for it,n in pairs(by_item) do parts[#parts+1]=n..' '..it end
      table.sort(parts)
      out.ammo_each=#parts>0 and 'each turret its own ammo: '..table.concat(parts,', ') or nil
      out.none_held=#none_held>0 and string.format('%d turret%s left out, none of %s ammo carried: %s%s',#none_held,#none_held==1 and '' or 's',#none_held==1 and 'its' or 'their',
        table.concat(none_held,'; ',1,math.min(6,#none_held)),#none_held>6 and ' ...' or '') or nil
      out.item=nil
    end
    out.below=below; out.count=target; out.types_note=note
    out.turrets=#rows>0 and rows or nil
    out.magazines=magazines; out.partial=lacking and string.format('partial: %d of %d stops get their full count with what you carry',done_stops,#order) or nil
    if ticks then
      out.ticks=ticks
      out.ticks_note=string.format('the default for this tour: %.0f tiles from you through %d turret%s at your running speed (%.1f tiles/s), half again for turns, 1 s a turret and 10 s%s',
        len,stops,stops==1 and '' or 's',speed*60,capped and '; cut to 10 min' or ticks==3600 and '; at least 60 s' or '')
    end
    out.clusters=#lines>0 and {} or nil
    for i=1,math.min(8,#lines) do out.clusters[i]=lines[i] end
    out.clusters_more=#lines>8 and #lines-8 or nil
    out.other_ammo=other>0 and string.format('%d turret%s there take%s other ammo than %s',other,other==1 and '' or 's',other==1 and 's' or '',ammo) or nil
    out.no_room=M.no_room_line(taken,ammo,below)
    out.turrets_skipped=out.no_room  -- (batch32 A2) on the warning line too
    do local act=state().active[p.index]; if act and out.no_room then act.turrets_skipped=out.no_room end end
    if #order==0 then
      out.nothing=own and (#none_held>0 and string.format('every turret there under %d round%s wants ammo you do not carry (none_held)',below,below==1 and '' or 's')
          or string.format('no turret there holds under %d round%s',below,below==1 and '' or 's'))
        or string.format('no turret there that takes %s holds under %d round%s%s',ammo,below,below==1 and '' or 's',#taken>0 and ' with room for it' or '')
      if a.surface==nil then
        local inside=base.radius and function(e) return distance(base.position,e.position)<=base.radius end
          or function(e) local q,b=e.position,base.area; return q.x>=b[1].x and q.x<=b[2].x and q.y>=b[1].y and q.y<=b[2].y end
        out.nearest_outside=M.nearest_outside(p,a.types or {'ammo-turret'},inside,function(e) return takes(e) and rounds(e)<below end,
          string.format('turret under %d %s',below,ammo))
      end
      M.tour_note(p,out)
    end
    return out
  end
  -- Turrets out of reach within 32 tiles (autowalk.lua; Astra, shift12: 7 turrets 14.8 tiles off refused at once):
  -- the tour radius walks, over these turrets; the ones holding below or more are left (held_enough).
  local far,n,ents
  if a.positions~=nil and a.walk~=false and not a.walked then far,n,ents=M.unreached(p,a) end
  if far then
    -- (the ones holding below or more stay as they are: walked to only for those that want ammo)
    local rows,enough,wanted={},{},{}
    -- (batch32 A2, Haiku: a gun on piercing rounds took +0 firearm magazines and the walk read topped_up) a turret
    -- whose ammo slots hold other ammo with no room for this one, or a ghost, is skipped and named; the rest are served
    local skipped={}
    for _,e in ipairs(ents) do
      local inv=ammo_inventory[e.type] and select(2,pcall(function() return e.get_inventory(defines.inventory[ammo_inventory[e.type]]) end))
      local it=own and M.rearm_pick(p,e) or ammo
      local okr,fits=pcall(function() return inv.can_insert{name=it,count=1,quality=a.quality or 'normal'} end)
      local okn,have=pcall(function() return inv.get_item_count() end)
      if type(inv)~='table' and type(inv)~='userdata' then
        skipped[#skipped+1]=string.format('%s (%g,%g): %s',e.name,e.position.x,e.position.y,e.type=='entity-ghost' and 'a ghost (not built: nothing to load)' or 'no ammo slots')
      elseif okr and fits==false then
        local parts={}
        for _,c in ipairs(select(2,pcall(function() return inv.get_contents() end)) or {}) do if type(c)=='table' and c.name then parts[#parts+1]=c.name..'*'..c.count end end
        skipped[#skipped+1]=string.format('%s (%g,%g): holds %s, no room for %s',e.name,e.position.x,e.position.y,#parts>0 and table.concat(parts,' ') or 'other ammo',it)
      elseif below and okn and have>=below then enough[#enough+1]=string.format('%s (%g,%g) %d',e.name,e.position.x,e.position.y,have)
      else rows[#rows+1]={entity=e,position=e.position}; wanted[e]=true end
    end
    local skipped_line=#skipped>0 and string.format('%d of %d turret%s skipped: %s%s',#skipped,#ents,#ents==1 and '' or 's',
      table.concat(skipped,'; ',1,math.min(6,#skipped)),#skipped>6 and string.format('; +%d more',#skipped-6) or '') or nil
    if #rows==0 and skipped_line then
      return {transferred=0,moved=0,turrets_skipped=skipped_line,nothing='no turret there to serve: '..skipped_line,held_enough=#enough>0 and table.concat(enough,', ') or nil}
    end
    local needed={}
    for _,f in ipairs(far) do if wanted[f.entity] then needed[#needed+1]=f end end
    local worst=#needed>0 and M.autowalk.wanted('rearm',a,needed)
    if worst then
      local held_enough=#enough>0 and string.format('%d turret%s hold%s %d round%s or more: %s%s',#enough,#enough==1 and '' or 's',#enough==1 and 's' or '',
        below,below==1 and '' or 's',table.concat(enough,', ',1,math.min(8,#enough)),#enough>8 and string.format(', +%d more',#enough-8) or '') or nil
      -- Inside the enemy reach the map shows: left out and named (as the radius tour's clusters).
      local kept,unsafe=stock.screen(p,rows,M.avoid.mode(a.avoid_enemies),a.unsafe_goal)
      if #kept==0 and unsafe then
        error(string.format('every turret there lies in enemy reach the map shows: %s%s%s: unsafe_goal: true to go anyway, avoid_enemies: false for no check',
          table.concat(unsafe.lines,'; '),unsafe.count>#unsafe.lines and string.format('; +%d more',unsafe.count-#unsafe.lines) or '',stock.blocker_text(unsafe)),0)
      end
      local order={}
      for i,r in ipairs(kept) do order[i]=r.entity end
      local out=start_tour(p,a,'rearm',ammo,below and math.max(count,below) or count,order,false,nil,unsafe)
      out.walking=M.autowalk.line(needed,#rows,worst); out.below=below; out.held_enough=held_enough
      out.turrets_skipped=skipped_line
      local act=state().active[p.index]
      if act and skipped_line then act.turrets_skipped=skipped_line end
      return out
    end
  end
  assert(a.ticks==nil,'ticks applies with radius, area, surface or walk')
  local target=below and math.max(count,below) or count
  local args={direction='to_entity',item=ammo,count=target,up_to=target,quality=a.quality,positions=a.positions,types=a.types or {'ammo-turret'},fail_short=true}
  assert(type(args.types)=='table' and #args.types>=1,'types requires entity types')
  local targets=reachable(p,args,function(e) return ammo_inventory[e.type]~=nil end)
  -- below: a turret holding that many rounds or more (any ammo) is left as it is, and named.
  local enough
  if below then
    local keep,list={},{}
    for _,t in ipairs(targets) do
      -- Read as a player reads a turret's ammo by sight (the transfer still needs reach).
      local okq,e=pcall(function()
        return t.entity or entity(p,{position=t.position,name=t.position.name,unit_number=t.position.unit_number},true)
      end)
      local okn,n=pcall(function() return e.get_inventory(defines.inventory[ammo_inventory[e.type]]).get_item_count() end)
      if okq and okn and n>=below then list[#list+1]=string.format('%s (%g,%g) %d',e.name,e.position.x,e.position.y,n)
      else keep[#keep+1]=t end
    end
    targets=keep
    if #list>0 then
      enough=string.format('%d turret%s hold%s %d round%s or more: %s%s',#list,#list==1 and '' or 's',#list==1 and 's' or '',below,below==1 and '' or 's',
        table.concat(list,', ',1,math.min(8,#list)),#list>8 and string.format(', +%d more',#list-8) or '')
    end
    if #targets==0 then return {transferred=0,moved=0,below=below,held_enough=enough,nothing=string.format('no turret there holds under %d round%s',below,below==1 and '' or 's')} end
  end
  -- A3 (Haiku: rearm refused two turrets holding firearm magazines): a turret whose ammo slots hold other ammo with
  -- no room for this one is left out and named; with no ammo named, each turret gets its own (M.rearm_pick).
  local groups,order_items,other={},{},{}
  for _,t in ipairs(targets) do
    local okq,e=pcall(function() return t.entity or entity(p,{position=t.position,name=t.position.name,unit_number=t.position.unit_number},true) end)
    local it=ammo
    if okq and e and own then it=M.rearm_pick(p,e) or ammo end
    local inv=okq and e and pcall(function() return e.get_inventory(defines.inventory[ammo_inventory[e.type]]) end) and e.get_inventory(defines.inventory[ammo_inventory[e.type]])
    local okr,fits=pcall(function() return inv.can_insert{name=it,count=1,quality=a.quality or 'normal'} end)
    local room=not inv or not okr or fits~=false
    if not room then
      local holds={}
      local okc,cont=pcall(function() return inv.get_contents() end)
      for _,st in ipairs(okc and cont or {}) do holds[#holds+1]=st.name..'*'..st.count end
      other[#other+1]=string.format('%s (%g,%g) holds %s',e.name,e.position.x,e.position.y,table.concat(holds,' '))
    else
      if not groups[it] then groups[it]={}; order_items[#order_items+1]=it end
      table.insert(groups[it],t)
    end
  end
  local other_line=#other>0 and string.format('%d turret%s left out, %s ammo slots hold other ammo with no room for %s: %s',#other,#other==1 and '' or 's',
    #other==1 and 'its' or 'their',own and 'the one carried' or ammo,table.concat(other,'; ',1,math.min(6,#other))) or nil
  if #order_items==0 then return {transferred=0,moved=0,below=below,held_enough=enough,other_ammo=other_line,turrets_skipped=other_line,nothing=other_line or 'no turret to rearm'} end
  local out
  for _,it in ipairs(order_items) do
    local ga={}
    for k,v in pairs(args) do ga[k]=v end
    ga.item=it
    local waiting=await_feed(p,'rearm',a,it,shortfall(p,ga,groups[it]))
    if waiting then return waiting end
    local o=transfer_batch(p,ga,groups[it],true)
    if not out then out=o
    elseif type(o)=='table' then
      out.transferred=(out.transferred or 0)+(o.transferred or 0)
      for _,row in ipairs(o.entities or {}) do out.entities=out.entities or {}; out.entities[#out.entities+1]=row end
    end
  end
  if type(out)=='table' then
    out.other_ammo=other_line
    out.turrets_skipped=other_line  -- (batch32 A2) on the warning line too
    if #order_items>1 then out.ammo_each='each turret its own ammo: '..table.concat(order_items,', ') end
    -- (batch28 C3, Haiku) a line per turret: what it got and what it holds now
    local lines={}
    for _,row in ipairs(out.entities or {}) do
      local okq,e=pcall(entity,p,{position=row.position},true)
      if okq and e then
        local okh,h=pcall(function() return e.get_inventory(defines.inventory[ammo_inventory[e.type]]).get_item_count() end)
        lines[#lines+1]=string.format('%s (%g,%g): +%d, holds %s now%s',e.name,e.position.x,e.position.y,row.moved or 0,okh and tostring(h) or '?',row.full and ' (full)' or '')
      end
    end
    out.turret_lines=#lines>0 and lines or nil
  end
  if below and type(out)=='table' then out.below=below; out.held_enough=enough end
  return out
end
-- up_to=true (courier steps; Grok, Luna, Sonnet and Muse asked in shift08): move what there is, min(count, what the
-- source holds, room), and say how far short it fell instead of failing. n: targets the count applies to.
local function short_facts(out,a,n)
  local moved=out.transferred or 0
  out.moved=moved
  local asked=a.count~=nil and integer(a.count,1,1,10000,'count')*n or (a.direction=='to_entity' and n or nil)
  if a.budget then asked=math.min(asked or a.budget.cap,a.budget.cap) end
  local full=out.inventory_full or out.entity_full
  for _,row in ipairs(out.entities or {}) do full=full or row.full end
  if (asked and moved>=asked) or (not asked and moved>0 and not full) then return out end
  local reason
  if full then reason='target_full'
  elseif out.none_held and moved==0 then reason='none_held'
  elseif a.direction=='to_player' and moved==0 then reason='source_empty'
  else reason='source_short' end
  out.short={asked=asked or 'all',moved=moved,reason=reason,why=reason=='target_full' and M.full_why(out) or nil}
  return out
end
M.short_facts=short_facts
-- A give the target could not take all of (Sol, 22:08: a delivery of 0 read as ok): the target and what fills it.
function M.full_why(out)
  local f=out.entity_full
  if f and f.slots then return f.slots end
  for _,row in ipairs(out.entities or {}) do
    if row.why then return string.format('(%g,%g) %s',row.position.x,row.position.y,row.why) end
  end
  return nil
end
-- transfer's own give (not rearm, refuel, feed): moved short of the count because the target is full is a short line.
function M.give_short(out,a,n)
  if a.direction~='to_entity' or out.short then return out end
  local full=out.entity_full
  for _,row in ipairs(out.entities or {}) do full=full or row.full end
  if not full then return out end
  local asked=a.count~=nil and integer(a.count,1,1,10000,'count')*n or nil
  out.short={asked=asked or (out.entity_full and out.entity_full.requested) or 'all',moved=out.transferred or 0,reason='target_full',why=M.full_why(out)}
  return out
end
-- Empties the outputs of furnaces and assemblers in reach. Plain chests are
-- usually feed chests the player stocked for machines, so they are only
-- emptied when named by position, listed in types, or with chests=true.
local collect_types={plain={'furnace','assembling-machine'},chests={'furnace','assembling-machine','container','logistic-container'}}
-- recover (Opus, shift12 15:20): walk to your own character corpses on this surface, nearest first, and take
-- everything from each, as a player empties a corpse (it goes once empty); one timed call, the tour collect walk=true
-- makes. A bot's corpses are the ones its deaths left (bots.lua note_corpse: no player is named on them); a player's
-- carry its index. Corpses on another surface are listed, not walked to. The walk keeps out of the enemy reach the map
-- shows as move_to's does (avoid_enemies), and a corpse inside a weapon's reach is left out unless unsafe_goal.
function handlers.recover(p,a)
  assert(a.unsafe_goal==nil or type(a.unsafe_goal)=='boolean','unsafe_goal must be true or false')
  assert(a.ignore_groups==nil or type(a.ignore_groups)=='boolean','ignore_groups must be true or false')
  local group_radius=a.group_radius~=nil and integer(a.group_radius,48,8,160,'group_radius (8..160 tiles)') or 48
  assert(a.dry_run==nil or type(a.dry_run)=='boolean','dry_run must be true or false')
  local mode=M.avoid.mode(a.avoid_enemies)
  local ticks=integer(a.ticks,3600,1,36000,'ticks')
  local list
  if M.bots.is(p) then list=M.bots.corpses(p.index)
  else
    list={}
    for _,k in pairs(p.surface.find_entities_filtered{type='character-corpse',limit=64}) do
      if k.character_corpse_player_index==p.index then
        list[#list+1]={entity=k,surface=p.surface.name,position=k.position,tick=k.character_corpse_tick_of_death}
      end
    end
  end
  -- corpse (one corpse: its position, or unit_number) and stop_after (the nearest N) (D6, Muse 3x: a recover walked on
  -- to a second corpse across the map into enemies).
  local stop_after=a.stop_after~=nil and integer(a.stop_after,1,1,5,'stop_after (1..5 corpses, the nearest first)') or nil
  if a.corpse~=nil then
    local want=type(a.corpse)=='number' and {unit_number=a.corpse} or {pos=position(a.corpse)}
    local kept,named={},{}
    for _,c in ipairs(list) do
      local okp,un=pcall(function() return c.entity.unit_number end)
      named[#named+1]=string.format('(%.1f,%.1f) on %s',c.position.x,c.position.y,c.surface)
      if want.unit_number and okp and un==want.unit_number or want.pos and c.surface==p.surface.name and distance(c.position,want.pos)<=2 then kept[#kept+1]=c end
    end
    if #kept==0 then error('corpse: none of yours there; yours: '..(#named>0 and table.concat(named,'; ') or 'none'),0) end
    list={kept[1]}
  end
  -- (d17 batch15 A1, Muse: a dry run with corpse {x,y} listed another corpse) the dry run reads the corpse chosen
  if a.dry_run then return M.recover_dry(p,a,list,mode) end
  local here,rows,elsewhere,left_out,unsafe={},{},{},{},{}
  for _,c in ipairs(list) do
    local okc,n=pcall(function() return c.entity.get_inventory(defines.inventory.character_corpse).get_item_count() end)
    local ago=math.floor((game.tick-(c.tick or game.tick))/60)
    local held=okc and n or 0
    local line=string.format('(%.1f,%.1f) on %s: died %dm%02ds ago, holds %d item%s',c.position.x,c.position.y,c.surface,math.floor(ago/60),ago%60,held,held==1 and '' or 's')
    -- what killed it and whether it is there now (A4)
    local okk,kf=pcall(M.killer_facts,c.surface,c.position,c.tick)
    if okk and kf.killed_by then line=line..'; killed by '..kf.killed_by..(kf.killer_now and '; '..kf.killer_now or '') end
    if okk and kf.units_near and c.surface==p.surface.name then line=line..'; '..kf.units_near end
    if c.surface~=p.surface.name then elsewhere[#elsewhere+1]=line
    else
      -- As move_to's goal check (avoid.lua): a corpse inside a worm's range (with avoid_enemies true, a spawner's units' sight too).
      local chk=mode and M.avoid.goal_check(p,p.position,c.position,mode)
      local text=chk and M.avoid.goal_text('the corpse',c.position,chk)
      -- Enemy groups our force sees round it (batch24 C2, Haiku): named before the walk; one within group_radius keeps
      -- the corpse out unless ignore_groups.
      local okg,groups=pcall(threat.groups_near,p.force,p.surface,c.position,160)
      groups=okg and groups or {}
      if #groups>0 then line=line..'; '..threat.groups_line(groups) end
      local close=groups[1] and groups[1].distance<=group_radius and groups[1] or nil
      if close and not a.ignore_groups then
        left_out[#left_out+1]=line..string.format('; a group of %d is %d tiles from it (group_radius %d): ignore_groups: true goes anyway',close.size,close.distance,group_radius)
      elseif chk and not a.unsafe_goal then left_out[#left_out+1]=line..'; '..text..M.avoid.spot_text(c.position,chk,mode)
      else
        if chk then unsafe[#unsafe+1]=text..' (unsafe_goal)' end
        here[#here+1]=c.entity; rows[#rows+1]=line
      end
    end
  end
  if #here==0 then
    if #left_out>0 then error('no corpse of yours on '..p.surface.name..' outside the enemy reach the map shows: '..table.concat(left_out,'; ')..': unsafe_goal: true to go anyway',0) end
    error('no corpse of yours on '..p.surface.name..(#elsewhere>0 and ('; elsewhere: '..table.concat(elsewhere,'; ')) or ''),0)
  end
  local not_walked
  if stop_after and #here>stop_after then
    local order={}
    for i,e in ipairs(here) do order[i]={e=e,row=rows[i],d=distance(p.position,e.position)} end
    table.sort(order,function(x,y) return x.d<y.d end)
    here,rows,not_walked={},{},{}
    for i,o in ipairs(order) do
      if i<=stop_after then here[#here+1]=o.e; rows[#rows+1]=o.row else not_walked[#not_walked+1]=o.row end
    end
  end
  -- (unsafe_goal: the leg check walks to a corpse the call let in; screened: the corpses were checked above)
  local action,out=stock.start_tour(p,'transfer',here,ticks,
    {transfer={direction='to_player'},rows={},items={},collect=true,recover=true,avoid_mode=mode,unsafe_goal=a.unsafe_goal,screened=true})
  if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
  state().active[p.index]=action
  out.op=nil; out.until_tick=action.until_tick; out.corpses=rows; out.elsewhere=#elsewhere>0 and elsewhere or nil
  out.not_walked=not_walked and #not_walked>0 and not_walked or nil
  out.not_walked_note=out.not_walked and string.format('stop_after %d: the nearest %d walked to; these are left',stop_after,stop_after) or nil
  out.left_out=#left_out>0 and left_out or nil; out.unsafe_goal=#unsafe>0 and table.concat(unsafe,'; ') or nil
  out.avoid_enemies=mode and M.avoid.describe(mode) or nil
  out.legs,out.legs_more=M.legs(p,action.targets)
  return out
end
-- recover dry_run (round2120a, Haiku, shift14 03:58, a big worm had just killed her on a rearm tour: "recover needs a
-- dry_run so I can see the corpse's danger before walking"): each corpse of yours, how far, what it holds, and the
-- danger the map shows round it: worms whose range comes within 16 tiles of it, spawners within 40 + 16, our
-- entities attacked within 48 tiles of it in the last 10 minutes (threat.lua's incidents); and whether recover walks
-- to it (inside a weapon's reach: left out, with the nearest safe spot). A read (M.read_call): nothing walks.
function M.recover_dry(p,a,list,mode)
  local RECOVER_DRY={near=16,attacks=48,since=36000,items=6,danger=8,nests=4}
  local look=mode or M.avoid.mode(nil)
  local rows,elsewhere={},{}
  local function kinds_line(kinds)
    local parts={}
    for name,n in pairs(kinds or {}) do parts[#parts+1]={name,n} end
    table.sort(parts,function(x,y) return x[2]>y[2] or x[2]==y[2] and x[1]<y[1] end)
    for i,v in ipairs(parts) do parts[i]=v[2]..' '..v[1] end
    return table.concat(parts,', ')
  end
  for _,c in ipairs(list) do
    local ago_s=math.floor((game.tick-(c.tick or game.tick))/60)
    local held,parts=0,{}
    local okc,contents=pcall(function() return c.entity.get_inventory(defines.inventory.character_corpse).get_contents() end)
    if okc and contents then
      table.sort(contents,function(x,y) return x.count>y.count end)
      for i,st in ipairs(contents) do held=held+st.count; if i<=RECOVER_DRY.items then parts[#parts+1]=st.name..'*'..st.count end end
      if #contents>RECOVER_DRY.items then parts[#parts+1]=string.format('+%d more kinds',#contents-RECOVER_DRY.items) end
    end
    local row={position={x=math.floor(c.position.x*10+0.5)/10,y=math.floor(c.position.y*10+0.5)/10},surface=c.surface,
      died=string.format('%dm%02ds ago',math.floor(ago_s/60),ago_s%60),items=held,holds=#parts>0 and table.concat(parts,', ') or 'nothing'}
    -- what killed it and whether it is there now (A4)
    local okk,kf=pcall(M.killer_facts,c.surface,c.position,c.tick)
    if okk then row.killed_by=kf.killed_by; row.killer_now=kf.killer_now; row.units_near=c.surface==p.surface.name and kf.units_near or nil end
    if c.surface==p.surface.name then
      local okg,groups=pcall(threat.groups_near,p.force,p.surface,c.position,160)
      if okg then row.groups=#groups>0 and groups or nil; row.groups_line=threat.groups_line(groups) end
    end
    if c.surface~=p.surface.name then elsewhere[#elsewhere+1]=row
    else
      row.distance=math.floor(distance(p.position,c.position)+0.5)
      -- recover's own check of it, as the call makes it
      local chk=mode and M.avoid.goal_check(p,p.position,c.position,mode)
      if chk and a.unsafe_goal then row.walk='recover walks to it (unsafe_goal): '..M.avoid.goal_text('the corpse',c.position,chk)
      elseif chk then row.walk='left out by recover: '..M.avoid.goal_text('the corpse',c.position,chk)..M.avoid.spot_text(c.position,chk,mode)
      else row.walk=mode and 'recover walks to it: it lies outside the enemy reach the map shows' or 'recover walks to it (avoid_enemies false: no check)' end
      local danger,nests,named={},{},{}
      for _,n in ipairs(M.avoid.near(p,c.position,look,RECOVER_DRY.near)) do
        local m=n.m
        if not m.attack then
          danger[#danger+1]=string.format('%s (%d,%d): %.1f tiles from it, %s: %s',m.name,math.floor(m.x+0.5),math.floor(m.y+0.5),n.d,
            m.spawner and string.format('its units come %g tiles',m.range) or string.format('range %g',m.range),
            n.inside and 'the corpse lies inside it' or string.format('%.1f tiles outside it',n.d-m.range))
          local nest=m.blob and M.avoid.name(m.blob,true)
          if nest and not named[nest] and #nests<RECOVER_DRY.nests then named[nest]=true; nests[#nests+1]=nest end
        end
      end
      local attacks={}
      for _,v in pairs(state().damage or {}) do
        if v.id and v.at and v.last and game.tick-v.last<=RECOVER_DRY.since and (v.surface==nil or v.surface==p.surface.name) then
          local d=distance(v.at,c.position)
          if d<=RECOVER_DRY.attacks then attacks[#attacks+1]={v=v,d=d} end
        end
      end
      table.sort(attacks,function(x,y) return x.v.last>y.v.last end)
      for _,t in ipairs(attacks) do
        local v=t.v
        local who=(v.size or 0)>0 and string.format('%d attacker%s seen (%s)',v.size,v.size==1 and '' or 's',kinds_line(v.kinds)) or (v.by and 'by '..v.by) or 'attackers not seen'
        local last_s=math.floor((game.tick-v.last)/60)
        danger[#danger+1]=string.format('attack #%d at (%d,%d): %.1f tiles from it, %s, last hit %ds ago%s',v.id,v.at.x,v.at.y,t.d,who,last_s,
          game.tick-v.last<=M.avoid.ATTACK_ACTIVE and ' (under attack now)' or '')
      end
      row.danger=#danger>0 and {} or 'none the map shows'
      for i=1,math.min(RECOVER_DRY.danger,#danger) do row.danger[i]=danger[i] end
      row.danger_more=#danger>RECOVER_DRY.danger and #danger-RECOVER_DRY.danger or nil
      row.nests=#nests>0 and nests or nil
      rows[#rows+1]=row
    end
  end
  return {dry_run=true,corpses=#rows>0 and rows or nil,none=#rows==0 and ('no corpse of yours on '..p.surface.name) or nil,
    elsewhere=#elsewhere>0 and elsewhere or nil,avoid_enemies=mode and M.avoid.describe(mode) or 'false: no check',
    danger_note=string.format('danger: worms whose range comes within %d tiles of it, spawners whose units\' reach does, attacks within %d tiles in the last %d min; what the map shows',
      RECOVER_DRY.near,RECOVER_DRY.attacks,RECOVER_DRY.since/3600)}
end
-- collect {pods: true, area?, surface?, to?} (d17 pods, Nick 15:45: landed cargo pods nobody empties): a walking tour
-- over the landed cargo-pod-containers, nearest first (those the landed sweep has found, else those within POD_NEAR
-- tiles of you; with area, those there), taking what each holds as a player opening it would, up to your free slots;
-- to: a chest of ours that gets what the tour took each time your inventory is full, and at the end. The tour's walk
-- and enemy checks are the other tours'. last: what was taken (items), given (to the chest), what is left.
M.POD_NEAR=64
function M.collect_pods(p,a)
  assert(a.pods==true,'pods must be true')
  assert(a.surface==nil or a.surface==p.surface.name,'collect {pods} walks your own surface ('..p.surface.name..')')
  assert(a.item==nil and a.items==nil and a.pick==nil and a.positions==nil,'collect {pods} takes everything the containers hold: no item, items, pick or positions')
  local area
  if a.area~=nil then
    local lt,rb=position(a.area.left_top or a.area[1]),position(a.area.right_bottom or a.area[2])
    assert(rb.x>lt.x and rb.y>lt.y and rb.x-lt.x<=256 and rb.y-lt.y<=256,'area: {left_top, right_bottom}, up to 256x256')
    area={{lt.x,lt.y},{rb.x,rb.y}}
  end
  local list=M.landed.containers(p.surface,p.position,area)
  local seen={}
  for _,e in ipairs(list) do seen[e.unit_number]=true end
  -- not yet swept: look there now
  local extra=p.surface.find_entities_filtered{name='cargo-pod-container',force=p.force,area=area,position=not area and p.position or nil,radius=not area and M.POD_NEAR or nil}
  for _,e in ipairs(extra) do
    if e.valid and not seen[e.unit_number] and not e.get_inventory(defines.inventory.chest).is_empty() then list[#list+1]=e; seen[e.unit_number]=true end
  end
  assert(#list>0,string.format('no landed cargo pod holding anything %s (pods reads where they are)',area and 'in that area' or 'that the sweep has found on '..p.surface.name..', nor within '..M.POD_NEAR..' tiles of you'))
  local to
  if a.to~=nil then
    local pos=position(a.to)
    local ok,e=pcall(entity,p,{position=pos},'walk')
    if not (ok and e) then ok,e=pcall(remote_entity,p,{position=pos}) end
    assert(ok and e and e.valid and e.get_inventory(defines.inventory.chest),string.format('to (%g,%g): no chest of ours there',pos.x,pos.y))
    to=e
  end
  local take={direction='to_player',partial=true}
  local action,out=stock.start_tour(p,'transfer',list,integer(a.ticks,36000,1,72000,'ticks'),
    {transfer=take,rows={},items={},collect=true,avoid_enemies=a.avoid_enemies,unsafe_goal=a.unsafe_goal,
     pods={to=to,given={},containers=list}})
  if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
  state().active[p.index]=action
  out.until_tick=action.until_tick
  out.legs,out.legs_more=M.legs(p,action.targets)
  out.pods=#action.targets
  out.to=to and string.format('%s (%g,%g)',to.name,to.position.x,to.position.y) or nil
  out.note='takes what each landed cargo pod holds, nearest first'..(to and ', and puts it in '..out.to..' whenever your inventory is full and at the end' or ', up to your free slots')..'; last says what was taken'..(to and ', given' or '')..' and what is left'
  return out
end
-- What a pods tour took and has not given to its chest yet, that you still carry (stock.lua).
function M.pods_owed(p,action)
  local n=0
  local inv=p.get_main_inventory()
  for key,c in pairs(action.items or {}) do
    local name,q=key:match('^([^@]+)@?(.*)$')
    local owed=c-((action.pods.given or {})[key] or 0)
    if owed>0 then n=n+math.min(owed,inv and inv.get_item_count{name=name,quality=q~='' and q or 'normal'} or 0) end
  end
  return n
end
-- A pods tour at its chest: what it took and still carries, given (stock.lua).
function M.pods_deposit(p,action,chest)
  local given,owed_all=0,0
  local inv=p.get_main_inventory()
  local given_map=action.pods.given
  for key,c in pairs(action.items or {}) do
    local name,q=key:match('^([^@]+)@?(.*)$')
    q=q~='' and q or 'normal'
    local owed=math.min(c-(given_map[key] or 0),inv and inv.get_item_count{name=name,quality=q} or 0)
    if owed>0 then
      owed_all=owed_all+owed
      local ok,out=pcall(transfer_one,p,{direction='to_entity',item=name,quality=q,count=owed,partial=true},nil,chest)
      local n=ok and out and out.transferred or 0
      if n>0 then given_map[key]=(given_map[key] or 0)+n; given=given+n end
    end
  end
  action.rows[#action.rows+1]={position=chest.position,name=chest.name,moved=given,direction='to_entity'}
  if owed_all==0 then return {transferred=0,stop='inventory_full'} end
  if given==0 then return {transferred=0,stop='destination_full'} end
  return {transferred=0}
end
function handlers.collect(p,a)
  if a.pods~=nil then return M.collect_pods(p,a) end
  if a.min_fresh~=nil then integer(a.min_fresh,nil,0,100,'min_fresh') end
  assert(a.outputs_only==nil or type(a.outputs_only)=='boolean','outputs_only must be true or false')
  if a.outputs_only then
    assert(not a.chests,'outputs_only excludes chests')
    assert(a.inventory==nil,'outputs_only selects the machine output inventory')
    for _,t in ipairs(a.types or {}) do assert(t=='assembling-machine' or t=='furnace' or t=='agricultural-tower','outputs_only requires machine output types') end
    a.types=a.types or {'assembling-machine','furnace','agricultural-tower'}
  end
  if a.pick~=nil then return M.pick_source(p,a,'collect') end
  if a.items~=nil or (a.to~=nil and a.wait_ticks==nil and a.keep_taking==nil) then
    error("items and to go with pick: pick + positions + item or items + to takes at the first listed place holding it and gives at to; e.g. fh call collect --args '"
      ..M.aliases.encode({pick='first_with_stock',positions={{x=12.5,y=4.5}},items=type(a.items)=='table' and a.items or {'ITEM'},to=type(a.to)=='table' and a.to or {x=30.5,y=4.5}}).."'",0)
  end
  assert(a.chests==nil or type(a.chests)=='boolean','chests must be true or false')
  assert(a.types==nil or (type(a.types)=='table' and #a.types>=1 and #a.types<=16),'types requires 1..16 entity types')
  assert(a.up_to==nil or a.up_to==true,'up_to must be true (an empty source never fails the step)')
  -- want: a target holding (shake2 and shake3 plans wrote collect want=N);
  -- takes only the difference, and nothing when the character has enough.
  -- Worked out when the step runs, so a queued step sees what earlier steps got.
  if a.want~=nil then
    assert(type(a.item)=='string','want needs item: collect item=NAME want=N stops once you hold N')
    assert(a.count==nil,'give count (how many to take) or want (how many to hold), not both')
    local want,have=integer(a.want,1,1,100000,'want'),held(p,a.item,a.quality)
    if have>=want then return {transferred=0,held=have,want=want,note='already holding '..have..' '..a.item} end
    local copy={}
    for k,v in pairs(a) do copy[k]=v end
    copy.want=nil; copy.count=math.min(want-have,10000)
    a=copy
  end
  -- wait_ticks or keep_taking (Muse, operator 09:31: a collect from a machine's output lost to its output inserters
  -- about four times): stand at the machine and take each product as it appears (stock.lua start_wait).
  if a.wait_ticks~=nil or a.keep_taking~=nil then
    -- One machine: position (the alias layer hands a single position over as positions).
    local at=a.position
    -- Several machines (Sonnet, ~6 a shift: waiting on scarce output such as low-density structures): it stands at the
    -- first and takes from each of the others too that it reaches from there (also).
    local also
    if at==nil and type(a.positions)=='table' and #a.positions>=1 then
      at=a.positions[1]
      if #a.positions>1 then
        assert(#a.positions<=16,'wait_ticks waits at 1..16 machines (positions)')
        also={}
        for i=2,#a.positions do
          local q=a.positions[i]
          also[#also+1]=entity(p,{position=q.position or q,name=q.name,unit_number=q.unit_number},true)
        end
      end
    end
    if a.radius~=nil or a.area~=nil or at==nil then
      error('wait_ticks waits at a machine: give its position (an assembler or furnace), or positions (1..16; it stands at the first)',0)
    end
    if not (a.keep_taking==nil or a.keep_taking==true or type(a.keep_taking)=='number') then error('keep_taking is true (3600 ticks) or ticks',0) end
    local wait=a.wait_ticks~=nil and integer(a.wait_ticks,nil,1,36000,'wait_ticks')
      or a.keep_taking==true and 3600 or integer(a.keep_taking,nil,1,36000,'keep_taking')
    local e=entity(p,{position=at.position or at,name=a.name or at.name,unit_number=at.unit_number},'walk')
    -- follow (Sol, shift18: twice a wait while inserters moved every lithium plate into an output chest): take from the
    -- chests its output inserters fill instead, when they hold the item.
    assert(a.follow==nil or type(a.follow)=='boolean','follow must be true or false')
    if a.follow then
      local tk=stock.output_takers(e,a.item)
      local list={}
      for _,c in ipairs(tk and tk.chests or {}) do if not a.item or c.holds>0 then list[#list+1]={x=c.position.x,y=c.position.y} end end
      if #list>0 then
        local copy={}
        for k,v in pairs(a) do if k~='wait_ticks' and k~='keep_taking' and k~='follow' and k~='position' and k~='positions' and k~='name' then copy[k]=v end end
        copy.positions=list
        local out=handlers.collect(p,copy)
        if type(out)=='table' then out.followed=tk.line..'; taken from '..(#list==1 and 'that chest' or 'those chests')..' instead of waiting' end
        return out
      end
    end
    -- to (batch26 C4, Grok: nutrients reach a provider and robots take them within 5 s, a craft lost several times an
    -- hour): each take from the output goes the same tick into the machine at to, by hand, its fuel or its input.
    local give_to
    if a.to~=nil then
      assert(a.follow==nil and also==nil,'to goes with one machine (position), not follow or several positions')
      assert(type(a.item)=='string','to needs item: the product handed on')
      local there=entity(p,{position=position(a.to)},true)
      friendly(p,there)
      assert(there~=e,'to is the machine waited at: name another machine')
      local named=a.to_inventory
      local okn,inv
      if named~=nil then okn,inv=pcall(inventory,there,named)
        if not okn then error(tostring(inv):gsub('^[^:]*:%d+: ','')..': to_inventory '..tostring(named)..'; '..M.inventory_names(there),0) end
      else okn,named,inv=pcall(infer_inventory,there,{direction='to_entity',item=a.item,quality=a.quality}) end
      assert(okn and inv and (not inv.can_insert or inv.can_insert{name=a.item,quality=a.quality or 'normal'}),
        string.format('%s (%g,%g) takes no %s%s now',there.name,there.position.x,there.position.y,a.item,named and ' in '..named or ''))
      give_to={entity=there,inventory=named}
    else assert(a.to_inventory==nil,'to_inventory goes with to') end
    -- give and take_back (d17 batch34 C4, Grok, every few minutes: a gap between calls let the next craft eat the seed or
    -- the nutrients spoil): put items into the machine first, by hand (its recipe input when the recipe takes one, else its
    -- fuel), wait for its products, then take back what is left of the named items (input and fuel), in one timed call.
    local gave,back
    if a.give~=nil then
      assert(type(a.give)=='table' and next(a.give)~=nil and a.give[1]==nil,'give is {item: count, ...}: what goes into the machine before the wait')
      assert(a.follow==nil and also==nil,'give goes with one machine (position)')
      assert(p.can_reach_entity(e),string.format('give needs %s (%g,%g) in reach: stand by it first',e.name,e.position.x,e.position.y))
      gave={}
      local names={}
      for item in pairs(a.give) do names[#names+1]=item end
      table.sort(names)
      for _,item in ipairs(names) do
        local n=integer(a.give[item],nil,1,10000,'give '..item)
        local okg,r=pcall(handlers.transfer,p,{position=e.position,direction='to_entity',item=item,count=n})
        if not okg then error(string.format('give %s %d into %s (%g,%g): %s; nothing waited',item,n,e.name,e.position.x,e.position.y,reason(r)),0) end
        gave[item]=type(r)=='table' and (r.moved or r.transferred) or n
      end
      if a.count==nil and type(a.item)=='string' then
        local okr,rc=pcall(e.get_recipe)
        for _,pr in ipairs(okr and rc and rc.products or {}) do
          if pr.name==a.item then local copy={}; for k,v in pairs(a) do copy[k]=v end; copy.count=pr.amount or pr.amount_max or 1; a=copy end
        end
      end
    end
    if a.take_back~=nil then
      assert(type(a.take_back)=='table' and #a.take_back>=1 and #a.take_back<=8,'take_back is a list of item names: what is left of them in the machine comes back at the end')
      for _,item in ipairs(a.take_back) do assert(type(item)=='string' and prototypes.item[item],'take_back: unknown item '..tostring(item)) end
      back=a.take_back
    end
    local action,out=stock.start_wait(p,a,e,wait)
    action.take_back=back
    if gave then out.gave=gave end
    if back then out.take_back='at the end the machine\'s '..table.concat(back,', ')..' come back to you (input and fuel; last.taken_back)' end
    if give_to then
      action.give_to=give_to
      out.to=string.format('each take goes the same tick into %s (%g,%g) %s, by hand; it must be in reach from where the wait stands at the machine',
        give_to.entity.name,give_to.entity.position.x,give_to.entity.position.y,give_to.inventory)
    end
    -- follow goes on during the wait (D1): stock.lua wait_tick
    action.follow=a.follow==true or nil
    if also then
      action.also=also
      local names={}
      for _,x in ipairs(also) do names[#names+1]=string.format('%s (%g,%g)',x.name,x.position.x,x.position.y) end
      out.also=string.format('also takes from %d more machine%s it reaches from where it stands at the first: %s (one out of reach from there waits: last.also says)',#also,#also==1 and '' or 's',table.concat(names,', '))
    end
    if a.follow then out.followed='no chest its output inserters fill holds '..(a.item or 'its products')..': waiting at the machine' end
    if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
    state().active[p.index]=action
    out.until_tick=action.until_tick
    return out
  end
  if a.radius~=nil then
    local action,out=stock.start(p,a,integer(a.ticks,3600,1,36000,'ticks'))
    if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
    state().active[p.index]=action
    out.until_tick=action.until_tick
    return out
  end
  -- walk=true (Muse 12:20: like transfer's): positions out of reach are walked to, nearest first, and each is
  -- collected from as in reach (the same take: machine outputs, named chests); one timed call with legs. All in reach:
  -- the collect at once.
  assert(a.walk==nil or type(a.walk)=='boolean','walk must be true or false')
  -- Places out of reach within 32 tiles (autowalk.lua): walked to as walk: true does, the reply saying so (walking).
  local walk,walking=a.walk==true,nil
  if a.walk==nil and not a.walked and (a.positions~=nil or a.position~=nil) then
    local far,n=M.unreached(p,a)
    local worst=far and M.autowalk.wanted('collect',a,far)
    if worst then walk=true; walking=M.autowalk.line(far,n,worst) end
  end
  if walk then
    local list=a.positions or (a.position~=nil and {a.position}) or nil
    assert(type(list)=='table' and #list>=1 and #list<=64,'walk goes with positions (1..64 places to collect from)')
    local entities,far={},0
    -- A stop that does not resolve is left out and named (skipped), as transfer's walk does.
    local skipped={}
    for _,pos in ipairs(list) do
      local ok,e=pcall(function()
        local e=entity(p,{position=pos,name=type(pos)=='table' and pos.name or a.name,unit_number=type(pos)=='table' and pos.unit_number or nil},true)
        friendly(p,e)
        return e
      end)
      if ok then
        entities[#entities+1]=e
        if not p.can_reach_entity(e) then far=far+1 end
      else
        local okp,q=pcall(position,pos)
        skipped[#skipped+1]=string.format('%s: %s',okp and string.format('(%g,%g)',q.x,q.y) or '?',(tostring(e):gsub('^[^:]*:%d+: ','')))
      end
    end
    if #entities==0 then error(#skipped>1 and string.format('none of the %d positions resolves; the first: %s',#skipped,skipped[1]) or skipped[1],0) end
    if far>0 then
      assert(a.keep_max==nil or type(a.keep_max)=='boolean','keep_max must be true or false')
      local take={direction='to_player',item=a.item,quality=a.quality,partial=a.up_to==true or nil,keep_max=a.keep_max,outputs_only=a.outputs_only,min_fresh=a.min_fresh,fresh_first=a.fresh_first,
        count=a.item and integer(a.count,10000,1,10000,'count') or nil}
      local action,out=stock.start_tour(p,'transfer',entities,integer(a.ticks,3600,1,36000,'ticks'),
        {transfer=take,item=a.item,quality=a.quality,rows={},items={},collect=true,avoid_enemies=a.avoid_enemies,unsafe_goal=a.unsafe_goal})
      if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
      state().active[p.index]=action
      out.until_tick=action.until_tick; out.out_of_reach=far
      out.legs,out.legs_more=M.legs(p,action.targets)
      out.walking=walking
      out.skipped=#skipped>0 and skipped or nil
      return out
    end
  end
  assert(a.ticks==nil or walk,'ticks applies to collect with radius, wait_ticks or walk')
  assert(a.keep_max==nil or type(a.keep_max)=='boolean','keep_max must be true or false')
  -- up_to=true stops at the request max (partial); keep_max refuses a take over it (trash.lua).
  local args={direction='to_player',item=a.item,types=a.types or (a.chests and collect_types.chests or collect_types.plain),positions=a.positions,quality=a.quality,
    partial=a.up_to==true or nil,keep_max=a.keep_max,outputs_only=a.outputs_only,min_fresh=a.min_fresh,fresh_first=a.fresh_first}
  args.count=a.item and integer(a.count,10000,1,10000,'count') or nil
  local targets=reachable(p,args,function() return true end)
  local out=transfer_batch(p,args,targets,true)
  if a.up_to==true then short_facts(out,{direction='to_player',count=a.count},1) end
  -- Named targets inside another agent's claim are taken from, but say whose (and when no permission is needed).
  local claimed={}
  for _,t in ipairs(targets) do
    local ok,at=pcall(position,t.entity and t.entity.valid and t.entity.position or t.position)
    local c=ok and #claimed<4 and M.claims.find(p,at)
    if c then claimed[#claimed+1]=string.format('(%g,%g) in %s',at.x,at.y,M.claims.label(c,p)) end
  end
  if #claimed>0 then out.claimed=claimed end
  if not a.positions and not a.types and not a.chests then
    local skipped=0
    for _,e in pairs(p.surface.find_entities_filtered{position=p.position,radius=(p.reach_distance or 10)+3,force=p.force,type={'container','logistic-container'}}) do
      if e.valid and p.can_reach_entity(e) then
        local ok,inv=pcall(e.get_inventory,defines.inventory.chest)
        if ok and inv and (not a.item and not inv.is_empty() or a.item and inv.get_item_count{name=a.item,quality=a.quality or 'normal'}>0) then skipped=skipped+1 end
      end
    end
    if skipped>0 then out.chests_skipped=skipped; out.note='chests in reach were left alone; pass chests=true or their positions to take from them' end
  end
  return out
end
-- What a machine takes by hand: its recipe's item ingredients (a furnace's
-- last recipe when idle), a lab's science packs, and a burner's fuel. Each
-- want names the inventory the item goes to and the target count.
local feeding={TYPES={'assembling-machine','furnace','lab','boiler','burner-generator','mining-drill','inserter','agricultural-tower'}}
-- The recipe an assembler or furnace is set to (a furnace's last one when idle), by name, or nil.
function feeding.recipe_of(e)
  if e.type~='assembling-machine' and e.type~='furnace' and e.type~='rocket-silo' then return nil end
  local ok,r=pcall(e.get_recipe)
  if ok and r then return r.name end
  if e.type=='furnace' then
    local okp,prev=pcall(function() return e.previous_recipe end)
    local name=okp and prev and prev.name
    return type(name)=='table' and name.name or name
  end
end
-- What a burner's fuel slots hold: {name=count}, or nil when empty (or no burner).
function feeding.fuel_in(e)
  local inv=fuel_inventory(e)
  if not inv then return nil end
  local out
  for i=1,#inv do
    local s=inv[i]
    if s and s.valid_for_read then out=out or {}; out[s.name]=(out[s.name] or 0)+s.count end
  end
  return out
end
-- A burner's fuel slots as one line ("coal 10", "solid-fuel 3, wood 2", "empty"); nil for a machine with no burner.
function feeding.fuel_line(e)
  if not fuel_inventory(e) then return nil end
  local held_,names=feeding.fuel_in(e) or {},{}
  for name in pairs(held_) do names[#names+1]=name end
  table.sort(names)
  for i,name in ipairs(names) do names[i]=name..' '..held_[name] end
  return #names>0 and table.concat(names,', ') or 'empty'
end
-- The fuel item for a burner: fuel=NAME; a fuel it burns named in items; what its slots hold, when carried; else
-- coal for chemical burners, or what it burns (a biochamber: nutrients; farm.lua). Second value: named in items.
function feeding.fuel_for(p,e,a)
  if type(a.fuel)=='string' then return a.fuel end
  for _,name in ipairs(a.items or {}) do
    if (prototypes.item[name].fuel_value or 0)>0 and M.farm.accepts_fuel(e,name) then return name,true end
  end
  for name in pairs(feeding.fuel_in(e) or {}) do
    if held(p,name,a.quality)>0 then return name end
  end
  return M.farm.default_fuel(e,function(n) return held(p,n,a.quality) end)
end
-- A burner gets fuel when asked (fuel=NAME, fuel=true, or a fuel named in items) or when its fuel slots are empty
-- (Gemini 03:20: furnaces burning solid fuel refused an ore feed over "you carry 0 coal").
function feeding.fuel_want(p,e,a)
  if a.fuel==false or not fuel_inventory(e) or not pcall(inventory,e,'fuel') then return nil end
  local fuel,named=feeding.fuel_for(p,e,a)
  if not (fuel and M.farm.accepts_fuel(e,fuel)) then return nil end
  if a.fuel==nil and not named and feeding.fuel_in(e) then return nil,true end
  return {item=fuel,inventory='fuel',count=a.fuel_count}
end
-- '2 burners hold another fuel in every fuel slot (solid-fuel 4): no slot for coal'
function M.other_fuel_line(n,holds,item)
  return string.format('%d burner%s hold%s another fuel in every fuel slot (%s): no slot for %s',n,n==1 and '' or 's',
    n==1 and 's' or '',table.concat(holds,', '),item or 'it')
end
-- A burner whose fuel slots are all taken by another fuel has no room for item (a slot holds one item kind):
-- what they hold ("solid-fuel 4"), or nil (Haiku, 07:55: feed with up_to over boilers burning the other fuel).
function feeding.blocked_fuel(e,item)
  local inv=fuel_inventory(e)
  if not inv then return nil end
  for i=1,#inv do
    local s=inv[i]
    if not (s and s.valid_for_read) or s.name==item then return nil end
  end
  local held_=feeding.fuel_in(e)
  if not held_ then return nil end
  local parts={}
  for name,c in pairs(held_) do parts[#parts+1]=name..' '..c end
  table.sort(parts)
  return table.concat(parts,', ')
end
-- Whether a furnace smelts item (a recipe of its crafting categories takes it), by furnace name; prototypes only.
feeding.smelts_cache={}
function feeding.smelts(e,item)
  local key=e.name..'\0'..item
  local smelts_cache=feeding.smelts_cache
  if smelts_cache[key]==nil then
    local ok,cats=pcall(function() return e.prototype.crafting_categories end)
    local found=false
    for _,r in pairs(ok and cats and prototypes.recipe or {}) do
      if cats[r.category] then
        for _,ing in ipairs(r.ingredients or {}) do if ing.type=='item' and ing.name==item then found=true; break end end
      end
      if found then break end
    end
    smelts_cache[key]=found
  end
  return smelts_cache[key]
end
function feeding.wants(p,e,a)
  local out={}
  -- recipe: that recipe's item ingredients for `crafts` crafts, only in machines set to it (the second value names
  -- the recipe a machine runs instead, or false for none).
  if a.recipe then
    local set=feeding.recipe_of(e)
    if set~=a.recipe then return out,set or false end
    for _,ing in ipairs(prototypes.recipe[a.recipe].ingredients or {}) do
      if ing.type=='item' then
        out[#out+1]={item=ing.name,inventory=e.type=='furnace' and 'furnace_source' or 'assembling_machine_input',count=math.min(ing.amount*(a.crafts or 1),100000)}
      end
    end
    return out
  end
  local fuel=feeding.fuel_want(p,e,a)
  if fuel then out[#out+1]=fuel end
  local recipe
  if e.type=='assembling-machine' or e.type=='furnace' or e.type=='rocket-silo' then
    local ok,r=pcall(e.get_recipe); recipe=ok and r or nil
    if not recipe and e.type=='furnace' then
      local okp,prev=pcall(function() return e.previous_recipe end)
      local name=okp and prev and prev.name
      name=type(name)=='table' and name.name or name
      recipe=name and prototypes.recipe and prototypes.recipe[name] or nil
    end
    for _,ing in ipairs(recipe and recipe.ingredients or {}) do
      if ing.type=='item' then out[#out+1]={item=ing.name,inventory=e.type=='furnace' and 'furnace_source' or 'assembling_machine_input',count=a.count} end
    end
    -- A furnace that never smelted has no recipe yet: it takes the named items it smelts, as a player puts them in.
    if not recipe and e.type=='furnace' then
      for _,name in ipairs(a.items or {}) do
        if feeding.smelts(e,name) then out[#out+1]={item=name,inventory='furnace_source',count=a.count} end
      end
    end
  elseif e.type=='lab' then
    local ok,names=pcall(function() return e.prototype.lab_inputs end)
    for _,name in ipairs(ok and names or {}) do out[#out+1]={item=name,inventory='lab_input',count=a.count} end
  elseif e.type=='agricultural-tower' then
    -- Seeds: the kinds it holds, else every kind the character carries.
    local seeds=M.farm.seeds()
    local okc,inv=pcall(inventory,e,'agricultural_tower_input')
    local kinds={}
    for _,st in ipairs(okc and inv.get_contents() or {}) do if seeds[st.name] then kinds[#kinds+1]=st.name end end
    if #kinds==0 then for name in pairs(seeds) do if held(p,name,a.quality)>0 then kinds[#kinds+1]=name end end end
    table.sort(kinds)
    for _,name in ipairs(kinds) do out[#out+1]={item=name,inventory='agricultural_tower_input',count=a.count} end
  end
  -- Items named (item, items) or a fuel named (fuel=NAME): only those go in (Grok, shift12 13:50: a feed of coal into
  -- furnaces put in the copper ore it held, then ended out_of_items before any coal moved).
  local only
  for _,name in ipairs(a.items or {}) do only=only or {}; only[name]=true end
  if type(a.fuel)=='string' and not a.recipe then only=only or {}; only[a.fuel]=true end
  if only then
    local keep={}
    for _,w in ipairs(out) do if only[w.item] then keep[#keep+1]=w end end
    out=keep
  end
  return out
end
M.feedclean=require('feedclean'){inventory=inventory,take=function(p,e,inv,item,quality,count)
  return transfer_one(p,{direction='to_player',inventory=inv,item=item,quality=quality,count=count,partial=true},nil,e)
end}
-- Feeds one machine every want the character can spare; returns what it got.
-- With recipe, also what each ingredient still lacks for the crafts asked (short) and a machine set to another recipe.
function feeding.one(p,e,a)
  local cleared=a.clear_spoilage and M.feedclean.clear(p,e) or nil
  local gave,total={},0
  local keep=integer(a.keep,0,0,100000,'keep')
  local wants,other=feeding.wants(p,e,a)
  local short,blocked
  for _,w in ipairs(wants) do
    -- Fuel slots all holding another fuel: skipped, and said (fifth value).
    local b=w.inventory=='fuel' and feeding.blocked_fuel(e,w.item)
    if b then blocked=b
    elseif held(p,w.item,a.quality)>keep then
      local ok,out=pcall(transfer_one,p,{direction='to_entity',item=w.item,inventory=w.inventory,count=w.count,up_to=w.count,keep=keep,quality=a.quality},nil,e)
      if ok and out.transferred>0 then gave[w.item]=(gave[w.item] or 0)+out.transferred; total=total+out.transferred end
    end
    if a.recipe then
      local ok,inv=pcall(inventory,e,w.inventory)
      local have=ok and inv.get_item_count{name=w.item,quality=a.quality or 'normal'} or 0
      if have<w.count then short=short or {}; short[w.item]=w.count-have end
    end
  end
  return gave,total,short,other,blocked,cleared
end
-- A machine below the target count on a want the character holds none of beyond the reserve.
function feeding.short_of(p,e,a)
  local keep=integer(a.keep,0,0,100000,'keep')
  for _,w in ipairs(feeding.wants(p,e,a)) do
    if held(p,w.item,a.quality)<=keep and not (w.inventory=='fuel' and feeding.blocked_fuel(e,w.item)) then
      local ok,inv=pcall(inventory,e,w.inventory)
      if ok and inv.get_item_count{name=w.item,quality=a.quality or 'normal'}<w.count then return true end
    end
  end
  return false
end
-- A machine that wants something the character holds beyond the reserve and
-- is below the target count for it.
function feeding.hungry(p,e,a)
  if a.clear_spoilage and #M.feedclean.pending(e)>0 then return true end
  local keep=integer(a.keep,0,0,100000,'keep')
  for _,w in ipairs(feeding.wants(p,e,a)) do
    if held(p,w.item,a.quality)>keep and not (w.inventory=='fuel' and feeding.blocked_fuel(e,w.item)) then
      local ok,inv=pcall(inventory,e,w.inventory)
      if ok and inv.get_item_count{name=w.item,quality=a.quality or 'normal'}<w.count then return true end
    end
  end
  return false
end
-- Why a feed gave nothing, per wanted item: what the character carries and
-- what the machines hold (Haiku's 35 empty feeds read "nothing_to_do, given
-- 0" while it carried no coal).
function feeding.why(p,es,a)
  local keep=integer(a.keep,0,0,100000,'keep')
  local by,order={},{}
  -- Burners left alone because they hold fuel, and furnaces with no recipe yet.
  local fueled,fuels,unset={n=0},{},0
  local blocked={n=0,holds={}}
  for _,e in ipairs(es) do
    for _,w in ipairs(feeding.wants(p,e,a)) do
      -- Fuel slots all taken by another fuel: counted apart, not as "at count already".
      local bf=w.inventory=='fuel' and feeding.blocked_fuel(e,w.item)
      if bf then
        blocked.n=blocked.n+1; blocked.item=w.item
        if not blocked.holds[bf] then blocked.holds[bf]=true; blocked.holds[#blocked.holds+1]=bf end
      else
        local ok,inv=pcall(inventory,e,w.inventory)
        local c=ok and inv.get_item_count{name=w.item,quality=a.quality or 'normal'} or 0
        local b=by[w.item]
        if not b then b={n=0,lo=math.huge,hi=0,count=w.count}; by[w.item]=b; order[#order+1]=w.item end
        b.n=b.n+1; b.lo=math.min(b.lo,c); b.hi=math.max(b.hi,c)
      end
    end
    local _,has=feeding.fuel_want(p,e,a)
    if has then
      fueled.n=fueled.n+1
      for name,c in pairs(feeding.fuel_in(e) or {}) do
        local f=fuels[name]
        if not f then f={lo=c,hi=c}; fuels[name]=f; fuels[#fuels+1]=name end
        f.lo=math.min(f.lo,c); f.hi=math.max(f.hi,c)
      end
    end
    if e.type=='furnace' and not feeding.recipe_of(e) then unset=unset+1 end
  end
  local notes={}
  -- Only fuel named: what goes into the furnaces' source slots is not asked about.
  local source=not a.items
  for _,name in ipairs(a.items or {}) do source=source or (prototypes.item[name].fuel_value or 0)<=0 end
  if unset>0 and source then
    -- What the character carries that those furnaces smelt (main inventory).
    local can={}
    local okc,contents=pcall(function() return p.get_main_inventory().get_contents() end)
    for _,st in ipairs(okc and contents or {}) do
      for _,e in ipairs(es) do
        if e.type=='furnace' and not feeding.recipe_of(e) and feeding.smelts(e,st.name) then can[#can+1]=st.name..' '..st.count; break end
      end
      if #can>=4 then break end
    end
    notes[#notes+1]=string.format('%d furnace%s with no recipe yet (nothing smelted there) take%s only items named in items or item%s',unset,unset==1 and '' or 's',unset==1 and 's' or '',
      #can>0 and ('; you carry '..table.concat(can,', ')..' that they smelt') or '')
  end
  if fueled.n>0 then
    table.sort(fuels)
    local holds={}
    for i,name in ipairs(fuels) do
      local f=fuels[name]
      holds[i]=name..' '..(f.lo==f.hi and f.lo or f.lo..'-'..f.hi)
    end
    notes[#notes+1]=string.format('%d burner%s hold%s fuel (%s): fuel is added to a burner with none, or with fuel=true or fuel=NAME',
      fueled.n,fueled.n==1 and '' or 's',fueled.n==1 and 's' or '',table.concat(holds,', '))
  end
  if blocked.n>0 then notes[#notes+1]=M.other_fuel_line(blocked.n,blocked.holds,blocked.item) end
  if #order==0 and blocked.n>0 then return table.concat(notes,'; ') end
  -- A silo's rocket cargo is not a recipe input: the calls that fill it.
  local silos=0
  for _,e in ipairs(es) do if e.type=='rocket-silo' then silos=silos+1 end end
  if silos>0 then notes[#notes+1]='feed fills a rocket silo\'s rocket-part ingredients; its rocket cargo: load_silo, or transfer {inventory: "rocket_silo_rocket"}' end
  -- Turrets and chests named to feed (B2, Muse 21:20, about 6 times: "none of the machines wants an item" for gun
  -- turrets): which call fills them, and what a turret holds now.
  local turrets,chests={},0
  for _,e in ipairs(es) do
    if e.type=='ammo-turret' or e.type=='artillery-turret' then
      local inv=e.get_inventory(e.type=='artillery-turret' and defines.inventory.artillery_turret_ammo or defines.inventory.turret_ammo)
      local held={}
      for _,c in ipairs(inv and inv.get_contents() or {}) do held[#held+1]=c.name..' '..c.count end
      turrets[#turrets+1]=string.format('%s (%g,%g) holds %s',e.name,e.position.x,e.position.y,#held>0 and table.concat(held,', ') or 'no ammo')
    elseif e.type=='container' or e.type=='logistic-container' then chests=chests+1 end
  end
  if #turrets>0 then notes[#notes+1]=string.format('feed loads no turret; rearm {ammo, positions} does: %s%s',table.concat(turrets,'; ',1,math.min(#turrets,4)),#turrets>4 and '; ...' or '') end
  if chests>0 then notes[#notes+1]=string.format('%d chest%s: feed fills machines; transfer {direction: "to_entity"} puts items in a chest',chests,chests==1 and '' or 's') end
  if #order==0 and #es>0 and #turrets+chests==#es then return table.concat(notes,'; ') end
  if #order==0 then
    local base=silos==#es and string.format('the rocket silo%s rocket-part recipe takes none of what was named',silos==1 and '\'s' or 's\'')
      or string.format('none of the %d machines wants an item (no recipe set, or not a machine feed fills)',#es)
    return #notes>0 and base..'; '..table.concat(notes,'; ') or base
  end
  local parts={}
  for i,item in ipairs(order) do
    if i>4 then parts[#parts+1]='+'..(#order-4)..' more'; break end
    local b,have=by[item],held(p,item,a.quality)
    local hold=b.lo==b.hi and tostring(b.lo) or (b.lo..'-'..b.hi)
    if have<=keep then
      parts[#parts+1]=string.format('you carry %d %s%s; %d machine%s hold %s',have,item,keep>0 and ' (keep '..keep..')' or '',b.n,b.n==1 and '' or 's',hold)
    else
      parts[#parts+1]=string.format('%d machine%s hold%s %s %s: at or over the %d each is topped up to',b.n,b.n==1 and '' or 's',b.n==1 and 's' or '',hold,item,b.count)
    end
  end
  for _,note in ipairs(notes) do parts[#parts+1]=note end
  return table.concat(parts,'; ')
end
-- Hand-feeds machines from inventory: recipe ingredients, science packs and
-- fuel, up to count each, keeping a reserve. In reach by default, at given
-- positions, or as a walking tour with radius. clear_spoilage also takes waste out.
function handlers.feed(p,a)
  assert(a.clear_spoilage==nil or type(a.clear_spoilage)=='boolean','clear_spoilage must be true or false')
  -- item: one name, as transfer takes it (Grok): the same as items=[item], beside any items given.
  if a.item~=nil then
    assert(type(a.item)=='string' and prototypes.item[a.item],'unknown item '..tostring(a.item))
    assert(a.items==nil or type(a.items)=='table','items requires 1..16 item names')
    local list={a.item}
    for _,name in ipairs(a.items or {}) do if name~=a.item then list[#list+1]=name end end
    a.items=list; a.item=nil
  end
  assert(a.items==nil or (type(a.items)=='table' and #a.items>=1 and #a.items<=16),'items requires 1..16 item names')
  for _,name in ipairs(a.items or {}) do assert(prototypes.item[name],'unknown item '..tostring(name)) end
  assert(a.fuel==nil or type(a.fuel)=='boolean' or (type(a.fuel)=='string' and prototypes.item[a.fuel] and (prototypes.item[a.fuel].fuel_value or 0)>0),'fuel must be a fuel item, true or false')
  a.count=integer(a.count,20,1,1000,'count'); a.fuel_count=integer(a.fuel_count,10,1,1000,'fuel_count')
  assert(a.types==nil or (type(a.types)=='table' and #a.types>=1 and #a.types<=16),'types requires 1..16 entity types')
  assert(a.up_to==nil or a.up_to==true,'up_to must be true (a short inventory never fails the step)')
  assert(a.crafts==nil or a.recipe~=nil,'crafts goes with recipe')
  if a.recipe~=nil then
    assert(type(a.recipe)=='string' and prototypes.recipe[a.recipe],'unknown recipe '..tostring(a.recipe))
    assert(a.items==nil,'give recipe or items (or item), not both')
    a.crafts=integer(a.crafts,1,1,1000,'crafts')
  end
  -- A rocket silo's fixed rocket-part recipe is fed as a machine's (Muse, twice: feed {recipe} refused it as "no recipe set").
  local types=a.types or (a.recipe and {'assembling-machine','furnace','rocket-silo'}) or feeding.TYPES
  if a.position~=nil then
    assert(a.positions==nil,'give position or positions, not both')
    if a.radius==nil then
      local b={}
      for k,v in pairs(a) do b[k]=v end
      b.positions={a.position}; b.position=nil
      a=b
    end
  end
  if a.radius~=nil or a.area_entities then
    assert(a.positions==nil,'give radius or positions, not both')
    local targets,found={},{}
    local radius=a.area_entities and 0 or integer(a.radius,32,1,256,'radius')
    -- position: the radius's centre, as rearm and refuel take it (Muse, d15 06:28: feed refused position + radius)
    local centre=a.position and position(a.position) or p.position
    -- area_entities: an area with more than 64 machines, walked as one tour (the area wrapper below)
    local list,types_note
    local area_list=a.area_entities
    a.area_entities=nil
    if area_list then list=area_list else list,types_note=M.find_kinds(p,{position=centre,radius=radius},types) end
    for _,e in pairs(list) do
      if e.valid then found[#found+1]=e; if feeding.hungry(p,e,a) then targets[#targets+1]=e end end
    end
    local action,out=stock.start_tour(p,'feed',targets,integer(a.ticks,3600,1,36000,'ticks'),{feed=a,avoid_enemies=a.avoid_enemies,unsafe_goal=a.unsafe_goal})
    if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
    state().active[p.index]=action
    out.until_tick=action.until_tick
    -- Burners whose fuel slots all hold another fuel are left out of the tour; with up_to, when they are all it found,
    -- that is no warning (Haiku, 07:55).
    local blocked={n=0,holds={}}
    for _,e in ipairs(found) do
      local fw=feeding.fuel_want(p,e,a)
      local fuel=fw and fw.item
      local bf=fuel and feeding.blocked_fuel(e,fuel)
      if bf then
        blocked.n=blocked.n+1; blocked.item=blocked.item or fuel
        if not blocked.holds[bf] then blocked.holds[bf]=true; blocked.holds[#blocked.holds+1]=bf end
      end
    end
    if blocked.n>0 then out.other_fuel=M.other_fuel_line(blocked.n,blocked.holds,blocked.item) end
    if #targets==0 and not (a.up_to==true and blocked.n>0 and blocked.n==#found) then
      local ok,why=pcall(feeding.why,p,found,a)
      out.nothing_moved=ok and ('nothing to feed: '..why) or nil
    end
    out.types_note=types_note
    if #targets==0 and area_list then
      out.nothing=string.format('nothing in the area wants what you hold (%d machine%s of those kinds there)',#found,#found==1 and '' or 's')
    elseif #targets==0 then
      out.nothing=string.format('nothing in radius %d wants what you hold (%d machine%s of those kinds there)',radius,#found,#found==1 and '' or 's')
      out.nearest_outside=M.nearest_outside(p,types,function(e) return distance(centre,e.position)<=radius end,function(e) return feeding.hungry(p,e,a) end,
        'machine that wants what you hold')
      M.tour_note(p,out)
    end
    return out
  end
  -- positions with walk=true (Opus 10:50: reach errors at 10.x tiles cost many retries): when any is out of reach,
  -- one timed tour walks a nearest-first route through them and feeds each as a radius tour does; legs lists the
  -- route. All in reach: the feed at once.
  assert(a.walk==nil or type(a.walk)=='boolean','walk must be true or false')
  -- Machines out of reach within 32 tiles (autowalk.lua): walked to as walk: true does, the reply saying so (walking).
  local walk,walking=a.walk==true,nil
  if a.walk==nil and not a.walked and a.positions~=nil then
    local far,n=M.unreached(p,a)
    local worst=far and M.autowalk.wanted('feed',a,far)
    if worst then walk=true; walking=M.autowalk.line(far,n,worst) end
  end
  if walk then
    assert(type(a.positions)=='table' and #a.positions>=1 and #a.positions<=64,'walk goes with positions (1..64)')
    local entities,far={},0
    for i,pos in ipairs(a.positions) do
      local e=entity(p,{position=pos,name=type(pos)=='table' and pos.name or nil,unit_number=type(pos)=='table' and pos.unit_number or nil},true)
      friendly(p,e)
      entities[i]=e
      if not p.can_reach_entity(e) then far=far+1 end
    end
    if far>0 then
      local action,out=stock.start_tour(p,'feed',entities,integer(a.ticks,3600,1,36000,'ticks'),{feed=a,avoid_enemies=a.avoid_enemies,unsafe_goal=a.unsafe_goal})
      if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
      state().active[p.index]=action
      out.until_tick=action.until_tick; out.out_of_reach=far
      out.legs,out.legs_more=M.legs(p,action.targets)
      out.walking=walking
      return out
    end
  end
  assert(a.ticks==nil or walk,'ticks applies with radius or walk')
  local targets=reachable(p,{positions=a.positions,types=types},function() return true end)
  local rows,items,total,unchanged,seen,other_recipe={},{},0,0,{},0
  local blocked={n=0,holds={}}
  for _,t in ipairs(targets) do
    local ok,e=pcall(function() return t.entity or entity(p,{position=t.position,name=t.position.name,unit_number=t.position.unit_number}) end)
    if not ok then rows[#rows+1]={position=t.position,error=reason(e)}
    else
      seen[#seen+1]=e
      local okf,gave,n,short,other,bf,cleared=pcall(feeding.one,p,e,a)
      local first_row=#rows+1
      if okf and bf and n==0 then
        blocked.n=blocked.n+1; blocked.item=blocked.item or feeding.fuel_for(p,e,a)
        if not blocked.holds[bf] then blocked.holds[bf]=true; blocked.holds[#blocked.holds+1]=bf end
      end
      if not okf then rows[#rows+1]={position=e.position,name=e.name,error=reason(gave)}
      elseif a.recipe then
        -- One row per machine: what it got and what it still lacks for the crafts, or the recipe it runs instead.
        -- Machines in reach on other recipes are only counted; named ones are listed.
        if other~=nil and a.positions and not a.from_area then rows[#rows+1]={position=e.position,name=e.name,recipe=other or 'none'}
        elseif other~=nil then other_recipe=other_recipe+1
        else rows[#rows+1]={position=e.position,name=e.name,loaded=next(gave) and gave or nil,short=short} end
        for item,c in pairs(gave) do items[item]=(items[item] or 0)+c end
        total=total+n
      elseif n>0 then
        rows[#rows+1]={position=e.position,name=e.name,gave=gave,fuel=feeding.fuel_line(e)}
        for item,c in pairs(gave) do items[item]=(items[item] or 0)+c end
        total=total+n
      else
        unchanged=unchanged+1
        -- Named machines (positions, area) each get a row, also when they got nothing (Haiku: one boiler call).
        if a.positions or cleared then rows[#rows+1]={position=e.position,name=e.name,got='nothing',fuel=feeding.fuel_line(e),other_fuel=bf and n==0 and true or nil} end
      end
      if cleared then
        if #rows<first_row then rows[#rows+1]={position=e.position,name=e.name} end
        rows[#rows].cleared=cleared
      end
    end
  end
  -- Every target failed: the call fails, naming the first reason (Astra 08:47).
  M.all_failed(rows,#targets)
  local left={}
  for item in pairs(items) do left[item]=held(p,item,a.quality) end
  local why
  -- up_to=true: burners whose fuel slots hold another fuel are skipped, not a warning, when they are all that got
  -- nothing (Haiku, 07:55); other_fuel says so.
  local skipped_only=a.up_to==true and blocked.n>0 and blocked.n==#seen
  if total==0 and not skipped_only then
    local ok,w=pcall(feeding.why,p,seen,a)
    why=ok and w or 'no machine in reach wants an item you hold above keep (or they are at count already)'
  end
  return {transferred=total,items=next(items) and items or nil,entities=rows,unchanged=unchanged>0 and unchanged or nil,held=next(left) and left or nil,
    other_recipe=other_recipe>0 and other_recipe or nil,nothing_moved=why and ('nothing given: '..why) or nil,
    other_fuel=blocked.n>0 and M.other_fuel_line(blocked.n,blocked.holds,blocked.item) or nil}
end
-- Items of this name in an entity's transferable inventories (fuel included).
local function entity_holds(e,item,quality)
  local n=0
  for _,name in ipairs(take_order) do
    local ok,inv=pcall(inventory,e,name)
    if ok then n=n+inv.get_item_count{name=item,quality=quality or 'normal'} end
  end
  return n
end
-- Slots a machine consumes from (fuel, ammunition, a machine's or lab's input, robots and repair packs in a roboport):
-- the target holding the item only in these, with you holding it too, means a give (d17 batch17 C3, Muse 4x: topping
-- up a turret holding 6 magazines was refused for direction).
M.FEED_SLOTS={fuel=true,furnace_source=true,assembling_machine_input=true,agricultural_tower_input=true,lab_input=true,
  turret_ammo=true,artillery_turret_ammo=true,artillery_wagon_ammo=true,car_ammo=true,spider_ammo=true,roboport_robot=true,roboport_material=true}
function M.feed_only(e,item,quality)
  for _,name in ipairs(take_order) do
    if not M.FEED_SLOTS[name] then
      local ok,inv=pcall(inventory,e,name)
      if ok and inv.get_item_count{name=item,quality=quality or 'normal'}>0 then return false end
    end
  end
  return true
end
-- An omitted direction follows where the item is, as a player's click would:
-- no item takes everything; an item only the character holds (or will get
-- from the hand-craft queue) is given; one only the targets hold is taken.
do local function infer_direction(p,a)
  if a.item==nil then return 'to_player' end
  local mine=held(p,a.item,a.quality)+crafting_count(p,a.item)
  local theirs,feeding=0,true
  for _,pos in ipairs(a.positions or {a.position}) do
    local ok,n,fed=pcall(function()
      local e=entity(p,{position=pos,name=pos.name or a.name,unit_number=pos.unit_number or a.unit_number})
      friendly(p,e)
      return entity_holds(e,a.item,a.quality),M.feed_only(e,a.item,a.quality)
    end)
    if ok then theirs=theirs+n; if not fed then feeding=false end end
  end
  if mine>0 and theirs==0 then return 'to_entity' end
  if theirs>0 and mine==0 then return 'to_player' end
  if mine>0 and theirs>0 and feeding then
    return 'to_entity',string.format('direction to_entity: you hold %d %s and the target%s it only in the slots %s from (%d); a take from them is direction: "to_player"',
      mine,a.item,a.positions and 's hold' or ' holds',a.positions and 'they feed' or 'it feeds',theirs)
  end
  error(string.format('direction is required (to_entity|to_player): the character holds %d %s and the target%s %d',
    mine,a.item,a.positions and 's hold' or ' holds',theirs),0)
end
M.infer_direction=infer_direction
-- transfer {walk=true} (Haiku, 06:20: solid fuel from a chest into a boiler out of reach, in one call): the targets
-- out of reach are walked to nearest first, then each gets the same transfer, as feed and collect tours do. All in
-- reach: the transfer at once. A field, not a local (runtime.lua's top-level locals are nearly all used).
-- via: 1..16 points {x,y} (or [x,y]) walked in order before a walking tour's first stop.
-- A queue step or standing order step that ended with the character 8 or more tiles from where it began (D5, Opus 3x:
-- "rearm-se took him to (53,112)"): a line for the agent's next reply (the last 4 kept).
function M.moved_by_note(step,ok)
  local p=M.lookup(step.index)
  local c=p and p.valid and p.character
  local f=step.from_pos
  if not (c and c.valid and f) then return end
  local here=c.position
  local same=c.surface.name==f.surface
  if same and distance(f,here)<8 then return end
  local st=state(); st.moved_by=st.moved_by or {}
  local list=st.moved_by[step.index] or {}; st.moved_by[step.index]=list
  local who=step.order and string.format('standing order %s',tostring(step.order)) or string.format('your queue step %s%s',tostring(step.id),step.label and ' ('..step.label..')' or '')
  list[#list+1]=string.format('%s (%s, %s) moved you from (%g,%g)%s to (%g,%g)%s, %s',who,tostring(step.action),ok and 'done' or 'failed',
    math.floor(f.x*10+0.5)/10,math.floor(f.y*10+0.5)/10,same and '' or ' on '..f.surface,math.floor(here.x*10+0.5)/10,math.floor(here.y*10+0.5)/10,
    same and string.format(' (%d tiles)',math.floor(distance(f,here)+0.5)) or ' on '..c.surface.name,'tick '..game.tick)
  while #list>4 do table.remove(list,1) end
end
function M.tour_via(v)
  if v==nil then return nil end
  assert(type(v)=='table' and #v>=1 and #v<=16,'via takes 1..16 points {x,y}, walked in order before the first stop')
  local out={}
  for i,q in ipairs(v) do out[i]=position(q) end
  return out
end
function M.transfer_walk(p,a)
  assert(a.total==nil and a.budget==nil,'total does not go with walk')
  -- fill (from: "nearest" over several chests): the count in all, what is still missing taken at each stop.
  local fill=a.fill
  local list=a.positions or {a.position}
  assert(type(list)=='table' and #list>=1 and #list<=64,'positions requires 1..64 entries')
  assert(list[1]~=nil,'position or positions is required')
  local args={}
  for k,v in pairs(a) do args[k]=v end
  args.walk=nil; args.ticks=nil
  local ticks=integer(a.ticks,3600,1,36000,'ticks')
  local entities,far={},0
  -- A stop that does not resolve (Muse 06:21 and 09:24, 4+ times: one bad position aborted the whole tour) is left out
  -- and named (skipped); none left: refused with the first reason.
  local skipped,invs={},{}
  for _,pos in ipairs(list) do
    -- Seen, not yet in reach (a read's sight): the walk brings it into reach.
    local ok,e=pcall(function()
      local e=entity(p,{position=pos,name=pos.name or a.name,unit_number=pos.unit_number or a.unit_number},true)
      friendly(p,e)
      invs[e.unit_number or e]=M.walk_inventory(p,e,a,pos)
      return e
    end)
    if ok then
      entities[#entities+1]=e
      if not p.can_reach_entity(e) then far=far+1 end
    else
      local okp,q=pcall(position,pos)
      skipped[#skipped+1]=string.format('%s: %s',okp and string.format('(%g,%g)',q.x,q.y) or '?',(tostring(e):gsub('^[^:]*:%d+: ','')))
    end
  end
  if #entities==0 then error(#skipped>1 and string.format('none of the %d positions resolves; the first: %s',#skipped,skipped[1]) or skipped[1],0) end
  if #skipped>0 then
    if a.positions then args.positions={} for _,e in ipairs(entities) do args.positions[#args.positions+1]={x=e.position.x,y=e.position.y,name=e.name} end end
    local out=M.transfer_walk_go(p,a,args,entities,far,fill,ticks,invs)
    if type(out)=='table' then out.skipped=skipped end
    return out
  end
  return M.transfer_walk_go(p,a,args,entities,far,fill,ticks,invs)
end
-- The inventory a walking transfer uses at e, found before the walk (Luna, shift62 03:58: a take of wood at a Gleba
-- chest's position, made from Nauvis, walked 512 tiles to the solar panel on that tile there and was refused on
-- arrival): its name, or a refusal naming the entity, its surface and the position given.
function M.walk_inventory(p,e,a,pos)
  if a.inventory~=nil then
    local named=type(a.inventory)=='string' and M.inventory_name(e,a.inventory) or a.inventory
    if pcall(inventory,e,named) then return tostring(a.inventory) end
  else
    for _,dir in ipairs(a.direction and {a.direction} or {'to_player','to_entity'}) do
      local args={}
      for k,v in pairs(a) do args[k]=v end
      args.direction=dir
      local ok,name=pcall(infer_inventory,e,args)
      if ok then return name end
    end
  end
  local okp,q=pcall(position,pos)
  local at=okp and (q.x~=e.position.x or q.y~=e.position.y) and string.format(' (position (%g,%g) is on its footprint)',q.x,q.y) or ''
  error(string.format('%s at (%g,%g) on %s%s has no %s: nothing walked; %s',e.name,e.position.x,e.position.y,e.surface and e.surface.name or p.surface.name,at,
    a.inventory~=nil and 'inventory '..tostring(a.inventory) or 'inventory a transfer reaches',M.inventory_names(e)),0)
end
function M.transfer_walk_go(p,a,args,entities,far,fill,ticks,invs)
  local via=args.via
  args.via=nil
  -- All in reach: the transfer at once (a fill is its total there).
  if far==0 and not via then
    args.avoid=nil
    if fill then args.fill=nil; args.total=fill end
    return handlers.transfer(p,args)
  end
  if args.up_to==true then args.up_to=nil; args.partial=true end
  if args.direction==nil then
    -- As infer_direction, over the entities found (out of reach too).
    local mine,theirs=args.item and held(p,args.item,args.quality)+crafting_count(p,args.item) or 0,0
    local feeding=true
    for _,e in ipairs(entities) do if args.item then theirs=theirs+entity_holds(e,args.item,args.quality); if not M.feed_only(e,args.item,args.quality) then feeding=false end end end
    if args.item==nil or (theirs>0 and mine==0) then args.direction='to_player'
    elseif mine>0 and (theirs==0 or feeding) then args.direction='to_entity'
    elseif args.partial and mine==0 and theirs==0 then
      return {transferred=0,moved=0,short={asked=args.count or 'all',moved=0,reason='none_held'}}
    else
      error(string.format('direction is required (to_entity|to_player): the character holds %d %s and the target%s %d',
        mine,args.item,#entities>1 and 's hold' or ' holds',theirs),0)
    end
  end
  assert(args.item or args.direction=='to_player','item is required for to_entity')
  if args.direction=='to_entity' and held(p,args.item,args.quality)+crafting_count(p,args.item)==0 then
    if args.partial then return {transferred=0,moved=0,direction='to_entity',short={asked=args.count or 1,moved=0,reason='none_held'}} end
    error(string.format('no %s in inventory; nothing to give at %d place%s',args.item,#entities,#entities>1 and 's' or ''),0)
  end
  -- A walking take from chests that hold none of the item now (round1650d: Sonnet walked 66 tiles to an empty provider
  -- chest, Muse 44 tiles to an empty iron chest, each ending nothing_collected): refused before the walk, naming the
  -- nearest chest holding it. Machines are walked to: they may make it meanwhile.
  if args.direction=='to_player' and args.item and not fill then
    local any,chests=false,true
    for _,e in ipairs(entities) do
      if entity_holds(e,args.item,args.quality)>0 then any=true end
      if e.type~='container' and e.type~='logistic-container' and e.type~='linked-container' then chests=false end
    end
    if not any and chests then
      local e=entities[1]
      local okn,near=pcall(M.nearest_holding,p,args.item,args.quality,32,nil)
      local text=string.format('%s no %s now: nothing walked%s%s',#entities==1 and string.format('%s at (%g,%g) holds',e.name,e.position.x,e.position.y)
        or string.format('the %d places hold',#entities),args.item,#entities==1 and (M.stock_then(e,args.item) or '') or '',
        okn and near and string.format('; the nearest holding it: %s at (%g,%g), %.1f tiles from you, holds %d%s%s',
          near.entity.name,near.entity.position.x,near.entity.position.y,near.distance,near.count,M.reserved_text(near.reserved),
          near.feeds and ' ('..near.feeds..'; transfer from: "nearest" with feeding: true)' or ' (transfer from: "nearest")') or '; none within 32 tiles of you holds any')
      if args.partial then return {transferred=0,moved=0,direction='to_player',short={asked=args.count or 'all',moved=0,reason='source_empty'},note=text} end
      error(text,0)
    end
  end
  local avoid=args.avoid
  args.positions=nil; args.position=nil; args.fill=nil; args.avoid=nil
  -- What each source holds as the walk starts, and what robots have reserved there (Grok, 15:20: a provider emptied by
  -- robots before he arrived, three times): an empty take on arrival says it.
  local reserved_total=0
  if args.direction=='to_player' and args.item then
    for _,e in ipairs(entities) do
      local okr,r=pcall(M.supply.reserved,e,args.item)
      r=okr and r or 0
      reserved_total=reserved_total+r
      M.saw_stock(e,args.item,entity_holds(e,args.item,args.quality),r)
    end
  end
  local action,out=stock.start_tour(p,'transfer',entities,ticks,{transfer=args,item=args.item,quality=args.quality,rows={},items={},fill=fill,avoid_mode=avoid,
    avoid_enemies=a.avoid_enemies,unsafe_goal=a.unsafe_goal,via=via})
  if via then out.via=string.format('%d via point%s walked first, in order',#via,#via==1 and '' or 's') end
  if reserved_total>0 then
    out.reserved_note=string.format('robots have %d %s reserved to take at %s now: they may empty %s before you arrive',
      reserved_total,args.item,#entities>1 and 'these places' or 'it',#entities>1 and 'them' or 'it')
  end
  if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
  state().active[p.index]=action
  out.until_tick=action.until_tick; out.direction=args.direction; out.out_of_reach=far
  local stops=action.targets
  if via then
    stops={}
    for _,v in ipairs(via) do stops[#stops+1]={position=v} end
    for _,t in ipairs(action.targets) do stops[#stops+1]=t end
  end
  out.legs,out.legs_more=M.legs(p,stops)
  for i,row in ipairs(out.legs) do local e=stops[i].entity; row.inventory=invs and e and invs[e.unit_number or e] or nil end
  out.surface=p.surface.name
  return out
end
-- A walking call's route, one row per stop in the order it walks them (Opus 10:50: transfer and feed over positions
-- with reach errors at 10.x tiles): {position, name, walk (tiles from the stop before, or from you), in_reach (now)};
-- the first 16, and how many more.
function M.legs(p,targets)
  local rows,from=({}),p.position
  for i,t in ipairs(targets) do
    local e=t.entity
    local at=e and e.valid and e.position or t.position
    if i<=16 then
      local ok,reach=pcall(function() return e and p.can_reach_entity(e) end)
      rows[#rows+1]={position=at,name=e and e.valid and e.name or nil,walk=math.floor(distance(from,at)*10+0.5)/10,in_reach=ok and reach==true}
    end
    from=at
  end
  return rows,#targets>16 and #targets-16 or nil
end
-- transfer {item, from: "nearest", radius} (Haiku 10:50: an ammo chest held pipes and no magazines, which cost a
-- walk): our chests in reach, or within radius (1..64, walking there), that hold the item, as the map shows them (in
-- sight or by remote view); the take is made at the nearest, and the reply says which (from_nearest).
-- friction2 (Sonnet: the nearest held 20 of the 300 asked, 6 of 108 chests holding it; Grok took 40 iron plates from a
-- requester feeding a machine): the chests holding it nearest first, requester and buffer chests last (they feed
-- machines), and a count taken from as many of them as it takes.
M.NEAREST_TYPES={'container','logistic-container','linked-container'}
-- What a chest feeds: a requester or buffer chest's own name for it, or what an inserter that takes from it drops
-- into (a machine's input chest, a turret's feeder); nil for a chest nothing takes from.
function M.feeds(p,e,mode,item)
  -- A requester or buffer chest: its request for the item (Luna, d15: from nearest kept picking a requester).
  if mode=='requester' or mode=='buffer' then
    local okp,pt=pcall(function() return e.get_logistic_point(defines.logistic_member_index.logistic_container) end)
    if not (item and okp and pt and M.reqchest) then return 'a '..mode..' chest' end
    local min=M.reqchest.request(pt,item) or 0
    return 'a '..mode..' chest'..(min>0 and string.format(' requesting %d %s: robots bring it there for that request',min,item) or ' with no request for '..item)
  end
  local b=e.bounding_box
  local ok,list=pcall(function() return p.surface.find_entities_filtered{area={{b.left_top.x-3,b.left_top.y-3},{b.right_bottom.x+3,b.right_bottom.y+3}},type='inserter',force=p.force} end)
  for _,i in ipairs(ok and list or {}) do
    local okp,src=pcall(function() return i.pickup_target end)
    if okp and src==e then
      local okd,dst=pcall(function() return i.drop_target end)
      return string.format('%s (%g,%g) picks from it%s',i.name,i.position.x,i.position.y,okd and dst and dst.valid and ' into '..dst.name or '')
    end
  end
end
-- Whether an inserter takes from chest and drops into target (the chest is that machine's feed).
function M.feeds_into(p,chest,target)
  local b=chest.bounding_box
  local ok,list=pcall(function() return p.surface.find_entities_filtered{area={{b.left_top.x-3,b.left_top.y-3},{b.right_bottom.x+3,b.right_bottom.y+3}},type='inserter',force=p.force} end)
  for _,i in ipairs(ok and list or {}) do
    local okp,src=pcall(function() return i.pickup_target end)
    local okd,dst=pcall(function() return i.drop_target end)
    if okp and src==chest and okd and dst==target then return true end
  end
  return false
end
-- Items in a logistic chest robots are on their way to pick up (the game's targeted pickups; 0 for other entities).
function M.robot_reserved(e,item)
  local ok,point=pcall(function() return e.get_logistic_point(defines.logistic_member_index.logistic_container) end)
  local n=0
  for _,st in ipairs(ok and point and point.targeted_items_pickup or {}) do
    local name=type(st.name)=='table' and st.name.name or st.name
    if name==item then n=n+(st.count or 0) end
  end
  return n
end
-- Delivery is the hand move at this tick. Inserters and logistics can remove it afterward.
function M.delivery_note(p,e,item)
  local mode=e.prototype.logistic_mode
  if mode~='requester' and mode~='buffer' then return nil end
  local parts={mode..' chest: moved counts the hand delivery, not stock retained'}
  local point=e.get_logistic_point(defines.logistic_member_index.logistic_container)
  if point then
    parts[#parts+1]='trash unrequested '..(point.trash_not_requested and 'on' or 'off')
    local n=0
    for _,st in ipairs(point.targeted_items_pickup or {}) do
      local name=type(st.name)=='table' and st.name.name or st.name
      if not item or name==item then n=n+(st.count or 0) end
    end
    parts[#parts+1]=string.format('%d %s reserved for robot pickup now',n,item or 'items')
    if n>0 then parts[#parts+1]='robot delivery destinations are not read here; supply lists network reservations' end
  end
  local list=p.surface.find_entities_filtered{position=e.position,radius=4,type='inserter',force=p.force,limit=32}
  local count=0
  for _,ins in ipairs(list) do
    if ins.valid and ins.pickup_target==e then
      count=count+1
      if count<=4 then
        local dst=ins.drop_target
        parts[#parts+1]=string.format('%s (%g,%g) takes from this chest -> %s',ins.name,ins.position.x,ins.position.y,
          dst and dst.valid and string.format('%s (%g,%g)',dst.name,dst.position.x,dst.position.y) or 'no entity')
      end
    end
  end
  if count>4 then parts[#parts+1]=string.format('+%d local inserters',count-4) end
  if #list==32 then parts[#parts+1]='local inserter read capped at 32' end
  -- What the game does with what is over the request (Sonnet, d15: robots took a hand-fed item back), and one item in
  -- every slot while others are requested (reqchest.lua).
  local oko,over=pcall(M.reqchest.over,e,item)
  if oko and over then parts[#parts+1]=over end
  local oki,one=pcall(M.reqchest.one_item,e)
  if oki and one then parts[#parts+1]=one.line end
  return table.concat(parts,'; ')
end
-- friction2 and friction3: the chests holding it, nearest first; each says what it feeds (M.feeds), and those come
-- last (Grok took 40 iron plates from a requester feeding a machine; Sonnet took 1130 cable back out of the input
-- chests of the line it had just filled; Opus's tour took 20 rounds from each of 5 requesters feeding turrets).
function M.holding(p,item,quality,radius,exclude)
  local found,checked={},0
  for _,e in pairs(p.surface.find_entities_filtered{position=p.position,radius=radius,force=p.force,type=M.NEAREST_TYPES}) do
    if e.valid and e~=exclude and pcall(M.read_sight,p,e.position,'chest') then
      checked=checked+1
      local n=entity_holds(e,item,quality)
      if n>0 then
        local okm,mode=pcall(function() return e.type=='logistic-container' and e.prototype.logistic_mode or nil end)
        mode=okm and mode or nil
        local feeds=M.feeds(p,e,mode,item)
        -- what robots have reserved there (Grok, 15:20: three walks to a copper-cable provider robots emptied)
        local okr,r=pcall(M.supply.reserved,e,item)
        r=okr and r or 0
        found[#found+1]={entity=e,count=n,reserved=r,free=math.max(0,n-r),distance=distance(p.position,e.position),fed=feeds and true or nil,feeds=feeds,mode=mode}
      end
    end
  end
  table.sort(found,function(x,y)
    if (x.fed or false)~=(y.fed or false) then return not x.fed end
    if (x.free>0)~=(y.free>0) then return x.free>0 end
    return x.distance<y.distance
  end)
  return found,checked
end
function M.nearest_holding(p,item,quality,radius,exclude)
  local found,checked=M.holding(p,item,quality,radius,exclude)
  if found[1] then M.saw_stock(found[1].entity,item,found[1].count,found[1].reserved) end
  return found[1],checked,#found
end
-- A chest's stock of an item as last named to an agent (nearest_holding, a walking take's start), for the reply of an
-- empty take there: what it held then and how much robots had reserved (kept 10 min, at most 2000 entries).
M.stock_seen={n=0,by={}}
function M.saw_stock(e,item,n,reserved)
  local unit=e and e.valid and e.unit_number
  if not unit then return end
  local s=M.stock_seen
  if s.n>=2000 then s.by,s.n={},0 end
  local key=unit..'|'..item
  if not s.by[key] then s.n=s.n+1 end
  s.by[key]={n=n,reserved=reserved or 0,tick=game.tick}
end
function M.stock_then(e,item)
  local unit=e and e.valid and e.unit_number
  local seen=unit and M.stock_seen.by[unit..'|'..item]
  if not seen or game.tick-seen.tick>36000 or seen.n<=0 then return nil end
  return string.format('; it held %d %s %ds ago when named to you%s',seen.n,item,math.floor((game.tick-seen.tick)/60),
    seen.reserved>0 and string.format(', %d of it then reserved for robots to take',seen.reserved) or '')
end
function M.reserved_text(r) return r and r>0 and string.format(', %d of it reserved for robots to take',r) or '' end
-- transfer {item, from: "nearest", radius} (Haiku 10:50: an ammo chest held pipes and no magazines, which cost a
-- walk): our chests in reach, or within radius (1..256, walking there; walk: true alone, 32), that hold the item, as
-- the map shows them (in sight or by remote view). Left out unless feeding: true: chests that feed something
-- (M.feeds). Walking, also left out: chests in a worm's reach the map shows, and the legs go round them as move_to's
-- do (friction3: Opus's tour of 5 turret feeders walked into worm range and was killed). A count the nearest lacks
-- comes from the next ones, nearest first; one chest that holds it all, no farther than those, is taken alone
-- (Sonnet: a 600 take went 57 tiles west, then 107 east, past a chest holding 1000).
-- Chests an agent just filled (batch27 A7, Grok: from: nearest took a spoilable seed, or a count being lowered, back out
-- of the chest he had just put it in): each give by hand into a chest, by agent, chest and item, kept FILLED_TICKS;
-- from: nearest leaves such a chest out for the same agent and item (named by position, it is taken from as asked).
M.FILLED_TICKS=36000
function M.filled_mark(p,direction,e,stacks)
  if direction~='to_entity' or not (e.type=='container' or e.type=='logistic-container') or not e.unit_number then return end
  local st=state()
  st.filled=st.filled or {}
  local mine=st.filled[p.index] or {}
  st.filled[p.index]=mine
  for u,rec in pairs(mine) do
    local live=false
    for item,t in pairs(rec) do if game.tick-t>M.FILLED_TICKS then rec[item]=nil else live=true end end
    if not live then mine[u]=nil end
  end
  local rec=mine[e.unit_number] or {}
  mine[e.unit_number]=rec
  for _,s in ipairs(stacks or {}) do if s.name then rec[s.name]=game.tick end end
end
-- The tick p last put item into chest e by hand within FILLED_TICKS, or nil.
function M.filled_recently(p,e,item)
  local mine=(state().filled or {})[p.index]
  local t=mine and e.unit_number and mine[e.unit_number] and mine[e.unit_number][item]
  return t and game.tick-t<=M.FILLED_TICKS and t or nil
end
function M.from_nearest(p,a)
  assert(a.from=='nearest','from is "nearest" (the nearest chest holding the item)')
  assert(type(a.item)=='string' and prototypes.item[a.item],'from: "nearest" needs item')
  assert(a.direction==nil or a.direction=='to_player','from: "nearest" takes from a chest: direction to_player')
  assert(a.position==nil and a.positions==nil and a.area==nil,'from: "nearest" finds the chest: no position, positions or area')
  assert(a.feeding==nil or type(a.feeding)=='boolean','feeding must be true or false')
  local reach=p.reach_distance or 10
  local radius=a.radius~=nil and integer(a.radius,reach,1,256,'radius') or (a.walk==true and 32) or nil
  local found,checked=M.holding(p,a.item,a.quality,radius or reach+3,nil)
  local holding=#found
  if not radius then
    local kept={}
    for _,f in ipairs(found) do if p.can_reach_entity(f.entity) then kept[#kept+1]=f end end
    found=kept
  end
  -- What feeds something stays, unless asked; walking, what lies in a worm's reach stays too. A chest that feeds the
  -- target in `to` itself is no other machine's feed (Opus 12:20: refuelling a boiler from nearest left out the
  -- requester chest its own inserter fills it from): it is taken from as any chest, and named so.
  local mode=radius and M.avoid.mode(a.avoid_enemies) or nil
  local target
  if type(a.to)=='table' and (a.to.x or a.to[1] or a.to.position) then
    local okt,t=pcall(entity,p,{position=position(a.to.position or a.to)},true)
    target=okt and t or nil
  end
  local pool,fed,unsafe,filled={},{},{},{}
  if target then
    for _,f in ipairs(found) do
      if f.fed and M.feeds_into(p,f.entity,target) then f.fed=nil; f.feeds=nil; f.feeds_target=string.format('it feeds %s (%g,%g), the target',target.name,target.position.x,target.position.y) end
    end
    table.sort(found,function(x,y)
      if (x.fed or false)~=(y.fed or false) then return not x.fed end
      if (x.free>0)~=(y.free>0) then return x.free>0 end
      return x.distance<y.distance
    end)
  end
  for _,f in ipairs(found) do
    local ft=M.filled_recently(p,f.entity,a.item)
    if ft then f.filled_ago=math.floor((game.tick-ft)/60); filled[#filled+1]=f
    elseif f.fed and not a.feeding then fed[#fed+1]=f
    else
      local c=mode and not a.unsafe_goal and #pool<24 and not p.can_reach_entity(f.entity) and M.avoid.goal_check(p,p.position,f.entity.position,mode)
      if c then f.unsafe=M.avoid.goal_text(f.entity.name,f.entity.position,c); unsafe[#unsafe+1]=f
      else pool[#pool+1]=f end
    end
  end
  local function left_out()
    local parts={}
    if #fed>0 then
      local list={}
      for i=1,math.min(3,#fed) do local f=fed[i]; list[i]=string.format('%s (%g,%g) holds %d: %s',f.entity.name,f.entity.position.x,f.entity.position.y,f.count,f.feeds) end
      parts[#parts+1]=string.format('%d chest%s feeding something left out (feeding: true includes them): %s%s',#fed,#fed==1 and '' or 's',
        table.concat(list,'; '),#fed>3 and '; ...' or '')
    end
    if #unsafe>0 then parts[#parts+1]=string.format('%d in enemy reach left out: %s',#unsafe,unsafe[1].unsafe) end
    if #filled>0 then
      local f=filled[1]
      parts[#parts+1]=string.format('%d chest%s you put %s into in the last %d min left out (%s (%g,%g), %ds ago; name it by position to take from it)',
        #filled,#filled==1 and '' or 's',a.item,M.FILLED_TICKS/3600,f.entity.name,f.entity.position.x,f.entity.position.y,f.filled_ago)
    end
    return #parts>0 and table.concat(parts,'; ') or nil
  end
  -- A spoilable item (Luna 00:20: from nearest drew 75%-spoiled mash from a requester while fresher stock sat at a
  -- provider): each chest's stock read for how spoiled it is (count-weighted), the freshest first in steps of 10%, then
  -- the nearest; fresh: false keeps the nearest first.
  local spoils=(pcall(function() return prototypes.item[a.item].get_spoil_ticks()>0 end)) and prototypes.item[a.item].get_spoil_ticks()>0
  assert(a.fresh==nil or type(a.fresh)=='boolean','fresh must be true or false')
  local fresh_text
  if spoils and #pool>0 then
    for _,f in ipairs(pool) do
      local n,w=0,0
      pcall(function()
        local inv=f.entity.get_output_inventory() or f.entity.get_inventory(defines.inventory.chest)
        for i=1,#inv do
          local s=inv[i]
          if s.valid_for_read and s.name==a.item then n=n+s.count; w=w+s.count*(s.spoil_percent or 0) end
        end
      end)
      f.spoiled=n>0 and w/n or nil
    end
    if a.fresh~=false then
      table.sort(pool,function(x,y)
        local bx,by=math.floor((x.spoiled or 0)*10),math.floor((y.spoiled or 0)*10)
        if bx~=by then return bx<by end
        return x.distance<y.distance
      end)
    end
    local parts={}
    for i,f in ipairs(pool) do
      if i>4 then break end
      parts[#parts+1]=string.format('%s (%g,%g) %d%% spoiled',f.entity.name,f.entity.position.x,f.entity.position.y,math.floor((f.spoiled or 0)*100+0.5))
    end
    fresh_text=(a.fresh~=false and 'freshest first: ' or 'nearest first (fresh: false): ')..table.concat(parts,', ')
  end
  -- A count asked (A12, Grok: a courier went to the freshest chest, which held 2, and robots emptied it): the chests
  -- whose free stock (not reserved by robots) holds the count go first, in the order above; those holding less are
  -- skipped to the end, and named. None holding it all: the order stays.
  local skipped_small
  if a.count~=nil and #pool>1 then
    local n=tonumber(a.count) or 0
    -- (only those ahead of the first that holds it all move)
    local big,small={},{}
    for _,f in ipairs(pool) do if #big==0 and (f.free or f.count)<n then small[#small+1]=f else big[#big+1]=f end end
    if #big>0 and #small>0 then
      local parts={}
      for i,f in ipairs(small) do
        if i<=4 then parts[i]=string.format('%s (%g,%g) holds %d%s',f.entity.name,f.entity.position.x,f.entity.position.y,f.free or f.count,f.spoiled and string.format(' (%d%% spoiled)',math.floor(f.spoiled*100+0.5)) or '') end
      end
      skipped_small=string.format('%d chest%s holding fewer than %d skipped (the chests that hold it all go first): %s%s',#small,#small==1 and '' or 's',n,
        table.concat(parts,'; '),#small>4 and '; ...' or '')
      pool=big
      for _,f in ipairs(small) do pool[#pool+1]=f end
    end
  end
  local best=pool[1]
  if not best then
    local far=M.nearest_holding(p,a.item,a.quality,32,nil)
    local where=far and string.format('; the nearest within 32 tiles: %s at (%g,%g), %.1f tiles away, holds %d%s (radius=%d walks there)',
      far.entity.name,far.entity.position.x,far.entity.position.y,far.distance,far.count,M.reserved_text(far.reserved),math.min(256,math.ceil(far.distance)+1)) or '; none within 32 tiles holds any'
    if far and (#fed>0 or #unsafe>0 or #filled>0) then where='' end
    local why=left_out()
    local text=string.format('no chest %s holds %s (%d checked)%s%s',radius and ('within '..radius..' tiles') or 'in reach',a.item,checked,where,
      why and '; '..why or '')
    if a.up_to==true then return {moved=0,transferred=0,short={asked=a.count or 'all',moved=0,reason='source_empty'},note=text} end
    error(text,0)
  end
  -- A count more than the first holds: the next ones too, in that order, until they hold it (at most 16 chests); one
  -- that holds it all and is no farther than the farthest of those goes alone.
  local want=a.count~=nil and integer(a.count,1,1,10000,'count') or nil
  local use,have={},0
  for _,f in ipairs(pool) do
    if #use>=16 then break end
    use[#use+1]=f; have=have+f.count
    if not want or have>=want then break end
  end
  if want and #use>1 then
    local farthest=0
    for _,f in ipairs(use) do farthest=math.max(farthest,f.distance) end
    for _,f in ipairs(pool) do
      if f.free>=want and f.distance<=farthest then use={f}; have=f.count; best=f; break end
    end
  end
  for _,f in ipairs(use) do M.saw_stock(f.entity,a.item,f.count,f.reserved) end
  local args={}
  for k,v in pairs(a) do args[k]=v end
  args.from=nil; args.radius=nil; args.direction='to_player'; args.feeding=nil; args.fresh=nil
  args.positions={}
  for i,f in ipairs(use) do args.positions[i]={x=f.entity.position.x,y=f.entity.position.y,unit_number=f.entity.unit_number} end
  local out
  if a.to~=nil then
    -- with to (B1, Grok 22:50: a breeder fed the stalest nutrients, or two trips through the inventory): a courier from
    -- the first of these chests (freshest first, then nearest) that holds it, straight to the destination; a spoilable
    -- item's freshest stacks first (fresh: false, slot order).
    args.positions={}
    for i,f in ipairs(pool) do if i<=16 then args.positions[i]={x=f.entity.position.x,y=f.entity.position.y,unit_number=f.entity.unit_number} end end
    args.pick='first_with_stock'; args.direction=nil; args.walk=nil
    args.fresh_first=(spoils and a.fresh~=false) or nil
    out=handlers.transfer(p,args)
  else
    args.walk=radius~=nil or nil
    if args.walk then args.avoid=mode end
    if #use>1 then if args.walk then args.fill=want else args.total=want end end
    out=args.walk and M.transfer_walk(p,args) or handlers.transfer(p,args)
  end
  local why=left_out()
  out.source_freshness=fresh_text
  out.skipped_small=skipped_small
  if a.to~=nil then
    out.from_nearest=string.format('%d chest%s %s hold %s (%d checked)%s: the courier takes from the first holding it (picked), %s%s',#pool,#pool==1 and '' or 's',
      radius and ('within '..radius..' tiles') or 'in reach',a.item,checked,a.feeding and ', those feeding something last' or '',
      spoils and a.fresh~=false and 'freshest first (then the nearest), its freshest stacks first' or 'nearest first',why and '; '..why or '')
  elseif #use==1 then
    local e=best.entity
    out.from_nearest=string.format('%s at (%g,%g), %.1f tiles from you, holds %d %s%s%s (%d chest%s checked, %d holding it%s)%s',e.name,e.position.x,e.position.y,
      best.distance,best.count,a.item,M.reserved_text(best.reserved),best.fed and ' ('..best.feeds..')' or best.feeds_target and ' ('..best.feeds_target..')' or '',checked,checked==1 and '' or 's',holding,
      best.free==0 and '; every one holding it has all of it reserved for robots' or '',why and '; '..why or '')
  else
    local parts={}
    for i,f in ipairs(use) do
      parts[i]=string.format('%s (%g,%g) %.1f tiles, holds %d%s%s',f.entity.name,f.entity.position.x,f.entity.position.y,f.distance,f.count,M.reserved_text(f.reserved),f.fed and ' ('..f.feeds..')' or '')
    end
    out.from_nearest=string.format('%d chests hold %d of the %d asked, %s%s: %s (%d chest%s checked, %d holding it)%s',
      #use,have,want,fresh_text and a.fresh~=false and 'freshest first (then the nearest)' or 'nearest first',a.feeding and ', those feeding something last' or '',table.concat(parts,'; '),checked,checked==1 and '' or 's',holding,why and '; '..why or '')
  end
  return out
end
-- How much of an item a crafting machine's input takes by hand now (Muse, shift18 12:46: modules collected from one
-- machine's output piled up in the character, 78 and growing, because the next machine took no more). Measured on
-- 2.0.77: an assembler's, chemical plant's or furnace's input takes up to one stack plus 64 of each ingredient (50 ->
-- 114, 100 -> 164, 200 -> 264), whatever the machine; an item its recipe does not use, none. nil: not a crafting
-- machine's input (a chest, module or fuel slots), no recipe read, or the item goes elsewhere.
M.INPUT_OVER_STACK=64
function M.machine_room(e,item,quality)
  if not (e and e.valid and (e.type=='assembling-machine' or e.type=='furnace')) then return nil end
  local okr,recipe=pcall(function() return e.get_recipe() or (e.type=='furnace' and e.previous_recipe) end)
  if not okr or not recipe then return nil end
  local name=recipe.name
  if type(name)~='string' then name=name and name.name end
  local proto=name and prototypes.recipe[name]
  if not proto then return nil end
  local okn,inv_name=pcall(infer_inventory,e,{direction='to_entity',item=item,quality=quality})
  local input=e.type=='furnace' and 'furnace_source' or 'assembling_machine_input'
  local uses=false
  for _,ing in ipairs(proto.ingredients or {}) do if ing.type~='fluid' and ing.name==item then uses=true end end
  if not uses then
    if okn and inv_name~=input then return nil end
    return {room=0,why=string.format('its recipe %s does not use %s',name,item)}
  end
  local inv=e.get_inventory(defines.inventory[input])
  local held=inv and inv.get_item_count{name=item,quality=quality or 'normal'} or 0
  local cap=(prototypes.item[item] and prototypes.item[item].stack_size or 1)+M.INPUT_OVER_STACK
  local room=math.max(0,cap-held)
  return {room=room,held=held,cap=cap,why=room==0 and string.format('its input holds %d %s, as much as a hand puts in (one stack and %d)',held,item,M.INPUT_OVER_STACK) or nil}
end
-- transfer or collect {positions, item | items, pick, to} (Luna 07:57: a repeating seed courier walked 300+ tile laps
-- from empty seed chests). pick reads every listed place as inspect does (in sight or by remote view) and takes from
-- one: first_with_stock, the first in list order that holds a listed item now (its first listed item it holds);
-- most_stock, the one holding the most. Empty places are skipped (counted in skipped, never short); none holding any
-- ends the step at once, nothing walked. The take walks there when out of reach (as walk=true). to ({x,y}, or
-- {item: {x,y}} by the item picked) carries what was taken on to that destination in the same timed call and gives
-- it there (the inventory inferred as a give).
function M.pick_source(p,a,verb)
  assert(a.pick=='first_with_stock' or a.pick=='most_stock','pick is first_with_stock or most_stock')
  assert(a.direction==nil or a.direction=='to_player','pick takes from the listed places: direction to_player')
  assert(a.total==nil and a.area==nil and a.radius==nil,'pick goes with positions (not total, area or radius)')
  local list=a.positions or (a.position~=nil and {a.position}) or nil
  assert(type(list)=='table' and #list>=1 and #list<=64,'pick needs positions: 1..64 places to take from')
  local items,counts={},{}
  -- items as {name: count} (Luna, shift17 10:50: {"items":{"bioflux":5}} was refused, and items:["bioflux"] then moved the
  -- whole 24-item stack): the picked item's count caps the take, as count does.
  if type(a.items)=='table' and a.items[1]==nil and next(a.items)~=nil then
    local names={}
    for n in pairs(a.items) do names[#names+1]=n end
    table.sort(names)
    for _,n in ipairs(names) do items[#items+1]=n; counts[n]=integer(a.items[n],nil,1,100000,'items count for '..tostring(n)) end
  elseif type(a.items)=='table' then for _,n in ipairs(a.items) do items[#items+1]=n end elseif a.items~=nil then items[1]=a.items end
  if a.item~=nil then table.insert(items,1,a.item) end
  assert(#items>=1 and #items<=16,'pick needs item or items (1..16 item names, or {name: count})')
  for _,n in ipairs(items) do assert(type(n)=='string' and prototypes.item[n],'unknown item '..tostring(n)) end
  -- The destination per item: one {x,y} for all, or a map item -> {x,y}.
  local function is_pos(v) return type(v)=='table' and ((type(v.x)=='number' and type(v.y)=='number') or (type(v[1])=='number' and type(v[2])=='number')) end
  local dest
  if a.to~=nil then
    assert(type(a.to)=='table','to is {x,y} or {item: {x,y}}')
    if is_pos(a.to) then dest=function() return position(a.to) end
    else
      for _,n in ipairs(items) do assert(is_pos(a.to[n]),'to has no destination {x,y} for '..n) end
      dest=function(n) return position(a.to[n]) end
    end
  end
  local skipped,best={},nil
  for _,raw in ipairs(list) do
    local ok,e=pcall(entity,p,{position=raw,name=type(raw)=='table' and raw.name or a.name,unit_number=type(raw)=='table' and raw.unit_number or nil},true)
    if not ok then skipped[#skipped+1]={position=raw,error=reason(e)}
    else
      friendly(p,e)
      local item,n,reserved,held_reserved=nil,0,0,nil
      -- A listed belt is refused, naming pickup (its lanes are no inventory; Grok 12:21).
      if M.BELT_TYPES[e.type] then
        for _,name in ipairs(items) do local why,k=M.belt_refusal(e,name); if k>0 then error(why,0) end end
      end
      for _,name in ipairs(items) do
        local k
        if a.outputs_only then
          local ok,_,inv=pcall(infer_inventory,e,{outputs_only=true})
          k=ok and inv.get_item_count{name=name,quality=a.quality or 'normal'} or 0
        else k=entity_holds(e,name,a.quality) end
        -- What robots already reserved there is not there for a hand (Haiku, shift17 10:50: walked to a chest, then
        -- "holds no X now"): only the rest counts, read before the walk.
        local r=k>0 and M.robot_reserved(e,name) or 0
        if k-r>0 and (item==nil or (a.pick=='most_stock' and k-r>n-reserved)) then item,n,reserved=name,k,r end
        if k>0 and r>=k then held_reserved={name=name,count=k,reserved=r} end
        if item and a.pick=='first_with_stock' then break end
      end
      if not item then skipped[#skipped+1]={position=e.position,name=e.name,holds=held_reserved and held_reserved.count or 0,
        reserved=held_reserved and held_reserved.reserved or nil,why=held_reserved and 'all of it reserved for robot pickup' or nil}
      elseif not best or (a.pick=='most_stock' and n-reserved>best.count-best.reserved) then best={entity=e,item=item,count=n,reserved=reserved} end
    end
    if best and a.pick=='first_with_stock' then break end
  end
  local label=table.concat(items,' or ')
  if not best then
    return {moved=0,transferred=0,picked='none',skipped=#skipped,skipped_places=#skipped<=8 and skipped or nil,
      note=(function()
        local res=0
        for _,s in ipairs(skipped) do res=res+(s.reserved or 0) end
        return res>0 and string.format('none of the %d listed places holds %s now that robots have not reserved for pickup (%d reserved): nothing taken, nothing walked',#list,label,res)
          or string.format('none of the %d listed places holds %s now: nothing taken, nothing walked',#list,label)
      end)()}
  end
  local e=best.entity
  local picked={position=e.position,name=e.name,item=best.item,holds=best.count,rule=a.pick,reserved=best.reserved>0 and best.reserved or nil,
    line=string.format('%s at (%g,%g) holds %d %s%s (%s; %d listed place%s skipped)',e.name,e.position.x,e.position.y,best.count,best.item,
      best.reserved>0 and string.format(', %d of them reserved for robot pickup',best.reserved) or '',a.pick,#skipped,#skipped==1 and '' or 's')}
  -- fresh_first (B1, Grok 22:50), or fresh: true on a courier: the least spoiled stacks of it first.
  assert(a.fresh_first==nil or type(a.fresh_first)=='boolean','fresh_first must be true or false')
  local take={direction='to_player',item=best.item,quality=a.quality,outputs_only=a.outputs_only,count=counts[best.item] or a.count,keep=a.keep,keep_max=a.keep_max,inventory=a.from_inventory or a.inventory,
    up_to=a.up_to==true and true or nil,ticks=a.ticks,fresh_first=(a.fresh_first or (a.fresh_first==nil and a.fresh==true)) or nil,
    -- (batch19 A2, Grok twice: the courier's take dropped these, and moved the younger packs with the rotten left)
    spoiled_first=a.spoiled_first,min_spoil=a.min_spoil,min_spoiled=a.min_spoiled,max_fresh=a.max_fresh,min_fresh=a.min_fresh}
  -- With to on a crafting machine: what its input takes now, read before the take; none: nothing taken, nothing walked;
  -- else the take is at most that (the rest stays in the source).
  local to_takes
  if dest and a.inventory==nil then
    local to=dest(best.item)
    local okd,there=pcall(entity,p,{position=to},true)
    local okr,room=pcall(M.machine_room,okd and there or nil,best.item,a.quality)
    if okr and room then
      local where=string.format('%s at (%g,%g)',there.name,there.position.x,there.position.y)
      if room.room==0 then
        return {moved=0,transferred=0,picked=picked,skipped=#skipped,refused=where..': '..room.why,
          note=string.format('%s takes no %s now: %s; nothing taken, nothing walked',where,best.item,room.why)}
      end
      take.count=math.min(take.count or room.room,room.room)
      to_takes=string.format('%s takes %d %s now (its input holds %d of %d: one stack and %d); the take is at most that',where,room.room,best.item,room.held,room.cap,M.INPUT_OVER_STACK)
    end
  end
  -- With to, inventory goes with the place that has it (round1650d: Luna's and Grok's rocket_silo_rocket was tried on the
  -- chest taken from, "inventory is not applicable", and the courier ended nothing_collected): the give's for a silo or
  -- a machine at to, the take's for the picked place; refused when neither has it.
  local give_inventory
  if dest and a.inventory~=nil then
    local to=dest(best.item)
    local okt=pcall(inventory,e,a.inventory)
    local okd,there=pcall(entity,p,{position=to},true)
    local okg=okd and pcall(inventory,there,a.inventory)
    if okg then give_inventory=a.inventory end
    if not okt then take.inventory=nil end
    if not okt and okd and not okg then
      error(string.format('inventory %s is neither on %s at (%g,%g), the place taken from, nor on %s at (%g,%g), the place given to',
        tostring(a.inventory),e.name,e.position.x,e.position.y,there.name,there.position.x,there.position.y),0)
    end
    if not okt and not okd then give_inventory=a.inventory end
  end
  -- from_inventory and to_inventory (Grok 06:30: inventory went to both ends, so a machine's output could not go
  -- straight into another's input): each end its own.
  if a.to_inventory~=nil then give_inventory=a.to_inventory end
  local out,personal_note
  if not dest then
    take.positions={{x=e.position.x,y=e.position.y,unit_number=e.unit_number}}; take.walk=true; take.via=M.tour_via(a.via)
    out=M.transfer_walk(p,take)
  else
    -- Two legs in order: take at the picked place, then give what was taken at the destination (found on arrival
    -- when it is out of sight now).
    local to=dest(best.item)
    assert(not (math.abs(to.x-e.position.x)<0.01 and math.abs(to.y-e.position.y)<0.01),'to is the picked place itself')
    take.ticks=nil
    if take.up_to then take.up_to=nil; take.partial=true end
    local give={direction='to_entity',item=best.item,quality=a.quality,partial=true,give_taken=true,inventory=give_inventory}
    local found=pcall(entity,p,{position=to},true)
    local places={{entity=e,position=e.position},{position=to,find=not found or nil}}
    if found then places[2].entity=entity(p,{position=to},true) end
    local action=stock.start_legs(p,places,integer(a.ticks,18000,1,36000,'ticks'),{transfer=take,legs={take,give},item=best.item,quality=a.quality,rows={},items={},
      picked_line=picked.line,avoid_enemies=a.avoid_enemies,unsafe_goal=a.unsafe_goal,via=M.tour_via(a.via)})
    if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
    state().active[p.index]=action
    -- What passes through your inventory over a personal request's max is trashed (D3): said, or personal logistics
    -- switched off for the move (personal_logistics: "pause"; back on when it ends).
    assert(a.personal_logistics==nil or a.personal_logistics=='pause','personal_logistics is "pause": your personal logistic requests off for this move, back on when it ends')
    local room=M.trash.room(p,best.item,a.quality)
    local carry=take.count or best.count
    if a.personal_logistics=='pause' then
      local c=p.character
      local rp=c and c.valid and c.get_requester_point()
      if rp and rp.enabled then rp.enabled=false; action.personal_paused=true end
      personal_note=action.personal_paused and 'your personal logistic requests are off for this move (personal_logistics: pause); back on when it ends' or nil
    elseif room and carry>room then
      personal_note=string.format('your personal request for %s has max %d (you hold %d): what you carry over it the game moves to your trash slots, so about %d of %d would arrive; personal_logistics: "pause" switches your requests off for the move',
        best.item,M.trash.cap(M.trash.limits(p),best.item,a.quality) or 0,(M.trash.cap(M.trash.limits(p),best.item,a.quality) or 0)-room,room,carry)
    end
    out={op='transfer',item=best.item,places=2,until_tick=action.until_tick,direction='to_player',to=to,
      to_line=string.format('then gives it at (%g,%g)%s',to.x,to.y,found and '' or ' (out of sight now: found on arrival)')}
  end
  out.picked=picked; out.skipped=#skipped; out.skipped_places=#skipped>0 and #skipped<=8 and skipped or nil
  out.to_takes=to_takes
  out.personal_logistics=personal_note
  if verb=='collect' then out.direction=nil end
  return out
end
-- Several items at one entity use one reach check and, when needed, one walk.
-- Validate the entire map before moving anything; each item reports its own shortfall.
function M.transfer_items_one(p,a,e)
  local rows,items,total,asked,fresh,errors={},{},0,0,nil,0
  local names={}
  for name in pairs(a.items) do names[#names+1]=name end
  table.sort(names)
  for _,name in ipairs(names) do
    local args={}
    for k,v in pairs(a) do args[k]=v end
    args.items=nil; args.item=name; args.count=a.items[name]
    if args.up_to==true then args.up_to=nil; args.partial=true end
    local ok,out=pcall(transfer_one,p,args,nil,e)
    local moved=ok and out.transferred or 0
    local row={item=name,requested=args.count,transferred=moved}
    if ok then
      for k,v in pairs(out) do if k~='transferred' and k~='fresh' then row[k]=v end end
      if out.fresh then fresh=M.fresh_merge(fresh or {},out.fresh) end
    else row.error=reason(out); errors=errors+1 end
    if moved<args.count then row.missing=args.count-moved end
    rows[#rows+1]=row; total=total+moved; asked=asked+args.count
    if moved>0 then items[#items+1]={name=name,count=moved,quality=a.quality} end
  end
  if errors==#rows then error(string.format('all %d items failed, nothing moved; first %s: %s',errors,rows[1].item,rows[1].error),0) end
  return {transferred=total,requested=asked,items=items,entries=rows,direction=a.direction,fresh=M.fresh_list(fresh),
    short=total<asked and {asked=asked,moved=total,missing=asked-total,reason='items_short'} or nil}
end
function M.transfer_items(p,a)
  assert(type(a.items)=='table','items must be an item-to-count map')
  assert(a.item==nil and a.count==nil and a.total==nil,'items supplies each item and count; item, count and total are exclusive with items')
  assert(a.position~=nil and a.positions==nil and a.to==nil,'items without pick requires one position')
  assert(a.direction=='to_entity' or a.direction=='to_player','items requires direction to_entity or to_player')
  assert(a.walk==nil or type(a.walk)=='boolean','walk must be true or false')
  assert(a.ticks==nil or a.walk==true,'ticks applies with walk')
  assert(a.up_to==nil or a.up_to==true or type(a.up_to)=='number','up_to must be a number (target cap) or true (move what there is)')
  if type(a.up_to)=='number' then integer(a.up_to,1,1,100000,'up_to') end
  if a.keep~=nil then integer(a.keep,0,0,100000,'keep') end
  assert(a.keep_max==nil or type(a.keep_max)=='boolean','keep_max must be true or false')
  assert(a.quality==nil or (type(a.quality)=='string' and prototypes.quality[a.quality]),'unknown quality')
  local n=0
  for name,count in pairs(a.items) do
    assert(type(name)=='string' and prototypes.item[name],'items keys must be item names: '..tostring(name))
    integer(count,1,1,10000,'items.'..name); n=n+1
  end
  assert(n>=1 and n<=32,'items requires 1..32 item counts')
  local e=entity(p,a,a.walk==true)
  friendly(p,e)
  if a.walk~=true or p.can_reach_entity(e) then return M.transfer_items_one(p,a,e) end
  local args={}
  for k,v in pairs(a) do args[k]=v end
  args.walk=nil; args.ticks=nil; args.position=nil
  local action,out=stock.start_tour(p,'transfer',{e},integer(a.ticks,3600,1,36000,'ticks'),
    {transfer=args,rows={},items={},avoid_mode=a.avoid,avoid_enemies=a.avoid_enemies,unsafe_goal=a.unsafe_goal})
  if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
  state().active[p.index]=action
  out.until_tick=action.until_tick; out.direction=a.direction; out.item_count=n
  out.legs,out.legs_more=M.legs(p,action.targets)
  return out
end
local transfer_directed
-- A teammate by name (d17 batch16 B2, Muse: transfer {to: "haiku"} could not hand over a uranium-235; players lists
-- humans only): their player and character, or an error naming the agents.
function M.teammate(p,name)
  assert(type(name)=='string' and name~='','to_player is a teammate\'s name (a give to them); a take into your inventory is direction: "to_player"')
  local want=name:lower()
  local names={}
  for _,ag in ipairs(M.board.agents() or {}) do
    local human=not M.bots.is_index(ag.index) and not (state().controlled and state().controlled[ag.index])
    if ag.index~=p.index and not human then
      names[#names+1]=ag.name
      if ag.name:lower()==want or tostring(ag.display_name or ''):lower()==want then
        local pl=M.lookup(ag.index)
        local c=pl and pl.valid and pl.character
        assert(c and c.valid,ag.name..' has no character now (dead, or riding a cargo pod)')
        return pl,c,ag.name
      end
    end
  end
  table.sort(names)
  error('no teammate '..name..'; teammates: '..table.concat(names,', '),0)
end
-- A give to a teammate (B2): as a player can, the items are dropped at the teammate's feet (loot their character picks
-- up while it stands within reach of it); their character must be within your reach. Nothing goes into their
-- inventory directly: a player cannot open another's.
function M.give_teammate(p,a)
  local pl,c,name=M.teammate(p,a.to_player or a.to)
  assert(c.surface==p.surface,name..' is on '..c.surface.name..', you are on '..p.surface.name)
  if not p.can_reach_entity(c) then
    error(string.format('%s\'s character at (%.1f,%.1f) is %.1f tiles away, out of your reach: move_to {position: {x: %.1f, y: %.1f}} first',
      name,c.position.x,c.position.y,distance(c.position,p.position),c.position.x,c.position.y),0)
  end
  local list
  if a.items~=nil then list=M.rocketload.items(a.items,'items')
  else
    assert(type(a.item)=='string' and prototypes.item[a.item],'item (or items) names what to give')
    list={{name=a.item,quality=a.quality or 'normal',count=integer(a.count,1,1,100000,'count')}}
  end
  local inv=main_inventory(p)
  assert(inv,'you have no inventory')
  local given,short={},{}
  for _,r in ipairs(list) do
    local held=inv.get_item_count({name=r.name,quality=r.quality})
    local n=math.min(held,r.count)
    if n>0 then
      local took=inv.remove({name=r.name,quality=r.quality,count=n})
      if took>0 then
        c.surface.spill_item_stack{position=c.position,stack={name=r.name,quality=r.quality,count=took},enable_looted=true,allow_belts=false}
        given[#given+1]=r.name..(r.quality~='normal' and '@'..r.quality or '')..' '..took
      end
    end
    if n<r.count then short[#short+1]=string.format('%s: asked %d, held %d',r.name,r.count,held) end
  end
  assert(#given>0,'you hold none of it: '..table.concat(short,'; '))
  return {to_player=name,given=given,at={x=c.position.x,y=c.position.y},short=#short>0 and short or nil,
    note=string.format('dropped at %s\'s feet (%.1f,%.1f): their character picks loot up within reach as it stands there; pickup takes what is left',name,c.position.x,c.position.y)}
end
-- to: "nearest_room" (batch29 C1, Grok: the copper provider's dump chests filled every few minutes): what you hold of
-- item (count, default all) into our chests in reach (radius, at most your reach) that have room for it, the nearest
-- first, each filled before the next; chest: a chest name or names only. Says which took how much, and the rest.
function M.to_nearest_room(p,a)
  assert(type(a.item)=='string' and prototypes.item[a.item],'to: "nearest_room" needs item')
  assert(a.position==nil and a.positions==nil,'to: "nearest_room" finds the chests: no position or positions')
  local reach=p.reach_distance or 10
  local radius=a.radius~=nil and integer(a.radius,reach,1,math.max(1,math.floor(reach)),'radius (up to your reach, '..math.floor(reach)..')') or reach
  local names
  if a.chest~=nil then
    names={}
    for _,n in ipairs(type(a.chest)=='table' and a.chest or {a.chest}) do assert(type(n)=='string' and prototypes.entity[n],'chest: a chest name or names'); names[n]=true end
  end
  local quality=a.quality or 'normal'
  local held=p.get_main_inventory().get_item_count{name=a.item,quality=quality}
  local want=a.count~=nil and math.min(held,integer(a.count,1,1,100000,'count')) or held
  assert(held>0,'you hold no '..a.item)
  local list={}
  for _,e in ipairs(p.surface.find_entities_filtered{position=p.position,radius=radius,type={'container','logistic-container'},force=p.force}) do
    if e.valid and (not names or names[e.name]) and p.can_reach_entity(e) then
      local inv=e.get_inventory(defines.inventory.chest)
      local room=inv and (pcall(function() return inv.get_insertable_count{name=a.item,quality=quality} end) and inv.get_insertable_count{name=a.item,quality=quality}) or 0
      if room>0 then list[#list+1]={e=e,room=room,d=distance(p.position,e.position)} end
    end
  end
  table.sort(list,function(x,y) return x.d<y.d end)
  local left,rows,lines=want,{},{}
  for _,c in ipairs(list) do
    if left<=0 then break end
    local out=transfer_one(p,{direction='to_entity',item=a.item,quality=a.quality,count=math.min(left,c.room),inventory='chest'},nil,c.e)
    local n=out.transferred or 0
    if n>0 then
      left=left-n
      rows[#rows+1]={name=c.e.name,position=c.e.position,moved=n}
      lines[#lines+1]=string.format('%s (%g,%g): %d',c.e.name,c.e.position.x,c.e.position.y,n)
    end
  end
  return {transferred=want-left,moved=want-left,item=a.item,chests=rows,
    line=string.format('%d %s into %d chest%s with room, nearest first: %s%s',want-left,a.item,#rows,#rows==1 and '' or 's',#lines>0 and table.concat(lines,', ') or 'none',
      left>0 and string.format('; %d not placed: no more room in chests of ours within %g tiles%s',left,radius,names and ' of that name' or '') or '')}
end
function handlers.transfer(p,a)
  if a.to=='nearest_room' then return M.to_nearest_room(p,a) end
  -- a teammate by name (B2): to_player, or to as a name
  if a.to_player~=nil or type(a.to)=='string' then return M.give_teammate(p,a) end
  -- from_inventory / to_inventory without to: the one end's inventory, as inventory (a take from, a give to).
  if a.to==nil and a.pick==nil and (a.from_inventory~=nil or a.to_inventory~=nil) then
    assert(a.inventory==nil,'inventory, or from_inventory and to_inventory: not both')
    local args={}
    for k,v in pairs(a) do if k~='from_inventory' and k~='to_inventory' then args[k]=v end end
    if a.from_inventory~=nil and a.to_inventory~=nil then error('from_inventory and to_inventory together go with to (take at position, give at to)',0) end
    if a.from_inventory~=nil then
      assert(a.direction==nil or a.direction=='to_player','from_inventory takes from the target: direction to_player')
      args.direction='to_player'; args.inventory=a.from_inventory
    else
      assert(a.direction==nil or a.direction=='to_entity','to_inventory gives to the target: direction to_entity')
      args.direction='to_entity'; args.inventory=a.to_inventory
    end
    return handlers.transfer(p,args)
  end
  if a.pick~=nil then return M.pick_source(p,a,'transfer') end
  if a.from~=nil then return M.from_nearest(p,a) end
  assert(a.radius==nil,'radius goes with from: "nearest"')
  if a.items~=nil then return M.transfer_items(p,a) end
  -- unit_number without position (opus, shift62 06:26: a spidertron's ammo by its number failed on a nil position):
  -- the entity by its number, at its position.
  if a.position==nil and a.positions==nil and a.to==nil then
    assert(a.unit_number~=nil,'transfer requires position (or positions, pick + positions, from: "nearest", to_player, unit_number)')
    assert(type(a.unit_number)=='number','unit_number must be a number')
    local e=M.by_unit_number(p,a.unit_number,'position={x,y},unit_number=%d')
    local args={}
    for k,v in pairs(a) do args[k]=v end
    args.position={x=e.position.x,y=e.position.y}
    return handlers.transfer(p,args)
  end
  -- to on the entity position names, at another of its tiles (a 9x9 silo): the one entity named twice, a give there.
  if a.items==nil and a.to~=nil and a.position~=nil and a.positions==nil and (a.direction==nil or a.direction=='to_entity') then
    local ok,e,there=pcall(function()
      return entity(p,{position=position(a.position),unit_number=a.unit_number},true),entity(p,{position=position(a.to)},true)
    end)
    if ok and e==there then
      local args={}
      for k,v in pairs(a) do args[k]=v end
      args.to=nil; args.direction='to_entity'
      local out=handlers.transfer(p,args)
      if type(out)=='table' then
        out.corrected=string.format('to (%g,%g) is on %s (%g,%g), the entity position names: a give there',position(a.to).x,position(a.to).y,e.name,
          e.position.x,e.position.y)
      end
      return out
    end
  end
  -- position and to (Grok 06:30: a machine's output into another machine's input): a take there and a give at to, as
  -- pick with that one place (from_inventory and to_inventory name each end's inventory).
  if a.to~=nil and a.position~=nil and a.positions==nil and a.pick==nil and a.items==nil and (a.direction==nil or a.direction=='to_player') and a.item~=nil then
    local args={}
    for k,v in pairs(a) do if k~='position' and k~='direction' then args[k]=v end end
    args.positions={a.position}; args.pick='first_with_stock'
    local out=handlers.transfer(p,args)
    if type(out)=='table' then out.corrected='position and to: take at position, give at to (a courier, as pick with that one place)' end
    return out
  end
  -- (Muse, shift11 17:18: to beside position, four times in a rocket load)
  if a.to~=nil then
    error('to goes with pick (pick + positions + item or items + to: take at the first listed place holding it, give at to); for this call: '
      ..M.transfer_example(a),0)
  end
  assert(a.walk==nil or type(a.walk)=='boolean','walk must be true or false')
  -- via (C5, Luna 18:20): points walked in order before the first stop; a walking transfer.
  if a.via~=nil and not a.walked then
    assert(a.walk~=false,'via walks: not with walk: false')
    local args={}
    for k,v in pairs(a) do args[k]=v end
    args.via=M.tour_via(a.via); args.walk=true; a=args
  end
  assert(a.ticks==nil or a.walk==true,'ticks applies with walk')
  if a.walk==true then return M.transfer_walk(p,a) end
  -- Targets out of reach within 32 tiles (autowalk.lua; Haiku 22:53: a boiler 10.5 and 11.5 tiles off, a retry with
  -- walk: true each time): the call walks to them first, as walk: true does, and its reply says so (walking).
  if a.walk==nil and not a.walked and a.total==nil then
    local far,n=M.unreached(p,a)
    local worst=far and M.autowalk.wanted('transfer',a,far)
    if worst then
      local args={}
      for k,v in pairs(a) do args[k]=v end
      args.walk=true
      local out=M.transfer_walk(p,args)
      if type(out)=='table' then out.walking=M.autowalk.line(far,n,worst) end
      return out
    end
  end
  if a.walk==false then
    local args={}
    for k,v in pairs(a) do args[k]=v end
    args.walk=nil; a=args
  end
  assert(a.direction==nil or a.direction=='to_entity' or a.direction=='to_player','direction must be to_entity or to_player')
  assert(a.item==nil or type(a.item)=='string','item must be a string')
  assert(a.up_to==nil or a.up_to==true or type(a.up_to)=='number','up_to must be a number (target cap) or true (move what there is)')
  assert(a.keep_max==nil or type(a.keep_max)=='boolean','keep_max must be true or false')
  if a.up_to==true then
    local args={}
    for k,v in pairs(a) do args[k]=v end
    args.up_to=nil; args.partial=true
    a=args
  end
  if a.direction~=nil then return transfer_directed(p,a) end
  local args={}
  for k,v in pairs(a) do args[k]=v end
  local ok,dir,dir_note=pcall(infer_direction,p,a)
  -- up_to=true with the item on neither side: a short, not an error.
  if not ok and a.partial and tostring(dir):find('holds 0 .- and the targets? holds? 0') then
    local asked=a.count~=nil and integer(a.count,1,1,10000,'count')*#(a.positions or {a.position}) or 'all'
    return {transferred=0,moved=0,short={asked=asked,moved=0,reason='none_held'}}
  end
  assert(ok,dir)
  args.direction=dir
  local out=transfer_directed(p,args)
  out.direction=args.direction
  if dir_note and type(out)=='table' then out.direction_note=dir_note end
  return out
end
-- transfer {retry_when_clear: true} (d17 batch21 D2, Muse: guns fed in a hot zone refused 3 times for an attack there),
-- as rearm's: a refusal for passing enemies only (an attack, units or a group seen now; none for a worm or spawner)
-- waits until no enemy unit is within 48 tiles of the first place held (wait_until units_clear, retry_ticks, default
-- 5 min), then transfers again, at most 6 times.
M.transfer_now=handlers.transfer
function M.tour_stock() return stock end
function handlers.transfer(p,a)
  -- (d24 batch154, the batch149 review's bug 4) the engine's "Unknown item name: X" is said as the harness's
  if a.retry_when_clear==nil then
    local ok,out=pcall(M.transfer_now,p,a)
    if ok then return out end
    error(M.argforms.unknown_item(a,out),0)
  end
  assert(type(a.retry_when_clear)=='boolean','retry_when_clear must be true or false')
  local rest={}
  for k,v in pairs(a) do if k~='retry_when_clear' and k~='retry_ticks' and k~='retries' then rest[k]=v end end
  if not a.retry_when_clear then return M.transfer_now(p,rest) end
  local tries=integer(a.retries,0,0,6,'retries')
  local ticks=integer(a.retry_ticks,18000,600,54000,'retry_ticks')
  stock.last_refusal=nil
  local ok,out=pcall(M.transfer_now,p,rest)
  if ok then return out end
  local r=stock.last_refusal
  if not (r and r.tick==game.tick and (r.passing or 0)>0 and (r.staying or 0)==0 and r.at) or tries>=6 then error(out,0) end
  local w=handlers.wait_until(p,{['until']='units_clear',position=r.at,radius=48,timeout=ticks})
  local now=state().active[p.index]
  -- no unit there now (an area under attack counts 30 s past its last hit: d17 batch21 D2): 30 s, then again
  if not now then w=handlers.wait_ticks(p,{ticks=1800}); now=state().active[p.index]; w.cleared='no enemy unit within 48 tiles now; the area under attack counts 30 s past its last hit' end
  if now then
    local again={}
    for k,v in pairs(rest) do again[k]=v end
    again.retry_when_clear=true; again.retry_ticks=ticks; again.retries=tries+1
    now.then_call={action='transfer',args=again}
  end
  w.retry=string.format('refused for passing enemies only: %s; waits until no enemy unit is within 48 tiles of (%g,%g) (at most %d s), then transfers again (try %d of 6)',
    reason(out),r.at.x,r.at.y,math.floor(ticks/60),tries+1)
  return w
end
transfer_directed=function(p,a)
  assert(a.item or a.direction=='to_player','item is required for to_entity')
  assert(a.item or (a.keep==nil and a.up_to==nil),'keep and up_to require item')
  if a.direction=='to_entity' and a.total==nil then
    local targets={}
    for i,pos in ipairs(a.positions or {a.position}) do targets[i]={position=pos} end
    local waiting=await_feed(p,'transfer',a,a.item,shortfall(p,a,targets))
    if waiting then return waiting end
  end
  if not a.positions then
    local out=transfer_one(p,a,a.position)
    if a.item and a.count~=nil then out.requested=integer(a.count,1,1,10000,'count') end
    if a.partial then return short_facts(out,a,1) end
    assert(not out.none_held,out.none_held and string.format('no %s in inventory%s; the target has %d',a.item,
      prototypes.item[a.item] and prototypes.item[a.item].type=='ammo' and ' or ammo slots' or '',out.target_has))
    return M.give_short(out,a,1)
  end
  assert(type(a.positions)=='table' and #a.positions>=1 and #a.positions<=64,'positions requires 1..64 entries')
  -- One unit_number cannot identify several entities; put it on the entries.
  assert(a.unit_number==nil,'with positions, give unit_number per entry: {x,y,unit_number}')
  -- total caps the whole batch, filled in order; count stays per entity.
  if a.total~=nil then
    assert(a.item,'total requires item')
    local cap=integer(a.total,1,1,100000,'total')
    local args={}
    for k,v in pairs(a) do args[k]=v end
    args.budget={cap=cap,left=cap}
    args.count=a.count or math.min(cap,10000)
    a=args
  end
  local targets={}
  for i,pos in ipairs(a.positions) do targets[i]={position=pos} end
  local out=transfer_batch(p,a,targets,false)
  if a.partial then return short_facts(out,a,#targets) end
  return M.give_short(out,a,#targets)
end
end local function queue_names(force)
  local names={}
  for i,technology in ipairs(force.research_queue or {}) do names[i]=technology.name end
  return names
end
-- What unlocks a trigger technology, in words: labs never research these.
local function trigger_text(t)
  local r=t.prototype.research_trigger
  if not r then return nil end
  local function name(v) return type(v)=='table' and (v.name or tostring(v)) or tostring(v) end
  if r.type=='craft-item' then return string.format('craft %d %s',r.count or 1,name(r.item)) end
  if r.type=='craft-fluid' then return string.format('produce %g %s',r.amount or 0,name(r.fluid)) end
  if r.type=='mine-entity' then return 'mine '..name(r.entity) end
  if r.type=='build-entity' then return 'build '..name(r.entity) end
  if r.type=='send-item-to-orbit' then return 'launch '..name(r.item)..' to orbit' end
  if r.type=='capture-spawner' then return 'capture '..(r.entity and name(r.entity) or 'a biter spawner') end
  if r.type=='create-space-platform' then return 'create a space platform' end
  return r.type
end
-- How many entries of a technology the queue can hold: a leveled one (an infinite technology, mining-productivity-3)
-- one per level still to research, each entry the next level, as the research GUI queues them (C2, Sol 16:50: a
-- repeated entry was dropped here, not by the game); any other one.
function M.research_slots(force,name)
  local t=type(name)=='string' and force.technologies[name]
  if not t then return 1 end
  local ok,n=pcall(function() return t.prototype.max_level>t.prototype.level and t.prototype.max_level-t.level+1 or 1 end)
  return ok and math.max(1,n) or 1
end
-- Why a technology cannot be queued behind `queued` (name: entries) right now; nil if it can.
local function research_block(force,name,queued)
  local t=type(name)=='string' and force.technologies[name]
  if not t then return 'unknown' end
  if t.researched then return 'already_researched' end
  if not t.enabled then return 'not_enabled' end
  if t.prototype.research_trigger then return 'trigger_unlocked ('..trigger_text(t)..')' end
  if queued[name] and queued[name]>=M.research_slots(force,name) then return 'duplicate' end
  local missing={}
  for pre_name,pre in pairs(t.prerequisites) do
    if not (pre.researched or queued[pre_name]) then missing[#missing+1]=pre_name end
  end
  if #missing>0 then
    table.sort(missing)
    return 'prerequisites_not_queued (needs '..table.concat(missing,', ')..')'
  end
end
-- Like the game GUI: every requested technology is preceded by its unresearched
-- prerequisites (recursively, dependency order, each once) unless the list
-- already has them earlier. added maps a requested name to what was inserted.
local function with_prerequisites(force,list)
  local out,seen,added={},{},{}
  local function visit(name,root)
    local t=type(name)=='string' and force.technologies[name]
    if not t or t.researched or seen[name] then return end
    seen[name]=true
    local pres={}
    for pre_name,pre in pairs(t.prerequisites) do
      if not pre.researched and not seen[pre_name] then pres[#pres+1]=pre_name end
    end
    table.sort(pres)
    for _,pre_name in ipairs(pres) do
      if not seen[pre_name] then
        visit(pre_name,root)
        added[root]=added[root] or {}
        table.insert(added[root],pre_name)
      end
    end
    out[#out+1]=name
  end
  local times={}
  for _,name in ipairs(list) do
    local t=type(name)=='string' and force.technologies[name]
    times[name]=(times[name] or 0)+1
    if t and not t.researched and not seen[name] then visit(name,name)
    elseif not seen[name] then seen[name]=true; out[#out+1]=name
    elseif times[name]<=M.research_slots(force,name) then out[#out+1]=name end
  end
  -- Report inserted prerequisites in queue order.
  local position={}
  for i,name in ipairs(out) do position[name]=i end
  for _,names in pairs(added) do table.sort(names,function(x,y) return position[x]<position[y] end) end
  return out,next(added) and added or nil
end
-- Sets the engine queue, reads it back and gives every entry that did not land
-- a reason. Entries that can land later (queue full, prerequisites still
-- pending) become the force's plan, which tick feeds in as slots free up.
local function set_research_queue(force,list)
  local added,asked=nil,list
  list,added=with_prerequisites(force,list)
  local wanted,queued,reasons={},{},{}
  for _,name in ipairs(list) do
    local why=research_block(force,name,queued)
    if why then reasons[tostring(name)]=why else wanted[#wanted+1]=name; queued[name]=(queued[name] or 0)+1 end
  end
  force.research_queue=wanted
  local queue,landed=queue_names(force),{}
  for _,name in ipairs(queue) do landed[name]=(landed[name] or 0)+1 end
  local skipped,pending,seen={},{},{}
  for _,name in ipairs(list) do
    name=tostring(name)
    seen[name]=(seen[name] or 0)+1
    if seen[name]>(landed[name] or 0) and reasons[name]~='duplicate' then
      local why=reasons[name] or 'queue_full'
      -- Entries that can land later are kept and fed in, not dropped.
      if why=='queue_full' or why:find('^prerequisites_not_queued') then pending[#pending+1]=name
      else skipped[#skipped+1]=name..': '..why end
    end
  end
  local plans=state().research_plan or {}
  state().research_plan=plans
  plans[force.name]=#pending>0 and {names=pending,queued=#queue} or nil
  -- A technology named more times than it has levels to research is queued that many times (C2, Sol 16:50).
  local count,once={},{}
  for _,name in ipairs(asked) do name=tostring(name); count[name]=(count[name] or 0)+1 end
  for name,n in pairs(count) do
    local slots=M.research_slots(force,name)
    if n>slots then once[#once+1]=string.format('%s: named %d times, queued %d (%s)',name,n,slots,slots==1 and 'it has one level to research' or slots..' levels left to research') end
  end
  table.sort(once)
  return {queue=queue,over_levels=#once>0 and once or nil,skipped=#skipped>0 and skipped or nil,pending=#pending>0 and pending or nil,
    pending_note=#pending>0 and 'the engine queue is full (or prerequisites are pending): these are fed in as it frees up' or nil,added_prerequisites=added}
end
do local function array_of_names(list)
  assert(type(list)=='table' and #list<=64 and (#list>0 or next(list)==nil),'research_queue requires an array of 0..64 names')
  return list
end
-- research_queue replaces the queue; with front it goes ahead of the current
-- queue, with append behind it. A lone technology is added (or put in front).
function handlers.research(p,a)
  local force=p.force
  -- Target levels for leveled technologies (researchtarget.lua; Sol 16:50).
  if a.target_level~=nil or a.targets~=nil then
    assert(a.technology==nil and a.research_queue==nil and a.remove==nil and a.cancel==nil and a.move==nil,'target_level and targets go alone')
    local set=a.target_level~=nil and M.research_target.set(force,a.target_level) or nil
    local rows=M.research_target.read(force)
    local lines={}
    for i,r in ipairs(rows) do lines[i]=r.line end
    return {set=set,targets=lines,queue=queue_names(force),
      note='each target keeps its technology coming: when it is neither researching nor queued and the queue has room, the next level is added to the end of the queue; at most 16 targets, 100 levels past the one researching'}
  end
  local current=queue_names(force)
  -- Adding keeps names still waiting for room behind the engine queue.
  local plan=state().research_plan and state().research_plan[force.name]
  local waiting=plan and plan.names or {}
  local function with_waiting(list)
    local seen={}
    for _,name in ipairs(list) do seen[name]=true end
    for _,name in ipairs(waiting) do if not seen[name] then seen[name]=true; list[#list+1]=name end end
    return list
  end
  -- remove (or cancel) and move: edit the queue as the research GUI does
  -- (research.lua without/moved); the names waiting beyond the engine queue count.
  local drop=a.remove; if drop==nil then drop=a.cancel end
  if drop~=nil or a.move~=nil then
    assert(a.technology==nil and a.research_queue==nil and a.front==nil and a.append==nil,'remove and move go without technology, research_queue, front or append')
    assert(drop==nil or a.move==nil,'remove or move, one per call')
    local list={}
    for _,name in ipairs(current) do list[#list+1]=name end
    list=with_waiting(list)
    local edit
    if drop~=nil then list,edit=M.research.without(force,list,drop) else list=M.research.moved(force,list,a.move,a.to) end
    local out=set_research_queue(force,list)
    if edit then out.removed=edit.removed; out.also_removed=edit.also end
    return out
  end
  if a.research_queue then
    local list=array_of_names(a.research_queue)
    assert(not (a.front and a.append),'use front or append, not both')
    if a.front or a.append then
      local merged,seen={},{}
      local first,second=list,current
      if a.append then first,second=current,list end
      for _,part in ipairs{first,second} do
        for _,name in ipairs(part) do
          seen[name]=(seen[name] or 0)+1
          if seen[name]==1 or a.append and seen[name]<=M.research_slots(force,name) then merged[#merged+1]=name end
        end
      end
      list=with_waiting(merged)
    end
    return set_research_queue(force,list)
  end
  -- No arguments: report, as observe does, instead of refusing.
  if a.technology==nil then
    assert(a.front==nil and a.append==nil,'technology or research_queue is required with front/append')
    local active=force.current_research
    local out={queue=current,pending=#waiting>0 and waiting or nil}
    if active then out.current=active.name; out.progress=force.research_progress
    else out.current=false; out.note='no research in progress: pass technology=name or research_queue=[...] (technologies available=true lists what can be researched)' end
    -- Each entry in full: progress, who queued it, packs, time to finish (research.lua).
    local view=M.research.queue(force,waiting)
    out.entries=view.entries; out.throughput=view.throughput; out.clock_stops_at=view.clock_stops_at
    local targets={}
    for i,r in ipairs(M.research_target.read(force)) do targets[i]=r.line end
    out.targets=#targets>0 and targets or nil
    return out
  end
  local technology=force.technologies[a.technology]
  assert(technology,'unknown technology '..tostring(a.technology))
  -- Appending may rely on prerequisites already queued; the front may not.
  local queued={}
  if not a.front then for _,name in ipairs(current) do queued[name]=true end end
  queued[technology.name]=nil
  local why=research_block(force,technology.name,queued)
  local needs=why and why:find('^prerequisites_not_queued')
  assert(not why or needs,'technology cannot be researched: '..tostring(why))
  -- Missing prerequisites go in ahead of it, as the game GUI does.
  if needs and not a.front then
    local list={}
    for _,name in ipairs(current) do if name~=technology.name then list[#list+1]=name end end
    list[#list+1]=technology.name
    return set_research_queue(force,with_waiting(list))
  end
  if not a.front or #current==0 and not needs then
    local queued=force.add_research(technology)
    if queued or #current==0 then return {queued=queued,queue=queue_names(force)} end
    -- Refused with an item ahead of it: the engine queue is full; wait for room.
    local list={}
    for _,name in ipairs(current) do list[#list+1]=name end
    for _,name in ipairs(waiting) do if name~=technology.name then list[#list+1]=name end end
    list[#list+1]=technology.name
    return set_research_queue(force,list)
  end
  -- The first queue entry is the active research; displaced progress is kept.
  local list={technology.name}
  for _,name in ipairs(current) do if name~=technology.name then list[#list+1]=name end end
  local out=set_research_queue(force,with_waiting(list))
  -- With the queue disabled by map settings, add_research replaces the current one.
  if not needs and out.queue[1]~=technology.name then out.queued=force.add_research(technology); out.queue=queue_names(force) end
  return out
end
end -- Who queued what (research.lua): names that were neither queued nor waiting
-- before this agent's research call are this agent's.
do
  local queue_research=handlers.research
  local function known(force)
    local seen={}
    for _,name in ipairs(queue_names(force)) do seen[name]=true end
    local plan=state().research_plan and state().research_plan[force.name]
    for _,name in ipairs(plan and plan.names or {}) do seen[name]=true end
    return seen
  end
  handlers.research=function(p,a)
    local before=known(p.force)
    local out=queue_research(p,a)
    local fresh={}
    for name in pairs(known(p.force)) do if not before[name] then fresh[#fresh+1]=name end end
    table.sort(fresh)
    if #fresh>0 then M.research.record(p.force.name,fresh,M.board.who(p)) end
    return out
  end
end
-- Feeds a force's pending plan into the engine queue once it has shrunk.
local function feed_research_plans()
  for name,plan in pairs(state().research_plan or {}) do
    local force=game.forces[name]
    if not (force and force.valid) then state().research_plan[name]=nil
    else
      local current=queue_names(force)
      if #current<plan.queued then
        local list=current
        for _,n in ipairs(plan.names) do list[#list+1]=n end
        set_research_queue(force,list)
      end
    end
  end
end
function handlers.research_next(p,a)
  assert(type(a.technologies)=='table' and #a.technologies>0 and #a.technologies<=64,'technologies requires 1..64 names')
  for _,name in ipairs(a.technologies) do assert(type(name)=='string' and p.force.technologies[name],'unknown technology') end
  if p.force.current_research then return {current=p.force.current_research.name,started=false} end
  for _,name in ipairs(a.technologies) do
    local t=p.force.technologies[name]
    local ready=t.enabled and not t.researched and not t.prototype.research_trigger
    for _,pre in pairs(t.prerequisites) do if not pre.researched then ready=false end end
    if ready then
      local started=p.force.add_research(t)
      if started then M.research.record(p.force.name,{name},M.board.who(p)) end
      return {started=started,current=name}
    end
  end
  return {started=false,current=false}
end
do local function catalog(p,a,kind)
  local limit=integer(a.limit,64,1,256,'limit')
  local prefix=a.prefix or ''; assert(type(prefix)=='string','prefix must be a string')
  local names={}
  -- available: unresearched technologies whose prerequisites are all done.
  local function available(entry)
    if entry.researched then return false end
    for _,pre in pairs(entry.prerequisites) do if not pre.researched then return false end end
    return true
  end
  -- (d19 batch45 2: 19 recipes calls with name in shifts 39-41 each listed 64 recipes, name unread) name: that one (or
  -- a list of names), refused when unknown or not enabled, with names that start alike
  if a.name~=nil then
    local list=type(a.name)=='string' and {a.name} or a.name
    assert(type(list)=='table' and #list>=1 and #list<=64,'name is a '..(kind=='recipes' and 'recipe' or 'technology')..' name or a list of 1..64')
    for _,n in ipairs(list) do
      local entry=type(n)=='string' and p.force[kind][n]
      if not (entry and entry.enabled) then
        local like={}
        for other,o in pairs(p.force[kind]) do
          if #like<6 and o.enabled and type(n)=='string' and (other:find(n,1,true) or n:find(other,1,true)) then like[#like+1]=other end
        end
        table.sort(like)
        error(string.format('%s: no %s of that name%s',tostring(n),entry and 'enabled '..(kind=='recipes' and 'recipe' or 'technology') or (kind=='recipes' and 'recipe' or 'technology'),
          #like>0 and ' (names like it: '..table.concat(like,', ')..')' or ''),0)
      end
      names[#names+1]=n
    end
  else
  for name,entry in pairs(p.force[kind]) do
    if entry.enabled and name:sub(1,#prefix)==prefix and not (a.available and kind=='technologies' and not available(entry)) then names[#names+1]=name end
  end
  end
  table.sort(names)
  local out={entries={},truncated=#names>limit}
  for i=1,math.min(#names,limit) do
    local entry=p.force[kind][names[i]]
    if kind=='recipes' then
      out.entries[i]={name=entry.name,ingredients=entry.ingredients,products=entry.products,energy=entry.energy}
      -- Crafts and output per minute at crafting speed 1 or at a.machine's speed, with research and the machine's own productivity.
      local okr,rate=pcall(M.craftrate.recipe,p.force,entry,a.machine)
      if okr then out.entries[i].rate=rate.line elseif a.machine~=nil then error(tostring(rate):gsub('^.-:%d+: ',''),0) end
    else
      local prerequisites={}
      for name,pre in pairs(entry.prerequisites) do prerequisites[#prerequisites+1]={name=name,researched=pre.researched} end
      table.sort(prerequisites,function(x,y) return x.name<y.name end)
      -- (d18 batch39 A3) a technology with levels (an infinite one reads researched false for ever): the levels done
      local okm,max=pcall(function() return entry.prototype.max_level end)
      local leveled=okm and (max or 1)>1
      out.entries[i]={name=entry.name,researched=entry.researched,level=entry.level,
        levels_done=leveled and (entry.researched and entry.level or math.max(0,(entry.level or 1)-1)) or nil,max_level=leveled and max or nil,
        prerequisites=prerequisites,ingredients=entry.research_unit_ingredients,
        count=not entry.prototype.research_trigger and entry.research_unit_count or nil,energy=not entry.prototype.research_trigger and entry.research_unit_energy or nil,
        trigger=trigger_text(entry)}
    end
  end
  return out
end
function handlers.recipes(p,a) return catalog(p,a,'recipes') end
function handlers.technologies(p,a) return catalog(p,a,'technologies') end
end -- The client that renders a screenshot: a player's own. A bot has none, and
-- without by_player every connected client rendered it into its own
-- script-output (shake1/2: ./shot never delivered), so one is chosen: the
-- first connected director, else the first connected player.
do local function screenshot_client(p)
  local own=real(p)
  if own then return own end
  local pick
  for _,pl in pairs(game.connected_players) do
    if pl.valid then
      local rank=M.is_director(pl.index) and 0 or 1
      if not pick or rank<pick.rank or (rank==pick.rank and pl.index<pick.player.index) then pick={player=pl,rank=rank} end
    end
  end
  return pick and pick.player
end
-- position (with surface= or platform=, bots.lua's lists) centres the shot there by remote view (d20 batch56 R2,
-- Enginerd 14:42: 5 of 19 shots came right after a 143-606 tile walk): the engine draws what stands there now, fog or
-- not, so every chunk of the frame (32 px a tile at zoom 1) must be one our force sees now, as remote view shows it.
-- Without position the shot is centred on the character, as before.
function handlers.screenshot(p,a)
  assert(type(a.path)=='string' and #a.path<=160 and a.path:match('^[%w_/-]+%.png$') and not a.path:find('..',1,true) and a.path:sub(1,1)~='/','path must be a relative PNG path')
  local w,h=integer(a.width,1280,320,1920,'width'),integer(a.height,720,240,1080,'height')
  local remote=type(p)=='table' and rawget(p,'__remote')
  assert(a.position~=nil or not remote,'screenshot with surface needs position there (your character stands on another surface)')
  local at,by=p.position,nil
  if a.position~=nil then
    at=position(a.position)
    by=M.read_sight(p,at,'screenshot centre')
    local lt,rb={x=at.x-w/64,y=at.y-h/64},{x=at.x+w/64,y=at.y+h/64}
    local _,n,unseen=M.area_sight(p,lt,rb)
    if #unseen>0 then
      local list={}
      for i,c in ipairs(unseen) do if i<=6 then list[i]=string.format('(%d,%d)-(%d,%d)',c.x*32,c.y*32,c.x*32+31,c.y*32+31) end end
      error(string.format('the frame (%g,%g)-(%g,%g) (%dx%d px, 32 px a tile) takes in %d of %d chunks our force does not see now: %s%s',
        lt.x,lt.y,rb.x,rb.y,w,h,#unseen,n,table.concat(list,', '),#unseen>6 and ', ...' or ''),0)
    end
  end
  local client=screenshot_client(p)
  assert(client,'no graphical client is connected to render a screenshot')
  local s=p.surface
  game.take_screenshot{player=real(p),by_player=client,surface=s,position=at,path=a.path,resolution={x=w,y=h},zoom=1,show_entity_info=true}
  -- (d21 batch66 AB2, Sol #1602: a shot of platform Solstice at (0,0) from Fulgora, its sprites drawn at low resolution,
  -- was read as Fulgora round his body) every reply names the surface and centre the engine was given, the frame, and
  -- what of ours stands in it, so the image can be checked against them
  local platform=type(p)=='table' and rawget(p,'__platform') or nil
  local lt,rb={x=at.x-w/64,y=at.y-h/64},{x=at.x+w/64,y=at.y+h/64}
  local by_name,ghosts,n={},0,0
  for _,e in ipairs(s.find_entities_filtered{area={lt,rb},force=p.force,limit=2000}) do
    if e.type=='entity-ghost' or e.type=='tile-ghost' then ghosts=ghosts+1
    elseif e.type~='character' then by_name[e.name]=(by_name[e.name] or 0)+1; n=n+1 end
  end
  local names={}
  for name,c in pairs(by_name) do names[#names+1]={name,c} end
  table.sort(names,function(x,y) return x[2]>y[2] or (x[2]==y[2] and x[1]<y[1]) end)
  local list={}
  for i,v in ipairs(names) do if i<=8 then list[i]=v[1]..' '..v[2] end end
  local where=platform and string.format('platform %s (surface %s)',platform,s.name) or s.name
  local line=string.format('rendered on %s centred (%g,%g)%s: frame (%g,%g)-(%g,%g), %gx%g tiles; ours in it: %s%s%s',where,at.x,at.y,
    a.position==nil and (platform and ' (the hub)' or ' (your character)') or '',lt.x,lt.y,rb.x,rb.y,w/32,h/32,
    #list>0 and table.concat(list,', ') or 'nothing',#names>8 and string.format(' and %d more names',#names-8) or '',
    ghosts>0 and string.format('; %d ghost%s',ghosts,ghosts==1 and '' or 's') or '')
  return {queued=true,path=a.path,client=client.name,requires_graphical_client=true,position={x=at.x,y=at.y},
    surface=s.name,platform=platform,frame={left_top=lt,right_bottom=rb},in_frame=by_name,ghosts_in_frame=ghosts,line=line,by=by}
end
end function handlers.revive_ghost(p,a)
  local e=entity(p,a); friendly(p,e)
  assert(e.type=='entity-ghost','target must be an entity ghost')
  local needed=e.ghost_prototype
  local quality=e.quality.name
  local item
  for i=1,#p.get_main_inventory() do
    local stack=p.get_main_inventory()[i]
    if stack.valid_for_read and stack.quality.name==quality and stack.prototype.place_result==needed then item=stack.name; break end
  end
  assert(item,'no matching building item and quality in inventory')
  local direction
  for name,value in pairs(directions) do if value==e.direction then direction=name end end
  assert(direction,'unsupported ghost direction')
  local result=handlers.build(p,{item=item,quality=quality,position=e.position,direction=direction})
  result.revived=not e.valid
  return result
end
-- Equipment grids (grids.lua): the armor's, or a vehicle's by vehicle= (operator 09:13, a viewer via Astra).
M.grids=require('grids'){position=position,out_of_reach=function(p,e) return M.out_of_reach(p,e) end}
function handlers.equipment(p,a)
  local op=a.operation or 'list'
  assert(op=='insert' or op=='remove' or op=='list','operation must be insert, remove or list')
  local grid,where=M.grids.target(p,a,op=='list')
  if op=='list' then local out=M.grids.view(grid,true); out.where=where; out.armor=where=='armor' and M.grids.armor(p.character) or nil; return out end
  local inv=p.get_main_inventory()
  if op=='insert' then
    assert(type(a.item)=='string','item required')
    local stack=inv.find_item_stack{name=a.item,quality=a.quality or 'normal'}
    assert(stack and stack.prototype.place_as_equipment_result,'equipment item missing')
    local pos=a.position and position(a.position)
    if pos then integer(pos.x,nil,0,grid.width-1,'x'); integer(pos.y,nil,0,grid.height-1,'y') end
    local equipment=grid.put{name=stack.prototype.place_as_equipment_result.name,quality=stack.quality,position=pos,by_player=real(p)}
    if not equipment then
      local v=M.grids.view(grid)
      error(string.format('%s does not fit in %s %s (%d free cells%s)',a.item,where,v.grid,v.free_cells,pos and string.format(', at (%d,%d)',pos.x,pos.y) or ''),0)
    end
    stack.count=stack.count-1
    return {inserted=equipment.name,position=equipment.position,where=where,grid=M.grids.view(grid)}
  end
  local pos=position(a.position)
  local equipment=grid.get(pos); assert(equipment,'equipment not found')
  local item={name=equipment.prototype.take_result.name,quality=equipment.quality.name,count=1}
  assert(inv.can_insert(item),'main inventory has no space for removed equipment')
  local removed=grid.take{equipment=equipment,by_player=real(p)}
  assert(removed,'equipment removal failed')
  local inserted=inv.insert(removed)
  if inserted<removed.count then
    p.surface.spill_item_stack{position=p.position,stack={name=removed.name,quality=removed.quality,count=removed.count-inserted},enable_looted=true,force=p.force}
  end
  return {removed=removed.name,where=where,grid=M.grids.view(grid)}
end
-- The character's gun slots: each gun, the ammo slot beside it and its count, and the gun's range (its attack
-- parameters, as the tooltip gives it).
function M.gun_rows(p)
  local guns=p.get_inventory(defines.inventory.character_guns)
  local ammo=p.get_inventory(defines.inventory.character_ammo)
  local out={}
  for i=1,guns and #guns or 0 do
    local g,am=guns[i],ammo and ammo[i]
    if g.valid_for_read then
      local okr,range=pcall(function() return prototypes.item[g.name].attack_parameters.range end)
      local loaded=am and am.valid_for_read
      out[#out+1]={index=i,gun=g.name,ammo=loaded and am.name or nil,count=loaded and am.count or 0,range=okr and range or nil}
    end
  end
  return out
end
-- Area ammunition (d17 batch19 D1, Opus: one explosive rocket at a spawner took ~19 of our solar panels and poles, and
-- auto-fired rockets cut our belts twice): the blast radius of an ammo item, the largest area its own action or its
-- projectile's attack and final attack hit (read on 2.0.77: explosive-rocket 6.5, explosive-cannon-shell 4,
-- explosive-uranium-cannon-shell 4.25; a plain rocket or bullet: none), cached.
M.BLAST={}
function M.blast_radius(ammo)
  if M.BLAST[ammo]~=nil then return M.BLAST[ammo] or nil end
  local best=0
  local seen={}
  local function walk(t,depth)
    if type(t)~='table' or depth>12 or seen[t] then return end
    seen[t]=true
    if t.type=='area' and type(t.radius)=='number' and t.radius>best then best=t.radius end
    for k,v in pairs(t) do
      if k=='projectile' and type(v)=='string' then
        local pr=prototypes.entity[v]
        if pr then
          local ok,r=pcall(function() return pr.attack_result end); if ok then walk(r,depth+1) end
          local ok2,f=pcall(function() return pr.final_attack_result end); if ok2 then walk(f,depth+1) end
        end
      elseif type(v)=='table' then walk(v,depth+1) end
    end
  end
  local okp,at=pcall(function() return prototypes.item[ammo].get_ammo_type() end)
  if okp and at then walk(at.action,0) end
  M.BLAST[ammo]=best>0 and best or false
  return best>0 and best or nil
end
-- The character's own blast (d17 batch21 C1, Opus: killed by his own rocket's splash with biters touching him): with
-- area ammunition in the gun, enemy units within MELEE tiles of the character, or the aim point inside the blast's
-- radius of it: the gun slot switches to one holding ammunition without an area (said in last_combat.switched_gun), or,
-- with none, fire holds (held_melee). Checked every 5 ticks; returns the target to fire at (nil: hold).
M.MELEE=6
function M.melee_guard(p,action,target,tick)
  if not (action.blast and target) then return target end
  local c=p.character
  if not (c and c.valid) then return target end
  local here=c.position or p.position
  if tick%5==0 or action.melee_near==nil then
    local okn,near=pcall(function() return p.surface.find_entities_filtered{position=here,radius=M.MELEE,force='enemy',type={'unit','spider-unit'},limit=1}[1] end)
    action.melee_near=okn and near and near.valid and {name=near.name,d=distance(here,near.position)} or false
  end
  local self=distance(here,target)<=action.blast.radius
  if not (action.melee_near or self) then return target end
  local why=action.melee_near and string.format('%s %.1f tiles from you',action.melee_near.name,action.melee_near.d)
    or string.format('the aim point is %.1f tiles from you, inside the %g-tile blast',distance(here,target),action.blast.radius)
  local okg,guns=pcall(M.gun_rows,p)
  for _,g in ipairs(okg and guns or {}) do
    if g.count>0 and g.ammo and not M.blast_radius(g.ammo) then
      c.selected_gun_index=g.index
      action.switched_gun=string.format('%s: switched to gun slot %d %s with %s (%s would burst on you)',why,g.index,g.gun,g.ammo,action.blast.ammo)
      action.blast=nil
      return target
    end
  end
  action.held_melee=string.format('held fire: %s, and no gun slot holds ammunition without an area (%s bursts %g tiles round where it hits)',why,action.blast.ammo,action.blast.radius)
  action.held_melee_n=(action.held_melee_n or 0)+1
  return nil
end
-- Our entities a blast of radius r at pos would reach (characters left out): {n, line} or nil.
function M.blast_hits(p,pos,r)
  local by,order,n={},{},0
  for _,e in ipairs(p.surface.find_entities_filtered{position=pos,radius=r,force=p.force,limit=200}) do
    if e.valid and e.type~='character' and e.type~='entity-ghost' and e.type~='tile-ghost' and e.type~='item-request-proxy' then
      n=n+1
      if not by[e.name] then by[e.name]={n=0,at=e.position}; order[#order+1]=e.name end
      by[e.name].n=by[e.name].n+1
    end
  end
  if n==0 then return nil end
  table.sort(order,function(x,y) return by[x].n>by[y].n end)
  local parts={}
  for i,name in ipairs(order) do if i<=6 then parts[#parts+1]=string.format('%d %s (one at (%g,%g))',by[name].n,name,by[name].at.x,by[name].at.y) end end
  return {n=n,line=string.format('%d of ours within its %g-tile blast at (%g,%g): %s%s',n,r,pos.x,pos.y,table.concat(parts,', '),#order>6 and ', ...' or '')}
end
function M.shoot_sight(p,pos,slot)
  if visible(p,pos) then return end
  local sel=slot or (p.character and p.character.selected_gun_index)
  local range
  local okg,guns=pcall(M.gun_rows,p)
  for _,g in ipairs(okg and guns or {}) do if g.index==sel then range=g.range end end
  local limit=math.max(32,range or 0)
  local d=distance(p.position,pos)
  local seen=own_platform(p) or p.force.is_chunk_visible(p.surface,chunk_of(pos))
  if d<=limit and seen then return end
  error(string.format('firing position (%g,%g) is %.1f tiles from you%s; shoot aims within %g tiles (32, or the selected gun\'s range%s, the larger) at a point in a chunk our force sees now',
    pos.x,pos.y,d,seen and '' or ' in a chunk our force does not see now',limit,range and string.format(': %g',range) or ''),0)
end
function handlers.shoot(p,a)
  local ticks=integer(a.ticks,60,1,MAX_TICKS,'ticks')
  assert(a.fire_anyway==nil or type(a.fire_anyway)=='boolean','fire_anyway must be true or false')
  -- vehicle=: a vehicle's guns (operator 08:32). Seated in it, as below; by remote view the game fires them for a
  -- gunner seated in it or a player driving it remotely, and an agent's character has no player (vehicles.lua).
  if a.vehicle~=nil then
    local sat=p.character and p.character.valid and p.character.vehicle
    local same=sat and sat.valid and ((type(a.vehicle)=='number' and sat.unit_number==a.vehicle)
      or (type(a.vehicle)=='table' and distance(sat.position,position(a.vehicle.position or a.vehicle))<=3))
    if not same then
      error('shoot vehicle=: an agent fires a vehicle\'s guns only seated in it (vehicle {position, enter: true}); by remote view the game fires them for a gunner seated in it or a player driving it remotely, and an agent\'s character has no player',0)
    end
  end
  -- Seated: the vehicle's gun (vehicles.lua), aimed at an entity the gunner selects.
  if p.character and p.character.valid and p.character.vehicle then
    local back=M.retreat.config(p,a,'shoot')
    local action,out,target=M.vehicles.shoot(p,a,ticks)
    state().combat=state().combat or {}
    combat_targets()[p.index]=target and {fixed=target} or nil
    state().combat[p.index]=action
    if M.retreat.arm(p,action,back) and type(out)=='table' then out.retreat=M.retreat.line(back) end
    return out
  end
  assert(a.gun==nil and a.ammo==nil,'gun and ammo pick a vehicle\'s gun (seated in a car, tank or spidertron); on foot gun_slot picks 1..3')
  local pos=a.position and position(a.position)
  assert(a.auto==true or pos,'specify position or auto=true')
  -- What the player could aim at (d17 batch20 C3, Opus: refused twice within his rocket launcher's 36 tiles): a point
  -- in a chunk our force sees now within 32 tiles or the selected gun's range, the larger.
  if pos then M.shoot_sight(p,pos,a.gun_slot) end
  local back=M.retreat.config(p,a,'shoot')
  if a.gun_slot then p.character.selected_gun_index=integer(a.gun_slot,nil,1,3,'gun_slot') end
  -- The engine fires from the ammo slots and spends what it fires; without
  -- ammo the trigger does nothing, so say so instead of "shooting". Empty
  -- slots are first filled from carried ammo (kite.auto_equip), and the reply says so.
  local equipped=kite.ammo_count(p)==0 and kite.auto_equip(p) or nil
  -- (d17 batch35 A2, Grok died at the north raft: rockets in the main inventory, the launcher's ammo slot empty) the
  -- selected gun's empty ammo slot is loaded from the main inventory first, as a player's click does, and said.
  local sel0=p.character and p.character.selected_gun_index
  local loaded,unloaded
  if sel0 then loaded,unloaded=M.ammoslots.load(p,sel0) end
  local ammo=kite.ammo_count(p)
  assert(ammo>0,'no ammunition in the ammo slots and none carried that fits a gun: craft firearm-magazine')
  -- The gun that fires (Sol, d15 07:50: the aggregated ammo count hid an empty rocket launcher; 10 s shoots used 0):
  -- the selected gun slot, the ammo slot beside it and its count, the gun's range, and why it will not fire.
  local gun_row,why
  local okg,guns=pcall(M.gun_rows,p)
  local sel=p.character and p.character.selected_gun_index
  for _,g in ipairs(okg and guns or {}) do if g.index==sel then gun_row=g end end
  local gun
  if gun_row then
    gun={slot=gun_row.index,name=gun_row.gun,range=gun_row.range,ammo_slot=gun_row.index,ammo=gun_row.ammo,count=gun_row.count}
    if gun_row.count==0 then
      local others={}
      for _,g in ipairs(guns) do if g.count>0 then others[#others+1]=string.format('slot %d %s has %s*%d',g.index,g.gun,g.ammo,g.count) end end
      -- Ammo that fits it in another ammo slot (Grok, shift19 00:36), and that slot's gun slot.
      local okr,r=pcall(M.ammoslots.read,p)
      local there=okr and M.ammoslots.elsewhere(r,gun_row.index)
      why={no_compatible_ammo=string.format('gun slot %d (%s) has nothing in ammo slot %d and your main inventory holds no ammunition it fires; nothing fires from it%s%s',gun_row.index,gun_row.gun,gun_row.index,
        #others>0 and '; '..table.concat(others,', ')..' (gun_slot picks it)' or '',
        there and '; '..there..'; equip {slot: ammo, item, index: '..gun_row.index..'} moves it between ammo slots' or '')}
    elseif pos and gun_row.range and distance(p.position,pos)>gun_row.range then
      why={out_of_range=string.format('%s reaches %g tiles; the target is %.1f away',gun_row.gun,gun_row.range,distance(p.position,pos))}
    end
  else
    gun={slot=sel,name='empty'}
    why={no_compatible_ammo=string.format('gun slot %s holds no gun',tostring(sel))}
  end
  -- Area ammunition: a fixed target whose blast reaches ours is refused; auto fire holds at such a target (D1).
  local blast=gun_row and gun_row.ammo and gun_row.count>0 and M.blast_radius(gun_row.ammo) or nil
  if blast and pos and a.fire_anyway~=true then
    local hit=M.blast_hits(p,pos,blast)
    if hit then
      error(string.format('%s bursts %g tiles round where it hits: %s; nothing fired (fire_anyway: true shoots anyway; gun_slot picks a gun without area ammunition)',
        gun_row.ammo,blast,hit.line),0)
    end
  end
  state().combat=state().combat or {}
  combat_targets()[p.index]=nil
  state().combat[p.index]={started=game.tick,until_tick=game.tick+ticks,position=pos,auto=a.auto==true,radius=integer(a.radius,24,1,32,'radius'),ammo_start=ammo,
    gun_used=gun,why_start=why,blast=blast and {radius=blast,ammo=gun_row.ammo} or nil,fire_anyway=a.fire_anyway==true or nil}
  M.retreat.arm(p,state().combat[p.index],back)
  local out={until_tick=game.tick+ticks,ammo=ammo,gun=gun,equipped=equipped,loaded=loaded,retreat=back and M.retreat.line(back) or nil}
  for k,v in pairs(why or {}) do out[k]=v end
  return out
end
-- (d17 batch35 A2) The shoot's gun ran dry mid-fight while its ammo was carried (Grok: one rocket in the slot, more in
-- the main inventory): the slot is loaded from the main inventory and the gun selected again, said in equipped; when
-- nothing carried fits it, dry says so once (last_combat).
function M.combat_reload(p,action)
  local g=action.gun_used
  local slot=g and g.name~='empty' and g.slot
  if not slot then return end
  local okr,r=pcall(M.ammoslots.read,p)
  if not (okr and r.guns[slot]) or r.ammo[slot] then return end
  local line,why=M.ammoslots.load(p,slot)
  if not line then
    if not action.dry then action.dry=string.format('gun slot %d ran dry at %ds: %s',slot,math.floor((game.tick-(action.started or game.tick))/60),why) end
    return
  end
  local okn,s=pcall(function() local st=p.get_inventory(defines.inventory.character_ammo)[slot]; return {name=st.name,count=st.count} end)
  action.ammo_start=(action.ammo_start or 0)+(okn and s.count or 0)
  action.reloads=(action.reloads or 0)+1
  action.equipped=action.equipped and action.equipped..'; '..line or line
  -- selected again unless the melee guard moved off it; the blast guard follows what is loaded now
  if not action.switched_gun then
    pcall(function() p.character.selected_gun_index=slot end)
    local blast=okn and M.blast_radius(s.name) or nil
    action.blast=blast and {radius=blast,ammo=s.name} or nil
  end
end
-- (d21 batch64 Z4) status's flight: a character in armor that provides flight, flying now or on the ground; nil else.
function M.flight_row(p)
  local c=p.character
  if not (c and c.valid and M.pathing.flies(c)) then return nil end
  local ok,f=pcall(function() return c.is_flying end)
  return ok and f and 'flying: it crosses water, walls and buildings (flying it collides only with spidertrons and pentapods); armor without flight put on now kills the character' or 'on the ground (armor with flight: it takes off when it walks into something)'
end
function handlers.equip(p,a)
  local names={gun='character_guns',ammo='character_ammo',armor='character_armor'}
  -- unequip (Grok, d15: a rocket ride refused ammo in the ammo slots, and equip could only put ammo in): the slot's
  -- stacks (index: one slot; item: that item) back to the main inventory, as the GUI's click on a slot does.
  if a.unequip~=nil then
    assert(a.unequip==true,'unequip must be true')
    assert(a.slot=='ammo' or a.slot=='gun','unequip takes slot "ammo" or "gun" (index? item?)')
    local inv=p.get_inventory(defines.inventory[names[a.slot]])
    local index=a.index~=nil and integer(a.index,nil,1,#inv,'index') or nil
    assert(a.item==nil or (type(a.item)=='string' and prototypes.item[a.item]),'item must be an item name')
    local main=p.get_main_inventory()
    local moved,left={},{}
    for i=1,#inv do
      local s=inv[i]
      if (index==nil or index==i) and s.valid_for_read and (a.item==nil or s.name==a.item) then
        local stack={name=s.name,count=s.count,quality=s.quality}
        local n=main.insert(stack)
        if n>0 then if n>=s.count then s.clear() else s.count=s.count-n end; moved[#moved+1]=string.format('%s*%d from %s slot %d',stack.name,n,a.slot,i) end
        if n<stack.count then left[#left+1]=string.format('%s*%d in %s slot %d (no room in your main inventory)',stack.name,stack.count-n,a.slot,i) end
      end
    end
    assert(#moved>0 or #left>0,'nothing in your '..a.slot..' slots'..(index and ' at index '..index or '')..(a.item and ' of '..a.item or '')..' to unequip')
    return {unequipped=#moved>0 and moved or nil,left=#left>0 and left or nil}
  end
  -- The slot from the item's kind when not given (Grok, shift19 00:36: equip {item: piercing-rounds-magazine}).
  if a.slot==nil and type(a.item)=='string' then
    local t=prototypes.item[a.item] and prototypes.item[a.item].type
    a.slot=t=='gun' and 'gun' or t=='ammo' and 'ammo' or t=='armor' and 'armor' or nil
  end
  assert(names[a.slot],'slot must be gun, ammo, or armor')
  local inv=p.get_inventory(defines.inventory[names[a.slot]])
  local index=a.index~=nil and integer(a.index,nil,1,#inv,'index') or nil
  assert(type(a.item)=='string','item required')
  -- (d21 batch64 Z4) a character that loses flight in the air dies: on a private 2.0.77 copy, equip power-armor over
  -- mech-armor while the character hovered beside a wall (is_flying) killed it; on the ground the change is safe.
  if a.slot=='armor' and type(a.item)=='string' then
    local c=p.character
    local okf,flying=pcall(function() return c and c.is_flying end)
    local proto=prototypes.item[a.item]
    if okf and flying and not (proto and proto.provides_flight) then
      error(string.format('armor: the character is flying now (%s provides flight, %s does not); in 2.0.77 a character that loses flight in the air dies (on a private copy this change made while it hovered killed it); it lands when it stops where it can stand, and status\'s flight then reads on the ground',
        M.pathing.flies(c) and (c.get_inventory(defines.inventory.character_armor)[1].name) or 'its armor',a.item),0)
    end
  end
  local source=p.get_main_inventory().find_item_stack(a.item)
  -- Ammo only in the ammo slots (Grok, shift19 00:36): moved between them. Without index it goes beside the selected
  -- gun when it fits that gun, else beside the first gun it fits.
  if not source and a.slot=='ammo' then
    local r=M.ammoslots.read(p)
    local held_at
    for j=1,r.n do if r.ammo[j] and r.ammo[j].name==a.item then held_at=held_at or j end end
    if held_at then
      local to=index
      if not to then
        local sel=p.character and p.character.selected_gun_index
        if sel and r.guns[sel] and M.ammoslots.fits(r.guns[sel].name,a.item) then to=sel
        else for i=1,r.n do if not to and r.guns[i] and M.ammoslots.fits(r.guns[i].name,a.item) then to=i end end end
      end
      if not to then error(string.format('%s is in ammo slot %d and no gun in your gun slots fires it; index picks the ammo slot',a.item,held_at),0) end
      if r.ammo[to] and r.ammo[to].name==a.item then
        return {equipped=a.item,slot='ammo',index=to,note=string.format('already in ammo slot %d (gun slot %d: %s)',to,to,r.guns[to] and r.guns[to].name or 'empty')}
      end
      local moved,why=M.ammoslots.move(p,a.item,to)
      if not moved then error(string.format('%s in ammo slot %d not moved to ammo slot %d: %s',a.item,held_at,to,why),0) end
      return {equipped=a.item,slot='ammo',index=to,moved_from=string.format('ammo slot %d',moved.from),
        swapped=moved.swapped and moved.swapped..' to ammo slot '..moved.from or nil,
        fired_by=string.format('gun slot %d: %s',to,r.guns[to] and r.guns[to].name or 'empty')}
    end
    error(a.item..' is not in your main inventory or ammo slots',0)
  end
  -- A gun already in a gun slot (Sol, d15 07:50): equip selects it.
  if not source and a.slot=='gun' then
    for i=1,#inv do
      if inv[i].valid_for_read and inv[i].name==a.item and (index==nil or index==i) then
        p.character.selected_gun_index=i
        return {selected=a.item,slot='gun',index=i,note='already in gun slot '..i..': selected'}
      end
    end
  end
  assert(source,'item is not in inventory')
  -- An omitted index tries compatible empty slots first. An explicit index
  -- always means that slot; failed swaps leave both stacks unchanged.
  if index==nil and a.slot~='armor' then
    for i=1,#inv do
      if not inv[i].valid_for_read and inv[i].swap_stack(source) then
        return {equipped=a.item,slot=a.slot,index=i}
      end
    end
  end
  index=index or 1
  if not inv[index].swap_stack(source) then
    local held=inv[index].valid_for_read and inv[index].name or 'empty'
    -- An occupied slot with room in the main inventory (Sol, d15 07:50: a pistol slot refused while main had room): the
    -- old stack goes to main, the new one in; put back when the game refuses the new one there.
    local main=p.get_main_inventory()
    local moved_out
    local okc,fits=pcall(function() return main.can_insert({name=inv[index].name,count=inv[index].count,quality=inv[index].quality}) end)
    if inv[index].valid_for_read and okc and fits then
      local old={name=inv[index].name,count=inv[index].count,quality=inv[index].quality}
      local n=main.insert(old)
      if n==old.count then
        inv[index].clear()
        if inv[index].transfer_stack(source) then moved_out=old
        else inv[index].set_stack(old); main.remove(old) end
      elseif n>0 then main.remove({name=old.name,count=n,quality=old.quality}) end
    end
    if not moved_out then
      error(string.format('%s cannot swap into %s slot %d (holds %s): incompatible item or displaced stack cannot fit; nothing moved',a.item,a.slot,index,held),0)
    end
    if a.slot=='gun' then p.character.selected_gun_index=index end
    return {equipped=a.item,slot=a.slot,index=index,replaced=moved_out.name..'*'..moved_out.count..' (to your inventory)'}
  end
  if a.slot=='gun' then pcall(function() p.character.selected_gun_index=index end) end
  return {equipped=a.item,slot=a.slot,index=index}
end
-- Why a ghost was not placed, and settings a pasted-over entity lacks (placewhy.lua).
M.placewhy=require('placewhy'){filters=function(e) return M.details.filters(e) end}
-- What inserters take from and put into (targets.lua): built, ghost or planned.
M.targets=require('targets'){}
-- The requests of entities a paste lands on (keep.lua).
M.keep=require('keep'){}
-- Personal logistics: what a take puts over the character's request max goes to trash (trash.lua).
M.trash=require('trash'){}
-- Ammo requests on turret ghosts: place_ghosts, paste and the ghosts of our turrets that died (turretammo.lua).
M.turretammo=require('turretammo'){state=state}
M.replace=require('replace'){filters=function(e) return M.details.filters(e) end,
  circuit_snapshot=function(e) return M.circuits.snapshot(e) end,circuit_restore=function(e,s) return M.circuits.restore(e,s) end}
-- A crafting machine's input against its recipe, and its feeders (inputs.lua; Grok, shift11).
