function M.fluid_guard(p,a,kind)
  if a.dry_run or a.mix_fluids==true then return end
  assert(a.mix_fluids==nil or a.mix_fluids==false,'mix_fluids must be true or false')
  local ok,_,mixes=pcall(function() return M.fluidjoin.plan(p.surface,p.force,M.fluidjoin.entries(a,kind)) end)
  if ok and mixes then
    error(string.format('nothing placed: %s%s; %s; mix_fluids: true places it anyway',mixes[1],#mixes>1 and string.format(' (+%d more)',#mixes-1) or '',M.fluidjoin.NOTE),0)
  end
end
-- mine of a pipe, pipe-to-ground, tank or pump (d17 batch35 B3, Sol): the fluid segments it would split (fluid_split, in
-- its dry run too); a part left with machines taking the fluid and no source refuses it unless cut_fluid: true.
M.mine_entity=handlers.mine
function handlers.mine(p,a)
  if a.tiles or a.position==nil or a.positions~=nil or a.area~=nil then return M.mine_entity(p,a) end
  assert(a.cut_fluid==nil or type(a.cut_fluid)=='boolean','cut_fluid must be true or false')
  local ok,e=pcall(entity,p,a,true)
  local lines,starved
  if ok and e and e.valid then
    local okf,l,st=pcall(M.fluidjoin.removal,p.force,{e})
    if okf then lines,starved=l,st end
  end
  if starved and not a.dry_run and a.cut_fluid~=true then
    error(string.format('nothing mined: %s; cut_fluid: true mines it anyway',starved[1]),0)
  end
  local rest={}
  for k,v in pairs(a) do if k~='cut_fluid' then rest[k]=v end end
  local out=M.mine_entity(p,rest)
  if lines and type(out)=='table' then out.fluid_split=lines end
  return out
end
