  end,
  -- load_silo walk: the silo and chests in sight or on the map (a walk brings them into reach), and a take by hand
  -- there (partial: up to the request max, as a walking take).
  sight_entity=function(p,pos) local e=entity(p,{position=pos},true); friendly(p,e); return e end,
  take=function(p,e,item,quality,count,fresh_first) return transfer_one(p,{direction='to_player',item=item,quality=quality,count=count,partial=true,fresh_first=fresh_first},nil,e) end,
  -- (d17 batch21 A3) a give back to the chest a load took from, in reach: what fits; what you hold of an item
  give=function(p,e,item,quality,count) return transfer_one(p,{direction='to_entity',item=item,quality=quality,count=count,up_to=true},nil,e) end,
  held=function(p,item,quality) local inv=p.get_main_inventory and p.get_main_inventory(); return inv and inv.get_item_count{name=item,quality=quality or 'normal'} or 0 end,
  -- What a player sees moving items by hand, and the hauls and hand share they count, as transfer does.
  moved=function(p,silo,stacks)
    local parts={}
    for _,s in ipairs(stacks) do parts[#parts+1]='-'..s.count..' [item='..s.name..']'; survey.log_hand('fed',s.name,s.count) end
    p.create_local_flying_text{text=table.concat(parts,' '),position=silo.position}
    pcall(M.visuals.moved,p,silo.position,silo.surface,table.concat(parts,' '))
    pcall(M.selfview.moved,p,'to_entity',silo,stacks)
    pcall(M.hauling.moved,p.index,'to_entity',silo.position,silo.surface and silo.surface.name,stacks,silo.name)
  end}
-- No rocket yet, or launch=true before it is ready: a timed action until it is (kind feed; M.feed_ready asks
-- rocketload.ready), then the same call runs whole in that tick.
-- load_silo {auto_requests: "pause"} (B5, Gemini 22:50: automatic requests kept sending bulk items while urgent defense
-- and repair items waited, and a silo with them on takes no hand load): the silo's automatic requests go off for this
-- manifest (its rockets: rockets N, or a split's) and back on after its last launch by this agent, or when a load of it
-- is refused before loading (a load that ends short or failed leaves them off: d17 batch17 A1). Kept in storage by the silo's unit number; one older than 2
-- game hours is switched back on when the silo is next read or loaded.
M.SILO_PAUSE_TICKS=432000
function M.silo_pauses() local st=state(); st.silo_pause=st.silo_pause or {}; return st.silo_pause end
-- The platform each silo's cargo was loaded for (D11): {platform, by, tick} by the silo's unit number; cleared at launch.
function M.silo_loads() local st=state(); st.silo_loads=st.silo_loads or {}; return st.silo_loads end
-- (d17 batch35 A7, operator 14:45: Gleba's silo read "loading for Cinder (loaded by hand by grok, 6h58m ago); aboard
-- nothing" with the rocket empty and automatic requests on) A hand load's record holds while the rocket holds any of
-- the items that load put aboard (a record from before: any cargo); else it is dropped.
function M.silo_load_record(e)
  local loads=M.silo_loads()
  local rec=e and e.valid and loads[e.unit_number]
  if not rec then return nil end
  local held={}
  local ok,cont=pcall(function() return e.get_inventory(defines.inventory.rocket_silo_rocket).get_contents() end)
  for _,c in ipairs(ok and cont or {}) do held[c.name]=true end
  local keep=false
  if rec.items then for _,n in ipairs(rec.items) do if held[n] then keep=true end end else keep=next(held)~=nil end
  if not keep then loads[e.unit_number]=nil; return nil end
  return rec
end
function M.silo_unpause(index,why,unit)
  local lines={}
  for u,rec in pairs(M.silo_pauses()) do
    if (unit==nil and rec.by==index) or u==unit then
      -- (batch32 A1) not while the rocket holds cargo no platform above asks for: the game would move it to the trash slots
      local okr,risk=pcall(function() return rec.silo and rec.silo.valid and M.silo.trash_risk(rec.silo,rec.silo.force) end)
      if okr and risk and risk.lost then
        lines[#lines+1]=string.format('automatic requests of %s stay off (%s, but %s; configure {auto_requests: true, force: true} turns them on anyway)',rec.where or 'the silo',why,risk.line)
      else
        if rec.silo and rec.silo.valid then
          rec.silo.use_transitional_requests=true
          -- (d19 batch46 3) the silo's reads say who switched it and why (editlog.lua)
          if M.editlog then pcall(M.editlog.setting,'silo:'..rec.silo.unit_number,'automatic requests',rec.who or '?','off','on (load_silo: '..why..')') end
        end
        lines[#lines+1]=string.format('automatic requests of %s back on (%s)',rec.where or 'the silo',why)
      end
      M.silo_pauses()[u]=nil
    end
  end
  return #lines>0 and table.concat(lines,'; ') or nil
end
-- A launch wait whose rocket the game launched itself since the wait began (A2): {by_game, cargo, to, tick, stayed, line}.
function M.game_launched(index,action)
  local t=action.then_launch
  local p=M.lookup(index)
  if not (t and t.position and p) then return nil end
  local silo=remote_entity(p,{position=t.position})
  local rec=M.silo.last_launch(silo)
  if not (rec and rec.tick>=(action.start_tick or 0) and rec.by==nil) then return nil end
  local inv=silo.get_inventory(defines.inventory.rocket_silo_rocket)
  local stayed={}
  for _,c in ipairs(inv and inv.get_contents() or {}) do stayed[#stayed+1]=c.name..'*'..c.count end
  local left=#stayed>0 and table.concat(stayed,' ') or nil
  return {by_game=true,tick=rec.tick,to=rec.to,cargo=rec.cargo,stayed=left,
    line=string.format('the game launched the rocket %d s ago %s with %s (a rocket holding what a platform above asks for goes up on its own, one item type a rocket)%s',
      math.floor((game.tick-rec.tick)/60),tostring(rec.to or ''),tostring(rec.cargo),left and '; still in the silo for the next rocket: '..left or '')}
end
-- A paused load that ended without its launch (A1): the pause ends and the requests stay off.
function M.silo_keep_off(index,why)
  local lines={}
  for u,rec in pairs(M.silo_pauses()) do
    if rec.by==index then
      lines[#lines+1]=string.format('automatic requests of %s stay off (%s; configure {auto_requests: true} turns them on)',rec.where or 'the silo',why)
      M.silo_pauses()[u]=nil
    end
  end
  return #lines>0 and table.concat(lines,'; ') or nil
end
-- A launch from a paused silo by the agent that paused it: one rocket of the manifest gone.
function M.silo_launched(p,silo)
  M.silo_pause_line(silo)
  local rec=silo and silo.valid and M.silo_pauses()[silo.unit_number]
  if not rec or rec.by~=p.index then return nil end
  rec.left=(rec.left or 1)-1
  if rec.left>0 then return string.format('automatic requests stay off for %d more rocket%s of this load',rec.left,rec.left==1 and '' or 's') end
  return M.silo_unpause(nil,'its last rocket launched',silo.unit_number)
end
-- The pause line for the silo read; an expired pause is ended here.
function M.silo_pause_line(silo)
  local rec=silo and silo.valid and M.silo_pauses()[silo.unit_number]
  if not rec then return nil end
  -- switched back on by hand (configure {auto_requests: true}): the pause is over
  if silo.use_transitional_requests then M.silo_pauses()[silo.unit_number]=nil; return nil end
  if game.tick-rec.tick>M.SILO_PAUSE_TICKS then return M.silo_unpause(nil,'paused over 2 game hours',silo.unit_number) end
  return string.format('automatic requests paused by %s for %d more rocket%s (load_silo auto_requests: pause), %d s ago',rec.who or '?',rec.left or 1,(rec.left or 1)==1 and '' or 's',math.floor((game.tick-rec.tick)/60))
end
function M.silo_pause(p,a,rockets)
  assert(a.auto_requests=='pause','auto_requests on load_silo is "pause": the silo\'s automatic requests go off for this load and come back on after its launch (configure {auto_requests} sets them for good)')
  assert(a.launch==true,'auto_requests: "pause" goes with launch: true (the requests come back on after the launch)')
  local silo=remote_entity(p,{position=a.position})
  assert(silo.type=='rocket-silo',silo.name..' is not a rocket silo')
  M.silo_pause_line(silo)
  local rec=M.silo_pauses()[silo.unit_number]
  if rec then return nil end
  if not silo.use_transitional_requests then return nil end
  local aboard={}
  local inv=silo.get_inventory(defines.inventory.rocket_silo_rocket)
  for _,c in ipairs(inv and inv.get_contents() or {}) do aboard[#aboard+1]=c.name..'*'..c.count end
  silo.use_transitional_requests=false
  if M.editlog then pcall(M.editlog.setting,'silo:'..silo.unit_number,'automatic requests',M.board.who(p) or p.name or '?','on','off (load_silo pause, back on after its last launch)') end
  M.silo_pauses()[silo.unit_number]={by=p.index,who=M.board.who(p),tick=game.tick,left=rockets or 1,silo=silo,where=string.format('%s (%g,%g)',silo.name,silo.position.x,silo.position.y)}
  return string.format('automatic requests of %s (%g,%g) switched off for this load (%d rocket%s): back on after its last launch; a load that ends short or failed leaves them off%s',
    silo.name,silo.position.x,silo.position.y,rockets or 1,(rockets or 1)==1 and '' or 's',#aboard>0 and '; the rocket already held '..table.concat(aboard,' ')..', which stays aboard' or '')
end
-- load_silo {position, platform, first: [items]} (d17 batch31 B7, Gemini about 4 times: a silo's automatic requests
-- loaded iron ore before foundation, collectors or ammo; the game has no priority among them): the items named, each at
-- what the platform's hub lacks of its requests (or the count given), from what you hold and the chests of the silo's
-- logistic network that hold them (the one robots would take from first, select_pickup_point, up to 4 an item) or the
-- chests in from, walked as load_silo walk does, launched to the platform with the silo's automatic requests paused
-- (auto_requests "pause": off now, back on after the launch).
function M.load_first(p,a)
  local function try(fn) local ok,v=pcall(fn); if ok then return v end end
  assert(type(a.platform)=='string','first goes with platform (the platform the rocket goes to)')
  assert(a.items==nil and a.launch==nil and a.auto_requests==nil and a.walk==nil and a.rockets==nil,'first sets items, walk, launch and auto_requests itself (from and position are yours)')
  local pl=space.platform(p,a.platform)
  local hub=pl.hub
  assert(hub and hub.valid,a.platform..' has no hub')
  local want,order={},{}
  if type(a.first)=='table' and a.first[1]==nil then
    for item,n in pairs(a.first) do
      assert(prototypes.item[item],'first: unknown item '..tostring(item))
      assert(type(n)=='number' and n>=1 and n==math.floor(n),'first: '..item..' count is 1 or more')
      want[item]=n; order[#order+1]=item
    end
    table.sort(order)
  else
    assert(type(a.first)=='table' and #a.first>=1 and #a.first<=8,'first is 1..8 item names (each at what the hub lacks of its requests) or {item: count}')
    -- what the hub asks of each (its sections that are on) against what it holds
    local asks={}
    local secs=try(function() return hub.get_logistic_sections() end)
    for i=1,secs and secs.sections_count or 0 do
      local sec=secs.get_section(i)
      if sec and sec.active~=false then
        for _,f in pairs(try(function() return sec.filters end) or {}) do
          local v=f.value
          local n=v and (type(v.name)=='string' and v.name or try(function() return v.name.name end))
          if n and (f.min or 0)>0 then asks[n]=(asks[n] or 0)+f.min end
        end
      end
    end
    local none={}
    for _,item in ipairs(a.first) do
      assert(type(item)=='string' and prototypes.item[item],'first: unknown item '..tostring(item))
      local lack=(asks[item] or 0)-(try(function() return hub.get_item_count(item) end) or 0)
      if lack>0 then want[item]=lack; order[#order+1]=item
      else none[#none+1]=string.format('%s (the hub %s)',item,asks[item] and string.format('asks %d and holds them',asks[item]) or 'does not request it') end
    end
    assert(#order>0,'first: '..a.platform..'\'s hub lacks none of them: '..table.concat(none,', ')..'; give counts as {item: count}')
    a.first_skipped=#none>0 and none or nil
  end
  local silo=remote_entity(p,{position=a.position})
  assert(silo.type=='rocket-silo',silo.name..' is not a rocket silo')
  -- the chests: yours in from, else those the silo's network would give from first
  local from=a.from
  local chests
  if from==nil then
    local net=try(function() return silo.surface.find_logistic_network_by_position(silo.position,silo.force) end)
    local seen={}
    from={}
    chests={}
    for _,item in ipairs(order) do
      for _=1,4 do
        local pt=net and try(function() return net.select_pickup_point{name=item,position=silo.position} end)
        local c=pt and try(function() return pt.owner end)
        if not (c and c.valid) then break end
        local k=c.unit_number or (c.position.x..','..c.position.y)
        if seen[k] then break end
        seen[k]=true
        if #from<16 then from[#from+1]={x=c.position.x,y=c.position.y}; chests[#chests+1]=string.format('%s (%g,%g) holding %d %s',c.name,c.position.x,c.position.y,try(function() return c.get_item_count(item) end) or 0,item) end
      end
    end
    if #from==0 then from=nil end
  end
  local items={}
  for _,item in ipairs(order) do items[item]=want[item] end
  local args={position=a.position,platform=a.platform,items=items,launch=true,auto_requests=try(function() return silo.use_transitional_requests end) and 'pause' or nil,
    walk=true,from=from,launch_split=a.launch_split,dry_run=a.dry_run}
  local out=handlers.load_silo(p,args)
  if type(out)=='table' then
    local parts={}
    for _,item in ipairs(order) do parts[#parts+1]=item..' '..want[item] end
    out.first=string.format('%s first: %s%s, launched to %s with the silo\'s automatic requests %s; from %s',
      silo.name,table.concat(parts,', '),type(a.first[1])=='string' and ' (what the hub lacks of its requests)' or '',a.platform,
      args.auto_requests and 'paused (back on after the launch)' or 'off already',
      a.from~=nil and 'the chests in from' or (chests and #chests>0 and 'what you hold and the network\'s chests robots would take from first: '..table.concat(chests,'; ')) or 'what you hold (the silo\'s network holds none of them)')
    out.first_skipped=a.first_skipped
  end
  return out
end
function handlers.load_silo(p,a)
  -- the silo (Grok d17 16:16: walk with from [chest] and no position failed "position requires x and y" and read as
  -- the from list being wrong): without position, the silos here and the call that works.
  if a.position==nil then error(M.launch_needs_silo(p,a,'load_silo'),0) end
  if a.first~=nil then return M.load_first(p,a) end
  -- wait_platform (d17 batch13 A4, Gemini: load_silo with arrived failed while the platform was still on its way): one
  -- timed call that ends when the rocket launches, or when the platform goes elsewhere. Nothing goes into the rocket
  -- until the platform is stopped in orbit here; then the load goes in and launches in that tick, as one rocket
  -- (d17 batch17 A2/A3, Grok 2x on Gleba: the cargo staged in the ready rocket ahead of Swift; when Swift stopped, the
  -- game launched the rocket itself for Swift's requests, one item type a rocket: bioflux*40 went and the 500 packs
  -- stayed for the next rocket, and the staged launch wait read launch_started as launch_failed).
  if a.wait_platform~=nil then
    assert(type(a.wait_platform)=='boolean','wait_platform must be true or false')
    local rest={}
    for k,v in pairs(a) do if k~='wait_platform' then rest[k]=v end end
    if not a.wait_platform then return handlers.load_silo(p,rest) end
    assert(a.launch==true and type(a.platform)=='string','wait_platform goes with launch: true and platform (the platform the rocket goes to)')
    assert(a.rockets==nil,'wait_platform loads one rocket (no rockets)')
    -- with walk (batch25 C1, Grok: Spindle 48 s from Gleba, a 60 s stop): the walking load, which gathers from the chests
    -- in from, then holds at the silo, loading nothing, until the platform is stopped in orbit here and the rocket is
    -- ready, then loads and launches in that tick (M.ready, walk_visit); it ends short when the platform goes elsewhere.
    if a.walk then
      local out=handlers.load_silo(p,rest)
      if type(out)=='table' then
        out.wait_platform=string.format('the walk gathers from the chests in from, then waits at the silo, loading nothing, until %s is stopped in orbit here and the rocket is ready; then it loads and launches in that tick; it ends short when %s goes elsewhere',a.platform,a.platform)
      end
      return out
    end
    assert(a.from==nil,'wait_platform without walk loads in reach (from goes with walk: true)')
    local out=handlers.load_silo(p,rest)
    if type(out)=='table' then
      out.wait_platform=string.format('nothing goes into the rocket until %s is stopped in orbit here: then the load goes in and launches in that tick, as one rocket (a rocket holding what a platform above asks for is launched by the game, one item type a rocket); this call ends when it launches, or when %s goes elsewhere (fh --wait follows it)',a.platform,a.platform)
    end
    return out
  end
  -- auto_requests: "pause" (B5): off now, the manifest's rocket count from rockets or the split.
  -- auto_requests: false (C4, Haiku 23:40 tried it): off now and left off, then the load.
  if a.auto_requests==false then
    local silo=remote_entity(p,{position=a.position})
    assert(silo.type=='rocket-silo',silo.name..' is not a rocket silo')
    local was=silo.use_transitional_requests
    silo.use_transitional_requests=false
    if M.editlog and was then pcall(M.editlog.setting,'silo:'..silo.unit_number,'automatic requests',M.board.who(p) or p.name or '?','on','off (load_silo auto_requests: false)') end
    local rest={}
    for k,v in pairs(a) do if k~='auto_requests' then rest[k]=v end end
    local out=handlers.load_silo(p,rest)
    if type(out)=='table' then out.auto_requests=was and 'automatic requests switched off and left off (launch or configure {auto_requests: true} turns them on; auto_requests: "pause" brings them back after the launch)' or 'automatic requests were off already' end
    return out
  end
  if a.auto_requests~=nil then
    assert(a.auto_requests=='pause','auto_requests on load_silo is "pause" (off for this load, back on after its launch) or false (off, and left off)')
    assert(a.launch==true,'auto_requests: "pause" goes with launch: true (the requests come back on after the launch)')
    -- Several rockets (rockets N, or a list over one rocket's lift): this call only queues the steps, each carrying the
    -- rockets left (pause_left); the first step that runs pauses the requests. A rerun after the wait finds them paused.
    local multi=a.rockets~=nil
    if not multi and not a.split_part and not a.awaited and not a.to_total and not a.up_to and a.items~=nil then
      local okl,list=pcall(M.rocketload.items,a.items,'items')
      local oks,silo=pcall(remote_entity,p,{position=a.position})
      if okl and oks then
        local okc,l,sl=pcall(M.cargo.limits,silo)
        multi=M.rocketload.split(list,okc and l or 1000000,okc and sl or 20)~=nil
      end
    end
    -- (batch31 B7) a dry run pauses nothing: it would leave them off, with no launch to bring them back
    local paused
    if a.dry_run then
      local oks,silo=pcall(remote_entity,p,{position=a.position})
      paused=oks and silo.valid and silo.type=='rocket-silo' and silo.use_transitional_requests and 'a dry run: nothing switched; the load would switch the silo\'s automatic requests off, and back on after its launch' or nil
    else paused=not multi and M.silo_pause(p,a,a.pause_left or 1) or nil end
    local ok,out=pcall(handlers.load_silo_run,p,a)
    if not ok then
      local back=M.silo_unpause(p.index,'the load was refused')
      error(tostring(out):gsub('^[^:]*:%d+: ','')..(back and '; '..back or ''),0)
    end
    if type(out)=='table' then
      out.auto_requests=paused
      if out.launch and out.launch.auto_requests_back then out.auto_requests_back=out.launch.auto_requests_back end
    end
    return out
  end
  return handlers.load_silo_run(p,a)
end
function handlers.load_silo_run(p,a)
  -- dry_run (A9): the plan, nothing loaded or queued
  if a.dry_run~=nil then
    assert(type(a.dry_run)=='boolean','dry_run must be true or false')
    if a.dry_run then
      assert(a.items~=nil,'dry_run reads a list: items')
      local silo=remote_entity(p,{position=a.position})
      assert(silo.type=='rocket-silo',silo.name..' is not a rocket silo')
      local okc,l,sl=pcall(M.cargo.limits,silo)
      return M.rocketload.plan(p,a,silo,okc and l or 1000000,okc and sl or 20)
    end
    local rest={}
    for k,v in pairs(a) do if k~='dry_run' then rest[k]=v end end
    a=rest
  end
  -- rockets (Sonnet 13:51): the same load for N rockets in one call, as N queue steps appended to your queue, each
  -- loading and launching one rocket in turn (each waits for its rocket as a single load_silo does).
  if a.rockets~=nil then
    local n=integer(a.rockets,nil,2,20,'rockets')
    assert(a.launch==true,'rockets goes with launch: true (the next rocket is built after this one leaves)')
    local args={}
    for k,v in pairs(a) do if k~='rockets' then args[k]=v end end
    M.rocketload.check(args)
    local steps={}
    for i=1,n do
      local c=args
      if args.auto_requests~=nil then c={}; for k,v in pairs(args) do c[k]=v end; c.pause_left=n-i+1 end
      steps[i]={action='load_silo',args=c,label=string.format('rocket %d of %d',i,n)}
    end
    local out=scheduler.handlers.queue_submit(p,{steps=steps,mode='append'})
    out.rockets=n
    out.note=string.format('%d load_silo steps appended to your queue, labelled rocket 1 of %d to rocket %d of %d: each loads the list and launches; queue_status follows them',n,n,n,n)
    return out
  end
  -- A launch whose list is over one rocket's lift or slots (B1, Sonnet 18:20): this call loads and launches the first
  -- rocket's part, and the rest go as load_silo steps appended to your queue, one a rocket (as rockets: N does).
  if a.launch==true and a.rockets==nil and not a.split_part and not a.to_total and not a.up_to and a.items~=nil then
    local okl,list=pcall(M.rocketload.items,a.items,'items')
    if okl then
      local silo=select(2,pcall(remote_entity,p,{position=a.position}))
      local lift,slots=1000000,20
      if type(silo)=='table' or type(silo)=='userdata' then
        local okc,l,sl=pcall(M.cargo.limits,silo); if okc and l then lift,slots=l,sl or slots end
      end
      local parts,total=M.rocketload.split(list,lift,slots)
      -- (A9) a split only when asked: launch_split: true; else refused, naming it. (d18 batch38 C2, Sonnet: a load over
      -- one rocket's lift is split by rocket by default, each at most a full rocket; launch_split: false refuses it, and
      -- so do all_or_nothing and wait_platform, one rocket each, unless launch_split: true)
      local split_ok=a.launch_split==true or (a.launch_split==nil and not a.all_or_nothing and not a.wait_platform)
      if parts and not split_ok then
        local lines={}
        for i,part in ipairs(parts) do
          local t={}; for _,r in ipairs(part) do t[#t+1]=r.name..' '..r.count end
          lines[i]=string.format('rocket %d: %s',i,table.concat(t,', '))
        end
        error(string.format('the list is over one rocket (%s kg; lift %g kg, %d slots): it would go as %d rockets (%s); launch_split: true sends it so (the default without all_or_nothing, wait_platform or launch_split: false), or load less; dry_run: true shows each item\'s weight and slots; nothing loaded or queued',
          total,lift/1000,slots,#parts,table.concat(lines,'; ')),0)
      end
      if parts then
        local function args_for(part,left)
          local c={}
          for k,v in pairs(a) do c[k]=v end
          c.items={}; for i,r in ipairs(part) do c.items[i]={item=r.name,count=r.count,quality=r.quality} end
          c.split_part=true; c.launch_split=nil
          if a.auto_requests~=nil then c.pause_left=left end
          return c
        end
        local lines={}
        for i,part in ipairs(parts) do
          local t={}; for _,r in ipairs(part) do t[#t+1]=r.name..' '..r.count end
          lines[i]=string.format('rocket %d: %s',i,table.concat(t,', '))
        end
        local steps={}
        for i=1,#parts do steps[#steps+1]={action='load_silo',args=args_for(parts[i],#parts-i+1),label=string.format('rocket %d of %d',i,#parts)} end
        local out=scheduler.handlers.queue_submit(p,{steps=steps,mode='append'})
        out.rockets=#parts
        out.rocket_cargo=lines
        out.split=string.format('%s kg over %d rockets (lift %g kg, %d slots): %s; each a load_silo step appended to your queue, loading and launching in turn%s',
          total,#parts,lift/1000,slots,table.concat(lines,'; '),a.launch_split==nil and ' (split by default: launch_split: false refuses a list over one rocket)' or '')
        return out
      end
    end
  end
  -- walk with from (Luna, shift14 21:20): one timed tour between the chests and the silo (rocketload.lua walk_start);
  -- the silo and every chest in reach: the load at once, as without walk.
  if a.walk==true and not a.awaited then
    local w=M.rocketload.walk_start(p,a)
    if w and w.done then return w.done end
    if w then
      local action,out=stock.start_tour(p,'load_silo',w.entities,integer(a.ticks,18000,1,36000,'ticks'),w.fields)
      if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
      state().active[p.index]=action
      for k,v in pairs(w.reply) do out[k]=v end
      out.until_tick=action.until_tick; out.legs,out.legs_more=M.legs(p,action.targets)
      return out
    end
    local rest={}
    for k,v in pairs(a) do rest[k]=v end
    rest.walk=nil; rest.avoid_enemies=nil; rest.unsafe_goal=nil; a=rest
  end
  -- (D1) in reach: what you and the chests hold now goes, as up_to
  if a.up_to_stock_at_start~=nil then
    local rest={}
    for k,v in pairs(a) do if k~='up_to_stock_at_start' then rest[k]=v end end
    if a.up_to_stock_at_start then rest.up_to=true end
    a=rest
  end
  local ticks=integer(a.ticks,3600,1,36000,'ticks')
  local r=M.rocketload.load(p,a)
  if not r.wait then return r end
  if a.awaited then error((r.platform and 'still waiting, nothing loaded: ' or 'the rocket is still not ready: ')..r.why,0) end
  local rest={}
  for k,v in pairs(a) do rest[k]=v end
  rest.awaited=true
  if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
  local until_tick=game.tick+ticks
  -- While the silo makes parts the wait goes on (rocketload.lua M.ready; Sonnet 22:50): ticks with no new part ends it.
  local await={position=a.position,launch=a.launch==true,platform=a.launch==true and a.platform or nil}
  -- wait_min (Sonnet 15:20): the idle window while the silo makes no part, in minutes (1..60), e.g. for an ingredient
  -- on its way.
  local wait_min=a.wait_min~=nil and integer(a.wait_min,nil,1,60,'wait_min') or nil
  local okw,wf=pcall(M.rocketload.wait_fields,entity(p,{position=a.position}),wait_min and math.max(ticks,wait_min*3600) or ticks)
  if okw then for k,v in pairs(wf) do await[k]=v end end
  if wait_min then until_tick=math.max(until_tick,game.tick+wait_min*3600) end
  state().active[p.index]={kind='feed',handler='load_silo',args=rest,await_silo=await,until_tick=until_tick,next_check=game.tick+FEED_CHECK}
  local short=okw and await.silo and M.rocketload.parts_short(await.silo)
  return {waiting={why=r.why,rocket=r.rocket,rate=okw and M.rocketload.wait_report(state().active[p.index]) or nil,parts_short=short and short.line or nil,
    note=okw and (r.platform and string.format('waits for the platform to be in orbit here, at the latest tick %d; then loads and launches in that tick',await.give_up)
      or string.format('waits while the silo makes parts: the idle window starts at %ds and grows to 3 times the longest observed interval to a part increase; at the latest tick %d',math.floor(ticks/60),await.give_up)) or nil},
    until_tick=until_tick,gives_up_tick=okw and await.give_up or nil}
end
function handlers.preflight(p,a)
  local out=M.rocketload.preflight(p,a)
  -- (d17 batch15, Astra 09:20) the platform's coming stops whose landing pads ask what the hub holds (shipment.lua)
  if type(out)=='table' and type(a.platform)=='string' and M.shipment then
    for _,pl in pairs(p.force.platforms) do
