-- Ghosts at absolute positions, as a player places them from the cursor or
-- the map: anywhere charted, no items needed. `construct` then builds them.
-- One ghost as a player's ghost placement (shift-build): manual ghost checks
-- on charted ground, no item needed. `type` picks an underground end.
-- A tile by its tile name or by the item that places it (stone-brick ->
-- stone-path), or nil.
local function tile_named(name)
  if type(name)~='string' then return nil end
  local item=prototypes.item[name]
  local result=item and item.place_as_tile_result
  if result then return result.result.name end
  if prototypes.tile[name] and not prototypes.entity[name] then return name end
end
-- A tile ghost goes where the engine's check takes it. Trees and rocks in
-- its way (Sol, shift10: a slipstack on Gleba wetland kept landfill from
-- three belt tiles; dryrun.lua tile_blockers) are marked for deconstruction
-- first, as the game's ghost placement marks them: marked, the engine takes
-- the tile ghost (2.0.77), and construct mines them before it lays the tile.
-- Anything else in the way refuses it, named. Returns the ghost and what it
-- marked.
do local function place_tile_ghost(p,tile,pos)
  assert(charted(p,pos),'position is not charted')
  local x,y=math.floor(pos.x),math.floor(pos.y)
  local marked={}
  local blockers=M.dryrun.tile_blockers(p.surface,p.force,tile,x,y)
  if blockers then
    local others={}
    for _,b in ipairs(blockers) do if not b.obstacle then others[#others+1]=b end end
    if #others>0 then error('tile placement blocked by '..table.concat(M.dryrun.blocker_texts({others}),', '),0) end
    if #blockers==0 then
      -- in front of an asteroid collector (A5, Astra 01:50): said
      local why=M.placewhy.collector_ahead(p.surface,p.force,x,y)
      -- (d20 batch52 J1) past the chunks the surface has generated: asked for, and said
      if not why then
        local okt,t=pcall(p.surface.get_tile,x,y)
        local okg,g=pcall(function() return p.surface.is_chunk_generated({math.floor(x/32),math.floor(y/32)}) end)
        local gen=not okg or g~=false
        if not (okt and t and t.valid~=false) or (not gen and t.name=='out-of-map') then
          why=M.placewhy.ungenerated_text(p.surface,{count=1,chunks={{x=math.floor(x/32),y=math.floor(y/32)}},x0=x,x1=x,y0=y,y1=y},true)
            :gsub('^the tile %(%-?%d+,%-?%d+%) it needs','it')
        end
      end
      error('tile placement blocked: the game refuses '..tile..' there now'..(why and ': '..why or ''),0)
    end
    for _,b in ipairs(blockers) do
      if b.entity.valid and b.entity.order_deconstruction(p.force,real(p)) then marked[#marked+1]=b.entity end
    end
  end
  local args={name='tile-ghost',inner_name=tile,position=pos,force=p.force}
  local ok=p.surface.can_place_entity{name='tile-ghost',inner_name=tile,position=pos,force=p.force,build_check_type=defines.build_check_type.manual_ghost}
  args.player=real(p); args.raise_built=true
  local ghost=ok and p.surface.create_entity(args)
  if not ghost then
    for _,e in ipairs(marked) do if e.valid then pcall(e.cancel_deconstruction,p.force,real(p)) end end
    error('tile placement blocked',0)
  end
  -- (d24 batch144 PP1) who placed it (ghostlog.lua): remove_ghosts {tiles: true} takes one's own by it; a record that
  -- fails never stops the placement
  pcall(function() M.ghostlog.placed(M.board.who(p),ghost) end)
  return ghost,marked
end
-- The reply's line for trees and rocks marked where tile ghosts go.
function M.tile_marks_line(list)
  if #list==0 then return nil end
  local parts,seen={},{}
  for _,e in ipairs(list) do
    if e.valid then
      local text=string.format('%s (%g,%g)',e.name,math.floor(e.position.x*10+0.5)/10,math.floor(e.position.y*10+0.5)/10)
      if not seen[text] then seen[text]=true; parts[#parts+1]=text end
    end
  end
  if #parts==0 then return nil end
  return 'marked for deconstruction where tile ghosts go: '..table.concat(parts,', ',1,math.min(8,#parts))..(#parts>8 and string.format(' and %d more',#parts-8) or '')
    ..'; construct mines them before it lays the tiles'
end
-- A place_ghosts entry's quality (d20 batch53 L1, Astra #1223, Sol #1298): a player places a ghost at any quality the
-- force has unlocked (the quality picker offers only those); the engine takes a locked one too (an epic ghost on the
-- copy of world n with epic locked), so that is refused here. nil for normal.
function M.ghost_quality(p,q)
  if q==nil or q=='normal' then return nil end
  assert(type(q)=='string' and prototypes.quality[q],'quality must be a quality name (normal, uncommon, rare, epic, legendary), not '..tostring(q))
  local ok,unlocked=pcall(function() return p.force.is_quality_unlocked(q) end)
  assert(not ok or unlocked,q..' quality is not unlocked for our force: a player cannot place a ghost of it')
  return q
end
-- The same entity on that spot at another quality (built or a ghost): the refusal names it and the upgrade that
-- changes its quality, as a player would use the upgrade planner there.
function M.other_quality_there(p,name,pos,q)
  for _,e in ipairs(p.surface.find_entities_filtered{position=pos,radius=0.3,force=p.force,limit=4}) do
    local ghost=e.type=='entity-ghost'
    if (ghost and e.ghost_name or e.name)==name then
      local okq,had=pcall(function() return e.quality.name end)
      had=okq and had or 'normal'
      if had~=(q or 'normal') then
        return string.format('placement blocked: %s %s of %s quality stands at (%g,%g): upgrade {position, quality: "%s"} changes its quality in place',
          ghost and 'a ghost of' or 'a built',name,had,e.position.x,e.position.y,q or 'normal')
      end
    end
  end
end
local function place_ghost(p,spec)
  assert(type(spec)=='table','entry must be {name,position,direction?,type?}')
  local tile=not prototypes.entity[spec.name or ''] and tile_named(spec.name)
  if tile then
    local ghost,tile_marked=place_tile_ghost(p,tile,position(spec.position))
    return ghost,0,nil,nil,tile_marked
  end
  local proto=type(spec.name)=='string' and prototypes.entity[spec.name]
  assert(proto and proto.items_to_place_this and #proto.items_to_place_this>0,'not a placeable entity: '..tostring(spec.name))
  local pos=position(spec.position)
  local direction=spec.direction and M.direction_of(spec.direction)
  assert(spec.direction==nil or direction,'direction must be a compass name (north, east, south, west) or 0..15')
  M.check_direction(proto,direction)
  assert(spec.type==nil or proto.type=='underground-belt' and (spec.type=='input' or spec.type=='output'),'type is input|output for underground belts only')
  if proto.type=='rail-ramp' then pos,direction=M.placewhy.ramp_position(pos,direction) end
  assert(charted(p,pos),'position is not charted')
  -- The engine's check refuses trees, rocks and stumps (shake3: "placement
  -- blocked by tree-08"); a player's ghost goes over them and marks the trees
  -- and rocks, and the build clears the stumps (build_direct).
  -- (d20 batch53 L1) the same entity there at another quality: refused before the engine's check, which takes a ghost
  -- over a ghost of the same name (the copy of world n stacked an uncommon and a normal assembler ghost on one spot)
  local other=M.other_quality_there(p,spec.name,pos,spec.quality)
  if other then error(other,0) end
  -- (AG1) a rail or chain signal: the game's ghost check on its rail layer (rail_layer, else ground then elevated), and
  -- the facing of the signal spot there when no direction is given
  local sig
  if M.railsignal.TYPES[proto.type] then
    sig=M.railsignal.resolve(p.surface,p.force,spec.name,pos,direction,M.railsignal.layer_arg(spec.rail_layer),true)
    direction=sig.direction
  elseif spec.rail_layer~=nil then error('rail_layer goes with rail signals and chain signals',0) end
  -- (d20 batch122, Astra #2064) ours of its fast-replace group standing there: the game's ghost check takes a player's
  -- ghost over it (a fast replace), create_entity does not; named, with what changes it in place
  if not sig then
    local rep=construction.ghost_replaces(p.surface,p.force,proto,pos,direction)
    if #rep>0 then error('placement blocked'..construction.ghost_replaces_text(proto,pos,direction,rep),0) end
  end
  if not sig and not construction.ghost_placeable(p.surface,p.force,proto,pos,direction) then
    -- (d22 batch95 BE1, Astra #1892: a decider on Aquilo's rough ice) tiles a forced placement does not lay (concrete;
    -- ice platform then concrete): tile entries before it lay their ghosts first, and the game takes its ghost over them
    local err=placement_error(p,proto,pos,direction)
    if err:find(' by tiles: ',1,true) then
      local okf,fx=pcall(M.dryrun.tile_fixes,p.surface,p.force,proto,pos,direction)
      local f=okf and fx and fx[1]
      local what=f and (f.item or f.two)
      if what then err=err..'; '..what..' as tile entries ({name, position}) before it in this place_ghosts call lay those tile ghosts first, and the game takes its ghost over them' end
    end
    error(err,0)
  end
  -- Tiles it cannot stand on (water, Gleba wetland): the forced ghost check
  -- takes them once the force has landfill, because a player's forced
  -- placement lays the tile ghosts under the entity; so do we, before it.
  -- With no tile item for them the ghost would never be built: refused.
  -- Trees and rocks where those tiles go are marked first (place_tile_ghost);
  -- anything else there refuses the ghost, named.
  local fixes=not sig and M.dryrun.tile_fixes(p.surface,p.force,proto,pos,direction) or nil
  -- (d20 batch52 J1) An entity with tile rules over empty space where a rule wants ground (a thruster's body): the
  -- foundation tile ghosts under it first, as the game's forced placement lays them (2.0.77 on the copy: a forced
  -- blueprint of a lone thruster placed it and 20 foundation tile ghosts); tile ghosts already there count as laid.
  if not fixes and not sig and #(proto.tile_buildability_rules or {})>0 then
    local rt=M.placewhy.rule_tiles(p.surface,p.force,proto,pos,direction)
    for _,n in ipairs(rt.need) do
      fixes=fixes or {}
      fixes[#fixes+1]={x=n.x+0.5,y=n.y+0.5,tile=n.tile,item=n.item}
    end
  end
  for _,f in ipairs(fixes or {}) do
    local result=f.item and prototypes.item[f.item] and prototypes.item[f.item].place_as_tile_result
    f.result=result and result.result.name
    local blockers=f.result and M.dryrun.tile_blockers(p.surface,p.force,f.result,math.floor(f.x),math.floor(f.y))
    local others={}
    for _,b in ipairs(blockers or {}) do if not b.obstacle then others[#others+1]=b end end
    if not f.result or #others>0 or (blockers and #blockers==0) then
      error(string.format('placement blocked by tiles: %s at (%g,%g)%s',f.tile,f.x,f.y,
        f.locked and ' (needs '..f.locked..')' or f.two and ' (needs '..f.two..': as tile entries before it)' or #others>0 and ': its '..f.item..' is blocked by '..table.concat(M.dryrun.blocker_texts({others}),', ')
        or f.result and ' (the game refuses '..f.item..' there)' or ' (no tile item makes it buildable)'),0)
    end
  end
  local laid,tiles,tile_marked={},{},{}
  for _,f in ipairs(fixes or {}) do
    local ok,t,m=pcall(place_tile_ghost,p,f.result,{x=f.x,y=f.y})
    if not ok then
      for _,g in ipairs(tiles) do if g.valid then g.destroy() end end
      for _,e in ipairs(tile_marked) do if e.valid then pcall(e.cancel_deconstruction,p.force,real(p)) end end
      error(string.format('placement blocked by tiles: %s at (%g,%g): %s',f.tile,f.x,f.y,reason(t)),0)
    end
    tiles[#tiles+1]=t
    for _,e in ipairs(m or {}) do tile_marked[#tile_marked+1]=e end
    laid[f.item]=(laid[f.item] or 0)+1
  end
  local ghost=p.surface.create_entity{name='entity-ghost',inner_name=spec.name,position=pos,direction=direction,force=p.force,player=real(p),raise_built=true,type=spec.type,
    quality=M.ghost_quality(p,spec.quality),rail_layer=sig and sig.layer or nil}
  if ghost then pcall(M.built_watch,p,spec.name,ghost) end
  if not ghost then
    for _,t in ipairs(tiles) do if t.valid then t.destroy() end end
    for _,e in ipairs(tile_marked) do if e.valid then pcall(e.cancel_deconstruction,p.force,real(p)) end end
    local okw,why=pcall(M.attach_why,p,prototypes.entity[spec.name],pos,direction)
    error('placement blocked'..(okw and why or ''),0)
  end
  local _,marked,cliffs=construction.mark_obstacles(p,ghost)
  -- The build log (efficiency.lua): a planned machine is its planner's when robots or a hand build it.
  pcall(M.efficiency.built,M.board.who(p),ghost)
  pcall(M.ghostlog.placed,M.board.who(p),ghost)
  return ghost,marked,fixes and laid or nil,fixes and fixes[1].tile or nil,tile_marked,cliffs,tiles
end
-- What already stands where a place_ghosts entry goes, the same as the entry (d17 batch12 C4, Astra: staged plans
-- re-run many times read every standing ghost as a failure): 'ghost' (a ghost of it), 'built' (the entity itself), or
-- nil. The same: name, position (the same tile: within 0.71), direction (north when the entry gives none), an underground's
-- type and a machine's recipe when the entry names them; the quality (normal when the entry gives none).
function M.same_standing(p,spec)
  if type(spec)~='table' or type(spec.name)~='string' or not prototypes.entity[spec.name] then return nil end
  local okp,pos=pcall(position,spec.position)
  if not okp then return nil end
  local dir=spec.direction and M.direction_of(spec.direction) or 0
  for _,e in ipairs(p.surface.find_entities_filtered{position=pos,radius=0.75,force=p.force,limit=8}) do
    local ghost=e.type=='entity-ghost'
    local name=ghost and e.ghost_name or e.name
    if name==spec.name and distance(e.position,pos)<=0.71 and (e.direction or 0)==dir then
      local same=true
      if spec.type then
        local okt,t=pcall(function() return e.belt_to_ground_type end)
        same=okt and t==spec.type
      end
      if same and spec.recipe then
        local okr,r=pcall(function() return e.get_recipe() end)
        same=okr and r and (r.name or r)==spec.recipe
      end
      if same then
        local okq,q=pcall(function() return e.quality.name end)
        same=(okq and q or 'normal')==(spec.quality or 'normal')
      end
      if same then return ghost and 'ghost' or 'built' end
    end
  end
end
-- On a platform, the empty tiles that the tile ghosts in tiles (one call's) enclose, by the dry run's rule, laid as
-- tile ghosts of their tile (d20 batch122, Astra #2087): {laid, item, note, failed (up to 8 {position, error})}, or nil.
function M.platform_holes(p,tiles,tile_marked)
  if #tiles==0 or not p.surface.platform then return nil end
  local cells,name={},nil
  for _,t in ipairs(tiles) do
    if t.valid then cells[#cells+1]={math.floor(t.position.x),math.floor(t.position.y)}; name=name or t.ghost_name end
  end
  if not name then return nil end
  local okh,list,other,unchecked=pcall(M.dryrun.live_holes,p.surface,p.force,cells)
  if not okh then return {laid=0,note='the hole check failed: '..reason(list)} end
  if #list==0 then return nil end
  local laid,failed,nfailed=0,{},0
  for _,c in ipairs(list) do
    local pos={x=c[1]+0.5,y=c[2]+0.5}
    local ok,g,m=pcall(place_tile_ghost,p,name,pos)
    if ok then
      laid=laid+1
      for _,e in ipairs(m or {}) do tile_marked[#tile_marked+1]=e end
    else
      nfailed=nfailed+1
      if #failed<8 then failed[#failed+1]={position=pos,error=reason(g)} end
    end
  end
  local oki,item=pcall(function() return prototypes.tile[name].items_to_place_this[1].name end)
  item=oki and item or name
  local note=string.format('%d empty tile%s enclosed by the new foundation: %d %s tile ghost%s laid there too (the hub builds no foundation that leaves a hole of empty space)',
    #list,#list==1 and '' or 's',laid,item,laid==1 and '' or 's')
    ..(nfailed>0 and string.format('; %d refused (holes_failed): the foundation beside them stays unbuilt while they are empty',nfailed) or '')
    ..(other>0 and string.format('; %d more enclosed empty tiles left out: the largest region the new tiles part may stay empty',other) or '')
    ..(unchecked and '; the hole check stopped at its budget, some enclosed tiles may be missing' or '')
  return {laid=laid,item=item,note=note,failed=#failed>0 and failed or nil}
end
local function place_ghost_list(p,list,ammo)
  local placed,failed,bounds,marked=0,{},nil,0
  local already={}
  local unders,inserters,chests,belts,ghosts={},{},{},{},{}
  local tiles_laid,laid_under,laid_on=nil,0,nil
  local tile_marked,new_tiles={},{}
  local ammo_rows={}
  local cliffs,ncliffs={},0
  local recipes,turned_notes={},{}
  for i,spec in ipairs(list) do
    local oks,same=pcall(M.same_standing,p,spec)
    if oks and same then already[#already+1]={index=i,name=spec.name,position=spec.position,already=same}
    else
    local ok,err=pcall(function()
      if type(spec)=='table' then M.turretammo.check(spec.ammo) end
      -- recipe: checked before the ghost is placed, set on it after (a ghost takes one as its machine would).
      local proto=type(spec)=='table' and spec.recipe~=nil and type(spec.name)=='string' and prototypes.entity[spec.name]
      if proto then M.recipe_for(p,proto,spec.recipe) end
      local ghost,n,laid,on,tm,cl,tg=place_ghost(p,spec)
      for _,t in ipairs(tg or {}) do new_tiles[#new_tiles+1]=t end
      if ghost.type=='tile-ghost' then new_tiles[#new_tiles+1]=ghost end
      if proto and ghost.type=='entity-ghost' then
        local r,turned=M.set_built_recipe(ghost,spec.recipe,spec.direction~=nil and M.direction_of(spec.direction) or nil)
        recipes[r]=(recipes[r] or 0)+1
        if turned then turned_notes[#turned_notes+1]=string.format('%s (%g,%g): %s',spec.name,ghost.position.x,ghost.position.y,turned) end
      end
      for _,c in ipairs(cl or {}) do
        local k=c.unit_number or (c.position.x..','..c.position.y)
        if not cliffs[k] then cliffs[k]=c; ncliffs=ncliffs+1 end
      end
      -- A turret ghost requests ammo, so the robots that build it bring some (turretammo.lua).
      if ghost.type=='entity-ghost' then
        local what=spec.ammo
        if what==nil then what=ammo end
        local c=M.turretammo.request(ghost,what)
        if c then c.default=what==nil or nil; M.turretammo.add(ammo_rows,c) end
      end
      for _,e in ipairs(tm or {}) do tile_marked[#tile_marked+1]=e end
      marked=marked+#(tm or {})
      if laid then
        tiles_laid=tiles_laid or {}
        for item,count in pairs(laid) do tiles_laid[item]=(tiles_laid[item] or 0)+count end
        laid_under=laid_under+1; laid_on=laid_on or on
      end
      local g=ghost.position
      if ghost.type=='entity-ghost' and M.beltflow.TYPES[ghost.ghost_type] then belts[#belts+1]=ghost end
      if ghost.type=='entity-ghost' and ghost.ghost_type=='inserter' then inserters[#inserters+1]=ghost end
      if ghost.type=='entity-ghost' and ghost.ghost_type=='logistic-container' then chests[#chests+1]=ghost end
      if ghost.type=='entity-ghost' then ghosts[#ghosts+1]=ghost end
      if ghost.type=='entity-ghost' and (ghost.ghost_type=='underground-belt' or ghost.ghost_type=='pipe-to-ground') then
        unders[#unders+1]={ghost=ghost,['end']=ghost.ghost_type=='underground-belt' and (spec.type or 'input') or nil}
      end
      marked=marked+n
      bounds=bounds or {left=g.x,top=g.y,right=g.x,bottom=g.y}
      bounds.left=math.min(bounds.left,g.x); bounds.top=math.min(bounds.top,g.y)
      bounds.right=math.max(bounds.right,g.x); bounds.bottom=math.max(bounds.bottom,g.y)
    end)
    if ok then placed=placed+1 else failed[#failed+1]={index=i,name=type(spec)=='table' and spec.name or nil,position=type(spec)=='table' and spec.position or nil,error=reason(err)} end
    end
  end
  -- (C4) the entries already standing: counted apart from failures
  local already_line
  if #already>0 then
    local g,b=0,0
    for _,r in ipairs(already) do if r.already=='ghost' then g=g+1 else b=b+1 end end
    already_line=string.format('%d entr%s already standing as asked (%d as ghosts, %d built): not placed again, not failures',#already,#already==1 and 'y' or 'ies',g,b)
  end
  -- Underground spans over tiles they cannot pass under (lava, space): once
  -- per span, from a belt entrance or either pipe end (underpass.lua).
  local warnings,seen={},{}
  for _,u in ipairs(unders) do
    local g=u.ghost
    local ok,s=pcall(M.underpass.span,g,u['end'])
    if ok and s and #s.blocked>0 and (s.kind=='pipe-to-ground' or s['end']=='input') then
      -- Both ends of a pipe pair see the same tiles: one warning.
      local tiles={}
      for _,t in ipairs(s.blocked) do tiles[#tiles+1]=t.x..','..t.y end
      table.sort(tiles)
      local key=table.concat(tiles,' ')
      if not seen[key] then
        seen[key]=true
        local why=M.underpass.why(g,u['end'])
        warnings[#warnings+1]=string.format('%s %s ghost at (%g,%g) will stay unpaired: %s',s.name,s['end'] or '',g.position.x,g.position.y,why):gsub('  ',' ')
      end
    end
  end
  -- Inserter ghosts with nothing to take from or put into on their points,
  -- once all of this call's ghosts stand (targets.lua).
  local loose,nloose=M.targets.check(inserters,16)
  -- (d20 batch122, Astra #2087: the dry run counted 32 foundation with 15 holes, the live call laid 17 and two ghosts
  -- stayed unbuilt until the 15 were placed by hand) on a platform, the empty tiles this call's tile ghosts enclose,
  -- by the dry run's rule (dryrun.lua live_holes): laid as tile ghosts too, since the hub builds no foundation that
  -- leaves a hole.
  local holes=M.platform_holes(p,new_tiles,tile_marked)
  -- Tile ghosts laid under entity ghosts that stand on water or wetland: construct lays them first.
  local tile_note
  if tiles_laid then
    local parts={}
    for item,count in pairs(tiles_laid) do parts[#parts+1]=count..' '..item end
    table.sort(parts)
    local n=0
    for _,count in pairs(tiles_laid) do n=n+count end
    tile_note=string.format('%d ghost%s %s on %s: %s tile ghost%s laid under %s, which construct builds first (it takes the items from your inventory)',
      laid_under,laid_under==1 and '' or 's',laid_under==1 and 'stands' or 'stand',laid_on,table.concat(parts,', '),n==1 and '' or 's',laid_under==1 and 'it' or 'them')
  end
  if holes and holes.laid>0 then
    tiles_laid=tiles_laid or {}
    tiles_laid[holes.item]=(tiles_laid[holes.item] or 0)+holes.laid
  end
  -- Logistic chest ghosts no roboport's logistic area covers (a roboport placed in this call counts: it is a ghost now).
  local cover=M.build_notes(p,chests)
  local no_power,outside=M.coverage_notes(p,ghosts)
  -- The last belt ghost: where it moves items, read once all of this call's ghosts stand (beltflow.lua).
  local okb,last_belt=pcall(M.beltflow.last,belts)
  local okl,belt_lines,belts_more=pcall(M.beltflow.lines,belts)
  if not (okl and #belt_lines>1) then belt_lines,belts_more=nil,nil end
  -- Cliffs under the ghosts, marked as a player's placement marks them: one explosive each.
  local cliffs_note
  if ncliffs>0 then
    local by={}
    for _,c in pairs(cliffs) do
      local ok,item=pcall(function() return c.prototype.cliff_explosive_prototype end)
      item=ok and item or 'cliff-explosives'
      by[item]=(by[item] or 0)+1
    end
    local parts={}
    for item,n in pairs(by) do parts[#parts+1]=string.format('%s %d, you hold %d',item,n,p.get_item_count(item)) end
    table.sort(parts)
    cliffs_note=string.format('%d cliff%s under the ghosts %s marked for deconstruction, as a player\'s placement marks them: a marked cliff goes only with one explosive (construction robots bring it from a logistic network): %s',
      ncliffs,ncliffs==1 and '' or 's',ncliffs==1 and 'is' or 'are',table.concat(parts,'; '))
  end
  return {last_belt=okb and last_belt or nil,belts=belt_lines,belts_more=belts_more and belts_more>0 and belts_more or nil,placed=placed,failed=#failed>0 and failed or nil,bounds=bounds,obstacles_marked=marked>0 and marked or nil,
    already_placed=#already>0 and #already or nil,already=already_line,already_list=#already>0 and {table.unpack(already,1,math.min(16,#already))} or nil,
    cliffs_marked=ncliffs>0 and ncliffs or nil,cliffs_note=cliffs_note,
    underground_warnings=#warnings>0 and warnings or nil,inserters_without_target=loose,inserters_without_target_count=nloose,
    tiles_laid=tiles_laid,tiles_note=tile_note,holes_laid=holes and holes.laid>0 and holes.laid or nil,holes_note=holes and holes.note,
    holes_failed=holes and holes.failed,outside_logistic_coverage=cover,tile_obstacles_marked=M.tile_marks_line(tile_marked),
    no_power_coverage=no_power,outside_construction_area=outside,
    ammo_requests=#ammo_rows>0 and ammo_rows or nil,ammo_note=M.turretammo.default_note(ammo_rows),recipes=next(recipes) and recipes or nil,directions_turned=#turned_notes>0 and turned_notes or nil,closes_in=M.ghosts_close_in(p,ghosts)}
end
-- Ghosts that, once built, close the character in where it stands, as the dry run's closes_in reads the plan
-- (friction2: Gemini's dry runs named the last gap out; the real calls said nothing): their boxes flooded with the
-- character's (pathing.lua), and the ghosts that each fill the last gap out.
function M.ghosts_close_in(p,ghosts)
  if #ghosts==0 or (type(p)=='table' and rawget(p,'__platform')) then return nil end
  local c=p.character
  if not (c and c.valid) or c.vehicle or (c.surface and c.surface~=p.surface) then return nil end
  local here,half=c.position or p.position,M.pathing.half(c)
  -- Each ghost as the dry run's record (a wall or pipe stretches toward its neighbours once built: a ghost's box is
  -- the lone wall's, 0.42 tiles apart on 2.0.77, while built walls meet), its box, and the stretched pieces.
  local boxes,near={},{}
  for _,g in ipairs(ghosts) do
    local ok,blocks,proto=pcall(function()
      local pr=g.ghost_prototype
      local m=pr.collision_mask
      return g.ghost_type~='gate' and m and m.layers and m.layers.player,pr
    end)
    local b=g.valid and g.bounding_box
    if ok and blocks and b and b.right_bottom.x>here.x-16 and b.left_top.x<here.x+16 and b.right_bottom.y>here.y-16 and b.left_top.y<here.y+16 then
      local r={proto=proto,pos=g.position,box=b,name=g.ghost_name,dir=g.direction}
      near[#near+1]=r
      boxes[#boxes+1]={b.left_top.x,b.left_top.y,b.right_bottom.x,b.right_bottom.y,g.ghost_name,r,base=true}
    end
  end
  if #boxes==0 then return nil end
  local okp,pieces=pcall(M.dryrun.joined_pieces,p.surface,p.force,near)
  for _,piece in ipairs(okp and pieces or {}) do boxes[#boxes+1]=piece end
  local ok,res=pcall(M.pathing.closes_in,p.surface,here,half,boxes,{ignore=c,force=p.force,search=6})
  if not (ok and res) or res.already then return nil end
  local list={}
  for _,b in ipairs(#res.gaps>0 and res.gaps or res.around) do
    if #list<6 then list[#list+1]=string.format('%s ghost (%g,%g)',b[6].name,b[6].pos.x,b[6].pos.y) end
  end
  local what=#res.gaps==1 and 'the last gap out is where '..list[1]..' stands'
    or #res.gaps>1 and 'without any one of '..table.concat(list,', ')..' a gap out stays'
    or 'the ghosts around it are '..table.concat(list,', ')
  return string.format('once built, these ghosts close the character in where it stands (%g,%g): %s; %s',
    math.floor(here.x*10+0.5)/10,math.floor(here.y*10+0.5)/10,what,M.pathing.area_text(res.region,half))
end
-- A filled rectangle of tile ghosts (landfill, foundation, paths); tiles the
-- game refuses there (landfill on land, a tile already present) are counted.
local function place_tile_area(p,t)
  assert(type(t)=='table' and type(t.area)=='table','tiles requires {name, area={left_top,right_bottom}}')
  local tile=tile_named(t.name); assert(tile,'tiles name must be a tile or an item that places one')
  local lt,rb=position(t.area.left_top),position(t.area.right_bottom)
  local x0,y0,x1,y1=math.floor(lt.x),math.floor(lt.y),math.ceil(rb.x)-1,math.ceil(rb.y)-1
  assert(x1>=x0 and y1>=y0 and (x1-x0+1)*(y1-y0+1)<=4096,'tiles area must be 1..4096 tiles')
  local placed,refused,existing,bounds=0,0,0,nil
  local tile_marked,why={},nil
  for x=x0,x1 do for y=y0,y1 do
    local pos={x=x+0.5,y=y+0.5}
    local ok=false
    local there=p.surface.find_entities_filtered{position=pos,radius=0.1,type='tile-ghost',force=p.force,limit=1}[1]
    if there and there.ghost_name==tile then existing=existing+1; ok=true
    else
      local res,m
      ok,res,m=pcall(place_tile_ghost,p,tile,pos)
      if ok then
        placed=placed+1
        for _,e in ipairs(m or {}) do tile_marked[#tile_marked+1]=e end
      elseif not why and type(res)=='string' and res:find('blocked by',1,true) then why=reason(res) end
    end
    if ok then
      bounds=bounds or {left=x+0.5,top=y+0.5,right=x+0.5,bottom=y+0.5}
      bounds.left=math.min(bounds.left,x+0.5); bounds.top=math.min(bounds.top,y+0.5)
      bounds.right=math.max(bounds.right,x+0.5); bounds.bottom=math.max(bounds.bottom,y+0.5)
    else refused=refused+1 end
  end end
  return {tile=tile,tiles_placed=placed,tiles_existing=existing>0 and existing or nil,tiles_refused=refused>0 and refused or nil,bounds=bounds,
    tiles_refused_why=refused>0 and why or nil,tile_obstacles_marked=M.tile_marks_line(tile_marked),
    obstacles_marked=#tile_marked>0 and #tile_marked or nil}
end
function handlers.place_ghosts(p,a)
  assert(a.entities~=nil or a.tiles~=nil,'place_ghosts requires entities and/or tiles')
  M.fluid_guard(p,a,'place_ghosts')
  local out={}
  if a.entities~=nil then
    assert(type(a.entities)=='table' and #a.entities>=1 and #a.entities<=256,'entities requires 1..256 {name,position,direction?}')
    M.turretammo.check(a.ammo)
    out=place_ghost_list(p,a.entities,a.ammo)
  end
  if a.tiles~=nil then
    local t=place_tile_area(p,a.tiles)
    for k,v in pairs(t) do
      if k=='obstacles_marked' then out[k]=(out[k] or 0)+v
      elseif k=='tile_obstacles_marked' and out[k] then out[k]=out[k]..'; '..v
      elseif k~='bounds' then out[k]=v end
    end
    local b,c=out.bounds,t.bounds
    if c then
      out.bounds=b and {left=math.min(b.left,c.left),top=math.min(b.top,c.top),right=math.max(b.right,c.right),bottom=math.max(b.bottom,c.bottom)} or c
    end
  end
  return out
end
-- A belt or pipe line planned around obstacles and placed as ghosts;
-- construct builds it. dry_run only plans.
local function place_route(p,a,plan,out)
  if a.details then out.entities=plan.entities end
  local inv=p.get_main_inventory()
  for name,n in pairs(plan.items) do
    local have=inv and inv.get_item_count(name) or 0
    if have<n then out.missing=out.missing or {}; out.missing[name]=n-have end
  end
  if a.dry_run then out.dry_run=true; return out end
  local placed=place_ghost_list(p,plan.entities)
  out.placed,out.failed,out.bounds=placed.placed,placed.failed,placed.bounds
  out.obstacles_marked,out.tiles_laid,out.tiles_note=placed.obstacles_marked,placed.tiles_laid,placed.tiles_note
  out.cliffs_marked,out.cliffs_note=placed.cliffs_marked,placed.cliffs_note
  out.last_belt=placed.last_belt
  return out
end
-- (d17 batch14 B3, Opus: a belt_route chose a path past 3 nests) avoid_nests: true routes round the worms and spawners
-- the map shows (avoid_enemies 4 unless given); without either, a line through one's own reach is refused (dry run:
-- said in nests_on_route), avoid_nests: false lays it anyway.
function M.belt_args(a)
  assert(a.avoid_nests==nil or type(a.avoid_nests)=='boolean','avoid_nests must be true or false')
  assert(a.item==nil or type(a.item)=='string' and prototypes.item[a.item],'item is the item name the line is for (its feeders of other items are conflicts)')
  assert(a.refuse_mixed==nil or type(a.refuse_mixed)=='boolean','refuse_mixed must be true or false')
  assert(not a.refuse_mixed or a.item,'refuse_mixed goes with item: the item the line is for')
  if a.avoid_nests==true and (a.avoid_enemies==nil or a.avoid_enemies==false) then
    local b={}; for k,v in pairs(a) do b[k]=v end; b.avoid_enemies=4; return b
  end
  return a
end
function M.belt_nests(p,a,plan)
  if not ((a.avoid_enemies==nil or a.avoid_enemies==false) and a.avoid_nests==nil) then return nil end
  local okg,blocked=pcall(M.avoid.route_guard,p,0)
  if not (okg and blocked) then return nil end
  local seen,list={},{}
  for _,e in ipairs(plan.entities or {}) do
    local why=e.position and blocked(math.floor(e.position.x),math.floor(e.position.y))
    if why and not seen[why] and #list<8 then seen[why]=true; list[#list+1]=string.format('%s at %s',why,M.pathing.at(e.position)) end
  end
  return #list>0 and list or nil
end
-- (d20 batch67 AC2, Astra #1647) what already feeds the planned tiles (routefeeds.lua): inserters dropping there, belts
-- and splitters running in; with item, feeders of other items are conflicts, and refuse_mixed refuses the line.
function M.route_feeders(p,a,plan)
  local ex=plan.existing
  local f=M.routefeeds.check(p.surface,p.force,plan.entities,{item=a.item,joins=ex and ex[#ex] and ex[#ex].position,own=plan.own_entities})
  if f and a.refuse_mixed and (f.conflicts or 0)>0 then
    if a.dry_run then f.refuse='refuse_mixed: a call without dry_run refuses this line and places nothing'
    else
      local lines={}
      for _,r in ipairs(f.rows) do if r.conflict and #lines<3 then lines[#lines+1]=r.line end end
      error(string.format('refuse_mixed: %d feeder%s of items other than %s on the planned tiles, nothing placed: %s',f.conflicts,f.conflicts==1 and '' or 's',a.item,table.concat(lines,'; ')),0)
    end
  end
  return f
end
-- The lines belt_route laid, per agent (the last M.ROUTES_KEPT): a re-run with the same from, via, to, belt and return
-- keeps what stands of the line and places what is missing as ghosts (d17 batch20 A2, Sonnet: a 491-tile line re-run
-- after it was cut). replan: true plans a new line instead.
M.ROUTES_KEPT=4
M.ROUTE_BELT_TYPES={['transport-belt']=true,['underground-belt']=true,splitter=true,loader=true,['loader-1x1']=true,['lane-splitter']=true,['linked-belt']=true}
function M.route_key(p,a)
  local parts={p.surface.name,a.belt or 'transport-belt',a['return'] and 'return' or ''}
  local function add(v) local pos=position(v); parts[#parts+1]=math.floor(pos.x)..','..math.floor(pos.y) end
  add(a.from)
  for _,v in ipairs(type(a.via)=='table' and a.via or {}) do add(v) end
  add(a.to)
  return table.concat(parts,'|')
end
function M.route_repair(p,a,keyed)
  local kept=state().belt_routes and state().belt_routes[p.index]
  local mem
  for _,r in ipairs(kept or {}) do if r.key==keyed then mem=r end end
  if not mem then return nil end
  local missing,differs,standing={},{},0
  for _,e in ipairs(mem.entities) do
    local x,y=e.position.x,e.position.y
    local here
    for _,o in ipairs(p.surface.find_entities_filtered{area={{x-0.1,y-0.1},{x+0.1,y+0.1}},force=p.force}) do
      local t=o.type=='entity-ghost' and o.ghost_type or o.type
      if o.valid and M.ROUTE_BELT_TYPES[t] then here=o end
    end
    if not here then missing[#missing+1]=e
    else
      standing=standing+1
      local dir=directions[e.direction]
      if here.direction~=dir and #differs<8 then
        differs[#differs+1]=string.format('%s at %s faces %s (the line: %s)',here.type=='entity-ghost' and 'ghost of '..here.ghost_name or here.name,M.pathing.at(here.position),
          M.direction_name(here.direction) or tostring(here.direction),e.direction)
      end
    end
  end
  local items={}
  for _,e in ipairs(missing) do items[e.name]=(items[e.name] or 0)+1 end
  return {entities=missing,own_entities=mem.entities,items=items,route=mem.route,tiles=#missing,kept=standing,differs=#differs>0 and differs or nil,
    repair=string.format('the line you laid with these from, via and to %s ago (%d belts and undergrounds): %d stand, %d missing%s; replan: true plans a new line',
      ago(game.tick-mem.tick),#mem.entities,standing,#missing,#missing>0 and (a.dry_run and ', which a call without dry_run places as ghosts' or ', placed as ghosts') or '')}
end
-- (d18 batch39 C3, Sol: ~10 min and 6 dry runs on Wayfarer to end a line where an inserter throws overboard) eject: true
-- (or an inserter name, default inserter) with to near a hull edge: the end is the free tile nearest to (within
-- EJECT_R tiles) where an inserter on foundation picks from the last belt and drops onto empty space off the hull; the
-- route ends on that belt tile and the inserter's ghost is laid with the line.
M.EJECT_R=6
function M.eject_end(p,a)
  local ins=type(a.eject)=='string' and a.eject or 'inserter'
  assert(a.eject==true or type(a.eject)=='string','eject is true or an inserter name')
  local proto=prototypes.entity[ins]
  assert(proto and proto.type=='inserter',ins..' is not an inserter')
  assert(a.to~=nil,'eject needs to: a place near the hull edge the line ends at')
  local belt=a.belt or 'transport-belt'
  local to=position(a.to)
  local tx,ty=math.floor(to.x),math.floor(to.y)
  local function empty(x,y) local ok,t=pcall(function() return p.surface.get_tile(x,y) end); return ok and t and t.valid and t.name=='empty-space' end
  local best,bd
  local STEPS={[0]={0,-1},[4]={1,0},[8]={0,1},[12]={-1,0}}
  for dy=-M.EJECT_R,M.EJECT_R do
    for dx=-M.EJECT_R,M.EJECT_R do
      local ix,iy=tx+dx,ty+dy
      local d2=dx*dx+dy*dy
      if (not bd or d2<bd) and not empty(ix,iy) then
        for _,dir in ipairs({0,4,8,12}) do
          local st=STEPS[dir]
          local I={x=ix+0.5,y=iy+0.5}
          local pick,drop=M.targets.points(proto,I,dir)
          if pick and drop and empty(math.floor(drop.x),math.floor(drop.y)) and not empty(math.floor(pick.x),math.floor(pick.y)) then
            local B={x=math.floor(pick.x)+0.5,y=math.floor(pick.y)+0.5}
            if p.surface.can_place_entity{name=ins,position=I,direction=dir,force=p.force}
              and p.surface.can_place_entity{name=belt,position=B,direction=0,force=p.force} then
              best,bd={inserter=ins,position=I,direction=dir,belt=B,drop={x=math.floor(drop.x)+0.5,y=math.floor(drop.y)+0.5}},d2
              break
            end
          end
        end
      end
    end
  end
  assert(best,string.format('eject: no spot within %d tiles of (%g,%g) where an inserter on foundation picks from a belt tile and drops onto empty space off the hull, both free to place',M.EJECT_R,to.x,to.y))
  local b={}; for k,v in pairs(a) do b[k]=v end
  b.to=best.belt; b.eject=nil
  return b,best
end
function handlers.belt_route(p,a)
  a=M.belt_args(a)
  local ej
  if a.eject~=nil then a,ej=M.eject_end(p,a) end
  assert(a.replan==nil or type(a.replan)=='boolean','replan must be true or false')
  local keyed=M.route_key(p,a)
  local fix=not a.replan and M.route_repair(p,a,keyed)
  if fix then
    local nests=M.belt_nests(p,a,fix)
    if nests and not a.dry_run then
      error(string.format('the missing tiles lie inside the reach of worms or spawners the map shows: %s; avoid_nests: false lays them anyway',table.concat(nests,'; ')),0)
    end
    local feeders=M.route_feeders(p,a,fix)
    local out=place_route(p,a,fix,{repair=fix.repair,route=fix.route,tiles=fix.tiles,items=fix.items,kept=fix.kept,differs=fix.differs,nests_on_route=nests,feeders=feeders})
    out.obstacles_marked=out.obstacles_marked or nil
    return out
  end
  local plan=route.plan(p,a)
  if ej then
    local names={[0]='north',[4]='east',[8]='south',[12]='west'}
    plan.entities[#plan.entities+1]={name=ej.inserter,position=ej.position,direction=names[ej.direction]}
    plan.items[ej.inserter]=(plan.items[ej.inserter] or 0)+1
  end
  local nests=M.belt_nests(p,a,plan)
  if nests and not a.dry_run then
    error(string.format('the line passes inside the reach of worms or spawners the map shows: %s; avoid_nests: true routes round them, avoid_nests: false lays it anyway',
      table.concat(nests,'; ')),0)
  end
  local feeders=M.route_feeders(p,a,plan)
  local out=place_route(p,a,plan,{feeders=feeders,nests_on_route=nests,route=plan.route,tiles=plan.tiles,items=plan.items,arrival=plan.arrival,extends=plan.extends,existing=plan.existing,connected=plan.connected,avoid_enemies=plan.avoid_enemies,avoidance_waypoints=plan.avoidance_waypoints,
    legs=plan.legs,over_trees_or_plants=plan.over_trees_or_plants,landfill=plan.landfill,['return']=plan['return'],cost=plan.cost,
    via_passed=plan.via_passed,joined=plan.joined})
  out.obstacles_marked=out.obstacles_marked or nil
  if ej then out.eject=string.format('the line ends on the belt at (%g,%g); %s at (%g,%g) facing %s picks from it and drops at (%g,%g), empty space off the hull',
    ej.belt.x,ej.belt.y,ej.inserter,ej.position.x,ej.position.y,({[0]='north',[4]='east',[8]='south',[12]='west'})[ej.direction],ej.drop.x,ej.drop.y) end
  if not a.dry_run and (out.placed or 0)>0 then
    local st=state()
    st.belt_routes=st.belt_routes or {}
    local list=st.belt_routes[p.index] or {}
    for i=#list,1,-1 do if list[i].key==keyed then table.remove(list,i) end end
    list[#list+1]={key=keyed,entities=plan.entities,route=plan.route,tick=game.tick}
    while #list>M.ROUTES_KEPT do table.remove(list,1) end
    st.belt_routes[p.index]=list
  end
  return out
end
-- Rails (rails.lua): rail_route plans the 2.0 rail planner's pieces around
-- what blocks them and places them as ghosts; the ones in build reach are
-- built from the inventory unless ghosts=true. train_stop puts a stop on the
-- side of a straight rail where it serves trains heading one way.
M.rails=require('rails'){position=position,directions=directions,chunk_of=chunk_of,
  -- (d20 batch61 W1) why the game refuses a ramp: what stands in its footprint, else the tiles it cannot stand on
  ramp_why=function(p,pos,d)
    local proto=prototypes.entity['rail-ramp']
    local _,_,text,box=M.placewhy.ramp_collisions(p.surface,p.force,proto,pos,d)
    if text and text~='' then return 'its footprint holds '..text end
    local layers,bad=proto.collision_mask.layers,{}
    for _,t in pairs(box and p.surface.find_tiles_filtered{area=box,limit=64} or {}) do
      for k in pairs(t.prototype.collision_mask.layers or {}) do if layers[k] and not bad[t.name] then bad[t.name]=true; bad[#bad+1]=t.name end end
    end
    return #bad>0 and 'its footprint covers '..table.concat(bad,', ') or nil
  end}
-- Ghosts of planned entities in build reach, built from the inventory as
-- construct builds them, without walking; the rest stay ghosts.
function M.rails.build(p,list)
  local built,why,order=0,{},{}
  local reach=p.build_distance or 0
  for _,spec in ipairs(list) do
    if distance(p.position,spec.position)<=reach then
      local g=p.surface.find_entities_filtered{position=spec.position,radius=0.1,ghost_name=spec.name,force=p.force,limit=1}[1]
      local proto=prototypes.entity[spec.name]
      local item=proto and proto.items_to_place_this and proto.items_to_place_this[1]
      if g and g.valid and item then
        local ok,err=pcall(build_one,p,{item=item.name,position=g.position,direction=spec.direction,entity=spec.name,stepped=true})
        if ok and not g.valid then built=built+1
        else
          local r=ok and 'the ghost remained' or reason(err)
          if not why[r] then order[#order+1]=r end
          why[r]=(why[r] or 0)+1
        end
      end
    end
  end
  local not_built={}
  for i=1,math.min(4,#order) do not_built[i]=why[order[i]]..'x '..order[i] end
  return built,#not_built>0 and not_built or nil
end
function handlers.rail_route(p,a)
  assert(a.ghosts==nil or type(a.ghosts)=='boolean','ghosts must be true or false')
  local plan=M.rails.plan(p,a)
  local out=plan.out
  if out.research and out.research.elevated_rail~='researched' then
    error('level elevated: Elevated rail (elevated-rail) is not researched; it unlocks rail ramps, rail supports and elevated rails (dry_run: true shows the plan)',0)
  end
  -- (d20 batch61 W2) a long elevated route: this call's part, ending on its own support; the reply says how to go on
  local part,capped=M.rails.cut(plan,a)
  if part then
    plan.entities=part
    out.route_items=out.items; out.items=capped.items; capped.items=nil
    out.capped=capped
  end
  if a.details then out.entities=plan.entities end
  local inv=p.get_main_inventory()
  for name,n in pairs(out.items) do
    local have=inv and inv.get_item_count(name) or 0
    if have<n then out.missing=out.missing or {}; out.missing[name]=n-have end
  end
  local placed=place_ghost_list(p,plan.entities)
  out.placed,out.failed,out.bounds,out.obstacles_marked=placed.placed,placed.failed,placed.bounds,placed.obstacles_marked
  if not a.ghosts and placed.placed>0 then out.built,out.not_built=M.rails.build(p,plan.entities) end
  return out
end
function handlers.train_stop(p,a)
  -- (d18 batch36 D2) where it goes, named when missing
  assert(a.position~=nil,'train_stop needs position {x, y}: a spot beside a straight rail (the stop stands on the right of the way trains run there), and name: the station name')
  local name=a.name or a.station
  assert(type(name)=='string' and #name>=1 and #name<=100,'name (the station name) is 1..100 characters')
  assert(a.name==nil or a.station==nil or a.name==a.station,'name and station differ; give one of them')
  assert(a.ghosts==nil or type(a.ghosts)=='boolean','ghosts must be true or false')
  local limit=a.limit~=nil and integer(a.limit,nil,0,1000,'limit (0..1000)') or nil
  local cands=M.rails.stop_spot(p,a)
  -- The nearest spot, else the next ones serving the same way along the rail.
  local chosen,errs=nil,{}
  for _,c in ipairs(cands) do
    if c.heading==cands[1].heading and #errs<3 then
      local ok,ghost=pcall(place_ghost,p,{name='train-stop',position=c.spot,direction=M.rails.NAMES[c.heading]})
      if ok then chosen=c; c.ghost=ghost; break end
      errs[#errs+1]=string.format('(%g,%g): %s',c.spot.x,c.spot.y,reason(ghost))
    end
  end
  if not chosen then
    local ok,one_way=pcall(M.rails.line_signals,p,cands[1])
    error('no train stop fits beside the rail for trains heading '..M.rails.NAMES[cands[1].heading]..': '..(ok and one_way or table.concat(errs,'; ')),0)
  end
  chosen.ghost.backer_name=name
  if limit then chosen.ghost.trains_limit=limit end
  local h=chosen.heading
  local out={stop=name,position=chosen.spot,direction=M.rails.NAMES[h],serves='trains heading '..M.rails.NAMES[h],
    side=({[0]='east',[4]='south',[8]='west',[12]='north'})[h]..' of the rail',
    rail={position=chosen.rail.e.position,ghost=chosen.rail.ghost or nil},limit=limit}
  if not a.ghosts then
    local built,not_built=M.rails.build(p,{{name='train-stop',position=chosen.spot,direction=M.rails.NAMES[h]}})
    out.built=built>0 or nil; out.not_built=not_built
  end
  if not out.built then
    out.ghost=true
    out.bounds={left=chosen.spot.x,top=chosen.spot.y,right=chosen.spot.x,bottom=chosen.spot.y}
    if distance(p.position,chosen.spot)>(p.build_distance or 0) then out.reach=string.format('%.1f tiles from you, build reach %g',distance(p.position,chosen.spot),p.build_distance or 0) end
  end
  return out
end
-- Long pipelines go in legs: through the given waypoints, or (beyond one
-- search's span) through free tiles picked along the straight line. Each leg
-- starts from the pipe ghost the previous one ended with.
local PIPE_LEG=150
local function free_pipe_tile(p,name,pos)
  local x0,y0=math.floor(pos.x),math.floor(pos.y)
  for r=0,6 do
    for dx=-r,r do for dy=-r,r do
      if math.max(math.abs(dx),math.abs(dy))==r then
        local c={x=x0+dx+0.5,y=y0+dy+0.5}
        if charted(p,c) and p.surface.can_place_entity{name=name,position=c,direction=0,force=p.force,build_check_type=defines.build_check_type.manual_ghost}
          and #p.surface.find_entities_filtered{position=c,radius=0.3,type='entity-ghost'}==0 then return c end
      end
    end end
  end
end
local function pipe_leg(p,a,from,to,reserved,from_held)
  local args={}
  for k,v in pairs(a) do if k~='waypoints' and k~='pumps' then args[k]=v end end
  args.from,args.to,args.reserved,args.from_held=from,to,reserved,from_held
  local plan=pipes.plan(p,args)
  return place_route(p,args,plan,{route=plan.route,tiles=plan.tiles,items=plan.items,joins=plan.joins}),plan
end
-- The existing segment a route end joins (pipes and tanks; machines and pumps
-- start segments of their own); a pipe ghost there with the line it is part of
-- (pipes.line_box: looked up by ghost_name, Astra 08:19).
local function joined_box(p,join)
  if not join then return nil end
  return pipes.line_box(p.surface,p.force,join,pipes.extent_limit())
end
-- Pumps where the finished route would pass the segment extent limit; with
-- place, they replace the route's own pipe ghosts on those tiles.
local function route_pumps(p,out,entities,joins_from,joins_to,place)
  local limit=pipes.extent_limit()
  local ext=pipes.pump_plan(entities,joined_box(p,joins_from),joined_box(p,joins_to),limit)
  out.segment_extent=ext.extent
  if ext.extent<=limit then return end
  out.extent_warning=string.format('this pipeline makes one fluid segment spanning %d tiles (limit %d, including the pipes it joins): the game stops all flow into it; %s',
    ext.extent,limit,ext.unsplittable or (place and 'pumps placed as below (they need power)' or 'add the pumps below (pumps=true places them; they need power), flowing from -> to'))
  local rows={}
  for i,pump in ipairs(ext.pumps or {}) do rows[i]={position=pump.position,direction=pump.direction} end
  out.pumps=#rows>0 and rows or nil
  if not place or out.dry_run or #rows==0 then return end
  local placed,failed=0,{}
  for _,pump in ipairs(ext.pumps) do
    local ok,err=pcall(function()
      for _,k in ipairs(pump.tiles) do
        for _,g in pairs(p.surface.find_entities_filtered{position=entities[k].position,radius=0.1,type='entity-ghost',force=p.force}) do
          if g.valid and g.ghost_name==entities[k].name then g.destroy() end
        end
      end
      place_ghost(p,{name='pump',position=pump.position,direction=pump.direction})
    end)
    if ok then placed=placed+1 else failed[#failed+1]=string.format('(%g,%g): %s',pump.position.x,pump.position.y,reason(err)) end
  end
  out.pumps_placed=placed; out.pump_failures=#failed>0 and failed or nil
  if placed>0 then
    out.items.pump=(out.items.pump or 0)+placed
    local pipe=entities[1] and entities[ext.pumps[1].tiles[1]].name
    if pipe and out.items[pipe] then out.items[pipe]=out.items[pipe]-2*placed end
  end
end
-- A line of power poles from A to B (through optional waypoints) as ghosts,
-- spaced within the pole's wire reach, each pole shifted sideways by up to
-- two tiles when its spot is blocked (water, a building, a tree that
-- construct would have to clear). Existing own poles of the same kind on the
-- line are reused. construct then builds it, like belt_route and pipe_route.
function handlers.pole_route(p,a)
  local item=a.item or 'small-electric-pole'
  local proto=prototypes.item[item]
  assert(proto and proto.place_result and proto.place_result.type=='electric-pole','item must place an electric pole (small-electric-pole, medium-electric-pole, big-electric-pole)')
  local pole=proto.place_result
  local ok,reach=pcall(function() return pole.get_max_wire_distance and pole.get_max_wire_distance() or pole.max_wire_distance end)
  reach=ok and tonumber(reach) or 7.5
  -- Spacing leaves room for a two-tile sideways shift inside the wire reach.
  local spacing=integer(a.spacing,math.max(1,math.floor(math.sqrt(reach*reach-4))),1,64,'spacing')
  assert(spacing<=reach,string.format('spacing %d is beyond the wire reach %g of %s',spacing,reach,item))
  local box=pole.collision_box or {left_top={x=-0.4,y=-0.4},right_bottom={x=0.4,y=0.4}}
  -- Footprint width in tiles: 1x1 poles sit on tile centres, 2x2 on corners.
  local even=math.ceil(box.right_bottom.x-box.left_top.x-0.01)%2==0
  local function snap(pos)
    if even then return {x=math.floor(pos.x+0.5),y=math.floor(pos.y+0.5)} end
    return {x=math.floor(pos.x)+0.5,y=math.floor(pos.y)+0.5}
  end
  local points={position(a.from)}
  for _,w in ipairs(a.waypoints or {}) do points[#points+1]=position(w) end
  points[#points+1]=position(a.to)
  assert(#points<=18,'waypoints requires at most 16 entries')
  local function free(pos)
    return p.surface.can_place_entity{name=pole.name,position=pos,force=p.force,build_check_type=defines.build_check_type.manual_ghost,forced=true}
  end
  -- The forced ghost check also takes water and Gleba wetland once the force
  -- has landfill (Sol, shift09: 5 of 16 poles on wetland, which construct
  -- could not build): a spot the pole stands on as the tiles are comes first,
  -- else one with landfill under it (place_ghosts lays its ghost).
  local function dry(pos) return not M.dryrun.tile_fixes(p.surface,p.force,pole,pos,0) end
  local function existing(pos)
    for _,e in pairs(p.surface.find_entities_filtered{position=pos,radius=1.1,name=pole.name,force=p.force,limit=1}) do
      if e.valid then return e end
    end
    for _,e in pairs(p.surface.find_entities_filtered{position=pos,radius=1.1,ghost_name=pole.name,force=p.force,limit=1}) do
      if e.valid then return e end
    end
  end
  local specs,reused,failed,last={},0,{},nil
  local function place(want,perp)
    local pos=snap(want)
    local there=existing(pos)
    if there then reused=reused+1; last=there.position; return end
    for pass=1,2 do
      for _,d in ipairs({0,1,-1,2,-2}) do
        local try={x=pos.x+perp.x*d,y=pos.y+perp.y*d}
        local ok_dist=not last or distance(last,try)<=reach
        if ok_dist and free(try) and (pass==2 or dry(try)) then specs[#specs+1]={name=pole.name,position=try}; last=try; return end
      end
    end
    failed[#failed+1]={position=pos,error=placement_error(p,pole,pos,0)}
    last=pos
  end
  local total=0
  for i=1,#points-1 do
    local from,to=points[i],points[i+1]
    local dx,dy=to.x-from.x,to.y-from.y
    local length=(dx*dx+dy*dy)^0.5
    assert(length<=512,'a leg is longer than 512 tiles')
    total=total+length
    assert(total<=1024,'the route is longer than 1024 tiles')
    local ux,uy=length>0 and dx/length or 0,length>0 and dy/length or 0
    local perp=math.abs(ux)>=math.abs(uy) and {x=0,y=1} or {x=1,y=0}
    local steps=math.max(1,math.ceil(length/spacing))
    for k=(i==1 and 0 or 1),steps-1 do place({x=from.x+ux*(length*k/steps),y=from.y+uy*(length*k/steps)},perp) end
    if i==#points-1 then place(to,perp) end
  end
  local out={item=item,spacing=spacing,wire_reach=reach,poles=#specs,reused=reused>0 and reused or nil,failed=#failed>0 and failed or nil}
  local held=p.get_main_inventory().get_item_count(item)
  out.held=held; out.short=#specs>held and #specs-held or nil
  -- Poles with no dry spot within 2 tiles stand on water or wetland: the
  -- tile items laid under them.
  local under,on,wet={},nil,0
  for _,spec in ipairs(specs) do
    local fixes=M.dryrun.tile_fixes(p.surface,p.force,pole,spec.position,0)
    if fixes then wet=wet+1 end
    for _,f in ipairs(fixes or {}) do
      if f.item then under[f.item]=(under[f.item] or 0)+1; on=on or f.tile end
    end
  end
  if next(under) then
    out.tiles_under=under
    local parts={}
    for name,n in pairs(under) do
      parts[#parts+1]=n..' '..name
      local have=p.get_main_inventory().get_item_count(name)
      if have<n then out.tiles_short=out.tiles_short or {}; out.tiles_short[name]=n-have end
    end
    table.sort(parts)
    out.tiles_note=string.format('%d pole%s with no dry spot within 2 tiles %s on %s: %s under %s, %s',wet,wet==1 and '' or 's',wet==1 and 'stands' or 'stand',on,
      table.concat(parts,', '),wet==1 and 'it' or 'them',
      a.dry_run and 'which the real call lays as tile ghosts for construct to build first' or 'laid as tile ghosts that construct builds first')
  end
  if a.dry_run then out.positions={}; for i,s in ipairs(specs) do out.positions[i]=s.position end; return out end
  if #specs>0 then
    local placed=handlers.place_ghosts(p,{entities=specs})
    out.placed=placed.placed; out.bounds=placed.bounds; out.obstacles_marked=placed.obstacles_marked
    if placed.failed then for _,f in ipairs(placed.failed) do failed[#failed+1]={position=specs[f.index].position,error=f.error} end; out.failed=failed end
  end
  out.note=#specs>0 and (type(p)=='table' and rawget(p,'__remote') and string.format('ghosts placed on %s by remote view; its construction robots build them (no hand reach there)',p.surface.name)
    or 'ghosts placed; run construct (default area: these bounds) to build them'..(out.short and string.format('; craft %d more %s first',out.short,item) or '')) or 'nothing to place'
  return out
end
function handlers.pipe_route(p,a)
  local from,to=position(a.from),position(a.to)
  local points={from}
  if a.waypoints~=nil then
    assert(type(a.waypoints)=='table' and #a.waypoints>=1 and #a.waypoints<=16,'waypoints requires 1..16 {x,y} free tiles')
    for _,w in ipairs(a.waypoints) do points[#points+1]=position(w) end
  else
    local span=math.abs(to.x-from.x)+math.abs(to.y-from.y)
    local legs=math.ceil(span/PIPE_LEG)
    for k=1,legs-1 do
      local want={x=from.x+(to.x-from.x)*k/legs,y=from.y+(to.y-from.y)*k/legs}
      local w=free_pipe_tile(p,a.pipe or 'pipe',want)
      assert(w,string.format('no free tile for an automatic waypoint near (%g,%g); give waypoints',want.x,want.y))
      points[#points+1]=w
    end
  end
  points[#points+1]=to
  assert(a.pumps==nil or type(a.pumps)=='boolean','pumps must be boolean')
  local out={route={},tiles=0,items={},placed=0}
  if #points>2 then
    out.legs=#points-1; out.waypoints={}
    for i=2,#points-1 do out.waypoints[#out.waypoints+1]=points[i] end
  end
  local entities,first_join,last_join={},nil,nil
  -- A dry run places nothing, so each leg would see the ground before the earlier ones: their tiles are reserved
  -- (all but the waypoint the next leg starts from), as their ghosts take them in the real call (Astra 08:19: a dry
  -- run planned leg 2 back over leg 1; the real call then failed at the waypoint).
  local reserved=a.dry_run and #points>2 and {} or nil
  local held_end
  for i=1,#points-1 do
    local ok,leg,plan=pcall(pipe_leg,p,a,points[i],points[i+1],reserved,held_end)
    if ok and reserved then
      held_end=plan.tail
      local wx,wy=math.floor(points[i+1].x),math.floor(points[i+1].y)
      for _,e in ipairs(plan.entities) do
        local x,y=math.floor(e.position.x),math.floor(e.position.y)
        if x~=wx or y~=wy then reserved[x..','..y]=true end
      end
    end
    if not ok then
      if #points==2 then error(leg,0) end
      error(string.format('pipe_route leg %d/%d (%g,%g)->(%g,%g) failed: %s%s',i,#points-1,points[i].x,points[i].y,points[i+1].x,points[i+1].y,reason(leg),
        out.bounds and string.format('; legs before it placed %d ghosts in (%g,%g)-(%g,%g)',out.placed,out.bounds.left,out.bounds.top,out.bounds.right,out.bounds.bottom) or ''),0)
    end
    for _,e in ipairs(plan.entities) do entities[#entities+1]=e end
    if i==1 then first_join=plan.joins and plan.joins.from end
    if i==#points-1 then last_join=plan.joins and plan.joins.to end
    out.route[i]=leg.route; out.tiles=out.tiles+(leg.tiles or 0); out.placed=out.placed+(leg.placed or 0)
    for name,n in pairs(leg.items or {}) do out.items[name]=(out.items[name] or 0)+n end
    for _,f in ipairs(leg.failed or {}) do out.failed=out.failed or {}; f.leg=#points>2 and i or nil; out.failed[#out.failed+1]=f end
    if leg.entities then out.entities=out.entities or {}; for _,e in ipairs(leg.entities) do out.entities[#out.entities+1]=e end end
    local b=leg.bounds
    if b then
      local t=out.bounds
      out.bounds=t and {left=math.min(t.left,b.left),top=math.min(t.top,b.top),right=math.max(t.right,b.right),bottom=math.max(t.bottom,b.bottom)} or b
    end
    out.dry_run=leg.dry_run
  end
  if first_join or last_join then out.joins={from=first_join,to=last_join} end
  route_pumps(p,out,entities,first_join,last_join,a.pumps==true)
  local inv=p.get_main_inventory()
  for name,n in pairs(out.items) do
    local have=inv and inv.get_item_count(name) or 0
    if have<n then out.missing=out.missing or {}; out.missing[name]=n-have end
  end
  out.route=table.concat(out.route,' | ')
  if out.dry_run and #points>2 then out.note='dry_run plans the legs in order, each kept off the tiles of the legs before it' end
  if out.dry_run then out.placed=nil end
  return out
end
end -- repeat={count,dx,dy} stamps the same placement count times, each shifted by
-- (dx,dy) from the previous one: a row of furnaces or turrets in one call.
-- Copies are independent; one that fails does not stop the rest.
do local function shifted(pos,dx,dy) local p0=position(pos); return {x=p0.x+dx,y=p0.y+dy} end
local repeat_shift={
  paste=function(a,dx,dy) return {position=shifted(a.position,dx,dy)} end,
  blueprint_place=function(a,dx,dy) return {position=shifted(a.position,dx,dy)} end,
  place_ghosts=function(a,dx,dy)
    local list={}
    for i,spec in ipairs(type(a.entities)=='table' and a.entities or {}) do
      list[i]={name=spec.name,direction=spec.direction,position=shifted(spec.position,dx,dy)}
    end
    return {entities=list}
  end}
for name,shift in pairs(repeat_shift) do
  local handler=handlers[name]
  handlers[name]=function(p,a)
    local r=a['repeat']
    if r==nil then return handler(p,a) end
    assert(type(r)=='table','repeat is {count,dx,dy}')
    local count=integer(r.count,1,1,64,'repeat count')
    local dx,dy=r.dx or 0,r.dy or 0
    assert(type(dx)=='number' and type(dy)=='number' and (dx~=0 or dy~=0),'repeat needs a nonzero dx or dy')
    local total={copies={}}
    for i=0,count-1 do
      local args={}
      for k,v in pairs(a) do if k~='repeat' then args[k]=v end end
      for k,v in pairs(shift(a,i*dx,i*dy)) do args[k]=v end
      local ok,out=pcall(handler,p,args)
      local row={index=i+1,position=args.position or (args.entities[1] and args.entities[1].position)}
      if not ok then row.error=reason(out)
      else
        for k,v in pairs(out) do
          if type(v)=='number' and k~='expected' and k~='existing_ghosts' and k~='existing_entities' then total[k]=(total[k] or 0)+v; row[k]=v end
        end
        row.reason=out.reason; row.wires=out.wires
        for item,n in pairs(out.by_name or {}) do total.by_name=total.by_name or {}; total.by_name[item]=(total.by_name[item] or 0)+n end
        for _,failure in ipairs(out.failed or {}) do
          total.failed=total.failed or {}; failure.copy=i+1; total.failed[#total.failed+1]=failure
        end
        local b=out.bounds
        if b then
          local t=total.bounds
          if t then t.left=math.min(t.left,b.left); t.top=math.min(t.top,b.top); t.right=math.max(t.right,b.right); t.bottom=math.max(t.bottom,b.bottom)
          else total.bounds={left=b.left,top=b.top,right=b.right,bottom=b.bottom} end
        end
      end
      total.copies[#total.copies+1]=row
    end
    return total
  end
end
end -- Remember where the last paste put ghosts so `construct` can default to it.
for _,name in ipairs({'paste','blueprint_place','place_ghosts','belt_route','pipe_route','rail_route','train_stop'}) do
  local handler=handlers[name]
  handlers[name]=function(p,a)
    local out=handler(p,a)
    -- construct works on the character's surface; platform ghosts are the hub's.
    if out.bounds and not (type(p)=='table' and rawget(p,'__platform')) then state().last_paste=state().last_paste or {}; state().last_paste[p.index]=out.bounds end
    return out
  end
end
-- Fluid ports of an entity not built yet (ports.lua; Gemini: a recipe moves
-- which fluid an electromagnetic plant's ports carry): each connection's tile,
-- the tile outside it where a pipe joins, facing, flow and the recipe's fluid
-- there, with what stands on that tile now.
-- What a planned build takes away (conflicts.lua; Sonnet, shift14 21:20: rich sulfuric acid wells under pipes, poles
-- and tanks): every entity in the way, the resource under it, and the fluid segments and power links taking them cuts.
M.conflicts=require('conflicts'){compass=compass_names,
  tile_fixes=function(surface,force,proto,pos,dir) return M.dryrun.tile_fixes(surface,force,proto,pos,dir) end,
  tile_rules=function(surface,proto,pos,dir) return (M.placewhy.tile_rules(surface,proto,pos,dir)) end}
function handlers.conflicts(p,a)
  assert(type(a.name)=='string','name: the entity to build (or the item that places it), e.g. pumpjack')
  local proto=prototypes.entity[a.name]
  if not proto and prototypes.item[a.name] then proto=prototypes.item[a.name].place_result end
  assert(proto,'unknown entity '..a.name)
  local dir=0
  if a.direction~=nil then dir=M.direction_of(a.direction); assert(dir,'direction must be a compass name (north, east, south, west) or 0..15') end
  local pos=M.dryrun.snap(proto,position(a.position),dir)
  assert(charted(p,pos),string.format('(%g,%g) is in a chunk our force has not charted',pos.x,pos.y))
  local box=M.dryrun.footprint(proto,pos,dir)
  return M.conflicts.read(p,a,{proto=proto,pos=pos,dir=dir,box=box})
end
function handlers.ports(p,a)
  assert(type(a.name)=='string','name is required: an entity (or the item that places it), e.g. electromagnetic-plant')
  local proto=prototypes.entity[a.name]
  if not proto and prototypes.item[a.name] then proto=prototypes.item[a.name].place_result end
  assert(proto,'unknown entity '..a.name)
  local direction=directions[a.direction or 'north']
  assert(direction and direction%4==0,'direction must be north, east, south or west')
  assert(a.mirror==nil or type(a.mirror)=='boolean','mirror must be true or false (the H/V flip of fluid machines)')
  local pos=M.dryrun.snap(proto,position(a.position),direction)
  local recipe=M.ports.recipe(proto,a.recipe)
  local rows,closed=M.ports.rows({prototype=proto,position=pos,direction=direction,mirroring=a.mirror==true},recipe)
  assert(#rows>0 or #closed>0,proto.name..' has no fluid connections')
  if charted(p,pos) then
    for _,r in ipairs(rows) do
      if not r.kind then
        for _,o in pairs(p.surface.find_entities_filtered{position=r.joins,radius=0.3,force=p.force,limit=4}) do
          if o.valid and o.type~='character' then r.there=o.type=='entity-ghost' and o.ghost_name..' (ghost)' or o.name; break end
        end
      end
    end
  end
  local note
  if proto.crafting_categories and not recipe then note='the recipe decides which ports open and the fluid of each: pass recipe'
  elseif #closed>0 then note='closed ports take no pipe with this recipe' end
  return {name=proto.name,position=pos,direction=compass_names[direction],mirror=a.mirror or nil,recipe=recipe and recipe.name or nil,
    ports=rows,closed=#closed>0 and closed or nil,note=note}
end
-- trace (trace.lua, set up with supply below); here so platform= wraps it.
function handlers.trace(p,a) return M.readmemory.read(p,a,'trace',M.trace.trace) end
-- Remote building on our space platforms: the same ghost and view actions,
-- run against the platform's surface (hub at its centre). The hub builds
-- the ghosts from its own inventory, as in the game.
do local function on_platform(p,name)
  local pl=space.platform(p,name)
  assert(pl.surface,'platform '..pl.name..' has no surface yet (waiting for its starter pack)')
  local hub=pl.hub and pl.hub.valid and pl.hub.position or {x=0,y=0}
  return setmetatable({__player=real(p),__platform=pl.name},{
    __index=function(_,k) if k=='surface' then return pl.surface elseif k=='position' then return hub end return p[k] end,
    __newindex=function(_,k,v) p[k]=v end})
end
-- Whether entity e takes item as a hand move would put it (Luna, d15: timed walks to a machine that did not use the item):
-- the inventory infer_inventory picks (or the one named), the recipe, the slots and filters, read now.
function M.accepts_text(e,a)
  local where=string.format('%s (%g,%g)',e.name,e.position.x,e.position.y)
  local args={direction='to_entity',item=a.item,inventory=a.inventory,quality=a.quality}
  local okn,name,inv
  if a.inventory~=nil then okn,inv=pcall(inventory,e,a.inventory); name=okn and M.inventory_name(e,a.inventory) or inv; if not okn then name=inv end
  else okn,name,inv=pcall(infer_inventory,e,args) end
  if not okn then return 'no: '..where..': '..tostring(name):gsub('^[^:]*:%d+: ','') end
  if not inv then return 'no: '..where..' has no inventory that takes '..a.item end
  -- An assembler takes only its recipe's ingredients; a furnace takes any smeltable while its source is empty (the
  -- game picks the recipe), so its slots decide.
  local recipe=name=='assembling_machine_input' and select(2,pcall(function() return e.get_recipe() end)) or nil
  if (name=='assembling_machine_input') and not recipe then return string.format('no: %s has no recipe set (its input takes nothing)',where) end
  if recipe then
    local takes,list=false,{}
    for _,ing in ipairs(recipe.ingredients or {}) do if ing.type~='fluid' then list[#list+1]=ing.name; if ing.name==a.item then takes=true end end end
    if not takes then return string.format('no: %s recipe %s takes %s, not %s',where,recipe.name,#list>0 and table.concat(list,', ') or 'no items',a.item) end
  end
  local okc,can=pcall(function() return inv.can_insert({name=a.item,count=1,quality=a.quality or 'normal'}) end)
  if okc and can==false then
    local okf,full=pcall(M.slots.full,inv,a.item)
    if okf and full then return string.format('no: %s %s is full: %s',where,name,full.text) end
    -- A furnace: whether any recipe of its crafting categories takes the item at all.
    if name=='furnace_source' then
      local okc2,cats=pcall(function() return e.prototype.crafting_categories end)
      local okr,list=pcall(function() return prototypes.get_recipe_filtered{{filter='has-ingredient-item',elem_filters={{filter='name',name=a.item}}}} end)
      local smelts=false
      for _,r in pairs(okr and list or {}) do if okc2 and cats and cats[r.category] then smelts=true end end
      if okr and not smelts then return string.format('no: %s makes nothing from %s (no recipe of its crafting categories takes it)',where,a.item) end
    end
    local fr=name=='furnace_source' and select(2,pcall(function() return e.get_recipe() or e.previous_recipe end)) or nil
    local frn=fr and (type(fr.name)=='string' and fr.name or fr.name and fr.name.name)
    if frn then return string.format('no: %s %s refuses %s now (its recipe %s; a furnace switches recipe only once its source is empty)',where,name,a.item,frn) end
    return string.format('no: %s %s refuses %s (a slot filter, or the item does not go in that inventory)',where,name,a.item)
  end
  return string.format('yes: %s takes %s into %s',where,a.item,name)
end
-- A courier's dry run (A3): the source (the first holding the item, as pick first_with_stock takes it: what it holds,
-- what robots have reserved there), the destination (whether it takes the item, the room for it), and the count that
-- would move: the least of count, what the source holds free and the room.
M.COURIER_INVS={'chest','assembling_machine_input','furnace_source','lab_input','rocket_silo_rocket','cargo_wagon','car_trunk','spider_trunk','hub_main','cargo_landing_pad_main'}
-- A side of a courier as its GUI shows it (d17 batch19 B3, Luna ~4x a shift: whether a move starves a request, spoils
-- on the way or races the robots): a requester or buffer chest's request for the item (asks: its min) and what robots
-- bring into it now (coming); the soonest spoil of its stacks of the item (spoil: ticks left, percent, hatches: an
-- item whose spoiling makes an enemy, as spoil.lua reads it).
function M.courier_side(e,item,quality)
  local out={}
  local okp,pt=pcall(function() return e.get_logistic_point(defines.logistic_member_index.logistic_container) end)
  if okp and pt and M.reqchest then
    local min,_,named=M.reqchest.request(pt,item)
    if named and min>0 then out.asks=min end
    local coming=0
    local okc,list=pcall(function() return pt.targeted_items_deliver end)
    for k,c in pairs(okc and list or {}) do
      if type(c)=='number' and k==item then coming=coming+c
      elseif type(c)=='table' and (type(c.name)=='table' and c.name.name or c.name)==item then coming=coming+(c.count or 0) end
    end
    if coming>0 then out.coming=coming end
  end
  local soon,pct
  for _,name in ipairs(take_order) do
    local ok,inv=pcall(inventory,e,name)
    if ok and inv then
      for i=1,#inv do
        local st=inv[i]
        if st.valid_for_read and st.name==item and (st.quality and st.quality.name or 'normal')==(quality or 'normal') then
          local okt,t=pcall(function() return st.spoil_tick end)
          if okt and t and t>0 and (not soon or t<soon) then soon=t; pct=st.spoil_percent end
        end
      end
    end
  end
  if soon then
    local okh,h=pcall(function() return M.spoil.hatch(item) end)
    out.spoil={ticks=math.max(0,soon-game.tick),percent=math.floor((pct or 0)*100+0.5),hatches=okh and h and h.entity or nil}
  end
  return out
end
function M.courier_dry(p,a,list,dest)
  local item=a.item
  if type(item)~='string' then return {line='courier: name item to read what would move'} end
  local src,held,reserved
  for _,q in ipairs(list) do
    local ok,e=pcall(entity,p,{position=position(type(q)=='table' and (q.position or q) or q)},'walk')
    if not ok then ok,e=pcall(remote_entity,p,{position=position(type(q)=='table' and (q.position or q) or q)}) end
    if ok and e then
      local n=entity_holds(e,item,a.quality)
      local okr,r=pcall(M.supply.reserved,e,item)
      if n>0 or not src then src,held,reserved=e,n,okr and r or 0 end
      if n>0 then break end
    end
  end
  local okd,d=pcall(entity,p,{position=dest},'walk')
  if not okd then okd,d=pcall(remote_entity,p,{position=dest}) end
  local room
  if okd and d then
    for _,name in ipairs(a.to_inventory and {a.to_inventory} or M.COURIER_INVS) do
      local oki,inv=pcall(inventory,d,name)
      if oki and inv then
        local okc,c=pcall(function() return inv.get_insertable_count({name=item,quality=a.quality or 'normal'}) end)
        if okc and c then room=(room or 0)+c; break end
      end
    end
  end
  local free=src and math.max(0,(held or 0)-(reserved or 0)) or 0
  local want=a.count or free
  local moves=math.min(want,free,room or want)
  -- B3: the source's request kept (spare: what can leave it with its request still filled), the destination's request
  -- and deliveries, the soonest spoil or hatch of what would move
  local sside=src and M.courier_side(src,item,a.quality) or {}
  local dside=okd and d and M.courier_side(d,item,a.quality) or {}
  local spare=sside.asks and math.max(0,free-sside.asks) or free
  local function span(t) local s2=math.floor(t/60); return s2>=60 and string.format('%dm%02ds',math.floor(s2/60),s2%60) or s2..'s' end
  local facts={}
  if sside.asks then
    facts[#facts+1]=string.format('the source asks %d itself%s: %d can leave it with its request still filled',sside.asks,
      sside.coming and string.format(' (robots bring %d now)',sside.coming) or '',spare)
  end
  if dside.asks then
    local short=math.max(0,dside.asks-entity_holds(d,item,a.quality)-(dside.coming or 0))
    facts[#facts+1]=string.format('the destination asks %d%s; %d short of it',dside.asks,dside.coming and string.format(', robots bring %d now',dside.coming) or '',short)
  elseif dside.coming then facts[#facts+1]=string.format('robots bring the destination %d now',dside.coming) end
  if sside.spoil then
    facts[#facts+1]=string.format('its first stack %s in %s (%d%% spoiled)',sside.spoil.hatches and 'hatches into '..sside.spoil.hatches or 'spoils',span(sside.spoil.ticks),sside.spoil.percent)
  end
  -- What arrives: the courier carries it, and over a personal request's max the game trashes the rest (D3, Luna 00:20:
  -- 1000 iron plates moved with a max of 40; 40 arrived).
  local cap=a.personal_logistics~='pause' and M.trash.room(p,item,a.quality) or nil
  local arrives=cap and math.min(moves,cap) or moves
  local src_text=src and string.format('%s (%g,%g) holds %d %s%s',src.name,src.position.x,src.position.y,held or 0,item,
    (reserved or 0)>0 and string.format(' (robots have %d reserved)',reserved) or '') or 'no source of ours found there'
  local dest_text=okd and d and string.format('%s (%g,%g): %s%s',d.name,d.position.x,d.position.y,(M.accepts_text(d,{item=item,inventory=a.to_inventory}):gsub('^(%a+): [^%(]*%b() ','%1, ')),
    room and string.format(', room for %d',room) or '') or string.format('no entity of ours in sight at (%g,%g)',dest.x,dest.y)
  return {from=src_text,to=dest_text,moves=moves,arrives=arrives,spare=spare,source_asks=sside.asks,source_coming=sside.coming,
    dest_asks=dside.asks,dest_coming=dside.coming,spoil=sside.spoil,facts=#facts>0 and facts or nil,
    line=string.format('takes %s from %s, gives it at %s: %d would move (asked %s)%s%s',item,src_text,dest_text,moves,a.count and tostring(a.count) or 'all',
      #facts>0 and '; '..table.concat(facts,'; ') or '',
      arrives<moves and string.format('; %d would arrive: your personal request for %s has max %d, and the game moves what you carry over it to your trash slots (personal_logistics: "pause" switches them off for the move)',
        arrives,item,M.trash.cap(M.trash.limits(p),item,a.quality) or 0) or '')}
end
-- Walking tours with dry_run (d15 batch3 item 4; Haiku, Luna): the route through the stops read now (routecheck.lua),
-- nothing walked or moved. The stops are the positions given, nearest first from you; a radius or area tour chooses its
-- stops when it runs.
for _,name in ipairs({'feed','collect','transfer','rearm','refuel'}) do
  local handler=handlers[name]
  handlers[name]=function(p,a)
    if type(a)~='table' or a.dry_run==nil or a.dry_run==false then return handler(p,a) end
    assert(a.dry_run==true,'dry_run must be true or false')
    local list=a.positions or (a.position~=nil and {a.position}) or nil
    -- rearm's radius, area or surface tour (A4): its stops as it would choose them now
    local plan
    if name=='rearm' and (a.radius~=nil or a.area~=nil or a.surface~=nil) then
      local rest={}
      for k,v in pairs(a) do if k~='dry_run' then rest[k]=v end end
      rest.dry_run_plan=true
      plan=M.rearm_now(p,rest)
      list={}
      for i,e in ipairs(plan.plan or {}) do if i<=128 then list[i]=e.position end end
      if #list==0 then
        return {dry_run=true,stops=0,nothing='no turret there under '..tostring(plan.below)..' rounds that a rearm would walk to with what you carry',turrets=plan.turrets,left_out=plan.left_out,other_ammo=plan.other_ammo}
      end
    elseif a.radius~=nil or a.area~=nil or type(list)~='table' or #list==0 then
      error(name..' dry_run reads the route through positions (1..128 places); a radius or area tour chooses its stops when it runs',0)
    end
    assert(#list<=128,name..' dry_run: at most 128 positions')
    local left={}
    for i,q in ipairs(list) do left[i]=position(type(q)=='table' and q.position or q) end
    local points,from={{x=p.position.x,y=p.position.y}},p.position
    while #left>0 do
      local bi,bd
      for i,q in ipairs(left) do local d=distance(from,q); if not bd or d<bd then bi,bd=i,d end end
      from=table.remove(left,bi); points[#points+1]=from
    end
    -- with to (a courier: take at the place, give at to; A3, Luna 21:20: the dry run named the source as the chest
    -- accepting the item): the destination is the last stop, and courier says what would move.
    local courier
    if name=='transfer' and a.to~=nil then
      local to=a.to
      if type(to)=='table' and to.x==nil and to[1]==nil then local _,v=next(to); if type(v)=='table' then to=v end end
      local dest=position(to)
      points[#points+1]=dest
      courier=M.courier_dry(p,a,list,dest)
    end
    local mode=M.walk_mode(a)
    local out=M.routecheck.check(p,points,mode)
    out.stops=#points-1
    if plan then
      out.turrets=plan.turrets; out.turrets_more=plan.turrets_more; out.below=plan.below; out.count=plan.count
      out.left_out=plan.left_out; out.none_held=plan.none_held; out.other_ammo=plan.other_ammo
      out.magazines=plan.magazines; out.completes=plan.completes
    end
    -- collect: the inserters that take a machine's output there, and where they put it (Sol, shift18).
    if name=='collect' then
      local lines={}
      for _,q in ipairs(list) do
        local ok,e=pcall(entity,p,{position=type(q)=='table' and (q.position or q) or q,name=a.name},'walk')
        local tk=ok and e and (e.type=='assembling-machine' or e.type=='furnace') and stock.output_takers(e,a.item)
        if tk then lines[#lines+1]=string.format('%s (%g,%g): %s',e.name,e.position.x,e.position.y,tk.line) end
      end
      out.outputs_taken=#lines>0 and lines or nil
      if a.wait_ticks~=nil or a.keep_taking~=nil then out.note=out.note..'; a wait takes each product the tick it is in the output' end
    end
    -- feed, and transfer to an entity: whether each stop takes the item (M.accepts_text).
    if courier then out.courier=courier
    elseif (name=='feed' or (name=='transfer' and a.direction~='to_player')) and type(a.item)=='string' and prototypes.item[a.item] then
      local lines={}
      for i,q in ipairs(list) do
        if i>16 then lines[#lines+1]=string.format('+%d more stops not read',#list-16); break end
        local pos=position(type(q)=='table' and (q.position or q) or q)
        local ok,e=pcall(entity,p,{position=pos,name=a.name},'walk')
        if not ok then ok,e=pcall(remote_entity,p,{position=pos}) end
        lines[#lines+1]=ok and e and M.accepts_text(e,a) or string.format('unknown: no entity of ours in sight at (%g,%g)',pos.x,pos.y)
      end
      out.accepts=lines
    end
    out.order=#points<=17 and (function() local t={}; for i=2,#points do t[#t+1]=string.format('(%g,%g)',points[i].x,points[i].y) end; return table.concat(t,' ') end)() or nil
    out.avoid_enemies=mode and M.avoid.describe(mode) or 'false: no check'
    out.note='walked and moved nothing (stops nearest first from you, as a tour orders them); the running action and queue go on'
    return out
  end
end
