-- Another surface by remote view (inspect, circuit_set, wire surface=): one
-- of our platforms (by its name or its surface's), or a planet by name, where
-- the game's remote view shows visible chunks (radar coverage).
-- (A block: runtime.lua is near Lua's 200 top-level locals, tests/locals.lua.)
do
  local function on_surface(p,name)
    assert(type(name)=='string','surface is a planet, surface or platform name')
    for _,pl in pairs(p.force.platforms) do
      if pl.valid and (pl.name==name or (pl.surface and pl.surface.valid and pl.surface.name==name)) then return on_platform(p,pl.name) end
    end
    local s=game.get_surface(name)
    if not s then
      local known={}
      for _,each in pairs(game.surfaces) do if not each.platform then known[#known+1]=each.name end end
      table.sort(known)
      error('no surface named '..name..'; planets and surfaces: '..table.concat(known,', '),0)
    end
    if s==p.surface then return p end
    return setmetatable({__player=real(p),__remote=s.name},{
      __index=function(_,k) if k=='surface' then return s end return p[k] end,
      __newindex=function(_,k,v) p[k]=v end})
  end
  M.on_surface=on_surface
  -- A call's arguments without one of them (a read made again by remote view there).
  function M.without(a,drop) local out={} for k,v in pairs(a) do if k~=drop then out[k]=v end end return out end
  -- launch, configure and silo too (Astra 01:41: the silo on Vulcanus from Sunward above it); requests (Astra 02:20,
  -- board #377: a requester chest on Vulcanus feeding an assembler there); place_ghosts and scan (Astra 12:33: laying
  -- out a Vulcanus chain while Sonnet builds there by hand; in 2.0 a player places ghosts on another planet from the
  -- map, and that planet's robots build them).
  -- deconstruct and cancel_deconstruction too (Sol, 23:13: marks on a planet from a platform). The list is bots.lua's.
  for _,name in ipairs(M.bots.SURFACE_ACTIONS) do
    local handler=handlers[name]
    handlers[name]=function(p,a)
      if a.surface==nil then return handler(p,a) end
      -- (d18 batch36 D1, live 18:40) silo {surface: "all"}: every planet, silo.lua reads it, no one surface
      if name=='silo' and a.surface=='all' then return handler(p,a) end
      -- (d18 batch37 D1) observe's scopes read surface themselves (agriculture, stock, ...): passed as they are
      if name=='observe' and a.scope~=nil then return handler(p,a) end
      -- launch's and preflight's platform is where the rocket goes, not where the call acts (Astra, shift14 03:09 and
      -- 04:24: preflight {surface, position, platform} was refused, and she dropped the platform).
      assert(name=='launch' or name=='preflight' or a.platform==nil,'give platform or surface, not both')
      -- requests on another surface acts on an entity there (a chest, a landing pad), never on your character.
      assert(name~='requests' or a.position~=nil,'requests with surface needs position (a requester or buffer chest, landing pad there)')
      -- a scan there is centred on a place there: your character stands on another surface.
      assert(name~='scan' or a.position~=nil or a.area~=nil or a.positions~=nil,'scan with surface needs position, area or positions there')
      local q0=on_surface(p,a.surface)
      assert(name~='nearest' or q0==p or a.position~=nil or (type(q0)=='table' and rawget(q0,'__platform')~=nil),'nearest with surface needs position there (your character stands on another surface)')
      local args={}
      for k,v in pairs(a) do if k~='surface' then args[k]=v end end
      local q=on_surface(p,a.surface)
      -- (d18 batch37 D1, Sol on Aquilo; Astra: Nauvis lakes from Aquilo) map, grid and observe of another planet: centred
      -- on a place there (your character stands elsewhere), within what our force has charted there
      if q~=p and (name=='map' or name=='grid' or name=='observe') then
        assert(a.position~=nil or (name=='grid' and a.area~=nil),name..' with surface needs position'..(name=='grid' and ' or area' or '')..' there (your character stands on another surface)')
      end
      -- (d20 batch62 X2, Sol #1529: power {surface: fulgora, position} from Nauvis read Nauvis network 2) power there reads
      -- the networks round a place there; by_cause reads the whole surface
      -- (d20 batch62 X5) a paste there lands at a place there
      assert((name~='paste' and name~='blueprint_place') or a.position~=nil,name..' with surface needs position there (your character stands on another surface)')
      -- (d20 batch62 X4) cargo there reads a chest, silo, pad or wagon there, or a silo's dependency for items
      assert(name~='cargo' or a.position~=nil or a.silo~=nil,'cargo with surface needs position (a chest, rocket silo, landing pad or wagon there) or items with silo there; incoming takes planet')
      if q~=p and name=='power' and not a.by_cause then
        assert(a.position~=nil or a.area~=nil,'power with surface needs position or area there (your character stands on another surface), or by_cause: true for the whole surface')
      end
      return handler(q,args)
    end
  end
end
-- area {left_top, right_bottom} on feed, collect and transfer (Muse: "I hand-feed the same 5 ADV + 2 cable machines
-- every few minutes all shift"): our entities whose centre is inside it, of the call's types (feed and collect: their
-- defaults as in reach; transfer: machines, chests, wagons and the like), become its positions, nearest first, each by
-- its unit_number; then the call runs as with positions (a target out of reach is a row with the reach line).
do
  local MAX_SIDE,MAX_TARGETS=128,64
  local TRANSFER_TYPES={'container','logistic-container','linked-container','assembling-machine','furnace','lab','rocket-silo',
    'boiler','burner-generator','reactor','mining-drill','ammo-turret','artillery-turret','cargo-wagon','car','spider-vehicle',
    'cargo-landing-pad','roboport','agricultural-tower'}
  local function types_for(action,a)
    if a.types~=nil then
      assert(type(a.types)=='table' and #a.types>=1 and #a.types<=16,'types requires 1..16 entity types')
      return a.types
    end
    if action=='feed' then return a.recipe and {'assembling-machine','furnace'} or feeding.TYPES end
    if action=='collect' then return a.chests and collect_types.chests or collect_types.plain end
    return TRANSFER_TYPES
  end
  for _,action in ipairs({'feed','collect','transfer'}) do
    local handler=handlers[action]
    handlers[action]=function(p,a)
      if a.area==nil then return handler(p,a) end
      assert(a.positions==nil and a.position==nil and a.radius==nil,'give area, positions, position or radius: one of them')
      assert(type(a.area)=='table' and a.area.left_top and a.area.right_bottom,'area requires left_top and right_bottom')
      local lt,rb=position(a.area.left_top),position(a.area.right_bottom)
      assert(lt.x<rb.x and lt.y<rb.y and rb.x-lt.x<=MAX_SIDE and rb.y-lt.y<=MAX_SIDE,'area must be nonempty and at most '..MAX_SIDE..'x'..MAX_SIDE)
      local types=types_for(action,a)
      local found={}
      for _,e in pairs(p.surface.find_entities_filtered{area={left_top=lt,right_bottom=rb},force=p.force,type=types}) do
        local at=e.valid and e.position
        if at and at.x>=lt.x and at.x<=rb.x and at.y>=lt.y and at.y<=rb.y then found[#found+1]=e end
      end
      assert(#found>0,string.format('no %s of ours with its centre in (%g,%g)-(%g,%g)',table.concat(types,', ',1,math.min(#types,6))..(#types>6 and ', ...' or ''),lt.x,lt.y,rb.x,rb.y))
      -- feed over more than 64 (Opus, d15 06:20: refused 3 times that day): one walking tour through those that want
      -- something you hold, as feed radius walks.
      if action=='feed' and #found>MAX_TARGETS then
        local args={}
        for k,v in pairs(a) do if k~='area' then args[k]=v end end
        args.area_entities=found
        local out=handler(p,args)
        if type(out)=='table' then out.area_targets=#found; out.area_tour=string.format('%d machines in the area (over %d): fed as one walking tour, as radius does',#found,MAX_TARGETS) end
        return out
      end
      assert(#found<=MAX_TARGETS,string.format('%d entities in the area; at most %d (a smaller area, or types)',#found,MAX_TARGETS))
      table.sort(found,function(x,y) return distance(p.position,x.position)<distance(p.position,y.position) end)
      local args={}
      for k,v in pairs(a) do if k~='area' then args[k]=v end end
      args.positions={}
      for i,e in ipairs(found) do args.positions[i]={x=e.position.x,y=e.position.y,unit_number=e.unit_number} end
      args.from_area=true
      local out=handler(p,args)
      if type(out)=='table' then out.area_targets=#found end
      return out
    end
  end
end
local permissions={recover='inventory_transfer',walk='start_walking',move_to='start_walking',mine='begin_mining',pickup='change_picking_state',repair='start_repair',craft='craft',cancel_craft='cancel_craft',build='build',build_path='build',construct='build',place_ghosts='build',belt_route='build',pipe_route='build',pole_route='build',rail_route='build',train_stop='build',wire='wire_dragging',kite='change_shooting_state',revive_ghost='build',rotate='rotate_entity',configure='setup_assembling_machine',flush='flush_opened_entity_fluid',transfer='inventory_transfer',refuel='inventory_transfer',rearm='inventory_transfer',collect='inventory_transfer',feed='inventory_transfer',research='start_research',research_next='start_research',shoot='change_shooting_state',equip='inventory_transfer'}
for name,input in pairs(permissions) do
  local handler=handlers[name]
  handlers[name]=function(p,a)
    assert(not p.permission_group or p.permission_group.allows_action(defines.input_action[input]),'permission denied: '..input)
    return handler(p,a)
  end
end
-- A dry run (dryrun.lua): dry_run=true on place_ghosts, paste,
-- blueprint_place or build checks the plan the call would place and places
-- nothing. Dispatch turns such a request into this read, so the running
-- action and queue go on; a queue step with dry_run=true gets the same check.
function handlers.dry_run(p,a)
  local action,args=a.action,a.args
  assert(M.dryrun.ACTIONS[action],'dry_run takes action (place_ghosts, paste, blueprint_place, build, rail_route or belt_route) and args (that call\'s arguments)')
  assert(type(args)=='table','args must be the call\'s arguments')
  -- (d20 batch122, Astra #2066) a call's own dry_run in its args: true, false or left out alike here (this is the dry run)
  assert(args.dry_run==nil or type(args.dry_run)=='boolean','dry_run must be true or false')
  local inner={}
  for k,v in pairs(args) do if k~='dry_run' then inner[k]=v end end
  -- details (every entry with its footprint) is the paste's own argument; the others take it here.
  local details=inner.details==true
  if action~='paste' and action~='blueprint_place' then inner.details=nil end
  check_args(action,inner)
  M.turretammo.check(inner.ammo)
  local q=p
  if inner.platform~=nil and action~='build' then q=on_platform(p,inner.platform) end
  -- place_ghosts on another planet by remote view (Astra 12:33): the plan is checked there; belt_route too (d17
  -- batch18 C1, Astra #862).
  if inner.surface~=nil then
    -- (d20 batch62 X5, Astra #1557) paste and blueprint_place there too
    assert(action=='place_ghosts' or action=='belt_route' or action=='paste' or action=='blueprint_place','dry_run with surface checks place_ghosts, belt_route, paste or blueprint_place (another planet by remote view)')
    assert(inner.platform==nil,'give platform or surface, not both')
    assert((action~='paste' and action~='blueprint_place') or inner.position~=nil,action..' with surface needs position there (your character stands on another surface)')
    q=M.on_surface(p,inner.surface)
  end
  local kind=action=='build' and 'build' or (action=='place_ghosts' or action=='rail_route' or action=='belt_route') and 'ghosts' or 'paste'
  local plan={kind=kind,mode=inner.mode,details=details,entities={},tiles={},standing=kind~='build',
    flipped=kind=='paste' and (inner.flip_horizontal==true or inner.flip_vertical==true) or nil}
  local rail_plan,belt_plan
  -- Bounded work: a plan past these is refused before anything is checked.
  -- (belt_route: a line and its return line, up to 2048 belts the route has checked tile by tile already)
  local max_entities=action=='belt_route' and 2*M.dryrun.MAX_ENTITIES or M.dryrun.MAX_ENTITIES
  local function bounded()
    assert(#plan.entities<=max_entities and #plan.tiles<=M.dryrun.MAX_TILES,string.format(
      'a dry run checks at most %d entities and %d tiles; this plan has %d entities and %d tiles so far (fewer repeat copies, or part of the layout)',
      max_entities,M.dryrun.MAX_TILES,#plan.entities,#plan.tiles))
  end
  local copies,dx,dy=1,0,0
  local r=inner['repeat']
  if r~=nil then
    assert(kind~='build','repeat is for place_ghosts and paste')
    assert(type(r)=='table','repeat is {count,dx,dy}')
    copies=integer(r.count,1,1,64,'repeat count'); dx,dy=r.dx or 0,r.dy or 0
    assert(type(dx)=='number' and type(dy)=='number' and (dx~=0 or dy~=0),'repeat needs a nonzero dx or dy')
  end
  local paste
  for k=0,copies-1 do
    local copy=copies>1 and k+1 or nil
    if action=='rail_route' then
      -- The route as rail_route plans it (rails.lua), each piece checked;
      -- its signals go with the plan's rails (after_rails).
      rail_plan=M.rails.plan(q,inner)
      for i,e in ipairs(rail_plan.entities) do plan.entities[i]={index=i,name=e.name,position=e.position,direction=directions[e.direction]} end
    elseif action=='belt_route' then
      -- The line (and its return line) as belt_route plans it (route.lua), each belt checked.
      inner=M.belt_args(inner)
      -- A re-run of a line laid before: only its missing tiles (route_repair).
      belt_plan=not inner.replan and M.route_repair(q,{dry_run=true},M.route_key(q,inner)) or route.plan(q,inner)
      belt_plan.nests_on_route=M.belt_nests(q,inner,belt_plan)
      local dry={}; for k,v in pairs(inner) do dry[k]=v end; dry.dry_run=true
      belt_plan.feeders=M.route_feeders(q,dry,belt_plan)
      for i,e in ipairs(belt_plan.entities) do plan.entities[i]={index=i,name=e.name,position=e.position,direction=directions[e.direction],type=e.type} end
    elseif kind=='ghosts' then
      assert(inner.entities~=nil or inner.tiles~=nil,'place_ghosts requires entities and/or tiles')
      if inner.entities~=nil then
        assert(type(inner.entities)=='table' and #inner.entities>=1 and #inner.entities<=256,'entities requires 1..256 {name,position,direction?}')
        for i,spec in ipairs(inner.entities) do
          assert(type(spec)=='table','entry must be {name,position,direction?,type?}')
          local pos=position(spec.position)
          pos={x=pos.x+k*dx,y=pos.y+k*dy}
          local tile=not prototypes.entity[spec.name or ''] and tile_named(spec.name)
          if tile then plan.tiles[#plan.tiles+1]={index=i,copy=copy,name=tile,position=pos}
          else
            local dir=spec.direction and M.direction_of(spec.direction)
            assert(spec.direction==nil or dir,'direction must be a compass name (north, east, south, west) or 0..15')
            M.check_direction(prototypes.entity[spec.name or ''],dir)
            if k==0 then M.ghost_quality(q,spec.quality) end
            plan.entities[#plan.entities+1]={index=i,copy=copy,name=spec.name,position=pos,direction=dir or 0,ug_type=spec.type,recipe=spec.recipe,circuit=spec.circuit,wires=spec.wires,quality=spec.quality,
              rail_layer=spec.rail_layer,dir_given=spec.direction~=nil}
          end
        end
      end
      if inner.tiles~=nil then
        local t=inner.tiles
        assert(type(t)=='table' and type(t.area)=='table','tiles requires {name, area={left_top,right_bottom}}')
        local tile=tile_named(t.name); assert(tile,'tiles name must be a tile or an item that places one')
        local lt,rb=position(t.area.left_top),position(t.area.right_bottom)
        local x0,y0,x1,y1=math.floor(lt.x),math.floor(lt.y),math.ceil(rb.x)-1,math.ceil(rb.y)-1
        assert(x1>=x0 and y1>=y0 and (x1-x0+1)*(y1-y0+1)<=4096,'tiles area must be 1..4096 tiles')
        for x=x0,x1 do for y=y0,y1 do plan.tiles[#plan.tiles+1]={copy=copy,name=tile,position={x=x+0.5+k*dx,y=y+0.5+k*dy}} end end
      end
    elseif kind=='build' then
      if inner.builds~=nil then assert(type(inner.builds)=='table' and #inner.builds>=1 and #inner.builds<=256,'builds requires 1..256 {item,position,direction} entries') end
      for i,b in ipairs(inner.builds or {inner}) do
        assert(type(b)=='table','each build must be an object')
        local item=b.item or inner.item
        assert(type(item)=='string','item is required')
        local ip=prototypes.item[item]; assert(ip,'unknown item '..item)
        local pos=position(b.position)
        if ip.place_as_tile_result then
          for _,t in ipairs(M.dryrun.brush(pos,integer(b.size or inner.size,1,1,4,'size'))) do
            plan.tiles[#plan.tiles+1]={index=i,name=ip.place_as_tile_result.result.name,item=item,position=t}
          end
        else
          local place=ip.place_result
          local okr,rails=pcall(function() return ip.rails end)
          if okr and type(rails)=='table' and #rails>0 then
            local want=b.entity or inner.entity
            place=nil
            for _,rl in ipairs(rails) do
              local n=type(rl)=='string' and rl or rl.name
              if not want or n==want then place=prototypes.entity[n]; break end
            end
          end
          assert(place,item..' places no entity here')
          local dir=M.direction_of(b.direction or inner.direction or 'north'); assert(dir,'invalid direction: a compass name (north, east, south, west) or 0..15')
          if (b.direction or inner.direction)~=nil then M.check_direction(place,dir) end
          local orient=b.orientation or inner.orientation
          if orient~=nil then
            assert(M.rollingstock.TYPES[place.type],'orientation goes with rolling stock (locomotives and wagons); others take direction')
            dir=M.rollingstock.direction_of_orientation(orient)
          end
          -- An entry's recipe, else the call's for an entry that places an assembling machine (as the real call).
          local recipe=b.recipe
          if recipe==nil and inner.recipe~=nil and (place.type=='assembling-machine' or not inner.builds) then recipe=inner.recipe end
          plan.entities[#plan.entities+1]={index=i,name=place.name,position=pos,direction=dir,quality=b.quality or inner.quality,item=item,ug_type=b.type or inner.type,
            recipe=recipe,circuit=b.circuit,wires=b.wires,rail_layer=b.rail_layer or inner.rail_layer,dir_given=(b.direction or inner.direction)~=nil}
        end
      end
    else
      local pa={}
      for kk,v in pairs(inner) do if kk~='repeat' then pa[kk]=v end end
      assert(copies==1 or inner.position~=nil,'repeat needs position')
      if inner.position~=nil then local p0=position(inner.position); pa.position={x=p0.x+k*dx,y=p0.y+k*dy} end
      local pl=M.paste_plan(q,pa)
      for _,e in ipairs(pl.entities) do e.copy=copy; plan.entities[#plan.entities+1]=e end
      for _,t in ipairs(pl.tiles) do t.copy=copy; plan.tiles[#plan.tiles+1]=t end
      paste=paste or {slot=pl.slot,label=pl.label,origin_at=pl.origin_at,center_at=pl.center_at,anchor=pl.anchor,retired=pl.retired}
    end
    bounded()
  end
  local out,recs,counts=M.dryrun.check(q,plan)
  out.action=action
  -- (d17 batch34 B1) the fluid segments the plan joins or cuts, and a join of two fluids
  if action=='place_ghosts' or action=='build' or action=='paste' or action=='blueprint_place' then
    local okf,fl,mix,cut=pcall(M.fluidjoin.plan,q.surface,q.force,recs or {})
    if okf then
      out.fluid_segments,out.fluid_mix,out.fluid_cuts=fl,mix,cut
      if mix then out.fluid_mix_note=M.fluidjoin.NOTE..((action=='place_ghosts' or action=='build') and '; the call itself is refused without mix_fluids: true' or '') end
    end
  end
  -- (d17 batch34 B3, Opus) the ghosts' robot trips: from which roboports, how far, past which enemies
  if action=='place_ghosts' or action=='paste' or action=='blueprint_place' then
    local jobs={}
    for _,r in ipairs(recs or {}) do
      if r.proto and r.pos and (r.status=='ok' or r.status=='after_tiles') and #jobs<4096 then
        local it=r.item or (function() local l=r.proto.items_to_place_this; local f=l and l[1]; return f and (type(f.name)=='string' and f.name or f.name.name) end)()
        if it then jobs[#jobs+1]={kind='construct',pos=r.pos,item=it,count=1} end
      end
    end
    local okd,lines=pcall(M.robottrips.preview,q.surface,q.force,jobs)
    if okd and lines then out.robot_dispatch=lines end
  end
  if own_platform(q) then out.pump_circuits=M.pumpcheck.plan(q,plan.entities) end
  -- A recipe given with an entry: the check the real call makes before it places anything (M.recipe_for).
  do
    local recipes,refused={},{}
    for _,e in ipairs(plan.entities) do
      if e.recipe~=nil then
        local proto=prototypes.entity[e.name]
        local ok,err=pcall(M.recipe_for,q,proto,e.recipe)
        if ok then recipes[e.recipe]=(recipes[e.recipe] or 0)+1
        else refused[#refused+1]=string.format('entry %d %s: %s',e.index or 0,e.name,reason(err)) end
      end
    end
    out.recipes=next(recipes) and recipes or nil
    out.recipes_refused=#refused>0 and refused or nil
    -- Placeable or not, the real call refuses those entries for their recipe.
    if #refused>0 and type(out.summary)=='string' then out.summary=string.format('%s; %d refused for the recipe',out.summary,#refused) end
  end
  -- The ammo the turret ghosts would request (turretammo.lua; a blueprint's own requests are not counted here).
  if kind~='build' then
    local rows={}
    for _,e in ipairs(plan.entities) do
      local t=M.turretammo.takes(prototypes.entity[e.name])
      if t then
        local spec=kind=='ghosts' and type(inner.entities)=='table' and inner.entities[e.index] or nil
        local what=spec and spec.ammo
        if what==nil then what=inner.ammo end
        local c=M.turretammo.choose(t,q.surface,q.force,e.position,what)
        if c then M.turretammo.add(rows,c) end
      end
    end
    out.ammo_requests=#rows>0 and rows or nil
  end
  if kind=='build' then out.materials=M.materials.build(p,inner) end
  -- (d20 batch65 AA8, Astra 19:02) entries setting what acts on a signal (an enable condition, set filters, ...) with no
  -- red or green wire in the call (or a blueprint's) and none on what stands there
  if kind~='ghosts' or action=='place_ghosts' then
    local oku,u=pcall(M.circuits.unwired_plan,plan.entities,M.unwired_check(q.surface,q.force),kind~='build')
    if oku then out.unwired=u end
  end
  out.paste=paste
  out.retired=paste and paste.retired or nil
  out.rail_route=rail_plan and rail_plan.out or nil
  if belt_plan then
    local b={}
    for k,v in pairs(belt_plan) do if k~='entities' and k~='own_entities' then b[k]=v end end
    out.belt_route=b
  end
  if kind=='paste' and (inner.mode or 'normal')=='normal' and (counts.refused_now or 0)>0 then
    out.paste_note=string.format('a normal paste is all or nothing: with %d entr%s the game refuses there now, it places no ghost at all; mode forced places the rest and marks trees and rocks in the way',
      counts.refused_now,counts.refused_now==1 and 'y' or 'ies')
  elseif kind=='build' and counts.fail_first then
    out.build_note=inner.skip_failed and string.format('skip_failed: entries that fail are skipped, the first #%d (%s)',counts.fail_first,counts.fail_why)
      or string.format('a build batch stops at the first entry that fails (the ones before it stay built): entry #%d (%s); with all: true the others build',
        counts.fail_first,counts.fail_why)
  end
  return out
end
end for name in pairs(M.dryrun.ACTIONS) do
  local handler=handlers[name]
  handlers[name]=function(p,a)
    if type(a)=='table' and a.dry_run==true then return handlers.dry_run(p,{action=name,args=a}) end
    -- "dry_run":"true" must not build for real.
    assert(type(a)~='table' or a.dry_run==nil or a.dry_run==false,'dry_run must be true or false')
    return handler(p,a)
  end
end
-- Settings on the entries of place_ghosts and build (entryset.lua; Sol, shift13 19:50: a bio cell took about 10
-- configure and wire round trips): hand builds set each placement immediately; wires follow the batch.
M.pumpcheck=require('pumpcheck'){read=function(e) return M.circuits.read(e) end}
M.entryset=require('entryset'){check=function(action,args) return check_args(action,args) end,
  call=function(action,p,args) return handlers[action](p,args) end,position=position,reason=reason,
  dry=function(p,entry,kind,args) return M.settings_dry(p,entry,kind,args) end,
  fix=function(action,args) return M.aliases.fix(action,args,M.takes) end,seen=function(p,ctx,pos) return M.settings_seen(p,ctx,pos) end}
-- (d24 batch142 PN2, Astra #2134) whether the live call can set an entry's settings at pos: they go by remote view
-- (configure_target, circuits' target, requests and wire), which needs our own platform or a chunk our force sees now
-- on the call's surface (ctx: platform, surface). true, or the refusal.
function M.settings_seen(p,ctx,pos)
  if ctx.platform~=nil then return true end
  local q=ctx.surface~=nil and M.on_surface(p,ctx.surface) or p
  if own_platform(q) or p.force.is_chunk_visible(q.surface,chunk_of(pos)) then return true end
  local c=chunk_of(pos)
  return string.format('(%g,%g) on %s is in chunk (%d,%d), which our force does not see now (no radar coverage or character there): the live call refuses settings there',
    pos.x,pos.y,q.surface.name,c.x,c.y)
end
-- A place_ghosts dry run's settings (d17 batch18 A3, Sol: requests written with name instead of item passed the dry run
-- and were refused live), checked by the code the real call runs on the ghost it places, given a stand-in of that ghost:
-- requests (space.lua check_requests, on a chest that takes requests), configure's recipe (configure_check), modules
-- (modules.lua check: slots, categories, effects under the recipe), filters (configure_filters' checks), spoil
-- priority, and circuit_set's arguments (circuits.lua dry_set). Errors with the real call's refusal.
function M.settings_dry(p,entry,kind,args)
  local name=entry.name or entry.item
  local proto=type(name)=='string' and prototypes.entity[name]
  if not proto then return end
  local ghost={valid=true,type='entity-ghost',name='entity-ghost',ghost_name=name,ghost_type=proto.type,ghost_prototype=proto,
    position=position(entry.position),filter_slot_count=proto.filter_count or 0,get_recipe=function() return nil end}
  if kind=='requests' then
    local t,mode=proto.type,proto.logistic_mode
    if not ((t=='logistic-container' and (mode=='requester' or mode=='buffer')) or t=='cargo-landing-pad' or t=='space-platform-hub') then
      error(name..' has no logistic requests',0)
    end
    local secs={sections_count=1,get_section=function(i) return i==1 and {index=1,is_manual=true} or nil end}
    space.check_requests(p,args,'chest',{valid=true,name=name,type=t},secs)
  elseif kind=='circuit' then
    M.circuits.dry_set(name,args,p.force)
  elseif kind=='wire' then
    -- (d20 batch122, Astra #2087) both ends by the live wire's rules: the entry, and at to an entry of this call or
    -- what stands there
    M.circuits.wire_end_id('from',name,proto.type,proto,entry.quality,args.color,args.from_side,'output')
    local to=args.to
    local function covers(o,op)
      local w,h=op.tile_width or 1,op.tile_height or 1
      local d=o.direction~=nil and M.direction_of(o.direction) or 0
      if d%8==4 then w,h=h,w end
      local okp,q=pcall(position,o.position)
      return okp and math.abs(to.x-q.x)<w/2 and math.abs(to.y-q.y)<h/2
    end
    for _,o in ipairs(args.entries or {}) do
      local on=type(o)=='table' and (o.name or o.item)
      local op=type(on)=='string' and prototypes.entity[on]
      if op and covers(o,op) then
        return M.circuits.wire_end_id('to',on,op.type,op,o.quality,args.color,args.to_side,'input')
      end
    end
    local ctx=args.ctx or {}
    local s=p.surface
    if ctx.platform~=nil then s=space.platform(p,ctx.platform).surface
    elseif ctx.surface~=nil then s=game.surfaces[ctx.surface] end
    for _,e in ipairs(s and s.find_entities_filtered{position=to,force=p.force,limit=8} or {}) do
      local g=e.type=='entity-ghost'
      if e.type~='character' and e.type~='tile-ghost' then
        return M.circuits.wire_end_id('to',g and e.ghost_name or e.name,g and e.ghost_type or e.type,g and e.ghost_prototype or e.prototype,
          e.quality,args.color,args.to_side,'input')
      end
    end
  elseif kind=='configure' then
    local rname=args.recipe or entry.recipe
    if args.recipe~=nil then M.configure_check(p,args,ghost,false) end
    if args.modules~=nil and args.modules~=false then
      local recipe=type(rname)=='string' and prototypes.recipe[rname] or nil
      M.modules.check(proto,recipe,proto.module_inventory_size or 0,M.modules.parse(args.modules),
        string.format('the ghost of %s (%g,%g)%s',name,ghost.position.x,ghost.position.y,recipe and ' making '..recipe.name or ''))
    end
    local f=args.filters
    if f==nil and args.filter~=nil and proto.type~='splitter' then f=args.filter end
    if f~=nil and proto.type~='asteroid-collector' then
      local slots=ghost.filter_slot_count
      assert(slots>0,name..' has no filter slots')
      local list=type(f)=='string' and {f} or f
      assert(type(list)=='table' and #list<=slots,'filters requires 0..'..slots..' item names')
      for _,n in ipairs(list) do assert(prototypes.item[n],'unknown item '..tostring(n)) end
    end
    if args.use_filters~=nil then assert(proto.type=='inserter' and type(args.use_filters)=='boolean','use_filters is true or false, on an inserter') end
    if args.filter_mode~=nil then
      assert(args.filter_mode=='whitelist' or args.filter_mode=='blacklist','filter_mode is whitelist or blacklist')
      assert(proto.type=='inserter','filter_mode applies to inserters')
    end
    if args.spoil_priority~=nil then
      assert(proto.type=='inserter','spoil_priority is an inserter setting (the inserter GUI\'s Spoil priority)')
      assert(type(args.spoil_priority)=='string' and M.SPOIL_PRIORITY[args.spoil_priority],'spoil_priority is none, fresh_first or spoiled_first (the inserter GUI\'s Spoil priority)')
    end
  end
end
-- A dry run's verdict (A3): fails when an entry is blocked or a setting refused, as the real call would leave them;
-- the CLI exits 1 on it.
function M.dry_verdict(out,a)
  if type(out)~='table' or type(a)~='table' or a.dry_run~=true or out.dry_run~=true then return out end
  local blocked=#(out.blocked or {})+(out.blocked_more or 0)
  local refused=out.settings_refused or 0
  local parts={}
  if blocked>0 then parts[#parts+1]=blocked..' entr'..(blocked==1 and 'y' or 'ies')..' blocked' end
  if refused>0 then parts[#parts+1]=refused..' setting'..(refused==1 and '' or 's')..' refused'..((out.settings_unseen or 0)>0 and string.format(' (%d in chunks our force does not see now)',out.settings_unseen) or '') end
  -- (batch28 A1, Astra ~4 times: ok while an unavailable recipe, floor the hub never builds or inserters with no
  -- target were listed) what the real call refuses or leaves undone fails the verdict too, each named
  -- (batch29 A2, Opus: a drill spot held one of our drills) an entry where the same entity of ours stands already
  local exists,first_exists=0,nil
  for _,e in ipairs(type(out.entities)=='table' and out.entities or {}) do
    if e.status=='exists' then exists=exists+1; first_exists=first_exists or string.format('#%s %s (%g,%g)',tostring(e.index),tostring(e.name),e.position and e.position.x or 0,e.position and e.position.y or 0) end
  end
  if exists>0 then parts[#parts+1]=string.format('%d entr%s where ours stands already (%s)',exists,exists==1 and 'y' or 'ies',first_exists) end
  -- (d22 batch95 BE1, Astra #1892) entries on tiles the game refuses them on, whose tiles place_ghosts does not lay
  local untiled=out.refused_until_tiles or 0
  if untiled>0 then parts[#parts+1]=string.format('%d entr%s the game refuses on the tiles there now, with no tile entry before %s (%s)',untiled,untiled==1 and 'y' or 'ies',untiled==1 and 'it' or 'them',tostring(out.refused_until_tiles_first)) end
  local recipes=#(out.recipes_refused or {})
  if recipes>0 then parts[#parts+1]=string.format('%d refused for the recipe (%s)',recipes,out.recipes_refused[1]) end
  -- (d20 batch76 AL2, Sol #1752) foundation tiles the real call refuses in front of asteroid collectors
  local ahead=type(out.tiles)=='table' and out.tiles.collector_refused or 0
  if ahead>0 then parts[#parts+1]=string.format('%d foundation tile%s refused in front of asteroid collectors (tiles.collector_clearance)',ahead,ahead==1 and '' or 's') end
  local tiles=type(out.tiles)=='table' and out.tiles.unbuilt_count or 0
  if tiles>0 then parts[#parts+1]=string.format('%d foundation tile%s the hub never builds (%s)',tiles,tiles==1 and '' or 's',out.tiles.unbuilt and out.tiles.unbuilt[1] or '') end
  -- (d20 batch122, Astra #2089) new foundation joined to the floor by no side or corner: never built, whether or not the
  -- hub's rules were played over it (a floor too large for one tick is played across ticks)
  local apart=type(out.tiles)=='table' and out.tiles.not_connected_count or 0
  if apart>0 and tiles==0 then parts[#parts+1]=string.format('%d foundation tile%s the hub never builds: no foundation by a side or a corner, even through the other new tiles (tiles.not_connected)',apart,apart==1 and '' or 's') end
  local loose=type(out.inserters_without_target)=='number' and out.inserters_without_target or #(type(out.inserters_without_target)=='table' and out.inserters_without_target or {})
  if loose>0 then
    local first
    for _,i in ipairs(type(out.inserters)=='table' and out.inserters or {}) do
      if i.missing then first=string.format('#%s %s (%g,%g): %s',tostring(i.index),tostring(i.name),i.position and i.position.x or 0,i.position and i.position.y or 0,tostring(i.missing)); break end
    end
    parts[#parts+1]=string.format('%d inserter%s with no target%s',loose,loose==1 and '' or 's',first and ' ('..first..')' or '')
  end
  out.dry_run_ok=#parts==0
  out.verdict=#parts==0 and 'ok: every entry places and every setting is taken' or 'fails: '..table.concat(parts,', ')..(out.settings_line and '; '..out.settings_line or '')
  -- a floor the hub's rules have not decided yet: ok says so
  if #parts==0 and type(out.tiles)=='table' and out.tiles.unchecked_count then
    out.verdict=out.verdict..string.format('; the floor (%d tiles) is not checked yet: %s',out.tiles.unchecked_count,out.tiles.check_id and 'floor check #'..out.tiles.check_id..' decides it (tiles.check)' or 'tiles.check')
  end
  return out
end
-- (d20 batch65 AA8) what stands at a spot (built or a ghost of that name, ours) with a red or green wire on it
function M.unwired_check(surface,force)
  return function(name,pos)
    for _,o in ipairs(surface.find_entities_filtered{position=pos,radius=0.5,force=force}) do
      local n=o.type=='entity-ghost' and o.ghost_name or o.name
      if n==name and M.circuits.has_circuit_wire(o) then return true end
    end
    return false
  end
end
-- The surface a place_ghosts call places on (its platform or surface, else the character's), or nil.
function M.call_surface(p,a)
  local ok,q=pcall(function()
    if a.platform~=nil then return space.platform(p,a.platform).surface end
    if a.surface~=nil then return M.on_surface(p,a.surface).surface end
    return p.surface
  end)
  return ok and q or nil
end
do
  local place=handlers.place_ghosts
  handlers.place_ghosts=function(p,a)
    local aliased=type(a)=='table' and M.entryset.normalize(a.entities) or 0
    if type(a)~='table' or not M.entryset.any(a.entities) then return M.dry_verdict(place(p,a),a) end
    local ctx={platform=a.platform,surface=a.surface}
    local fixed=M.entryset.check(a.entities,ctx)
    local out=place(p,a)
    if type(out)=='table' and #fixed>0 then out.settings_corrected=fixed end
    if a.dry_run==true then
      if type(out)=='table' then
        local rows,line,n,unseen=M.entryset.dry(p,a.entities,ctx)
        out.settings,out.settings_line,out.settings_refused,out.settings_unseen=rows,line,n>0 and n or nil,unseen and unseen>0 and unseen or nil
      end
      return M.dry_verdict(out,a)
    end
    local skip={}
    for _,f in ipairs(out.failed or {}) do if f.index then skip[f.index]=true end end
    local stats
    out.settings,out.settings_line,stats=M.entryset.apply(p,a.entities,ctx,skip)
    -- (d24 batch142 PN2, Astra #2134: 31 ghosts placed, all 17 settings refused, and the reply read as a success) the
    -- verdict and summary say how many settings were refused
    local nref=stats and #stats.failed or 0
    if nref>0 then
      out.settings_refused=nref
      out.summary=string.format('%s ghost%s placed; %d of %d settings refused',tostring(out.placed or 0),out.placed==1 and '' or 's',nref,nref+stats.set)
      out.verdict='partial: '..out.summary..': '..stats.failed[1]..(nref>1 and string.format(' (and %d more: settings_line, settings)',nref-1) or '')
    end
    if aliased>0 then out.settings_alias=aliased..' entries\' settings read as configure/requests/circuit/wires' end
    -- (AA8) an entry setting what acts on a signal with no red or green wire planned or standing
    local placed={}
    for i,e in ipairs(a.entities) do if not skip[i] then placed[#placed+1]=e end end
    local surface=M.call_surface(p,a)
    local oku,u=pcall(M.circuits.unwired_plan,placed,surface and M.unwired_check(surface,p.force),true)
    if oku then out.unwired=u end
    return out
  end
  local build=handlers.build
  handlers.build=function(p,a)
    local aliased=type(a)=='table' and type(a.builds)=='table' and M.entryset.normalize(a.builds,'builds entry') or 0
    local entries=type(a)=='table' and (a.builds or {a}) or {}
    if M.entryset.any(entries) then M.entryset.check(entries,{}) end
    local out=build(p,a)
    if aliased>0 and type(out)=='table' then out.settings_alias=aliased..' entries\' settings read as configure/requests/circuit/wires' end
    -- (AA8) as place_ghosts: settings that act on a signal with no red or green wire planned or standing
    if type(out)=='table' and M.entryset.any(entries) then
      local oku,u=pcall(M.circuits.unwired_plan,entries,M.unwired_check(p.surface,p.force),false)
      if oku then out.unwired=u end
    end
    return out
  end
  -- check_inserters (Luna, d15 09:20 round: misaligned or blocked inserters on the Gleba seed feeders, many round trips):
  -- the call's own dry run first; each planned inserter's pickup and drop (what stands there: built, planned in this
  -- call, a ghost), its power (a pole's supply area, built or planned) and its filters (an inserter that takes none);
  -- any inserter with a problem refuses the whole call before anything is placed, with every inserter's row; all
  -- good, the call runs and the reply carries the rows (inserter_check).
  function M.inserter_check(p,action,a)
    -- (d20 batch122, Astra #2066: check_inserters with dry_run: false refused "dry_run must be true or false") the
    -- call's dry_run is not passed on: this is its dry run
    local args={}
    for k,v in pairs(a) do if k~='check_inserters' and k~='dry_run' then args[k]=v end end
    local dry_out=handlers.dry_run(p,{action=action,args=args})
    local entries=action=='build' and (a.builds or {a}) or a.entities or {}
    local unpowered={}
    for _,u in ipairs(type(dry_out.power)=='table' and dry_out.power.unpowered or {}) do unpowered[tostring(u.index)]=u.why end
    local rows,bad={},0
    for _,r in ipairs(dry_out.inserters or {}) do
      local e=entries[tonumber(r.index) or 0]
      local problems={}
      if r.missing then problems[#problems+1]=r.missing end
      if unpowered[tostring(r.index)] then problems[#problems+1]='no power: '..unpowered[tostring(r.index)] end
      local filters=type(e)=='table' and type(e.configure)=='table' and e.configure.filters
      if filters then
        local n=0
        pcall(function() n=prototypes.entity[r.name].filter_count or 0 end)
        if n==0 then problems[#problems+1]=r.name..' takes no filters' end
      end
      if #problems>0 then bad=bad+1 end
      rows[#rows+1]={index=r.index,name=r.name,position=r.position,direction=r.direction,pickup=r.pickup,drop=r.drop,
        filters=filters and table.concat(type(filters)=='table' and filters or {tostring(filters)},', ') or nil,
        power=unpowered[tostring(r.index)] and 'none' or 'covered',ok=#problems==0,problems=#problems>0 and table.concat(problems,'; ') or nil}
      -- both sides by name in one line (D2, Gemini 18:24)
      local row=rows[#rows]
      row.line=string.format('#%s %s (%g,%g)%s: picks from %s, drops into %s%s',tostring(r.index),r.name,r.position.x,r.position.y,
        r.direction and ' facing '..r.direction or '',(tostring(r.pickup):gsub('^none: ','nothing: ')),(tostring(r.drop):gsub('^none: ','nothing: ')),row.problems and ': '..row.problems or ': ok')
    end
    if bad>0 then
      local lines={}
      for _,r in ipairs(rows) do if not r.ok then lines[#lines+1]=r.line end end
      error(string.format('check_inserters: %d of %d inserters would not work; nothing placed: %s',bad,#rows,table.concat(lines,'; ')),0)
    end
    return rows
  end
  for _,action in ipairs({'build','place_ghosts'}) do
    local inner=handlers[action]
    handlers[action]=function(p,a)
      if type(a)~='table' or not a.check_inserters or a.dry_run then
        if type(a)=='table' and a.check_inserters~=nil and a.dry_run then
          local b={}; for k,v in pairs(a) do if k~='check_inserters' then b[k]=v end end; a=b
        end
        return inner(p,a)
      end
      assert(a.check_inserters==true,'check_inserters must be true')
      local rows=M.inserter_check(p,action,a)
      local b={}
      for k,v in pairs(a) do if k~='check_inserters' then b[k]=v end end
      local out=inner(p,b)
      if type(out)=='table' then out.inserter_check=rows end
      return out
    end
  end
  -- A dry run (the dispatcher's dry_run action, a queue step's): the same check, and what each entry would set.
  local dry=handlers.dry_run
  handlers.dry_run=function(p,a)
    local args=type(a)=='table' and type(a.args)=='table' and a.args or nil
    local entries=args and (a.action=='place_ghosts' and args.entities or a.action=='build' and (args.builds or {args})) or nil
    if entries and (a.action=='place_ghosts' or args.builds) then M.entryset.normalize(entries) end
    local judged=(a.action=='place_ghosts' or a.action=='build') and {dry_run=true} or nil
    if not entries or not M.entryset.any(entries) then return M.dry_verdict(dry(p,a),judged) end
    local fixed=M.entryset.check(entries,a.action=='place_ghosts' and {platform=args.platform,surface=args.surface} or {})
    local out=dry(p,a)
    if #fixed>0 then out.settings_corrected=fixed end
    out.settings_planned=M.entryset.plan(entries)
    -- each checked as the real call checks it (A3)
    local rows,line,n,unseen=M.entryset.dry(p,entries,a.action=='place_ghosts' and {platform=args.platform,surface=args.surface} or {})
    out.settings_check,out.settings_line,out.settings_refused,out.settings_unseen=rows,line,n>0 and n or nil,unseen and unseen>0 and unseen or nil
    return M.dry_verdict(out,judged)
  end
end
do local equipment_handler=handlers.equipment
handlers.equipment=function(p,a)
  local input=a.operation=='remove' and 'take_equipment' or 'place_equipment'
  assert(not p.permission_group or p.permission_group.allows_action(defines.input_action[input]),'permission denied: '..input)
  return equipment_handler(p,a)
end
end -- Actions whose handler can start a timed action: as a queue step they wait for its end (Sol 22:45: a clear_cliffs step
-- began and ended in the same tick, and the next step, a move_to, stopped its throw; vehicle drives the same).
-- tests/queuetimed.lua lists every timed action and checks each is here.
local timed={recover=true,walk=true,move_to=true,build_path=true,construct=true,kite=true,mine=true,pickup=true,repair=true,rearm=true,refuel=true,transfer=true,collect=true,feed=true,wait_until=true,wait_ticks=true,build=true,load_silo=true,
  clear_cliffs=true,use_item=true,vehicle=true,
  -- configure and rotate: a walk into reach that the call makes first (autowalk.lua)
  configure=true,rotate=true,
  -- launch {wait_ready}: a wait for the rocket, then the launch
  launch=true}
-- The active action kind a step's handler starts, where it differs from its name (use_item: cliff explosives only;
-- vehicle: a drive, or a drive's dry run).
do local timed_kind={rearm={feed=true,gather=true},refuel={feed=true,gather=true},transfer={feed=true,gather=true},build={feed=true},collect={gather=true},feed={gather=true},load_silo={feed=true,gather=true},
  recover={gather=true},use_item={clear_cliffs=true},vehicle={drive=true},launch={wait_until=true}}
-- Whether a queue step of `action` waits while an active action of `kind` runs (shoot and drop are read apart: the
-- combat channel and drop jobs).
function M.queue_waits(action,kind)
  return timed[action]==true and (timed_kind[action] and timed_kind[action][kind]==true or kind==action) or false
end
end local conditions=conditions_module{losses_since=function(f,s,since,names,max) return M.lostlog.since(f,s,since,names,max) end,platform_hits=function(pl) return M.platalerts.hit_ring(pl),M.platalerts.HIT_RING end,leg=function(pl) return M.freight.leg(pl) end,receipts=function(pl,since) return M.freight.receipts_since(pl,since) end,pods_landed=function(name,since,item,q) return M.podlog.landed_from(name,since,item,q) end,drop_record=function(id) return M.drops.find(id) end,last_drop=function(name) return M.drops.last_of(name) end,known=known,position=position,passing=function(e) return M.passing(e) end,
  -- platform_arrived reads where a platform is as the platforms row does (freight.lua)
  platform_where=function(pl) return M.freight and M.freight.where(pl) end,
  -- (d22 batch100 BJ1) a platform's departure logged since a tick (freight.lua), for platform_left's baseline
  left_since=function(name,force,location,since) return M.freight and M.freight.left_since(name,force,location,since) end,
  -- (d22 batch117 BZ1) platform_ammo_below's background reading (ammoreserve.lua)
  ammo_reserve=function(pl,force,c) return M.ammoreserve.check(pl,force,c) end}
M.waiteta=require('waiteta'){before_departure=function(pl,loc) return M.freight.before_departure(pl,loc) end,state=state,check=function(p,c,record) return conditions.check(p,c,true,record) end,
  research_rate=function(name) return M.research.rate(name) end,crafting_left=crafting_left,
  busy=function(s,index) return M.idle.busy(s,index) end,
  has_body=function(index) local p=M.lookup(index); return p and p.valid and p.character and p.character.valid end}
M.scheduler_api={collect_waiting=function(index) return M.waits.collect_waiting(index) end,
  -- (d22 batch112 BV1) a build's entries its running action had left (a walk for the rest, a step aside): {count, line}
  left_undone=function(index) return M.left_undone(index) end,
  guard_refusal=function(p,c) return conditions.guard_refusal(p,c) end,
  recheck_read=function(rc) return space.recheck_read(rc) end,
  state=state,player=player,handlers=handlers,timed=M.timed,
  check_action=function(index,action,args) return M.bots.check_action(index,action,args) end,
  step_read_check=function(p,action,args,prior) return M.step_read_check(p,action,args,prior) end,
  condition=function(p,c) return conditions.check(p,c) end,check_args=function(action,args) check_args(action,args); if M.step_checks[action] and type(args)=='table' then M.step_checks[action](args) end; if type(args)=='table' then M.step_range_check(action,args) end end,validate_condition=function(c) return conditions.validate(c) end,
  wait_check=function(p,c,record) return M.waiteta.check(p,c,record) end,
  extend_wait=function(step,c,started) return M.waiteta.extend(step,c,started) end,
  wait_info=function(out,record) return M.waiteta.info(out,record) end,
  fix_args=function(action,args) return M.aliases.fix(action,args,M.takes) end,
  takes=function(action,key) return M.takes(action,key) end,
  simulate=function(p,items) return M.rocketload.simulate(p,items) end,
  busy=function(p,action)
    if action=='shoot' then return state().combat and state().combat[p.index]~=nil end
    if action=='drop' then return state().drop_jobs and state().drop_jobs[p.index]~=nil or false end
    local now=timed[action] and state().active[p.index]
    -- (or a walk into reach that the call makes first: autowalk.lua)
    return now and (M.queue_waits(action,now.kind) or (now.then_call~=nil and now.then_call.action==action) or (action=='move_to' and now.then_move~=nil)) or false
  end,
  -- Halting controls must not pause the queue: guard reactions and goto
  -- continue right after it. Pausing is always explicit (scheduler.pause).
  stop=function(p) finish(p.index,'interrupted'); stop_combat(p.index,'interrupted') end,
  stop_index=function(index) finish(index,'interrupted'); stop_combat(index,'interrupted') end,
  -- Timed actions a plan step started are its own; any other is a direct call's.
  claim=function(p) local action=state().active[p.index]; if action then action.queued=true end end,
  direct_action=function(p) local action=state().active[p.index]; return action and not action.queued and action.kind or nil end,
  reason=reason,
  on_step=function(index,action) M.selfview.request(index,action,true) end,
  step_begin=function(index,step) M.ghost_via={action=step.action,step=step.id,label=step.label,order=step.order}; M.hauling.begin(index,step.order and 'order' or 'queue') end,
  step_moved=function(step,ok) return M.moved_by_note(step,ok) end,
  step_done=function(index) M.ghost_via=nil; M.hauling.done(index) end,
  on_fail=function(index,action,reason) M.selfview.failed(index,action,reason) end,
  -- (d24 batch178 QU1) the character's last completion counts for a step only when written since the step began: a
  -- step whose action left none (an instant finish, a refusal) never reports an earlier action's
  completion=function(p,action,step)
    local last=action=='shoot' and state().last_combat or action=='drop' and state().last_drop or timed[action] and state().last
    local row=last and last[p.index]
    if row and step and step.started_tick and (row.tick or 0)<step.started_tick then return nil end
    return row
  end,
  moved_step=function(p,step,result) return M.moved_step(p,step,result) end,
  outcome=function(p,action,step)
    local last=action=='shoot' and state().last_combat or action=='drop' and state().last_drop or timed[action] and state().last
    local row=last and last[p.index]
    if row and step and step.started_tick and (row.tick or 0)<step.started_tick then return nil end
    return row and row.outcome
  end
}
scheduler=scheduler_module(M.scheduler_api)
scheduler=require('queue_lanes'){scheduler=scheduler,factory=scheduler_module,base=M.scheduler_api,is_read=function(action) return M.is_read(action) end,
  deliver=function(index,t) return M.board.deliver(index,t) end}
-- (d17 batch21 D1) a queue call for a platform's own lane: as the remote lane, no body
function M.platform_lane(a) return type(a)=='table' and type(a.lane)=='string' and a.lane:match('^platform:.+$')~=nil end
for name,handler in pairs(scheduler.handlers) do handlers[name]=handler end
-- A direct action a harness update stopped, started again from the call that started it (carry.lua), ending by
-- the tick it would have (until_tick: a pending fh --wait budgets for that).
function M.restart_call(index,call,until_tick)
  local ok,err=pcall(function()
    local p=player(index,call.seated)
    handlers[call.action](p,call.args)
    local now=state().active[index]
    if now then
      now.call=call
      if until_tick and now.until_tick and now.until_tick>until_tick then now.until_tick=until_tick end
    end
  end)
  return ok,(not ok) and reason(err) or nil
end
-- An action carried over a harness update as it was (carry.lua): what the outgoing stop undid on the character, and
-- fields this runtime counts that the one before did not (a wait at a machine's output counts from now: stock.lua).
function M.resume_carried(index,action)
  if action.kind=='repair' then
    local ok,p=pcall(player,index)
    if ok then M.rehold_tool(p,action) end
  elseif action.kind=='gather' then stock.carried(action) end
end
-- Standing orders (orders.lua): the agent's routines, run in its own queue
-- while its character is free.
M.orders=require('orders'){state=state,player=player,scheduler=scheduler,agents=function() return M.board.agents() end,
  -- (C2) what enemies our force sees now hold the place (an area under attack, units or a group, as move_to counts
  -- them), nil when clear; no place: round the character
  enemies_near=function(index,at)
    local p=M.lookup(index)
    if not (p and p.character and p.character.valid) then return nil end
    local q=at or p.position
    for _,d in ipairs(M.avoid.attack_discs(p.surface,M.avoid.mode(nil),{q.x-40,q.y-40,q.x+40,q.y+40})) do
      if distance(d,q)<d.r then return string.format('%s at (%d,%d)',d.name,math.floor(d.x+0.5),math.floor(d.y+0.5)) end
    end
  end,
  condition=function(p,c) return conditions.check(p,c) end,validate_condition=function(c) return conditions.validate(c) end,
  busy=function(index)
    local action=state().active[index]
    if action then return action.kind end
    if state().combat and state().combat[index] then return 'shoot' end
  end,
  interrupt=function(index) M.stop_player(index,'interrupted') end,
  -- The agent's own last request (a clock a peek started is not one) or fh sleep poll.
  last_seen=function(index)
    local c=(state().clocks or {})[index]
    if not c then return nil end
    return math.max(not c.peeked and c.call_tick or 0,c.wait_tick or 0)
  end}
