function handlers.construction_robots(p,a)
  if a.surface==nil then return M.robots.read(p,a) end
  -- Another planet by remote view (M.on_surface): a place there, or a network id.
  assert(a.position~=nil or a.network~=nil,'construction_robots with surface needs position or network there')
  local args={}
  for k,v in pairs(a) do if k~='surface' then args[k]=v end end
