    local out,clocks={},state().clocks or {}
    local function recent(c) return c and ((not c.peeked and game.tick-c.call_tick<=window) or (c.wait_tick and game.tick-c.wait_tick<=window)) end
    for _,b in ipairs(M.bots.list()) do if recent(clocks[b.index]) then out[#out+1]=b.name end end
    for index in pairs(state().controlled or {}) do
      local p=game.get_player(index)
      if p and recent(clocks[index]) then out[#out+1]=p.name end
    end
    return out
  end,
  viewer_name=M.audience.viewer_name,muted=M.audience.muted,mute=M.audience.mute,unmute=M.audience.unmute,muted_list=M.audience.muted_list,
  human=function(name) return M.players.find(name) end,group=function(p) return M.players.group(p) end}
for name,handler in pairs(M.votes.handlers) do handlers[name]=handler end
for name,handler in pairs(M.players.handlers) do handlers[name]=handler end
function handlers.cameras() return M.cameras.list() end
-- A load_silo queue step paused by the agent's own build, transfer and the like (Sonnet, Astra) was requeued
-- (scheduler.lua): the queue goes on at once when the call ran at once, or when the timed action it started ends.
M.RESUME_AFTER={build=true,transfer=true,collect=true,feed=true,rearm=true,refuel=true,configure=true,rotate=true,pickup=true,mine=true,craft=true,load_silo=false}
function M.resume_after(index,id)
  local q=(state().queues or {})[index]
  if q and q.held then return false end  -- the agent's own pause (queue_pause) holds
  if q and q.paused and q.pending[1] and q.pending[1].id==id then q.paused=false; q.revision=q.revision+1; q.requeued_load=nil; return true end
end
function M.resume_requeued_load(p,action,result)
  local q=(state().queues or {})[p.index]
  local r=q and q.requeued_load
  if q and q.held and q.paused and type(result)=='table' and M.RESUME_AFTER[action] then
    result.queue_held=string.format('your queue is paused by you (queue_pause, %ds ago) with %d pending: it holds until queue_resume; this call did not resume it',
      math.floor((game.tick-q.held.tick)/60),#q.pending)
    q.requeued_load=nil
    return
  end
  if not (r and r.tick==game.tick and q.paused) then return end
  if not M.RESUME_AFTER[action] then q.requeued_load=nil; return end
  local now=state().active[p.index]
  local text
  if now and now.until_tick then
    now.resume_queue=r.id
    text=string.format('your queue\'s load_silo step (%s) was requeued: the queue goes on when this %s ends (queue_pause first holds it until queue_resume)',r.id,tostring(now.kind))
  elseif M.resume_after(p.index,r.id) then
    text=string.format('your queue\'s load_silo step (%s) was requeued and the queue goes on',r.id)
  end
  if text and type(result)=='table' then result.queue_resumed=text end
end
-- A direct wait_ticks or wait_until as a sleep's request (the queue runs on; dispatch): ticks or timeout as seconds
-- (rounded up), the rest of wait_until's arguments as the condition, and the wake options.
-- (d18 batch36 B1) wake: {near: N} on sleep, wait_ticks and wait_until is the urgent wake filter (urgent.lua M.option).
function M.wake_arg(a)
  if type(a)~='table' or a.wake==nil then return a end
  assert(a.wake_on_urgent==nil,'give wake or wake_on_urgent, not both')
  assert(type(a.wake)=='table' and a.wake.near~=nil,'wake is {near: N}: only an attack on ours or buildings of ours destroyed within N tiles of you (1..200) wake it; other urgent alerts are held for the reply')
  local c={}
  for k,v in pairs(a) do if k~='wake' then c[k]=v end end
  c.wake_on_urgent={near=a.wake.near}
  return c
end
function M.wait_as_sleep(request)
  local a=M.wake_arg(request.args)
  local args={wake_on_messages=a.wake_on_messages,wake_on_viewers=a.wake_on_viewers,wake_on_urgent=a.wake_on_urgent,wake_from=a.wake_from,wake_on_operator=a.wake_on_operator,wake_local=a.wake_local}
  if request.action=='wait_ticks' then
    args.seconds=math.max(1,math.min(900,math.ceil((tonumber(a.ticks) or 60)/60)))
  else
    args.seconds=math.max(1,math.min(900,math.ceil((tonumber(a.timeout) or 3600)/60)))
    local c={}
    for k,v in pairs(a) do
      if k~='timeout' and k~='pause_queue' and k~='wake_on_messages' and k~='wake_on_viewers' and k~='wake_on_urgent' and k~='wake_from' and k~='wake_on_operator' and k~='wake_local' then c[k]=v end
    end
    args.condition=c
  end
  local out={}
  for k,v in pairs(request) do out[k]=v end
  out.action='sleep'; out.args=args
  return out
end
-- wait_until as a direct call: a timed action that holds the character idle
-- until the condition is met (outcome met) or the timeout passes (timed_out),
-- so `fh call wait_until --wait` works outside a queue (in turn mode the
-- clock runs for it like any timed action).
function handlers.wait_until(p,a)
  a=M.wake_arg(a)
  assert(a.on_timeout==nil,'on_timeout is a queue step\'s (queue_submit {steps: [{action: "wait_until", args: {..., on_timeout: "hold"}}]}): a direct wait ends at its timeout')
  assert(a.wake_on_viewers==nil or type(a.wake_on_viewers)=='boolean','wake_on_viewers must be true or false')
  assert(a.wake_on_messages==nil or type(a.wake_on_messages)=='boolean','wake_on_messages must be true or false')
  local urgent_on,urgent_radius=M.urgent.option(a.wake_on_urgent)
  local viewers=a.wake_on_viewers==true or nil
  local messages=a.wake_on_messages
  local urgent=urgent_on and M.urgent.base(p,urgent_radius) or nil
  local wake_filter=M.board.wake_filter(a)
  if urgent and a.wake_local==true then urgent.local_only=true end  -- wake_local (d17 batch16 C1)
  if a.pause_queue~=nil or a.wake_on_viewers~=nil or messages~=nil or a.wake_on_urgent~=nil or a.wake_from~=nil or a.wake_on_operator~=nil or a.wake_local~=nil then
    local copy={}
    for k,v in pairs(a) do if k~='pause_queue' and k~='wake_on_viewers' and k~='wake_on_messages' and k~='wake_on_urgent' and k~='wake_from' and k~='wake_on_operator' and k~='wake_local' then copy[k]=v end end
    a=copy
  end
  conditions.validate(a)
  local timeout=integer(a.timeout,3600,1,54000,'timeout (1..54000 ticks)')
  local condition={}
  for k,v in pairs(a) do if k~='timeout' and k~='pause_queue' then condition[k]=v end end
  -- Met already: done at once, like construct with nothing to do.
  local record={kind='wait_until',condition=condition,until_tick=game.tick+timeout,next_check=game.tick+FEED_CHECK,start_tick=game.tick,
    wake_viewers=viewers,wake_messages=messages,urgent=urgent,default_timeout=a.timeout==nil or nil,wake_filter=wake_filter}
  local ok,met,saw=pcall(M.waiteta.check,p,condition,record)
  -- error, not assert: Factorio's Lua 5.2 assert puts the source line in front of the reason.
  if not ok then error(met,0) end
  if met then return M.waiteta.info({outcome='met',saw=saw,until_tick=game.tick},record) end
  if state().active[p.index] then finish(p.index,'replaced') else stop(p) end
  record.saw=saw; state().active[p.index]=record
  return M.waiteta.info({until_tick=game.tick+timeout,condition=condition['until'],saw=saw,wake_on_messages=messages},record)
end
