-- surface= reads that surface's remembered belts (it was ignored: the caller's surface was read).
function handlers.belt_gaps(p,a)
  if a.surface~=nil then p=M.on_surface(p,a.surface) end
  -- line: the whole belt line through one belt, end to end (linecut.lua M.line; d17 batch20 B3, Sonnet)
  if a.line~=nil then
    assert(a.from==nil and a.to==nil and a.via==nil,'give line (one belt of it), or from and to')
    local q=position(a.line)
    M.read_sight(p,q,'line')
    local e
    for _,o in pairs(p.surface.find_entities_filtered{position=q,radius=0.6,force=p.force}) do
      local t=o.type=='entity-ghost' and o.ghost_type or o.type
      if o.valid and (t=='transport-belt' or t=='underground-belt' or t=='splitter') then e=o; break end
    end
    assert(e,string.format('no belt, underground or splitter of ours at (%g,%g)',q.x,q.y))
    return M.linecut.line(p,e)
  end
  return M.beltgaps.read(p,a)
end
