-- fields (d18 batch39 C1, Astra, about 30 times a shift with a local JSON projection): platform, platforms, inspect and
-- status return only the named fields of the reply: a top-level key, a key of each row (platforms' rows, inspect's
-- results or entities: a row keeps name and position), or one level down ("hub.cargo"). The read runs whole; only the
-- reply is cut. (d22 batch90 AZ3: 177 refusals in s55-57 of names only some states have, eta_min, leg, freshness) A
-- name this reply lacks that the read can have (its describe text names it, or an earlier reply had it) is listed in
-- absent; only a name the read never has is refused, with the names there are.
M.FIELD_ROWS={'platforms','results','entities'}
M.FIELD_KEEP={name=true,position=true}
-- the names seen live in the save (state().field_seen), so a joined client answers as the server does
local function field_seen(action)
  local s=state()
  s.field_seen=s.field_seen or {}
  if action then s.field_seen[action]=s.field_seen[action] or {} end
  return action and s.field_seen[action]
end
local field_words={}
local function field_known(action,name)
  if not action then return false end
  local seen=field_seen(action)
  local head=name:match('^([^%.]+)%.') or name
  if seen and (seen[name] or seen[head]) then return true end
  local words=field_words[action]
  if not words then
    words={}
    local ok,d=pcall(function() return handlers.describe().actions[action] end)
    local function walk(t,depth)
      for k,v in pairs(t) do
        if type(k)=='string' then words[k]=true end
        if type(v)=='string' then for w in v:gmatch('[%a_][%w_]*') do words[w]=true end
        elseif type(v)=='table' and depth<4 then walk(v,depth+1) end
      end
    end
    if ok and type(d)=='table' then walk(d,1) end
    field_words[action]=words
  end
  return words[name]==true or words[head]==true
end
function M.project(out,fields,action)
  local list={}
  if type(fields)=='string' then for f in fields:gmatch('[^|,%s]+') do list[#list+1]=f end
  elseif type(fields)=='table' then for _,f in ipairs(fields) do assert(type(f)=='string','fields are names (strings)'); list[#list+1]=f end end
  assert(#list>=1 and #list<=32,'fields: 1..32 names')
  if type(out)~='table' then return out end
  local rowkey
  for _,k in ipairs(M.FIELD_ROWS) do if type(out[k])=='table' and type(out[k][1])=='table' then rowkey=k; break end end
  local function pick(t,f,dst)
    local head,rest=f:match('^([^%.]+)%.(.+)$')
    if head then
      local v=t[head]
      if type(v)=='table' and v[rest]~=nil then dst[head]=dst[head] or {}; dst[head][rest]=v[rest]; return true end
      return false
    end
    if t[f]~=nil then dst[f]=t[f]; return true end
    return false
  end
  local res,found={},{}
  local rows
  if rowkey then
    rows={}
    for i,row in ipairs(out[rowkey]) do
      local r={}
      for k in pairs(M.FIELD_KEEP) do r[k]=row[k] end
      for _,f in ipairs(list) do if pick(row,f,r) then found[f]=true end end
      rows[i]=r
    end
  end
  for _,f in ipairs(list) do if f~=rowkey and pick(out,f,res) then found[f]=true end end
  -- the names this action's replies have had (rows' too), for absent above
  if action then
    local seen=field_seen(action)
    for k in pairs(out) do if type(k)=='string' then seen[k]=true end end
    if rowkey then for i,row in ipairs(out[rowkey]) do if i>64 then break end; for k in pairs(row) do if type(k)=='string' then seen[k]=true end end end end
  end
  local missing,absent={},{}
  for _,f in ipairs(list) do
    if not found[f] and f~=rowkey then
      if field_known(action,f) then absent[#absent+1]=f else missing[#missing+1]=f end
    end
  end
  if #missing>0 then
    local names,seen={},{}
    local function add(t) for k in pairs(t) do if type(k)=='string' and not seen[k] then seen[k]=true; names[#names+1]=k end end end
    add(out); if rowkey then for _,row in ipairs(out[rowkey]) do add(row) end end
    table.sort(names)
    error(string.format('fields: %s %s never in this read\'s reply; its fields%s: %s (one level down as "name.key")',table.concat(missing,', '),#missing==1 and 'is' or 'are',
      rowkey and ' and its '..rowkey..' rows\' fields' or '',table.concat(names,', ')),0)
  end
  if rowkey then res[rowkey]=rows end
  res.fields=table.concat(list,', ')
  if #absent>0 then res.absent=absent end
  return res
end
for _,name in ipairs({'platforms','inspect','status'}) do
  local h=handlers[name]
  handlers[name]=function(p,a)
    if type(a)~='table' or a.fields==nil then return h(p,a) end
    local rest={}
    for k,v in pairs(a) do if k~='fields' then rest[k]=v end end
    -- (d22 batch90 AZ4) fields picks from the full rows, platforms' compact default aside
    if name=='platforms' and rest.compact==nil then rest.compact=false end
    -- (d22 batch96 BF1) the platforms read makes only the parts of a row those fields name (__want: each name's part
    -- before a dot)
    if name=='platforms' then
      local want={}
      for _,v in ipairs(type(a.fields)=='string' and {a.fields} or type(a.fields)=='table' and a.fields or {}) do
        for raw in tostring(v):gmatch('[^|,%s]+') do local k=raw:match('^[^.]+'); if k then want[k]=true end end
      end
      rest.__want=want
    end
    return M.project(h(p,rest),a.fields,name)
  end
end
-- (d18 batch37 U1, Haiku: a long rearm leg cut at once with enemies_ahead, retry_when_clear or not) a walking rearm, and
-- a walking transfer with retry_when_clear, waits where it stands for a leg enemies pass (stock.lua ahead_wait):
-- retry_ticks with retry_when_clear, else 60 s; rearm by default, retry_when_clear: false for none.
M.AHEAD_WAIT=3600
do
  local function with_ahead(name,default)
    local h=handlers[name]
    handlers[name]=function(p,a)
      local before=state().active[p.index]
      local out=h(p,a)
      local now=state().active[p.index]
      if now and now~=before and now.kind=='gather' and now.avoid_mode and type(a)=='table' then
        local w
        if a.retry_when_clear==true then w=a.retry_ticks~=nil and integer(a.retry_ticks,M.AHEAD_WAIT,600,54000,'retry_ticks') or M.AHEAD_WAIT
        elseif a.retry_when_clear==nil then w=default end
        if w then
          now.ahead_wait=w
          if type(out)=='table' then out.leg_wait=string.format('a leg enemies pass is waited for where you stand, up to %d s (rechecked every 3 s), then walked',math.floor(w/60)) end
        end
      end
      return out
    end
  end
  with_ahead('rearm',M.AHEAD_WAIT)
  with_ahead('transfer',nil)
end
