function handlers.circuit_audit(p,a)
  -- (d20 batch62 X4) surface: the networks of our entities at area or positions there, by remote view (in chunks our
  -- force sees now)
  if a.surface~=nil then
    assert(a.platform==nil,'give platform or surface, not both')
    assert(a.area~=nil or a.positions~=nil,'circuit_audit with surface needs area or positions there (your character may stand on another surface)')
    return M.circaudit.read(M.on_surface(p,a.surface),M.without(a,'surface'))
  end
  return M.circaudit.read(p,a)
end
