-- The belt, line-cut, robot-loss and power-cut alert groups of a force, kept (pushalerts belt_groups).
function M.belt_groups_read(f)
  M.belt_groups_kept=M.belt_groups_kept or {}
  local out=M.beltgaps.alert_groups(f)
  local ok,cuts=pcall(M.linecut.alert_groups,f)
  for _,g in ipairs(ok and cuts or {}) do out[#out+1]=g end
  local okr,lost=pcall(M.robotloss.alert_groups,f)
  for _,g in ipairs(okr and lost or {}) do out[#out+1]=g end
  -- power cuts not joined again (powercut.lua; batch32 B3)
  local okp,pc=pcall(M.powercut.alert_groups,f)
  for _,g in ipairs(okp and pc or {}) do out[#out+1]=g end
  M.belt_groups_kept[f.name]={tick=game.tick,list=out}
  return out
end
M.pushalerts=require('pushalerts'){rest_label=function(name) local r=M.rests.get(name); return r and M.rests.label(r) or nil end,platform_eta=function(pl,loc)
    local leg=M.freight.leg(pl)
    if leg and leg.to==loc and leg.eta_ticks then return leg.eta_ticks/60 end
    local est=M.freight.before_departure(pl,loc)
    return est and est.eta_s or nil
  end,mine_forecast=function(surface,force,q,cap) return M.ores.forecast(surface,force,q,cap) end,
  territory=function(surface,force,pos) return M.territory_line(surface,force,pos) end,belt_groups=function(f)
    -- (d19 batch44 A2: these four took about 4.6 ms in every reply of every agent on the private copy) the list is
    -- kept per force; (d19 batch45: the first reply after it aged paid them) read again in the tick every 120 ticks
    -- (M.belt_groups_read), here only when none is kept or the kept one is 600 ticks old
    local kept=(M.belt_groups_kept or {})[f.name]
    if kept and game.tick-kept.tick<600 and game.tick>=kept.tick then return kept.list end
    return M.belt_groups_read(f)
  end,drill_site=function(f,g) return M.drill_sites.group(f,g) end,state=state,timed=M.timed,silo_sample=function(e) return M.silo.sample_made(e) end,agents=function() return M.board.agents() end,who=M.board.who,
  first_spoil=function(inv) return survey.first_spoil(inv) end,
  burnt_stuck=function(e) return M.burnt.stuck(e) end,condition_text=function(c) return M.circuits.condition_text(c) end,
  negative_note=function(item,n) return M.circuits.negative_note(item,n) end,
  claim_surface=function(i) return M.claims.surface_of(i) end,
  status_name=function(e) return entity_status_names[e.status] end,
  place=function(index) return M.where.place(index,true) end,targets=M.targets,
  network_groups=function(force)
    local out=M.networks.alert_groups(force)
    local ok,more=pcall(M.lightning.alert_groups,force)
    if ok then for _,g in ipairs(more) do out[#out+1]=g end
    else local s=state(); s.lightning_errors={count=((s.lightning_errors or {}).count or 0)+1,last=tostring(more),tick=game.tick} end
    -- A science colour with no maker working for 5+ min (scienceline.lua, Opus 07:55).
    local oks,idle=pcall(M.scienceline.alert_groups,force)
    if oks then for _,g in ipairs(idle) do out[#out+1]=g end end
    return out
  end,
  -- The same in steps for the background read: max networks a step, then lightning, then science (networks.alert_step).
  network_cursor=function(force) return {nets=M.networks.alert_cursor(force),phase='nets'} end,
  -- Our buildings outside every lightning attractor's protection, in steps (lightning.lua; d17 territory part 4).
  strike_cursor=function(surface,force) return M.lightning.exposure_cursor(surface,force) end,
  strike_step=function(cur,max) return M.lightning.exposure_step(cur,max) end,
  strike_lines=function(strike,force,areas) return M.lightning.exposure_lines(strike,force,areas) end,
  network_step=function(cur,max)
    local out=cur.nets.out
    if cur.phase=='nets' then
      if M.networks.alert_step(cur.nets,max) then cur.phase='lightning' end
      return false
    elseif cur.phase=='lightning' then
      cur.phase='science'
      local ok,more=pcall(M.lightning.alert_groups,game.forces[cur.nets.force])
      if ok then for _,g in ipairs(more) do out[#out+1]=g end
      else local s=state(); s.lightning_errors={count=((s.lightning_errors or {}).count or 0)+1,last=tostring(more),tick=game.tick} end
      return false
    end
    local oks,idle=pcall(M.scienceline.alert_groups,game.forces[cur.nets.force])
    if oks then for _,g in ipairs(idle) do out[#out+1]=g end end
    return true,out
  end,
  -- The game's alerts are the force's: any connected player of it reads the same list. A person first; else a camera
  -- client (d17 16:58: with no person connected nothing was read, so the agents never got the game's no-storage or
  -- no-materials alerts; a camera's list matched Nick's exactly). A camera's GUI hides the alert panel, not the list.
  alert_reader=function(force) return M.cameras.alert_reader(force, M.is_director) end}
