-- (d18 batch37 D4, viewer Aurora 18:11) every agent's queued or running jobs that act on or wait on a platform
-- (platjobs.lua): on the platforms read (one platform, or each row with jobs) and platform_digest. Read only.
M.platjobs=require('platjobs'){state=state,lookup=function(i) return M.lookup(i) end,remote_keys=function(s) return scheduler.remote_keys(s) end}
do
  local plain=handlers.platforms
  handlers.platforms=function(p,a)
    local out=plain(p,a)
    -- (d22 batch96 BF1) the jobs lines only for full rows: the compact read has none (1 ms a call on a copy of world n)
    if not (type(out)=='table' and type(out.platforms)=='table') then return out end
    local want={}
    for _,row in ipairs(out.platforms) do if type(row)=='table' and row.name then want[row.name]=true end end
    local ok,by=pcall(M.platjobs.all,want)
    if ok then
      for _,row in ipairs(out.platforms) do
        if type(row)=='table' and row.name and by[row.name] then row.jobs=M.platjobs.lines(row.name,by) end
      end
    end
    return out
  end
end
-- platform_tiles (tilecheck.lua, batch24 B3): tiles at exact coordinates, and whether the hub removes or builds them now.
M.tilecheck=require('tilecheck')()
function handlers.platform_tiles(p,a)
  local pl=space.platform(p,a.platform)
  assert(pl.surface,'platform '..pl.name..' has no surface yet')
  local cells={}
  if a.positions~=nil then
    assert(type(a.positions)=='table' and #a.positions>=1 and #a.positions<=64,'positions: 1..64 tiles {x,y}')
    for _,q in ipairs(a.positions) do local v=position(q); cells[#cells+1]={v.x,v.y} end
  else
    assert(type(a.area)=='table' and a.area.left_top and a.area.right_bottom,'positions (1..64 tiles) or area {left_top, right_bottom}')
    local lt,rb=position(a.area.left_top),position(a.area.right_bottom)
    local x0,y0,x1,y1=math.floor(lt.x),math.floor(lt.y),math.ceil(rb.x)-1,math.ceil(rb.y)-1
    assert((x1-x0+1)*(y1-y0+1)<=64,'area: at most 64 tiles (8x8)')
    for y=y0,y1 do for x=x0,x1 do cells[#cells+1]={x,y} end end
  end
  return M.tilecheck.query(pl,cells)
end
