-- A full drop's pods that wait for a hatch (space.lua), every 10 ticks: sent
-- as hatches free up, then the result kept as last_drop (status shows it,
-- and drop_pending while pods wait; --wait follows them as it does shoot).
function M.drop_jobs_tick(tick)
  local jobs=state().drop_jobs
  if not (jobs and next(jobs)) or tick%10~=0 then return end
  for index,job in pairs(jobs) do
    local ok,outcome=pcall(space.drop_tick,M.lookup(index),job)
    if not ok then job.why=reason(outcome); outcome='failed' end
    if not outcome and tick>job.until_tick then outcome='timed_out' end
    if outcome then
      local result,why=space.drop_result(job,outcome)
      state().last_drop=state().last_drop or {}
      state().last_drop[index]={kind='drop',outcome=outcome,tick=tick,result=result,why=why}
      jobs[index]=nil
    end
  end
end
function M.drop_pending(index)
  local job=state().drop_jobs and state().drop_jobs[index]
  return job and {kind='drop',platform=job.platform.valid and job.platform.name or nil,pods_sent=#job.sent,pods_left=#job.pods,until_tick=job.until_tick} or nil
end
-- The last full drop's result for a minute after it ended (a wait reads it once).
function M.last_drop(index)
  local last=state().last_drop and state().last_drop[index]
  return last and game.tick-last.tick<=3600 and last or nil
end
-- (d20 batch54 N6, viewers Foobator 14:43 and 14:49: "we're seeing grok do something to stay stationary on the belt")
-- A tour's hold at an entity (a visit that waits: load_silo's silo stop) begun on a belt or rail: Grok's silo wait stood
-- on a west belt 400+ s, the belt carrying him to the edge of reach and the tour's leg walking him back each time, a
-- walk in place. The hold steps to the nearest free tile in reach of the entity without a belt or rail, as move_to's
-- arrival does (last.off_belt), at most 10 s; action.hold_belt {line} says what it did. True while it steps.
function M.hold_off_belt(p,action,e)
  local hb=action.hold_belt
  if hb and hb.done then return false end
  if not hb then
    if not (p.character and e and e.valid) then return false end
    local pos=p.position
    local belt=M.pathing.belt_at(p.surface,pos)
    local rail=not belt and M.rail_under(p,pos)
    if not (belt or rail) then return false end
    local r=(p.reach_distance or 10)-0.5
    local spot=M.pathing.off_belt_spot(p,pos,0,function(c) return M.box_distance(c,e)<=r end,function(c) return M.rail_under(p,c,0.35)~=nil end)
    hb={on=belt and belt.name or 'rail',at={x=pos.x,y=pos.y},spot=spot,since=game.tick}
    action.hold_belt=hb
    if not spot then
      hb.done=true
      hb.line=string.format('held on a %s at (%.1f,%.1f): no free tile without a belt or rail within 4 tiles in reach of %s',hb.on,pos.x,pos.y,e.name)
      return false
    end
  end
  if distance(p.position,hb.spot)<=0.3 or game.tick-hb.since>600 then
    hb.done=true
    local there=distance(p.position,hb.spot)<=0.3
    hb.line=there and string.format('the hold began on a %s at (%.1f,%.1f); stepped to (%g,%g), the nearest free tile without a belt or rail in reach of %s',
      hb.on,hb.at.x,hb.at.y,hb.spot.x,hb.spot.y,e.name)
      or string.format('the hold began on a %s at (%.1f,%.1f); the step to (%g,%g) did not get there in 10 s (now (%.1f,%.1f))',hb.on,hb.at.x,hb.at.y,hb.spot.x,hb.spot.y,p.position.x,p.position.y)
    return false
  end
  steer(p,hb.spot,nil)
  return true
end
stock=stock_module{hold_off_belt=function(p,action,e) return M.hold_off_belt(p,action,e) end,elsewhere=function(...) return M.elsewhere.line(...) end,on_ground=function(force,surface,item,o) return M.stores.on_ground(force,surface,item,o) end,give=function(p,e,item,quality,count,inv) return transfer_one(p,{direction='to_entity',item=item,quality=quality,count=count,inventory=inv},e.position,e) end,pods_deposit=function(p,action,chest) return M.pods_deposit(p,action,chest) end,pods_owed=function(p,action) return M.pods_owed(p,action) end,
  corridor=function(p,from,goal,near) return M.pathing.corridor(body(p) or p,from,goal,near) end,stall_why=function(p,nav,goal) return M.pathing.stall_why(body(p) or p,nav,goal) end,distance=distance,integer=integer,position=position,claims=M.claims,spoil=M.spoil,
  -- a stop's transfer reach, as move_to {target} walks to it (A5, Gemini 21:29: a silo's centre lies inside it)
  reach_target=function(p,e) return M.walk_target(p,{target={position=e.position,unit_number=e.unit_number,name=e.name}}) end,
  reserved=function(e,item) local ok,r=pcall(M.supply.reserved,e,item); return ok and r or 0 end,
  -- One stop of a rearm/refuel tour: top the entity up; stop when none is left.
  visit=function(p,action,e)
    if action.op=='refuel_source' then return M.fuelround.source_visit(p,action,e) end
    if action.fuel_round then return M.fuelround.feed_visit(p,action,e) end
    if action.op=='load_silo' then return M.rocketload.walk_visit(p,action,e) end
    if action.op=='feed' then
      -- A feed stop gives every want; the tour ends early once nothing the
      -- remaining machines want is left above the reserve.
      local gave,n,_,_,_,cleared=feeding.one(p,e,action.feed)
      for item,c in pairs(gave) do action.items=action.items or {}; action.items[item]=(action.items[item] or 0)+c end
      -- Each stop: what the machine got and its fuel after (last.entities).
      action.rows=action.rows or {}
      -- Given nothing, with spoilage its recipe does not take in its input (Sol, 22:08): said on its row.
      local sp=n==0 and select(2,pcall(M.slots.input_spoilage,e)) or nil
      action.rows[#action.rows+1]={position=e.position,name=e.name,gave=next(gave) and gave or nil,got=n==0 and 'nothing' or nil,fuel=feeding.fuel_line(e),
        spoilage=type(sp)=='table' and sp.text or nil,cleared=cleared}
      local more,short=false,false
      for i=action.index+1,#action.targets do
        local t=action.targets[i]
        if t.entity and t.entity.valid and feeding.hungry(p,t.entity,action.feed) then more=true; break end
      end
      -- Nothing more to give: out of what the rest want, or the rest hold enough already (topped_up).
      if not more then
        for i=action.index+1,#action.targets do
          local t=action.targets[i]
          if t.entity and t.entity.valid and feeding.short_of(p,t.entity,action.feed) then short=true; break end
        end
      end
      return {transferred=n,stop=(not more and action.targets[action.index+1]) and (short and 'out_of_items' or 'topped_up') or nil}
    end
    if action.op=='transfer' then
      -- transfer {walk=true}: the call's own transfer at each place (M.transfer_walk); a row per place. A courier
      -- (M.pick_source with to): its leg's transfer, the give for what the take got.
      -- (d18 batch37 C1) a chain's leg: a take or a give, sized now (transferchain.lua)
      if action.chain then
        local t,g=M.transferchain.args(p,action)
        local epos,ename=e.position,e.name
        local out=transfer_one(p,t,nil,e)
        M.transferchain.moved(action,g,e,out.transferred or 0)
        if (out.transferred or 0)>0 then action.items[g.item]=(action.items[g.item] or 0)+out.transferred end
        action.rows[#action.rows+1]={position=epos,name=ename,moved=out.transferred,direction=t.direction,step=g.step,item=g.item}
        return {transferred=out.transferred}
      end
      local t=action.legs and action.legs[action.index] or action.transfer
      if action.fill and not action.legs then
        local c={}
        for k,v in pairs(t) do c[k]=v end
        c.count=math.max(1,action.fill-action.got)
        t=c
      end
      if t.give_taken then
        local c={}
        for k,v in pairs(t) do c[k]=v end
        c.give_taken=nil; c.count=math.max(1,action.taken or 0)
        t=c
      end
      -- Read before the take: a corpse emptied by it is gone after (recover).
      local epos,ename=e.position,e.name
      local out=t.items and M.transfer_items_one(p,t,e) or transfer_one(p,t,nil,e)
      if t.items then action.entries=out.entries; action.short=out.short end
      -- The moved batch's spoilage over the tour (the courier's take leg only: its give moves the same items).
      if out.fresh and not (action.legs and action.index>1) then action.fresh=M.fresh_merge(action.fresh or {},out.fresh) end
      -- What a spoil filter left where it was (min_spoil, max_fresh, min_fresh): last.left_less_fresh
      if out.left_less_fresh then
        local q=string.format('(%g,%g): %s',epos.x,epos.y,out.left_less_fresh)
        action.left_less_fresh=action.left_less_fresh and action.left_less_fresh..'; '..q or q
      end
      local moved=t.item and {{name=t.item,count=out.transferred,quality=t.quality}} or out.items or {}
      for _,st in ipairs(moved) do
        if (st.count or 0)>0 then
          local key=st.name..(st.quality and st.quality~='normal' and '@'..st.quality or '')
          action.items[key]=(action.items[key] or 0)+st.count
        end
      end
      action.rows[#action.rows+1]={position=epos,name=ename,moved=out.transferred,direction=action.legs and t.direction or nil,
        full=(out.inventory_full or out.entity_full) and true or nil,inventory=out.inventory or t.inventory,delivery_note=out.delivery_note,removed=out.corpse_removed,why=out.entity_full and out.entity_full.slots or nil}
      -- The courier's take: nothing taken ends it before the walk on; a full inventory still carries what it took.
      if action.legs and action.index==1 then
        action.taken=out.transferred
        return {transferred=out.transferred,stop=out.transferred==0 and 'nothing_collected' or nil}
      end
      local stop
      if t.item and t.direction=='to_entity' and held(p,t.item,t.quality)==0 and crafting_count(p,t.item)==0 and action.targets[action.index+1] then stop='out_of_items' end
      return {transferred=out.transferred,inventory_full=t.direction=='to_player' and out.inventory_full or nil,stop=stop}
    end
    -- each turret its own ammo (A3: action.item_of by unit number)
    local item=action.item_of and e.unit_number and action.item_of[e.unit_number] or action.item
    local args={direction='to_entity',item=item,quality=action.quality,count=action.count,up_to=action.count,
      inventory=action.op=='refuel' and 'fuel' or nil}
    local out=transfer_one(p,args,nil,e)
    -- (batch28 C3, Haiku) a rearm tour's line per turret: what it got and what it holds now (last.turret_lines)
    if action.op=='rearm' then
      local okh,h=pcall(function() return e.get_inventory(defines.inventory[ammo_inventory[e.type]]).get_item_count() end)
      action.turret_lines=action.turret_lines or {}
      action.turret_lines[#action.turret_lines+1]=string.format('%s (%g,%g): +%d %s, holds %s now',e.name,e.position.x,e.position.y,out.transferred or 0,tostring(item),okh and tostring(h) or '?')
    end
    if action.item_of then
      action.items=action.items or {}
      if (out.transferred or 0)>0 then action.items[item]=(action.items[item] or 0)+out.transferred end
      return {transferred=out.transferred}
    end
    local left=held(p,action.item,action.quality)
    local stop
    if left==0 and action.targets[action.index+1] and crafting_count(p,action.item)==0 then
      -- Out of it with stops left: out_of_items only while one of them still wants it (Haiku, d15 07:50: a tour whose
      -- remaining burners held enough ended out_of_items, and fh wait exited 1); else topped_up.
      stop='topped_up'
      for i=action.index+1,#action.targets do
        local te=action.targets[i].entity
        if te and te.valid and M.tour_wants(te,action) then stop='out_of_items'; break end
      end
    end
    return {transferred=out.transferred,stop=stop}
  end,
  -- A collect's min_fresh rides on its action (stock.lua start, start_wait).
  take=function(p,e,item,quality,count,inv,tally)
    local act=state().active[p.index]
    return transfer_one(p,{direction='to_player',item=item,quality=quality,count=count,inventory=inv,tally=tally,min_fresh=act and act.min_fresh or nil},nil,e)
  end,
  request_path=function(p,nav) return request_path(p,nav) end,navigate=function(p,nav) return navigate(p,nav) end,
  -- recover's walk keeps out of the enemy reach the map shows, as move_to's (avoid.lua).
  avoid_report=function(out,nav) return M.avoid.report(out,nav) end,
  avoid_start=function(p,nav,mode) return M.avoid.start(p,nav,mode) end,
  stop_walking=function(p) p.walking_state={walking=false,direction=defines.direction.north} end,
  -- a tour ending on rails walks off them (backlog #820)
  rail_under=function(p,pos) return p.character and M.rail_under(p,pos)~=nil end,
  off_rail_spot=function(p) local spot=M.pathing.off_belt_spot(p,p.position,4,nil,function(c) return M.rail_under(p,c,0.35)~=nil end); return spot end,
  -- A tour's legs round the worms the map shows (avoid.lua), as a walk's: each leg's end starts the next.
  leg_done=function(p,nav,outcome) return M.avoid.leg_done(p,nav,outcome) end,
  -- A courier's destination found on arrival: within reach of its position, then the entity there.
  near=function(p,pos) return distance(p.position,pos)<=math.max(1,(p.reach_distance or 10)-1) end,
  find=function(p,pos) return entity(p,{position=pos}) end,
  -- Every tour's enemy check (round1950a): the walk's mode, and a place inside a reach the map shows.
  avoid_mode=function(v) return M.avoid.mode(v) end,
  goal_check=function(p,from,goal,mode) return M.avoid.goal_check(p,from,goal,mode) end,leg_threat=function(p,from,to,mode) return M.avoid.leg_threat(p,from,to,mode) end,
  goal_text=function(label,goal,c) return M.avoid.goal_text(label,goal,c) end,
  -- The call's check of every stop (round2120a), and the reply's avoid_enemies line.
  goal_inside=function(p,goal,mode) return M.avoid.inside(p,goal,mode) end,
  describe_avoid=function(mode) return M.avoid.describe(mode) end}
