  legs=function(p,targets) return M.legs(p,targets) end,nearest_outside=function(...) return M.nearest_outside(...) end,
  accepts=function(e,item) return M.farm.accepts_fuel(e,item) end,entity=remote_entity,held=held,
  give=function(p,e,item,quality,count) return transfer_one(p,{direction='to_entity',inventory='fuel',item=item,quality=quality,count=count,up_to=count},nil,e) end,
  -- feed_chests: a chest's inventory, a give into it, and the chests inserters take from to feed a burner.
  chest_inventory=function(e) local ok,inv=pcall(function() return e.get_inventory(defines.inventory.chest) end); return ok and inv or nil end,
  give_chest=function(p,e,item,quality,count) return transfer_one(p,{direction='to_entity',inventory='chest',item=item,quality=quality,count=count,up_to=count},nil,e) end,
  feed_chests=function(p,burner)
    local out={}
    local b=burner.bounding_box
    for _,ins in ipairs(p.surface.find_entities_filtered{area={{b.left_top.x-3,b.left_top.y-3},{b.right_bottom.x+3,b.right_bottom.y+3}},type='inserter',force=p.force}) do
      local okd,drop=pcall(function() return ins.drop_target end)
      local okp,pick=pcall(function() return ins.pickup_target end)
      if okd and drop==burner and okp and pick and pick.valid and (pick.type=='container' or pick.type=='logistic-container') and pick.force==p.force then out[#out+1]=pick end
    end
    return out
  end,
  start_tour=function(...) return stock.start_tour(...) end,screen=function(...) return stock.screen(...) end,
  tick=function(...) return stock.tick(...) end,
  take=function(p,e,item,quality,count) return transfer_one(p,{direction='to_player',inventory='chest',item=item,quality=quality,count=count},nil,e) end,
  belt_count=function(...) return M.beltpick.count(...) end,belt_take=function(...) return M.beltpick.take(...) end,
  stop=function(p) p.walking_state={walking=false,direction=defines.direction.north} end,
  start=function(p,action) if state().active[p.index] then finish(p.index,'replaced') else stop(p) end;state().active[p.index]=action end}
-- A route given up only for enemies that move (d17 batch17 B3, Opus on the far-east route: no_safe_route for a roaming
-- group, a lone big biter and an attack where he stood; standing where such a walk ended, he died): stand, and plan
-- again after 5 s, up to 6 times (nav.unit_waits; the reply's last.waited_for_units says for what); worms and spawners
-- end it as before.
M.UNIT_WAIT_TICKS,M.UNIT_WAITS=300,6
function M.unit_wait(p,nav)
  local who=M.avoid.moving_only and M.avoid.moving_only(nav)
  if not who or (nav.unit_waits or 0)>=M.UNIT_WAITS then return false end
  nav.unit_waits=(nav.unit_waits or 0)+1
  nav.unit_wait_until=game.tick+M.UNIT_WAIT_TICKS
  nav.waited_for_units=string.format('no way round %s (enemies that move): stood and planned again %d time%s, 5 s apart',who,nav.unit_waits,nav.unit_waits==1 and '' or 's')
  nav.path_state='waiting_units'
  local c=p.character
  nav.unit_wait_health=c and c.valid and c.health or nil
  return true
end
-- Shared walking controller (move_to, construct). Follows the engine path when
-- one exists, else steers directly. A stall of a few ticks first sidesteps
-- perpendicular to the heading, then re-paths with a wider goal radius, and
-- only gives up after repeated failures. Diagnostics stay on `nav`.
do local STALL_TICKS,SIDESTEP_TICKS,MAX_STALLS,MAX_REPLANS,PROGRESS_TICKS=8,12,15,5,90
navigate=function(p,nav)
  local pos,goal=p.position,nav.position
  -- waiting for enemies that move to clear the way (M.unit_wait), then planned again
  if nav.path_state=='waiting_units' then
    p.walking_state={walking=false,direction=defines.direction.north}
    -- hit while it stands: the walk ends now, and the retreat on a hit with no action running takes over
    local c=p.character
    if nav.unit_wait_health and c and c.valid and c.health<nav.unit_wait_health then nav.waited_for_units=(nav.waited_for_units or '')..'; hit while standing: ended'; return 'no_safe_route' end
    if game.tick<(nav.unit_wait_until or 0) then return end
    nav.path_state=nil; nav.foes=nil; nav.found=nil
    if nav.avoid_mode and not nav.direct then M.avoid.start(p,nav,nav.avoid_mode) end
    request_path(p,nav); return
  end
  if nav.path_state=='unsafe' then
    p.walking_state={walking=false,direction=defines.direction.north}
    if M.margin_probe.tick(p,nav) then return end
    if M.unit_wait(p,nav) then return end
    return 'no_safe_route'
  end
  -- A move_to never ends on a belt (shift08: Grok's arrivals on the y=-27.5
  -- belt carried it off, then transfers failed out of reach): from a belt it
  -- steps to the nearest free tile without one (pathing.lua).
  if nav.step_off then
    if distance(pos,nav.step_off)<=0.3 or game.tick-nav.step_off_tick>120 then return 'arrived' end
    steer(p,nav.step_off,nav); return
  end
  -- A target's reach (move_to target), on the last leg: arrived once within it.
  local rt=nav.reach_target
  if rt and nav.via and nav.via.index<=#nav.via.points then rt=nil end
  local reached
  if rt then
    reached=M.in_reach(p,rt)
    if reached=='gone' then nav.why=string.format('the target %s (%g,%g) is gone',rt.name,rt.center.x,rt.center.y); return 'failed' end
  end
  if reached or distance(pos,goal)<=math.max(nav.tolerance,(p.character_running_speed or 0)*0.55) then
    -- Nor on a ground rail (round1520d: a character left standing on a track was killed by the next train).
    -- (a corner of a way round enemies is passed: only the last leg steps off)
    local belt=nav.off_belts and not nav.leg and M.pathing.belt_at(p.surface,pos)
    local rail=nav.off_belts and not nav.leg and not belt and M.rail_under(p,pos)
    belt=belt or rail
    if not belt then return 'arrived' end
    -- A target's reach: the free tile must stay within it (a walk that stopped in reach on a belt stepped 4 tiles
    -- further in, to a tile within the arrival radius of the target's centre).
    local spot,within=M.pathing.off_belt_spot(p,goal,nav.tolerance,rt and reached and function(c) return M.reach_dist(c,rt)<=rt.r-0.25 end or nil,
      function(c) return M.rail_under(p,c,0.35)~=nil end)
    nav.off_belt={belt=belt.name,rail=rail and true or nil,spot=spot,within=within,reach=rt and reached and true or nil}
    if not spot then return 'arrived' end
    nav.step_off=spot; nav.step_off_tick=game.tick; steer(p,spot,nav); return
  end
  local last=nav.last_position or pos
  local moved=distance(pos,last)
  local oscillating=nav.previous_position and distance(pos,nav.previous_position)<0.005 and moved>0.005
  nav.previous_position=last; nav.last_position={x=pos.x,y=pos.y}
  -- A goal inside an entity is unreachable; stopping just beside it is what
  -- callers targeting a machine or chest want.
  local near=distance(pos,goal)<=nav.tolerance+1.5
  -- Enemy worms and spawners near the way: read while the path is asked for (avoid.lua).
  if nav.foes then M.avoid.tick(p,nav) end
  -- An attack that starts near the way on: planned again round it, as round a nest (round1950a item 1: Haiku's rearm
  -- tour walked on into attack #1550 and died). Every half second while walking a found path.
  if nav.foes and nav.path_state=='found' and not nav.direct and game.tick%30==0 then
    local z=M.avoid.attack_ahead(p,nav)
    -- An enemy group seen on the way ahead (d17 batch12 A2, Opus 00:17: a group of 7 heading for his goal was planned
    -- round and he walked on into it): the walk stops and walks away, as when hit (M.flee: the standing retreat_guard's
    -- to, else turret cover out of the groups' way, else away from it); not a walk away itself, nor retreat: false.
    local act=z and z.group and state().active[p.index]
    if act and (act.nav or act)==nav and not act.retreat_walk and not act.no_retreat and not nav.vehicle and p.character and p.character.valid then
      M.flee(p.index,p.character,{x=z.x,y=z.y},z.name,string.format('%s seen on the way ahead at %s',z.name,M.pathing.at(z)))
      return
    end
    if z then
      local f=nav.foes
      local goal,tol,mode=f.goal,f.tolerance,f.mode
      nav.attack_replan=string.format('%s at %s started on the way: planned again round it',z.name,M.pathing.at(z))
      for _,k in ipairs(M.LEG_FIELDS) do nav[k]=nil end
      nav.position=goal; nav.tolerance=tol; nav.leg=nil
      M.avoid.start(p,nav,mode); request_path(p,nav)
      p.walking_state={walking=false,direction=defines.direction.north}
      return
    end
  end
  if nav.path_state=='pending' or nav.path_state=='probing' or nav.path_state=='scanning' then
    -- The first level's belt-free twin may answer late: decide without it after a while.
    if nav.found then M.pathing.grace(p,nav) end
    if nav.path_state=='pending' or nav.path_state=='probing' or nav.path_state=='scanning' then p.walking_state={walking=false,direction=defines.direction.north}; nav.stalled=0; nav.progress_tick=nil; return end
  end
  if nav.path_state=='unreachable' then
    -- A target's reach: once, walk to a spot within it the give-up found (M.reach_spot), squeezing if it takes that;
    -- then up to M.REACH_TRIES other spots round it within reach (D8, Gemini 00:20: a transfer walk ended unreached when
    -- the one spot beside a chest had rails or pipes round it), nearest you first.
    if rt and (not nav.reach_walk or (nav.reach_tries or 0)<M.REACH_TRIES) then
      local spot,squeeze
      if not nav.reach_walk then spot,squeeze=M.reach_spot(p,nav,rt) end
      if not spot then
        spot=M.reach_ring(p,rt,nav.reach_walk and nav.reach_walk.tried or {})
        if spot then nav.reach_tries=(nav.reach_tries or 0)+1 end
      end
      if spot then
        local tried=nav.reach_walk and nav.reach_walk.tried or {}
        if nav.reach_walk then tried[#tried+1]=nav.reach_walk.to end
        local first_why=nav.reach_walk and nav.reach_walk.why or nav.why
        nav.reach_walk={from={x=pos.x,y=pos.y},to=spot,squeeze=squeeze,why=first_why,tried=tried}
        for _,k in ipairs(M.LEG_FIELDS) do nav[k]=nil end
        nav.position=spot; nav.tolerance=0.5
        if squeeze then nav.squeeze=true end
        if nav.avoid_mode and not nav.direct then M.avoid.start(p,nav,nav.avoid_mode) end
        request_path(p,nav); return
      end
    end
    -- A plain position nothing leads to (friction2: a tile inside a silo, a landing pad or a machine; Gemini's (-50,75)
    -- five times, each followed by a move_to to the spot the reply named; Haiku stood in reach already, and the exit
    -- stopped its && chain): once, walk to the spot within build reach of it the give-up found, and end arrived_near
    -- there (last.near_walk). Not closed in (the reply says what to mine), not toward a via point, not with near=false.
    local sp=nav.spot
    if not rt and not nav.near_walk and nav.near~=false and not (nav.via and nav.via.index<=#nav.via.points)
      and sp and sp.pos and not sp.none and not sp.closed and not (nav.region and nav.region.closed) then
      nav.near_walk={from={x=pos.x,y=pos.y},to={x=sp.pos.x,y=sp.pos.y},goal={x=nav.position.x,y=nav.position.y},why=nav.why,
        squeeze=(sp.searched or not sp.room) and true or nil}
      for _,k in ipairs(M.LEG_FIELDS) do nav[k]=nil end
      nav.position=nav.near_walk.to; nav.tolerance=0.5
      if nav.near_walk.squeeze then nav.squeeze=true end
      if nav.avoid_mode and not nav.direct then M.avoid.start(p,nav,nav.avoid_mode) end
      request_path(p,nav); return
    end
    return 'unreachable'
  end
  if nav.path_state=='unsafe' then
    p.walking_state={walking=false,direction=defines.direction.north}
    if M.margin_probe.tick(p,nav) then return end
    if M.unit_wait(p,nav) then return end
    return 'no_safe_route'
  end
  -- Closed in: the way out by mining, a tick after the flood (pathing.lua dig_step).
  if nav.path_state=='digging' then p.walking_state={walking=false,direction=defines.direction.north}; M.pathing.dig_step(p,nav); return end
  -- The character's own steps searched, a slice a tick (pathing.lua search_tick): a build spot, or a squeeze walk's trail.
  if nav.path_state=='searching' then p.walking_state={walking=false,direction=defines.direction.north}; M.pathing.search_tick(p,nav); return end
  -- Squeezed in: walking out along the flood's trail, then asking again (pathing.lua escape).
  if nav.path_state=='escape' then
    local wp=waypoint_goal(p,nav,nav.escape.to)
    if nav.waypoint>#nav.waypoints and distance(pos,nav.escape.to)<=0.2 then M.pathing.escaped(p,nav); return end
    nav.escape_still=moved<0.005 and (nav.escape_still or 0)+1 or 0
    if nav.escape_still>=30 then
      local at=M.pathing.at
      nav.why=string.format('squeezed in at %s: walking out toward %s stalled at %s',at(nav.escape.from),at(nav.escape.to),at(pos))
      nav.escape=nil; nav.reach=nil; nav.escape_stalled=true
      return 'blocked'
    end
    steer(p,wp,nav); return
  end
  -- squeeze=true where no path request led: the character's own steps, walked as a trail (pathing.lua squeeze_begin, walk_trail).
  if nav.path_state=='trail' then
    local wp=waypoint_goal(p,nav,goal)
    nav.trail_still=moved<0.005 and (nav.trail_still or 0)+1 or 0
    if nav.trail_still>=30 then
      local at=M.pathing.at
      nav.why=string.format('walking the gaps from %s toward %s stalled at %s',at(nav.squeezed.from),at(goal),at(pos))
      return 'blocked'
    end
    steer(p,wp,nav); return
  end
  if nav.path_state=='busy' then
    nav.retry_tick=nav.retry_tick or game.tick+20
    if game.tick>=nav.retry_tick then nav.retry_tick=nil; request_path(p,nav); return end
  end
  -- A moving train on its way over the rails a few tiles ahead: wait short of them until it has passed (M.train_guard).
  local tg,back_to=M.train_guard(p,nav,pos,goal)
  if tg=='backing' then
    -- off the rails the way it came (A5), every tick until off them
    nav.backing_to=back_to
    steer(p,back_to,nav); nav.stalled=0; nav.progress_tick=nil; nav.sidestep=nil
    return
  elseif tg then
    if nav.backing_to and M.rail_under(p,pos) then steer(p,nav.backing_to,nav); nav.stalled=0; nav.progress_tick=nil; return end
    nav.backing_to=nil
    p.walking_state={walking=false,direction=defines.direction.north}; nav.stalled=0; nav.progress_tick=nil; nav.sidestep=nil
    return
  end
  nav.backing_to=nil
  -- Flipping between two spots is a stall in disguise.
  if oscillating and near then return 'arrived_near' end
  nav.stalled=(moved<0.01 or oscillating) and (nav.stalled or 0)+1 or 0
  -- Motion is not progress: a belt carrying the character back, units shoving
  -- it, or any other jitter moves it every tick without getting closer. Count
  -- a stall when neither the waypoint nor the distance to it has improved by
  -- half a tile for PROGRESS_TICKS.
  local mark=nav.waypoint or 0
  local gap=distance(pos,waypoint_goal(p,nav,goal))
  if not nav.progress_tick or mark~=nav.progress_mark or gap<nav.progress_gap-0.5 then
    nav.progress_tick,nav.progress_mark,nav.progress_gap=game.tick,mark,gap
  elseif game.tick-nav.progress_tick>=PROGRESS_TICKS then
    nav.progress_tick=game.tick; nav.progress_gap=gap
    nav.no_progress=(nav.no_progress or 0)+1
    nav.sidestep=nil; nav.stalled=STALL_TICKS
  end
  if nav.sidestep then
    if game.tick<nav.sidestep.until_tick and nav.stalled<STALL_TICKS then
      p.walking_state={walking=true,direction=directions[compass[nav.sidestep.choice]]}; return
    end
    nav.sidestep=nil
  end
  if nav.stalled>=STALL_TICKS then
    if near then return 'arrived_near' end
    nav.stalls=(nav.stalls or 0)+1; nav.stalled=0
    if nav.stalls>(nav.max_stalls or MAX_STALLS) then
      if not nav.direct and M.pathing.escape(p,nav) then nav.stalls=0; return end
      return 'blocked'
    end
    if nav.stalls%(nav.replan_every or 3)==0 and (nav.replans or 0)<MAX_REPLANS and not nav.direct then
      -- each stall-driven replan asks for 0.15 tiles more room either side, to 0.45 (batch26 C2: stalls in a dense block)
      nav.stall_pad=math.min(0.45,(nav.stall_pad or 0)+0.15)
      nav.replans=(nav.replans or 0)+1; nav.path_level=0; request_path(p,nav); return
    end
    -- Slide around the obstacle: 90 degrees off the heading, alternating sides.
    local heading=nav.steer or 1
    local turn=nav.stalls%2==1 and 2 or -2
    nav.sidestep={choice=(heading-1+turn)%8+1,until_tick=game.tick+SIDESTEP_TICKS}
    p.walking_state={walking=true,direction=directions[compass[nav.sidestep.choice]]}
    return
  end
  local wp=waypoint_goal(p,nav,goal)
  -- The path ended short of the goal: a move_to walks the rest straight only
  -- with room to turn (Sol, shift09 03:12: that last stretch took him into the
  -- 0.6-tile gap between two assembling machines, which no path led out of).
  if nav.pocket_check and not nav.leg and wp==goal and nav.waypoints and not nav.approach then
    nav.approach=true
    local sq=not nav.squeeze and M.pathing.in_gap(p.surface,goal,M.pathing.half(p.character),nav.tolerance,p.character)
    if sq then
      nav.pocket={at={x=sq.x,y=sq.y},by=sq.by,stop={x=pos.x,y=pos.y}}
      p.walking_state={walking=false,direction=defines.direction.north}
      return 'arrived_near'
    end
  end
  steer(p,wp,nav)
end
end -- Trains (Opus, shift12 15:20: killed by our own train at (195,-150) walking to a locomotive). Every 10 ticks of a
-- walk, the next 4 tiles of its way are checked for rails (elevated rails pass overhead and are left out). A train that
-- moves and would reach them within 6 s at its speed (its path goes over one of them; a train with no path, within 30
-- tiles), or whose wagons are on them now, stops the character short of the rail until it has passed. Standing on a
-- rail already, it walks on off it. True while it waits (nav.train_wait); each wait ends in nav.train_waits, or for a
-- leg of an action that walks several (a tour, construct, pickup), in the action's train_waits (its last, at finish).
M.RAIL_TYPES={'straight-rail','half-diagonal-rail','curved-rail-a','curved-rail-b','legacy-straight-rail','legacy-curved-rail'}
M.TRAIN_TICKS,M.TRAIN_LOOK=360,4
function M.train_wait_line(w)
  if not w then return nil end
  return string.format('waiting %.0f s at (%.1f,%.1f) for %s to pass the rails ahead at (%.1f,%.1f)',(game.tick-w.since)/60,w.at.x,w.at.y,w.train,w.rails.x,w.rails.y)
end
function M.train_done(nav)
  local w=nav.train_wait
  if not w then return false end
  nav.train_wait=nil
  local a=w.index and state().active[w.index]
  local into=(a and a~=nav and a.nav==nav) and a or nav
  into.train_waits=into.train_waits or {}
  if #into.train_waits<4 then
    into.train_waits[#into.train_waits+1]=string.format('waited %.1f s at (%.1f,%.1f) for %s to pass the rails ahead at (%.1f,%.1f)%s',
      (game.tick-w.since)/60,w.at.x,w.at.y,w.train,w.rails.x,w.rails.y,w.backed and string.format(', backing off the rails to (%.1f,%.1f)',w.backed.x,w.backed.y) or '')
  end
  return false
end
-- A ground rail under the character: one whose footprint meets the character's box (an area find follows a rail's
-- own oriented footprint; a radius find only meets rails whose centre is near, a copy of world n: a character on a
-- half-diagonal rail between two centres met none).
-- pad: that much more round the box (a step-off spot, which the walk stops within 0.3 of).
function M.rail_under(p,pos,pad)
  local h=M.pathing.half(p.character)+(pad or 0)
  return p.surface.find_entities_filtered{area={{pos.x-h,pos.y-h},{pos.x+h,pos.y+h}},type=M.RAIL_TYPES,limit=1}[1]
end
-- Standing on a ground rail at the end of a walk: the rail, as the guard finds one underfoot.
M.WALK_KINDS={move_to=true,gather=true,construct=true,pickup=true,repair=true}
function M.on_rails(p)
  if not (p and p.valid and p.character and p.character.valid) then return nil end
  local r=M.rail_under(p,p.position)
  return r and string.format('you stand on %s (%g,%g)',r.name,r.position.x,r.position.y) or nil
end
function M.train_guard(p,nav,pos,goal)
  if game.tick%10~=0 then return nav.train_wait~=nil end
  local s=p.surface
  -- The way ahead: TRAIN_LOOK tiles along the waypoints (or straight to the goal).
  local pts,left,at={{x=pos.x,y=pos.y}},M.TRAIN_LOOK,pos
  local list,i=nav.waypoints,nav.waypoint or 1
  while left>0 do
    local nxt=list and list[i] and list[i].position or goal
    if not nxt then break end
    local d=distance(at,nxt)
    if d>=left then
      local f=left/math.max(d,1e-6)
      pts[#pts+1]={x=at.x+(nxt.x-at.x)*f,y=at.y+(nxt.y-at.y)*f}
      break
    end
    pts[#pts+1]={x=nxt.x,y=nxt.y}; left=left-d; at=nxt
    if not (list and list[i]) then break end
    i=i+1
  end
  local x0,y0,x1,y1=pos.x,pos.y,pos.x,pos.y
  for _,q in ipairs(pts) do x0=math.min(x0,q.x); y0=math.min(y0,q.y); x1=math.max(x1,q.x); y1=math.max(y1,q.y) end
  local rails=s.find_entities_filtered{area={{x0-1,y0-1},{x1+1,y1+1}},type=M.RAIL_TYPES,limit=16}
  -- Standing on a rail (d17 batch14 A5, Opus: killed by our own train at (383,-288) on a double track: on the first
  -- track the check was off and the walk went on onto the second as a train came): the rails underfoot count too, and
  -- with a train coming the character goes back to where it last stood off the rails (backing), then waits there.
  local under=M.rail_under(p,pos)
  if not under then nav.offrail={x=pos.x,y=pos.y} end
  if #rails==0 then return M.train_done(nav) end
  local under_set={}
  if under then
    local h=M.pathing.half(p.character)
    for _,r in ipairs(s.find_entities_filtered{area={{pos.x-h,pos.y-h},{pos.x+h,pos.y+h}},type=M.RAIL_TYPES,limit=8}) do under_set[r.unit_number or (r.position.x..','..r.position.y)]=true end
  end
  local ahead,cx,cy,n={},0,0,0
  for _,r in ipairs(rails) do
    local k=r.unit_number or (r.position.x..','..r.position.y)
    if not under_set[k] then ahead[k]=true; cx,cy,n=cx+r.position.x,cy+r.position.y,n+1 end
  end
  -- only the rails underfoot: walk on off them
  if n==0 then return M.train_done(nav) end
  local crossing={x=cx/n,y=cy/n}
  local okt,trains=pcall(function() return game.train_manager.get_trains{surface=s} end)
  local danger
  for _,t in ipairs(okt and trains or {}) do
    local speed=math.abs(t.speed)
    if t.valid and speed>0.001 then
      -- Its nearest wagon to the rails ahead.
      local near,nd
      for _,c in ipairs(t.carriages) do
        local d=distance(c.position,crossing)
        if not nd or d<nd then near,nd=c,d end
      end
      local eta=nd and nd/speed
      if near and (nd<=4 or eta<=M.TRAIN_TICKS) then
        local over=nd<=4
        local path=not over and t.path
        if path then
          local okp=pcall(function()
            for k=path.current,math.min(path.size,path.current+300) do
              local r=path.rails[k]
              if r and r.valid and ahead[r.unit_number or (r.position.x..','..r.position.y)] then over=true; break end
            end
          end)
          if not okp then over=nd<30 end
        elseif not over then over=nd<30 end
        if over and (not danger or eta<danger.eta) then danger={stock=near,eta=eta,speed=speed} end
      end
    end
  end
  if not danger then return M.train_done(nav) end
  -- Standing on a rail (d17 batch14 A5, Opus: killed by our own train at (383,-288) on a double track: on the first
  -- track the check was off and the walk went on onto the second as a train came) with a train coming over the rails
  -- ahead: back to where it last stood off the rails (within 8 tiles), then wait there; none known: walk on off them.
  if under and not (nav.offrail and distance(pos,nav.offrail)<=8) then return M.train_done(nav) end
  if not nav.train_wait then
    local st=danger.stock
    nav.train_wait={since=game.tick,at={x=pos.x,y=pos.y},rails=crossing,index=p.index,
      train=string.format('a train (%s at (%.0f,%.0f), %.0f km/h)',st.name,st.position.x,st.position.y,danger.speed*216)}
  end
  if under then
    nav.train_wait.backed=nav.train_wait.backed or {x=nav.offrail.x,y=nav.offrail.y}
    return 'backing',nav.offrail
  end
  return true
end
-- Route planners take only tiles the piece stands on as they are (or on a tile ghost ordered there), and a
-- route with no way says what tiles the straight line crosses (dryrun.lua; Sol, shift09: poles on Gleba wetland).
do
  local tiles={stands_fn=function(...) return M.dryrun.stands_fn(...) end,line_tiles=function(...) return M.dryrun.line_tiles(...) end}
  -- belt_route also passes trees, rocks and wild plants (marked when placed) and, with landfill, water and wetland
  route=route_module{position=position,directions=directions,chunk_of=chunk_of,tiles=tiles,
    route_guard=function(...) return M.avoid.route_guard(...) end,
    tile_info=function(...) return M.dryrun.tile_info(...) end,only_obstacles=function(...) return construction.only_obstacles(...) end}
  pipes=pipes_module{position=position,directions=directions,chunk_of=chunk_of,tiles=tiles}
end
-- Tiles mined by hand (tilemine.lua; Sol, operator 15:30): mine {tiles: true}, and construct's tile deconstruction orders.
M.tilemine=require('tilemine'){position=position,integer=integer,charted=charted,
  -- its walks into reach keep out of the enemy reach the map shows, as move_to's (round1950a)
  request_path=function(p,nav)
    if not nav.foes and not nav.avoid_mode then nav.avoid_mode=M.avoid.mode(nil); M.avoid.start(p,nav,nav.avoid_mode) end
    return request_path(p,nav)
  end,navigate=function(p,nav) return navigate(p,nav) end,
  stop_walking=function(p) p.walking_state={walking=false,direction=defines.direction.north} end,
  -- walking by default within 32 tiles, the call that walks (autowalk.lua); the enemy check of the walk's goals and legs
  autowalk=M.autowalk,avoid_mode=function(v) return M.avoid.mode(v) end,avoid_start=function(p,nav,mode) return M.avoid.start(p,nav,mode) end,
  leg_done=function(p,nav,outcome) return M.avoid.leg_done(p,nav,outcome) end,goal_inside=function(p,goal,mode) return M.avoid.inside(p,goal,mode) end,
  goal_text=function(label,goal,c) return M.avoid.goal_text(label,goal,c) end}
construction=construction_module{position=position,distance=distance,integer=integer,visible=visible,steer=steer,real=real,
  known=known,reason=reason,directions=directions,waypoint_goal=waypoint_goal,
  request_path=function(p,nav) return request_path(p,nav) end,navigate=function(p,nav) return navigate(p,nav) end,
  build=function(p,a) return handlers.build(p,a) end,hand_mining_ticks=hand_mining_ticks,crafting_count=crafting_count,
  tilemine=M.tilemine,
  -- construct's walks keep move_to's enemy checks (C2)
  avoid_mode=function(v) return M.avoid.mode(v) end,avoid_start=function(p,nav,mode) return M.avoid.start(p,nav,mode) end,
  leg_done=function(p,nav,outcome) return M.avoid.leg_done(p,nav,outcome) end,goal_inside=function(p,goal,mode) return M.avoid.inside(p,goal,mode) end,
  margin_discs=function(p,point,mode,R) return M.avoid.margin_discs(p,point,mode,R) end}
do local function blocked_product(p,action)
  for _,name in ipairs(action.products or {}) do
    if not p.can_insert{name=name} then return name end
  end
end
-- The nearest visible enemy within the shot's radius, rescanned every 6
-- ticks (cached per agent): auto shoot on foot and in a vehicle.
function M.combat_scan(p,action,index,tick)
  local cached=combat_targets()[index]
  if not cached or tick>=(cached.next_scan or 0) then
    local enemies={}
    for _,force in pairs(game.forces) do
      if force~=p.force and force.name~='neutral' and not p.force.get_friend(force) and not p.force.get_cease_fire(force) then enemies[#enemies+1]=force end
    end
    local best=action.radius+1
    cached={next_scan=tick+6}
    if #enemies>0 then
      for _,e in pairs(p.surface.find_entities_filtered{position=p.position,radius=action.radius,force=enemies,limit=256,type={'unit','spider-unit','segmented-unit','unit-spawner','turret','ammo-turret','electric-turret','character'}}) do
        local d=distance(p.position,e.position)
        if e.valid and visible(p,e.position) and d<best then best=d; cached.entity=e end
      end
    end
    combat_targets()[index]=cached
  end
  local e=cached.entity
  if e and e.valid and distance(p.position,e.position)<=action.radius and visible(p,e.position) then return e end
end
-- Operator measurement (profile_ticks): the harness tick's own cost, timed
-- with LuaProfiler and written to the log. Module state on purpose: it never
-- touches game state, and profiler readings differ between machines anyway.
local profiling
function M.tick(event)
  if not profiling then return M.tick_body(event) end
  local timer=helpers.create_profiler()
  M.tick_body(event)
  timer.stop(); profiling.total.add(timer); profiling.left=profiling.left-1
  if profiling.left==0 then
    profiling.total.divide(profiling.n)
    log({'','agent-harness tick average over ',profiling.n,' ticks (',#M.bots.list(),' bots, ',table_size(state().active),' active actions): ',profiling.total})
    profiling=nil
  end
end
-- One running action's tick (M.tick_body).
function M.tick_action(index,action,event)
  local ok,p=pcall(player,index,action.kind=='drive')
  -- Read a due silo sample before testing the deadline: a part arriving on
  -- that tick can extend the idle window, but never the absolute give-up.
  local silo_ready
  if ok and action.await_silo and event.tick>=action.next_check
    and event.tick<=(action.await_silo.give_up or action.until_tick) then
    silo_ready=M.feed_ready(p,action)
  end
  if not ok then
    finish(index,'player_unavailable')
  elseif action.retreat and event.tick%5==0 and M.retreat_due(index,p,action) then
    -- Hurt below its retreat (retreat.lua): it goes back after this loop.
  elseif (action.kind=='wait_ticks' or action.kind=='wait_until') and not action.queued and action.start_tick and action.wake_messages~=false
    and event.tick%30==0 and (M.board.inbox_tick(index,action.wake_viewers,action.wake_filter) or -1)>=action.start_tick then
    -- A tell or mention ends a direct wait (agent-minds study, fix 5: agents
    -- moved to waits nobody could interrupt; Grok chose wait_until for that);
    -- a viewer's @mention only one started with wake_on_viewers (board.lua).
    local _,kind,from=M.board.inbox_tick(index,action.wake_viewers,action.wake_filter)
    action.told=from and kind..' by '..from or kind
    finish(index,kind)
  elseif (action.kind=='wait_ticks' or action.kind=='wait_until') and not action.queued and action.start_tick and event.tick%30==19
    and state().spiderroute and M.spiderroute.since(M.board.who(p),action.start_tick) then
    -- (d24 batch189 addendum) a spidertron of ours retreated (spiderroute.lua): last.why says it
    action.told=M.spiderroute.since(M.board.who(p),action.start_tick)
    finish(index,'spidertron_retreated')
  elseif (action.kind=='wait_ticks' or action.kind=='wait_until') and not action.queued and action.urgent and event.tick%60==0
    and M.urgent.waking(p,action) then
    -- An urgent alert ends a direct wait as it ends a sleep (urgent.lua; last.why names it).
    finish(index,'urgent')
  elseif event.tick>action.until_tick and action.kind=='wait_until' and action.default_timeout and M.waiteta.extend(action,action.condition,action.start_tick) then
    action.until_tick=M.waiteta.extend(action,action.condition,action.start_tick)
  elseif event.tick>action.until_tick then
    finish(index,(action.kind=='move_to' or action.kind=='build_path' or action.kind=='construct' or (action.kind=='mine' and action.tiles) or action.kind=='kite' or action.kind=='feed' or action.kind=='gather' or action.kind=='wait_until' or action.kind=='drive' or action.area~=nil or (action.kind=='repair' and action.targets~=nil)) and 'timed_out' or 'duration_elapsed')
  elseif action.kind=='wait_until' then
    if event.tick>=action.next_check then
      action.next_check=event.tick+FEED_CHECK
      local ok,met,saw=pcall(M.waiteta.check,p,action.condition,action)
      action.saw=ok and saw or nil
      if not ok then action.error=reason(met); finish(index,'failed')
      elseif met then finish(index,'met') end
    end
  elseif action.kind=='walk' then
    p.walking_state={walking=true,direction=action.direction}
  elseif action.kind=='move_to' then
    M.trail_point(action,p.position)
    local outcome=navigate(p,action)
    -- Legs around enemies (avoid.lua): the next one starts where one ends.
    if outcome and action.foes and M.avoid.leg_done(p,action,outcome) then outcome=nil end
    -- Legs through via points: the next one starts where one arrives.
    if outcome and action.via then
      local nxt,instead=M.via_next(p,action,outcome,index)
      if nxt then outcome=nil elseif instead then outcome=instead end
    end
    -- An end that says arrived far from the walk's goal is no arrival (A1): stopped_short, with where and why.
    if outcome=='arrived' or outcome=='arrived_near' then outcome=M.short_check(p,action,outcome) end
    if outcome then
      finish(index,outcome)
      -- A walk into reach for a call (autowalk.lua): the call, made on arrival.
      if action.then_call then M.autowalk.resume(index,p,action) end
      -- mine_out: the blockers it named, mined by hand, then the walk again (M.mine_out_start).
      if action.mine_out and action.mine_list and outcome~='arrived' and outcome~='arrived_near' then M.mine_out_start(index,p,action) end
    end
  elseif action.kind=='build_path' then
    local outcome=construction.tick(p,action)
    if outcome then finish(index,outcome) end
  elseif action.kind=='kite' then
    local outcome=kite.tick(p,action,event.tick)
    if outcome then finish(index,outcome) end
  elseif action.kind=='drive' then
    local outcome=M.vehicles.tick(p,action)
    if outcome then finish(index,outcome) end
  elseif action.kind=='construct' then
    local outcome=construction.tick_ghosts(p,action)
    if outcome then
      finish(index,outcome)
      if action.then_move and (outcome=='constructed' or outcome=='nothing_to_do') then
        local ok,err=pcall(handlers.move_to,p,action.then_move)
        if not ok and state().last[index] then state().last[index].walk_again_error=reason(err) end
      end
    end
  elseif action.kind=='mine' and action.tiles then
    local outcome=M.tilemine.tick(p,action)
    if outcome then finish(index,outcome) end
  elseif action.kind=='gather' then
    local outcome
    if action.fuel_round then outcome=M.fuelround.tick(p,action) else outcome=stock.tick(p,action) end
    if action.queued and action.marked_index~=action.index then pcall(M.tour_mark,index,action) end
    if outcome then finish(index,outcome) end
  elseif action.kind=='feed' then
    -- A build stepping aside walks until the character is off the footprint.
    if action.aside and construction.in_box(p.position,action.aside.box) then steer(p,action.aside.to,action)
    elseif event.tick>=action.next_check then
      if action.aside then stop(p); action.aside=nil end
      action.next_check=event.tick+FEED_CHECK
      if silo_ready or (not action.await_silo and M.feed_ready(p,action)) then
        action.awaiting_craft=nil
        action.running=true
        local ok,result=pcall(handlers[action.handler],p,action.args)
        action.running=nil
        if ok then action.result=result else action.error=reason(result) end
        -- A later batch entry stepping aside installed a new action: keep it.
        if state().active[index]==action then finish(index,ok and 'fed' or 'failed') end
      end
    end
  elseif action.kind=='pickup' and action.belt then
    local outcome=M.beltpick.tick(p,action,event.tick)
    if outcome then finish(index,outcome) end
  elseif action.kind=='pickup' and action.area then
    local outcome=M.ground.tick(p,action,event.tick)
    if outcome then finish(index,outcome) end
  elseif action.kind=='clear_cliffs' then
    local outcome=M.capsules.tick_cliffs(p,action,event.tick)
    if outcome then finish(index,outcome) end
  elseif action.kind=='pickup' then
    -- One item stack every 6 ticks; done when none is left in reach. No
    -- picking_state: the engine's own pickup would go uncounted in picked.
    if event.tick>=(action.next_pick or 0) then
      action.next_pick=event.tick+6
      local item=p.surface.find_entities_filtered{position=p.position,radius=action.reach or 1,type='item-entity',limit=1}[1]
      if not (item and item.valid and item.stack and item.stack.valid_for_read) then finish(index,action.picked and 'picked_up' or 'nothing_in_reach')
      else
        local name,count=item.stack.name,item.stack.count
        local q=item.stack.quality and item.stack.quality.name or nil
        local n=p.insert{name=name,count=count,quality=q}
        if n==0 then finish(index,'inventory_full')
        else
          action.picked=action.picked or {}; action.picked[name]=(action.picked[name] or 0)+n
          action.trashed=M.trash.count(p,action.trashed,name,q,n)
          if n>=count then item.destroy() else item.stack.count=count-n end
        end
      end
    end
  elseif action.kind=='repair' and action.targets then
    -- positions or area: the next damaged target once this one is full or gone; walk to one out of reach.
    while action.entity and M.repair_done(action.entity) do M.repair_next(p,action) end
    local e=action.entity
    if not e then finish(index,'repair_completed')
    elseif not p.can_reach_entity(e) then
      if not action.nav then
        action.nav={position=e.position,tolerance=math.max(1,(p.reach_distance or 10)-3),max_stalls=6,replans=0,stalled=0,last_position=p.position}
        request_path(p,action.nav)
      end
      if navigate(p,action.nav) then
        action.unreached=action.unreached+1; action.entity=nil
        p.walking_state={walking=false,direction=defines.direction.north}
        M.repair_next(p,action)
      end
    elseif not p.cursor_stack.valid_for_read or p.cursor_stack.prototype.type~='repair-tool' then finish(index,'repair_tool_exhausted')
    else
      if action.nav then action.nav=nil; p.walking_state={walking=false,direction=defines.direction.north} end
      action.working=true
      if M.bots.is(p) then M.bots.repair(p,e)
      else
        if p.selected~=e then p.selected=e end
        if not p.repair_state.repairing then p.repair_state={repairing=true,position=e.position} end
      end
    end
  elseif action.kind=='repair' then
    local e=action.entity
    if not e or not e.valid then finish(index,'target_lost')
    elseif not p.can_reach_entity(e) then finish(index,'out_of_reach')
    elseif e.health>=e.max_health then finish(index,'repair_completed')
    elseif not p.cursor_stack.valid_for_read or p.cursor_stack.prototype.type~='repair-tool' then finish(index,'repair_tool_exhausted')
    else
      -- Reassigning selection/state every tick fights the client's cursor
      -- hover and makes the selection box flash; only correct drift.
      if M.bots.is(p) then M.bots.repair(p,e)
      else
        if p.selected~=e then p.selected=e end
        if not p.repair_state.repairing then p.repair_state={repairing=true,position=e.position} end
      end
    end
  elseif action.kind=='mine' then
    local e=action.entity
    -- Timed mining only finishes through mine_entity; a vanished target was
    -- taken by something else (a bot, a biter, another player).
    if not e or not e.valid then finish(index,action.done_tick and 'target_lost' or 'target_mined')
    elseif not p.can_reach_entity(e) then
      -- Walked or pushed off mid-mine: the same words as a refused mine.
      local ok,why=pcall(M.out_of_reach,p,e); action.error=ok and why or nil
      finish(index,'out_of_reach')
    elseif action.done_tick then
      if event.tick>=action.done_tick then
        local okh,holds=pcall(M.grids.mining_line,e)
        -- (d23 batch123 CF2) as it stood, for a running watch it was in (mixed.lua)
        local okd,was=pcall(function() return M.mixed.watches() and M.mixed.describe(e) end)
        if M.bots.mine(p,e) then
          action.holds=okh and holds or nil
          if okd and was then pcall(M.mixed.edit,was,'mined by '..M.board.who(p),true) end
          finish(index,'target_mined')
        else
          -- The engine refuses for two reasons: no room for the products,
          -- or an entity that cannot be mined by hand (a stump or remnant).
          action.blocked_item=blocked_product(p,action)
          if action.blocked_item or e.valid and e.type=='character-corpse' then finish(index,'inventory_full')
          else action.error='the engine refused to mine '..e.name..' (not hand-minable: a stump, remnant or corpse; it does not block building, or deconstruct it)'; finish(index,'not_minable') end
        end
      end
    elseif blocked_product(p,action) then
      -- The engine silently idles a character whose output has no room.
      action.blocked_item=blocked_product(p,action); finish(index,'inventory_full')
    elseif action.next_mine and event.tick>=action.next_mine then
      -- mine_entity on a resource takes one unit and returns false while
      -- the tile has ore left, so judge success by the amount.
      local before=e.amount
      local name=e.name
      p.mine_entity(e,false)
      if not e.valid then
        action.mined=action.mined+1
        -- count: the next tile of the same resource in reach, nearest first (mine_count_next).
        local nxt=action.count and action.mined<action.count and M.mine_count_next(p,name)
        if action.count and action.mined>=action.count then finish(index,'mined')
        elseif nxt then action.entity=nxt; action.next_mine=event.tick+action.cycle
        else
          if action.count then action.why=string.format('mined %d of %d: no %s left in reach',action.mined,action.count,name) end
          finish(index,'target_mined')
        end
      elseif e.amount<before then
        action.mined=action.mined+1; action.next_mine=event.tick+action.cycle
        if action.count and action.mined>=action.count then finish(index,'mined') end
      else action.blocked_item=blocked_product(p,action); finish(index,'inventory_full') end
    end
  end
  if ok and state().active[index]==action then watch(p,action) end
end
-- A carried action this runtime could not run or end (carry.lua): it ends (failed when its tick raised, else with the
-- outcome it ended with), saying why, and the tick goes on.
function M.carry_failed(index,action,err,outcome)
  local s=state()
  local why=reason(err)
  if log then log('agent-harness: '..tostring(action.kind)..' carried over a harness update failed for player '..tostring(index)..': '..tostring(err)) end
  if s.active[index]~=action then return end
  s.active[index]=nil
  s.last=s.last or {}
  s.last[index]={kind=action.kind,outcome=outcome or 'failed',tick=game.tick,
    error=outcome and 'carried over a harness update; this runtime could not report how it ended: '..why
      or 'carried over a harness update; this runtime could not run it: '..why}
  pcall(stop,body(M.lookup(index)))
  local head=string.format('harness updated at tick %s: your %s carried over',tostring(action.carried),M.carry.called(action))
  M.carry.note(index,outcome and string.format('%s and ended %s at tick %d; this runtime could not report the rest (%s)',head,outcome,game.tick,why)
    or string.format('%s, then stopped at tick %d: this runtime could not run it (%s); start it again if it is still needed',head,game.tick,why))
end
function M.tick_body(event)
  M.carry.carry()
  idle_tick()
  M.research.tick(event.tick)
  M.bots.tick(event.tick)
  M.drops.tick(event.tick)
  M.drop_jobs_tick(event.tick)
  M.nametags.tick(event.tick)
  pcall(M.networks.tick,event.tick)  -- the networks' samples never stop the harness tick
  pcall(M.fusion.tick,event.tick)  -- fusion reactors' fuel, sampled for those read (fusion.lua)
  pcall(M.pushalerts.tick,event.tick)  -- the alert read, one stage a tick (task-statuscost)
  pcall(survey.tick,event.tick)  -- status's factory survey, a slice a tick (task-statuscost)
  pcall(threat.tick,event.tick)  -- the chart sweep, a slice a tick (task-statuscost)
  pcall(M.census.tick,event.tick)  -- the host reads' counts, a band or slice a step (census.lua)
  if M.netmap then pcall(M.timed,'netmap.tick',M.netmap.tick,event.tick) end
  if M.platdefense and M.platdefense.tick then pcall(M.timed,'platdefense.tick',M.platdefense.tick,event.tick) end  -- planned hulls' sides, a chunk or a slice a tick (platdefense.lua)  -- the live map's networks, a slice a step (netmap.lua)
  if M.seeds then pcall(M.timed,'seeds.tick',M.seeds.tick,event.tick) end  -- seed loops running out (seeds.lua)
  if M.floorcheck then pcall(M.timed,'floorcheck.tick',M.floorcheck.tick) end  -- foundation checks across ticks (floorcheck.lua)
  if M.floorphases then pcall(M.timed,'floorphases.tick',M.floorphases.tick) end  -- floor plans across ticks (floorphases.lua)
  if M.platplan and M.platplan.tick then pcall(M.timed,'platplan.tick',M.platplan.tick) end  -- platform_plan support jobs, a slice a tick (platplan.lua)
  if M.ghosttally then pcall(M.timed,'ghosttally.tick',M.ghosttally.tick) end  -- platform ghost tallies across ticks (ghosttally.lua)
  pcall(M.platwait.tick,event.tick)  -- stop waits the harness keeps for platforms, every second (platwait.lua)
  if M.ammofeed then pcall(M.timed,'ammofeed.step',M.ammofeed.step) end  -- a large platform's ammunition trace, read over ticks (ammofeed.lua)
  -- (d19 batch45: 8-14 ms in the first call after a load) the argument sets check_args builds from describe
  if not allowed_args then pcall(check_args,'describe',{}) end
  -- the kept belt alert groups of each force a reply asked for (after a load, the player force's), read again every 120
  -- ticks (d19 batch45)
  if event.tick%120==60 then for name in pairs(M.belt_groups_kept or {player=true}) do if game.forces[name] then pcall(M.belt_groups_read,game.forces[name]) end end end
  pcall(M.chronicle.tick,event.tick)  -- the chronicle's events: research, launches, platform stops and platforms made
  pcall(M.ground.watch_tick,event.tick)  -- items on the ground for status alerts and reply hints, a band or a pile a step
  pcall(M.scienceline.tick,event.tick)
  M.powercut.tick(event.tick)  -- a pole death's check and trace, a stage a tick (never raises)
  if M.burnerfuel then M.burnerfuel.tick(event.tick) end  -- hand-fed burners running dry (never raises)
  if state().turret_deaths then pcall(M.turretammo.tick,event.tick) end  -- ammo requests on the ghosts of turrets that died
  M.ores.tick()  -- queued chunks of an ore survey, a few a tick (never raises)
  if event.tick%600==0 then pcall(M.avoid.prune) end  -- enemy chunk records older than a minute (avoid.lua)
  if event.tick%60==0 and space then pcall(space.watch_stops,event.tick) end  -- when each platform stopped (space.lua stops)
  if event.tick%60==0 and M.freight then pcall(M.timed,'freight.tick',M.freight.tick,event.tick) end
  -- (d22 batch96 BF1) the platforms read lately: their belts and inserter hands, a band every few ticks (freight.lua)
  if M.freight and M.freight.belt_tick and event.tick%M.freight.BELT_STEP==0 then pcall(M.timed,'freight.belts',M.freight.belt_tick,event.tick) end
  if M.platalerts and M.platalerts.tick and event.tick%M.platalerts.SCAN_STEP==0 then pcall(M.timed,'platalerts.scan',M.platalerts.tick,event.tick) end
  -- platform_bom requests kept to the ghosts' need (A6)
  if event.tick%600==23 and M.owed then pcall(M.timed,'owed.tick',M.owed.tick) end  -- unanswered mentions' reminders
  if M.platbom and M.platbom.watch then pcall(M.platbom.watch) end  -- the platform_bom request lowered as the hub spends (A3)
  if event.tick%600==17 and M.platbom then pcall(M.timed,'platbom.tick',M.platbom.tick,event.tick) end  -- each hub's items by stop and leg (freight.lua)
  if M.research_target then pcall(M.timed,'research_target.tick',M.research_target.tick,event.tick) end  -- research target levels (researchtarget.lua)
  if event.tick%3600==61 and M.lessonbook then pcall(M.timed,'lessonbook.tick',M.lessonbook.tick) end  -- lesson checks, surfacings (lessonbook.lua)
  if event.tick%120==65 and M.turretwatch then pcall(M.timed,'turretwatch.tick',M.turretwatch.tick) end  -- turret ghosts' targeting once built
  if event.tick%120==53 and M.progress then pcall(M.timed,'progress.tick',M.progress.tick) end  -- owned board items' checks (progress.lua)
  if event.tick%120==41 and M.shipment then pcall(M.timed,'shipment.tick',M.shipment.tick) end
  if event.tick%60==37 and M.spiderroute then pcall(M.timed,'spiderroute.tick',M.spiderroute.tick) end  -- spidertrons sent by go_to (spiderroute.lua)
  if event.tick%30==19 and M.spiderroute and state().spiderroute then pcall(M.timed,'spiderroute.guard_tick',M.spiderroute.guard_tick) end  -- their retreat guards (QAE1)
  if event.tick%60==23 and M.delivwatch then pcall(M.timed,'delivwatch.tick',M.delivwatch.tick,event.tick-23) end  -- delivery watches (delivwatch.lua)  -- shipment fact lines (shipment.lua)
  if state().ammo_reserve then pcall(M.timed,'ammoreserve.tick',M.ammoreserve.tick,event.tick) end  -- platform_ammo_below's readings (ammoreserve.lua): a band a step while a pass runs
  if state().flightwatch and M.flightwatch.due(event.tick) then pcall(M.timed,'flightwatch.tick',M.flightwatch.tick,event.tick) end  -- flight watches (flightwatch.lua): a read a second each, on its own tick of the second (BS1)
  if M.delivwatch then pcall(M.delivwatch.pod_tick,event.tick) end  -- (AB7) watched pods read each tick near landing; none followed: one lookup
  if event.tick%60==30 and M.launchwatch then pcall(M.timed,'launchwatch.tick',M.launchwatch.tick) end  -- launches waiting while their platform leaves (launchwatch.lua)
  if event.tick%60==0 and M.pods then pcall(M.pods.tick,event.tick) end  -- cargo pods leaving our platforms (pods.lua)
  do local pa=state().podlog; if pa and pa.after and next(pa.after) then pcall(M.timed,'podlog.tick',M.podlog.tick,event.tick) end end  -- (d24 batch179) a pod's delivery read the tick after (podlog.lua)
  if event.tick%60==17 and state().endurance_readings then pcall(M.timed,'endurance.refresh',M.endurance.tick,event.tick) end  -- (batch195) drops batch187's kept platform_endurance readings once; none are kept now
  if M.beltsample and state().belt_flow then pcall(M.timed,'beltsample.tick',M.beltsample.tick,event.tick) end  -- belt_flow samplers (beltsample.lua): none, nothing read
  if state().turret_tally then pcall(M.timed,'turret_tally.tick',M.turrettally.tick,event.tick) end
  if state().signal_watch then pcall(M.timed,'signal_watch.tick',M.signalwatch.tick,event.tick) end  -- (PL1) signal_watch: a get_signal per signal every 60 ticks
  -- (d24 batch144 cp2) a ghost record log from before the position index: 512 ring slots a tick until it is whole
  if state().ghost_log and not state().ghost_log.pidx_done then pcall(M.timed,'ghostlog.index',M.ghostlog.index_tick,M.ghostlog.INDEX_SLICE) end
  if state().asteroid_watch then pcall(M.timed,'asteroid_watch.tick',M.asteroidwatch.tick,event.tick) end  -- (AR1) asteroid_watch: a read every 15 ticks
  if state().collector_tally then pcall(M.timed,'collector_tally.tick',M.collectreach.tick,event.tick) end  -- (AN2) collector_tally watches: a read every 10 ticks  -- turret_tally watches (turrettally.lua): a read a second
  if state().uptime then pcall(M.timed,'uptime.tick',M.uptime.tick,event.tick) end  -- uptime watches (uptime.lua): each job's samples at a moving phase
  if event.tick%60==45 and M.landed then pcall(M.landed.tick,event.tick-45) end  -- landed pods on the ground: a slice of the sweep a second (landed.lua)
  -- (after pods.lua's look: freight takes the new pods from it and counts each on its stop)
  if event.tick%60==0 and M.freight then pcall(M.timed,'freight.pod_tick',M.freight.pod_tick,event.tick) end  -- the cargo pods leaving hubs at stops
  if event.tick%120==47 and state().built_watch then pcall(M.built_tick) end  -- new builds not working (B2)
  if event.tick%60==13 and state().clear_jobs then pcall(M.clearobs.tick) end  -- clear_obstacles waits (clearobs.lua)
  if event.tick%600==29 then pcall(M.timed,'hubfull.tick',M.hubfull.tick,event.tick) end  -- a hub too full for its payload (hubfull.lua)
  if event.tick%60==37 and state().artillery_checks then pcall(M.artillery.tick) end  -- a flare's shot confirmed (artillery.lua)
  if event.tick%60==41 and state().decon_went then pcall(M.deconwent.tick) end  -- where a deconstructed item went (deconwent.lua)
  if event.tick%60==0 and M.engine then pcall(M.engine.tick,event.tick) end  -- each platform's speed, fluids and pumps
  if M.engine then pcall(M.engine.pump_tick,event.tick) end  -- its pumps once a second at a moving phase (engine.lua)
  -- The egg watch, a bounded stage a tick (spoil.lua); a fault is counted, never stops the tick.
  do
    local ok,err=pcall(M.spoil.tick,event.tick)
    if not ok then local s=state(); s.spoil_errors={count=((s.spoil_errors or {}).count or 0)+1,last=tostring(err),tick=event.tick} end
  end
  M.seated_ok=nil
  for index,action in pairs(state().active) do
    -- One carried over a harness update runs guarded: a shape this runtime does not expect ends it, never the tick (carry.lua).
    if action.carried then
      local ok,err=pcall(M.tick_action,index,action,event)
      if not ok then M.carry_failed(index,action,err) end
    else M.tick_action(index,action,event) end
  end
  for index,action in pairs(state().combat or {}) do
    -- Vehicle fire runs seated (vehicles.lua); the rest needs the character on foot.
    local ok,p=pcall(player,index,action.vehicle~=nil)
    if not ok or event.tick>action.until_tick then stop_combat(index,ok and (action.end_outcome or 'duration_elapsed') or 'player_unavailable')
    elseif action.retreat and event.tick%5==0 and M.retreat_due(index,p,action) then
      -- Hurt below its retreat (retreat.lua): it goes back after this loop.
    elseif action.vehicle then
      local aim=combat_targets()[index]
      local fixed=aim and aim.fixed
      if fixed and not fixed.valid then stop_combat(index,'target_destroyed')
      else
        local aimed=fixed or (action.auto and M.combat_scan(p,action,index,event.tick)) or nil
        if aimed then action.fired_tick=event.tick end
        local outcome=M.vehicles.combat_tick(p,action,aimed)
        if outcome then stop_combat(index,outcome) end
      end
    elseif action.ammo_start and kite.ammo_count(p)==0 and not kite.reload(p,action) then stop_combat(index,'out_of_ammo')
    else
      if event.tick%10==0 then pcall(M.combat_reload,p,action) end
      local target=action.position
      if action.auto then
        local e=M.combat_scan(p,action,index,event.tick)
        if e then target=e.position end
        -- (area ammunition: no shot at a target whose blast reaches ours; held_blast says the last such)
        if e and action.blast and not action.fire_anyway then
          local okh,hit=pcall(M.blast_hits,p,e.position,action.blast.radius)
          if okh and hit then
            target=nil; e=nil
            action.held_blast=string.format('held fire at %s: %s',action.blast.ammo,hit.line); action.held_blast_n=(action.held_blast_n or 0)+1
          end
        end
        target=M.melee_guard(p,action,target,event.tick)
        if e and target then action.fired_tick=event.tick end
      elseif target then
        target=M.melee_guard(p,action,target,event.tick)
        if target then action.fired_tick=event.tick end
      end
      p.shooting_state={state=target and defines.shooting.shooting_enemies or defines.shooting.not_shooting,position=target or p.position}
    end
  end
  -- Retreats due this tick: the actions end and the agents go back (outside the loops over the tables they change).
  if M.retreat_pending then
    local list=M.retreat_pending
    M.retreat_pending=nil
    for _,r in ipairs(list) do
      local okr,err=pcall(M.retreat_go,r)
      if not okr then local st=state(); st.retreat_errors={count=((st.retreat_errors or {}).count or 0)+1,last=tostring(err),tick=game.tick} end
    end
  end
  -- Calls due after a met wait (then_call): each as the agent's own, its reply in last.then_result.
  local tc=state().then_calls
  if tc then
    state().then_calls=nil
    for _,c in ipairs(tc) do
      local okp,p=pcall(player,c.index)
      local ok,r=false,'no character'
      if okp and handlers[c.call.action] then ok,r=pcall(handlers[c.call.action],p,c.call.args) end
      local last=state().last and state().last[c.index]
      local now=state().active[c.index]
      local text=ok and (type(r)=='table' and (r.until_tick and string.format('%s started (until tick %d)',c.call.action,r.until_tick) or c.call.action..' ran') or tostring(r)) or (c.call.action..' refused: '..reason(r))
      if last then last.then_result=text end
      -- the action it started says so in its own last (finish)
      if ok and now and now.kind~='wait_until' then now.started_by=c.started_by or c.call.action..' run again after a wait (then_call)' end
    end
  end
  if event.tick%120==7 and state().belt_cuts then pcall(M.belt_cut_tell) end
  if event.tick%60==0 then feed_research_plans() end
  if event.tick%3600==0 then
    for _,connected in pairs(game.connected_players) do
      local ok,p=pcall(player,connected.index)
      if ok then pcall(survey.sample,p) end
    end
  end
  if event.tick%3600==0 then
    for _,b in ipairs(M.bots.list()) do
      local ok,p=pcall(player,b.index)
      -- A bot aboard a platform has no body to sample (live on sa, tick 72000).
      if ok and p.character then pcall(survey.sample,p) end
    end
  end
  scheduler.tick()
  -- (d18 batch38 A1) platform_schedule's second read of no_schedule or no_path, for direct calls
  local okrc,errrc=pcall(space.recheck_tick)
  if not okrc then local s=state(); s.recheck_error={tick=event.tick,error=tostring(errrc)} end
  if event.tick%15==0 then
    local okb,errb=pcall(M.beltgaps.tick,event.tick)
    if not okb then local s=state();s.belt_memory_error={tick=event.tick,error=tostring(errb)} end
  end
  M.orders.tick()
  local okr,errr=pcall(M.timed,'reminders.tick',M.reminders.tick)
  if not okr then local s=state(); s.reminder_error={tick=event.tick,error=tostring(errr)} end
  clock.tick()
  M.cameras.tick()
  -- Production credit (efficiency.lua): a block every other tick; like the camera drawing, its faults are counted.
  local oke,erre=pcall(M.efficiency.tick,event.tick)
  if not oke then local s=state(); s.efficiency_errors={count=((s.efficiency_errors or {}).count or 0)+1,last=tostring(erre),tick=game.tick} end
  -- Camera-only drawing must never quarantine the runtime: its faults are counted.
  local okv,errv=pcall(M.visuals.tick,event.tick)
  if not okv then local s=state(); s.visual_errors={count=((s.visual_errors or {}).count or 0)+1,last=tostring(errv),tick=game.tick} end
end
-- Operator-only remote functions (control.lua): never reachable through
-- dispatch, so agents cannot spawn bots or move cameras.
M.operator={
  bot_create=function(name) return {ok=true,tick=game.tick,bot=M.bots.create(name)} end,
  bot_remove=function(name) local out=M.bots.remove(name); return {ok=true,tick=game.tick,bot=out} end,
  bots=function() local out={}; for _,b in ipairs(M.bots.list()) do out[#out+1]={name=b.name,index=b.index,alive=M.bots.alive(b),position=b.position,dead_until_tick=b.dead_until_tick} end; return {ok=true,tick=game.tick,bots=out} end,
  camera=function(args) return M.cameras.set(args) end,
  -- A table ({seconds=N} or {stop=true}) runs the dispatch/event profiler (profile.lua).
  profile_ticks=function(n)
    if type(n)=='table' then return M.profile.start(n) end
    n=integer(n,600,1,36000,'ticks')
    local total=helpers.create_profiler(true)
    profiling={n=n,left=n,total=total}
    return {ok=true,tick=game.tick,until_tick=game.tick+n,note='the average lands in the server log (factorio-current.log)'}
  end,
  cameras=function() return M.cameras.list() end,
  -- A resumed world's later shift: its losses start fresh incidents.
  -- n: the shift's number in the world (tools/start-team.sh, from the resumed-from chain); progress: the last shifts'
  -- team numbers (tools/progress.py --shift-lines, joined by " ~ "), for each agent's shift retro.
  shift_start=function(n,progress)
    local closed=0
    for _,i in ipairs(state().losses or {}) do if not i.closed then i.closed='shift'; closed=closed+1 end end
    -- Each agent's first reply of the shift carries a shift block (research.lua).
    local shift=M.research.shift_start(n,progress)
    return {ok=true,tick=game.tick,incidents_closed=closed,shift=shift.number,progress_lines=shift.progress and #shift.progress or 0}
  end}
end do local MAX_ALERTS=64
function M.on_event(event)
  -- (d24 batch179 QV1) a cargo pod leaving, landing or delivering: the pod ledger (podlog.lua); faults are counted
  if M.podlog.EVENTS[event.name] then
    local ok,err=pcall(M.podlog.on_event,event)
    if not ok then local s=state(); s.podlog_errors={count=((s.podlog_errors or {}).count or 0)+1,last=tostring(err),tick=game.tick} end
    return
  end
  -- (d22 batch97 BG3) a chunk something was built in by hand, mined in or died in is marked for the chart (chart.lua)
  if M.chart and M.chart.events[event.name] then pcall(M.chart.mark,event) end
  -- (d23 batch123 CF2) a build, mine, death, ctrl-click or GUI change inside what a running watch measures (mixed.lua)
  if M.mixed and M.mixed.events[event.name] then pcall(M.timed,'mixed.event',M.mixed.on_event,event) end  -- (d25 batch200) its own part in profile_ticks: a split closes a watch here
  -- The player log must never quarantine the runtime: its faults are counted.
  if M.players.events[event.name] then
    local ok,err=pcall(M.players.on_event,event)
    if not ok then local s=state(); s.player_log_errors={count=((s.player_log_errors or {}).count or 0)+1,last=tostring(err),tick=game.tick} end
    -- a belt line blocked by what was built on its tile (linecut.lua; batch17 C1, Sonnet)
    if event.name==defines.events.on_built_entity and M.linecut then pcall(M.linecut.built,event) end
    -- mined or deconstructed by us: the fog memory forgets it (fogmem.lua)
    -- (d18 batch37 D3) a robot's mining: where its items go (deconwent.lua)
    if event.name==defines.events.on_robot_mined_entity and M.deconwent then
      local okd,errd=pcall(M.deconwent.on_mined,event)
      if not okd then local s=state(); s.decon_went_error={tick=game.tick,error=tostring(errd)} end
    end
    if (event.name==defines.events.on_player_mined_entity or event.name==defines.events.on_robot_mined_entity) and M.fogmem then
      pcall(M.fogmem.forget,event.entity)
    end
    -- removed or destroyed: its placement record goes (ghostlog.lua); a ghost the game puts there for a destroyed one is the game's
    if (event.name==defines.events.on_player_mined_entity or event.name==defines.events.on_robot_mined_entity or event.name==defines.events.on_entity_died)
      and M.ghostlog and event.entity and event.entity.valid and event.entity.force==game.forces.player then
      pcall(M.ghostlog.forget,event.entity)
    end
    if event.name~=defines.events.on_entity_died then return end
  end
  -- Research news (research.lua): like the player log, its faults are counted.
  if event.name==defines.events.on_research_finished or event.name==defines.events.on_research_queued then
    local ok,err=pcall(event.name==defines.events.on_research_finished and M.research.on_finished or M.research.on_queued,event)
    if not ok then local s=state(); s.research_errors={count=((s.research_errors or {}).count or 0)+1,last=tostring(err),tick=game.tick} end
    -- (d22 batch94 BD1) the reminders set on.research
    if event.name==defines.events.on_research_finished and M.reminders and event.research and event.research.valid and event.research.force==game.forces.player then
      pcall(M.reminders.trigger,'research',{name=event.research.name,gear=M.gapfacts.unlocks_gear(event.research)})
    end
    return
  end
  -- Rocket launches for the silo read (silo.lua): like research news, faults are counted.
  if event.name==defines.events.on_rocket_launch_ordered then
    -- the cargo ledger first (d18 batch36 D3): its launch id goes with freight's and silo's records of the same launch
    -- (d18 batch39 B1, Astra: silo and shipment read as disagreeing; both name it, with the launch tick)
    local okl,lid=pcall(M.ledger.on_launch,event)
    event.harness_up=okl and lid or nil
    pcall(M.podlog.on_launch,event)
    if M.freight then pcall(M.freight.on_launch,event) end
    local ok,err=pcall(M.silo.on_launch_ordered,event)
    if not ok then local s=state(); s.silo_errors={count=((s.silo_errors or {}).count or 0)+1,last=tostring(err),tick=game.tick} end
    return
  end
  if event.name==defines.events.on_script_path_request_finished then
    local paths=state().paths or {}
    local index=paths[event.id]; paths[event.id]=nil
    local action=index and state().active[index]
    local nav=action and (action.nav or action)
    if not nav then return end
    if M.margin_probe.on_path(nav,event) then return end
    -- A drive's path for the vehicle's box (vehicles.lua).
    if action.kind=='drive' then
      local ok,p=pcall(player,index,true)
      if ok then M.vehicles.on_path(p,action,event) elseif nav.path_id==event.id then nav.path_state='failed' end
      return
    end
    -- The walk's own request, its belt-free twin, or the probe after a give-up (pathing.lua).
    local ok,p=pcall(player,index)
    if ok and action.carried then
      -- Carried over a harness update: guarded as its tick is (carry.lua).
      local fine,err=pcall(M.pathing.on_finished,p,nav,event)
      if not fine then M.carry_failed(index,action,err) end
    elseif ok then M.pathing.on_finished(p,nav,event) elseif nav.path_id==event.id then nav.path_state='failed' end
  elseif event.name==defines.events.on_console_chat then
    if M.chat then M.chat.on_console_chat(event) end
  elseif event.name==defines.events.on_unit_group_finished_gathering then
    threat.on_group(event)
  elseif event.name==defines.events.on_entity_damaged then
    -- (AR1) an asteroid shot, or an asteroid's hit on us, on a platform an asteroid_watch watches (asteroidwatch.lua)
    if state().asteroid_watch then
      local oka,erra=pcall(M.asteroidwatch.on_damaged,event)
      if not oka then local s=state(); s.asteroid_watch_errors={count=((s.asteroid_watch_errors or {}).count or 0)+1,last=tostring(erra),tick=game.tick} end
    end
    -- (BH1) a railgun's hit on a platform a flight_watch watches (flightwatch.lua)
    if state().flightwatch then pcall(M.flightwatch.on_damaged,event) end
    -- A unit a driving bot's vehicle hits counts as rammed (vehicles.lua).
    local cause=event.cause
    if cause and cause.valid and cause.type=='car' then
      for _,action in pairs(state().active) do
        if action.kind=='drive' and action.vehicle==cause then M.vehicles.rammed(action,event.entity) end
      end
    end
    -- A platform's hits go to its alerts (platalerts.lua), counted on a fault.
    local ok,platform=pcall(M.platalerts.on_damaged,event)
    if not ok then local s=state(); s.platform_alert_errors={count=((s.platform_alert_errors or {}).count or 0)+1,last=tostring(platform),tick=game.tick} end
    if not (ok and platform) then threat.on_damaged(event) end
    -- What hit our entities where our force sees (damagelog.lua; Sol, board #695).
    local okd,errd=pcall(M.damagelog.on_damaged,event)
    if not okd then local s=state(); s.damage_log_errors={count=((s.damage_log_errors or {}).count or 0)+1,last=tostring(errd),tick=game.tick} end
    -- A hit on a character of ours or its vehicle (status hurt; combat.hurt).
    local okh,errh=pcall(M.note_hurt,event)
    if not okh then local s=state(); s.hurt_errors={count=((s.hurt_errors or {}).count or 0)+1,last=tostring(errh),tick=game.tick} end
  elseif event.name==defines.events.on_entity_died then
    local cause=event.cause
    -- (AR1) an asteroid destroyed on a platform an asteroid_watch watches (asteroidwatch.lua)
    if state().asteroid_watch then
      local oka,erra=pcall(M.asteroidwatch.on_died,event)
      if not oka then local s=state(); s.asteroid_watch_errors={count=((s.asteroid_watch_errors or {}).count or 0)+1,last=tostring(erra),tick=game.tick} end
    end
    if state().flightwatch then pcall(M.flightwatch.on_died,event) end
    -- An enemy a character or a vehicle of ours killed (status combat.kills_10s).
    if cause and cause.valid and event.entity and event.entity.valid and event.entity.force ~= cause.force then pcall(M.note_kill,cause,event.tick) end
    if cause and cause.valid and cause.type=='character' then
      for index,action in pairs(state().active) do
        local p=action.kind=='kite' and M.lookup(index)
        if p and p.character==cause then action.kills=action.kills+1 end
      end
    end
    -- A vehicle's guns (shoot seated, drive combat): a death caused by the vehicle or by its gunner counts.
    if cause and cause.valid then
      for index,combat in pairs(state().combat or {}) do
        local v=combat.vehicle_entity
        local mine=v and v.valid and (cause==v or (cause.type=='character' and pcall(function() return cause.vehicle==v end) and cause.vehicle==v))
        local died=event.entity
        if mine and died and died.valid and died.force and died.force.name~='neutral' and died.force~=v.force then
          combat.kills=(combat.kills or 0)+1
          combat.kills_by=combat.kills_by or {}
          combat.kills_by[died.name]=(combat.kills_by[died.name] or 0)+1
        end
      end
    end
    local e=event.entity
    local s=state()
    -- A character's death and what killed it (recover names it: d17 batch12 A4).
    if e and e.valid and e.type=='character' then pcall(M.note_char_death,event) end
    -- A demolisher's death: its territory, when, what killed it (demolishers.lua; d17 territory, Nick 17:08).
    if e and e.valid and e.type=='segmented-unit' then pcall(M.demolishers.died,event) end
    -- A belt of ours carrying items destroyed (d17 batch13 C1): its claim's owner is told (M.belt_cut_tell).
    if e and e.valid and (e.type=='transport-belt' or e.type=='underground-belt' or e.type=='splitter') and e.force and e.force.name~='enemy' and e.force.name~='neutral' then
      pcall(M.note_belt_cut,event)
    end
    -- a long belt or pipe line cut: a team alert (linecut.lua, d17 batch17 C1)
    if e and e.valid and (e.type=='transport-belt' or e.type=='underground-belt' or e.type=='splitter' or e.type=='pipe' or e.type=='pipe-to-ground')
      and e.force and e.force.name~='enemy' and e.force.name~='neutral' and M.linecut then
      pcall(M.linecut.note,event)
    end
    -- a robot of ours an enemy killed, with the job that sent it (robotloss.lua, d17 batch21 C2)
    if e and e.valid and (e.type=='construction-robot' or e.type=='logistic-robot') and M.robotloss then pcall(M.robotloss.note,event) end
    if e and e.valid and e.force and e.force.name=='enemy' and (e.type=='unit-spawner' or e.type=='turret') and event.force and event.force.name~='enemy' then
      s.kills=s.kills or {}
      table.insert(s.kills,{tick=event.tick,name=e.name,position=e.position})
      while #s.kills>MAX_ALERTS do table.remove(s.kills,1) end
      return
    end
    if not (e and e.valid and e.force and e.force.name~='enemy' and e.force.name~='neutral') then return end
    -- A platform's hub (the platform is lost: where it was, what killed it, its cargo) or an agent's character: the
    -- chronicle's events (chronicle.lua); a fault is counted.
    if e.type=='space-platform-hub' or e.type=='character' then
      local ok,err=pcall(M.chronicle.on_died,e,event)
      if not ok then s.chronicle_errors={count=((s.chronicle_errors or {}).count or 0)+1,last=tostring(err),tick=game.tick} end
    end
    if e.type=='agricultural-tower' then M.agriculture.died(e,event.cause and event.cause.valid and event.cause.name or nil) end
    -- a captive spawner of ours: its group names what takes its place (pushalerts.lua; d17 batch18 C6)
    if e.name=='captive-biter-spawner' then pcall(M.pushalerts.captive_died,e) end
    if LOSS.not_lost[e.type] then return end
    s.alerts=nil -- superseded by incidents
    -- A turret of ours that died: its ghost requests the ammo it held (turretammo.lua); a fault is counted.
    if e.type=='ammo-turret' or e.type=='artillery-turret' then
      local ok,err=pcall(M.turretammo.on_died,e)
      if ok then ok,err=pcall(M.pushalerts.turret_died,e) end  -- rebuilt, it is named if it stays empty (pushalerts.lua)
      if not ok then s.turret_ammo_errors={count=((s.turret_ammo_errors or {}).count or 0)+1,last=tostring(err),tick=game.tick} end
    end
    -- Friendly fire: a cause of the entity's own force, or, with the cause gone (a flame outliving its turret), the
    -- killing force (event.force) its own.
    local cause=event.cause and event.cause.valid and event.cause or nil
    local own=e.force.name
    local friendly=(cause and cause.force and cause.force.name==own) or (not cause and event.force and event.force.name==own) or false
    -- A strike (lightning.lua: no cause, the neutral force, electric damage on a lightning planet) is named lightning.
    local okt,struck=pcall(M.lightning.struck,event)
    struck=not cause and not friendly and okt and struck or nil
    if struck then pcall(M.lightning.lost,e) end
    -- A pole of ours: whether its loss split its network or left machines with no pole (powercut.lua); a fault is counted.
    if e.type=='electric-pole' then
      local ok,err=pcall(M.powercut.on_died,e,cause and cause.name or (friendly and 'friendly fire') or struck)
      if not ok then s.powercut_errors={count=((s.powercut_errors or {}).count or 0)+1,last=tostring(err),tick=game.tick} end
    end
    record_loss(event.tick,e,cause and cause.name or (friendly and 'unknown source') or struck,friendly,friendly and cause and cause.position or nil)
    -- One row a building (lostlog.lua); seen to die, the fog memory forgets it, else it stays remembered (fogmem.lua).
    local okl,errl=pcall(function()
      M.lostlog.died(e,cause and cause.name or (friendly and 'unknown source') or struck)
      if e.force.is_chunk_visible(e.surface,chunk_of(e.position)) then M.fogmem.forget(e) end
    end)
    if not okl then s.lostlog_errors={count=((s.lostlog_errors or {}).count or 0)+1,last=tostring(errl),tick=game.tick} end
  end
end
end -- A placement inside a demolisher territory says so (territory.lua; d17 batch14 B5, Sonnet): each building call's
-- reply, dry runs too, gets demolisher_territory when its box's chunks lie in one.
M.territory=require('territory'){state=function(surface,force,t) return M.demolishers.state(surface,force,t) end}
;(function()
  local function points(a,out)
    local q={}
    local b=type(out)=='table' and out.bounds
    if type(b)=='table' and b.left then q[1]={x=b.left,y=b.top}; q[2]={x=b.right,y=b.bottom}; return q end
    for _,k in ipairs({'position','from','to'}) do
      local v=a[k]
      if type(v)=='table' then q[#q+1]={x=v.x or v[1],y=v.y or v[2]} end
    end
    for i,e in ipairs(type(a.entities)=='table' and a.entities or {}) do
      if i>256 then break end
      local v=type(e)=='table' and e.position
      if type(v)=='table' then q[#q+1]={x=v.x or v[1],y=v.y or v[2]} end
    end
    return q
  end
  for _,name in ipairs({'build','place_ghosts','paste','blueprint_place','belt_route','rail_route','dry_run'}) do
    local h=handlers[name]
    if h then
      handlers[name]=function(p,a)
        local out=h(p,a)
        if type(out)=='table' and type(a)=='table' and out.demolisher_territory==nil then
          local inner=name=='dry_run' and type(a.args)=='table' and a.args or a
          if inner.platform==nil then
            local ok,line=pcall(function()
              local surface=type(inner.surface)=='string' and game.get_surface(inner.surface) or p.surface
              return M.territory.note(surface,p.force,M.territory.box(points(inner,out)))
            end)
            if ok and line then out.demolisher_territory=line end
          end
        end
        return out
      end
    end
  end
end)()
-- (d23 batch123 CF2, viewer Aurora 09:45) an edit inside what a running bounded watch measures splits its window there
-- (mixed.lua): the watch calls keep their arguments (a split starts the watch again with them) and their reads carry
-- the split; the edit calls (any agent's) are seen after they act, the builds and mines where they happen.
;(function()
  M.mixed=require('mixed'){state=state,player=function(index) return M.lookup(index) end,who=function(p) return M.board.who(p) end,
    who_index=function(index) local pl=M.lookup(index); return pl and pl.valid and M.board.who(pl) or nil end,
    call=function(p,action,args) return handlers[action](p,args) end,flight_rebase=function(w,tick) return M.flightwatch.rebase(w,tick) end,
    read={uptime=function(job) return M.uptime.result(job,false) end,turret_tally=function(job) return M.turrettally.result(job,false) end,
      belt_flow=function(job) return M.beltsample.finish(job) end,collector_tally=function(job) return M.collectreach.result(job,false) end,
      asteroid_watch=function(job) return M.asteroidwatch.result(job,false) end},
    close={asteroid_watch=function(job,new,tick,why) return M.asteroidwatch.close(job,new,tick,why) end}}
  local WATCH={uptime='uptime',turret_tally='turret_tally',belt_flow='belt_flow',
    platform_defense=function(a) return a.asteroids==true and 'asteroid_watch' or nil end,
    platform_supply=function(a) return a.collection==true and 'collector_tally' or nil end}
  for name,kind in pairs(WATCH) do
    local orig=handlers[name]
    handlers[name]=function(p,a)
      local out=orig(p,a)
      local k=type(kind)=='function' and kind(a or {}) or kind
      local job=k and p and p.valid and (state()[k] or {})[p.index]
      if type(job)=='table' then
        if job.start==game.tick and not job.result and not job.call then
          local args={}
          for key,v in pairs(a or {}) do args[key]=v end
          job.call={action=name,args=args}
        elseif job.mixed and type(out)=='table' then
          local into=k=='collector_tally' and type(out.tally)=='table' and out.tally or out
          into.mixed=M.mixed.view(job)
        end
      end
      return out
    end
  end
  local SKIP={position=true,positions=true,surface=true,platform=true,walk=true,walked=true,by=true,via=true,avoid_enemies=true,unsafe_goal=true}
  local function surface_of(p,a)
    if a.platform~=nil then local pl=space.platform(p,a.platform); return pl and pl.surface end
    if type(a.surface)=='string' then return game.get_surface(a.surface) end
    local b=body(p); return b and b.valid and b.surface or nil
  end
  for _,name in ipairs{'configure','rotate','transfer','feed','refuel','rearm','wire'} do
    local orig=handlers[name]
    handlers[name]=function(p,a)
      local out=orig(p,a)
      if type(out)=='table' and not out.walking and p and p.valid and M.mixed.watches() then
        pcall(function()
          local keys={}
          for key in pairs(a or {}) do if not SKIP[key] then keys[#keys+1]=key end end
          table.sort(keys)
          local list={}
          if type(a.positions)=='table' then for _,q in ipairs(a.positions) do list[#list+1]=type(q)=='table' and (q.position or q) or q end end
          if type(a.position)=='table' then list[#list+1]=a.position end
          if type(out.position)=='table' then list[#list+1]=out.position end
          M.mixed.at(surface_of(p,a),list,name..(#keys>0 and ' '..table.concat(keys,', ') or '')..' by '..M.board.who(p))
        end)
      end
      return out
    end
  end
end)()
-- (d23 batch123 CF3, viewer Aurora 09:47) a hub or landing pad request changed, a schedule changed or a platform
-- deleted: the supply left without an active delivery path, in the call's reply and once to the link's last editor
-- (freightpath.lua).
;(function()
  M.freightpath=require('freightpath'){pads=function(planet,force) return M.freight.pads(planet,force) end,
    census_typed=function(f,sf,t) return M.census and M.census.typed(f,sf,t) end,owner=function(scope,key,tick) return M.editlog.owner(scope,key,tick) end,
    who=function(p) return M.board.who(p) end,deliver=function(index,t) return M.board.deliver(index,t) end,
    surface=function(p) local b=body(p); return b and b.valid and b.surface or nil end,
    index_of=function(name) local ok,i=pcall(M.bots.index_of,name); if ok and i then return i end; local pl=game.get_player(name); return pl and pl.index or nil end}
  for _,name in ipairs{'requests','platform_schedule','platform_delete'} do
    local orig=handlers[name]
    handlers[name]=function(p,a)
      local okb,before=pcall(M.freightpath.before,p,name,a or {})
      local out=orig(p,a)
      if okb and before then
        local ok,err=pcall(M.freightpath.after,p,name,a or {},out,before)
        if not ok and type(out)=='table' then out.supply_left_error=tostring(err) end
      end
      return out
    end
  end
end)()
